-- private._invoice_document_operation_ensure_batch(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_document_operation_ensure_batch(p_requests jsonb, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_requests jsonb := coalesce(p_requests,'[]'::jsonb);
  v_now timestamptz := coalesce(p_now_utc, now());
  v_processor_policy jsonb;
  v_result jsonb;
begin
  if jsonb_typeof(v_requests) is distinct from 'array' then
    raise exception using errcode='22023', message='INVOICE_DOCUMENT_ENSURE_REQUESTS_INVALID';
  end if;

  if jsonb_array_length(v_requests) < 1 or jsonb_array_length(v_requests) > 250 then
    raise exception using errcode='22023', message='INVOICE_DOCUMENT_ENSURE_REQUEST_COUNT_INVALID';
  end if;

  select private._invoice_processor_limits() into v_processor_policy;

  with
  raw_requests as materialized (
    select value request_json, ordinality::integer request_no
    from jsonb_array_elements(v_requests) with ordinality request_row(value, ordinality)
  ),
  requests as materialized (
    select
      request_no,
      nullif(btrim(coalesce(request_json->>'request_key','')),'') request_key,
      case when pg_input_is_valid(coalesce(request_json->>'invoice_id',''),'uuid')
        then (request_json->>'invoice_id')::uuid end invoice_id,
      case when coalesce(request_json->>'document_revision','') ~ '^[1-9][0-9]{0,8}$'
        then (request_json->>'document_revision')::integer end document_revision,
      upper(coalesce(nullif(request_json->>'purpose',''),'DRAFT_PREVIEW')) purpose,
      case when coalesce(request_json->>'priority','') ~ '^[0-9]{1,8}$'
        then greatest(0,least((request_json->>'priority')::integer,2000))
        else 450 end priority,
      case when pg_input_is_valid(coalesce(request_json->>'parent_operation_id',''),'uuid')
        then (request_json->>'parent_operation_id')::uuid end parent_operation_id,
      case when pg_input_is_valid(coalesce(request_json->>'actor_user_id',''),'uuid')
        then (request_json->>'actor_user_id')::uuid end actor_user_id,
      coalesce(nullif(request_json->>'template_version',''),'invoice-professional-v2') template_version,
      request_json
    from raw_requests
  ),
  invalid_requests as materialized (
    select request_no, coalesce(request_key,'request:'||request_no::text) request_key,
      case
        when request_key is null then 'REQUEST_KEY_REQUIRED'
        when invoice_id is null then 'INVOICE_ID_INVALID'
        when document_revision is null then 'DOCUMENT_REVISION_INVALID'
        when purpose <> 'DRAFT_PREVIEW' then 'DOCUMENT_PURPOSE_INVALID'
        when template_version <> 'invoice-professional-v2' then 'DOCUMENT_TEMPLATE_VERSION_INVALID'
        when parent_operation_id is null then 'PARENT_OPERATION_ID_REQUIRED'
        when actor_user_id is null then 'ACTOR_USER_ID_REQUIRED'
        else null end code
    from requests
    where request_key is null
       or invoice_id is null
       or document_revision is null
       or purpose <> 'DRAFT_PREVIEW'
       or template_version <> 'invoice-professional-v2'
       or parent_operation_id is null
       or actor_user_id is null
  ),
  duplicate_requests as materialized (
    select request_key, count(*) count_rows
    from requests
    where request_key is not null
    group by request_key
    having count(*) > 1
  ),
  valid_requests as materialized (
    select r.*
    from requests r
    where not exists (select 1 from invalid_requests i where i.request_no=r.request_no)
      and not exists (select 1 from duplicate_requests d where d.request_key=r.request_key)
  ),
  locked_invoices as materialized (
    select r.*,i.id locked_invoice_id,i.status invoice_status,i.document_revision current_document_revision,
      i.preview_document_version_id,i.issued_document_version_id,
      i.client_id
    from valid_requests r
    join public.invoices i on i.id=r.invoice_id
    order by i.id
    for update of i
  ),
  invoice_not_found as materialized (
    select r.request_no,r.request_key,'INVOICE_NOT_FOUND' code
    from valid_requests r
    where not exists (select 1 from locked_invoices l where l.request_no=r.request_no)
  ),
  source_changed as materialized (
    select request_no,request_key,'SOURCE_CHANGED' code
    from locked_invoices
    where coalesce(current_document_revision,0) <> document_revision
  ),
  invoice_blocked as materialized (
    select request_no,request_key,
      case
        when invoice_status::text in ('ISSUED','PAID') and purpose='DRAFT_PREVIEW' then 'INVOICE_ALREADY_ISSUED'
        when invoice_status::text not in ('DRAFT','ON_HOLD','ISSUED','PAID') then 'INVOICE_STATUS_UNSUPPORTED'
      end code
    from locked_invoices
    where (invoice_status::text in ('ISSUED','PAID') and purpose='DRAFT_PREVIEW')
       or invoice_status::text not in ('DRAFT','ON_HOLD','ISSUED','PAID')
  ),
  actionable as materialized (
    select l.*
    from locked_invoices l
    where not exists (select 1 from source_changed s where s.request_no=l.request_no)
      and not exists (select 1 from invoice_blocked b where b.request_no=l.request_no)
  ),
  ready_versions as materialized (
    select distinct on(a.request_no)
      a.request_no,a.request_key,v.id document_version_id,v.r2_key,v.sha256,v.size_bytes,v.page_count
    from actionable a
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=a.invoice_id
     and v.purpose=a.purpose
     and v.source_revision=a.document_revision::text
     and v.template_version=a.template_version
     and v.status='READY'
     and v.r2_key is not null
     and v.sha256 ~ '^[0-9a-f]{64}$'
     and coalesce(v.size_bytes,0)>0
     and coalesce(v.page_count,0)>0
    order by a.request_no,v.ready_at_utc desc nulls last,v.created_at_utc desc,v.id desc
  ),
  active_operations as materialized (
    select distinct on(a.request_no)
      a.request_no,a.request_key,o.id operation_id,o.status,o.phase,o.change_seq
    from actionable a
    join public.invoice_operations o
      on o.operation_type='BUILD_DOCUMENT'
     and o.entity_type='INVOICE'
     and o.entity_id=a.invoice_id
     and o.source_revision=a.document_revision::text
     and coalesce(o.input_json->>'purpose','DRAFT_PREVIEW')=a.purpose
     and coalesce(o.template_version,'')=a.template_version
     and o.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    where not exists (select 1 from ready_versions rv where rv.request_no=a.request_no)
    order by a.request_no,o.priority desc,o.created_at_utc desc,o.id desc
  ),
  to_create as materialized (
    select a.*,
      encode(digest(concat_ws('|','BUILD_DOCUMENT',a.purpose,a.invoice_id::text,a.document_revision::text,a.template_version,a.request_key),'sha256'),'hex') idempotency_key
    from actionable a
    where not exists (select 1 from ready_versions rv where rv.request_no=a.request_no)
      and not exists (select 1 from active_operations ao where ao.request_no=a.request_no)
  ),
  inserted_operations as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,completed_units,failed_units,chunk_count,
      created_at_utc,updated_at_utc
    )
    select
      parent_operation_id,'BUILD_DOCUMENT','INVOICE',invoice_id,actor_user_id,
      idempotency_key,'QUEUED','BUILD_MANIFEST',priority,document_revision::text,template_version,
      jsonb_build_object(
        'invoice_id',invoice_id,
        'purpose',purpose,
        'expected_revision',document_revision,
        'source_revision',document_revision::text,
        'request_key',request_key,
        'created_by','private._invoice_document_operation_ensure_batch'
      ),
      jsonb_build_object('processor_policy',v_processor_policy),
      jsonb_build_object('status_message','Queued document preparation'),
      1,0,0,1,
      v_now,v_now
    from to_create
    on conflict (idempotency_key)
    where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set
      priority=greatest(public.invoice_operations.priority, excluded.priority),
      updated_at_utc=excluded.updated_at_utc
    returning id operation_id,entity_id invoice_id,source_revision,control_version,status,phase,change_seq,idempotency_key
  ),
  inserted_operation_requests as materialized (
    select c.request_no,c.request_key,c.invoice_id,c.document_revision,c.purpose,c.priority,c.template_version,
      o.operation_id,o.control_version,o.status,o.phase,o.change_seq
    from to_create c
    join inserted_operations o
      on o.invoice_id=c.invoice_id and o.source_revision=c.document_revision::text
     and o.idempotency_key=c.idempotency_key
  ),
  inserted_versions as materialized (
    insert into public.invoice_document_versions(
      entity_type,entity_id,purpose,operation_id,source_revision,template_version,
      status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',invoice_id,purpose,operation_id,document_revision::text,
      template_version,'PLANNING','{}'::jsonb,encode(digest('{}','sha256'),'hex'),
      '[]'::jsonb,encode(digest('[]','sha256'),'hex'),v_now
    from inserted_operation_requests
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET')
        and status in('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id document_version_id,entity_id invoice_id,operation_id,source_revision,template_version,purpose,status
  ),
  ensured_inserted_versions as materialized (
    select ir.*,v.document_version_id,v.status document_status
    from inserted_operation_requests ir
    join inserted_versions v
      on v.operation_id=ir.operation_id
     and v.invoice_id=ir.invoice_id
     and v.source_revision=ir.document_revision::text
     and v.template_version=ir.template_version
     and v.purpose=ir.purpose
    union all
    select ir.*,v.id document_version_id,v.status document_status
    from inserted_operation_requests ir
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=ir.invoice_id
     and v.purpose=ir.purpose
     and v.source_revision=ir.document_revision::text
     and v.template_version=ir.template_version
     and v.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    where not exists (
      select 1
      from inserted_versions inserted
      where inserted.operation_id=ir.operation_id
        and inserted.invoice_id=ir.invoice_id
        and inserted.source_revision=ir.document_revision::text
        and inserted.template_version=ir.template_version
        and inserted.purpose=ir.purpose
    )
  ),
  inserted_chunks as materialized (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,plan_generation,sequence_no,level_no,
      entity_type,entity_id,document_version_id,status,priority,run_after_utc,payload_json,
      operation_control_version,created_at_utc,updated_at_utc
    )
    select
      operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',document_version_id::text,document_revision::text,purpose,template_version,'1'),'sha256'),'hex'),
      1,0,0,
      'INVOICE',invoice_id,document_version_id,'QUEUED',priority,v_now,
      jsonb_build_object(
        'invoice_id',invoice_id,
        'purpose',purpose,
        'expected_revision',document_revision,
        'source_revision',document_revision::text,
        'template_version',template_version,
        'request_key',request_key
      ),
      control_version,v_now,v_now
    from ensured_inserted_versions
    where document_status <> 'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do update set
      priority=greatest(public.invoice_operation_chunks.priority, excluded.priority),
      updated_at_utc=excluded.updated_at_utc
    returning id chunk_id,operation_id,document_version_id
  ),
  outcomes as materialized (
    select request_no,request_key,false ok,'INVALID' status,code,null::uuid operation_id,null::uuid document_version_id,null::uuid chunk_id
    from invalid_requests
    union all
    select r.request_no,r.request_key,false,'INVALID','REQUEST_KEY_DUPLICATE',null::uuid,null::uuid,null::uuid
    from requests r join duplicate_requests d on d.request_key=r.request_key
    union all
    select request_no,request_key,false,'BLOCKED',code,null::uuid,null::uuid,null::uuid
    from invoice_not_found
    union all
    select request_no,request_key,false,'BLOCKED',code,null::uuid,null::uuid,null::uuid
    from source_changed
    union all
    select request_no,request_key,false,'BLOCKED',code,null::uuid,null::uuid,null::uuid
    from invoice_blocked
    union all
    select request_no,request_key,true,'READY',null,null::uuid,document_version_id,null::uuid
    from ready_versions
    union all
    select request_no,request_key,true,status,null,operation_id,null::uuid,null::uuid
    from active_operations
    union all
    select ev.request_no,ev.request_key,true,ev.status,null,ev.operation_id,ev.document_version_id,ic.chunk_id
    from ensured_inserted_versions ev
    left join inserted_chunks ic on ic.operation_id=ev.operation_id and ic.document_version_id=ev.document_version_id
  )
  select jsonb_build_object(
    'contract_version','INVOICE_DOCUMENT_OPERATION_ENSURE_V1',
    'ok',not exists(select 1 from outcomes where ok is false),
    'results',coalesce(jsonb_agg(jsonb_build_object(
      'request_no',request_no,
      'request_key',request_key,
      'ok',ok,
      'status',status,
      'code',code,
      'operation_id',operation_id,
      'document_version_id',document_version_id,
      'chunk_id',chunk_id
    ) order by request_no),'[]'::jsonb),
    'created_count',(select count(*) from inserted_operation_requests),
    'ready_count',(select count(*) from ready_versions),
    'active_count',(select count(*) from active_operations),
    'blocked_count',(select count(*) from outcomes where ok is false),
    'checked_at_utc',v_now
  )
  into v_result
  from outcomes;

  return coalesce(v_result,jsonb_build_object(
    'contract_version','INVOICE_DOCUMENT_OPERATION_ENSURE_V1',
    'ok',false,
    'results','[]'::jsonb,
    'code','NO_OUTCOMES'
  ));
end;
$function$;

-- private._invoice_generation_advance_batch_legacy_20260726(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_generation_advance_batch_legacy_20260726(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_result jsonb := '[]'::jsonb;
  v_part jsonb;
begin
  -- VALIDATE_SOURCES: no invoice/header/line writes are permitted in this block.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  member_values as materialized (
    select c.id chunk_id,c.operation_id,c.payload_json,
      m.value member,m.ordinality
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
          and jsonb_array_length(c.payload_json->'canonical_source_members')>0
        then c.payload_json->'canonical_source_members'
        else coalesce((
          select jsonb_agg(jsonb_build_object(
            'source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality)
          from jsonb_array_elements_text(coalesce(
            c.payload_json->'canonical_source_ids',
            c.payload_json->'source_ids','[]'::jsonb))
            with ordinality s(value,ordinality)
        ),'[]'::jsonb) end) with ordinality m(value,ordinality)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select m.chunk_id,m.operation_id,m.payload_json,m.member,
      upper(coalesce(m.member->>'source_type','TIMESHEET')) source_type,
      case when coalesce(m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(m.member->>'source_id')::uuid end source_id,
      case when coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id')::uuid end timesheet_id,
      nullif(btrim(m.member->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(m.member->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(m.member->>'source_type','TIMESHEET')),
          coalesce(m.member->>'source_id',''),
          coalesce(m.member->>'related_timesheet_id',''),
          coalesce(m.member->>'segment_id','WHOLE'),
          coalesce(m.member->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key,
      nullif(btrim(coalesce(m.member->>'row_revision',
        m.member->>'source_revision','')),'') expected_revision,
      m.ordinality
    from member_values m
  ),
  reference_eval as materialized (
    select distinct on (r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.member->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode',
        'source_revision',m.expected_revision)
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  vat_eval as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,'segment_id',m.segment_id,
        'effective_date',m.payload_json->>'effective_settings_date')
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-validate:'||scope.chunk_id::text,
      'scope_key',scope.chunk_id::text,
      'validation_purpose','GENERATION_VALIDATE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.chunk_id),'[]'::jsonb) scopes
    from(
      select m.chunk_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.ordinality) planned_members
      from members m
      left join vat_eval v on v.source_member_key=m.source_member_key
      group by m.chunk_id
    ) scope
  ),
  correction_eval as materialized (
    select r.*
    from correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_eval as materialized (
    select m.chunk_id,m.operation_id,m.timesheet_id,m.segment_id,
      m.source_member_key,m.ordinality,
      tf.id tsfin_id,
      encode(digest(concat_ws('|',tf.id::text,tf.timesheet_version::text,
        tf.updated_at::text,ts.version::text,ts.updated_at::text,
        coalesce(tf.invoice_breakdown_json::text,'')),'sha256'),'hex') row_revision,
      array_remove(array[
        case when ts.timesheet_id is null then 'TIMESHEET_NOT_FOUND' end,
        case when ts.timesheet_id is not null and (not ts.is_current or ts.revoked_at is not null) then 'TIMESHEET_NOT_CURRENT' end,
        case when tf.id is null then 'CURRENT_FINANCIALS_MISSING' end,
        case when tf.id is not null and tf.is_stale then 'FINANCIALS_STALE' end,
        case when tf.id is not null and tf.processing_status::text<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE' end,
        case when tf.id is not null and tf.has_rate_issue then 'RATE_MISSING' end,
        case when tf.id is not null and tf.has_pay_channel_issue then 'PAY_CHANNEL_MISSING' end,
        case when tf.id is not null and tf.client_id is null then 'CLIENT_UNRESOLVED' end,
        case when tf.id is not null and tf.locked_by_invoice_id is not null then 'SOURCE_ALREADY_LOCKED' end,
        case when ts.authorised_at_server is null
          then 'TIMESHEET_NOT_AUTHORISED' end,
        case when upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null)
          then 'QR_TIMESHEET_UNSIGNED' end,
        case when pc.require_reference_to_invoice
          and coalesce(ref.reference_ready,false) is not true
          then coalesce(ref.blocker_code,'MISSING_REFERENCE') end,
        case when coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_MILEAGE_EVIDENCE' end end,
        case when(coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'MILEAGE_ASSET_NOT_REGISTERED' end,
        case when coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_EXPENSE_EVIDENCE' end end,
        case when(
            coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'EXPENSE_ASSET_NOT_REGISTERED' end,
        case when(coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_TRAVEL_EVIDENCE' end,
        case when(coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_ACCOMMODATION_EVIDENCE' end,
        case when(coalesce(tf.other_pay_ex_vat,0)<>0
            or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_OTHER_EXPENSE_EVIDENCE' end,
        case when exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
            where e.timesheet_id=m.timesheet_id
              and a.status in(
                'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'))
          then 'REQUIRED_ASSET_PERMANENT_FAILURE' end,
        case when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED') end,
        case when corr.valid is false
          then coalesce(corr.blocker_code,'CORRECTION_VALIDATION_FAILED') end,
        case when coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED')
          then 'HEALTHROSTER_VALIDATION_REQUIRED' end,
        case when coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and coalesce(vs.nhsp_shift_included_count,0)=0
          then 'NHSP_SOURCE_NOT_READY' end,
        case when exists(select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
                         where l.timesheet_id=m.timesheet_id and i.status in ('DRAFT','ISSUED','ON_HOLD'))
             and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS' then 'SOURCE_ALREADY_INVOICED' end
      ],null)::text[] blockers
    from members m
    left join public.timesheets ts on ts.timesheet_id=m.timesheet_id
    left join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join reference_eval ref on ref.source_member_key=m.source_member_key
    left join vat_eval vat on vat.source_member_key=m.source_member_key
    left join correction_eval corr
      on corr.scope_key=m.chunk_id::text
  ),
  resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  canonical_now as materialized (
    select ri.chunk_id,r.group_key,r.source_revision_hash,
      r.blocker_code,r.blocker_detail
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from resolver_inputs ri),null,v_now) r
    join resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=ri.payload_json->>'group_key'
  ),
  per_chunk as materialized (
    select c.id chunk_id,
      n.source_revision_hash current_revision,
      coalesce(jsonb_agg(jsonb_build_object('source_id',se.timesheet_id,
        'segment_id',se.segment_id,
        'codes',to_jsonb(se.blockers)) order by se.ordinality)
        filter(where cardinality(se.blockers)>0),'[]'::jsonb)
        ||case when n.blocker_code is null then '[]'::jsonb
          else jsonb_build_array(coalesce(n.blocker_detail,
            jsonb_build_object('code',n.blocker_code))) end blockers,
      count(se.timesheet_id)::integer source_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join source_eval se on se.chunk_id=c.id
    left join canonical_now n on n.chunk_id=c.id
    group by c.id,n.source_revision_hash,n.blocker_code,n.blocker_detail
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case
          when p.source_count=0 then 'BLOCKED'
          when jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'PLAN' end,
        status=case
          when p.source_count=0 or jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'QUEUED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',p.current_revision,'source_count',p.source_count),
        progress_json=jsonb_build_object('status_message',
          case when p.source_count=0 then 'No sources resolved'
               when jsonb_array_length(p.blockers)>0 then 'Source validation blocked'
               when nullif(c.payload_json->>'source_revision','') is not null
                and c.payload_json->>'source_revision'<>p.current_revision then 'Source changed'
               else 'Sources validated' end,'source_count',p.source_count),
        error_json=case
          when p.source_count=0 then jsonb_build_object('code','NO_SOURCES','sources','[]'::jsonb)
          when jsonb_array_length(p.blockers)>0 then jsonb_build_object('code','SOURCE_VALIDATION_BLOCKED','sources',p.blockers)
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then jsonb_build_object('code','SOURCE_CHANGED')
          else null end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from per_chunk p where c.id=p.chunk_id
    returning c.id,c.operation_id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note validation is deliberately separate from normal timesheet sources.
  with claim_ids as (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  credit_eval as (
    select c.id chunk_id,i.id invoice_id,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),'sha256'),'hex') revision,
      case when i.id is null then 'INVOICE_NOT_FOUND'
           when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
           when i.status::text not in ('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
           when exists(select 1 from public.invoices cn where cn.original_invoice_id=i.id and cn.type='CREDIT_NOTE'
                       and cn.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
           else null end blocker
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case when e.blocker is null then 'PLAN' else 'BLOCKED' end,
        status=case when e.blocker is null then 'QUEUED' else 'BLOCKED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',e.revision,'source_invoice_id',e.invoice_id),
        progress_json=jsonb_build_object('status_message',case when e.blocker is null then 'Credit source validated' else 'Credit source blocked' end),
        error_json=case when e.blocker is null then null else jsonb_build_object('code',e.blocker,'invoice_id',c.entity_id) end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from credit_eval e where c.id=e.chunk_id
    returning c.id,c.status,c.phase,c.error_json
  )
  select v_result||coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_result from updated;

  -- PLAN: compact financial/settings summary only; no complete line arrays.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='PLAN'
  ),
  members as materialized (
    select c.id chunk_id,c.payload_json,
      case when pg_input_is_valid(s.value,'uuid')
        then s.value::uuid end timesheet_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements_text(coalesce(
      c.payload_json->'canonical_source_ids',c.payload_json->'source_ids','[]'::jsonb)) s(value)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
      and pg_input_is_valid(s.value,'uuid')
  ),
  values_by_chunk as materialized (
    select m.chunk_id,count(*)::integer source_count,
      round(sum(coalesce(tf.total_pay_ex_vat,0)),2) expected_pay_ex_vat,
      round(sum(coalesce(tf.total_charge_ex_vat,0)),2) expected_charge_ex_vat,
      (array_agg(tf.client_id order by tf.client_id))[1] client_id,
      jsonb_build_object(
        'client_id',(array_agg(tf.client_id order by tf.client_id))[1],'consolidation_mode',max(c.payload_json->>'consolidation_mode'),
        'stream',max(c.payload_json->>'invoice_stream'),
        'invoice_week_start',max(c.payload_json->>'target_invoice_week'),
        'client',jsonb_build_object('name',max(cl.name),'vat_chargeable',bool_and(cl.vat_chargeable),
          'payment_terms_days',max(cl.payment_terms_days),'primary_invoice_email',max(cl.primary_invoice_email)),
        'attach_policy',jsonb_build_object(
          'hr_attach_to_invoice',coalesce(bool_or(cs.hr_attach_to_invoice),bool_or(sd.hr_attach_to_invoice),true),
          'ts_attach_to_invoice',coalesce(bool_or(cs.ts_attach_to_invoice),bool_or(sd.ts_attach_to_invoice),true),
          'requires_hr',coalesce(bool_or(cs.requires_hr),false))
      ) settings_snapshot
    from members m join public.invoice_operation_chunks c on c.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.clients cl on cl.id=tf.client_id
    left join lateral (
      select s.* from public.client_settings s where s.client_id=tf.client_id
       and (s.effective_from is null or s.effective_from<=coalesce(
      case when c.payload_json->>'effective_settings_date' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(c.payload_json->>'effective_settings_date','date')
           then (c.payload_json->>'effective_settings_date')::date end,
         (v_now at time zone 'Europe/London')::date))
      order by s.effective_from desc nulls last,s.updated_at desc nulls last,
        s.created_at desc nulls last,s.id desc
      limit 1
    ) cs on true
    cross join public.settings_defaults sd
    where sd.id=1
    group by m.chunk_id
  ),
  plans as materialized (
    select c.id chunk_id,coalesce(
      case when pg_input_is_valid(
        nullif(c.payload_json->>'planned_invoice_id',''),'uuid')
        then(c.payload_json->>'planned_invoice_id')::uuid end,
      case when c.payload_json->>'consolidation_mode' in ('BY_WEEK','ANY_WEEK') then (
        select i.id from public.invoices i
        where i.client_id=v.client_id and i.status='DRAFT' and i.type='INVOICE'
          and coalesce(i.header_snapshot_json#>>'{meta,consolidation_mode}','NONE')=c.payload_json->>'consolidation_mode'
          and coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false')=
              case when c.payload_json->>'invoice_stream'='SELF_BILL' then 'true' else 'false' end
          and (c.payload_json->>'consolidation_mode'='ANY_WEEK'
               or i.header_snapshot_json#>>'{meta,invoice_week_start}'=c.payload_json->>'target_invoice_week')
        order by i.created_at desc limit 1
      ) end,gen_random_uuid()) planned_invoice_id,
      v.source_count,v.expected_charge_ex_vat,v.expected_pay_ex_vat,v.client_id,
      v.settings_snapshot,encode(digest(v.settings_snapshot::text,'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join values_by_chunk v on v.chunk_id=c.id
  ),
  credit_plans as materialized (
    select c.id chunk_id,gen_random_uuid() planned_invoice_id,1 source_count,
      -i.subtotal_ex_vat expected_charge_ex_vat,-coalesce(sum(l.total_pay_ex_vat),0) expected_pay_ex_vat,
      i.client_id,jsonb_build_object('source_invoice_id',i.id,'source_invoice_no',i.invoice_no,
        'client_id',i.client_id,'credit_note',true) settings_snapshot,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text),'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    left join public.invoice_lines l on l.invoice_id=i.id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
    group by c.id,i.id
  ),
  all_plans as materialized (select * from plans union all select * from credit_plans),
  updated as (
    update public.invoice_operation_chunks c
    set phase='COMMIT',status='QUEUED',
      payload_json=c.payload_json||jsonb_build_object('plan',jsonb_build_object(
        'planned_invoice_id',p.planned_invoice_id,'intended_invoice_count',1,
        'source_count',p.source_count,'expected_pay_ex_vat',p.expected_pay_ex_vat,
        'expected_charge_ex_vat',p.expected_charge_ex_vat,'settings_snapshot',p.settings_snapshot,
        'settings_hash',p.settings_hash,'source_revision',c.payload_json->>'source_revision')),
      progress_json=jsonb_build_object('status_message','Generation plan ready','source_count',p.source_count),
      error_json=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=v_now
    from all_plans p where c.id=p.chunk_id
    returning c.id,c.status,c.phase,c.payload_json->'plan' plan
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'plan',plan)),'[]'::jsonb)
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- COMMIT: revalidate immediately, then headers, lines, locks, documents and audit set-wise.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='COMMIT'
  ),
  normal_chunks as materialized (
    select c.*,case when pg_input_is_valid(
        c.payload_json#>>'{plan,planned_invoice_id}','uuid')
      then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end planned_invoice_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select c.id chunk_id,c.operation_id,c.planned_invoice_id,c.payload_json,
      upper(coalesce(s.value->>'source_type','TIMESHEET')) source_type,
      case when pg_input_is_valid(s.value->>'source_id','uuid')
        then(s.value->>'source_id')::uuid end source_id,
      case when pg_input_is_valid(coalesce(
          s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
        then coalesce(s.value->>'related_timesheet_id',
          s.value->>'source_id')::uuid end timesheet_id,
      nullif(btrim(s.value->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(s.value->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(s.value->>'source_type','TIMESHEET')),
          coalesce(s.value->>'source_id',''),
          coalesce(s.value->>'related_timesheet_id',''),
          coalesce(s.value->>'segment_id','WHOLE'),
          coalesce(s.value->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key
    from normal_chunks c
    cross join lateral jsonb_array_elements(case
      when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        and jsonb_array_length(c.payload_json->'canonical_source_members')>0
      then c.payload_json->'canonical_source_members'
      else coalesce((
        select jsonb_agg(jsonb_build_object(
          'source_type','TIMESHEET','source_id',ids.value,
          'related_timesheet_id',ids.value) order by ids.ordinality)
        from jsonb_array_elements_text(coalesce(
          c.payload_json->'canonical_source_ids',
          c.payload_json->'source_ids','[]'::jsonb))
          with ordinality ids(value,ordinality)
      ),'[]'::jsonb) end) s(value)
    where pg_input_is_valid(coalesce(
      s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
  ),
  selected_segments as materialized (
    select c.id chunk_id,
      (m.value->>'source_id')::uuid timesheet_id,
      array_agg(distinct m.value->>'segment_id'
        order by m.value->>'segment_id')
        filter(where nullif(m.value->>'segment_id','') is not null) segment_ids
    from normal_chunks c
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        then c.payload_json->'canonical_source_members' else '[]'::jsonb end)
      m(value)
    where coalesce(m.value->>'source_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    group by c.id,(m.value->>'source_id')::uuid
  ),
  commit_reference_eval as materialized (
    select distinct on(r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.payload_json->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode')
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  commit_vat_eval as materialized (
    select distinct on(v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'effective_date',m.payload_json->>'effective_settings_date')
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  commit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-commit:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_COMMIT',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select m.planned_invoice_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.source_member_key) planned_members
      from members m
      left join commit_vat_eval v
        on v.source_member_key=m.source_member_key
      group by m.planned_invoice_id
    ) scope
  ),
  commit_correction_eval as materialized (
    select r.*
    from commit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_still_valid as materialized (
    select m.chunk_id,
      bool_and(tf.processing_status='READY_FOR_INVOICE' and not tf.is_stale
        and (tf.locked_by_invoice_id is null
          or coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS')
        and ts.authorised_at_server is not null
        and not(upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null))
        and(not coalesce(pc.require_reference_to_invoice,false)
          or coalesce(ref.reference_ready,false))
        and coalesce(vat.valid,false)
        and coalesce(corr.valid,true)
        and not(coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED'))
        and not(coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and coalesce(vs.nhsp_shift_included_count,0)=0)
        and not((coalesce(tf.mileage_pay_ex_vat,0)<>0
              or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.travel_pay_ex_vat,0)<>0
              or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.accommodation_pay_ex_vat,0)<>0
              or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.expenses_pay_ex_vat,0)<>0
              or coalesce(tf.expenses_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.other_pay_ex_vat,0)<>0
              or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null))
        and not exists(
          select 1
          from public.timesheet_evidence e
          left join public.invoice_document_assets a
            on a.id=e.document_asset_id
          where e.timesheet_id=m.timesheet_id
            and(
              (upper(coalesce(e.kind,''))='MILEAGE'
                and(coalesce(tf.mileage_pay_ex_vat,0)<>0
                  or coalesce(tf.mileage_charge_ex_vat,0)<>0))
              or(upper(coalesce(e.kind,'')) in(
                  'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
                and(coalesce(tf.expenses_pay_ex_vat,0)<>0
                  or coalesce(tf.expenses_charge_ex_vat,0)<>0
                  or coalesce(tf.travel_pay_ex_vat,0)<>0
                  or coalesce(tf.travel_charge_ex_vat,0)<>0
                  or coalesce(tf.accommodation_pay_ex_vat,0)<>0
                  or coalesce(tf.accommodation_charge_ex_vat,0)<>0)))
            and(e.document_asset_id is null
              or a.status in('UNSUPPORTED','CORRUPT','MISSING',
                'FAILED','SUPERSEDED')))
        and not exists(
          select 1
          from public.invoice_lines l
          join public.invoices existing on existing.id=l.invoice_id
          where l.timesheet_id=m.timesheet_id
            and existing.id<>m.planned_invoice_id
            and existing.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS')
      ) still_valid
    from members m join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current and ts.revoked_at is null
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join commit_reference_eval ref
      on ref.source_member_key=m.source_member_key
    left join commit_vat_eval vat
      on vat.source_member_key=m.source_member_key
    left join commit_correction_eval corr
      on corr.scope_key=m.planned_invoice_id::text
    group by m.chunk_id
  ),
  commit_resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from normal_chunks c
  ),
  commit_resolver_results as materialized (
    select ri.chunk_id,r.source_revision_hash,r.blocker_code
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from commit_resolver_inputs ri),null,v_now) r
    join commit_resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=ri.payload_json->>'group_key'
  ),
  revision_check as materialized (
    select c.id chunk_id,r.source_revision_hash current_revision,
      s.still_valid and r.blocker_code is null still_valid
    from normal_chunks c
    join source_still_valid s on s.chunk_id=c.id
    join commit_resolver_results r on r.chunk_id=c.id
  ),
  rejected as (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code','SOURCE_CHANGED_BEFORE_COMMIT'),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from revision_check r
    where c.id=r.chunk_id and (not r.still_valid or r.current_revision<>c.payload_json->>'source_revision')
    returning c.id
  ),
  valid_chunks as materialized (
    select c.* from normal_chunks c join revision_check r on r.chunk_id=c.id
    where r.still_valid and r.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from rejected x where x.id=c.id)
  ),
  header_source as materialized (
    select vc.id chunk_id,vc.planned_invoice_id,(array_agg(tf.client_id order by tf.client_id))[1] client_id,
      max(cl.name) client_name,max(cl.invoice_address) client_invoice_address,
      max(cl.primary_invoice_email) primary_invoice_email,bool_and(cl.vat_chargeable) vat_chargeable,
      max(cl.payment_terms_days) payment_terms_days,
      max(sd.agency_name) agency_name,max(sd.agency_logo) agency_logo,
      max(sd.registered_address) registered_address,max(sd.company_reg_number) company_reg_number,
      max(sd.bank_name) bank_name,max(sd.bank_sort_code) bank_sort_code,
      max(sd.bank_account_number) bank_account_number,max(sd.vat_registration_number) vat_registration_number,
      count(*)::integer source_count
    from valid_chunks vc join members m on m.chunk_id=vc.id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.clients cl on cl.id=tf.client_id cross join public.settings_defaults sd
    where sd.id=1 group by vc.id,vc.planned_invoice_id
  ),
  source_rows_base as materialized (
    select m.chunk_id,m.planned_invoice_id,m.payload_json,
      m.source_member_key,m.source_type,m.source_id,m.segment_id,tf.*,ts.booking_id,
      ts.week_ending_date,ts.reference_number,ts.sheet_scope,ts.submission_mode,ts.day_references_json,
      ts.actual_schedule_json,coalesce(ts.contract_id,cw.contract_id) contract_id,
      coalesce(cd.display_name,'Candidate '||left(coalesce(tf.candidate_id::text,m.timesheet_id::text),8)) candidate_display,
      coalesce(ct.daily_calc_of_invoices,false) daily_calc_of_invoices,
      coalesce(ct.bucket_labels_json,
        jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH'))
        bucket_labels_json,
      ct.role contract_role,ct.display_site contract_display_site,
      ct.ward_hint contract_ward_hint,
      null::numeric ordinary_vat_rate,
      case when ts.sheet_scope::text='WEEKLY'
          and ts.submission_mode::text='MANUAL'
          and jsonb_typeof(ts.actual_schedule_json)='array'
        then coalesce((
          select jsonb_agg(jsonb_build_object(
            'date',e.value->>'date','start',e.value->>'start',
            'end',e.value->>'end','start_utc',e.value->>'start_utc',
            'end_utc',e.value->>'end_utc','ref_num',e.value->>'ref_num')
            order by e.ordinality)
          from jsonb_array_elements(ts.actual_schedule_json)
            with ordinality e(value,ordinality)
          where nullif(btrim(e.value->>'start'),'') is not null
            and nullif(btrim(e.value->>'end'),'') is not null
        ),'[]'::jsonb)
        else '[]'::jsonb end schedule_refs
    from members m join valid_chunks vc on vc.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    left join lateral (
      select w.contract_id
      from public.contract_weeks w
      where w.timesheet_id=m.timesheet_id
      order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc
      limit 1
    ) cw on true
    left join public.contracts ct on ct.id=coalesce(ts.contract_id,cw.contract_id)
    left join public.candidates cd on cd.id=tf.candidate_id
  ),
  vat_policy as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',s.source_member_key,
        'source_type',s.source_type,'source_id',s.source_id,
        'timesheet_id',s.timesheet_id,'segment_id',s.segment_id,
        'ordinary_rate',s.ordinary_vat_rate,
        'effective_date',coalesce(
          case when s.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                s.payload_json->>'effective_settings_date','date')
            then(s.payload_json->>'effective_settings_date')::date end,
          s.week_ending_date::date))
        order by s.chunk_id,s.timesheet_id)
      from source_rows_base s
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  source_rows as materialized (
    select s.*,v.vat_rate
    from source_rows_base s
    join vat_policy v on v.source_member_key=s.source_member_key and v.valid
  ),
  segment_lock_targets_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'invoice_id',s.planned_invoice_id,
      'timesheet_id',s.timesheet_id,
      'segment_ids',to_jsonb(p.segment_ids),
      'expected_financial_revision',encode(digest(jsonb_build_object(
        'financial_id',s.id,
        'timesheet_version',s.timesheet_version,
        'updated_at',s.updated_at,
        'basis',s.basis,
        'invoice_breakdown_json',s.invoice_breakdown_json
      )::text,'sha256'),'hex'))
      order by s.planned_invoice_id,s.timesheet_id),'[]'::jsonb) targets
    from source_rows s
    join selected_segments p
      on p.chunk_id=s.chunk_id and p.timesheet_id=s.timesheet_id
    where cardinality(coalesce(p.segment_ids,array[]::text[]))>0
  ),
  segment_lock_authority_pre as materialized (
    select r.*
    from segment_lock_targets_pre t
    cross join lateral private._invoice_segment_lock_batch(t.targets,v_now) r
  ),
  segment_lock_failures_pre as materialized (
    select * from segment_lock_authority_pre where not success
  ),
  segment_entries as materialized (
    select s.*,seg.ordinality,
      coalesce(nullif(seg.value->>'segment_id',''),
        left(encode(digest(seg.value::text,'sha256'),'hex'),24)) segment_id,
      case when left(coalesce(seg.value->>'date',''),10)
        ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        then left(seg.value->>'date',10) end work_date,
      case when coalesce(seg.value->>'hours_day','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_day')::numeric
        else 0 end segment_hours_day,
      case when coalesce(seg.value->>'hours_night','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_night')::numeric
        else 0 end segment_hours_night,
      case when coalesce(seg.value->>'hours_sat','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sat')::numeric
        else 0 end segment_hours_sat,
      case when coalesce(seg.value->>'hours_sun','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sun')::numeric
        else 0 end segment_hours_sun,
      case when coalesce(seg.value->>'hours_bh','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_bh')::numeric
        else 0 end segment_hours_bh,
      case
        when coalesce(seg.value->>'pay_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_amount')::numeric
        when coalesce(seg.value->>'pay_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_ex_vat')::numeric
        else 0 end segment_pay_ex,
      case
        when coalesce(seg.value->>'charge_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_amount')::numeric
        when coalesce(seg.value->>'charge_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_ex_vat')::numeric
        else 0 end segment_charge_ex
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      with ordinality seg(value,ordinality)
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and nullif(seg.value->>'invoice_locked_invoice_id','') is null
      and exists(
        select 1 from selected_segments picked
        where picked.chunk_id=s.chunk_id
          and picked.timesheet_id=s.timesheet_id
          and coalesce(nullif(seg.value->>'segment_id',''),
            left(encode(digest(seg.value::text,'sha256'),'hex'),24))
            =any(coalesce(picked.segment_ids,array[]::text[])))
  ),
  segment_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where s.daily_calc_of_invoices and s.work_date is not null
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date
  ),
  segment_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where not s.daily_calc_of_invoices
       or not exists(select 1 from segment_entries d
         where d.chunk_id=s.chunk_id and d.timesheet_id=s.timesheet_id
           and d.daily_calc_of_invoices and d.work_date is not null)
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date
  ),
  nonsegment_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      coalesce(s.hours_day,0) h_day,coalesce(s.hours_night,0) h_night,coalesce(s.hours_sat,0) h_sat,
      coalesce(s.hours_sun,0) h_sun,coalesce(s.hours_bh,0) h_bh,
      round(coalesce(s.total_pay_ex_vat,0)-coalesce(s.additional_pay_ex_vat,0)
        -coalesce(s.expenses_pay_ex_vat,0)-coalesce(s.mileage_pay_ex_vat,0),2) pay_ex,
      round(coalesce(s.total_charge_ex_vat,0)-coalesce(s.additional_charge_ex_vat,0)
        -coalesce(s.expenses_charge_ex_vat,0)-coalesce(s.mileage_charge_ex_vat,0),2) charge_ex,
      s.vat_rate,s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,
      s.charge_bh,s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
       or jsonb_array_length(case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
                                  then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ),
  additional_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,upper(a.key) code,
      left(d.key,10) work_date,
      case when pg_input_is_valid(d.value,'numeric')
        then d.value::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'pay_rate','numeric')
          then(a.value->>'pay_rate')::numeric else 0 end),2) pay_ex,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'charge_rate','numeric')
          then(a.value->>'charge_rate')::numeric else 0 end),2) charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    cross join lateral jsonb_each_text(
      case when jsonb_typeof(a.value->'days')='object'
        then a.value->'days' else '{}'::jsonb end) d
    where s.daily_calc_of_invoices
      and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      and exists(select 1 from segment_entries se
        where se.chunk_id=s.chunk_id and se.timesheet_id=s.timesheet_id
          and se.work_date is not null)
  ),
  additional_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      upper(a.key) code,
      case when pg_input_is_valid(a.value->>'unit_count','numeric')
        then(a.value->>'unit_count')::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
        then(a.value->>'pay_ex_vat')::numeric else 0 end pay_ex,
      case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
        then(a.value->>'charge_ex_vat')::numeric else 0 end charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    where jsonb_typeof(a.value)='object'
      and ((case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
              then(a.value->>'pay_ex_vat')::numeric else 0 end)<>0
        or (case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
              then(a.value->>'charge_ex_vat')::numeric else 0 end)<>0)
      and not(s.daily_calc_of_invoices
        and jsonb_typeof(a.value->'days')='object'
        and exists(select 1 from jsonb_each_text(
          case when jsonb_typeof(a.value->'days')='object'
            then a.value->'days' else '{}'::jsonb end) d
          where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
  ),
  expense_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      e.code,e.pay_ex,e.charge_ex,s.vat_rate,s.expenses_description,
      s.expenses_evidence_r2_key,s.expenses_evidence_manifest,
      s.mileage_units,s.mileage_pay_rate,s.mileage_charge_rate,
      s.mileage_evidence_r2_key,s.mileage_evidence_manifest,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral (
      values
       ('TRAVEL',coalesce(s.travel_pay_ex_vat,0),coalesce(s.travel_charge_ex_vat,0)),
       ('ACCOMMODATION',coalesce(s.accommodation_pay_ex_vat,0),coalesce(s.accommodation_charge_ex_vat,0)),
       ('OTHER',coalesce(s.other_pay_ex_vat,0),coalesce(s.other_charge_ex_vat,0)),
       ('EXPENSES_FALLBACK',
          case when coalesce(s.travel_pay_ex_vat,0)+coalesce(s.accommodation_pay_ex_vat,0)+coalesce(s.other_pay_ex_vat,0)=0 then coalesce(s.expenses_pay_ex_vat,0) else 0 end,
          case when coalesce(s.travel_charge_ex_vat,0)+coalesce(s.accommodation_charge_ex_vat,0)+coalesce(s.other_charge_ex_vat,0)=0 then coalesce(s.expenses_charge_ex_vat,0) else 0 end),
       ('MILEAGE',coalesce(s.mileage_pay_ex_vat,0),coalesce(s.mileage_charge_ex_vat,0))
    ) e(code,pay_ex,charge_ex)
    where e.pay_ex<>0 or e.charge_ex<>0
  ),
  line_union as materialized (
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||work_date description,h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric pay_day,null::numeric pay_night,null::numeric pay_sat,
      null::numeric pay_sun,null::numeric pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_DAILY' line_type,
      'TS:'||timesheet_id||':HOURS:'||work_date source_key,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json) detail
    from segment_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from segment_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from nonsegment_lines
    where pay_ex<>0 or charge_ex<>0 or h_day+h_night+h_sat+h_sun+h_bh<>0
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||work_date||' - '||
        units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE_DAILY',
      'TS:'||timesheet_id||':ADD:'||code||':'||work_date,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE',
      'TS:'||timesheet_id||':ADD:'||code||':WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      case when code='MILEAGE' then 'Mileage - '||coalesce(mileage_units,0)||
          ' miles (W/E '||week_ending_date||')'
        else initcap(replace(code,'_',' '))||' (W/E '||week_ending_date||')' end,
      0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,
      case when code='MILEAGE' then 'MILEAGE'
        when code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
        else 'EXPENSE_'||code end,
      case when code='MILEAGE' then 'TS:'||timesheet_id||':MILEAGE'
        when code='EXPENSES_FALLBACK' then 'TS:'||timesheet_id||':EXP:TOTAL'
        else 'TS:'||timesheet_id||':EXP:'||code end,
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'expense',case when code='MILEAGE' then jsonb_build_object(
          'category','MILEAGE','mileage_units',mileage_units,
          'pay_rate',mileage_pay_rate,'charge_rate',mileage_charge_rate,
          'evidence_r2_key',mileage_evidence_r2_key,
          'evidence_manifest',mileage_evidence_manifest)
        else jsonb_build_object('category',code,'note',expenses_description,
          'evidence_r2_key',expenses_evidence_r2_key,
          'evidence_manifest',expenses_evidence_manifest) end)
    from expense_lines
  ),
  correction_scopes_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-prewrite:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_PREWRITE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select l.planned_invoice_id,min(vc.payload_json::text)::jsonb payload_json,
        jsonb_agg(distinct jsonb_build_object(
          'timesheet_id',l.timesheet_id,
          'vat_rate_pct',l.vat_rate))
          filter(where l.timesheet_id is not null) planned_members
      from line_union l
      join valid_chunks vc on vc.id=l.chunk_id
      group by l.planned_invoice_id
    ) scope
  ),
  correction_validation_pre as materialized (
    select r.*
    from correction_scopes_pre s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),
  correction_failures_pre as materialized (
    select scope_key,blocker_code,detail_json detail
    from correction_validation_pre
    where not valid
  ),  write_eligible_chunks as materialized (
    select vc.*
    from valid_chunks vc
    where not exists(
      select 1 from correction_failures_pre f
      where f.scope_key=vc.planned_invoice_id::text)
  ),
  line_totals as materialized (
    select l.planned_invoice_id,
      round(sum(round(l.charge_ex,2)),2) subtotal_ex_vat,
      round(sum(round(l.charge_ex*l.vat_rate/100,2)),2) vat_amount,
      round(sum(round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)),2) total_inc_vat
    from line_union l
    join write_eligible_chunks w on w.id=l.chunk_id
    group by l.planned_invoice_id
  ),
  existing_target_headers as materialized (
    select vc.id chunk_id,i.id invoice_id
    from write_eligible_chunks vc
    join header_source h on h.chunk_id=vc.id
    join public.invoices i on i.id=vc.planned_invoice_id
      and i.client_id=h.client_id and i.type='INVOICE' and i.status='DRAFT'
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=vc.planned_invoice_id)
  ),
  inserted_headers as (
    insert into public.invoices(id,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select h.planned_invoice_id,h.client_id,'DRAFT',v_now,
      t.subtotal_ex_vat,t.vat_amount,t.total_inc_vat,
      jsonb_build_object('client_id',h.client_id,'client_name',h.client_name,
        'client_invoice_address',h.client_invoice_address,'client_primary_invoice_email',h.primary_invoice_email,
        'agency_name',h.agency_name,'agency_logo',h.agency_logo,'registered_address',h.registered_address,
        'company_reg_number',h.company_reg_number,'company_registration_number',h.company_reg_number,
        'vat_chargeable',h.vat_chargeable,'payment_terms_days',h.payment_terms_days,
        'issued_at_utc',null,'due_at_utc',null,
        'totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,
          'vat_amount',t.vat_amount,'total_inc_vat',t.total_inc_vat),
        'bank',jsonb_build_object('name',h.bank_name,'sort_code',h.bank_sort_code,'account_number',h.bank_account_number),
        'vat_registration_number',h.vat_registration_number,
        'meta',jsonb_build_object('source','INVOICE_OPERATION_QUEUE',
          'invoice_week_start',vc.payload_json->>'target_invoice_week',
          'consolidation_mode',vc.payload_json->>'consolidation_mode',
          'self_bill',vc.payload_json->>'invoice_stream'='SELF_BILL','timesheet_count',h.source_count),
        'attach_policy',vc.payload_json#>'{plan,settings_snapshot,attach_policy}'),
      1,'STALE',v_now,v_now
    from header_source h join write_eligible_chunks vc on vc.id=h.chunk_id
    join line_totals t on t.planned_invoice_id=h.planned_invoice_id
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=h.planned_invoice_id)
    on conflict(id) do nothing returning id
  ),
  target_headers as materialized (
    select vc.id chunk_id,h.id invoice_id
    from inserted_headers h
    join write_eligible_chunks vc on vc.planned_invoice_id=h.id
    union all
    select e.chunk_id,e.invoice_id
    from existing_target_headers e
  ),
  inserted_lines as (
    insert into public.invoice_lines(
      invoice_id,timesheet_id,booking_id,description,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,
      paper_ts_r2_key,meta_json,source_key
    )
    select l.planned_invoice_id,l.timesheet_id,l.booking_id,l.description,
      round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),l.vat_rate,
      round(l.charge_ex*l.vat_rate/100,2),round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2),
      null,jsonb_build_object('line_type',l.line_type,'timesheet_id',l.timesheet_id,
        'candidate_display',l.description,'week_ending_date',
        (select s.week_ending_date from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'schedule_references',
        (select s.schedule_refs from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
          'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
          'vat_rate_pct',l.vat_rate,'vat_amount',round(l.charge_ex*l.vat_rate/100,2),
          'total_inc_vat',round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)))||l.detail,l.source_key
    from line_union l join target_headers h on h.invoice_id=l.planned_invoice_id
    on conflict(invoice_id,source_key) do nothing
    returning invoice_id,timesheet_id,total_charge_ex_vat,vat_amount,total_inc_vat
  ),
  all_target_lines as materialized (
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from public.invoice_lines l
    where l.invoice_id in(select invoice_id from target_headers)
    union all
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from inserted_lines l
  ),
  all_line_totals as materialized (
    select l.invoice_id,count(*)::integer line_count,
      round(sum(l.total_charge_ex_vat),2) subtotal_ex_vat,
      round(sum(l.vat_amount),2) vat_amount,
      round(sum(l.total_inc_vat),2) total_inc_vat
    from all_target_lines l
    group by l.invoice_id
  ),
  updated_header_totals as (
    update public.invoices i
    set subtotal_ex_vat=t.subtotal_ex_vat,vat_amount=t.vat_amount,
      total_inc_vat=t.total_inc_vat,document_state='STALE',
      header_snapshot_json=coalesce(i.header_snapshot_json,'{}'::jsonb)
        ||jsonb_build_object('totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,'vat_amount',t.vat_amount,
          'total_inc_vat',t.total_inc_vat)),
      updated_at=v_now
    from all_line_totals t where i.id=t.invoice_id
    returning i.id
  ),
  segment_lock_targets as materialized (
    select targets from segment_lock_targets_pre
  ),
  segment_lock_authority as materialized (
    select * from segment_lock_authority_pre
  ),
  segment_lock_failures as materialized (
    select * from segment_lock_authority where not success
  ),
  whole_lock as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=vc.planned_invoice_id,locked_at_utc=v_now,updated_at=v_now
    from members m join write_eligible_chunks vc on vc.id=m.chunk_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    where tf.timesheet_id=m.timesheet_id and tf.is_current
      and (coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        or not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                      where nullif(e->>'invoice_locked_invoice_id','') is null))
    returning tf.timesheet_id
  ),
  week_lock as (
    update public.contract_weeks cw set status='INVOICED',updated_at=v_now
    where cw.timesheet_id in(select timesheet_id from members)
      and exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=cw.timesheet_id
        and tf.is_current and (tf.locked_by_invoice_id is not null or
          not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                     where nullif(e->>'invoice_locked_invoice_id','') is null)))
    returning cw.id
  ),
  hr_sources as (
    insert into public.invoice_hr_source_rows(invoice_id,source_system,import_id,header_columns,rows_json,header_rows)
    select distinct vc.planned_invoice_id,
      case when tf.basis::text='NHSP' then 'NHSP' else 'HEALTHROSTER' end,
      tf.nhsp_import_id,'[]'::jsonb,
      case when jsonb_typeof(tf.external_source_rows_json)='array' then tf.external_source_rows_json else '[]'::jsonb end,
      '[]'::jsonb
    from members m join write_eligible_chunks vc on vc.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    where tf.nhsp_import_id is not null
    on conflict(invoice_id,source_system,import_id) do update set rows_json=excluded.rows_json
    returning invoice_id
  ),
  source_segments as materialized (
    select distinct s.planned_invoice_id,
      substr(x.value->>'segment_id',6)::uuid shift_id
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end) x(value)
    where left(x.value->>'segment_id',5)='nhsp:'
      and substr(x.value->>'segment_id',6) ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and (
        upper(coalesce(x.value->>'source_system',''))='NHSP'
        or (upper(coalesce(x.value->>'source_system',''))='HEALTHROSTER'
          and coalesce((s.payload_json#>>'{plan,settings_snapshot,attach_policy,requires_hr}')::boolean,false)
          and coalesce((s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,true)))
  ),
  source_imports as materialized (
    select s.planned_invoice_id,upper(coalesce(n.source_system::text,'UNKNOWN')) source_system,
      n.latest_import_id import_id,jsonb_agg(distinct n.external_row_key) row_keys
    from source_segments s join public.nhsp_shifts n on n.id=s.shift_id
    where n.latest_import_id is not null and n.external_row_key is not null
    group by s.planned_invoice_id,upper(coalesce(n.source_system::text,'UNKNOWN')),n.latest_import_id
  ),
  authoritative_hr_sources as (
    insert into public.invoice_hr_source_rows(
      invoice_id,source_system,import_id,header_columns,rows_json)
    select g.planned_invoice_id,g.source_system,g.import_id,
      case when jsonb_typeof(i.parse_summary_json->'header_columns')='array'
        then i.parse_summary_json->'header_columns' else '[]'::jsonb end,
      coalesce((select jsonb_agg(r.payload_json order by r.id)
        from public.hr_rows r where r.import_id=g.import_id
          and r.external_row_key in(select jsonb_array_elements_text(g.row_keys))),
        '[]'::jsonb)
    from source_imports g join public.hr_imports i on i.id=g.import_id
    on conflict(invoice_id,source_system,import_id) do update
      set header_columns=excluded.header_columns,rows_json=excluded.rows_json
    returning invoice_id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoices',vc.planned_invoice_id::text,
      case when exists(select 1 from inserted_headers h
        where h.id=vc.planned_invoice_id)
        then 'INVOICE_CREATED' else 'INVOICE_DRAFT_APPENDED' end,
      jsonb_build_object('invoice_id',vc.planned_invoice_id,
        'source_ids',coalesce(vc.payload_json->'canonical_source_ids',
          vc.payload_json->'source_ids','[]'::jsonb),
        'source_revision',vc.payload_json->>'source_revision',
        'operation_id',vc.operation_id),'INVOICE_OPERATION_QUEUE'
    from write_eligible_chunks vc join public.invoice_operations o on o.id=vc.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  correction_failures as materialized (
    select scope_key::uuid invoice_id,blocker_code,detail
    from correction_failures_pre
    where scope_key~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  update public.invoice_operation_chunks c
    set status=case when exists(select 1 from all_line_totals l
                               where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'QUEUED' else 'BLOCKED' end,
      phase=case when exists(select 1 from all_line_totals l
                            where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'QUEUE_DOCUMENT' else 'BLOCKED' end,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(vc.planned_invoice_id),
        'source_revision',vc.payload_json->>'source_revision'),
      error_json=case
        when not exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','NO_INVOICE_LINES_CREATED')
        when exists(select 1 from segment_lock_failures sf
          where sf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','SEGMENT_LOCK_FAILED','detail',(
            select jsonb_agg(to_jsonb(sf))
            from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id))
        when exists(select 1 from correction_failures cf
          where cf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code',(
            select cf.blocker_code from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id))
        else null end,
      completed_at_utc=null,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from valid_chunks vc
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    cross join (select count(*) cached_count from authoritative_hr_sources) source_cache_application
    where c.id=vc.id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='COMMIT'
    and coalesce(c.payload_json->>'command_type','')<>'GENERATE_CREDIT_NOTE';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note COMMIT: exact negative line clone and source unlock; document creation stays asynchronous.
  execute $q$
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements($1) x where x->>'phase'='COMMIT'
  ),
  credit_revisions as materialized (
    select c.*,i.id source_invoice_id,(c.payload_json#>>'{plan,planned_invoice_id}')::uuid credit_note_id
      ,encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex') current_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
      and i.type='INVOICE' and i.status in ('ISSUED','PAID')
  ),
  credit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','credit-source:'||c.source_invoice_id::text,
      'scope_key',c.source_invoice_id::text,
      'invoice_id',c.source_invoice_id,
      'validation_purpose','CREDIT_SOURCE')
      order by c.source_invoice_id),'[]'::jsonb) scopes
    from(select distinct source_invoice_id from credit_revisions) c
  ),
  credit_correction_failures as materialized (
    select r.invoice_id source_invoice_id,r.blocker_code,r.detail_json
    from credit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,($2 at time zone 'Europe/London')::date) r
    where not r.valid
  ),
  credit_rejected as (
    update public.invoice_operation_chunks q
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code',case
        when c.current_revision<>c.payload_json->>'source_revision'
          then 'CREDIT_SOURCE_CHANGED_BEFORE_COMMIT'
        else coalesce((select f.blocker_code
          from credit_correction_failures f
          where f.source_invoice_id=c.source_invoice_id
          order by f.blocker_code limit 1),'CREDIT_CORRECTION_VALIDATION_FAILED')
        end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=$2
    from credit_revisions c
    where q.id=c.id and(
      c.current_revision<>c.payload_json->>'source_revision'
      or exists(select 1 from credit_correction_failures f
        where f.source_invoice_id=c.source_invoice_id))
    returning q.id
  ),
  credits as materialized (
    select c.* from credit_revisions c
    where c.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from credit_rejected r where r.id=c.id)
  ),
  inserted_credit as (
    insert into public.invoices(id,type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      original_invoice_id,notes,header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select c.credit_note_id,'CREDIT_NOTE',i.client_id,'DRAFT',$2,
      -i.subtotal_ex_vat,-i.vat_amount,-i.total_inc_vat,i.id,
      c.payload_json->>'credit_reason',
      i.header_snapshot_json||jsonb_build_object(
        'credit_source_invoice_id',i.id,
        'credit_reason',c.payload_json->>'credit_reason'),1,'STALE',$2,$2
    from credits c join public.invoices i on i.id=c.source_invoice_id
    on conflict(id) do nothing returning id
  ),
  cloned_lines as (
    insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,
      hours_day,hours_night,hours_sat,hours_sun,hours_bh,pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,total_pay_ex_vat,total_charge_ex_vat,
      margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,paper_ts_r2_key,meta_json,source_key)
    select c.credit_note_id,l.timesheet_id,l.booking_id,
      'CREDIT NOTE – '||coalesce(l.description,''),
      l.hours_day,l.hours_night,l.hours_sat,l.hours_sun,l.hours_bh,
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      -l.total_pay_ex_vat,-l.total_charge_ex_vat,-l.margin_ex_vat,l.vat_rate_pct,
      -l.vat_amount,-l.total_inc_vat,l.paper_ts_r2_key,
      coalesce(l.meta_json,'{}'::jsonb)||jsonb_build_object(
        'credit_note',true,'original_invoice_id',c.source_invoice_id,
        'original_invoice_line_id',l.id,'credit_of_line_id',l.id,'line_type',
        'CREDIT_'||coalesce(l.meta_json->>'line_type','LINE')),
      'CN:'||c.credit_note_id||':LINE:'||l.id
    from credits c join public.invoice_lines l on l.invoice_id=c.source_invoice_id
    on conflict(invoice_id,source_key) do nothing returning invoice_id
  ),
  source_mark as (
    update public.invoices i set credit_note_created_at_utc=$2,updated_at=$2
    where i.id in(select source_invoice_id from credits) returning i.id
  ),
  unlocks as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=null,locked_at_utc=null,
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.locked_by_invoice_id=c.source_invoice_id and tf.is_current returning tf.timesheet_id
  ),
  segment_unlocks as (
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(tf.invoice_breakdown_json,'{segments}',
      (select jsonb_agg(case
        when e.value->>'invoice_locked_invoice_id'=c.source_invoice_id::text
          then (e.value-'invoice_locked_invoice_id'-'invoice_locked_at_utc')
        else e.value end order by e.ordinality)
       from jsonb_array_elements(tf.invoice_breakdown_json->'segments')
         with ordinality e(value,ordinality)),true),
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.is_current and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
      and exists(select 1 from jsonb_array_elements(tf.invoice_breakdown_json->'segments') e
        where e->>'invoice_locked_invoice_id'=c.source_invoice_id::text)
    returning tf.timesheet_id
  ),
  recompute_outbox as (
    insert into public.ts_financials_outbox(
      timesheet_id,reason,attempt_count,next_attempt_at,last_error,created_at)
    select distinct u.timesheet_id,'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,$2,null,$2
    from (
      select timesheet_id from unlocks
      union all select timesheet_id from segment_unlocks
    ) u
    on conflict on constraint uq_tsfin_outbox do nothing
    returning timesheet_id
  ),
  credit_audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,
      actor_role_at_time,object_type,object_id_text,action,after_json,reason)
    select $2,o.actor_user_id,u.display_name,u.role,'invoices',
      c.credit_note_id::text,'CREDIT_NOTE_CREATED',
      jsonb_build_object('credit_note_id',c.credit_note_id,
        'original_invoice_id',c.source_invoice_id,
        'credit_reason',c.payload_json->>'credit_reason',
        'command_token',c.payload_json->>'command_token',
        'subtotal_ex_vat',-i.subtotal_ex_vat,'vat_amount',-i.vat_amount,
        'total_inc_vat',-i.total_inc_vat,
        'financial_recompute_enqueued',true),
      'INVOICE_OPERATION_QUEUE'
    from credits c join public.invoices i on i.id=c.source_invoice_id
    join public.invoice_operations o on o.id=c.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  completed as (
    update public.invoice_operation_chunks q
    set status='QUEUED',
      phase='QUEUE_DOCUMENT',
      error_json=null,
      completed_at_utc=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=$2,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(c.credit_note_id),
        'credit_note_id',c.credit_note_id,'source_invoice_id',c.source_invoice_id)
    from credits c
    cross join (select count(*) outbox_count from recompute_outbox) outbox_application
    cross join (select count(*) audit_count from credit_audits) audit_application
    where q.id=c.id
    returning q.id,q.status,q.phase,q.result_json,q.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]'::jsonb)
  from completed
  $q$
  into v_part using p_claims,v_now;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Document work is queued in a separate SQL statement so source-invalidation
  -- statement triggers cannot supersede the freshly-created document operation.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='QUEUE_DOCUMENT'
  ),
  queued_sources as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,
      (c.payload_json#>>'{plan,planned_invoice_id}')::uuid planned_invoice_id,
      c.payload_json->>'source_revision' source_revision,
      c.payload_json->>'command_type' command_type,
      c.payload_json->>'command_token' command_token,
      c.payload_json->>'credit_reason' credit_reason,
      i.document_revision::text document_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i
      on i.id=(c.payload_json#>>'{plan,planned_invoice_id}')::uuid
  ),
  existing_doc_versions as materialized (
    select distinct on(q.chunk_id) q.chunk_id,v.id document_version_id,
      v.operation_id,v.status
    from queued_sources q
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=q.planned_invoice_id
     and v.purpose='DRAFT_PREVIEW'
     and v.source_revision=q.document_revision
     and v.template_version='invoice-professional-v1'
     and v.status in(
       'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
       'VERIFYING','READY')
    where q.command_type<>'GENERATE_CREDIT_NOTE'
    order by q.chunk_id,case when v.status='READY' then 0 else 1 end,
      v.created_at_utc desc,v.id desc
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'BUILD_DOCUMENT','INVOICE',q.planned_invoice_id,o.actor_user_id,
      encode(digest('DRAFT_PREVIEW|'||q.planned_invoice_id||'|'||q.document_revision||
        '|invoice-professional-v1','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',550,q.document_revision,'invoice-professional-v1',
      jsonb_build_object('invoice_id',q.planned_invoice_id,'purpose','DRAFT_PREVIEW'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type<>'GENERATE_CREDIT_NOTE'
      and not exists(
        select 1 from existing_doc_versions e where e.chunk_id=q.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),updated_at_utc=v_now
    returning *
  ),
  selected_doc_ops as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision source_revision,
      d.id operation_id,d.control_version,null::uuid existing_version_id,
      null::text existing_status
    from queued_sources q join doc_ops d on d.entity_id=q.planned_invoice_id
    union all
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      e.operation_id,o.control_version,e.document_version_id,e.status
    from queued_sources q
    join existing_doc_versions e on e.chunk_id=q.chunk_id
    join public.invoice_operations o on o.id=e.operation_id
  ),
  doc_versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',d.planned_invoice_id,'DRAFT_PREVIEW',d.operation_id,d.source_revision,
      'invoice-professional-v1','PLANNING','{}',encode(digest('{}','sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected_doc_ops d
    where d.existing_version_id is null
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET')
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id
  ),
  all_doc_versions as materialized (
    select d.chunk_id,d.planned_invoice_id,d.operation_id,d.control_version,
      d.source_revision,
      coalesce(d.existing_version_id,v.id) document_version_id,
      coalesce(d.existing_status,'PLANNING') document_status
    from selected_doc_ops d
    left join doc_versions v
      on v.entity_id=d.planned_invoice_id and v.operation_id=d.operation_id
    where d.existing_version_id is not null or v.id is not null
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select d.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',d.document_version_id::text,
        d.source_revision,'invoice-professional-v1','1'),'sha256'),'hex'),
      0,'INVOICE',d.planned_invoice_id,d.document_version_id,
      'QUEUED',550,v_now,jsonb_build_object('purpose','DRAFT_PREVIEW'),d.control_version,v_now,v_now
    from all_doc_versions d
    where d.document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning operation_id
  ),
  invoice_ptrs as (
    update public.invoices i set preview_document_version_id=d.document_version_id,
      active_document_operation_id=case when d.document_status='READY'
        then null else d.operation_id end,
      document_state=case when d.document_status='READY'
        then 'READY' else 'QUEUED' end,updated_at=v_now
    from all_doc_versions d where i.id=d.planned_invoice_id returning i.id
  ),
  credit_issue_ops as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,chunk_count,
      control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'ISSUE_INVOICES','INVOICE_BATCH',null,
      o.actor_user_id,
      encode(digest('CREDIT_ISSUE|'||q.planned_invoice_id||'|'||
        q.document_revision||'|'||coalesce(q.command_token,''),'sha256'),'hex'),
      'QUEUED','VALIDATE',850,q.document_revision,'invoice-professional-v1',
      jsonb_build_object(
        'invoice_ids',jsonb_build_array(q.planned_invoice_id),
        'credit_note',true,'credit_reason',q.credit_reason,
        'command_token',q.command_token,'deliver',false),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q
    join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type='GENERATE_CREDIT_NOTE'
    on conflict(idempotency_key)
      where status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),
      updated_at_utc=v_now
    returning *
  ),
  selected_credit_issue as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      q.command_token,q.credit_reason,o.id operation_id,o.control_version
    from queued_sources q
    join credit_issue_ops o on o.parent_operation_id=q.parent_operation_id
      and o.operation_type='ISSUE_INVOICES'
    where q.command_type='GENERATE_CREDIT_NOTE'
  ),
  credit_issue_chunks as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,status,
      priority,run_after_utc,payload_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select s.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',s.planned_invoice_id::text,
        s.document_revision,s.command_token),'sha256'),'hex'),
      0,'INVOICE',
      s.planned_invoice_id,'QUEUED',850,v_now,
      jsonb_build_object(
        'invoice_id',s.planned_invoice_id,
        'source_revision',s.document_revision,
        'allow_early',true,'deliver',false,
        'command_token',s.command_token,
        'credit_note',true,'credit_reason',s.credit_reason),
      s.control_version,v_now,v_now
    from selected_credit_issue s
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning operation_id
  ),
  credit_issue_ptrs as (
    update public.invoices i
    set active_issue_operation_id=s.operation_id,issue_state='VALIDATING',
      updated_at=v_now
    from selected_credit_issue s
    where i.id=s.planned_invoice_id
    returning i.id
  ),
  child_results as materialized (
    select d.chunk_id,d.operation_id document_operation_id,
      d.document_version_id,null::uuid issue_operation_id
    from all_doc_versions d
    union all
    select s.chunk_id,null::uuid,null::uuid,s.operation_id
    from selected_credit_issue s
  )
  update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=coalesce(c.result_json,'{}'::jsonb)||jsonb_build_object(
        'document_operation_id',d.document_operation_id,
        'document_version_id',d.document_version_id,
        'issue_operation_id',d.issue_operation_id)
    from child_results d where c.id=d.chunk_id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='QUEUE_DOCUMENT';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

-- private._invoice_generation_advance_batch(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_generation_advance_batch(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_manifest_claims jsonb;
  v_core_claims jsonb;
  v_rejected_claims jsonb;
  v_result jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(coalesce(p_claims,'null'::jsonb)) is distinct from 'array'
     or jsonb_array_length(p_claims) < 1
     or jsonb_array_length(p_claims) > 100 then
    raise exception using
      errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;

  with claims as materialized (
    select value claim_json,ordinality
    from jsonb_array_elements(p_claims) with ordinality claim(value,ordinality)
  ),
  classified as materialized (
    select
      claim.*,
      exists (
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.id=case
          when pg_input_is_valid(coalesce(claim.claim_json->>'chunk_id',''),'uuid')
            then (claim.claim_json->>'chunk_id')::uuid
        end
          and c.chunk_type='GENERATION_GROUP'
          and o.entity_type='INVOICE_BATCH'
          and not c.is_manifest_member
          and c.phase in ('BUILD_MANIFEST','RELEASE_MANIFEST')
          and coalesce(c.payload_json->>'is_selection_expander','false')
            in ('true','t','1','yes','on')
      ) is_manifest,
      exists (
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.id=case
          when pg_input_is_valid(
            coalesce(claim.claim_json->>'chunk_id',''),
            'uuid'
          ) then (claim.claim_json->>'chunk_id')::uuid
        end
          and c.chunk_type='GENERATION_GROUP'
          and (
            -- Direct client-scoped operations pre-date the batch manifest and
            -- are intentionally admitted by the public dispatcher.  They must
            -- continue directly to the V8 core processor.
            o.entity_type is distinct from 'INVOICE_BATCH'
            or (
              c.is_manifest_member
              and c.manifest_committed
              and o.manifest_committed
              and c.phase not in (
                'AWAITING_MANIFEST_COMMIT',
                'AWAITING_RELEASE'
              )
              and coalesce(
                c.payload_json->>'is_selection_expander',
                'false'
              ) not in ('true','t','1','yes','on')
            )
          )
      ) is_released
    from claims claim
  )
  select
    coalesce(jsonb_agg(claim_json order by ordinality)
      filter (where is_manifest),'[]'::jsonb),
    coalesce(jsonb_agg(claim_json order by ordinality)
      filter (where not is_manifest and is_released),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',claim_json->>'chunk_id',
      'status','REJECTED',
      'phase','OWNERSHIP_REJECTED',
      'accepted',false,
      'code','MANIFEST_CLAIM_NOT_RELEASED'
    ) order by ordinality)
      filter (where not is_manifest and not is_released),'[]'::jsonb)
  into v_manifest_claims,v_core_claims,v_rejected_claims
  from classified;

  if jsonb_array_length(v_manifest_claims)>0 then
    v_result := v_result
      || private._invoice_batch_manifest_advance_v2(
        v_manifest_claims,
        'GENERATE',
        v_now
      );
  end if;

  if jsonb_array_length(v_core_claims)>0 then
    v_result := v_result
      || private._invoice_generation_advance_core_v8(
        v_core_claims,
        v_now
      );
  end if;

  return coalesce(v_result,'[]'::jsonb)
    || coalesce(v_rejected_claims,'[]'::jsonb);
end;
$function$;

-- private._invoice_generation_advance_core_v8(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_generation_advance_core_v8(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_result jsonb := '[]'::jsonb;
  v_part jsonb;
begin
  -- VALIDATE_SOURCES: no invoice/header/line writes are permitted in this block.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  member_values as materialized (
    select c.id chunk_id,c.operation_id,c.payload_json,
      m.value member,m.ordinality
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
          and jsonb_array_length(c.payload_json->'canonical_source_members')>0
        then c.payload_json->'canonical_source_members'
        else coalesce((
          select jsonb_agg(jsonb_build_object(
            'source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality)
          from jsonb_array_elements_text(coalesce(
            c.payload_json->'canonical_source_ids',
            c.payload_json->'source_ids','[]'::jsonb))
            with ordinality s(value,ordinality)
        ),'[]'::jsonb) end) with ordinality m(value,ordinality)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select m.chunk_id,m.operation_id,m.payload_json,m.member,
      upper(coalesce(m.member->>'source_type','TIMESHEET')) source_type,
      case when coalesce(m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(m.member->>'source_id')::uuid end source_id,
      case when coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id')::uuid end timesheet_id,
      nullif(btrim(m.member->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(m.member->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(m.member->>'source_type','TIMESHEET')),
          coalesce(m.member->>'source_id',''),
          coalesce(m.member->>'related_timesheet_id',''),
          coalesce(m.member->>'segment_id','WHOLE'),
          coalesce(m.member->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key,
      nullif(btrim(coalesce(m.member->>'row_revision',
        m.member->>'source_revision','')),'') expected_revision,
      m.ordinality
    from member_values m
  ),
  reference_eval as materialized (
    select distinct on (r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.member->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode',
        'source_revision',m.expected_revision)
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  vat_eval as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-validate:'||scope.chunk_id::text,
      'scope_key',scope.chunk_id::text,
      'validation_purpose','GENERATION_VALIDATE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.chunk_id),'[]'::jsonb) scopes
    from(
      select m.chunk_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.ordinality) planned_members
      from members m
      left join vat_eval v on v.source_member_key=m.source_member_key
      group by m.chunk_id
    ) scope
  ),
  correction_eval as materialized (
    select r.*
    from correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_eval as materialized (
    select m.chunk_id,m.operation_id,m.timesheet_id,m.segment_id,
      m.source_member_key,m.ordinality,
      tf.id tsfin_id,
      encode(digest(concat_ws('|',tf.id::text,tf.timesheet_version::text,
        tf.updated_at::text,ts.version::text,ts.updated_at::text,
        coalesce(tf.invoice_breakdown_json::text,'')),'sha256'),'hex') row_revision,
      array_remove(array[
        case when ts.timesheet_id is null then 'TIMESHEET_NOT_FOUND' end,
        case when ts.timesheet_id is not null and (not ts.is_current or ts.revoked_at is not null) then 'TIMESHEET_NOT_CURRENT' end,
        case when tf.id is null then 'CURRENT_FINANCIALS_MISSING' end,
        case when tf.id is not null and tf.is_stale then 'FINANCIALS_STALE' end,
        case when tf.id is not null and tf.processing_status::text<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE' end,
        case when tf.id is not null and tf.has_rate_issue then 'RATE_MISSING' end,
        case when tf.id is not null and tf.has_pay_channel_issue then 'PAY_CHANNEL_MISSING' end,
        case when tf.id is not null and tf.client_id is null then 'CLIENT_UNRESOLVED' end,
        case when tf.id is not null and tf.locked_by_invoice_id is not null then 'SOURCE_ALREADY_LOCKED' end,
        case when ts.authorised_at_server is null
          then 'TIMESHEET_NOT_AUTHORISED' end,
        case when upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null)
          then 'QR_TIMESHEET_UNSIGNED' end,
        case when pc.require_reference_to_invoice
          and coalesce(ref.reference_ready,false) is not true
          then coalesce(ref.blocker_code,'MISSING_REFERENCE') end,
        case when coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_MILEAGE_EVIDENCE' end end,
        case when(coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'MILEAGE_ASSET_NOT_REGISTERED' end,
        case when coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_EXPENSE_EVIDENCE' end end,
        case when(
            coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'EXPENSE_ASSET_NOT_REGISTERED' end,
        case when(coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_TRAVEL_EVIDENCE' end,
        case when(coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_ACCOMMODATION_EVIDENCE' end,
        case when(coalesce(tf.other_pay_ex_vat,0)<>0
            or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_OTHER_EXPENSE_EVIDENCE' end,
        case when exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
            where e.timesheet_id=m.timesheet_id
              and a.status in(
                'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'))
          then 'REQUIRED_ASSET_PERMANENT_FAILURE' end,
        case when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED') end,
        case when corr.valid is false
          then coalesce(corr.blocker_code,'CORRECTION_VALIDATION_FAILED') end,
        case when coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED')
          then 'HEALTHROSTER_VALIDATION_REQUIRED' end,
        case when coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null)
          then 'NHSP_SOURCE_NOT_READY' end,
        case when exists(select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
                         where l.timesheet_id=m.timesheet_id and i.status in ('DRAFT','ISSUED','ON_HOLD'))
             and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS' then 'SOURCE_ALREADY_INVOICED' end
      ],null)::text[] blockers
    from members m
    left join public.timesheets ts on ts.timesheet_id=m.timesheet_id
    left join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join reference_eval ref on ref.source_member_key=m.source_member_key
    left join vat_eval vat on vat.source_member_key=m.source_member_key
    left join correction_eval corr
      on corr.scope_key=m.chunk_id::text
  ),
  resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  canonical_now as materialized (
    select ri.chunk_id,r.group_key,r.source_revision_hash,
      r.blocker_code,r.blocker_detail
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from resolver_inputs ri),null,v_now) r
    join resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  per_chunk as materialized (
    select c.id chunk_id,
      n.source_revision_hash current_revision,
      coalesce(jsonb_agg(jsonb_build_object('source_id',se.timesheet_id,
        'segment_id',se.segment_id,
        'codes',to_jsonb(se.blockers)) order by se.ordinality)
        filter(where cardinality(se.blockers)>0),'[]'::jsonb)
        ||case when n.blocker_code is null then '[]'::jsonb
          else jsonb_build_array(coalesce(n.blocker_detail,
            jsonb_build_object('code',n.blocker_code))) end blockers,
      count(se.timesheet_id)::integer source_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join source_eval se on se.chunk_id=c.id
    left join canonical_now n on n.chunk_id=c.id
    group by c.id,n.source_revision_hash,n.blocker_code,n.blocker_detail
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case
          when p.source_count=0 then 'BLOCKED'
          when jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'PLAN' end,
        status=case
          when p.source_count=0 or jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'QUEUED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',p.current_revision,'source_count',p.source_count),
        progress_json=jsonb_build_object('status_message',
          case when p.source_count=0 then 'No sources resolved'
               when jsonb_array_length(p.blockers)>0 then 'Source validation blocked'
               when nullif(c.payload_json->>'source_revision','') is not null
                and c.payload_json->>'source_revision'<>p.current_revision then 'Source changed'
               else 'Sources validated' end,'source_count',p.source_count),
        error_json=case
          when p.source_count=0 then jsonb_build_object('code','NO_SOURCES','sources','[]'::jsonb)
          when jsonb_array_length(p.blockers)>0 then jsonb_build_object('code','SOURCE_VALIDATION_BLOCKED','sources',p.blockers)
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then jsonb_build_object('code','SOURCE_CHANGED')
          else null end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from per_chunk p where c.id=p.chunk_id
    returning c.id,c.operation_id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note validation is deliberately separate from normal timesheet sources.
  with claim_ids as (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  credit_eval as (
    select c.id chunk_id,i.id invoice_id,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),'sha256'),'hex') revision,
      case when i.id is null then 'INVOICE_NOT_FOUND'
           when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
           when i.status::text not in ('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
           when exists(select 1 from public.invoices cn where cn.original_invoice_id=i.id and cn.type='CREDIT_NOTE'
                       and cn.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
           else null end blocker
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case when e.blocker is null then 'PLAN' else 'BLOCKED' end,
        status=case when e.blocker is null then 'QUEUED' else 'BLOCKED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',e.revision,'source_invoice_id',e.invoice_id),
        progress_json=jsonb_build_object('status_message',case when e.blocker is null then 'Credit source validated' else 'Credit source blocked' end),
        error_json=case when e.blocker is null then null else jsonb_build_object('code',e.blocker,'invoice_id',c.entity_id) end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from credit_eval e where c.id=e.chunk_id
    returning c.id,c.status,c.phase,c.error_json
  )
  select v_result||coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_result from updated;

  -- PLAN: compact financial/settings summary only; no complete line arrays.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='PLAN'
  ),
  members as materialized (
    select c.id chunk_id,c.payload_json,
      case when pg_input_is_valid(s.value,'uuid')
        then s.value::uuid end timesheet_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements_text(coalesce(
      c.payload_json->'canonical_source_ids',c.payload_json->'source_ids','[]'::jsonb)) s(value)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
      and pg_input_is_valid(s.value,'uuid')
  ),
  values_by_chunk as materialized (
    select m.chunk_id,count(*)::integer source_count,
      round(sum(coalesce(tf.total_pay_ex_vat,0)),2) expected_pay_ex_vat,
      round(sum(coalesce(tf.total_charge_ex_vat,0)),2) expected_charge_ex_vat,
      (array_agg(tf.client_id order by tf.client_id))[1] client_id,
      jsonb_build_object(
        'client_id',(array_agg(tf.client_id order by tf.client_id))[1],'consolidation_mode',max(c.payload_json->>'consolidation_mode'),
        'stream',max(c.payload_json->>'invoice_stream'),
        'invoice_week_start',max(c.payload_json->>'target_invoice_week'),
        'client',jsonb_build_object('name',max(cl.name),'vat_chargeable',bool_and(cl.vat_chargeable),
          'payment_terms_days',max(cl.payment_terms_days),'primary_invoice_email',max(cl.primary_invoice_email)),
        'attach_policy',jsonb_build_object(
          'hr_attach_to_invoice',coalesce(bool_or(cs.hr_attach_to_invoice),bool_or(sd.hr_attach_to_invoice),true),
          'ts_attach_to_invoice',coalesce(bool_or(cs.ts_attach_to_invoice),bool_or(sd.ts_attach_to_invoice),true),
          'requires_hr',coalesce(bool_or(cs.requires_hr),false))
      ) settings_snapshot
    from members m join public.invoice_operation_chunks c on c.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.clients cl on cl.id=tf.client_id
    left join lateral (
      select s.* from public.client_settings s where s.client_id=tf.client_id
       and (s.effective_from is null or s.effective_from<=coalesce(
      case when c.payload_json->>'effective_settings_date' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(c.payload_json->>'effective_settings_date','date')
           then (c.payload_json->>'effective_settings_date')::date end,
         (v_now at time zone 'Europe/London')::date))
      order by s.effective_from desc nulls last,s.updated_at desc nulls last,
        s.created_at desc nulls last,s.id desc
      limit 1
    ) cs on true
    cross join public.settings_defaults sd
    where sd.id=1
    group by m.chunk_id
  ),
  plans as materialized (
    select c.id chunk_id,coalesce(
      case when pg_input_is_valid(
        nullif(c.payload_json->>'planned_invoice_id',''),'uuid')
        then(c.payload_json->>'planned_invoice_id')::uuid end,
      case when c.payload_json->>'consolidation_mode' in ('BY_WEEK','ANY_WEEK') then (
        select i.id from public.invoices i
        where i.client_id=v.client_id and i.status='DRAFT' and i.type='INVOICE'
          and coalesce(i.header_snapshot_json#>>'{meta,consolidation_mode}','NONE')=c.payload_json->>'consolidation_mode'
          and coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false')=
              case when c.payload_json->>'invoice_stream'='SELF_BILL' then 'true' else 'false' end
          and (not private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
            or upper(coalesce(
              nullif(i.header_snapshot_json#>>'{meta,invoice_stream}',''),
              nullif(i.header_snapshot_json->>'invoice_stream',''),
              case when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))
                in('true','t','1','yes') then 'SELF_BILL' else 'NORMAL' end
            ))=upper(coalesce(c.payload_json->>'invoice_stream','NORMAL')))
          and (c.payload_json->>'consolidation_mode'='ANY_WEEK'
               or i.header_snapshot_json#>>'{meta,invoice_week_start}'=c.payload_json->>'target_invoice_week')
        order by i.created_at desc limit 1
      ) end,gen_random_uuid()) planned_invoice_id,
      v.source_count,v.expected_charge_ex_vat,v.expected_pay_ex_vat,v.client_id,
      v.settings_snapshot,encode(digest(v.settings_snapshot::text,'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join values_by_chunk v on v.chunk_id=c.id
  ),
  credit_plans as materialized (
    select c.id chunk_id,gen_random_uuid() planned_invoice_id,1 source_count,
      -i.subtotal_ex_vat expected_charge_ex_vat,-coalesce(sum(l.total_pay_ex_vat),0) expected_pay_ex_vat,
      i.client_id,jsonb_build_object('source_invoice_id',i.id,'source_invoice_no',i.invoice_no,
        'client_id',i.client_id,'credit_note',true) settings_snapshot,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text),'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    left join public.invoice_lines l on l.invoice_id=i.id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
    group by c.id,i.id
  ),
  all_plans as materialized (select * from plans union all select * from credit_plans),
  updated as (
    update public.invoice_operation_chunks c
    set phase='COMMIT',status='QUEUED',
      payload_json=c.payload_json||jsonb_build_object('plan',jsonb_build_object(
        'planned_invoice_id',p.planned_invoice_id,'intended_invoice_count',1,
        'source_count',p.source_count,'expected_pay_ex_vat',p.expected_pay_ex_vat,
        'expected_charge_ex_vat',p.expected_charge_ex_vat,'settings_snapshot',p.settings_snapshot,
        'settings_hash',p.settings_hash,'source_revision',c.payload_json->>'source_revision')),
      progress_json=jsonb_build_object('status_message','Generation plan ready','source_count',p.source_count),
      error_json=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=v_now
    from all_plans p where c.id=p.chunk_id
    returning c.id,c.status,c.phase,c.payload_json->'plan' plan
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'plan',plan)),'[]'::jsonb)
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- COMMIT: revalidate immediately, then headers, lines, locks, documents and audit set-wise.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='COMMIT'
  ),
  normal_chunks as materialized (
    select c.*,case when pg_input_is_valid(
        c.payload_json#>>'{plan,planned_invoice_id}','uuid')
      then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end planned_invoice_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select c.id chunk_id,c.operation_id,c.planned_invoice_id,c.payload_json,
      upper(coalesce(s.value->>'source_type','TIMESHEET')) source_type,
      case when pg_input_is_valid(s.value->>'source_id','uuid')
        then(s.value->>'source_id')::uuid end source_id,
      case when pg_input_is_valid(coalesce(
          s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
        then coalesce(s.value->>'related_timesheet_id',
          s.value->>'source_id')::uuid end timesheet_id,
      nullif(btrim(s.value->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(s.value->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(s.value->>'source_type','TIMESHEET')),
          coalesce(s.value->>'source_id',''),
          coalesce(s.value->>'related_timesheet_id',''),
          coalesce(s.value->>'segment_id','WHOLE'),
          coalesce(s.value->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key
    from normal_chunks c
    cross join lateral jsonb_array_elements(case
      when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        and jsonb_array_length(c.payload_json->'canonical_source_members')>0
      then c.payload_json->'canonical_source_members'
      else coalesce((
        select jsonb_agg(jsonb_build_object(
          'source_type','TIMESHEET','source_id',ids.value,
          'related_timesheet_id',ids.value) order by ids.ordinality)
        from jsonb_array_elements_text(coalesce(
          c.payload_json->'canonical_source_ids',
          c.payload_json->'source_ids','[]'::jsonb))
          with ordinality ids(value,ordinality)
      ),'[]'::jsonb) end) s(value)
    where pg_input_is_valid(coalesce(
      s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
  ),
  selected_segments as materialized (
    select c.id chunk_id,
      (m.value->>'source_id')::uuid timesheet_id,
      array_agg(distinct m.value->>'segment_id'
        order by m.value->>'segment_id')
        filter(where nullif(m.value->>'segment_id','') is not null) segment_ids
    from normal_chunks c
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        then c.payload_json->'canonical_source_members' else '[]'::jsonb end)
      m(value)
    where coalesce(m.value->>'source_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    group by c.id,(m.value->>'source_id')::uuid
  ),
  commit_reference_eval as materialized (
    select distinct on(r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.payload_json->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode')
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  commit_vat_eval as materialized (
    select distinct on(v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  commit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-commit:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_COMMIT',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select m.planned_invoice_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.source_member_key) planned_members
      from members m
      left join commit_vat_eval v
        on v.source_member_key=m.source_member_key
      group by m.planned_invoice_id
    ) scope
  ),
  commit_correction_eval as materialized (
    select r.*
    from commit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_still_valid as materialized (
    select m.chunk_id,
      bool_and(tf.processing_status='READY_FOR_INVOICE' and not tf.is_stale
        and (tf.locked_by_invoice_id is null
          or coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS')
        and ts.authorised_at_server is not null
        and not(upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null))
        and(not coalesce(pc.require_reference_to_invoice,false)
          or coalesce(ref.reference_ready,false))
        and coalesce(vat.valid,false)
        and coalesce(corr.valid,true)
        and not(coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED'))
        and not(coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null))
        and not((coalesce(tf.mileage_pay_ex_vat,0)<>0
              or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.travel_pay_ex_vat,0)<>0
              or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.accommodation_pay_ex_vat,0)<>0
              or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.expenses_pay_ex_vat,0)<>0
              or coalesce(tf.expenses_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.other_pay_ex_vat,0)<>0
              or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null))
        and not exists(
          select 1
          from public.timesheet_evidence e
          left join public.invoice_document_assets a
            on a.id=e.document_asset_id
          where e.timesheet_id=m.timesheet_id
            and(
              (upper(coalesce(e.kind,''))='MILEAGE'
                and(coalesce(tf.mileage_pay_ex_vat,0)<>0
                  or coalesce(tf.mileage_charge_ex_vat,0)<>0))
              or(upper(coalesce(e.kind,'')) in(
                  'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
                and(coalesce(tf.expenses_pay_ex_vat,0)<>0
                  or coalesce(tf.expenses_charge_ex_vat,0)<>0
                  or coalesce(tf.travel_pay_ex_vat,0)<>0
                  or coalesce(tf.travel_charge_ex_vat,0)<>0
                  or coalesce(tf.accommodation_pay_ex_vat,0)<>0
                  or coalesce(tf.accommodation_charge_ex_vat,0)<>0)))
            and(e.document_asset_id is null
              or a.status in('UNSUPPORTED','CORRUPT','MISSING',
                'FAILED','SUPERSEDED')))
        and not exists(
          select 1
          from public.invoice_lines l
          join public.invoices existing on existing.id=l.invoice_id
          where l.timesheet_id=m.timesheet_id
            and existing.id<>m.planned_invoice_id
            and existing.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS')
      ) still_valid
    from members m join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current and ts.revoked_at is null
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join commit_reference_eval ref
      on ref.source_member_key=m.source_member_key
    left join commit_vat_eval vat
      on vat.source_member_key=m.source_member_key
    left join commit_correction_eval corr
      on corr.scope_key=m.planned_invoice_id::text
    group by m.chunk_id
  ),
  commit_resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from normal_chunks c
  ),
  commit_resolver_results as materialized (
    select ri.chunk_id,r.source_revision_hash,r.blocker_code
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from commit_resolver_inputs ri),null,v_now) r
    join commit_resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  revision_check as materialized (
    select c.id chunk_id,r.source_revision_hash current_revision,
      s.still_valid and r.blocker_code is null still_valid
    from normal_chunks c
    join source_still_valid s on s.chunk_id=c.id
    join commit_resolver_results r on r.chunk_id=c.id
  ),
  rejected as (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code','SOURCE_CHANGED_BEFORE_COMMIT'),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from revision_check r
    where c.id=r.chunk_id and (not r.still_valid or r.current_revision<>c.payload_json->>'source_revision')
    returning c.id
  ),
  valid_chunks as materialized (
    select c.* from normal_chunks c join revision_check r on r.chunk_id=c.id
    where r.still_valid and r.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from rejected x where x.id=c.id)
  ),
  header_source as materialized (
    select vc.id chunk_id,vc.planned_invoice_id,(array_agg(tf.client_id order by tf.client_id))[1] client_id,
      max(cl.name) client_name,max(cl.invoice_address) client_invoice_address,
      max(cl.primary_invoice_email) primary_invoice_email,bool_and(cl.vat_chargeable) vat_chargeable,
      max(cl.payment_terms_days) payment_terms_days,
      max(sd.agency_name) agency_name,max(sd.agency_logo) agency_logo,
      max(sd.registered_address) registered_address,max(sd.company_reg_number) company_reg_number,
      max(sd.bank_name) bank_name,max(sd.bank_sort_code) bank_sort_code,
      max(sd.bank_account_number) bank_account_number,max(sd.vat_registration_number) vat_registration_number,
      count(*)::integer source_count
    from valid_chunks vc join members m on m.chunk_id=vc.id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.clients cl on cl.id=tf.client_id cross join public.settings_defaults sd
    where sd.id=1 group by vc.id,vc.planned_invoice_id
  ),
  source_rows_base as materialized (
    select m.chunk_id,m.planned_invoice_id,m.payload_json,
      m.source_member_key,m.source_type,m.source_id,m.segment_id,tf.*,ts.booking_id,
      ts.week_ending_date,ts.reference_number,ts.sheet_scope,ts.submission_mode,ts.day_references_json,
      ts.actual_schedule_json,coalesce(ts.contract_id,cw.contract_id) contract_id,
      coalesce(cd.display_name,'Candidate '||left(coalesce(tf.candidate_id::text,m.timesheet_id::text),8)) candidate_display,
      coalesce(ct.daily_calc_of_invoices,false) daily_calc_of_invoices,
      coalesce(ct.bucket_labels_json,
        jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH'))
        bucket_labels_json,
      ct.role contract_role,ct.display_site contract_display_site,
      ct.ward_hint contract_ward_hint,
      null::numeric ordinary_vat_rate,
      case when ts.sheet_scope::text='WEEKLY'
          and ts.submission_mode::text='MANUAL'
          and jsonb_typeof(ts.actual_schedule_json)='array'
        then coalesce((
          select jsonb_agg(jsonb_build_object(
            'date',e.value->>'date','start',e.value->>'start',
            'end',e.value->>'end','start_utc',e.value->>'start_utc',
            'end_utc',e.value->>'end_utc','ref_num',e.value->>'ref_num')
            order by e.ordinality)
          from jsonb_array_elements(ts.actual_schedule_json)
            with ordinality e(value,ordinality)
          where nullif(btrim(e.value->>'start'),'') is not null
            and nullif(btrim(e.value->>'end'),'') is not null
        ),'[]'::jsonb)
        else '[]'::jsonb end schedule_refs
    from members m join valid_chunks vc on vc.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    left join lateral (
      select w.contract_id
      from public.contract_weeks w
      where w.timesheet_id=m.timesheet_id
      order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc
      limit 1
    ) cw on true
    left join public.contracts ct on ct.id=coalesce(ts.contract_id,cw.contract_id)
    left join public.candidates cd on cd.id=tf.candidate_id
  ),
  vat_policy as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',s.source_member_key,
        'source_type',s.source_type,'source_id',s.source_id,
        'timesheet_id',s.timesheet_id,'segment_id',s.segment_id,
        'ordinary_rate',s.ordinary_vat_rate,
        'effective_date',coalesce(
          case when s.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                s.payload_json->>'effective_settings_date','date')
            then(s.payload_json->>'effective_settings_date')::date end,
          s.week_ending_date::date))
        order by s.chunk_id,s.timesheet_id)
      from source_rows_base s
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  source_rows as materialized (
    select s.*,v.vat_rate
    from source_rows_base s
    join vat_policy v on v.source_member_key=s.source_member_key and v.valid
  ),
  source_timesheet_ancestry(
    planned_invoice_id,
    root_timesheet_id,
    source_timesheet_id,
    ancestry_path,
    ancestry_depth
  ) as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id,s.timesheet_id,
      array[s.timesheet_id]::uuid[],0
    from source_rows s
    union all
    select a.planned_invoice_id,a.root_timesheet_id,t.parent_timesheet_id,
      a.ancestry_path||t.parent_timesheet_id,a.ancestry_depth+1
    from source_timesheet_ancestry a
    join public.timesheets t
      on t.timesheet_id=a.source_timesheet_id
     and t.is_current
    where t.parent_timesheet_id is not null
      and not(t.parent_timesheet_id=any(a.ancestry_path))
      and a.ancestry_depth<32
  ),
  adjustment_segment_refs as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id root_timesheet_id,
      coalesce(
        (s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,
        true
      ) healthroster_attach_allowed,
      nullif(btrim(seg.value->>'ref_num'),'') ref_num,
      case when pg_input_is_valid(
          seg.value->>'start_utc','timestamp with time zone')
        then(seg.value->>'start_utc')::timestamptz end start_utc,
      case when pg_input_is_valid(
          seg.value->>'end_utc','timestamp with time zone')
        then(seg.value->>'end_utc')::timestamptz end end_utc,
      lower(coalesce(seg.value->>'is_reversal','false')) in(
        'true','t','1','yes') is_reversal
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      seg(value)
    where s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
  ),
  segment_lock_targets_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'invoice_id',s.planned_invoice_id,
      'timesheet_id',s.timesheet_id,
      'segment_ids',to_jsonb(p.segment_ids),
      'expected_financial_revision',encode(digest(jsonb_build_object(
        'financial_id',s.id,
        'timesheet_version',s.timesheet_version,
        'updated_at',s.updated_at,
        'basis',s.basis,
        'invoice_breakdown_json',s.invoice_breakdown_json
      )::text,'sha256'),'hex'))
      order by s.planned_invoice_id,s.timesheet_id),'[]'::jsonb) targets
    from source_rows s
    join selected_segments p
      on p.chunk_id=s.chunk_id and p.timesheet_id=s.timesheet_id
    where cardinality(coalesce(p.segment_ids,array[]::text[]))>0
      and exists(
        select 1
        from public.invoices existing_header
        where existing_header.id=s.planned_invoice_id)
  ),
  segment_lock_authority_pre as materialized (
    select r.*
    from segment_lock_targets_pre t
    cross join lateral private._invoice_segment_lock_batch(t.targets,v_now) r
  ),
  segment_lock_failures_pre as materialized (
    select * from segment_lock_authority_pre where not success
  ),
  segment_entries as materialized (
    select s.*,seg.ordinality,
      coalesce(nullif(seg.value->>'segment_id',''),
        left(encode(digest(seg.value::text,'sha256'),'hex'),24)) segment_id,
      case when left(coalesce(seg.value->>'date',''),10)
        ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        then left(seg.value->>'date',10) end work_date,
      case when coalesce(seg.value->>'hours_day','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_day')::numeric
        else 0 end segment_hours_day,
      case when coalesce(seg.value->>'hours_night','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_night')::numeric
        else 0 end segment_hours_night,
      case when coalesce(seg.value->>'hours_sat','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sat')::numeric
        else 0 end segment_hours_sat,
      case when coalesce(seg.value->>'hours_sun','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sun')::numeric
        else 0 end segment_hours_sun,
      case when coalesce(seg.value->>'hours_bh','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_bh')::numeric
        else 0 end segment_hours_bh,
      case
        when coalesce(seg.value->>'pay_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_amount')::numeric
        when coalesce(seg.value->>'pay_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_ex_vat')::numeric
        else 0 end segment_pay_ex,
      case
        when coalesce(seg.value->>'charge_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_amount')::numeric
        when coalesce(seg.value->>'charge_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_ex_vat')::numeric
        else 0 end segment_charge_ex
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      with ordinality seg(value,ordinality)
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and nullif(seg.value->>'invoice_locked_invoice_id','') is null
      and exists(
        select 1 from selected_segments picked
        where picked.chunk_id=s.chunk_id
          and picked.timesheet_id=s.timesheet_id
          and coalesce(nullif(seg.value->>'segment_id',''),
            left(encode(digest(seg.value::text,'sha256'),'hex'),24))
            =any(coalesce(picked.segment_ids,array[]::text[])))
  ),
  segment_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where s.daily_calc_of_invoices and s.work_date is not null
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date
  ),
  segment_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where not s.daily_calc_of_invoices
       or not exists(select 1 from segment_entries d
         where d.chunk_id=s.chunk_id and d.timesheet_id=s.timesheet_id
           and d.daily_calc_of_invoices and d.work_date is not null)
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date
  ),
  nonsegment_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      coalesce(s.hours_day,0) h_day,coalesce(s.hours_night,0) h_night,coalesce(s.hours_sat,0) h_sat,
      coalesce(s.hours_sun,0) h_sun,coalesce(s.hours_bh,0) h_bh,
      round(coalesce(s.total_pay_ex_vat,0)-coalesce(s.additional_pay_ex_vat,0)
        -coalesce(s.expenses_pay_ex_vat,0)-coalesce(s.mileage_pay_ex_vat,0),2) pay_ex,
      round(coalesce(s.total_charge_ex_vat,0)-coalesce(s.additional_charge_ex_vat,0)
        -coalesce(s.expenses_charge_ex_vat,0)-coalesce(s.mileage_charge_ex_vat,0),2) charge_ex,
      s.vat_rate,s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,
      s.charge_bh,s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
       or jsonb_array_length(case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
                                  then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ),
  additional_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,upper(a.key) code,
      left(d.key,10) work_date,
      case when pg_input_is_valid(d.value,'numeric')
        then d.value::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'pay_rate','numeric')
          then(a.value->>'pay_rate')::numeric else 0 end),2) pay_ex,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'charge_rate','numeric')
          then(a.value->>'charge_rate')::numeric else 0 end),2) charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    cross join lateral jsonb_each_text(
      case when jsonb_typeof(a.value->'days')='object'
        then a.value->'days' else '{}'::jsonb end) d
    where s.daily_calc_of_invoices
      and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      and exists(select 1 from segment_entries se
        where se.chunk_id=s.chunk_id and se.timesheet_id=s.timesheet_id
          and se.work_date is not null)
  ),
  additional_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      upper(a.key) code,
      case when pg_input_is_valid(a.value->>'unit_count','numeric')
        then(a.value->>'unit_count')::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
        then(a.value->>'pay_ex_vat')::numeric else 0 end pay_ex,
      case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
        then(a.value->>'charge_ex_vat')::numeric else 0 end charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    where jsonb_typeof(a.value)='object'
      and ((case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
              then(a.value->>'pay_ex_vat')::numeric else 0 end)<>0
        or (case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
              then(a.value->>'charge_ex_vat')::numeric else 0 end)<>0)
      and not(s.daily_calc_of_invoices
        and jsonb_typeof(a.value->'days')='object'
        and exists(select 1 from jsonb_each_text(
          case when jsonb_typeof(a.value->'days')='object'
            then a.value->'days' else '{}'::jsonb end) d
          where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
  ),
  expense_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      e.code,e.pay_ex,e.charge_ex,s.vat_rate,s.expenses_description,
      s.expenses_evidence_r2_key,s.expenses_evidence_manifest,
      s.mileage_units,s.mileage_pay_rate,s.mileage_charge_rate,
      s.mileage_evidence_r2_key,s.mileage_evidence_manifest,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral (
      values
       ('TRAVEL',coalesce(s.travel_pay_ex_vat,0),coalesce(s.travel_charge_ex_vat,0)),
       ('ACCOMMODATION',coalesce(s.accommodation_pay_ex_vat,0),coalesce(s.accommodation_charge_ex_vat,0)),
       ('OTHER',coalesce(s.other_pay_ex_vat,0),coalesce(s.other_charge_ex_vat,0)),
       ('EXPENSES_FALLBACK',
          case when coalesce(s.travel_pay_ex_vat,0)+coalesce(s.accommodation_pay_ex_vat,0)+coalesce(s.other_pay_ex_vat,0)=0 then coalesce(s.expenses_pay_ex_vat,0) else 0 end,
          case when coalesce(s.travel_charge_ex_vat,0)+coalesce(s.accommodation_charge_ex_vat,0)+coalesce(s.other_charge_ex_vat,0)=0 then coalesce(s.expenses_charge_ex_vat,0) else 0 end),
       ('MILEAGE',coalesce(s.mileage_pay_ex_vat,0),coalesce(s.mileage_charge_ex_vat,0))
    ) e(code,pay_ex,charge_ex)
    where e.pay_ex<>0 or e.charge_ex<>0
  ),
  line_union as materialized (
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||work_date description,h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric pay_day,null::numeric pay_night,null::numeric pay_sat,
      null::numeric pay_sun,null::numeric pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_DAILY' line_type,
      'TS:'||timesheet_id||':HOURS:'||work_date source_key,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json) detail
    from segment_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from segment_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from nonsegment_lines
    where pay_ex<>0 or charge_ex<>0 or h_day+h_night+h_sat+h_sun+h_bh<>0
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||work_date||' - '||
        units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE_DAILY',
      'TS:'||timesheet_id||':ADD:'||code||':'||work_date,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE',
      'TS:'||timesheet_id||':ADD:'||code||':WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      case when code='MILEAGE' then 'Mileage - '||coalesce(mileage_units,0)||
          ' miles (W/E '||week_ending_date||')'
        else initcap(replace(code,'_',' '))||' (W/E '||week_ending_date||')' end,
      0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,
      case when code='MILEAGE' then 'MILEAGE'
        when code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
        else 'EXPENSE_'||code end,
      case when code='MILEAGE' then 'TS:'||timesheet_id||':MILEAGE'
        when code='EXPENSES_FALLBACK' then 'TS:'||timesheet_id||':EXP:TOTAL'
        else 'TS:'||timesheet_id||':EXP:'||code end,
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'expense',case when code='MILEAGE' then jsonb_build_object(
          'category','MILEAGE','mileage_units',mileage_units,
          'pay_rate',mileage_pay_rate,'charge_rate',mileage_charge_rate,
          'evidence_r2_key',mileage_evidence_r2_key,
          'evidence_manifest',mileage_evidence_manifest)
        else jsonb_build_object('category',code,'note',expenses_description,
          'evidence_r2_key',expenses_evidence_r2_key,
          'evidence_manifest',expenses_evidence_manifest) end)
    from expense_lines
  ),
  correction_scopes_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-prewrite:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_PREWRITE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select l.planned_invoice_id,min(vc.payload_json::text)::jsonb payload_json,
        jsonb_agg(distinct jsonb_build_object(
          'timesheet_id',l.timesheet_id,
          'vat_rate_pct',l.vat_rate))
          filter(where l.timesheet_id is not null) planned_members
      from line_union l
      join valid_chunks vc on vc.id=l.chunk_id
      group by l.planned_invoice_id
    ) scope
  ),
  correction_validation_pre as materialized (
    select r.*
    from correction_scopes_pre s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),
  correction_failures_pre as materialized (
    select scope_key,blocker_code,detail_json detail
    from correction_validation_pre
    where not valid
  ),  write_eligible_chunks as materialized (
    select vc.*
    from valid_chunks vc
    where not exists(
      select 1 from correction_failures_pre f
      where f.scope_key=vc.planned_invoice_id::text)
  ),
  line_totals as materialized (
    select l.planned_invoice_id,
      round(sum(round(l.charge_ex,2)),2) subtotal_ex_vat,
      round(sum(round(l.charge_ex*l.vat_rate/100,2)),2) vat_amount,
      round(sum(round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)),2) total_inc_vat
    from line_union l
    join write_eligible_chunks w on w.id=l.chunk_id
    group by l.planned_invoice_id
  ),
  existing_target_headers as materialized (
    select vc.id chunk_id,i.id invoice_id
    from write_eligible_chunks vc
    join header_source h on h.chunk_id=vc.id
    join public.invoices i on i.id=vc.planned_invoice_id
      and i.client_id=h.client_id and i.type='INVOICE' and i.status='DRAFT'
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=vc.planned_invoice_id)
  ),
  inserted_headers as (
    insert into public.invoices(id,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select h.planned_invoice_id,h.client_id,'DRAFT',v_now,
      t.subtotal_ex_vat,t.vat_amount,t.total_inc_vat,
      jsonb_build_object('client_id',h.client_id,'client_name',h.client_name)
      ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then jsonb_build_object('invoice_stream',upper(coalesce(vc.payload_json->>'invoice_stream','NORMAL')))
        else '{}'::jsonb end
      ||jsonb_build_object(
        'client_invoice_address',h.client_invoice_address,'client_primary_invoice_email',h.primary_invoice_email,
        'agency_name',h.agency_name,'agency_logo',h.agency_logo,'registered_address',h.registered_address,
        'company_reg_number',h.company_reg_number,'company_registration_number',h.company_reg_number,
        'vat_chargeable',h.vat_chargeable,'payment_terms_days',h.payment_terms_days,
        'issued_at_utc',null,'due_at_utc',null,
        'totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,
          'vat_amount',t.vat_amount,'total_inc_vat',t.total_inc_vat),
        'bank',jsonb_build_object('name',h.bank_name,'sort_code',h.bank_sort_code,'account_number',h.bank_account_number),
        'vat_registration_number',h.vat_registration_number,
        'meta',jsonb_build_object('source','INVOICE_OPERATION_QUEUE',
          'invoice_week_start',vc.payload_json->>'target_invoice_week',
          'consolidation_mode',vc.payload_json->>'consolidation_mode',
          'self_bill',vc.payload_json->>'invoice_stream'='SELF_BILL','timesheet_count',h.source_count)
          ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
            then jsonb_build_object('invoice_stream',upper(coalesce(vc.payload_json->>'invoice_stream','NORMAL')))
            else '{}'::jsonb end,
        'attach_policy',vc.payload_json#>'{plan,settings_snapshot,attach_policy}'),
      1,'STALE',v_now,v_now
    from header_source h join write_eligible_chunks vc on vc.id=h.chunk_id
    join line_totals t on t.planned_invoice_id=h.planned_invoice_id
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=h.planned_invoice_id)
    on conflict(id) do nothing returning id
  ),
  target_headers as materialized (
    select e.chunk_id,e.invoice_id
    from existing_target_headers e
    where not exists(
      select 1
      from inserted_headers h
      where h.id=e.invoice_id)
  ),
  deferred_new_headers as (
    update public.invoice_operation_chunks c
    set status='QUEUED',
      phase='COMMIT',
      progress_json=coalesce(c.progress_json,'{}'::jsonb)
        ||jsonb_build_object('status_message',
          'Invoice header created; applying authoritative source ownership'),
      error_json=null,
      lease_owner=null,
      lease_token=null,
      lease_expires_at_utc=null,
      updated_at_utc=v_now
    from inserted_headers h
    join write_eligible_chunks vc on vc.planned_invoice_id=h.id
    where c.id=vc.id
    returning c.id
  ),
  inserted_lines as (
    insert into public.invoice_lines(
      invoice_id,timesheet_id,booking_id,description,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,
      paper_ts_r2_key,meta_json,source_key
    )
    select l.planned_invoice_id,l.timesheet_id,l.booking_id,l.description,
      round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),l.vat_rate,
      round(l.charge_ex*l.vat_rate/100,2),round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2),
      null,jsonb_build_object('line_type',l.line_type,'timesheet_id',l.timesheet_id,
        'candidate_display',l.description,'week_ending_date',
        (select s.week_ending_date from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'schedule_references',
        (select s.schedule_refs from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
          'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
          'vat_rate_pct',l.vat_rate,'vat_amount',round(l.charge_ex*l.vat_rate/100,2),
          'total_inc_vat',round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)))||l.detail,l.source_key
    from line_union l join target_headers h on h.invoice_id=l.planned_invoice_id
    on conflict(invoice_id,source_key) do nothing
    returning invoice_id,timesheet_id,total_charge_ex_vat,vat_amount,total_inc_vat
  ),
  all_target_lines as materialized (
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from public.invoice_lines l
    where l.invoice_id in(select invoice_id from target_headers)
    union all
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from inserted_lines l
  ),
  all_line_totals as materialized (
    select l.invoice_id,count(*)::integer line_count,
      round(sum(l.total_charge_ex_vat),2) subtotal_ex_vat,
      round(sum(l.vat_amount),2) vat_amount,
      round(sum(l.total_inc_vat),2) total_inc_vat
    from all_target_lines l
    group by l.invoice_id
  ),
  target_header_streams as materialized (
    select h.invoice_id,
      max(upper(coalesce(c.payload_json->>'invoice_stream','NORMAL'))) invoice_stream
    from target_headers h
    join public.invoice_operation_chunks c on c.id=h.chunk_id
    group by h.invoice_id
  ),
  updated_header_totals as (
    update public.invoices i
    set subtotal_ex_vat=t.subtotal_ex_vat,vat_amount=t.vat_amount,
      total_inc_vat=t.total_inc_vat,document_state='STALE',
      header_snapshot_json=coalesce(i.header_snapshot_json,'{}'::jsonb)
        ||jsonb_build_object('totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,'vat_amount',t.vat_amount,
          'total_inc_vat',t.total_inc_vat))
        ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
          then jsonb_build_object(
            'invoice_stream',s.invoice_stream,
            'meta',coalesce(i.header_snapshot_json->'meta','{}'::jsonb)
              ||jsonb_build_object('invoice_stream',s.invoice_stream))
          else '{}'::jsonb end,
      updated_at=v_now
    from all_line_totals t
    join target_header_streams s on s.invoice_id=t.invoice_id
    where i.id=t.invoice_id
    returning i.id
  ),
  segment_lock_targets as materialized (
    select targets from segment_lock_targets_pre
  ),
  segment_lock_authority as materialized (
    select * from segment_lock_authority_pre
  ),
  segment_lock_failures as materialized (
    select * from segment_lock_authority where not success
  ),
  whole_lock as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=vc.planned_invoice_id,locked_at_utc=v_now,updated_at=v_now
    from members m join write_eligible_chunks vc on vc.id=m.chunk_id
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    where tf.timesheet_id=m.timesheet_id and tf.is_current
      and (coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        or not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                      where nullif(e->>'invoice_locked_invoice_id','') is null))
    returning tf.timesheet_id
  ),
  week_lock as (
    update public.contract_weeks cw set status='INVOICED',updated_at=v_now
    where cw.timesheet_id in(
      select m.timesheet_id
      from members m
      join target_headers h on h.chunk_id=m.chunk_id)
      and exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=cw.timesheet_id
        and tf.is_current and (tf.locked_by_invoice_id is not null or
          not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                     where nullif(e->>'invoice_locked_invoice_id','') is null)))
    returning cw.id
  ),
  nhsp_shift_inclusion as (
    update public.nhsp_shifts ns
    set invoice_status='INCLUDED',
      invoice_id=h.invoice_id,
      updated_at=v_now
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    where ns.timesheet_id=s.timesheet_id
      and ns.invoice_status='PENDING'
      and ns.invoice_id is null
      and ns.cancelled_at_utc is null
      and exists(
        select 1
        from jsonb_array_elements(
          case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
            then s.invoice_breakdown_json->'segments'
            else '[]'::jsonb end) segment(value)
        where coalesce(
            nullif(segment.value->>'nhsp_shift_id',''),
            nullif(segment.value->>'shift_id',''))=ns.id::text)
    returning ns.id
  ),
  hr_sources as (
    insert into public.invoice_hr_source_rows(invoice_id,source_system,import_id,header_columns,rows_json,header_rows)
    select distinct h.invoice_id,
      case when tf.basis::text in('NHSP','NHSP_ADJUSTMENT')
        then 'NHSP' else 'HEALTHROSTER' end,
      tf.nhsp_import_id,'[]'::jsonb,
      case when jsonb_typeof(tf.external_source_rows_json)='array' then tf.external_source_rows_json else '[]'::jsonb end,
      '[]'::jsonb
    from members m
    join target_headers h on h.chunk_id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    where tf.nhsp_import_id is not null
    on conflict(invoice_id,source_system,import_id) do update set rows_json=excluded.rows_json
    returning invoice_id
  ),
  source_segments as materialized (
    select distinct h.invoice_id planned_invoice_id,
      coalesce(
        case when coalesce(x.value->>'nhsp_shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'nhsp_shift_id')::uuid end,
        case when coalesce(x.value->>'shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'shift_id')::uuid end,
        case when substr(coalesce(x.value->>'segment_id',''),6)~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substr(x.value->>'segment_id',6)::uuid end) shift_id,
      case
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
         and (
           lower(coalesce(x.value->>'is_reversal','false')) in(
             'true','t','1','yes')
           or coalesce(s.total_hours,0)<0
         ) then 'REVERSAL'
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
          then 'CORRECTED_HOURS'
        else 'SOURCE'
      end evidence_role_key
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end) x(value)
    where coalesce(
        nullif(x.value->>'nhsp_shift_id',''),
        nullif(x.value->>'shift_id',''),
        case when left(x.value->>'segment_id',5)='nhsp:'
          then substr(x.value->>'segment_id',6) end)~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and (
        upper(coalesce(x.value->>'source_system',''))='NHSP'
        or (upper(coalesce(x.value->>'source_system',''))='HEALTHROSTER'
          and coalesce((s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,true)))
    union
    select distinct r.planned_invoice_id,n.id shift_id,
      case when r.is_reversal then 'REVERSAL'
        else 'CORRECTED_HOURS' end evidence_role_key
    from adjustment_segment_refs r
    join source_timesheet_ancestry a
      on a.planned_invoice_id=r.planned_invoice_id
     and a.root_timesheet_id=r.root_timesheet_id
     and a.ancestry_depth>0
    join public.nhsp_shifts n
      on n.timesheet_id=a.source_timesheet_id
     and n.latest_import_id is not null
     and n.external_row_key is not null
     and (
       upper(coalesce(n.source_system::text,''))='NHSP'
       or (
         upper(coalesce(n.source_system::text,''))='HEALTHROSTER'
         and r.healthroster_attach_allowed
       )
     )
     and (
       (r.ref_num is not null
         and btrim(coalesce(n.ref_num,''))=r.ref_num)
       or (
         r.ref_num is null
         and r.start_utc is not null
         and r.end_utc is not null
         and n.start_utc=r.start_utc
         and n.end_utc=r.end_utc
       )
     )
  ),
  source_import_rows as materialized (
    select distinct s.planned_invoice_id,
      upper(coalesce(n.source_system::text,'UNKNOWN')) source_system,
      n.latest_import_id import_id,n.external_row_key,s.evidence_role_key
    from source_segments s
    join public.nhsp_shifts n on n.id=s.shift_id
    where n.latest_import_id is not null
      and n.external_row_key is not null
  ),
  source_imports as materialized (
    select s.planned_invoice_id,s.source_system,s.import_id,
      jsonb_agg(jsonb_build_object(
        'external_row_key',s.external_row_key,
        'evidence_role_key',s.evidence_role_key)
        order by s.external_row_key,s.evidence_role_key) row_occurrences
    from source_import_rows s
    group by s.planned_invoice_id,s.source_system,s.import_id
  ),
  authoritative_hr_sources as (
    insert into public.invoice_hr_source_rows(
      invoice_id,source_system,import_id,header_columns,rows_json)
    select g.planned_invoice_id,g.source_system,g.import_id,
      case when jsonb_typeof(i.parse_summary_json->'header_columns')='array'
        then i.parse_summary_json->'header_columns' else '[]'::jsonb end,
      coalesce((select jsonb_agg(
          r.payload_json
            ||jsonb_build_object(
              'evidence_role',case occurrence.value->>'evidence_role_key'
                when 'REVERSAL' then case when g.source_system='NHSP'
                  then 'NHSP Reversal' else 'HealthRoster Reversal' end
                when 'CORRECTED_HOURS' then case when g.source_system='NHSP'
                  then 'NHSP Corrected Hours' else 'HealthRoster Corrected Hours' end
                else case when g.source_system='NHSP'
                  then 'NHSP Shift' else 'HealthRoster Shift' end
              end)
            ||case when occurrence.value->>'evidence_role_key'='REVERSAL'
              then jsonb_build_object('reversal_state','REVERSED')
              else '{}'::jsonb end
          order by r.id,occurrence.value->>'evidence_role_key')
        from jsonb_array_elements(g.row_occurrences) occurrence(value)
        join public.hr_rows r
          on r.import_id=g.import_id
         and r.external_row_key=occurrence.value->>'external_row_key'),
        '[]'::jsonb)
    from source_imports g join public.hr_imports i on i.id=g.import_id
    on conflict(invoice_id,source_system,import_id) do update
      set header_columns=excluded.header_columns,rows_json=excluded.rows_json
    returning invoice_id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoices',vc.planned_invoice_id::text,
      case when exists(select 1 from inserted_headers h
        where h.id=vc.planned_invoice_id)
        then 'INVOICE_CREATED' else 'INVOICE_DRAFT_APPENDED' end,
      jsonb_build_object('invoice_id',vc.planned_invoice_id,
        'source_ids',coalesce(vc.payload_json->'canonical_source_ids',
          vc.payload_json->'source_ids','[]'::jsonb),
        'source_revision',vc.payload_json->>'source_revision',
        'operation_id',vc.operation_id),'INVOICE_OPERATION_QUEUE'
    from write_eligible_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    join public.invoice_operations o on o.id=vc.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  correction_failures as materialized (
    select scope_key::uuid invoice_id,blocker_code,detail
    from correction_failures_pre
    where scope_key~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  update public.invoice_operation_chunks c
    set status=case when exists(select 1 from all_line_totals l
                               where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      phase=case when exists(select 1 from all_line_totals l
                            where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(vc.planned_invoice_id),
        'source_revision',vc.payload_json->>'source_revision'),
      error_json=case
        when not exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','NO_INVOICE_LINES_CREATED')
        when exists(select 1 from segment_lock_failures sf
          where sf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','SEGMENT_LOCK_FAILED','detail',(
            select jsonb_agg(to_jsonb(sf))
            from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id))
        when exists(select 1 from correction_failures cf
          where cf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code',(
            select cf.blocker_code from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id))
        else null end,
      completed_at_utc=case
        when exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then v_now else null end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from valid_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    cross join (select count(*) cached_count from authoritative_hr_sources) source_cache_application
    where c.id=vc.id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='COMMIT'
    and coalesce(c.payload_json->>'command_type','')<>'GENERATE_CREDIT_NOTE';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note COMMIT: exact negative line clone and source unlock; document creation stays asynchronous.
  execute $q$
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements($1) x where x->>'phase'='COMMIT'
  ),
  credit_revisions as materialized (
    select c.*,i.id source_invoice_id,(c.payload_json#>>'{plan,planned_invoice_id}')::uuid credit_note_id
      ,encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex') current_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
      and i.type='INVOICE' and i.status in ('ISSUED','PAID')
  ),
  credit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','credit-source:'||c.source_invoice_id::text,
      'scope_key',c.source_invoice_id::text,
      'invoice_id',c.source_invoice_id,
      'validation_purpose','CREDIT_SOURCE')
      order by c.source_invoice_id),'[]'::jsonb) scopes
    from(select distinct source_invoice_id from credit_revisions) c
  ),
  credit_correction_failures as materialized (
    select r.invoice_id source_invoice_id,r.blocker_code,r.detail_json
    from credit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,($2 at time zone 'Europe/London')::date) r
    where not r.valid
  ),
  credit_rejected as (
    update public.invoice_operation_chunks q
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code',case
        when c.current_revision<>c.payload_json->>'source_revision'
          then 'CREDIT_SOURCE_CHANGED_BEFORE_COMMIT'
        else coalesce((select f.blocker_code
          from credit_correction_failures f
          where f.source_invoice_id=c.source_invoice_id
          order by f.blocker_code limit 1),'CREDIT_CORRECTION_VALIDATION_FAILED')
        end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=$2
    from credit_revisions c
    where q.id=c.id and(
      c.current_revision<>c.payload_json->>'source_revision'
      or exists(select 1 from credit_correction_failures f
        where f.source_invoice_id=c.source_invoice_id))
    returning q.id
  ),
  credits as materialized (
    select c.* from credit_revisions c
    where c.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from credit_rejected r where r.id=c.id)
  ),
  inserted_credit as (
    insert into public.invoices(id,type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      original_invoice_id,notes,header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select c.credit_note_id,'CREDIT_NOTE',i.client_id,'DRAFT',$2,
      -i.subtotal_ex_vat,-i.vat_amount,-i.total_inc_vat,i.id,
      c.payload_json->>'credit_reason',
      i.header_snapshot_json||jsonb_build_object(
        'credit_source_invoice_id',i.id,
        'credit_reason',c.payload_json->>'credit_reason'),1,'STALE',$2,$2
    from credits c join public.invoices i on i.id=c.source_invoice_id
    on conflict(id) do nothing returning id
  ),
  cloned_lines as (
    insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,
      hours_day,hours_night,hours_sat,hours_sun,hours_bh,pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,total_pay_ex_vat,total_charge_ex_vat,
      margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,paper_ts_r2_key,meta_json,source_key)
    select c.credit_note_id,l.timesheet_id,l.booking_id,
      'CREDIT NOTE – '||coalesce(l.description,''),
      l.hours_day,l.hours_night,l.hours_sat,l.hours_sun,l.hours_bh,
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      -l.total_pay_ex_vat,-l.total_charge_ex_vat,-l.margin_ex_vat,l.vat_rate_pct,
      -l.vat_amount,-l.total_inc_vat,l.paper_ts_r2_key,
      coalesce(l.meta_json,'{}'::jsonb)||jsonb_build_object(
        'credit_note',true,'original_invoice_id',c.source_invoice_id,
        'original_invoice_line_id',l.id,'credit_of_line_id',l.id,'line_type',
        'CREDIT_'||coalesce(l.meta_json->>'line_type','LINE')),
      'CN:'||c.credit_note_id||':LINE:'||l.id
    from credits c join public.invoice_lines l on l.invoice_id=c.source_invoice_id
    on conflict(invoice_id,source_key) do nothing returning invoice_id
  ),
  source_mark as (
    update public.invoices i set credit_note_created_at_utc=$2,updated_at=$2
    where i.id in(select source_invoice_id from credits) returning i.id
  ),
  unlocks as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=null,locked_at_utc=null,
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.locked_by_invoice_id=c.source_invoice_id and tf.is_current returning tf.timesheet_id
  ),
  segment_unlocks as (
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(tf.invoice_breakdown_json,'{segments}',
      (select jsonb_agg(case
        when e.value->>'invoice_locked_invoice_id'=c.source_invoice_id::text
          then (e.value-'invoice_locked_invoice_id'-'invoice_locked_at_utc')
        else e.value end order by e.ordinality)
       from jsonb_array_elements(tf.invoice_breakdown_json->'segments')
         with ordinality e(value,ordinality)),true),
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.is_current and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
      and exists(select 1 from jsonb_array_elements(tf.invoice_breakdown_json->'segments') e
        where e->>'invoice_locked_invoice_id'=c.source_invoice_id::text)
    returning tf.timesheet_id
  ),
  recompute_outbox as (
    insert into public.ts_financials_outbox(
      timesheet_id,reason,attempt_count,next_attempt_at,last_error,created_at)
    select distinct u.timesheet_id,'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,$2,null,$2
    from (
      select timesheet_id from unlocks
      union all select timesheet_id from segment_unlocks
    ) u
    on conflict on constraint uq_tsfin_outbox do nothing
    returning timesheet_id
  ),
  credit_audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,
      actor_role_at_time,object_type,object_id_text,action,after_json,reason)
    select $2,o.actor_user_id,u.display_name,u.role,'invoices',
      c.credit_note_id::text,'CREDIT_NOTE_CREATED',
      jsonb_build_object('credit_note_id',c.credit_note_id,
        'original_invoice_id',c.source_invoice_id,
        'credit_reason',c.payload_json->>'credit_reason',
        'command_token',c.payload_json->>'command_token',
        'subtotal_ex_vat',-i.subtotal_ex_vat,'vat_amount',-i.vat_amount,
        'total_inc_vat',-i.total_inc_vat,
        'financial_recompute_enqueued',true),
      'INVOICE_OPERATION_QUEUE'
    from credits c join public.invoices i on i.id=c.source_invoice_id
    join public.invoice_operations o on o.id=c.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  completed as (
    update public.invoice_operation_chunks q
    set status='QUEUED',
      phase='QUEUE_DOCUMENT',
      error_json=null,
      completed_at_utc=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=$2,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(c.credit_note_id),
        'credit_note_id',c.credit_note_id,'source_invoice_id',c.source_invoice_id)
    from credits c
    cross join (select count(*) outbox_count from recompute_outbox) outbox_application
    cross join (select count(*) audit_count from credit_audits) audit_application
    where q.id=c.id
    returning q.id,q.status,q.phase,q.result_json,q.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]'::jsonb)
  from completed
  $q$
  into v_part using p_claims,v_now;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Document work is queued in a separate SQL statement so source-invalidation
  -- statement triggers cannot supersede the freshly-created document operation.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='QUEUE_DOCUMENT'
  ),
  queued_sources as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,
      (c.payload_json#>>'{plan,planned_invoice_id}')::uuid planned_invoice_id,
      c.payload_json->>'source_revision' source_revision,
      c.payload_json->>'command_type' command_type,
      c.payload_json->>'command_token' command_token,
      c.payload_json->>'credit_reason' credit_reason,
      i.document_revision::text document_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i
      on i.id=(c.payload_json#>>'{plan,planned_invoice_id}')::uuid
  ),
  existing_doc_versions as materialized (
    select distinct on(q.chunk_id) q.chunk_id,v.id document_version_id,
      v.operation_id,v.status
    from queued_sources q
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=q.planned_invoice_id
     and v.purpose='DRAFT_PREVIEW'
     and v.source_revision=q.document_revision
     and v.template_version='invoice-professional-v2'
     and v.status in(
       'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
       'VERIFYING','READY')
    where q.command_type<>'GENERATE_CREDIT_NOTE'
    order by q.chunk_id,case when v.status='READY' then 0 else 1 end,
      v.created_at_utc desc,v.id desc
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'BUILD_DOCUMENT','INVOICE',q.planned_invoice_id,o.actor_user_id,
      encode(digest('DRAFT_PREVIEW|'||q.planned_invoice_id||'|'||q.document_revision||
        '|invoice-professional-v2','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',550,q.document_revision,'invoice-professional-v2',
      jsonb_build_object('invoice_id',q.planned_invoice_id,'purpose','DRAFT_PREVIEW'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type<>'GENERATE_CREDIT_NOTE'
      and not exists(
        select 1 from existing_doc_versions e where e.chunk_id=q.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),updated_at_utc=v_now
    returning *
  ),
  selected_doc_ops as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision source_revision,
      d.id operation_id,d.control_version,null::uuid existing_version_id,
      null::text existing_status
    from queued_sources q join doc_ops d on d.entity_id=q.planned_invoice_id
    union all
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      e.operation_id,o.control_version,e.document_version_id,e.status
    from queued_sources q
    join existing_doc_versions e on e.chunk_id=q.chunk_id
    join public.invoice_operations o on o.id=e.operation_id
  ),
  doc_versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',d.planned_invoice_id,'DRAFT_PREVIEW',d.operation_id,d.source_revision,
      'invoice-professional-v2','PLANNING','{}',encode(digest('{}','sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected_doc_ops d
    where d.existing_version_id is null
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET')
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id
  ),
  all_doc_versions as materialized (
    select d.chunk_id,d.planned_invoice_id,d.operation_id,d.control_version,
      d.source_revision,
      coalesce(d.existing_version_id,v.id) document_version_id,
      coalesce(d.existing_status,'PLANNING') document_status
    from selected_doc_ops d
    left join doc_versions v
      on v.entity_id=d.planned_invoice_id and v.operation_id=d.operation_id
    where d.existing_version_id is not null or v.id is not null
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select d.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',d.document_version_id::text,
        d.source_revision,'invoice-professional-v2','1'),'sha256'),'hex'),
      0,'INVOICE',d.planned_invoice_id,d.document_version_id,
      'QUEUED',550,v_now,jsonb_build_object('purpose','DRAFT_PREVIEW'),d.control_version,v_now,v_now
    from all_doc_versions d
    where d.document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning operation_id
  ),
  invoice_ptrs as (
    update public.invoices i set preview_document_version_id=d.document_version_id,
      active_document_operation_id=case when d.document_status='READY'
        then null else d.operation_id end,
      document_state=case when d.document_status='READY'
        then 'READY' else 'QUEUED' end,updated_at=v_now
    from all_doc_versions d where i.id=d.planned_invoice_id returning i.id
  ),
  credit_issue_ops as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,chunk_count,
      control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'ISSUE_INVOICES','INVOICE_BATCH',null,
      o.actor_user_id,
      encode(digest('CREDIT_ISSUE|'||q.planned_invoice_id||'|'||
        q.document_revision||'|'||coalesce(q.command_token,''),'sha256'),'hex'),
      'QUEUED','VALIDATE',850,q.document_revision,'invoice-professional-v2',
      jsonb_build_object(
        'invoice_ids',jsonb_build_array(q.planned_invoice_id),
        'credit_note',true,'credit_reason',q.credit_reason,
        'command_token',q.command_token,'deliver',false),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q
    join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type='GENERATE_CREDIT_NOTE'
    on conflict(idempotency_key)
      where status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),
      updated_at_utc=v_now
    returning *
  ),
  selected_credit_issue as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      q.command_token,q.credit_reason,o.id operation_id,o.control_version
    from queued_sources q
    join credit_issue_ops o on o.parent_operation_id=q.parent_operation_id
      and o.operation_type='ISSUE_INVOICES'
    where q.command_type='GENERATE_CREDIT_NOTE'
  ),
  credit_issue_chunks as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,status,
      priority,run_after_utc,payload_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select s.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',s.planned_invoice_id::text,
        s.document_revision,s.command_token),'sha256'),'hex'),
      0,'INVOICE',
      s.planned_invoice_id,'QUEUED',850,v_now,
      jsonb_build_object(
        'invoice_id',s.planned_invoice_id,
        'source_revision',s.document_revision,
        'allow_early',true,'deliver',false,
        'command_token',s.command_token,
        'credit_note',true,'credit_reason',s.credit_reason),
      s.control_version,v_now,v_now
    from selected_credit_issue s
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning operation_id
  ),
  credit_issue_ptrs as (
    update public.invoices i
    set active_issue_operation_id=s.operation_id,issue_state='VALIDATING',
      updated_at=v_now
    from selected_credit_issue s
    where i.id=s.planned_invoice_id
    returning i.id
  ),
  child_results as materialized (
    select d.chunk_id,d.operation_id document_operation_id,
      d.document_version_id,null::uuid issue_operation_id
    from all_doc_versions d
    union all
    select s.chunk_id,null::uuid,null::uuid,s.operation_id
    from selected_credit_issue s
  )
  update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=coalesce(c.result_json,'{}'::jsonb)||jsonb_build_object(
        'document_operation_id',d.document_operation_id,
        'document_version_id',d.document_version_id,
        'issue_operation_id',d.issue_operation_id)
    from child_results d where c.id=d.chunk_id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='QUEUE_DOCUMENT';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

-- private._invoice_generation_resolve_command_groups(jsonb,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_generation_resolve_command_groups(p_commands jsonb, p_actor_user_id uuid, p_effective_at_utc timestamp with time zone)
 RETURNS TABLE(command_no integer, command_type text, group_key text, canonical_source_ids uuid[], canonical_source_members jsonb, source_types text[], client_id uuid, contract_ids uuid[], target_invoice_week date, natural_source_weeks date[], consolidation_mode text, invoice_stream text, self_bill boolean, automatic boolean, source_origin text, allow_early boolean, effective_settings_date date, source_revision_hash text, idempotency_components jsonb, blocker_code text, blocker_detail jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
with raw_commands as materialized (
  select e.ordinality::integer command_no,e.value command_json,
    upper(btrim(coalesce(e.value->>'command_type',e.value->>'type',''))) command_type
  from jsonb_array_elements(
    case when jsonb_typeof(p_commands)='array' then p_commands else '[]'::jsonb end
  ) with ordinality e(value,ordinality)
),
generation_commands as materialized (
  select r.*,
    case
      when r.command_type='GENERATE_NHSP'
        and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
        then r.command_json->'nhsp_shift_ids'
      when jsonb_typeof(r.command_json->'source_ids')='array'
        then r.command_json->'source_ids'
      when jsonb_typeof(r.command_json->'canonical_source_ids')='array'
        then r.command_json->'canonical_source_ids'
      when jsonb_typeof(r.command_json->'timesheet_ids')='array'
        then r.command_json->'timesheet_ids'
      when r.command_type='GENERATE_CREDIT_NOTE'
        and jsonb_typeof(r.command_json->'invoice_ids')='array'
        then r.command_json->'invoice_ids'
      when r.command_type='GENERATE_CREDIT_NOTE'
        and coalesce(r.command_json->>'base_invoice_id','')<>''
        then jsonb_build_array(r.command_json->>'base_invoice_id')
      when r.command_type='GENERATE_CREDIT_NOTE'
        and coalesce(r.command_json->>'invoice_id','')<>''
        then jsonb_build_array(r.command_json->>'invoice_id')
      else '[]'::jsonb
    end requested_ids,
    case when lower(coalesce(r.command_json->>'allow_early','false')) in('true','false')
      then(r.command_json->>'allow_early')::boolean else false end allow_early,
    r.command_type='GENERATE_AUTO' automatic
  from raw_commands r
  where r.command_type in(
    'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS','GENERATE_EXPENSES',
    'GENERATE_NHSP','GENERATE_CREDIT_NOTE','GENERATE_AUTO')
),
raw_ids as materialized (
  select c.command_no,c.command_type,c.command_json,c.allow_early,c.automatic,
    x.ordinality::integer source_ordinal,x.value source_id_text,
    x.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      valid_uuid
  from generation_commands c
  cross join lateral jsonb_array_elements_text(c.requested_ids)
    with ordinality x(value,ordinality)
),
command_shape as materialized (
  select c.command_no,c.command_type,c.command_json,c.allow_early,c.automatic,
    jsonb_array_length(c.requested_ids) requested_count,
    count(r.source_id_text) filter(where r.valid_uuid)::integer valid_uuid_count,
    count(r.source_id_text) filter(where not r.valid_uuid)::integer invalid_uuid_count,
    coalesce(jsonb_agg(r.source_id_text order by r.source_ordinal)
      filter(where not r.valid_uuid),'[]'::jsonb) invalid_values
  from generation_commands c left join raw_ids r on r.command_no=c.command_no
  group by c.command_no,c.command_type,c.command_json,c.allow_early,c.automatic,c.requested_ids
),
resolved_ids as materialized (
  select distinct r.command_no,r.command_type,r.command_json,r.allow_early,r.automatic,
    case when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      then s.timesheet_id else r.source_id_text::uuid end timesheet_id,
    case when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      then 'NHSP_SHIFT' else 'TIMESHEET' end requested_source_type,
    case when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      then r.source_id_text::uuid else r.source_id_text::uuid end requested_source_id
  from raw_ids r
  left join public.nhsp_shifts s
    on r.command_type='GENERATE_NHSP'
      and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      and s.id=r.source_id_text::uuid
  where r.valid_uuid
),
base_sources as materialized (
  select r.*,ts.week_ending_date::date natural_week_ending,
    (ts.week_ending_date::date-6) natural_week_start,
    ts.version timesheet_version,ts.updated_at timesheet_updated_at,
    ts.is_current timesheet_is_current,ts.revoked_at,ts.is_adjustment,ts.adjustment_origin,
    ts.parent_timesheet_id,ts.correction_id,ts.correction_kind::text correction_kind,
    tf.id tsfin_id,tf.timesheet_version tsfin_timesheet_version,
    tf.updated_at tsfin_updated_at,tf.is_current tsfin_is_current,tf.is_stale,
    tf.processing_status::text processing_status,tf.locked_by_invoice_id,
    tf.client_id,tf.candidate_id,tf.basis::text basis,tf.total_hours,
    tf.hours_day,tf.hours_night,tf.hours_sat,tf.hours_sun,tf.hours_bh,
    tf.additional_pay_ex_vat,tf.additional_charge_ex_vat,
    tf.expenses_pay_ex_vat,tf.expenses_charge_ex_vat,
    tf.mileage_pay_ex_vat,tf.mileage_charge_ex_vat,
    tf.travel_pay_ex_vat,tf.travel_charge_ex_vat,
    tf.accommodation_pay_ex_vat,tf.accommodation_charge_ex_vat,
    tf.other_pay_ex_vat,tf.other_charge_ex_vat,
    tf.invoice_breakdown_json,
    tf.additional_units_json,
    coalesce(
      ts.candidate_hint_text->'correction_financials_policy_envelope',
      tf.policy_snapshot_json->'correction_financials_policy_envelope',
      tf.rate_source_refs_json->'correction_financials_policy_envelope'
    ) correction_envelope,
    coalesce(ts.contract_id,cw.contract_id) contract_id,
    coalesce(parent_ts.contract_id,parent_cw.contract_id) parent_contract_id,
    coalesce(parent_contract.self_bill,contract.self_bill,false) self_bill,
    nullif(btrim(coalesce(
      parent_contract.candidate_expense_invoice_email_override,
      contract.candidate_expense_invoice_email_override,'')),'')
      contract_expense_invoice_email,
    case
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
      and (
        abs(coalesce(tf.total_hours,0))
        +abs(coalesce(tf.hours_day,0))+abs(coalesce(tf.hours_night,0))
        +abs(coalesce(tf.hours_sat,0))+abs(coalesce(tf.hours_sun,0))
        +abs(coalesce(tf.hours_bh,0))
        +abs(coalesce(tf.additional_pay_ex_vat,0))
        +abs(coalesce(tf.additional_charge_ex_vat,0))
      )=0
      and (
        abs(coalesce(tf.expenses_pay_ex_vat,0))
        +abs(coalesce(tf.expenses_charge_ex_vat,0))
        +abs(coalesce(tf.mileage_pay_ex_vat,0))
        +abs(coalesce(tf.mileage_charge_ex_vat,0))
        +abs(coalesce(tf.travel_pay_ex_vat,0))
        +abs(coalesce(tf.travel_charge_ex_vat,0))
        +abs(coalesce(tf.accommodation_pay_ex_vat,0))
        +abs(coalesce(tf.accommodation_charge_ex_vat,0))
        +abs(coalesce(tf.other_pay_ex_vat,0))
        +abs(coalesce(tf.other_charge_ex_vat,0))
      )>0 then 'EXPENSE'
      when upper(coalesce(tf.basis::text,'')) in(
        'NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL',
        'HEALTHROSTER_ADJUSTMENT'
      ) then 'SELF_BILL'
      when coalesce(parent_contract.self_bill,contract.self_bill,false)
        then 'SELF_BILL'
      else 'NORMAL'
    end invoice_stream,
    case
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
      and (
        abs(coalesce(tf.total_hours,0))
        +abs(coalesce(tf.hours_day,0))+abs(coalesce(tf.hours_night,0))
        +abs(coalesce(tf.hours_sat,0))+abs(coalesce(tf.hours_sun,0))
        +abs(coalesce(tf.hours_bh,0))
        +abs(coalesce(tf.additional_pay_ex_vat,0))
        +abs(coalesce(tf.additional_charge_ex_vat,0))
      )=0
      and (
        abs(coalesce(tf.expenses_pay_ex_vat,0))
        +abs(coalesce(tf.expenses_charge_ex_vat,0))
        +abs(coalesce(tf.mileage_pay_ex_vat,0))
        +abs(coalesce(tf.mileage_charge_ex_vat,0))
        +abs(coalesce(tf.travel_pay_ex_vat,0))
        +abs(coalesce(tf.travel_charge_ex_vat,0))
        +abs(coalesce(tf.accommodation_pay_ex_vat,0))
        +abs(coalesce(tf.accommodation_charge_ex_vat,0))
        +abs(coalesce(tf.other_pay_ex_vat,0))
        +abs(coalesce(tf.other_charge_ex_vat,0))
      )>0 then 'EXPENSE'
      when upper(coalesce(tf.basis::text,'')) like 'NHSP%' then 'NHSP'
      when upper(coalesce(tf.basis::text,'')) like 'HEALTHROSTER%' then 'HEALTHROSTER'
      when upper(coalesce(tf.basis::text,'')) like '%EXPENSE%' then 'EXPENSE'
      when coalesce(ts.is_adjustment,false) then 'ADJUSTMENT'
      else 'TIMESHEET'
    end resolved_source_type
  from resolved_ids r
  left join public.timesheets ts on ts.timesheet_id=r.timesheet_id
  left join public.timesheets_financials tf
    on tf.timesheet_id=r.timesheet_id and tf.is_current
  left join lateral (
    select w.contract_id from public.contract_weeks w
    where w.timesheet_id=r.timesheet_id
    order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc limit 1
  ) cw on true
  left join public.contracts contract on contract.id=coalesce(ts.contract_id,cw.contract_id)
  left join public.timesheets parent_ts
    on parent_ts.timesheet_id=ts.parent_timesheet_id and parent_ts.is_current
  left join lateral (
    select w.contract_id from public.contract_weeks w
    where w.timesheet_id=parent_ts.timesheet_id
    order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc limit 1
  ) parent_cw on true
  left join public.contracts parent_contract
    on parent_contract.id=coalesce(parent_ts.contract_id,parent_cw.contract_id)
),
expanded_sources as materialized (
  select b.*,
    case
      when seg.segment_json is not null
        and pg_input_is_valid(
          coalesce(seg.segment_json->>'invoice_target_week_start',''),'date')
        then(seg.segment_json->>'invoice_target_week_start')::date
      when pg_input_is_valid(
          coalesce(b.command_json->>'target_invoice_week',''),'date')
        then(b.command_json->>'target_invoice_week')::date
      else b.natural_week_start end economic_target_week,
    seg.segment_json,seg.segment_ordinal,
    seg.segment_json->>'segment_id' segment_id,
    case
      when b.requested_source_type='NHSP_SHIFT' and b.timesheet_id is null
        then 'NHSP_SHIFT_TIMESHEET_REQUIRED'
      when b.timesheet_id is null then 'SOURCE_NOT_RESOLVED'
      when b.tsfin_id is null then 'CURRENT_FINANCIALS_MISSING'
      when b.timesheet_is_current is not true or b.revoked_at is not null
        then 'TIMESHEET_NOT_CURRENT'
      when b.tsfin_is_current is not true then 'CURRENT_FINANCIALS_MISSING'
      when b.is_stale then 'FINANCIALS_STALE'
      when b.processing_status<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE'
      when b.client_id is null then 'CLIENT_UNRESOLVED'
      when b.locked_by_invoice_id is not null
        and coalesce(b.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        then 'SOURCE_ALREADY_LOCKED'
      when seg.segment_json is not null
        and nullif(btrim(coalesce(
          seg.segment_json->>'invoice_target_week_start','')),'') is not null
        and not pg_input_is_valid(
          seg.segment_json->>'invoice_target_week_start','date')
        then 'MALFORMED_SEGMENT_TARGET_WEEK'
      when seg.segment_json is not null and exists(
        select 1
        from (values
          (seg.segment_json->>'hours_day'),(seg.segment_json->>'hours_night'),
          (seg.segment_json->>'hours_sat'),(seg.segment_json->>'hours_sun'),
          (seg.segment_json->>'hours_bh'),(seg.segment_json->>'pay_amount'),
          (seg.segment_json->>'pay_ex_vat'),
          (seg.segment_json->>'charge_amount'),
          (seg.segment_json->>'charge_ex_vat')) n(value)
        where nullif(btrim(n.value),'') is not null
          and n.value!~'^[+-]?[0-9]+([.][0-9]+)?$')
        then 'MALFORMED_SEGMENT_FINANCIAL'
      when jsonb_typeof(b.additional_units_json)='object' and exists(
        select 1
        from jsonb_each(b.additional_units_json) a(key,value)
        where jsonb_typeof(a.value)<>'object'
          or exists(
            select 1
            from (values
              (a.value->>'unit_count'),(a.value->>'pay_rate'),
              (a.value->>'charge_rate'),(a.value->>'pay_ex_vat'),
              (a.value->>'charge_ex_vat')) n(value)
            where nullif(btrim(n.value),'') is not null
              and not pg_input_is_valid(n.value,'numeric'))
          or exists(
            select 1
            from jsonb_each_text(case
              when jsonb_typeof(a.value->'days')='object'
                then a.value->'days' else '{}'::jsonb end) d(key,value)
            where nullif(btrim(d.value),'') is not null
              and not pg_input_is_valid(d.value,'numeric')))
        then 'MALFORMED_ADDITIONAL_RATE'
      when seg.segment_json is not null
        and nullif(seg.segment_json->>'invoice_locked_invoice_id','') is not null
        then 'SEGMENT_ALREADY_LOCKED'
    end source_blocker
  from base_sources b
  left join lateral (
    select x.value segment_json,x.ordinality::integer segment_ordinal
    from jsonb_array_elements(
      case when jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
        then b.invoice_breakdown_json->'segments' else '[]'::jsonb end
    ) with ordinality x(value,ordinality)
    where coalesce(b.invoice_breakdown_json->>'mode','')='SEGMENTS'
      and jsonb_typeof(x.value)='object'
    union all
    select null::jsonb,0
    where coalesce(b.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
      or jsonb_array_length(case
        when jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
          then b.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ) seg on true
  where case
    when coalesce(b.command_json->>'target_invoice_week','')='' then true
    when not pg_input_is_valid(
      b.command_json->>'target_invoice_week','date') then true
    else coalesce(
      case when seg.segment_json is not null
          and pg_input_is_valid(
            coalesce(seg.segment_json->>'invoice_target_week_start',''),'date')
        then(seg.segment_json->>'invoice_target_week_start')::date end,
      b.natural_week_start)=(b.command_json->>'target_invoice_week')::date
    end
),
settings_resolved as materialized (
  select e.*,
    upper(coalesce(nullif(e.command_json->>'consolidation_mode',''),
      cs.invoice_consolidation_mode::text,'NONE')) consolidation_mode,
    case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
      and e.invoice_stream='EXPENSE' then lower(nullif(btrim(coalesce(
      e.contract_expense_invoice_email,cs.candidate_expense_invoice_email,'')),''))
      else null::text end expense_delivery_identity,
    coalesce(e.economic_target_week,e.natural_week_start,
      (p_effective_at_utc at time zone 'Europe/London')::date) settings_date
  from expanded_sources e
  left join lateral (
    select s.invoice_consolidation_mode,s.candidate_expense_invoice_email
    from public.client_settings s
    where s.client_id=e.client_id
      and(s.effective_from is null
        or s.effective_from<=coalesce(e.economic_target_week,e.natural_week_start,
          (p_effective_at_utc at time zone 'Europe/London')::date))
    order by s.effective_from desc nulls last,s.updated_at desc nulls last,
      s.created_at desc nulls last,s.id desc
    limit 1
  ) cs on true
),
source_rows_base as materialized (
  select s.*,
    case
      when s.consolidation_mode='NONE'
        and coalesce(s.is_adjustment,false)
        and upper(btrim(coalesce(s.adjustment_origin,'')))='IMPORT_CORRECTION'
        and nullif(btrim(coalesce(s.correction_id,'')),'') is not null
        and upper(btrim(coalesce(s.correction_kind,''))) in(
          'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
        and jsonb_typeof(s.correction_envelope)='object'
        and s.correction_envelope->>'policy_schema_version'=
          'IMPORT_CORRECTION_FINANCIALS_POLICY_V2'
        and s.correction_envelope->>'route_family'='IMPORT_AUTHORITATIVE'
        and lower(coalesce(
          s.correction_envelope#>>'{classification,canonical}','false'))
          in('true','t','1','yes')
        and s.correction_envelope->>'correction_shape'=
          'REVERSAL_REPLACEMENT'
        and s.correction_envelope->>'expected_member_count'='2'
        and nullif(
          s.correction_envelope#>>'{operation,operation_id}','') is not null
        and nullif(
          s.correction_envelope->>'correction_chain_id','') is not null
        and s.correction_envelope#>>'{operation,correction_action}'=
          'CHANGED_HOURS'
        and s.correction_envelope->>'envelope_fingerprint'=
          encode(digest(convert_to(
            (s.correction_envelope-'envelope_fingerprint')::text,'UTF8'),
            'sha256'),'hex')
      then 'IMPORT_AUTHORITATIVE_CORRECTION:'||s.correction_id
      else s.timesheet_id::text
    end atomic_grouping_value,
    encode(digest(concat_ws('|',
      s.resolved_source_type,s.timesheet_id::text,
      coalesce(s.segment_id,'WHOLE'),s.economic_target_week::text),
      'sha256'),'hex') source_member_key,
    encode(digest(concat_ws('|',
      s.timesheet_id::text,s.tsfin_id::text,s.tsfin_timesheet_version::text,
      s.tsfin_updated_at::text,s.timesheet_version::text,s.timesheet_updated_at::text,
      coalesce(s.invoice_breakdown_json::text,''),coalesce(s.segment_id,'WHOLE'),
      coalesce(s.segment_json::text,''),coalesce(s.segment_json->>'segment_id',''),
      coalesce(s.segment_json->>'invoice_target_week_start',''),
      coalesce(s.segment_json->>'invoice_locked_invoice_id',''),
      coalesce(s.segment_json->>'ref_num',''),
      coalesce(s.segment_json->>'charge_amount',''),
      coalesce(s.segment_json->>'pay_amount',''),
      coalesce(s.economic_target_week::text,''),s.invoice_stream,s.consolidation_mode,
      case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then coalesce(s.expense_delivery_identity,'NO_EXPENSE_RECIPIENT') end),
      'sha256'),'hex') row_revision
  from settings_resolved s
),
pre_reference_groups as materialized (
  select
    s.command_no,
    s.client_id,
    s.invoice_stream,
    s.expense_delivery_identity,
    s.consolidation_mode,
    case
      when s.consolidation_mode='NONE' then s.atomic_grouping_value
      when s.consolidation_mode='BY_WEEK'
        then s.economic_target_week::text
      else 'ANY_WEEK'
    end grouping_value,
    encode(digest(concat_ws(
      '|',
      s.command_type,
      s.client_id::text,
      s.invoice_stream,
      case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then coalesce(s.expense_delivery_identity,'NO_EXPENSE_RECIPIENT') end,
      s.consolidation_mode,
      case
        when s.consolidation_mode='NONE' then s.atomic_grouping_value
        when s.consolidation_mode='BY_WEEK'
          then s.economic_target_week::text
        else 'ANY_WEEK'
      end,
      encode(digest(string_agg(concat_ws(
        ':',
        s.timesheet_id::text,
        coalesce(s.segment_id,'WHOLE'),
        s.economic_target_week::text
      ),'|' order by
        s.timesheet_id,
        coalesce(s.segment_id,'WHOLE')
      ),'sha256'),'hex')
    ),'sha256'),'hex') group_key
  from source_rows_base s
  group by
    s.command_no,
    s.command_type,
    s.client_id,
    s.invoice_stream,
    s.expense_delivery_identity,
    s.consolidation_mode,
    case
      when s.consolidation_mode='NONE' then s.atomic_grouping_value
      when s.consolidation_mode='BY_WEEK'
        then s.economic_target_week::text
      else 'ANY_WEEK'
    end
),
source_rows_scoped as materialized (
  select source_row.*
  from source_rows_base source_row
  join pre_reference_groups candidate_group
    on candidate_group.command_no=source_row.command_no
   and candidate_group.client_id=source_row.client_id
   and candidate_group.invoice_stream=source_row.invoice_stream
   and candidate_group.expense_delivery_identity is not distinct from
       source_row.expense_delivery_identity
   and candidate_group.consolidation_mode=
       source_row.consolidation_mode
   and candidate_group.grouping_value is not distinct from case
     when source_row.consolidation_mode='NONE'
       then source_row.atomic_grouping_value
     when source_row.consolidation_mode='BY_WEEK'
       then source_row.economic_target_week::text
     else 'ANY_WEEK'
   end
  join generation_commands command
    on command.command_no=source_row.command_no
  where jsonb_typeof(command.command_json->'scope_keys')
          is distinct from 'array'
     or jsonb_array_length(
          case
            when jsonb_typeof(
              command.command_json->'scope_keys'
            )='array'
              then command.command_json->'scope_keys'
            else '[]'::jsonb
          end
        )=0
     or exists (
       select 1
       from jsonb_array_elements_text(
         case
           when jsonb_typeof(
             command.command_json->'scope_keys'
           )='array'
             then command.command_json->'scope_keys'
           else '[]'::jsonb
         end
       ) requested_scope(scope_key)
       where requested_scope.scope_key=candidate_group.group_key
     )
),
reference_results as materialized (
  select distinct on (r.source_member_key) r.*
  from private._invoice_source_reference_validate_batch(coalesce((
    select jsonb_agg(jsonb_build_object(
      'source_member_key',b.source_member_key,
      'source_type',b.resolved_source_type,
      'source_id',b.timesheet_id,
      'related_timesheet_id',b.timesheet_id,
      'segment_id',b.segment_id,
      'target_invoice_week',b.economic_target_week,
      'invoice_stream',b.invoice_stream,
      'consolidation_mode',b.consolidation_mode,
      'row_revision',b.row_revision)
      order by b.command_no,b.timesheet_id,b.segment_ordinal)
    from source_rows_scoped b
  ),'[]'::jsonb)) r
  order by r.source_member_key
),
source_rows as materialized (
  select b.*,
    case
      when b.source_blocker is not null then b.source_blocker
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
       and b.invoice_stream='EXPENSE'
       and b.expense_delivery_identity is null
        then 'EXPENSE_INVOICE_EMAIL_REQUIRED'
      when r.blocker_code='INVOICE_REFERENCE_REQUIRED'
       and not (
         coalesce(precheck.require_reference_to_invoice,false)
         and coalesce(b.total_hours,0)>0
       ) then null
      else r.blocker_code
    end canonical_blocker,
    r.reference_hash,r.current_revision canonical_row_revision,
    r.detail_json reference_detail
  from source_rows_scoped b
  left join reference_results r
    on r.source_member_key=b.source_member_key
  left join public.v_ts_invoice_precheck precheck
    on precheck.timesheet_id=b.timesheet_id
),
grouped as materialized (
  select s.command_no,s.command_type,
    encode(digest(concat_ws('|',s.command_type,s.client_id::text,s.invoice_stream,
      case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then coalesce(s.expense_delivery_identity,'NO_EXPENSE_RECIPIENT') end,
      s.consolidation_mode,
      case
        when s.consolidation_mode='NONE' then s.atomic_grouping_value
        when s.consolidation_mode='BY_WEEK' then s.economic_target_week::text
        else 'ANY_WEEK' end,
      encode(digest(string_agg(concat_ws(':',s.timesheet_id::text,
        coalesce(s.segment_id,'WHOLE'),s.economic_target_week::text)
        ,'|' order by s.timesheet_id,coalesce(s.segment_id,'WHOLE')),'sha256'),'hex')),
      'sha256'),'hex') group_key,
    array_agg(distinct s.timesheet_id order by s.timesheet_id)
      filter(where s.timesheet_id is not null) canonical_source_ids,
    jsonb_agg(jsonb_build_object(
      'source_member_key',s.source_member_key,
      'source_type',s.resolved_source_type,
      'source_id',s.timesheet_id,
      'related_timesheet_id',s.timesheet_id,
      'requested_source_type',s.requested_source_type,
      'requested_source_id',s.requested_source_id,
      'natural_week_start',s.natural_week_start,
      'target_invoice_week',s.economic_target_week,
      'segment_id',s.segment_id,
      'segment_ordinal',s.segment_ordinal,
      'row_revision',coalesce(s.canonical_row_revision,s.row_revision))
      order by s.economic_target_week,s.timesheet_id,s.segment_ordinal)
      canonical_source_members,
    array_agg(distinct s.resolved_source_type order by s.resolved_source_type)
      source_types,
    s.client_id,
    array_agg(distinct coalesce(s.parent_contract_id,s.contract_id)
      order by coalesce(s.parent_contract_id,s.contract_id))
      filter(where coalesce(s.parent_contract_id,s.contract_id) is not null) contract_ids,
    case when s.consolidation_mode='ANY_WEEK' then null::date
      else min(s.economic_target_week) end target_invoice_week,
    array_agg(distinct s.natural_week_start order by s.natural_week_start)
      filter(where s.natural_week_start is not null) natural_source_weeks,
    s.consolidation_mode,s.invoice_stream,bool_or(s.self_bill) self_bill,
    bool_or(s.automatic) automatic,
    case when bool_or(s.command_type='GENERATE_AUTO') then 'AUTOMATIC'
      when bool_or(s.requested_source_type='NHSP_SHIFT') then 'NHSP_SELECTION'
      else 'MANUAL_SELECTION' end source_origin,
    bool_and(s.allow_early) allow_early,
    min(s.settings_date) effective_settings_date,
    encode(digest(string_agg(s.timesheet_id::text||':'||
      coalesce(s.canonical_row_revision,s.row_revision),
      '|' order by s.timesheet_id,s.segment_ordinal),'sha256'),'hex') source_revision_hash,
    coalesce(min(s.canonical_blocker),null) blocker_code,
    coalesce(jsonb_agg(jsonb_build_object(
      'source_id',s.timesheet_id,'segment_id',s.segment_id,
      'code',s.canonical_blocker,
      'reference_hash',s.reference_hash,
      'reference_detail',s.reference_detail)
      order by s.timesheet_id,s.segment_ordinal)
      filter(where s.canonical_blocker is not null),'[]'::jsonb) blocker_sources
  from source_rows s
  group by s.command_no,s.command_type,s.client_id,s.consolidation_mode,s.invoice_stream,
    s.expense_delivery_identity,
    case
      when s.consolidation_mode='NONE' then s.atomic_grouping_value
      when s.consolidation_mode='BY_WEEK' then s.economic_target_week::text
      else 'ANY_WEEK' end
),
normal_results as (
  select g.command_no,g.command_type,g.group_key,g.canonical_source_ids,
    g.canonical_source_members,g.source_types,g.client_id,g.contract_ids,
    g.target_invoice_week,g.natural_source_weeks,g.consolidation_mode,
    g.invoice_stream,g.self_bill,g.automatic,g.source_origin,g.allow_early,
    g.effective_settings_date,g.source_revision_hash,
    jsonb_build_object(
      'command_type',g.command_type,'group_key',g.group_key,
      'canonical_source_ids',to_jsonb(g.canonical_source_ids),
      'canonical_source_members',g.canonical_source_members,
      'client_id',g.client_id,'contract_ids',to_jsonb(g.contract_ids),
      'target_invoice_week',g.target_invoice_week,
      'natural_source_weeks',to_jsonb(g.natural_source_weeks),
      'consolidation_mode',g.consolidation_mode,'invoice_stream',g.invoice_stream,
      'self_bill',g.self_bill,'automatic',g.automatic,
      'source_origin',g.source_origin,'allow_early',g.allow_early,
      'effective_settings_date',g.effective_settings_date,
      'source_revision_hash',g.source_revision_hash) idempotency_components,
    g.blocker_code,
    case when g.blocker_code is null then null
      else jsonb_build_object('code',g.blocker_code,'sources',g.blocker_sources) end blocker_detail
  from grouped g
),
shape_errors as (
  select s.command_no,s.command_type,
    encode(digest('INVALID|'||s.command_no||'|'||s.command_type,'sha256'),'hex') group_key,
    array[]::uuid[] canonical_source_ids,'[]'::jsonb canonical_source_members,
    array[]::text[] source_types,null::uuid client_id,array[]::uuid[] contract_ids,
    null::date target_invoice_week,array[]::date[] natural_source_weeks,
    upper(coalesce(nullif(s.command_json->>'consolidation_mode',''),'NONE')) consolidation_mode,
    'UNKNOWN'::text invoice_stream,false self_bill,s.automatic,
    case when s.automatic then 'AUTOMATIC' else 'MANUAL_SELECTION' end source_origin,
    s.allow_early,
    (p_effective_at_utc at time zone 'Europe/London')::date effective_settings_date,
    encode(digest('INVALID','sha256'),'hex') source_revision_hash,
    jsonb_build_object('command_type',s.command_type,'invalid',true) idempotency_components,
    case
      when s.requested_count=0 then 'SOURCE_IDS_REQUIRED'
      when s.invalid_uuid_count>0 then 'MALFORMED_SOURCE_ID'
      when s.valid_uuid_count<>s.requested_count then 'MIXED_VALID_INVALID_SOURCE_IDS'
      when not exists(select 1 from resolved_ids r where r.command_no=s.command_no
        and r.timesheet_id is not null) then 'SOURCE_NOT_RESOLVED'
      when exists(
        select 1 from resolved_ids r
        left join public.timesheets t on t.timesheet_id=r.timesheet_id
        where r.command_no=s.command_no
          and(r.timesheet_id is null or t.timesheet_id is null)
      ) then 'SOURCE_NOT_RESOLVED'
    end blocker_code,
    jsonb_build_object(
      'requested_count',s.requested_count,'valid_uuid_count',s.valid_uuid_count,
      'invalid_uuid_count',s.invalid_uuid_count,'invalid_values',s.invalid_values) blocker_detail
  from command_shape s
  where s.requested_count=0 or s.invalid_uuid_count>0
    or s.valid_uuid_count<>s.requested_count
    or not exists(select 1 from resolved_ids r where r.command_no=s.command_no
      and r.timesheet_id is not null)
    or exists(
      select 1 from resolved_ids r
      left join public.timesheets t on t.timesheet_id=r.timesheet_id
      where r.command_no=s.command_no
        and(r.timesheet_id is null or t.timesheet_id is null)
    )
),
credit_results as (
  select s.command_no,s.command_type,
    encode(digest('CREDIT|'||i.id||'|'||
      coalesce(s.command_json->>'credit_reason','')||'|'||
      coalesce(s.command_json->>'command_token',''),'sha256'),'hex') group_key,
    array[i.id] canonical_source_ids,
    jsonb_build_array(jsonb_build_object(
      'source_type','INVOICE','source_id',i.id,'source_revision',
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex'))) canonical_source_members,
    array['INVOICE']::text[] source_types,i.client_id,array[]::uuid[] contract_ids,
    null::date target_invoice_week,array[]::date[] natural_source_weeks,
    'CREDIT_NOTE'::text consolidation_mode,'CREDIT_NOTE'::text invoice_stream,
    false self_bill,false automatic,'MANUAL_SELECTION'::text source_origin,
    true allow_early,(i.updated_at at time zone 'Europe/London')::date effective_settings_date,
    encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
      i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
      'sha256'),'hex') source_revision_hash,
    jsonb_build_object('command_type',s.command_type,'source_invoice_id',i.id,
      'source_revision',encode(digest(concat_ws('|',i.id::text,i.updated_at::text,
        i.status::text,i.subtotal_ex_vat::text,i.vat_amount::text,
        i.total_inc_vat::text),'sha256'),'hex'),
      'credit_reason',s.command_json->>'credit_reason',
      'command_token',s.command_json->>'command_token') idempotency_components,
    case
      when i.id is null then 'INVOICE_NOT_FOUND'
      when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
      when i.status::text not in('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
      when exists(select 1 from public.invoices c
        where c.original_invoice_id=i.id and c.type='CREDIT_NOTE'
          and c.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
    end blocker_code,
    null::jsonb blocker_detail
  from command_shape s
  join raw_ids r on r.command_no=s.command_no and r.valid_uuid
  left join public.invoices i on i.id=r.source_id_text::uuid
  where s.command_type='GENERATE_CREDIT_NOTE'
    and s.requested_count>0 and s.invalid_uuid_count=0
)
select * from normal_results
where command_type<>'GENERATE_CREDIT_NOTE'
  and not exists(select 1 from shape_errors e where e.command_no=normal_results.command_no)
union all
select * from shape_errors
union all
select * from credit_results
order by command_no,group_key;
$function$;

-- private._invoice_generation_vat_policy_batch(jsonb)
CREATE OR REPLACE FUNCTION private._invoice_generation_vat_policy_batch(p_sources jsonb)
 RETURNS TABLE(source_member_key text, source_type text, source_id uuid, timesheet_id uuid, segment_id text, vat_rate numeric, policy_source text, effective_date date, policy_identity text, valid boolean, blocker_code text, detail_json jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
with supplied as materialized (
  select e.ordinality::integer source_no,
    upper(btrim(coalesce(e.value->>'source_type','TIMESHEET'))) source_type,
    case when coalesce(e.value->>'source_id',
        e.value->>'timesheet_id',e.value->>'related_timesheet_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then coalesce(e.value->>'source_id',
        e.value->>'timesheet_id',e.value->>'related_timesheet_id')::uuid end
      source_id,
    nullif(btrim(e.value->>'segment_id'),'') segment_id,
    coalesce(nullif(btrim(e.value->>'source_member_key'),''),
      encode(digest(concat_ws('|',
        coalesce(e.value->>'timesheet_id',
          e.value->>'related_timesheet_id',e.value->>'source_id',''),
        coalesce(e.value->>'segment_id','WHOLE'),
        coalesce(e.value->>'effective_date','')),'sha256'),'hex'))
      source_member_key,
    case when coalesce(e.value->>'timesheet_id',
      e.value->>'related_timesheet_id',e.value->>'source_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then coalesce(e.value->>'timesheet_id',
        e.value->>'related_timesheet_id',e.value->>'source_id')::uuid end
      timesheet_id,
    case when coalesce(e.value->>'ordinary_rate','')~'^[+-]?[0-9]+([.][0-9]+)?$'
      then(e.value->>'ordinary_rate')::numeric end supplied_ordinary_rate,
    case when coalesce(e.value->>'effective_date','')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      and pg_input_is_valid(e.value->>'effective_date','date')
      then(e.value->>'effective_date')::date end supplied_effective_date
  from jsonb_array_elements(case when jsonb_typeof(p_sources)='array'
    then p_sources else '[]'::jsonb end) with ordinality e(value,ordinality)
  where jsonb_typeof(e.value)='object'
),
source_rows as materialized (
  select s.*,t.correction_kind,t.adjustment_origin,t.week_ending_date,
    s.supplied_effective_date resolved_effective_date,
    coalesce(s.supplied_ordinary_rate,
      case when coalesce(cl.vat_chargeable,true) then
        coalesce(cs.vat_rate_pct,sf.vat_rate_pct) else 0 end)
      ordinary_rate,
    cl.vat_chargeable client_vat_chargeable,
    cs.client_settings_id,cs.client_settings_effective_from,
    sf.finance_settings_id,sf.finance_settings_date_from,
    coalesce(
      t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope') envelope
  from supplied s
  left join public.timesheets t
    on t.timesheet_id=s.timesheet_id and t.is_current
  left join public.timesheets_financials f
    on f.timesheet_id=s.timesheet_id and f.is_current
  left join public.clients cl on cl.id=f.client_id
  left join lateral (
    select x.id client_settings_id,x.effective_from client_settings_effective_from,
      x.vat_rate_pct
    from public.client_settings x
    where x.client_id=f.client_id
      and(x.effective_from is null
        or x.effective_from<=s.supplied_effective_date)
      and s.supplied_effective_date is not null
    order by x.effective_from desc nulls last,x.updated_at desc nulls last,
      x.created_at desc nulls last,x.id desc
    limit 1
  ) cs on true
  left join lateral (
    select x.id finance_settings_id,x.date_from finance_settings_date_from,
      x.vat_rate_pct
    from public.settings_finance_windows x
    where s.supplied_effective_date is not null
      and(x.date_from is null or x.date_from<=s.supplied_effective_date)
      and(x.date_to is null or x.date_to>=s.supplied_effective_date)
    order by x.date_from desc nulls last,x.updated_at desc nulls last,
      x.created_at desc nulls last,x.id desc
    limit 1
  ) sf on true
),
classified as materialized (
  select s.*,
    upper(btrim(coalesce(s.correction_kind,''))) kind,
    upper(btrim(coalesce(s.adjustment_origin,''))) origin,
    case
      when upper(btrim(coalesce(s.correction_kind,''))) in(
        'CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL')
        then s.envelope->'reversal'
      when upper(btrim(coalesce(s.correction_kind,''))) in(
        'CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
        then s.envelope->'replacement'
    end leg,
    coalesce(
      upper(btrim(coalesce(s.adjustment_origin,''))) in(
        'IMPORT_CORRECTION','IMPORT_CANCELLATION',
        'HEALTHROSTER_CHANGED_HOURS','NHSP_CHANGED_HOURS',
        'HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION')
      and upper(btrim(coalesce(s.correction_kind,''))) in(
        'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT',
        'CANCELLATION_REVERSAL','CANCELLATION_REPLACEMENT')
      and jsonb_typeof(s.envelope)='object'
      and s.envelope->>'policy_schema_version'=
        'IMPORT_CORRECTION_FINANCIALS_POLICY_V2'
      and s.envelope->>'route_family'='IMPORT_AUTHORITATIVE'
      and lower(coalesce(s.envelope#>>'{classification,canonical}','false'))
        in('true','t','1','yes')
      and nullif(s.envelope#>>'{operation,operation_id}','') is not null
      and nullif(s.envelope->>'correction_chain_id','') is not null
      and s.envelope->>'envelope_fingerprint'=
        encode(digest(convert_to(
          (s.envelope-'envelope_fingerprint')::text,'UTF8'),'sha256'),'hex')
      and(
        (upper(btrim(coalesce(s.correction_kind,''))) like 'CHANGED_HOURS_%'
          and s.envelope#>>'{operation,correction_action}'='CHANGED_HOURS')
        or
        (upper(btrim(coalesce(s.correction_kind,''))) like 'CANCELLATION_%'
          and s.envelope#>>'{operation,correction_action}'='CANCELLATION')),
      false) authoritative
  from source_rows s
),
policy as materialized (
  select c.*,c.leg->'invoice_policy' invoice_policy,
    c.leg->'tsfin_policy' tsfin_policy,
    case when coalesce(c.leg#>>'{invoice_policy,applied_vat_rate_pct}','')
      ~'^[+-]?[0-9]+([.][0-9]+)?$'
      then(c.leg#>>'{invoice_policy,applied_vat_rate_pct}')::numeric end
      applied_rate,
    case when lower(coalesce(
      c.leg#>>'{invoice_policy,invoice_vat_chargeable}','')) in(
        'true','t','1','yes','false','f','0','no')
      then lower(c.leg#>>'{invoice_policy,invoice_vat_chargeable}')
        in('true','t','1','yes') end vat_chargeable
  from classified c
)
select p.source_member_key,p.source_type,p.source_id,p.timesheet_id,p.segment_id,
  case when not p.authoritative then p.ordinary_rate
    when validation.blocker_code is null then p.applied_rate end vat_rate,
  case when p.authoritative then 'IMPORT_CORRECTION_POLICY'
    else 'ORDINARY_FINANCE_POLICY' end policy_source,
  p.resolved_effective_date effective_date,
  encode(digest(jsonb_build_object(
    'source_member_key',p.source_member_key,
    'effective_date',p.resolved_effective_date,
    'authoritative',p.authoritative,
    'vat_chargeable',p.vat_chargeable,
    'ordinary_rate',p.ordinary_rate,
    'applied_rate',p.applied_rate,
    'client_settings_id',p.client_settings_id,
    'client_settings_effective_from',p.client_settings_effective_from,
    'finance_settings_id',p.finance_settings_id,
    'finance_settings_date_from',p.finance_settings_date_from,
    'envelope_fingerprint',p.envelope->>'envelope_fingerprint',
    'invoice_policy_fingerprint',
      p.invoice_policy->>'invoice_policy_fingerprint')::text,'sha256'),'hex')
    policy_identity,
  p.timesheet_id is not null and p.resolved_effective_date is not null
    and p.ordinary_rate is not null
    and validation.blocker_code is null valid,
  case
    when p.timesheet_id is null then 'VAT_SOURCE_ID_INVALID'
    when p.resolved_effective_date is null then 'VAT_EFFECTIVE_DATE_REQUIRED'
    when p.ordinary_rate is null or p.ordinary_rate<0 or p.ordinary_rate>100
      then 'ORDINARY_VAT_RATE_INVALID'
    else validation.blocker_code
  end blocker_code,
  jsonb_build_object(
    'source_member_key',p.source_member_key,
    'authoritative_correction',p.authoritative,
    'effective_date',p.resolved_effective_date,
    'client_settings_id',p.client_settings_id,
    'client_settings_effective_from',p.client_settings_effective_from,
    'finance_settings_id',p.finance_settings_id,
    'finance_settings_date_from',p.finance_settings_date_from,
    'ordinary_rate',p.ordinary_rate,'applied_rate',p.applied_rate,
    'invoice_vat_chargeable',p.vat_chargeable,
    'correction_kind',nullif(p.kind,''),
    'envelope_fingerprint',p.envelope->>'envelope_fingerprint',
    'leg_fingerprint',p.leg->>'leg_fingerprint',
    'invoice_policy_fingerprint',
      p.invoice_policy->>'invoice_policy_fingerprint')
from policy p
cross join lateral (
  select case
    when not p.authoritative then null
    when jsonb_typeof(p.leg)<>'object' then 'IMPORT_CORRECTION_POLICY_LEG_MISSING'
    when nullif(p.leg->>'leg_fingerprint','') is null
      or p.leg->>'leg_fingerprint'<>encode(digest(convert_to(
        (p.leg-'leg_fingerprint')::text,'UTF8'),'sha256'),'hex')
      then 'IMPORT_CORRECTION_POLICY_LEG_FINGERPRINT_INVALID'
    when jsonb_typeof(p.tsfin_policy)<>'object'
      or nullif(p.tsfin_policy->>'tsfin_policy_fingerprint','') is null
      or p.tsfin_policy->>'tsfin_policy_fingerprint'<>encode(digest(convert_to(
        (p.tsfin_policy-'tsfin_policy_fingerprint')::text,'UTF8'),
        'sha256'),'hex')
      then 'IMPORT_CORRECTION_TSFIN_SUBPOLICY_FINGERPRINT_INVALID'
    when jsonb_typeof(p.invoice_policy)<>'object'
      or nullif(p.invoice_policy->>'invoice_policy_fingerprint','') is null
      or p.invoice_policy->>'invoice_policy_fingerprint'<>encode(digest(convert_to(
        (p.invoice_policy-'invoice_policy_fingerprint')::text,'UTF8'),
        'sha256'),'hex')
      or p.invoice_policy->>'invoice_stream'
        is distinct from p.envelope->>'invoice_stream'
      then 'IMPORT_CORRECTION_INVOICE_SUBPOLICY_FINGERPRINT_INVALID'
    when lower(coalesce(p.invoice_policy->>'applicable','false'))
      not in('true','t','1','yes')
      or p.invoice_policy->>'materialisation_stage'<>'INVOICE_GENERATION'
      or lower(coalesce(
        p.invoice_policy->>'final_invoice_vat_materialised','true'))
        not in('false','f','0','no')
      or nullif(p.invoice_policy->>'source_vat_rate_pct','') is null
      or p.vat_chargeable is null or p.applied_rate is null
      then 'IMPORT_CORRECTION_INVOICE_VAT_UNRESOLVED'
    when p.applied_rate<0 or p.applied_rate>100
      then 'IMPORT_CORRECTION_INVOICE_VAT_INVALID'
    when p.vat_chargeable is false and p.applied_rate<>0
      then 'IMPORT_CORRECTION_INVOICE_VAT_CHARGEABILITY_MISMATCH'
  end blocker_code
) validation
order by p.source_no;
$function$;

-- private._invoice_issue_advance_batch_legacy_20260726(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_issue_advance_batch_legacy_20260726(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_result jsonb:='[]'::jsonb;
  v_part jsonb;
begin
  if p_claims is null or jsonb_typeof(p_claims) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;
  if jsonb_array_length(p_claims) < 1 or jsonb_array_length(p_claims) > 100 then
    raise exception using errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;

  -- VALIDATE preserves stable issue blocker codes and makes no legal transition.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      then (x->>'chunk_id')::uuid end chunk_id
    from jsonb_array_elements(p_claims) x
    where x->>'phase'='VALIDATE'
  ),
  requests as materialized (
    select c.id chunk_id,c.operation_id,c.entity_id invoice_id,
      case when pg_input_is_valid(
          nullif(c.payload_json->>'evaluation_date',''),'date')
        then(c.payload_json->>'evaluation_date')::date end
        evaluation_date,
      jsonb_build_object(
        'request_key',c.id::text,
        'invoice_id',c.entity_id,
        'operation_id',c.operation_id,
        'expected_revision',c.payload_json->'source_revision',
        'allow_early',coalesce(c.payload_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.payload_json->'deliver','false'::jsonb),
        'recipient_set',coalesce(c.payload_json#>'{delivery_intent,recipient_set}',
          '[]'::jsonb),
        'cc',coalesce(c.payload_json#>'{delivery_intent,cc}','[]'::jsonb),
        'bcc',coalesce(c.payload_json#>'{delivery_intent,bcc}','[]'::jsonb)
      ) request_json
    from ids x
    join public.invoice_operation_chunks c on c.id=x.chunk_id
  ),
  validation_groups as materialized (
    select r.evaluation_date,
      jsonb_agg(r.request_json order by r.chunk_id) request_json
    from requests r
    group by r.evaluation_date
  ),
  shared_validation as materialized (
    select v.*
    from validation_groups g
    cross join lateral private._invoice_issue_validate_batch(
      g.request_json,g.evaluation_date) v
  ),
  eval as materialized (
    select r.chunk_id,r.operation_id,r.invoice_id,
      array(select jsonb_array_elements_text(
        coalesce(v.hard_blocker_codes,'[]'::jsonb))) blockers
    from requests r
    left join shared_validation v
      on v.request_key=r.chunk_id::text and v.invoice_id=r.invoice_id
  ),
  updated as (
    update public.invoice_operation_chunks c set
      phase=case when cardinality(e.blockers)=0 then 'FREEZE' else 'BLOCKED' end,
      status=case when cardinality(e.blockers)=0 then 'QUEUED' else 'BLOCKED' end,
      error_json=case when cardinality(e.blockers)=0 then null else
        jsonb_build_object('code',e.blockers[1],'blocker_codes',to_jsonb(e.blockers),'invoice_id',e.invoice_id) end,
      progress_json=jsonb_build_object('status_message',
        case when cardinality(e.blockers)=0 then 'Issue validation passed' else 'Issue blocked' end,
        'blocker_codes',to_jsonb(e.blockers)),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from eval e where c.id=e.chunk_id returning c.id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]')
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]');

  -- FREEZE: immutable legal/render snapshot; invoice deliberately remains DRAFT.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='FREEZE'
  ),
  freeze_route_requests as materialized (
    select c.id chunk_id,
      case when pg_input_is_valid(
          nullif(c.payload_json->>'evaluation_date',''),'date')
        then(c.payload_json->>'evaluation_date')::date end
        evaluation_date,
      jsonb_build_object(
      'request_key',c.id::text,
      'invoice_id',c.entity_id,
      'recipient_set',coalesce(
        c.payload_json#>'{delivery_intent,recipient_set}','[]'::jsonb),
      'cc',coalesce(c.payload_json#>'{delivery_intent,cc}','[]'::jsonb),
      'bcc',coalesce(c.payload_json#>'{delivery_intent,bcc}','[]'::jsonb),
      'delivery_policy',coalesce(
        c.payload_json#>>'{delivery_intent,delivery_policy}','ATTACH'),
      'template_version',coalesce(
        c.payload_json#>>'{delivery_intent,template_version}',
        'invoice-delivery-v1')
    ) request_json
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
  ),
  freeze_route_groups as materialized (
    select q.evaluation_date,
      jsonb_agg(q.request_json order by q.chunk_id) request_json
    from freeze_route_requests q
    group by q.evaluation_date
  ),
  frozen_routes as materialized (
    select r.*
    from freeze_route_groups g
    cross join lateral private._invoice_delivery_routes_batch(
      g.request_json,g.evaluation_date) r
  ),
  freeze_seed as materialized (
    select c.id chunk_id,c.operation_id,c.entity_id invoice_id,c.payload_json,
      i.document_revision,i.invoice_no,i.client_id,
      frozen_clock.issue_at_utc,
      frozen_clock.issue_at_utc tax_point_utc,
      frozen_clock.issue_at_utc+make_interval(days=>coalesce(
        case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
          then greatest(0,least(3650,(i.header_snapshot_json->>'payment_terms_days')::integer)) end,
        cl.payment_terms_days,30)) due_at_utc,
      rr.request_json routing_request,
      jsonb_build_object(
        'request_key',dr.request_key,
        'to',coalesce(dr.canonical_to,'[]'::jsonb),
        'cc',coalesce(dr.canonical_cc,'[]'::jsonb),
        'bcc',coalesce(dr.canonical_bcc,'[]'::jsonb),
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'route_source',dr.route_source,
        'do_not_send',dr.do_not_send,
        'delivery_suppressed',dr.delivery_suppressed,
        'suppression_reason',dr.suppression_reason,
        'client_settings_id',dr.client_settings_id,
        'contract_settings_ids',dr.contract_settings_ids,
        'effective_date',dr.effective_date,
        'client_id',dr.client_id,
        'invoice_group_identity',dr.invoice_group_identity,
        'self_bill',dr.self_bill,
        'grouping_identity',dr.grouping_identity,
        'template_version',coalesce(c.payload_json#>>'{delivery_intent,template_version}','invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(c.payload_json#>>'{delivery_intent,delivery_policy}','ATTACH')),
        'warning_codes',coalesce(dr.warning_codes,'[]'::jsonb),
        'blocker_codes',coalesce(dr.blocker_codes,'[]'::jsonb),
        'evaluated_date',dr.effective_date
      ) delivery_route,
      coalesce(nullif(c.payload_json->>'delivery_request_token',''),
        'ISSUE:'||coalesce(c.payload_json->>'command_token',c.id::text)) delivery_request_token,
      coalesce(c.payload_json->'deliver','false'::jsonb) deliver
    from ids x
    join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoices i on i.id=c.entity_id and i.status='DRAFT'
    join public.clients cl on cl.id=i.client_id
    cross join lateral (
      select case when pg_input_is_valid(nullif(c.payload_json->>'frozen_issue_at_utc',''),'timestamptz')
        then (c.payload_json->>'frozen_issue_at_utc')::timestamptz else v_now end issue_at_utc
    ) frozen_clock
    left join frozen_routes dr on dr.request_key=c.id::text and dr.invoice_id=i.id
    left join freeze_route_requests rr on rr.chunk_id=c.id
  ),
  presentation_requests as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
        'request_key',fs.chunk_id::text,
        'entity_type','INVOICE',
        'entity_id',fs.invoice_id,
        'purpose','FINAL_ISSUE',
        'template_version','invoice-professional-v1',
        'issue_at_utc',fs.issue_at_utc,
        'tax_point_utc',fs.tax_point_utc,
        'due_at_utc',fs.due_at_utc
      ) order by fs.chunk_id),'[]'::jsonb) requests
    from freeze_seed fs
  ),
  presentation_batch as materialized (
    select p.*
    from (
      select pr.requests
      from presentation_requests pr
      where jsonb_typeof(pr.requests)='array'
        and jsonb_array_length(pr.requests)>0
    ) pr
    cross join lateral private._invoice_presentation_snapshot_batch(
      pr.requests,v_now) p
  ),
  frozen as materialized (
    select fs.chunk_id,fs.operation_id,fs.invoice_id,fs.payload_json,
      fs.document_revision,fs.invoice_no,fs.client_id,
      (
        pb.snapshot_json
        || jsonb_build_object(
          'snapshot_schema_version','FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5',
          'issue_date_utc',fs.issue_at_utc,
          'tax_point_utc',fs.tax_point_utc,
          'due_date_utc',fs.due_at_utc,
          'routing_request',coalesce(fs.routing_request,'{}'::jsonb),
          'delivery_route',coalesce(fs.delivery_route,'{}'::jsonb),
          'delivery_intent',coalesce(fs.payload_json->'delivery_intent','{}'::jsonb),
          'delivery_request_token',fs.delivery_request_token,
          'deliver',fs.deliver,
          'presentation_model_hash',coalesce(pb.presentation_model->>'presentation_model_hash',pb.snapshot_json->>'presentation_model_hash',encode(digest(coalesce(pb.presentation_model,'{}'::jsonb)::text,'sha256'),'hex'))
        )
      ) snapshot,
      pb.valid presentation_valid,
      pb.error_code presentation_error_code,
      pb.error_detail presentation_error_detail
    from freeze_seed fs
    left join presentation_batch pb on pb.request_key=fs.chunk_id::text
  ),
  existing_versions as materialized (
    select f.*,v.id existing_document_version_id,v.operation_id doc_operation_id,
      o.control_version doc_control_version,v.status document_status,
      v.snapshot_hash existing_snapshot_hash
    from frozen f join public.invoice_document_versions v
      on coalesce(f.presentation_valid,false) is true
      and v.entity_type='INVOICE' and v.entity_id=f.invoice_id
      and v.purpose='FINAL_ISSUE'
      and v.snapshot_hash=encode(digest(f.snapshot::text,'sha256'),'hex')
      and v.template_version='invoice-professional-v1'
      and v.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING',
        'ASSEMBLING','VERIFYING','READY')
    join public.invoice_operations o on o.id=v.operation_id
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select f.operation_id,'BUILD_DOCUMENT','INVOICE',f.invoice_id,o.actor_user_id,
      encode(digest('FINAL_ISSUE|'||f.invoice_id||'|'||
        encode(digest(f.snapshot::text,'sha256'),'hex')||
        '|invoice-professional-v1','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',850,f.document_revision::text,'invoice-professional-v1',
      jsonb_build_object('invoice_id',f.invoice_id,'purpose','FINAL_ISSUE'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from frozen f join public.invoice_operations o on o.id=f.operation_id
    where coalesce(f.presentation_valid,false) is true
      and not exists(select 1 from existing_versions e where e.chunk_id=f.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,850),updated_at_utc=v_now
    returning *
  ),
  selected as materialized (
    select f.chunk_id,f.operation_id,f.invoice_id,f.payload_json,f.document_revision,
      f.invoice_no,f.client_id,f.snapshot,d.id doc_operation_id,d.control_version doc_control_version,
      null::uuid existing_document_version_id,null::text document_status,
      null::text existing_snapshot_hash
    from frozen f join doc_ops d on d.entity_id=f.invoice_id
    where coalesce(f.presentation_valid,false) is true
    union all
    select f.chunk_id,f.operation_id,f.invoice_id,f.payload_json,f.document_revision,
      f.invoice_no,f.client_id,f.snapshot,e.doc_operation_id,e.doc_control_version,
      e.existing_document_version_id,e.document_status,e.existing_snapshot_hash
    from frozen f join existing_versions e on e.chunk_id=f.chunk_id
    where coalesce(f.presentation_valid,false) is true
  ),
  presentation_blocked as (
    update public.invoice_operation_chunks c set
      status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
      error_json=jsonb_build_object(
        'code',coalesce(f.presentation_error_code,'FINAL_ISSUE_PRESENTATION_INVALID'),
        'detail',coalesce(f.presentation_error_detail,'{}'::jsonb),
        'invoice_id',f.invoice_id),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from frozen f
    where c.id=f.chunk_id and coalesce(f.presentation_valid,false) is not true
    returning c.id,c.status,c.phase,c.document_version_id
  ),
  versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',s.invoice_id,'FINAL_ISSUE',s.doc_operation_id,s.document_revision::text,
      'invoice-professional-v1','PLANNING',s.snapshot,encode(digest(s.snapshot::text,'sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected s
    where s.existing_document_version_id is null
    on conflict(entity_type,entity_id,purpose,snapshot_hash,template_version)
      where purpose='FINAL_ISSUE'
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id,snapshot_hash
  ),
  exact_versions as materialized (
    select s.*,coalesce(s.existing_document_version_id,v.id) document_version_id,
      coalesce(s.existing_snapshot_hash,v.snapshot_hash) snapshot_hash,
      coalesce(s.document_status,'PLANNING') exact_document_status
    from selected s left join versions v
      on v.entity_id=s.invoice_id and v.operation_id=s.doc_operation_id
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select s.doc_operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',
        s.document_version_id::text,s.document_revision::text,
        'invoice-professional-v1','1'),'sha256'),'hex'),
      0,'INVOICE',s.invoice_id,s.document_version_id,
      'QUEUED',850,v_now,jsonb_build_object('purpose','FINAL_ISSUE'),s.doc_control_version,v_now,v_now
    from exact_versions s
    where s.exact_document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning id
  ),
  invoice_state as (
    update public.invoices i set issue_state='PREPARING_DOCUMENT',
      active_issue_operation_id=s.operation_id,
      active_document_operation_id=case when s.exact_document_status='READY'
        then i.active_document_operation_id else s.doc_operation_id end,
      document_state=case when s.exact_document_status='READY'
        then i.document_state else 'PREPARING' end,updated_at=v_now
    from exact_versions s where i.id=s.invoice_id and i.status='DRAFT' returning i.id
  ),
  advanced as (
    update public.invoice_operation_chunks c set
      phase=case when s.exact_document_status='READY' then 'FINALISE' else 'WAIT_DOCUMENT' end,
      status=case when s.exact_document_status='READY' then 'QUEUED' else 'WAITING' end,
      document_version_id=s.document_version_id,
      payload_json=c.payload_json||jsonb_build_object('frozen_document_revision',s.document_revision,
        'document_version_id',s.document_version_id,'document_operation_id',s.doc_operation_id,
        'snapshot_hash',s.snapshot_hash,
        'routing_request',s.snapshot->'routing_request',
        'frozen_delivery_route',s.snapshot->'delivery_route',
        'delivery_request_token',s.snapshot->>'delivery_request_token'),
      progress_json=jsonb_build_object('status_message',
        case when s.exact_document_status='READY'
          then 'Exact final document is ready' else 'Final issue document is preparing' end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from exact_versions s where c.id=s.chunk_id
    returning c.id,c.status,c.phase,c.document_version_id
  ),
  freeze_outcomes as (
    select id,status,phase,document_version_id from advanced
    union all
    select id,status,phase,document_version_id from presentation_blocked
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,
    'document_version_id',document_version_id)),'[]') into v_part from freeze_outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- WAIT_DOCUMENT observes only the exact row and never R2.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='WAIT_DOCUMENT'
  ),
  updated as (
    update public.invoice_operation_chunks c set
      phase=case when v.status='READY' then 'FINALISE'
                 when v.status in ('FAILED','SUPERSEDED','CANCELLED') then 'BLOCKED'
                 else 'WAIT_DOCUMENT' end,
      status=case when v.status='READY' then 'QUEUED'
                  when v.status in ('FAILED','SUPERSEDED','CANCELLED') then 'BLOCKED'
                  else 'WAITING' end,
      error_json=case when v.status in ('FAILED','SUPERSEDED','CANCELLED')
        then jsonb_build_object('code','FINAL_DOCUMENT_'||v.status,'document_version_id',v.id,'detail',v.error_json)
        else null end,run_after_utc=case when v.status='READY' then v_now else c.run_after_utc end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from ids x,public.invoice_document_versions v
    where c.id=x.chunk_id and v.id=c.document_version_id
    returning c.id,c.status,c.phase,c.error_json
  ),
  missing as (
    update public.invoice_operation_chunks c set
      phase='BLOCKED',status='BLOCKED',
      error_json=jsonb_build_object(
        'code','FINAL_DOCUMENT_VERSION_MISSING',
        'document_version_id',c.document_version_id),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from ids x
    where c.id=x.chunk_id
      and not exists(
        select 1 from public.invoice_document_versions v
        where v.id=c.document_version_id)
    returning c.id,c.status,c.phase,c.error_json
  ),
  outcomes as (
    select * from updated
    union all
    select * from missing
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]')
    into v_part from outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- FINALISE is the only legal issue transition and demands the exact verified version.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='FINALISE'
  ),
  eligible as materialized (
    select c.*,i.document_revision,v.id final_document_version_id,v.r2_key,v.sha256,v.size_bytes,v.page_count,
      v.verified_at_utc,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'issue_date_utc',''),'timestamptz')
        then (v.snapshot_json->>'issue_date_utc')::timestamptz
        else v_now end issue_at,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'tax_point_utc',''),'timestamptz')
        then (v.snapshot_json->>'tax_point_utc')::timestamptz end tax_point_at,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'due_date_utc',''),'timestamptz')
        then (v.snapshot_json->>'due_date_utc')::timestamptz end due_at,
      v.snapshot_hash
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoices i on i.id=c.entity_id and i.status='DRAFT'
      and i.issue_state='PREPARING_DOCUMENT'
      and i.active_issue_operation_id=c.operation_id
    join public.invoice_document_versions v on v.id=c.document_version_id and v.purpose='FINAL_ISSUE'
      and v.entity_type='INVOICE' and v.entity_id=c.entity_id
      and v.status='READY' and v.verified_at_utc is not null and v.r2_key is not null
      and v.sha256 is not null and v.size_bytes>0 and v.page_count>0
    where case when pg_input_is_valid(
        nullif(c.payload_json->>'frozen_document_revision',''),'bigint')
      then(c.payload_json->>'frozen_document_revision')::bigint=i.document_revision
      else false end
      and v.source_revision=i.document_revision::text
      and c.payload_json->>'snapshot_hash'=v.snapshot_hash
  ),
  issued as (
    update public.invoices i set status='ISSUED',status_date_utc=v_now,
      issued_at_utc=e.issue_at,due_at_utc=e.due_at,
      on_hold_reason=null,issued_document_version_id=e.final_document_version_id,
      invoice_pdf_r2_key=e.r2_key,invoice_pdf_generated_at_utc=e.verified_at_utc,
      issue_state='ISSUED',document_state='READY',active_issue_operation_id=null,
      active_document_operation_id=case
        when pg_input_is_valid(
          nullif(e.payload_json->>'document_operation_id',''),'uuid')
          then case when i.active_document_operation_id=
              (e.payload_json->>'document_operation_id')::uuid
            then null else i.active_document_operation_id end
        else i.active_document_operation_id end,updated_at=v_now
    from eligible e where i.id=e.entity_id returning i.id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoice',e.entity_id::text,'INVOICE_ISSUED',
      jsonb_build_object('invoice_id',e.entity_id,'document_version_id',e.final_document_version_id,
        'issue_at_utc',e.issue_at,'tax_point_utc',e.tax_point_at,'due_at_utc',e.due_at,
        'sha256',e.sha256,'size_bytes',e.size_bytes,'page_count',e.page_count),'INVOICE_OPERATION_QUEUE'
    from eligible e join public.invoice_operations o on o.id=e.operation_id
    left join public.tms_users u on u.id=o.actor_user_id returning id
  ),
  advanced as (
    update public.invoice_operation_chunks c set
      phase=case when lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes') then 'QUEUE_DELIVERY' else 'COMPLETE' end,
      status=case when lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes') then 'QUEUED' else 'COMPLETE' end,
      completed_at_utc=case when lower(coalesce(
        c.payload_json->>'deliver','false')) in('true','t','1','yes')
        then null else v_now end,
      result_json=jsonb_build_object('invoice_id',e.entity_id,'document_version_id',e.final_document_version_id,
        'issue_at_utc',e.issue_at,'tax_point_utc',e.tax_point_at,'due_at_utc',e.due_at,
        'r2_key',e.r2_key,'sha256',e.sha256,'size_bytes',e.size_bytes,'page_count',e.page_count),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from eligible e where c.id=e.id
    returning c.id,c.status,c.phase,c.result_json,c.error_json
  ),
  ineligible as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','ISSUE_FINALISE_OWNERSHIP_OR_DOCUMENT_MISMATCH',
          'invoice_id',c.entity_id,
          'document_version_id',c.document_version_id),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from ids x
    where c.id=x.chunk_id
      and not exists(select 1 from eligible e where e.id=c.id)
    returning c.id,c.status,c.phase,c.result_json,c.error_json
  ),
  outcomes as (
    select * from advanced
    union all
    select * from ineligible
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]')
    into v_part from outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- QUEUE_DELIVERY durably delegates to the single delivery-routing authority.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then (x->>'chunk_id')::uuid end chunk_id
    from jsonb_array_elements(p_claims) x
    where x->>'phase'='QUEUE_DELIVERY'
  ),
  delivery_specs as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,c.entity_id invoice_id,
      o.actor_user_id,i.issued_document_version_id,
      coalesce(c.payload_json->'delivery_intent','{}'::jsonb) delivery_intent,
      coalesce(c.payload_json->'routing_request','{}'::jsonb)
        routing_request,
      coalesce(c.payload_json->'frozen_delivery_route','{}'::jsonb)
        frozen_delivery_route,
      coalesce(nullif(c.payload_json->>'delivery_request_token',''),
        'ISSUE:'||coalesce(c.payload_json->>'command_token',c.id::text))
        delivery_request_token,
      nullif(c.payload_json#>>'{frozen_delivery_route,template_version}','')
        template_version,
      nullif(c.payload_json#>>'{frozen_delivery_route,recipient_set_hash}','')
        recipient_set_hash,
      nullif(c.payload_json#>>'{frozen_delivery_route,route_policy_hash}','')
        route_policy_hash,
      coalesce(c.payload_json#>'{frozen_delivery_route,to}','[]'::jsonb)
        canonical_to,
      coalesce(c.payload_json#>'{frozen_delivery_route,cc}','[]'::jsonb)
        canonical_cc,
      coalesce(c.payload_json#>'{frozen_delivery_route,bcc}','[]'::jsonb)
        canonical_bcc,
      lower(coalesce(
        c.payload_json#>>'{frozen_delivery_route,do_not_send}','false'))
        in('true','t','1','yes') do_not_send,
      lower(coalesce(
        c.payload_json#>>'{frozen_delivery_route,delivery_suppressed}','false'))
        in('true','t','1','yes') delivery_suppressed,
      c.payload_json#>>'{frozen_delivery_route,route_source}' route_source,
      coalesce(c.payload_json#>'{frozen_delivery_route,warning_codes}',
        '[]'::jsonb) route_warnings,
      coalesce(c.payload_json#>'{frozen_delivery_route,blocker_codes}',
        '[]'::jsonb) route_blockers,
      c.payload_json#>>'{frozen_delivery_route,route_policy_hash}' is not null
        and c.payload_json#>>'{frozen_delivery_route,recipient_set_hash}'
          is not null
        and c.payload_json#>>'{frozen_delivery_route,template_version}'
          is not null
        and upper(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_policy}',''))
          in('ATTACH','SPLIT','SECURE_LINK')
        and lower(coalesce(
          c.payload_json#>>'{frozen_delivery_route,do_not_send}','false'))
          not in('true','t','1','yes')
        and lower(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_suppressed}','false'))
          not in('true','t','1','yes')
        and (case
          when jsonb_typeof(c.payload_json#>'{frozen_delivery_route,blocker_codes}')='array'
            then jsonb_array_length(c.payload_json#>'{frozen_delivery_route,blocker_codes}')
          when c.payload_json#>'{frozen_delivery_route,blocker_codes}' is null then 0
          else 1
        end)=0
        frozen_route_usable,
      coalesce(case when coalesce(c.payload_json#>>'{delivery_intent,part_number}','') ~
        '^[0-9]+$' then(c.payload_json#>>'{delivery_intent,part_number}')::integer end,1)
        part_number,
      case when upper(coalesce(
          c.payload_json#>>'{delivery_intent,delivery_policy}','')) in(
            'ATTACH','SPLIT','SECURE_LINK')
        then upper(c.payload_json#>>'{delivery_intent,delivery_policy}')
        when upper(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_policy}','')) in(
            'ATTACH','SPLIT','SECURE_LINK')
        then upper(c.payload_json#>>'{frozen_delivery_route,delivery_policy}')
      end delivery_policy
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoice_operations o on o.id=c.operation_id
    join public.invoices i on i.id=c.entity_id and i.status='ISSUED'
      and i.issued_document_version_id=c.document_version_id
  ),
  delivery_groups as materialized (
    select d.parent_operation_id,
      (array_agg(d.actor_user_id order by d.chunk_id))[1] actor_user_id,
      (array_agg(d.template_version order by d.chunk_id))[1] template_version,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.route_policy_hash),'||' order by d.invoice_id),'sha256'),'hex')
        route_policy_hash,
      (array_agg(d.delivery_policy order by d.chunk_id))[1] delivery_policy,
      array_agg(d.invoice_id order by d.invoice_id) invoice_ids,
      array_agg(d.issued_document_version_id order by d.invoice_id)
        issued_document_version_ids,
      array_agg(d.delivery_request_token order by d.invoice_id)
        delivery_request_tokens,
      count(*)::integer unit_count,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.issued_document_version_id::text,d.delivery_request_token),
        '||' order by d.invoice_id),'sha256'),'hex') group_request_hash,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.issued_document_version_id::text,d.delivery_request_token,
        d.route_policy_hash),
        '||' order by d.invoice_id),'sha256'),'hex') delivery_revision,
      encode(digest(concat_ws('|','DELIVER_INVOICES',d.parent_operation_id::text,
        encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
          d.issued_document_version_id::text,d.delivery_request_token),
          '||' order by d.invoice_id),'sha256'),'hex')),'sha256'),'hex')
        delivery_key
    from delivery_specs d
    group by d.parent_operation_id
  ),
  existing_delivery as materialized (
    select g.parent_operation_id,o.id operation_id,o.control_version,o.status
    from delivery_groups g join lateral(
      select x.* from public.invoice_operations x
      where x.idempotency_key=g.delivery_key
        and x.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(x.status='COMPLETE') desc,x.created_at_utc desc limit 1
    ) o on true
  ),
  inserted_delivery as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,
      entity_type,entity_id,actor_user_id,idempotency_key,status,phase,priority,
      source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,requires_user_action,
      error_json,created_at_utc,updated_at_utc)
    select g.parent_operation_id,'DELIVER_INVOICES','INVOICE_BATCH',null,
      g.actor_user_id,g.delivery_key,'QUEUED','PREPARE',700,
      g.delivery_revision,g.template_version,
      jsonb_build_object('invoice_ids',to_jsonb(g.invoice_ids),
        'issued_document_version_ids',to_jsonb(g.issued_document_version_ids),
        'template_version',g.template_version,
        'delivery_request_tokens',to_jsonb(g.delivery_request_tokens),
        'group_request_hash',g.group_request_hash,
        'route_policy_hash',g.route_policy_hash,
        'delivery_policy',g.delivery_policy),
      jsonb_build_object(
        'delivery_request_tokens',to_jsonb(g.delivery_request_tokens),
        'group_request_hash',g.group_request_hash,
        'route_policy_hash',g.route_policy_hash,
        'processor_policy',parent.config_json->'processor_policy'),
      jsonb_build_object('status_message','Batch delivery preparation queued'),
      g.unit_count,g.unit_count,1,nextval('public.invoice_operation_change_seq'),
      false,null,v_now,v_now
    from delivery_groups g
    join public.invoice_operations parent on parent.id=g.parent_operation_id
    where not exists(
      select 1 from existing_delivery e
      where e.parent_operation_id=g.parent_operation_id)
    on conflict do nothing
    returning *
  ),
  selected_delivery_groups as materialized (
    select g.*,coalesce(e.operation_id,n.id) delivery_operation_id,
      coalesce(e.control_version,n.control_version) delivery_control_version,
      coalesce(e.status,n.status) delivery_status
    from delivery_groups g
    left join existing_delivery e
      on e.parent_operation_id=g.parent_operation_id
    left join inserted_delivery n on n.idempotency_key=g.delivery_key
  ),
  selected_delivery as materialized (
    select d.*,g.delivery_operation_id,g.delivery_control_version,
      g.delivery_status
    from delivery_specs d
    join selected_delivery_groups g
      on g.parent_operation_id=d.parent_operation_id
  ),
  delivery_chunk_specs as materialized (
    select d.*,gen_random_uuid() delivery_chunk_id
    from selected_delivery d
    where d.delivery_status<>'COMPLETE'
  ),
  delivery_chunks as (
    insert into public.invoice_operation_chunks(id,operation_id,chunk_type,phase,
      work_key,sequence_no,entity_type,entity_id,document_version_id,status,priority,
      run_after_utc,payload_json,error_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select d.delivery_chunk_id,d.delivery_operation_id,'DELIVERY_PREPARE',
      case when d.frozen_route_usable then 'PREPARE' else 'BLOCKED' end,
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        d.issued_document_version_id::text,d.route_policy_hash,
        d.template_version,d.part_number::text,d.delivery_request_token),
        'sha256'),'hex'),
      row_number() over(partition by d.delivery_operation_id
        order by d.invoice_id)::integer-1,
      'INVOICE',d.invoice_id,d.issued_document_version_id,
      case when d.frozen_route_usable then 'QUEUED' else 'BLOCKED' end,
      700,v_now,
      jsonb_build_object('request_key',d.delivery_chunk_id::text,
        'invoice_id',d.invoice_id,
        'issued_document_version_id',d.issued_document_version_id,
        'recipient_set',d.canonical_to,'cc',d.canonical_cc,'bcc',d.canonical_bcc,
        'recipient_set_hash',d.recipient_set_hash,'template_version',d.template_version,
        'route_policy_hash',d.route_policy_hash,
        'delivery_part_number',d.part_number,'do_not_send',d.do_not_send,
        'delivery_suppressed',d.delivery_suppressed,
        'delivery_policy',d.delivery_policy,
        'route_source',d.route_source,
        'delivery_request_token',d.delivery_request_token,
        'routing_request',d.routing_request,
        'frozen_delivery_route',d.frozen_delivery_route),
      case when d.frozen_route_usable then null else jsonb_build_object(
        'code','FROZEN_DELIVERY_ROUTE_UNUSABLE',
        'frozen_route',d.frozen_delivery_route,
        'route_blockers',d.route_blockers) end,
      d.delivery_control_version,v_now,v_now
    from delivery_chunk_specs d
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning id
  ),
  completed_delivery_request as (
    update public.invoice_operation_chunks c set status='COMPLETE',phase='COMPLETE',
      completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=coalesce(c.result_json,'{}')||jsonb_build_object(
        'delivery_operation_id',d.delivery_operation_id,
        'delivery_status',case when d.frozen_route_usable
          then d.delivery_status else 'BLOCKED' end,
        'delivery_requested',true,
        'delivery_request_token',d.delivery_request_token,
        'delivery_blocker',case when d.frozen_route_usable then null
          else jsonb_build_object('code','FROZEN_DELIVERY_ROUTE_UNUSABLE',
            'frozen_route',d.frozen_delivery_route,
            'route_blockers',d.route_blockers) end)
    from selected_delivery d where c.id=d.chunk_id
    returning c.id,c.status,c.phase,c.result_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,
    'phase',phase,'result',result_json)),'[]') into v_part
  from completed_delivery_request;
  v_result:=v_result||coalesce(v_part,'[]');

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

-- private._invoice_issue_advance_batch(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_issue_advance_batch(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_manifest_claims jsonb;
  v_core_claims jsonb;
  v_rejected_claims jsonb;
  v_result jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(coalesce(p_claims,'null'::jsonb)) is distinct from 'array'
     or jsonb_array_length(p_claims) < 1
     or jsonb_array_length(p_claims) > 100 then
    raise exception using
      errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;

  with claims as materialized (
    select value claim_json,ordinality
    from jsonb_array_elements(p_claims) with ordinality claim(value,ordinality)
  ),
  classified as materialized (
    select
      claim.*,
      exists (
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.id=case
          when pg_input_is_valid(coalesce(claim.claim_json->>'chunk_id',''),'uuid')
            then (claim.claim_json->>'chunk_id')::uuid
        end
          and c.chunk_type='ISSUE_INVOICE'
          and o.entity_type='INVOICE_BATCH'
          and not c.is_manifest_member
          and c.phase in ('BUILD_MANIFEST','RELEASE_MANIFEST')
          and coalesce(c.payload_json->>'is_selection_expander','false')
            in ('true','t','1','yes','on')
      ) is_manifest,
      exists (
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.id=case
          when pg_input_is_valid(
            coalesce(claim.claim_json->>'chunk_id',''),
            'uuid'
          ) then (claim.claim_json->>'chunk_id')::uuid
        end
          and c.chunk_type='ISSUE_INVOICE'
          and (
            -- Preserve the established direct invoice operation path while
            -- retaining manifest-release enforcement for batch roots.
            o.entity_type is distinct from 'INVOICE_BATCH'
            or (
              c.is_manifest_member
              and c.manifest_committed
              and o.manifest_committed
              and c.phase not in (
                'AWAITING_MANIFEST_COMMIT',
                'AWAITING_RELEASE'
              )
              and coalesce(
                c.payload_json->>'is_selection_expander',
                'false'
              ) not in ('true','t','1','yes','on')
            )
          )
      ) is_released
    from claims claim
  )
  select
    coalesce(jsonb_agg(claim_json order by ordinality)
      filter (where is_manifest),'[]'::jsonb),
    coalesce(jsonb_agg(claim_json order by ordinality)
      filter (where not is_manifest and is_released),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',claim_json->>'chunk_id',
      'status','REJECTED',
      'phase','OWNERSHIP_REJECTED',
      'accepted',false,
      'code','MANIFEST_CLAIM_NOT_RELEASED'
    ) order by ordinality)
      filter (where not is_manifest and not is_released),'[]'::jsonb)
  into v_manifest_claims,v_core_claims,v_rejected_claims
  from classified;

  if jsonb_array_length(v_manifest_claims)>0 then
    v_result := v_result
      || private._invoice_batch_manifest_advance_v2(
        v_manifest_claims,
        'ISSUE',
        v_now
      );
  end if;

  if jsonb_array_length(v_core_claims)>0 then
    v_result := v_result
      || private._invoice_issue_advance_core_v8(
        v_core_claims,
        v_now
      );
  end if;

  return coalesce(v_result,'[]'::jsonb)
    || coalesce(v_rejected_claims,'[]'::jsonb);
end;
$function$;

-- private._invoice_issue_advance_core_v8(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_issue_advance_core_v8(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_result jsonb:='[]'::jsonb;
  v_part jsonb;
begin
  if p_claims is null or jsonb_typeof(p_claims) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;
  if jsonb_array_length(p_claims) < 1 or jsonb_array_length(p_claims) > 100 then
    raise exception using errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;

  -- VALIDATE preserves stable issue blocker codes and makes no legal transition.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      then (x->>'chunk_id')::uuid end chunk_id
    from jsonb_array_elements(p_claims) x
    where x->>'phase'='VALIDATE'
  ),
  requests as materialized (
    select c.id chunk_id,c.operation_id,c.entity_id invoice_id,
      case when pg_input_is_valid(
          nullif(c.payload_json->>'evaluation_date',''),'date')
        then(c.payload_json->>'evaluation_date')::date end
        evaluation_date,
      jsonb_build_object(
        'request_key',c.id::text,
        'invoice_id',c.entity_id,
        'operation_id',c.operation_id,
        'expected_revision',case
          when coalesce(c.payload_json->>'source_revision','')~'^[0-9]+$'
            then to_jsonb((c.payload_json->>'source_revision')::bigint)
          else c.payload_json->'source_revision'
        end,
        'allow_early',coalesce(c.payload_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.payload_json->'deliver','false'::jsonb),
        'recipient_set',coalesce(c.payload_json#>'{delivery_intent,recipient_set}',
          '[]'::jsonb),
        'cc',coalesce(c.payload_json#>'{delivery_intent,cc}','[]'::jsonb),
        'bcc',coalesce(c.payload_json#>'{delivery_intent,bcc}','[]'::jsonb)
      ) request_json
    from ids x
    join public.invoice_operation_chunks c on c.id=x.chunk_id
  ),
  validation_groups as materialized (
    select r.evaluation_date,
      jsonb_agg(r.request_json order by r.chunk_id) request_json
    from requests r
    group by r.evaluation_date
  ),
  shared_validation as materialized (
    select v.*
    from validation_groups g
    cross join lateral private._invoice_issue_validate_batch(
      g.request_json,g.evaluation_date) v
  ),
  eval as materialized (
    select r.chunk_id,r.operation_id,r.invoice_id,
      array(select jsonb_array_elements_text(
        coalesce(v.hard_blocker_codes,'[]'::jsonb))) blockers
    from requests r
    left join shared_validation v
      on v.request_key=r.chunk_id::text and v.invoice_id=r.invoice_id
  ),
  updated as (
    update public.invoice_operation_chunks c set
      phase=case when cardinality(e.blockers)=0 then 'FREEZE' else 'BLOCKED' end,
      status=case when cardinality(e.blockers)=0 then 'QUEUED' else 'BLOCKED' end,
      error_json=case when cardinality(e.blockers)=0 then null else
        jsonb_build_object('code',e.blockers[1],'blocker_codes',to_jsonb(e.blockers),'invoice_id',e.invoice_id) end,
      progress_json=jsonb_build_object('status_message',
        case when cardinality(e.blockers)=0 then 'Issue validation passed' else 'Issue blocked' end,
        'blocker_codes',to_jsonb(e.blockers)),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from eval e where c.id=e.chunk_id returning c.id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]')
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]');

  -- FREEZE: immutable legal/render snapshot; invoice deliberately remains DRAFT.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='FREEZE'
  ),
  freeze_route_requests as materialized (
    select c.id chunk_id,
      case when pg_input_is_valid(
          nullif(c.payload_json->>'evaluation_date',''),'date')
        then(c.payload_json->>'evaluation_date')::date end
        evaluation_date,
      jsonb_build_object(
      'request_key',c.id::text,
      'invoice_id',c.entity_id,
      'recipient_set',coalesce(
        c.payload_json#>'{delivery_intent,recipient_set}','[]'::jsonb),
      'cc',coalesce(c.payload_json#>'{delivery_intent,cc}','[]'::jsonb),
      'bcc',coalesce(c.payload_json#>'{delivery_intent,bcc}','[]'::jsonb),
      'delivery_policy',coalesce(
        c.payload_json#>>'{delivery_intent,delivery_policy}','ATTACH'),
      'template_version',coalesce(
        c.payload_json#>>'{delivery_intent,template_version}',
        'invoice-delivery-v1')
    ) request_json
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
  ),
  freeze_route_groups as materialized (
    select q.evaluation_date,
      jsonb_agg(q.request_json order by q.chunk_id) request_json
    from freeze_route_requests q
    group by q.evaluation_date
  ),
  frozen_routes as materialized (
    select r.*
    from freeze_route_groups g
    cross join lateral private._invoice_delivery_routes_batch(
      g.request_json,g.evaluation_date) r
  ),
  freeze_seed as materialized (
    select c.id chunk_id,c.operation_id,c.entity_id invoice_id,c.payload_json,
      i.document_revision,i.invoice_no,i.client_id,
      frozen_clock.issue_at_utc,
      frozen_clock.issue_at_utc tax_point_utc,
      frozen_clock.issue_at_utc+make_interval(days=>coalesce(
        case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
          then greatest(0,least(3650,(i.header_snapshot_json->>'payment_terms_days')::integer)) end,
        cl.payment_terms_days,30)) due_at_utc,
      rr.request_json routing_request,
      jsonb_build_object(
        'request_key',dr.request_key,
        'to',coalesce(dr.canonical_to,'[]'::jsonb),
        'cc',coalesce(dr.canonical_cc,'[]'::jsonb),
        'bcc',coalesce(dr.canonical_bcc,'[]'::jsonb),
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'route_source',dr.route_source,
        'do_not_send',dr.do_not_send,
        'delivery_suppressed',dr.delivery_suppressed,
        'suppression_reason',dr.suppression_reason,
        'client_settings_id',dr.client_settings_id,
        'contract_settings_ids',dr.contract_settings_ids,
        'effective_date',dr.effective_date,
        'client_id',dr.client_id,
        'invoice_group_identity',dr.invoice_group_identity,
        'self_bill',dr.self_bill,
        'grouping_identity',dr.grouping_identity,
        'template_version',coalesce(c.payload_json#>>'{delivery_intent,template_version}','invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(c.payload_json#>>'{delivery_intent,delivery_policy}','ATTACH')),
        'warning_codes',coalesce(dr.warning_codes,'[]'::jsonb),
        'blocker_codes',coalesce(dr.blocker_codes,'[]'::jsonb),
        'evaluated_date',dr.effective_date
      ) delivery_route,
      coalesce(nullif(c.payload_json->>'delivery_request_token',''),
        'ISSUE:'||coalesce(c.payload_json->>'command_token',c.id::text)) delivery_request_token,
      coalesce(c.payload_json->'deliver','false'::jsonb) deliver
    from ids x
    join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoices i on i.id=c.entity_id and i.status='DRAFT'
    join public.clients cl on cl.id=i.client_id
    cross join lateral (
      select case when pg_input_is_valid(nullif(c.payload_json->>'frozen_issue_at_utc',''),'timestamptz')
        then (c.payload_json->>'frozen_issue_at_utc')::timestamptz else v_now end issue_at_utc
    ) frozen_clock
    left join frozen_routes dr on dr.request_key=c.id::text and dr.invoice_id=i.id
    left join freeze_route_requests rr on rr.chunk_id=c.id
  ),
  presentation_requests as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
        'request_key',fs.chunk_id::text,
        'entity_type','INVOICE',
        'entity_id',fs.invoice_id,
        'purpose','FINAL_ISSUE',
        'template_version','invoice-professional-v2',
        'issue_at_utc',fs.issue_at_utc,
        'tax_point_utc',fs.tax_point_utc,
        'due_at_utc',fs.due_at_utc
      ) order by fs.chunk_id),'[]'::jsonb) requests
    from freeze_seed fs
  ),
  presentation_batch as materialized (
    select p.*
    from (
      select pr.requests
      from presentation_requests pr
      where jsonb_typeof(pr.requests)='array'
        and jsonb_array_length(pr.requests)>0
    ) pr
    cross join lateral private._invoice_presentation_snapshot_batch(
      pr.requests,v_now) p
  ),
  frozen as materialized (
    select fs.chunk_id,fs.operation_id,fs.invoice_id,fs.payload_json,
      fs.document_revision,fs.invoice_no,fs.client_id,
      (
        pb.snapshot_json
        || jsonb_build_object(
          'snapshot_schema_version','FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5',
          'issue_date_utc',fs.issue_at_utc,
          'tax_point_utc',fs.tax_point_utc,
          'due_date_utc',fs.due_at_utc,
          'routing_request',coalesce(fs.routing_request,'{}'::jsonb),
          'delivery_route',coalesce(fs.delivery_route,'{}'::jsonb),
          'delivery_intent',coalesce(fs.payload_json->'delivery_intent','{}'::jsonb),
          'delivery_request_token',fs.delivery_request_token,
          'deliver',fs.deliver,
          'presentation_model_hash',coalesce(pb.presentation_model->>'presentation_model_hash',pb.snapshot_json->>'presentation_model_hash',encode(digest(coalesce(pb.presentation_model,'{}'::jsonb)::text,'sha256'),'hex'))
        )
      ) snapshot,
      pb.valid presentation_valid,
      pb.error_code presentation_error_code,
      pb.error_detail presentation_error_detail
    from freeze_seed fs
    left join presentation_batch pb on pb.request_key=fs.chunk_id::text
  ),
  existing_versions as materialized (
    select f.*,v.id existing_document_version_id,v.operation_id doc_operation_id,
      o.control_version doc_control_version,v.status document_status,
      v.snapshot_hash existing_snapshot_hash
    from frozen f join public.invoice_document_versions v
      on coalesce(f.presentation_valid,false) is true
      and v.entity_type='INVOICE' and v.entity_id=f.invoice_id
      and v.purpose='FINAL_ISSUE'
      and v.snapshot_hash=encode(digest(f.snapshot::text,'sha256'),'hex')
      and v.template_version='invoice-professional-v2'
      and v.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING',
        'ASSEMBLING','VERIFYING','READY')
    join public.invoice_operations o on o.id=v.operation_id
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select f.operation_id,'BUILD_DOCUMENT','INVOICE',f.invoice_id,o.actor_user_id,
      encode(digest('FINAL_ISSUE|'||f.invoice_id||'|'||
        encode(digest(f.snapshot::text,'sha256'),'hex')||
        '|invoice-professional-v2','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',850,f.document_revision::text,'invoice-professional-v2',
      jsonb_build_object('invoice_id',f.invoice_id,'purpose','FINAL_ISSUE'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from frozen f join public.invoice_operations o on o.id=f.operation_id
    where coalesce(f.presentation_valid,false) is true
      and not exists(select 1 from existing_versions e where e.chunk_id=f.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,850),updated_at_utc=v_now
    returning *
  ),
  selected as materialized (
    select f.chunk_id,f.operation_id,f.invoice_id,f.payload_json,f.document_revision,
      f.invoice_no,f.client_id,f.snapshot,d.id doc_operation_id,d.control_version doc_control_version,
      null::uuid existing_document_version_id,null::text document_status,
      null::text existing_snapshot_hash
    from frozen f join doc_ops d on d.entity_id=f.invoice_id
    where coalesce(f.presentation_valid,false) is true
    union all
    select f.chunk_id,f.operation_id,f.invoice_id,f.payload_json,f.document_revision,
      f.invoice_no,f.client_id,f.snapshot,e.doc_operation_id,e.doc_control_version,
      e.existing_document_version_id,e.document_status,e.existing_snapshot_hash
    from frozen f join existing_versions e on e.chunk_id=f.chunk_id
    where coalesce(f.presentation_valid,false) is true
  ),
  presentation_blocked as (
    update public.invoice_operation_chunks c set
      status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
      error_json=jsonb_build_object(
        'code',coalesce(f.presentation_error_code,'FINAL_ISSUE_PRESENTATION_INVALID'),
        'detail',coalesce(f.presentation_error_detail,'{}'::jsonb),
        'invoice_id',f.invoice_id),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from frozen f
    where c.id=f.chunk_id and coalesce(f.presentation_valid,false) is not true
    returning c.id,c.status,c.phase,c.document_version_id
  ),
  versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',s.invoice_id,'FINAL_ISSUE',s.doc_operation_id,s.document_revision::text,
      'invoice-professional-v2','PLANNING',s.snapshot,encode(digest(s.snapshot::text,'sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected s
    where s.existing_document_version_id is null
    on conflict(entity_type,entity_id,purpose,snapshot_hash,template_version)
      where purpose='FINAL_ISSUE'
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id,snapshot_hash
  ),
  exact_versions as materialized (
    select s.*,coalesce(s.existing_document_version_id,v.id) document_version_id,
      coalesce(s.existing_snapshot_hash,v.snapshot_hash) snapshot_hash,
      coalesce(s.document_status,'PLANNING') exact_document_status
    from selected s left join versions v
      on v.entity_id=s.invoice_id and v.operation_id=s.doc_operation_id
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select s.doc_operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',
        s.document_version_id::text,s.document_revision::text,
        'invoice-professional-v2','1'),'sha256'),'hex'),
      0,'INVOICE',s.invoice_id,s.document_version_id,
      'QUEUED',850,v_now,jsonb_build_object('purpose','FINAL_ISSUE'),s.doc_control_version,v_now,v_now
    from exact_versions s
    where s.exact_document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning id
  ),
  invoice_state as (
    update public.invoices i set issue_state='PREPARING_DOCUMENT',
      active_issue_operation_id=s.operation_id,
      active_document_operation_id=case when s.exact_document_status='READY'
        then i.active_document_operation_id else s.doc_operation_id end,
      document_state=case when s.exact_document_status='READY'
        then i.document_state else 'PREPARING' end,updated_at=v_now
    from exact_versions s where i.id=s.invoice_id and i.status='DRAFT' returning i.id
  ),
  advanced as (
    update public.invoice_operation_chunks c set
      phase=case when s.exact_document_status='READY' then 'FINALISE' else 'WAIT_DOCUMENT' end,
      status=case when s.exact_document_status='READY' then 'QUEUED' else 'WAITING' end,
      document_version_id=s.document_version_id,
      payload_json=c.payload_json||jsonb_build_object('frozen_document_revision',s.document_revision,
        'document_version_id',s.document_version_id,'document_operation_id',s.doc_operation_id,
        'snapshot_hash',s.snapshot_hash,
        'routing_request',s.snapshot->'routing_request',
        'frozen_delivery_route',s.snapshot->'delivery_route',
        'delivery_request_token',s.snapshot->>'delivery_request_token'),
      progress_json=jsonb_build_object('status_message',
        case when s.exact_document_status='READY'
          then 'Exact final document is ready' else 'Final issue document is preparing' end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from exact_versions s where c.id=s.chunk_id
    returning c.id,c.status,c.phase,c.document_version_id
  ),
  freeze_outcomes as (
    select id,status,phase,document_version_id from advanced
    union all
    select id,status,phase,document_version_id from presentation_blocked
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,
    'document_version_id',document_version_id)),'[]') into v_part from freeze_outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- WAIT_DOCUMENT observes only the exact row and never R2.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='WAIT_DOCUMENT'
  ),
  updated as (
    update public.invoice_operation_chunks c set
      phase=case when v.status='READY' then 'FINALISE'
                 when v.status in ('FAILED','SUPERSEDED','CANCELLED') then 'BLOCKED'
                 else 'WAIT_DOCUMENT' end,
      status=case when v.status='READY' then 'QUEUED'
                  when v.status in ('FAILED','SUPERSEDED','CANCELLED') then 'BLOCKED'
                  else 'WAITING' end,
      error_json=case when v.status in ('FAILED','SUPERSEDED','CANCELLED')
        then jsonb_build_object('code','FINAL_DOCUMENT_'||v.status,'document_version_id',v.id,'detail',v.error_json)
        else null end,run_after_utc=case when v.status='READY' then v_now else c.run_after_utc end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from ids x,public.invoice_document_versions v
    where c.id=x.chunk_id and v.id=c.document_version_id
    returning c.id,c.status,c.phase,c.error_json
  ),
  missing as (
    update public.invoice_operation_chunks c set
      phase='BLOCKED',status='BLOCKED',
      error_json=jsonb_build_object(
        'code','FINAL_DOCUMENT_VERSION_MISSING',
        'document_version_id',c.document_version_id),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from ids x
    where c.id=x.chunk_id
      and not exists(
        select 1 from public.invoice_document_versions v
        where v.id=c.document_version_id)
    returning c.id,c.status,c.phase,c.error_json
  ),
  outcomes as (
    select * from updated
    union all
    select * from missing
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]')
    into v_part from outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- FINALISE is the only legal issue transition and demands the exact verified version.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='FINALISE'
  ),
  locked_invoices as materialized (
    select invoice.id
    from ids supplied
    join public.invoice_operation_chunks carrier
      on carrier.id=supplied.chunk_id
    join public.invoices invoice
      on invoice.id=carrier.entity_id
    order by invoice.id
    for update of invoice
  ),
  eligible as materialized (
    select c.*,i.document_revision,v.id final_document_version_id,v.r2_key,v.sha256,v.size_bytes,v.page_count,
      v.verified_at_utc,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'issue_date_utc',''),'timestamptz')
        then (v.snapshot_json->>'issue_date_utc')::timestamptz
        else v_now end issue_at,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'tax_point_utc',''),'timestamptz')
        then (v.snapshot_json->>'tax_point_utc')::timestamptz end tax_point_at,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'due_date_utc',''),'timestamptz')
        then (v.snapshot_json->>'due_date_utc')::timestamptz end due_at,
      v.snapshot_hash
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
    join locked_invoices locked_invoice on locked_invoice.id=c.entity_id
    join public.invoices i on i.id=locked_invoice.id and i.status='DRAFT'
      and i.issue_state='PREPARING_DOCUMENT'
      and i.active_issue_operation_id=c.operation_id
    join public.invoice_document_versions v on v.id=c.document_version_id and v.purpose='FINAL_ISSUE'
      and v.entity_type='INVOICE' and v.entity_id=c.entity_id
      and v.status='READY' and v.verified_at_utc is not null and v.r2_key is not null
      and v.sha256 is not null and v.size_bytes>0 and v.page_count>0
    where case when pg_input_is_valid(
        nullif(c.payload_json->>'frozen_document_revision',''),'bigint')
      then(c.payload_json->>'frozen_document_revision')::bigint=i.document_revision
      else false end
      and v.source_revision=i.document_revision::text
      and c.payload_json->>'snapshot_hash'=v.snapshot_hash
  ),
  issued as (
    update public.invoices i set status='ISSUED',status_date_utc=v_now,
      issued_at_utc=e.issue_at,due_at_utc=e.due_at,
      on_hold_reason=null,issued_document_version_id=e.final_document_version_id,
      invoice_pdf_r2_key=e.r2_key,invoice_pdf_generated_at_utc=e.verified_at_utc,
      issue_state='ISSUED',document_state='READY',active_issue_operation_id=null,
      active_document_operation_id=case
        when pg_input_is_valid(
          nullif(e.payload_json->>'document_operation_id',''),'uuid')
          then case when i.active_document_operation_id=
              (e.payload_json->>'document_operation_id')::uuid
            then null else i.active_document_operation_id end
        else i.active_document_operation_id end,updated_at=v_now
    from eligible e where i.id=e.entity_id returning i.id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoice',e.entity_id::text,'INVOICE_ISSUED',
      jsonb_build_object('invoice_id',e.entity_id,'document_version_id',e.final_document_version_id,
        'issue_at_utc',e.issue_at,'tax_point_utc',e.tax_point_at,'due_at_utc',e.due_at,
        'sha256',e.sha256,'size_bytes',e.size_bytes,'page_count',e.page_count),'INVOICE_OPERATION_QUEUE'
    from eligible e join public.invoice_operations o on o.id=e.operation_id
    left join public.tms_users u on u.id=o.actor_user_id returning id
  ),
  advanced as (
    update public.invoice_operation_chunks c set
      phase=case when lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes') then 'QUEUE_DELIVERY' else 'COMPLETE' end,
      status=case when lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes') then 'QUEUED' else 'COMPLETE' end,
      completed_at_utc=case when lower(coalesce(
        c.payload_json->>'deliver','false')) in('true','t','1','yes')
        then null else v_now end,
      result_json=jsonb_build_object('invoice_id',e.entity_id,'document_version_id',e.final_document_version_id,
        'issue_at_utc',e.issue_at,'tax_point_utc',e.tax_point_at,'due_at_utc',e.due_at,
        'r2_key',e.r2_key,'sha256',e.sha256,'size_bytes',e.size_bytes,'page_count',e.page_count),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from eligible e where c.id=e.id
    returning c.id,c.status,c.phase,c.result_json,c.error_json
  ),
  ineligible as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','ISSUE_FINALISE_OWNERSHIP_OR_DOCUMENT_MISMATCH',
          'invoice_id',c.entity_id,
          'document_version_id',c.document_version_id),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from ids x
    where c.id=x.chunk_id
      and not exists(select 1 from eligible e where e.id=c.id)
    returning c.id,c.status,c.phase,c.result_json,c.error_json
  ),
  outcomes as (
    select * from advanced
    union all
    select * from ineligible
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]')
    into v_part from outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- QUEUE_DELIVERY durably delegates to the single delivery-routing authority.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then (x->>'chunk_id')::uuid end chunk_id
    from jsonb_array_elements(p_claims) x
    where x->>'phase'='QUEUE_DELIVERY'
  ),
  delivery_specs as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,c.entity_id invoice_id,
      o.actor_user_id,i.issued_document_version_id,
      coalesce(c.payload_json->'delivery_intent','{}'::jsonb) delivery_intent,
      coalesce(c.payload_json->'routing_request','{}'::jsonb)
        routing_request,
      coalesce(c.payload_json->'frozen_delivery_route','{}'::jsonb)
        frozen_delivery_route,
      coalesce(nullif(c.payload_json->>'delivery_request_token',''),
        'ISSUE:'||coalesce(c.payload_json->>'command_token',c.id::text))
        delivery_request_token,
      nullif(c.payload_json#>>'{frozen_delivery_route,template_version}','')
        template_version,
      nullif(c.payload_json#>>'{frozen_delivery_route,recipient_set_hash}','')
        recipient_set_hash,
      nullif(c.payload_json#>>'{frozen_delivery_route,route_policy_hash}','')
        route_policy_hash,
      coalesce(c.payload_json#>'{frozen_delivery_route,to}','[]'::jsonb)
        canonical_to,
      coalesce(c.payload_json#>'{frozen_delivery_route,cc}','[]'::jsonb)
        canonical_cc,
      coalesce(c.payload_json#>'{frozen_delivery_route,bcc}','[]'::jsonb)
        canonical_bcc,
      lower(coalesce(
        c.payload_json#>>'{frozen_delivery_route,do_not_send}','false'))
        in('true','t','1','yes') do_not_send,
      lower(coalesce(
        c.payload_json#>>'{frozen_delivery_route,delivery_suppressed}','false'))
        in('true','t','1','yes') delivery_suppressed,
      c.payload_json#>>'{frozen_delivery_route,route_source}' route_source,
      coalesce(c.payload_json#>'{frozen_delivery_route,warning_codes}',
        '[]'::jsonb) route_warnings,
      coalesce(c.payload_json#>'{frozen_delivery_route,blocker_codes}',
        '[]'::jsonb) route_blockers,
      c.payload_json#>>'{frozen_delivery_route,route_policy_hash}' is not null
        and c.payload_json#>>'{frozen_delivery_route,recipient_set_hash}'
          is not null
        and c.payload_json#>>'{frozen_delivery_route,template_version}'
          is not null
        and upper(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_policy}',''))
          in('ATTACH','SPLIT','SECURE_LINK')
        and lower(coalesce(
          c.payload_json#>>'{frozen_delivery_route,do_not_send}','false'))
          not in('true','t','1','yes')
        and lower(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_suppressed}','false'))
          not in('true','t','1','yes')
        and (case
          when jsonb_typeof(c.payload_json#>'{frozen_delivery_route,blocker_codes}')='array'
            then jsonb_array_length(c.payload_json#>'{frozen_delivery_route,blocker_codes}')
          when c.payload_json#>'{frozen_delivery_route,blocker_codes}' is null then 0
          else 1
        end)=0
        frozen_route_usable,
      coalesce(case when coalesce(c.payload_json#>>'{delivery_intent,part_number}','') ~
        '^[0-9]+$' then(c.payload_json#>>'{delivery_intent,part_number}')::integer end,1)
        part_number,
      case when upper(coalesce(
          c.payload_json#>>'{delivery_intent,delivery_policy}','')) in(
            'ATTACH','SPLIT','SECURE_LINK')
        then upper(c.payload_json#>>'{delivery_intent,delivery_policy}')
        when upper(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_policy}','')) in(
            'ATTACH','SPLIT','SECURE_LINK')
        then upper(c.payload_json#>>'{frozen_delivery_route,delivery_policy}')
      end delivery_policy
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoice_operations o on o.id=c.operation_id
    join public.invoices i on i.id=c.entity_id and i.status='ISSUED'
      and i.issued_document_version_id=c.document_version_id
  ),
  delivery_groups as materialized (
    select d.parent_operation_id,
      (array_agg(d.actor_user_id order by d.chunk_id))[1] actor_user_id,
      (array_agg(d.template_version order by d.chunk_id))[1] template_version,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.route_policy_hash),'||' order by d.invoice_id),'sha256'),'hex')
        route_policy_hash,
      (array_agg(d.delivery_policy order by d.chunk_id))[1] delivery_policy,
      array_agg(d.invoice_id order by d.invoice_id) invoice_ids,
      array_agg(d.issued_document_version_id order by d.invoice_id)
        issued_document_version_ids,
      array_agg(d.delivery_request_token order by d.invoice_id)
        delivery_request_tokens,
      count(*)::integer unit_count,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.issued_document_version_id::text,d.delivery_request_token),
        '||' order by d.invoice_id),'sha256'),'hex') group_request_hash,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.issued_document_version_id::text,d.delivery_request_token,
        d.route_policy_hash),
        '||' order by d.invoice_id),'sha256'),'hex') delivery_revision,
      encode(digest(concat_ws('|','DELIVER_INVOICES',d.parent_operation_id::text,
        encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
          d.issued_document_version_id::text,d.delivery_request_token),
          '||' order by d.invoice_id),'sha256'),'hex')),'sha256'),'hex')
        delivery_key
    from delivery_specs d
    group by d.parent_operation_id
  ),
  existing_delivery as materialized (
    select g.parent_operation_id,o.id operation_id,o.control_version,o.status
    from delivery_groups g join lateral(
      select x.* from public.invoice_operations x
      where x.idempotency_key=g.delivery_key
        and x.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(x.status='COMPLETE') desc,x.created_at_utc desc limit 1
    ) o on true
  ),
  inserted_delivery as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,
      entity_type,entity_id,actor_user_id,idempotency_key,status,phase,priority,
      source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,requires_user_action,
      error_json,created_at_utc,updated_at_utc)
    select g.parent_operation_id,'DELIVER_INVOICES','INVOICE_BATCH',null,
      g.actor_user_id,g.delivery_key,'QUEUED','PREPARE',700,
      g.delivery_revision,g.template_version,
      jsonb_build_object('invoice_ids',to_jsonb(g.invoice_ids),
        'issued_document_version_ids',to_jsonb(g.issued_document_version_ids),
        'template_version',g.template_version,
        'delivery_request_tokens',to_jsonb(g.delivery_request_tokens),
        'group_request_hash',g.group_request_hash,
        'route_policy_hash',g.route_policy_hash,
        'delivery_policy',g.delivery_policy),
      jsonb_build_object(
        'delivery_request_tokens',to_jsonb(g.delivery_request_tokens),
        'group_request_hash',g.group_request_hash,
        'route_policy_hash',g.route_policy_hash,
        'processor_policy',parent.config_json->'processor_policy'),
      jsonb_build_object('status_message','Batch delivery preparation queued'),
      g.unit_count,g.unit_count,1,nextval('public.invoice_operation_change_seq'),
      false,null,v_now,v_now
    from delivery_groups g
    join public.invoice_operations parent on parent.id=g.parent_operation_id
    where not exists(
      select 1 from existing_delivery e
      where e.parent_operation_id=g.parent_operation_id)
    on conflict do nothing
    returning *
  ),
  selected_delivery_groups as materialized (
    select g.*,coalesce(e.operation_id,n.id) delivery_operation_id,
      coalesce(e.control_version,n.control_version) delivery_control_version,
      coalesce(e.status,n.status) delivery_status
    from delivery_groups g
    left join existing_delivery e
      on e.parent_operation_id=g.parent_operation_id
    left join inserted_delivery n on n.idempotency_key=g.delivery_key
  ),
  selected_delivery as materialized (
    select d.*,g.delivery_operation_id,g.delivery_control_version,
      g.delivery_status
    from delivery_specs d
    join selected_delivery_groups g
      on g.parent_operation_id=d.parent_operation_id
  ),
  delivery_chunk_specs as materialized (
    select d.*,gen_random_uuid() delivery_chunk_id
    from selected_delivery d
    where d.delivery_status<>'COMPLETE'
  ),
  delivery_chunks as (
    insert into public.invoice_operation_chunks(id,operation_id,chunk_type,phase,
      work_key,sequence_no,entity_type,entity_id,document_version_id,status,priority,
      run_after_utc,payload_json,error_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select d.delivery_chunk_id,d.delivery_operation_id,'DELIVERY_PREPARE',
      case when d.frozen_route_usable then 'PREPARE' else 'BLOCKED' end,
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        d.issued_document_version_id::text,d.route_policy_hash,
        d.template_version,d.part_number::text,d.delivery_request_token),
        'sha256'),'hex'),
      row_number() over(partition by d.delivery_operation_id
        order by d.invoice_id)::integer-1,
      'INVOICE',d.invoice_id,d.issued_document_version_id,
      case when d.frozen_route_usable then 'QUEUED' else 'BLOCKED' end,
      700,v_now,
      jsonb_build_object('request_key',d.delivery_chunk_id::text,
        'invoice_id',d.invoice_id,
        'issued_document_version_id',d.issued_document_version_id,
        'recipient_set',d.canonical_to,'cc',d.canonical_cc,'bcc',d.canonical_bcc,
        'recipient_set_hash',d.recipient_set_hash,'template_version',d.template_version,
        'route_policy_hash',d.route_policy_hash,
        'delivery_part_number',d.part_number,'do_not_send',d.do_not_send,
        'delivery_suppressed',d.delivery_suppressed,
        'delivery_policy',d.delivery_policy,
        'route_source',d.route_source,
        'delivery_request_token',d.delivery_request_token,
        'routing_request',d.routing_request,
        'frozen_delivery_route',d.frozen_delivery_route),
      case when d.frozen_route_usable then null else jsonb_build_object(
        'code','FROZEN_DELIVERY_ROUTE_UNUSABLE',
        'frozen_route',d.frozen_delivery_route,
        'route_blockers',d.route_blockers) end,
      d.delivery_control_version,v_now,v_now
    from delivery_chunk_specs d
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning id
  ),
  completed_delivery_request as (
    update public.invoice_operation_chunks c set status='COMPLETE',phase='COMPLETE',
      completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      payload_json=coalesce(c.payload_json,'{}'::jsonb)
        || jsonb_build_object(
          'blocked_for_sending',
          not d.frozen_route_usable
        ),
      result_json=coalesce(c.result_json,'{}')||jsonb_build_object(
        'delivery_operation_id',d.delivery_operation_id,
        'delivery_status',case when d.frozen_route_usable
          then d.delivery_status else 'BLOCKED' end,
        'delivery_requested',true,
        'delivery_request_token',d.delivery_request_token,
        'delivery_blocker',case when d.frozen_route_usable then null
          else jsonb_build_object('code','FROZEN_DELIVERY_ROUTE_UNUSABLE',
            'frozen_route',d.frozen_delivery_route,
            'route_blockers',d.route_blockers) end)
    from selected_delivery d where c.id=d.chunk_id
    returning c.id,c.status,c.phase,c.result_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,
    'phase',phase,'result',result_json)),'[]') into v_part
  from completed_delivery_request;
  v_result:=v_result||coalesce(v_part,'[]');

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

-- private._invoice_issue_validate_batch(jsonb,date)
CREATE OR REPLACE FUNCTION private._invoice_issue_validate_batch(p_requests jsonb, p_evaluation_date date)
 RETURNS TABLE(request_key text, invoice_id uuid, hard_blocker_codes jsonb, document_dependency_codes jsonb, delivery_blocker_codes jsonb, warning_codes jsonb, can_issue_only boolean, can_issue_and_deliver boolean, route_policy_result jsonb, detail_json jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
with raw as materialized (
  select x.ordinality::integer request_no,
      nullif(btrim(coalesce(x.value->>'request_key','')),'') request_key,
      case when coalesce(x.value->>'invoice_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (x.value->>'invoice_id')::uuid end invoice_id,
      case when coalesce(x.value->>'operation_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (x.value->>'operation_id')::uuid end operation_id,
      case when jsonb_typeof(x.value->'expected_revision')='number'
        and coalesce(x.value->>'expected_revision','')~'^[0-9]+$'
        then (x.value->>'expected_revision')::bigint end expected_revision,
      case when jsonb_typeof(x.value->'allow_early')='boolean'
        then(x.value->>'allow_early')::boolean else false end allow_early,
      case when jsonb_typeof(x.value->'deliver')='boolean'
        then(x.value->>'deliver')::boolean else false end deliver,
      case when jsonb_typeof(x.value->'recipient_set')='array'
        then x.value->'recipient_set' else '[]'::jsonb end recipient_set,
      case when jsonb_typeof(x.value->'cc')='array'
        then x.value->'cc' else '[]'::jsonb end cc,
      case when jsonb_typeof(x.value->'bcc')='array'
        then x.value->'bcc' else '[]'::jsonb end bcc,
      jsonb_typeof(x.value->'expected_revision')='number'
        and coalesce(x.value->>'expected_revision','')~'^[0-9]+$'
        expected_revision_well_formed,
      (not (x.value ? 'allow_early')
        or jsonb_typeof(x.value->'allow_early')='boolean')
        allow_early_well_formed,
      (not (x.value ? 'deliver')
        or jsonb_typeof(x.value->'deliver')='boolean')
        deliver_well_formed
    from jsonb_array_elements(
      case when jsonb_typeof(p_requests)='array' then p_requests else '[]'::jsonb end)
      with ordinality x(value,ordinality)
    where jsonb_typeof(x.value)='object'
),
invoice_scope as materialized (
  select distinct r.invoice_id
  from raw r
  where r.invoice_id is not null
),
request_counts as materialized (
  select r.request_key,count(*)::integer request_key_count
  from raw r where r.request_key is not null group by r.request_key
),
invoice_ids as materialized (
  select coalesce(array_agg(r.invoice_id order by r.invoice_id),array[]::uuid[]) ids
  from invoice_scope r
),
references_batch as materialized (
  select r.*
  from invoice_ids i
  cross join lateral private._invoice_reference_rows_batch(i.ids) r
),
correction_scopes as materialized (
  select coalesce(jsonb_agg(jsonb_build_object(
    'request_key',r.request_key,
    'scope_key',r.request_key,
    'invoice_id',r.invoice_id,
    'validation_purpose','ISSUE',
    'expected_client_id',i.client_id,
    'expected_invoice_stream',case
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then upper(coalesce(
          nullif(i.header_snapshot_json#>>'{meta,invoice_stream}',''),
          nullif(i.header_snapshot_json->>'invoice_stream',''),
          case when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))
            in('true','t','1','yes') then 'SELF_BILL' else 'NORMAL' end))
      when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))
        in('true','t','1','yes') then 'SELF_BILL'
      else 'NORMAL'
    end,
    'planned_members',coalesce((select jsonb_agg(jsonb_build_object(
      'timesheet_id',l.timesheet_id,
      'vat_rate_pct',l.vat_rate_pct)
      order by l.timesheet_id,l.id)
      from public.invoice_lines l
      where l.invoice_id=r.invoice_id and l.timesheet_id is not null),
      '[]'::jsonb)) order by r.request_no),'[]'::jsonb) scopes
  from raw r
  left join public.invoices i on i.id=r.invoice_id
  where r.invoice_id is not null
),
corrections as materialized (
  select c.*
  from correction_scopes s
  cross join lateral private._invoice_correction_validate_batch(
    s.scopes,p_evaluation_date) c
),
routes as materialized (
  select d.*
  from private._invoice_delivery_routes_batch(
    (select coalesce(jsonb_agg(jsonb_build_object(
      'request_key',r.request_key,'invoice_id',r.invoice_id,
      'recipient_set',r.recipient_set,
      'cc',r.cc,'bcc',r.bcc)),'[]'::jsonb) from raw r),
    p_evaluation_date) d
),
line_totals as materialized (
  select r.invoice_id,count(l.id) line_count,
    round(coalesce(sum(l.total_charge_ex_vat),0),2) net,
    round(coalesce(sum(l.vat_amount),0),2) vat,
    round(coalesce(sum(l.total_inc_vat),0),2) gross,
    count(*) filter(where upper(coalesce(l.meta_json->>'line_type',''))
      like '%HIGHER_RATE%'
      and not exists(
        select 1 from public.invoice_hr_source_rows hs
        where hs.invoice_id=r.invoice_id
          and hs.source_system in('HEALTHROSTER','NHSP')))
      missing_higher_rate
  from invoice_scope r
  left join public.invoice_lines l on l.invoice_id=r.invoice_id
  group by r.invoice_id
),
source_requirements as materialized (
  select l.invoice_id,l.timesheet_id,
    bool_or(
      upper(coalesce(l.meta_json->>'line_type','')) like 'HOURS%'
      or upper(coalesce(l.meta_json->>'line_type',''))
        like 'ADDITIONAL_RATE%') reference_required,
    bool_or(
      upper(coalesce(l.meta_json->>'line_type','')) in(
        'EXPENSE_MILEAGE','MILEAGE')
      or coalesce(l.source_key,'') like '%:MILEAGE') mileage_required,
    bool_or(upper(coalesce(l.meta_json->>'line_type',''))
      like '%TRAVEL%') travel_required,
    bool_or(upper(coalesce(l.meta_json->>'line_type',''))
      like '%ACCOMMODATION%') accommodation_required,
    bool_or(
      upper(coalesce(l.meta_json->>'line_type','')) in(
        'EXPENSES_TOTAL','EXPENSE_TOTAL','OTHER_EXPENSE','EXPENSE_OTHER')
      or(
        upper(coalesce(l.meta_json->>'line_type','')) like 'EXPENSE_%'
        and upper(coalesce(l.meta_json->>'line_type','')) not in(
          'EXPENSE_MILEAGE','EXPENSE_TRAVEL','EXPENSE_ACCOMMODATION')))
      general_expense_required
  from public.invoice_lines l
  join invoice_scope s on s.invoice_id=l.invoice_id
  where l.timesheet_id is not null
  group by l.invoice_id,l.timesheet_id
),
timesheet_state as materialized (
  select s.invoice_id,s.timesheet_id,s.reference_required,
    s.mileage_required,s.travel_required,s.accommodation_required,
    s.general_expense_required,
    t.timesheet_id is not null source_exists,
    upper(coalesce(t.submission_mode::text,'')) submission_mode,
    coalesce(pc.effective_ts_attach_to_invoice,true)
      and not coalesce(summary.client_no_timesheet_required,false)
      and not coalesce(summary.client_is_nhsp,false) document_required,
    coalesce(pc.issue_missing_reference,false) issue_missing_reference,
    manual_source.evidence_id manual_source_evidence_id,
    coalesce(t.manual_document_asset_id,manual_source.document_asset_id)
      manual_document_asset_id,
    manual_asset.status manual_asset_status,
    manual_asset.operation_id manual_asset_operation_id,
    manual_asset_op.status manual_asset_operation_status,
    v.id timesheet_document_version_id,
    v.status timesheet_document_status,
    v.operation_id timesheet_document_operation_id,
    vop.status timesheet_document_operation_status,
    t.document_revision timesheet_document_revision,
    upper(coalesce(t.submission_mode::text,''))='QR'
      and(nullif(t.qr_signed_hash,'') is null
        or t.qr_signed_at_utc is null) qr_unsigned
  from source_requirements s
  left join public.timesheets t
    on t.timesheet_id=s.timesheet_id and t.is_current
  left join public.v_ts_invoice_precheck pc on pc.timesheet_id=s.timesheet_id
  left join public.v_timesheets_summary_base summary
    on summary.timesheet_id=s.timesheet_id
  left join lateral (
    select ev.id evidence_id,ev.document_asset_id
    from public.timesheet_evidence ev
    left join public.invoice_document_assets candidate_asset
      on candidate_asset.id=ev.document_asset_id
    where ev.timesheet_id=t.timesheet_id
      and upper(coalesce(ev.kind,''))='TIMESHEET'
      and coalesce(ev.processing_state,'')<>'SUPERSEDED'
    order by(ev.document_asset_id=t.manual_document_asset_id) desc,
      (candidate_asset.status='READY') desc,
      ev.created_at desc nulls last,ev.id desc
    limit 1
  ) manual_source on true
  left join public.invoice_document_assets manual_asset
    on manual_asset.id=coalesce(t.manual_document_asset_id,
      manual_source.document_asset_id)
  left join public.invoice_operations manual_asset_op
    on manual_asset_op.id=manual_asset.operation_id
  left join lateral (
    select dv.*
    from public.invoice_document_versions dv
    where dv.entity_type='TIMESHEET' and dv.entity_id=t.timesheet_id
      and dv.purpose='TIMESHEET'
      and dv.source_revision=t.document_revision::text
      and dv.template_version='timesheet-professional-v1'
      and dv.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
        'VERIFYING','READY','FAILED','SUPERSEDED','CANCELLED')
    order by
      (dv.status='READY') desc,
      (dv.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING',
        'ASSEMBLING','VERIFYING')) desc,
      dv.created_at_utc desc,dv.id desc
    limit 1
  ) v on true
  left join public.invoice_operations vop on vop.id=v.operation_id
),
timesheet_readiness as materialized (
  select t.*,
    case
      when not t.document_required then 'NOT_REQUIRED'
      when not t.source_exists then 'SOURCE_MISSING'
      when t.qr_unsigned then 'QR_UNSIGNED'
      when t.submission_mode in('MANUAL','QR')
        and t.manual_document_asset_id is null then 'MANUAL_SOURCE_MISSING'
      when t.submission_mode in('MANUAL','QR')
        and t.manual_document_asset_id is not null
        and t.manual_asset_status is null then 'ASSET_NOT_REGISTERED'
      when t.submission_mode in('MANUAL','QR') and(
        t.manual_asset_status in(
          'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
        or t.manual_asset_operation_status='DEAD_LETTER')
        then 'ASSET_PERMANENT_FAILURE'
      when t.submission_mode in('MANUAL','QR')
        and t.manual_asset_status in('DISCOVERED','INSPECTING','NORMALISING')
        and coalesce(t.manual_asset_operation_status,'') not in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT')
        then 'ASSET_WORKFLOW_MISSING'
      when t.submission_mode in('MANUAL','QR')
        and t.manual_asset_status in('DISCOVERED','INSPECTING','NORMALISING')
        then 'ASSET_IN_PROGRESS'
      when t.timesheet_document_status='READY' then 'DOCUMENT_READY'
      when t.timesheet_document_status in('FAILED','SUPERSEDED','CANCELLED')
        and coalesce(t.timesheet_document_operation_status,'') not in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT')
        then 'DOCUMENT_PERMANENT_FAILURE'
      when t.timesheet_document_status in(
          'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING')
        or t.timesheet_document_operation_status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT')
        then 'DOCUMENT_IN_PROGRESS'
      else 'DOCUMENT_CREATABLE'
    end readiness_classification
  from timesheet_state t
),
timesheet_readiness_json as materialized (
  select t.invoice_id,jsonb_agg(jsonb_build_object(
    'timesheet_id',t.timesheet_id,
    'required',t.document_required,
    'submission_mode',t.submission_mode,
    'readiness_classification',t.readiness_classification,
    'manual_source_evidence_id',t.manual_source_evidence_id,
    'manual_document_asset_id',t.manual_document_asset_id,
    'manual_asset_status',t.manual_asset_status,
    'manual_asset_operation_id',t.manual_asset_operation_id,
    'manual_asset_operation_status',t.manual_asset_operation_status,
    'timesheet_document_revision',t.timesheet_document_revision,
    'timesheet_document_version_id',t.timesheet_document_version_id,
    'timesheet_document_status',t.timesheet_document_status,
    'timesheet_document_operation_id',t.timesheet_document_operation_id,
    'timesheet_document_operation_status',t.timesheet_document_operation_status,
    'qr_unsigned',t.qr_unsigned)
    order by t.timesheet_id) readiness_rows
  from timesheet_readiness t
  group by t.invoice_id
),timesheet_checks as materialized (
  select i.invoice_id,
    count(*) filter(where t.document_required and not t.source_exists)
      missing_timesheet,
    count(*) filter(where t.document_required and t.source_exists
      and t.submission_mode in('MANUAL','QR')
      and t.manual_document_asset_id is null) missing_manual_source,
    count(*) filter(where t.document_required and t.source_exists
      and t.submission_mode in('MANUAL','QR')
      and t.manual_document_asset_id is not null
      and t.manual_asset_status is null) missing_asset_registration,
    count(*) filter(where t.document_required and t.qr_unsigned)
      unsigned_qr_source,
    count(*) filter(where t.reference_required
      and t.issue_missing_reference) missing_reference,
    count(*) filter(where t.document_required and t.source_exists
      and t.submission_mode in('MANUAL','QR')
      and(
        t.manual_asset_status in(
          'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
        or t.manual_asset_operation_status='DEAD_LETTER'))
      permanently_failed_required_asset,
    count(*) filter(where t.document_required and t.source_exists
      and t.submission_mode in('MANUAL','QR')
      and t.manual_asset_status in('DISCOVERED','INSPECTING','NORMALISING')
      and coalesce(t.manual_asset_operation_status,'') not in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT'))
      missing_asset_workflow,
    count(*) filter(where t.document_required and t.source_exists
      and t.submission_mode in('MANUAL','QR')
      and t.manual_asset_status in('DISCOVERED','INSPECTING','NORMALISING')
      and t.manual_asset_operation_status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT'))
      queueable_required_asset,
    count(*) filter(where t.document_required and t.source_exists
      and t.timesheet_document_status in(
        'FAILED','SUPERSEDED','CANCELLED')
      and coalesce(t.timesheet_document_operation_status,'') not in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT'))
      permanently_failed_timesheet_document,
    count(*) filter(where t.document_required and t.source_exists
      and coalesce(t.timesheet_document_status,'')<>'READY'
      and(
        t.timesheet_document_status in(
          'PLANNING','WAITING_FOR_INPUTS','RENDERING',
          'ASSEMBLING','VERIFYING')
        or t.timesheet_document_operation_status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT')
        or(
          t.timesheet_document_version_id is null
          and t.submission_mode not in('MANUAL','QR'))
        or(
          t.timesheet_document_version_id is null
          and t.submission_mode in('MANUAL','QR')
          and t.manual_asset_status='READY')
      )) queueable_timesheet_document
  from invoice_scope i
  left join timesheet_readiness t on t.invoice_id=i.invoice_id
  group by i.invoice_id
),
import_source_requirements as materialized (
  select distinct s.invoice_id,s.timesheet_id,
    case
      when coalesce(summary.client_is_nhsp,false)
        or upper(coalesce(summary.route_type,'')) like '%NHSP%'
        or upper(coalesce(financial.basis::text,'')) like 'NHSP%'
        then 'NHSP'
      when upper(coalesce(summary.route_type,'')) like '%HEALTHROSTER%'
        or upper(coalesce(financial.basis::text,'')) in(
          'HEALTHROSTER','HEALTHROSTER_ADJUSTMENT','HR_WEEKLY','HR_DAILY')
        then 'HEALTHROSTER'
    end source_system,
    financial.nhsp_import_id import_id
  from source_requirements s
  left join public.v_timesheets_summary_base summary
    on summary.timesheet_id=s.timesheet_id
  left join public.timesheets_financials financial
    on financial.timesheet_id=s.timesheet_id and financial.is_current
  join public.invoices invoice_policy on invoice_policy.id=s.invoice_id
  where (
      coalesce(summary.client_is_nhsp,false)
      or upper(coalesce(summary.route_type,'')) like '%NHSP%'
      or upper(coalesce(financial.basis::text,'')) like 'NHSP%'
    )
    or (
      (
        upper(coalesce(summary.route_type,'')) like '%HEALTHROSTER%'
        or upper(coalesce(financial.basis::text,'')) in(
          'HEALTHROSTER','HEALTHROSTER_ADJUSTMENT','HR_WEEKLY','HR_DAILY')
      )
      and coalesce(
        (invoice_policy.header_snapshot_json#>>'{attach_policy,hr_attach_to_invoice}')::boolean,
        true
      )
    )
),
import_source_checks as materialized (
  select i.invoice_id,
    count(*) filter(where r.source_system is not null and not exists(
      select 1
      from public.invoice_hr_source_rows source
      where source.invoice_id=r.invoice_id
        and upper(coalesce(source.source_system,''))=r.source_system
        and(r.import_id is null or source.import_id=r.import_id)
        and jsonb_typeof(source.rows_json)='array'
        and jsonb_array_length(source.rows_json)>0
    )) missing_import_source
  from invoice_scope i
  left join import_source_requirements r on r.invoice_id=i.invoice_id
  group by i.invoice_id
),
evidence_requirements as materialized (
  select s.invoice_id,s.timesheet_id,'MILEAGE'::text requirement
  from source_requirements s where s.mileage_required
  union all
  select s.invoice_id,s.timesheet_id,'TRAVEL'
  from source_requirements s where s.travel_required
  union all
  select s.invoice_id,s.timesheet_id,'ACCOMMODATION'
  from source_requirements s where s.accommodation_required
  union all
  select s.invoice_id,s.timesheet_id,'GENERAL_EXPENSE'
  from source_requirements s where s.general_expense_required
),
evidence_state as materialized (
  select r.*,e.id evidence_id,e.document_asset_id,
    a.status asset_status,op.status asset_operation_status
  from evidence_requirements r
  left join lateral (
    select ev.*
    from public.timesheet_evidence ev
    left join public.invoice_document_assets candidate_asset
      on candidate_asset.id=ev.document_asset_id
    where ev.timesheet_id=r.timesheet_id
      and(
        upper(coalesce(ev.kind,''))=r.requirement
        or r.requirement='GENERAL_EXPENSE'
          and upper(coalesce(ev.kind,'')) in('OTHER','EXPENSE','EXPENSES'))
    order by
      (candidate_asset.status='READY') desc,
      (candidate_asset.status in(
        'DISCOVERED','INSPECTING','NORMALISING')) desc,
      ev.created_at desc nulls last,ev.id desc
    limit 1
  ) e on true
  left join public.invoice_document_assets a on a.id=e.document_asset_id
  left join public.invoice_operations op on op.id=a.operation_id
),
evidence_checks as materialized (
  select i.invoice_id,
    count(*) filter(where e.requirement='MILEAGE'
      and e.evidence_id is null) missing_mileage,
    count(*) filter(where e.requirement<>'MILEAGE'
      and e.evidence_id is null) missing_expense,
    count(*) filter(where e.evidence_id is not null
      and(e.document_asset_id is null or e.asset_status is null))
      missing_asset_registration,
    count(*) filter(where e.asset_status in(
      'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
      or e.asset_operation_status='DEAD_LETTER')
      permanently_failed_required_asset,
    count(*) filter(where e.asset_status in(
      'DISCOVERED','INSPECTING','NORMALISING')
      and e.asset_operation_status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT'))
      queueable_required_asset,
    count(*) filter(where e.asset_status in(
      'DISCOVERED','INSPECTING','NORMALISING')
      and coalesce(e.asset_operation_status,'') not in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT'))
      missing_asset_workflow
  from invoice_scope i
  left join evidence_state e on e.invoice_id=i.invoice_id
  group by i.invoice_id
),
reference_checks as materialized (
  select r.invoice_id,
    count(*) filter(where
      coalesce(precheck.reference_number_required_to_issue_invoice,false)
      and nullif(btrim(ref.current_reference),'') is null)
      missing_required_reference
  from invoice_scope r
  left join references_batch ref on ref.invoice_id=r.invoice_id
  left join public.v_ts_invoice_precheck precheck
    on precheck.timesheet_id=ref.timesheet_id
  group by r.invoice_id
),
correction_checks as materialized (
  select r.invoice_id,
    count(*) filter(where not coalesce(c.valid,true)) invalid_correction,
    (array_agg(c.blocker_code order by c.request_key) filter(where not coalesce(c.valid,true)))[1]
      correction_blocker
  from invoice_scope r
  left join corrections c on c.invoice_id=r.invoice_id
  group by r.invoice_id
),
facts as materialized (
  select r.request_no,r.request_key,r.operation_id,r.expected_revision,
    r.allow_early,r.deliver,r.expected_revision_well_formed,
    r.allow_early_well_formed,r.deliver_well_formed,
    r.invoice_id,
    r.recipient_set,r.cc,r.bcc,
    coalesce(rkc.request_key_count,0) request_key_count,
    i.status invoice_status,i.document_revision,i.on_hold_reason,
    i.subtotal_ex_vat,i.vat_amount,i.total_inc_vat,i.header_snapshot_json,
    lt.line_count,lt.net,lt.vat,lt.gross,
    ec.missing_mileage,ec.missing_expense,lt.missing_higher_rate,
    isc.missing_import_source,
    tc.missing_timesheet,tc.missing_manual_source,tc.unsigned_qr_source,
    tc.missing_reference,
    coalesce(tc.missing_asset_registration,0)
      +coalesce(ec.missing_asset_registration,0) missing_asset_registration,
    coalesce(tc.missing_asset_workflow,0)
      +coalesce(ec.missing_asset_workflow,0) missing_asset_workflow,
    coalesce(tc.permanently_failed_required_asset,0)
      +coalesce(ec.permanently_failed_required_asset,0)
      permanently_failed_required_asset,
    coalesce(tc.queueable_required_asset,0)
      +coalesce(ec.queueable_required_asset,0) queueable_required_asset,
    tc.permanently_failed_timesheet_document,
    tc.queueable_timesheet_document,rc.missing_required_reference,
    cc.invalid_correction,cc.correction_blocker,
    tr.readiness_rows timesheet_readiness,
    dr.canonical_to,dr.canonical_cc,dr.canonical_bcc,
    dr.recipient_set_hash,dr.grouping_identity,
    dr.route_policy_hash,
    dr.route_source,dr.warning_codes route_warnings,
    dr.blocker_codes route_blockers,dr.do_not_send,
    dr.delivery_suppressed,
    exists(
      select 1 from public.invoice_operation_chunks oc
      join public.invoice_operations other_operation
        on other_operation.id=oc.operation_id
      where oc.chunk_type='ISSUE_INVOICE' and oc.entity_type='INVOICE'
        and oc.entity_id=r.invoice_id
        and(r.operation_id is null or oc.operation_id<>r.operation_id)
        and oc.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and other_operation.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
      conflicting_issue
  from raw r
  left join request_counts rkc on rkc.request_key=r.request_key
  left join public.invoices i on i.id=r.invoice_id
  left join line_totals lt on lt.invoice_id=r.invoice_id
  left join timesheet_checks tc on tc.invoice_id=r.invoice_id
  left join import_source_checks isc on isc.invoice_id=r.invoice_id
  left join evidence_checks ec on ec.invoice_id=r.invoice_id
  left join reference_checks rc on rc.invoice_id=r.invoice_id
  left join correction_checks cc on cc.invoice_id=r.invoice_id
  left join timesheet_readiness_json tr on tr.invoice_id=r.invoice_id
  left join routes dr
    on dr.request_key=r.request_key and dr.invoice_id=r.invoice_id
),
classified as materialized (
  select f.*,
    array_remove(array[
      case when f.request_key is null then 'REQUEST_KEY_REQUIRED' end,
      case when f.request_key_count>1 then 'REQUEST_KEY_DUPLICATE' end,
      case when p_evaluation_date is null then 'EVALUATION_DATE_REQUIRED' end,
      case when f.invoice_status is null then 'INVOICE_NOT_FOUND' end,
      case when not f.expected_revision_well_formed
        then 'EXPECTED_REVISION_INVALID' end,
      case when not f.allow_early_well_formed
        then 'ALLOW_EARLY_INVALID' end,
      case when not f.deliver_well_formed
        then 'DELIVERY_INTENT_INVALID' end,
      case when f.invoice_status='ON_HOLD' or f.on_hold_reason is not null
        then 'INVOICE_ON_HOLD' end,
      case when f.invoice_status is not null and f.invoice_status<>'DRAFT'
        then 'INVOICE_NOT_DRAFT' end,
      case when f.expected_revision is not null
        and f.expected_revision<>f.document_revision
        then 'SOURCE_REVISION_CHANGED' end,
      case when coalesce(f.line_count,0)=0
        or round(coalesce(f.subtotal_ex_vat,0),2)<>coalesce(f.net,0)
        or round(coalesce(f.vat_amount,0),2)<>coalesce(f.vat,0)
        or round(coalesce(f.total_inc_vat,0),2)<>coalesce(f.gross,0)
        then 'INVALID_TOTALS' end,
      case when coalesce(f.missing_required_reference,0)>0
        or coalesce(f.missing_reference,0)>0 then 'MISSING_REFERENCE' end,
      case when coalesce(f.missing_timesheet,0)>0 then 'MISSING_TIMESHEET' end,
      case when coalesce(f.missing_manual_source,0)>0
        then 'MANUAL_TIMESHEET_SOURCE_MISSING' end,
      case when coalesce(f.unsigned_qr_source,0)>0
        then 'QR_TIMESHEET_UNSIGNED' end,
      case when coalesce(f.missing_asset_registration,0)>0
        then 'ASSET_NOT_REGISTERED' end,
      case when coalesce(f.missing_asset_workflow,0)>0
        then 'ASSET_WORKFLOW_MISSING' end,
      case when coalesce(f.permanently_failed_required_asset,0)>0
        then 'REQUIRED_ASSET_FAILED' end,
      case when coalesce(f.permanently_failed_timesheet_document,0)>0
        then 'TIMESHEET_DOCUMENT_FAILED' end,
      case when coalesce(f.missing_mileage,0)>0
        then 'MISSING_MILEAGE_EVIDENCE' end,
      case when coalesce(f.missing_expense,0)>0
        then 'MISSING_EXPENSE_EVIDENCE' end,
      case when coalesce(f.missing_higher_rate,0)>0
        then 'MISSING_HIGHER_RATE_SUPPORT' end,
      case when coalesce(f.missing_import_source,0)>0
        then 'MISSING_IMPORT_SOURCE_EVIDENCE' end,
      case when coalesce(f.invalid_correction,0)>0
        then coalesce(f.correction_blocker,'CORRECTION_LINES_NOT_UNIT_SAFE') end,
      case when not f.allow_early
        and coalesce(
          case when coalesce(f.header_snapshot_json#>>'{meta,invoice_week_start}','')
            ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            then (f.header_snapshot_json#>>'{meta,invoice_week_start}')::date+6
          end,p_evaluation_date-1)
          >=p_evaluation_date
        then 'EARLY_ISSUE_NOT_ALLOWED' end,
      case when f.conflicting_issue then 'CONFLICTING_ISSUE_OPERATION' end
    ],null)::text[] blockers
  from facts f
)
select c.request_key,c.invoice_id,
  to_jsonb(c.blockers),
  (case when coalesce(c.queueable_timesheet_document,0)>0
      then jsonb_build_array('TIMESHEET_DOCUMENT_NOT_READY')
    else '[]'::jsonb end)
  ||(case when coalesce(c.queueable_required_asset,0)>0
      then jsonb_build_array('REQUIRED_ASSET_NOT_READY')
    else '[]'::jsonb end),
  case when c.deliver
    then coalesce(c.route_blockers,'[]'::jsonb) else '[]'::jsonb end,
  coalesce(c.route_warnings,'[]'::jsonb),
  cardinality(c.blockers)=0,
  cardinality(c.blockers)=0
    and(not c.deliver or jsonb_array_length(
      coalesce(c.route_blockers,'[]'::jsonb))=0),
  jsonb_build_object(
    'request_key',c.request_key,
    'invoice_id',c.invoice_id,
    'route_policy_hash',c.route_policy_hash,
    'recipient_set_hash',c.recipient_set_hash,
    'grouping_identity',c.grouping_identity,
    'route_source',c.route_source,
    'do_not_send',c.do_not_send,
    'delivery_suppressed',c.delivery_suppressed,
    'canonical_to',c.canonical_to,
    'canonical_cc',c.canonical_cc,
    'canonical_bcc',c.canonical_bcc,
    'warnings',coalesce(c.route_warnings,'[]'::jsonb),
    'blockers',coalesce(c.route_blockers,'[]'::jsonb)),
  jsonb_build_object(
    'request_key',c.request_key,
    'evaluation_date',p_evaluation_date,
    'expected_revision',c.expected_revision,
    'current_revision',c.document_revision,
    'net_expected',c.subtotal_ex_vat,'net_lines',c.net,
    'vat_expected',c.vat_amount,'vat_lines',c.vat,
    'gross_expected',c.total_inc_vat,'gross_lines',c.gross,
    'hard_blockers',to_jsonb(c.blockers),
    'timesheet_readiness',coalesce(c.timesheet_readiness,'[]'::jsonb),
    'document_dependency_codes',
      (case when coalesce(c.queueable_timesheet_document,0)>0
          then jsonb_build_array('TIMESHEET_DOCUMENT_NOT_READY')
        else '[]'::jsonb end)
      ||(case when coalesce(c.queueable_required_asset,0)>0
          then jsonb_build_array('REQUIRED_ASSET_NOT_READY')
        else '[]'::jsonb end),
    'queueable_asset_count',coalesce(c.queueable_required_asset,0),
    'missing_import_source_count',coalesce(c.missing_import_source,0),
    'missing_asset_workflow_count',coalesce(c.missing_asset_workflow,0),
    'queueable_timesheet_document_count',
      coalesce(c.queueable_timesheet_document,0),
    'delivery_blockers',case when c.deliver
      then coalesce(c.route_blockers,'[]'::jsonb) else '[]'::jsonb end,
    'can_issue_only',cardinality(c.blockers)=0,
    'can_issue_and_deliver',cardinality(c.blockers)=0
      and(not c.deliver or jsonb_array_length(
        coalesce(c.route_blockers,'[]'::jsonb))=0),
    'recipient_set_hash',c.recipient_set_hash,
    'route_policy_hash',c.route_policy_hash,
    'grouping_identity',c.grouping_identity,
    'recipient_to',c.canonical_to,
    'recipient_cc',c.canonical_cc,
    'recipient_bcc',c.canonical_bcc,
    'route_source',c.route_source,
    'do_not_send',c.do_not_send,
    'delivery_suppressed',c.delivery_suppressed)
from classified c
order by c.request_no;
$function$;

-- private._invoice_jsonb_pick_v2(jsonb,text[])
CREATE OR REPLACE FUNCTION private._invoice_jsonb_pick_v2(p_value jsonb, p_keys text[])
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
  select coalesce(
    jsonb_object_agg(e.key, e.value order by e.key),
    '{}'::jsonb
  )
  from jsonb_each(coalesce(p_value, '{}'::jsonb)) e
  where e.key = any(coalesce(p_keys, array[]::text[]));
$function$;

-- private._invoice_operation_get_core_v8(uuid[],uuid,text)
CREATE OR REPLACE FUNCTION private._invoice_operation_get_core_v8(p_operation_ids uuid[], p_actor_user_id uuid, p_mode text DEFAULT 'PROGRESS'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mode_input text:=upper(btrim(coalesce(p_mode,'PROGRESS')));
  v_mode text;
  v_descendant_offset integer:=0;
  v_chunk_offset integer:=0;
  v_role text;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_result jsonb;
begin
  if v_mode_input='PROGRESS' then
    v_mode:='PROGRESS';
  elsif v_mode_input='DETAIL' then
    v_mode:='DETAIL';
  elsif v_mode_input~'^DETAIL:[0-9]{1,6}$' then
    v_mode:='DETAIL';
    v_descendant_offset:=split_part(v_mode_input,':',2)::integer;
  elsif v_mode_input~'^DETAIL:[0-9]{1,6}:[0-9]{1,6}$' then
    v_mode:='DETAIL';
    v_descendant_offset:=split_part(v_mode_input,':',2)::integer;
    v_chunk_offset:=split_part(v_mode_input,':',3)::integer;
  else
    raise exception
      'p_mode must be PROGRESS, DETAIL, DETAIL:<descendant offset>, or DETAIL:<descendant offset>:<chunk offset>';
  end if;
  if cardinality(coalesce(p_operation_ids,array[]::uuid[]))<1
    or cardinality(p_operation_ids)>100 then
    raise exception 'p_operation_ids must contain 1..100 IDs';
  end if;
  if not v_service and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',message='Authenticated actor mismatch';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_role
  from public.tms_users u where u.id=p_actor_user_id and u.is_active;
  if not found and not v_service then
    raise exception using errcode='42501',message='Active actor required';
  end if;
  if v_mode='DETAIL' and not v_service and coalesce(v_role,'')<>'admin' then
    raise exception using errcode='42501',message='Administrator permission required for DETAIL';
  end if;

  with recursive requested as materialized (
    select id,min(ordinality) ordinality
    from unnest(p_operation_ids) with ordinality x(id,ordinality)
    group by id
  ),
  authorised as materialized (
    select o.*,r.ordinality
    from requested r join public.invoice_operations o on o.id=r.id
    where v_service or v_role='admin' or o.actor_user_id=p_actor_user_id
  ),
  descendants(root_id,parent_id,id,operation_type,entity_type,entity_id,status,phase,
      progress_json,result_json,error_json,change_seq,updated_at_utc,
      created_at_utc,depth,path)
      as materialized (
    select p.id,ch.parent_operation_id,ch.id,ch.operation_type,ch.entity_type,ch.entity_id,
      ch.status,ch.phase,ch.progress_json,ch.result_json,ch.error_json,ch.change_seq,
      ch.updated_at_utc,ch.created_at_utc,1,array[p.id,ch.id]::uuid[]
    from authorised p
    join public.invoice_operations ch on ch.parent_operation_id=p.id
    union all
    select d.root_id,ch.parent_operation_id,ch.id,ch.operation_type,ch.entity_type,ch.entity_id,
      ch.status,ch.phase,ch.progress_json,ch.result_json,ch.error_json,ch.change_seq,
      ch.updated_at_utc,ch.created_at_utc,d.depth+1,d.path||ch.id
    from descendants d
    join public.invoice_operations ch on ch.parent_operation_id=d.id
    where not ch.id=any(d.path)
  ),
  scope_operation_ids as materialized (
    select a.id operation_id from authorised a
    union
    select d.id from descendants d
  ),
  scope_ranked as materialized (
    select s.operation_id,row_number() over(order by s.operation_id) rn
    from scope_operation_ids s
  ),
  scope_pages as materialized (
    select ((s.rn-1)/100)::integer page_no,
      array_agg(s.operation_id order by s.operation_id) operation_ids
    from scope_ranked s
    group by ((s.rn-1)/100)::integer
  ),
  current_slots as materialized (
    select slot.*
    from scope_pages p
    cross join lateral private._invoice_current_chunks_batch(
      p.operation_ids,null,null,10000) slot
  ),
  current_chunks as materialized (
    select slot.logical_slot_key,
      coalesce(c.id,slot.current_chunk_id) id,slot.operation_id,
      slot.chunk_type,slot.level_no,slot.sequence_no,slot.work_key,
      slot.plan_generation,slot.entity_type,slot.entity_id,
      slot.document_version_id,slot.document_asset_id,
      slot.input_document_version_id,
      case when slot.replacement_chain_status='INVALID'
        then 'BLOCKED' else c.status end status,
      case when slot.replacement_chain_status='INVALID'
        then 'REPLACEMENT_VALIDATION' else c.phase end phase,
      c.attempt_count,c.max_attempts,c.payload_json,
      c.progress_json,c.result_json,
      case when slot.replacement_chain_status='INVALID'
        then slot.replacement_chain_error else c.error_json end error_json,
      c.created_at_utc,c.updated_at_utc
    from current_slots slot
    left join public.invoice_operation_chunks c
      on c.id=slot.current_chunk_id
  ),
  child_rows as materialized (
    select *
    from(
      select d.*,row_number() over(partition by d.root_id
        order by d.depth,d.created_at_utc,d.id) rn
      from descendants d
    ) bounded
    where rn>v_descendant_offset
      and rn<=v_descendant_offset+200
  ),
  expected_purpose as materialized (
    select a.id operation_id,
      case
        when a.operation_type='ISSUE_INVOICES' then 'FINAL_ISSUE'
        when a.entity_type='TIMESHEET' then 'TIMESHEET'
        when upper(coalesce(a.input_json->>'purpose','')) in(
          'DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
          then upper(a.input_json->>'purpose')
        when a.entity_type='INVOICE' and exists(
          select 1 from public.invoices i
          where i.id=a.entity_id and i.status in('ISSUED','PAID'))
          then 'FINAL_ISSUE'
        else 'DRAFT_PREVIEW'
      end purpose
    from authorised a
  ),
  issue_document_ids as materialized (
    select distinct a.id operation_id,
      case when coalesce(c.payload_json->>'final_document_version_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(c.payload_json->>'final_document_version_id')::uuid end document_version_id
    from authorised a
    join current_chunks c
      on c.operation_id=a.id and c.chunk_type='ISSUE_INVOICE'
  ),
  candidate_documents as materialized (
    select a.id root_operation_id,v.*
    from authorised a join public.invoice_document_versions v on v.operation_id=a.id
    union all
    select cr.root_id root_operation_id,v.*
    from descendants cr join public.invoice_document_versions v on v.operation_id=cr.id
    union all
    select x.operation_id root_operation_id,v.*
    from issue_document_ids x join public.invoice_document_versions v on v.id=x.document_version_id
    union all
    select a.id root_operation_id,v.*
    from authorised a join public.invoices i
      on a.entity_type='INVOICE' and i.id=a.entity_id
    join public.invoice_document_versions v
      on v.id in(i.preview_document_version_id,i.issued_document_version_id)
    union all
    select a.id root_operation_id,v.*
    from authorised a join public.timesheets t
      on a.entity_type='TIMESHEET' and t.timesheet_id=a.entity_id and t.is_current
    join public.invoice_document_versions v on v.id=t.current_document_version_id
  ),
  selected_documents as materialized (
    select distinct on(c.root_operation_id) c.*
    from candidate_documents c
    join expected_purpose expected on expected.operation_id=c.root_operation_id
    where c.purpose=expected.purpose
    order by c.root_operation_id,
      case status when 'READY' then 0 when 'VERIFYING' then 1
        when 'ASSEMBLING' then 2 when 'RENDERING' then 3 else 4 end,
      created_at_utc desc,id desc
  ),
  descendant_summary as materialized (
    select a.id root_id,count(d.id)::integer total_descendants,
      greatest(a.change_seq,coalesce(max(d.change_seq),0))::bigint
        effective_change_seq,
      count(d.id) filter(where d.operation_type='BUILD_DOCUMENT')::integer
        document_operation_count,
      count(d.id) filter(where d.operation_type='DELIVER_INVOICES')::integer
        delivery_operation_count
    from authorised a
    left join descendants d on d.root_id=a.id
    group by a.id,a.change_seq
  ),
  operation_rows as materialized (
    select a.*,d.id active_document_version_id,d.entity_type document_entity_type,
      d.entity_id document_entity_id,d.purpose document_purpose,
      d.status document_status,d.r2_key,d.sha256,d.size_bytes,d.page_count,
      ds.total_descendants,
      least(greatest(ds.total_descendants-v_descendant_offset,0),200)::integer
        returned_descendants,
      ds.total_descendants>v_descendant_offset+200 results_truncated,
      case when ds.total_descendants>v_descendant_offset+200
        then 'DETAIL:'||(v_descendant_offset+200)::text end
        continuation_token,
      ds.effective_change_seq,ds.document_operation_count,
      ds.delivery_operation_count,
      (select count(*)::integer from current_chunks z
        where z.operation_id=a.id) total_chunks,
      least(greatest((select count(*)::integer from current_chunks z
        where z.operation_id=a.id)-v_chunk_offset,0),250)::integer
        returned_chunks,
      (select count(*) from current_chunks z
        where z.operation_id=a.id)>v_chunk_offset+250 chunks_truncated,
      case when (select count(*) from current_chunks z
          where z.operation_id=a.id)>v_chunk_offset+250
        then 'DETAIL:'||v_descendant_offset::text||':'||
          (v_chunk_offset+250)::text end chunk_continuation_token,
      case when v_mode='DETAIL' then(
        select coalesce(jsonb_agg(jsonb_build_object(
          'chunk_id',q.id,'chunk_type',q.chunk_type,'phase',q.phase,'status',q.status,
          'entity_type',q.entity_type,'entity_id',q.entity_id,
          'attempt_count',q.attempt_count,'max_attempts',q.max_attempts,
          'progress',q.progress_json,'result',q.result_json,'error',q.error_json)
          order by q.created_at_utc,q.id),'[]'::jsonb)
        from(
          select * from current_chunks z
          where z.operation_id=a.id
          order by z.created_at_utc,z.id
          offset v_chunk_offset limit 250
        ) q
      ) end chunks,
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'operation_id',cr.id,'operation_type',cr.operation_type,
          'entity_type',cr.entity_type,'entity_id',cr.entity_id,
          'status',cr.status,'phase',cr.phase,
          'progress',case when v_mode='DETAIL' then cr.progress_json else
            jsonb_build_object('status_message',cr.progress_json->>'status_message') end,
          'result',case when v_mode='DETAIL' and cr.status='COMPLETE'
            then cr.result_json end,
          'error_code',cr.error_json->>'code','change_seq',cr.change_seq,'updated_at_utc',cr.updated_at_utc)
          order by cr.updated_at_utc,cr.id)
        from child_rows cr where cr.root_id=a.id
      ),'[]'::jsonb) children,
      jsonb_build_object(
        'created_invoice_ids',coalesce((
          select jsonb_agg(to_jsonb(b.value) order by b.value)
          from(
            select distinct e.value
            from current_chunks c
            cross join lateral jsonb_array_elements_text(
              case when jsonb_typeof(c.result_json->'invoice_ids')='array'
                then c.result_json->'invoice_ids'
                when c.result_json?'invoice_id'
                  then jsonb_build_array(c.result_json->>'invoice_id')
                else '[]'::jsonb end) e(value)
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
            order by e.value limit 500
          ) b),'[]'::jsonb),
        'document_operation_ids',coalesce((
          select jsonb_agg(to_jsonb(b.id) order by b.id)
          from(
            select cr.id from descendants cr
            where cr.root_id=a.id and cr.operation_type='BUILD_DOCUMENT'
            order by cr.id limit 500
          ) b),'[]'::jsonb),
        'delivery_operation_ids',coalesce((
          select jsonb_agg(to_jsonb(b.id) order by b.id)
          from(
            select cr.id from descendants cr
            where cr.root_id=a.id and cr.operation_type='DELIVER_INVOICES'
            order by cr.id limit 500
          ) b),'[]'::jsonb),
        'issue_results',coalesce((
          select jsonb_agg(jsonb_build_object(
            'chunk_id',b.id,'invoice_id',b.entity_id,
            'status',b.status,'phase',b.phase,
            'document_version_id',coalesce(
              b.result_json->>'issued_document_version_id',
              b.result_json->>'document_version_id'),
            'document_operation_id',b.result_json->>'document_operation_id',
            'delivery_operation_id',b.result_json->>'delivery_operation_id',
            'error_code',b.error_json->>'code') order by b.entity_id,b.id)
          from(
            select c.* from current_chunks c
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
              and c.chunk_type='ISSUE_INVOICE'
            order by c.entity_id,c.id limit 500
          ) b),'[]'::jsonb),
        'mail_outbox_ids',coalesce((
          select jsonb_agg(to_jsonb(b.value) order by b.value)
          from(
            select distinct m.value
            from current_chunks c
            cross join lateral jsonb_array_elements_text(
              case when jsonb_typeof(c.result_json->'mail_outbox_ids')='array'
                then c.result_json->'mail_outbox_ids' else '[]'::jsonb end)
              m(value)
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
            order by m.value limit 500
          ) b),'[]'::jsonb),
        'blocked_or_failed_entities',coalesce((
          select jsonb_agg(jsonb_build_object(
            'chunk_id',b.id,'entity_type',b.entity_type,
            'entity_id',b.entity_id,'status',b.status,
            'error_code',b.error_json->>'code') order by b.id)
          from(
            select c.* from current_chunks c
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
              and c.status in('BLOCKED','FAILED','DEAD_LETTER')
            order by c.id limit 500
          ) b),'[]'::jsonb),
        'invoice_ids_page',coalesce(a.result_json->'invoice_ids_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false)),
        'document_operations_page',coalesce(
          a.result_json->'document_operations_page',
          jsonb_build_object('total_count',ds.document_operation_count,
            'returned_count',least(ds.document_operation_count,500),
            'truncated',ds.document_operation_count>500)),
        'delivery_operations_page',coalesce(
          a.result_json->'delivery_operations_page',
          jsonb_build_object('total_count',ds.delivery_operation_count,
            'returned_count',least(ds.delivery_operation_count,500),
            'truncated',ds.delivery_operation_count>500)),
        'issue_outcomes_page',coalesce(a.result_json->'issue_outcomes_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false)),
        'mail_ids_page',coalesce(a.result_json->'mail_ids_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false)),
        'blocked_entities_page',coalesce(
          a.result_json->'blocked_entities_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false))
      ) aggregate_result
    from authorised a
    join descendant_summary ds on ds.root_id=a.id
    left join selected_documents d on d.root_operation_id=a.id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'operation_id',r.id,'parent_operation_id',r.parent_operation_id,
    'operation_type',r.operation_type,'entity_type',r.entity_type,'entity_id',r.entity_id,
    'status',r.status,'phase',r.phase,'priority',r.priority,
    'source_revision',r.source_revision,'template_version',r.template_version,
    'total_units',r.total_units,'completed_units',r.completed_units,'failed_units',r.failed_units,
    'progress',r.progress_json,
    'result',case when v_mode='DETAIL' or r.status='COMPLETE'
      then coalesce(r.result_json,'{}'::jsonb)||r.aggregate_result end,
    'error_code',r.error_json->>'code',
    'error_summary',coalesce(r.error_json->>'summary',r.error_json->>'message'),
    'requires_user_action',r.requires_user_action,
    'can_retry',r.status in('FAILED','DEAD_LETTER','BLOCKED','RETRY_WAIT'),
    'can_cancel',r.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and not exists(
        select 1 from current_chunks ic
        join public.invoices i on i.id=ic.entity_id
        where ic.operation_id in(
            select r.id
            union all select cr.id from descendants cr where cr.root_id=r.id)
          and ic.chunk_type='ISSUE_INVOICE'
          and i.status in('ISSUED','PAID')),
    'change_seq',r.change_seq,
    'effective_change_seq',r.effective_change_seq,
    'total_descendants',r.total_descendants,
    'descendant_page_offset',v_descendant_offset,
    'returned_descendants',r.returned_descendants,
    'results_truncated',r.results_truncated,
    'continuation_token',r.continuation_token,
    'total_chunks',r.total_chunks,
    'returned_chunks',r.returned_chunks,
    'chunks_truncated',r.chunks_truncated,
    'chunk_page_offset',v_chunk_offset,
    'chunk_continuation_token',r.chunk_continuation_token,
    'legal_issue_state',coalesce(
      r.result_json->>'legal_issue_status',
      case when r.operation_type='ISSUE_INVOICES' then 'IN_PROGRESS' end),
    'delivery_state',coalesce(
      r.result_json->>'delivery_status',
      case when r.delivery_operation_count>0 then 'IN_PROGRESS'
        else 'NOT_REQUESTED' end),
    'active_document_version_id',r.active_document_version_id,
    'document_purpose',r.document_purpose,'document_status',r.document_status,
    'ready_key',case when r.document_status='READY' then r.r2_key end,
    'artifact',case when v_mode='DETAIL' and r.document_status='READY'
      then jsonb_build_object('sha256',r.sha256,'size_bytes',r.size_bytes,
        'page_count',r.page_count) end,
    'children',r.children,'chunks',r.chunks,
    'created_at_utc',r.created_at_utc,'updated_at_utc',r.updated_at_utc,
    'completed_at_utc',r.completed_at_utc
  ) order by r.ordinality),'[]'::jsonb) into v_result
  from operation_rows r;

  return v_result;
end;
$function$;

-- private._invoice_operation_get_legacy_20260726(uuid[],uuid,text)
CREATE OR REPLACE FUNCTION private._invoice_operation_get_legacy_20260726(p_operation_ids uuid[], p_actor_user_id uuid, p_mode text DEFAULT 'PROGRESS'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mode_input text:=upper(btrim(coalesce(p_mode,'PROGRESS')));
  v_mode text;
  v_descendant_offset integer:=0;
  v_chunk_offset integer:=0;
  v_role text;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_result jsonb;
begin
  if v_mode_input='PROGRESS' then
    v_mode:='PROGRESS';
  elsif v_mode_input='DETAIL' then
    v_mode:='DETAIL';
  elsif v_mode_input~'^DETAIL:[0-9]{1,6}$' then
    v_mode:='DETAIL';
    v_descendant_offset:=split_part(v_mode_input,':',2)::integer;
  elsif v_mode_input~'^DETAIL:[0-9]{1,6}:[0-9]{1,6}$' then
    v_mode:='DETAIL';
    v_descendant_offset:=split_part(v_mode_input,':',2)::integer;
    v_chunk_offset:=split_part(v_mode_input,':',3)::integer;
  else
    raise exception
      'p_mode must be PROGRESS, DETAIL, DETAIL:<descendant offset>, or DETAIL:<descendant offset>:<chunk offset>';
  end if;
  if cardinality(coalesce(p_operation_ids,array[]::uuid[]))<1
    or cardinality(p_operation_ids)>100 then
    raise exception 'p_operation_ids must contain 1..100 IDs';
  end if;
  if not v_service and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',message='Authenticated actor mismatch';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_role
  from public.tms_users u where u.id=p_actor_user_id and u.is_active;
  if not found and not v_service then
    raise exception using errcode='42501',message='Active actor required';
  end if;
  if v_mode='DETAIL' and not v_service and coalesce(v_role,'')<>'admin' then
    raise exception using errcode='42501',message='Administrator permission required for DETAIL';
  end if;

  with recursive requested as materialized (
    select id,min(ordinality) ordinality
    from unnest(p_operation_ids) with ordinality x(id,ordinality)
    group by id
  ),
  authorised as materialized (
    select o.*,r.ordinality
    from requested r join public.invoice_operations o on o.id=r.id
    where v_service or v_role='admin' or o.actor_user_id=p_actor_user_id
  ),
  descendants(root_id,parent_id,id,operation_type,entity_type,entity_id,status,phase,
      progress_json,result_json,error_json,change_seq,updated_at_utc,
      created_at_utc,depth,path)
      as materialized (
    select p.id,ch.parent_operation_id,ch.id,ch.operation_type,ch.entity_type,ch.entity_id,
      ch.status,ch.phase,ch.progress_json,ch.result_json,ch.error_json,ch.change_seq,
      ch.updated_at_utc,ch.created_at_utc,1,array[p.id,ch.id]::uuid[]
    from authorised p
    join public.invoice_operations ch on ch.parent_operation_id=p.id
    union all
    select d.root_id,ch.parent_operation_id,ch.id,ch.operation_type,ch.entity_type,ch.entity_id,
      ch.status,ch.phase,ch.progress_json,ch.result_json,ch.error_json,ch.change_seq,
      ch.updated_at_utc,ch.created_at_utc,d.depth+1,d.path||ch.id
    from descendants d
    join public.invoice_operations ch on ch.parent_operation_id=d.id
    where not ch.id=any(d.path)
  ),
  scope_operation_ids as materialized (
    select a.id operation_id from authorised a
    union
    select d.id from descendants d
  ),
  scope_ranked as materialized (
    select s.operation_id,row_number() over(order by s.operation_id) rn
    from scope_operation_ids s
  ),
  scope_pages as materialized (
    select ((s.rn-1)/100)::integer page_no,
      array_agg(s.operation_id order by s.operation_id) operation_ids
    from scope_ranked s
    group by ((s.rn-1)/100)::integer
  ),
  current_slots as materialized (
    select slot.*
    from scope_pages p
    cross join lateral private._invoice_current_chunks_batch(
      p.operation_ids,null,null,10000) slot
  ),
  current_chunks as materialized (
    select slot.logical_slot_key,
      coalesce(c.id,slot.current_chunk_id) id,slot.operation_id,
      slot.chunk_type,slot.level_no,slot.sequence_no,slot.work_key,
      slot.plan_generation,slot.entity_type,slot.entity_id,
      slot.document_version_id,slot.document_asset_id,
      slot.input_document_version_id,
      case when slot.replacement_chain_status='INVALID'
        then 'BLOCKED' else c.status end status,
      case when slot.replacement_chain_status='INVALID'
        then 'REPLACEMENT_VALIDATION' else c.phase end phase,
      c.attempt_count,c.max_attempts,c.payload_json,
      c.progress_json,c.result_json,
      case when slot.replacement_chain_status='INVALID'
        then slot.replacement_chain_error else c.error_json end error_json,
      c.created_at_utc,c.updated_at_utc
    from current_slots slot
    left join public.invoice_operation_chunks c
      on c.id=slot.current_chunk_id
  ),
  child_rows as materialized (
    select *
    from(
      select d.*,row_number() over(partition by d.root_id
        order by d.depth,d.created_at_utc,d.id) rn
      from descendants d
    ) bounded
    where rn>v_descendant_offset
      and rn<=v_descendant_offset+200
  ),
  expected_purpose as materialized (
    select a.id operation_id,
      case
        when a.operation_type='ISSUE_INVOICES' then 'FINAL_ISSUE'
        when a.entity_type='TIMESHEET' then 'TIMESHEET'
        when upper(coalesce(a.input_json->>'purpose','')) in(
          'DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
          then upper(a.input_json->>'purpose')
        when a.entity_type='INVOICE' and exists(
          select 1 from public.invoices i
          where i.id=a.entity_id and i.status in('ISSUED','PAID'))
          then 'FINAL_ISSUE'
        else 'DRAFT_PREVIEW'
      end purpose
    from authorised a
  ),
  issue_document_ids as materialized (
    select distinct a.id operation_id,
      case when coalesce(c.payload_json->>'final_document_version_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(c.payload_json->>'final_document_version_id')::uuid end document_version_id
    from authorised a
    join current_chunks c
      on c.operation_id=a.id and c.chunk_type='ISSUE_INVOICE'
  ),
  candidate_documents as materialized (
    select a.id root_operation_id,v.*
    from authorised a join public.invoice_document_versions v on v.operation_id=a.id
    union all
    select cr.root_id root_operation_id,v.*
    from descendants cr join public.invoice_document_versions v on v.operation_id=cr.id
    union all
    select x.operation_id root_operation_id,v.*
    from issue_document_ids x join public.invoice_document_versions v on v.id=x.document_version_id
    union all
    select a.id root_operation_id,v.*
    from authorised a join public.invoices i
      on a.entity_type='INVOICE' and i.id=a.entity_id
    join public.invoice_document_versions v
      on v.id in(i.preview_document_version_id,i.issued_document_version_id)
    union all
    select a.id root_operation_id,v.*
    from authorised a join public.timesheets t
      on a.entity_type='TIMESHEET' and t.timesheet_id=a.entity_id and t.is_current
    join public.invoice_document_versions v on v.id=t.current_document_version_id
  ),
  selected_documents as materialized (
    select distinct on(c.root_operation_id) c.*
    from candidate_documents c
    join expected_purpose expected on expected.operation_id=c.root_operation_id
    where c.purpose=expected.purpose
    order by c.root_operation_id,
      case status when 'READY' then 0 when 'VERIFYING' then 1
        when 'ASSEMBLING' then 2 when 'RENDERING' then 3 else 4 end,
      created_at_utc desc,id desc
  ),
  descendant_summary as materialized (
    select a.id root_id,count(d.id)::integer total_descendants,
      greatest(a.change_seq,coalesce(max(d.change_seq),0))::bigint
        effective_change_seq,
      count(d.id) filter(where d.operation_type='BUILD_DOCUMENT')::integer
        document_operation_count,
      count(d.id) filter(where d.operation_type='DELIVER_INVOICES')::integer
        delivery_operation_count
    from authorised a
    left join descendants d on d.root_id=a.id
    group by a.id,a.change_seq
  ),
  operation_rows as materialized (
    select a.*,d.id active_document_version_id,d.entity_type document_entity_type,
      d.entity_id document_entity_id,d.purpose document_purpose,
      d.status document_status,d.r2_key,d.sha256,d.size_bytes,d.page_count,
      ds.total_descendants,
      least(greatest(ds.total_descendants-v_descendant_offset,0),200)::integer
        returned_descendants,
      ds.total_descendants>v_descendant_offset+200 results_truncated,
      case when ds.total_descendants>v_descendant_offset+200
        then 'DETAIL:'||(v_descendant_offset+200)::text end
        continuation_token,
      ds.effective_change_seq,ds.document_operation_count,
      ds.delivery_operation_count,
      (select count(*)::integer from current_chunks z
        where z.operation_id=a.id) total_chunks,
      least(greatest((select count(*)::integer from current_chunks z
        where z.operation_id=a.id)-v_chunk_offset,0),250)::integer
        returned_chunks,
      (select count(*) from current_chunks z
        where z.operation_id=a.id)>v_chunk_offset+250 chunks_truncated,
      case when (select count(*) from current_chunks z
          where z.operation_id=a.id)>v_chunk_offset+250
        then 'DETAIL:'||v_descendant_offset::text||':'||
          (v_chunk_offset+250)::text end chunk_continuation_token,
      case when v_mode='DETAIL' then(
        select coalesce(jsonb_agg(jsonb_build_object(
          'chunk_id',q.id,'chunk_type',q.chunk_type,'phase',q.phase,'status',q.status,
          'entity_type',q.entity_type,'entity_id',q.entity_id,
          'attempt_count',q.attempt_count,'max_attempts',q.max_attempts,
          'progress',q.progress_json,'result',q.result_json,'error',q.error_json)
          order by q.created_at_utc,q.id),'[]'::jsonb)
        from(
          select * from current_chunks z
          where z.operation_id=a.id
          order by z.created_at_utc,z.id
          offset v_chunk_offset limit 250
        ) q
      ) end chunks,
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'operation_id',cr.id,'operation_type',cr.operation_type,
          'entity_type',cr.entity_type,'entity_id',cr.entity_id,
          'status',cr.status,'phase',cr.phase,
          'progress',case when v_mode='DETAIL' then cr.progress_json else
            jsonb_build_object('status_message',cr.progress_json->>'status_message') end,
          'result',case when v_mode='DETAIL' and cr.status='COMPLETE'
            then cr.result_json end,
          'error_code',cr.error_json->>'code','change_seq',cr.change_seq,'updated_at_utc',cr.updated_at_utc)
          order by cr.updated_at_utc,cr.id)
        from child_rows cr where cr.root_id=a.id
      ),'[]'::jsonb) children,
      jsonb_build_object(
        'created_invoice_ids',coalesce((
          select jsonb_agg(to_jsonb(b.value) order by b.value)
          from(
            select distinct e.value
            from current_chunks c
            cross join lateral jsonb_array_elements_text(
              case when jsonb_typeof(c.result_json->'invoice_ids')='array'
                then c.result_json->'invoice_ids'
                when c.result_json?'invoice_id'
                  then jsonb_build_array(c.result_json->>'invoice_id')
                else '[]'::jsonb end) e(value)
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
            order by e.value limit 500
          ) b),'[]'::jsonb),
        'document_operation_ids',coalesce((
          select jsonb_agg(to_jsonb(b.id) order by b.id)
          from(
            select cr.id from descendants cr
            where cr.root_id=a.id and cr.operation_type='BUILD_DOCUMENT'
            order by cr.id limit 500
          ) b),'[]'::jsonb),
        'delivery_operation_ids',coalesce((
          select jsonb_agg(to_jsonb(b.id) order by b.id)
          from(
            select cr.id from descendants cr
            where cr.root_id=a.id and cr.operation_type='DELIVER_INVOICES'
            order by cr.id limit 500
          ) b),'[]'::jsonb),
        'issue_results',coalesce((
          select jsonb_agg(jsonb_build_object(
            'chunk_id',b.id,'invoice_id',b.entity_id,
            'status',b.status,'phase',b.phase,
            'document_version_id',coalesce(
              b.result_json->>'issued_document_version_id',
              b.result_json->>'document_version_id'),
            'document_operation_id',b.result_json->>'document_operation_id',
            'delivery_operation_id',b.result_json->>'delivery_operation_id',
            'error_code',b.error_json->>'code') order by b.entity_id,b.id)
          from(
            select c.* from current_chunks c
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
              and c.chunk_type='ISSUE_INVOICE'
            order by c.entity_id,c.id limit 500
          ) b),'[]'::jsonb),
        'mail_outbox_ids',coalesce((
          select jsonb_agg(to_jsonb(b.value) order by b.value)
          from(
            select distinct m.value
            from current_chunks c
            cross join lateral jsonb_array_elements_text(
              case when jsonb_typeof(c.result_json->'mail_outbox_ids')='array'
                then c.result_json->'mail_outbox_ids' else '[]'::jsonb end)
              m(value)
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
            order by m.value limit 500
          ) b),'[]'::jsonb),
        'blocked_or_failed_entities',coalesce((
          select jsonb_agg(jsonb_build_object(
            'chunk_id',b.id,'entity_type',b.entity_type,
            'entity_id',b.entity_id,'status',b.status,
            'error_code',b.error_json->>'code') order by b.id)
          from(
            select c.* from current_chunks c
            where c.operation_id in(
              select a.id union all
              select cr.id from descendants cr where cr.root_id=a.id)
              and c.status in('BLOCKED','FAILED','DEAD_LETTER')
            order by c.id limit 500
          ) b),'[]'::jsonb),
        'invoice_ids_page',coalesce(a.result_json->'invoice_ids_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false)),
        'document_operations_page',coalesce(
          a.result_json->'document_operations_page',
          jsonb_build_object('total_count',ds.document_operation_count,
            'returned_count',least(ds.document_operation_count,500),
            'truncated',ds.document_operation_count>500)),
        'delivery_operations_page',coalesce(
          a.result_json->'delivery_operations_page',
          jsonb_build_object('total_count',ds.delivery_operation_count,
            'returned_count',least(ds.delivery_operation_count,500),
            'truncated',ds.delivery_operation_count>500)),
        'issue_outcomes_page',coalesce(a.result_json->'issue_outcomes_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false)),
        'mail_ids_page',coalesce(a.result_json->'mail_ids_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false)),
        'blocked_entities_page',coalesce(
          a.result_json->'blocked_entities_page',
          jsonb_build_object('total_count',0,'returned_count',0,
            'truncated',false))
      ) aggregate_result
    from authorised a
    join descendant_summary ds on ds.root_id=a.id
    left join selected_documents d on d.root_operation_id=a.id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'operation_id',r.id,'parent_operation_id',r.parent_operation_id,
    'operation_type',r.operation_type,'entity_type',r.entity_type,'entity_id',r.entity_id,
    'status',r.status,'phase',r.phase,'priority',r.priority,
    'source_revision',r.source_revision,'template_version',r.template_version,
    'total_units',r.total_units,'completed_units',r.completed_units,'failed_units',r.failed_units,
    'progress',r.progress_json,
    'result',case when v_mode='DETAIL' or r.status='COMPLETE'
      then coalesce(r.result_json,'{}'::jsonb)||r.aggregate_result end,
    'error_code',r.error_json->>'code',
    'error_summary',coalesce(r.error_json->>'summary',r.error_json->>'message'),
    'requires_user_action',r.requires_user_action,
    'can_retry',r.status in('FAILED','DEAD_LETTER','BLOCKED','RETRY_WAIT'),
    'can_cancel',r.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and not exists(
        select 1 from current_chunks ic
        join public.invoices i on i.id=ic.entity_id
        where ic.operation_id in(
            select r.id
            union all select cr.id from descendants cr where cr.root_id=r.id)
          and ic.chunk_type='ISSUE_INVOICE'
          and i.status in('ISSUED','PAID')),
    'change_seq',r.change_seq,
    'effective_change_seq',r.effective_change_seq,
    'total_descendants',r.total_descendants,
    'descendant_page_offset',v_descendant_offset,
    'returned_descendants',r.returned_descendants,
    'results_truncated',r.results_truncated,
    'continuation_token',r.continuation_token,
    'total_chunks',r.total_chunks,
    'returned_chunks',r.returned_chunks,
    'chunks_truncated',r.chunks_truncated,
    'chunk_page_offset',v_chunk_offset,
    'chunk_continuation_token',r.chunk_continuation_token,
    'legal_issue_state',coalesce(
      r.result_json->>'legal_issue_status',
      case when r.operation_type='ISSUE_INVOICES' then 'IN_PROGRESS' end),
    'delivery_state',coalesce(
      r.result_json->>'delivery_status',
      case when r.delivery_operation_count>0 then 'IN_PROGRESS'
        else 'NOT_REQUESTED' end),
    'active_document_version_id',r.active_document_version_id,
    'document_purpose',r.document_purpose,'document_status',r.document_status,
    'ready_key',case when r.document_status='READY' then r.r2_key end,
    'artifact',case when v_mode='DETAIL' and r.document_status='READY'
      then jsonb_build_object('sha256',r.sha256,'size_bytes',r.size_bytes,
        'page_count',r.page_count) end,
    'children',r.children,'chunks',r.chunks,
    'created_at_utc',r.created_at_utc,'updated_at_utc',r.updated_at_utc,
    'completed_at_utc',r.completed_at_utc
  ) order by r.ordinality),'[]'::jsonb) into v_result
  from operation_rows r;

  return v_result;
end;
$function$;

-- private._invoice_operation_rollup_batch_legacy_20260726(uuid[],timestamp with time zone,boolean)
CREATE OR REPLACE FUNCTION private._invoice_operation_rollup_batch_legacy_20260726(p_operation_ids uuid[], p_now_utc timestamp with time zone DEFAULT now(), p_propagate_ancestors boolean DEFAULT true)
 RETURNS TABLE(operation_id uuid, status text, phase text, total_units integer, completed_units integer, failed_units integer, blocked_required_count integer, requires_user_action boolean, change_seq bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
begin
  return query
  with recursive requested as materialized (
    select distinct x.id
    from unnest(coalesce(p_operation_ids,array[]::uuid[])) x(id)
    where x.id is not null
  ),
  scope(id,depth) as (
    select r.id,0 from requested r
    union
    select o.parent_operation_id,s.depth+1
    from scope s join public.invoice_operations o on o.id=s.id
    where p_propagate_ancestors and o.parent_operation_id is not null
      and s.depth<16
  ),
  targets as materialized (
    select distinct id from scope where id is not null
  ),
  ancestor_bumps as materialized (
    select distinct id from scope where id is not null and depth>0
  ),
  target_ranked as materialized (
    select t.id,
      row_number() over(order by t.id) operation_no
    from targets t
  ),
  target_pages as materialized (
    select ((t.operation_no-1)/500)::integer page_no,
      array_agg(t.id order by t.id) operation_ids
    from target_ranked t
    group by ((t.operation_no-1)/500)::integer
  ),
  current_slots as materialized (
    select cc.*
    from target_pages a
    cross join lateral private._invoice_current_chunks_batch(
      a.operation_ids,null,null,10000) cc
  ),
  current_chunks as materialized (
    select s.logical_slot_key,
      coalesce(c.id,s.current_chunk_id) id,s.operation_id,s.chunk_type,
      s.level_no,s.sequence_no,s.work_key,s.plan_generation,
      s.entity_type,s.entity_id,s.document_version_id,s.document_asset_id,
      s.input_document_version_id,
      case when s.replacement_chain_status='INVALID'
        then 'BLOCKED' else c.status end status,
      case when s.replacement_chain_status='INVALID'
        then 'REPLACEMENT_VALIDATION' else c.phase end phase,
      c.payload_json,c.progress_json,c.result_json,
      case when s.replacement_chain_status='INVALID'
        then s.replacement_chain_error else c.error_json end error_json,
      coalesce(c.updated_at_utc,v_now) updated_at_utc,
      s.replacement_chain_status,s.replacement_chain_error
    from current_slots s
    left join public.invoice_operation_chunks c on c.id=s.current_chunk_id
  ),
  counts as materialized (
    select t.id operation_id,count(c.logical_slot_key)::integer total_units,
      count(*) filter(where c.status='QUEUED')::integer queued_units,
      count(*) filter(where c.status='RUNNING')::integer running_units,
      count(*) filter(where c.status='WAITING')::integer waiting_units,
      count(*) filter(where c.status='RETRY_WAIT')::integer retry_units,
      count(*) filter(where c.status='BLOCKED')::integer blocked_units,
      count(*) filter(where c.status='COMPLETE')::integer complete_units,
      count(*) filter(where c.status='FAILED')::integer failed_only_units,
      count(*) filter(where c.status='DEAD_LETTER')::integer dead_units,
      count(*) filter(where c.status='CANCELLED')::integer cancelled_units,
      count(*) filter(where c.status='SUPERSEDED')::integer superseded_units,
      count(*) filter(where c.replacement_chain_status='INVALID')::integer
        missing_replacement_units,
      (count(*) filter(where c.status in(
        'FAILED','DEAD_LETTER','BLOCKED'))
       +count(*) filter(where c.replacement_chain_status='INVALID'
          and c.status<>'BLOCKED'))::integer failed_units,
      (array_agg(c.phase order by
        case c.status when 'RUNNING' then 0 when 'QUEUED' then 1
          when 'RETRY_WAIT' then 2 when 'BLOCKED' then 3 when 'WAITING' then 4
          else 5 end,c.updated_at_utc desc,c.id)
        filter(where c.id is not null))[1] current_phase,
      coalesce(jsonb_agg(jsonb_build_object(
        'chunk_id',c.id,'chunk_type',c.chunk_type,'entity_type',c.entity_type,
        'entity_id',c.entity_id,'code',c.error_json->>'code',
        'replacement_chain_status',c.replacement_chain_status)
        order by c.updated_at_utc desc,c.id)
        filter(where c.status in('BLOCKED','FAILED','DEAD_LETTER')),
        '[]'::jsonb) blocker_summary
    from targets t
    left join current_chunks c on c.operation_id=t.id
    group by t.id
  ),
  derived as materialized (
    select c.*,
      case
        when o.status in('CANCELLED','SUPERSEDED') then o.status
        when c.missing_replacement_units>0 then 'BLOCKED'
        when c.running_units>0 then 'RUNNING'
        when c.queued_units>0 then 'QUEUED'
        when c.retry_units>0 then 'RETRY_WAIT'
        when c.blocked_units>0 then 'BLOCKED'
        when c.waiting_units>0 then 'WAITING'
        when c.dead_units>0 then 'DEAD_LETTER'
        when c.failed_only_units>0 then 'FAILED'
        when c.total_units>0 and c.complete_units=c.total_units then 'COMPLETE'
        when c.total_units>0 and c.cancelled_units=c.total_units then 'CANCELLED'
        when c.total_units>0 and c.superseded_units=c.total_units then 'SUPERSEDED'
        when c.cancelled_units>0 then 'BLOCKED'
        else o.status
      end derived_status,
      c.blocked_units>0 or c.dead_units>0 or c.failed_only_units>0
        or c.missing_replacement_units>0
        requires_action
    from counts c join public.invoice_operations o on o.id=c.operation_id
  ),
  child_rows as materialized (
    select parent.id operation_id,child.id child_id,
      child.operation_type,child.status,child.phase,child.change_seq,
      child.entity_id,child.error_json->>'code' error_code,
      row_number() over(partition by parent.id
        order by child.created_at_utc,child.id) child_no,
      count(*) over(partition by parent.id)::integer child_total
    from public.invoice_operations parent
    join targets t on t.id=parent.id
    join public.invoice_operations child
      on child.parent_operation_id=parent.id
  ),
  child_results as materialized (
    select t.id operation_id,
      coalesce(jsonb_agg(jsonb_build_object(
        'operation_id',child.child_id,
        'operation_type',child.operation_type,
        'status',child.status,'phase',child.phase,
        'change_seq',child.change_seq,
        'entity_id',child.entity_id,
        'error_code',child.error_code)
        order by child.child_no)
        filter(where child.child_no<=200),'[]'::jsonb) children,
      coalesce(max(child.child_total),0)::integer child_total,
      least(coalesce(max(child.child_total),0),200)::integer child_returned,
      coalesce(max(child.child_total),0)>200 children_truncated,
      coalesce(max(child.change_seq),0) descendant_change_seq
    from targets t
    left join child_rows child on child.operation_id=t.id
    group by t.id
  ),
  descendant_tree(root_operation_id,operation_id,depth,path) as (
    select t.id,t.id,0,array[t.id]::uuid[] from targets t
    union all
    select d.root_operation_id,o.id,d.depth+1,d.path||o.id
    from descendant_tree d
    join public.invoice_operations o
      on o.parent_operation_id=d.operation_id
    where not o.id=any(d.path)
  ),
  descendant_ranked as materialized (
    select d.*,
      row_number() over(
        partition by d.root_operation_id
        order by d.depth,d.operation_id) descendant_no
    from descendant_tree d
  ),
  descendant_scope as materialized (
    select d.root_operation_id,d.operation_id,d.depth,d.descendant_no
    from descendant_ranked d
  ),
  descendant_operation_ids as materialized (
    select d.operation_id,
      row_number() over(order by d.operation_id) operation_no
    from (
      select distinct scoped.operation_id
      from descendant_scope scoped
    ) d
  ),
  descendant_operation_pages as materialized (
    select ((d.operation_no-1)/500)::integer page_no,
      array_agg(d.operation_id order by d.operation_id) operation_ids
    from descendant_operation_ids d
    group by ((d.operation_no-1)/500)::integer
  ),
  descendant_current_slots as materialized (
    select cc.*
    from descendant_operation_pages a
    cross join lateral private._invoice_current_chunks_batch(
      a.operation_ids,null,null,10000) cc
  ),
  descendant_chunks as materialized (
    select d.root_operation_id,
      coalesce(c.id,s.current_chunk_id) id,s.operation_id,s.chunk_type,
      s.entity_type,s.entity_id,
      case when s.replacement_chain_status='INVALID'
        then 'BLOCKED' else c.status end status,
      case when s.replacement_chain_status='INVALID'
        then 'REPLACEMENT_VALIDATION' else c.phase end phase,
      c.result_json,
      case when s.replacement_chain_status='INVALID'
        then s.replacement_chain_error else c.error_json end error_json,
      coalesce(c.updated_at_utc,v_now) updated_at_utc
    from descendant_scope d
    join descendant_current_slots s on s.operation_id=d.operation_id
    left join public.invoice_operation_chunks c on c.id=s.current_chunk_id
  ),
  invoice_result_rows as materialized (
    select distinct c.root_operation_id,x.value::uuid invoice_id
    from descendant_chunks c
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(c.result_json->'invoice_ids')='array'
        then c.result_json->'invoice_ids' else '[]'::jsonb end) x(value)
    where x.value~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  invoice_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.invoice_id) order by r.invoice_id) invoice_ids
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.invoice_id) result_no
      from invoice_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  document_result_rows as materialized (
    select distinct d.root_operation_id,o.id document_operation_id
    from descendant_scope d
    join public.invoice_operations o on o.id=d.operation_id
    where o.operation_type='BUILD_DOCUMENT'
    union
    select distinct c.root_operation_id,
      (c.result_json->>'document_operation_id')::uuid
    from descendant_chunks c
    where coalesce(c.result_json->>'document_operation_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  document_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.document_operation_id)
        order by r.document_operation_id) document_operation_ids
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.document_operation_id) result_no
      from document_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  delivery_operation_result_rows as materialized (
    select distinct d.root_operation_id,o.id delivery_operation_id
    from descendant_scope d
    join public.invoice_operations o on o.id=d.operation_id
    where o.operation_type='DELIVER_INVOICES'
  ),
  delivery_operation_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.delivery_operation_id)
        order by r.delivery_operation_id) delivery_operation_ids
    from(
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.delivery_operation_id) result_no
      from delivery_operation_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),  mail_result_rows as materialized (
    select distinct c.root_operation_id,x.value::uuid mail_outbox_id
    from descendant_chunks c
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(c.result_json->'mail_outbox_ids')='array'
        then c.result_json->'mail_outbox_ids' else '[]'::jsonb end) x(value)
    where x.value~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    union
    select distinct c.root_operation_id,
      (c.result_json->>'mail_outbox_id')::uuid
    from descendant_chunks c
    where coalesce(c.result_json->>'mail_outbox_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  mail_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.mail_outbox_id)
        order by r.mail_outbox_id) mail_outbox_ids
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.mail_outbox_id) result_no
      from mail_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  issue_result_rows as materialized (
    select c.root_operation_id,c.entity_id invoice_id,
      c.status,c.phase,c.result_json,c.error_json,c.updated_at_utc,c.id
    from descendant_chunks c
    where c.chunk_type='ISSUE_INVOICE'
      and c.entity_type='INVOICE' and c.entity_id is not null
  ),
  issue_results as materialized (
    select r.root_operation_id,
      jsonb_agg(jsonb_build_object(
        'chunk_id',r.id,'invoice_id',r.invoice_id,
        'status',r.status,'phase',r.phase,
        'document_version_id',coalesce(
          r.result_json->>'issued_document_version_id',
          r.result_json->>'document_version_id'),
        'document_operation_id',r.result_json->>'document_operation_id',
        'delivery_operation_id',r.result_json->>'delivery_operation_id',
        'error_code',r.error_json->>'code')
        order by r.updated_at_utc,r.id) issue_outcomes
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.updated_at_utc,x.id) result_no
      from issue_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  descendant_blocked as materialized (
    select c.root_operation_id,
      jsonb_agg(jsonb_build_object(
        'chunk_id',c.id,'chunk_type',c.chunk_type,
        'entity_type',c.entity_type,'entity_id',c.entity_id,
        'status',c.status,'code',c.error_json->>'code')
        order by c.updated_at_utc desc,c.id)
        filter(where c.status in('BLOCKED','FAILED','DEAD_LETTER'))
        blocked_entities
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.updated_at_utc desc,x.id) result_no
      from descendant_chunks x
      where x.status in('BLOCKED','FAILED','DEAD_LETTER')
    ) c
    where c.result_no<=500
    group by c.root_operation_id
  ),
  category_counts as materialized (
    select t.id root_operation_id,
      (select count(*)::integer from invoice_result_rows r
        where r.root_operation_id=t.id) invoice_total,
      (select count(*)::integer from document_result_rows r
        where r.root_operation_id=t.id) document_total,
      (select count(*)::integer from issue_result_rows r
        where r.root_operation_id=t.id) issue_total,
      (select count(*)::integer from delivery_operation_result_rows r
        where r.root_operation_id=t.id) delivery_operation_total,
      (select count(*)::integer from mail_result_rows r
        where r.root_operation_id=t.id) mail_total,
      (select count(*)::integer from descendant_chunks r
        where r.root_operation_id=t.id
          and r.status in('BLOCKED','FAILED','DEAD_LETTER')) blocked_total
    from targets t
  ),
  terminal_counts as materialized (
    select t.id root_operation_id,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE')::integer
        issue_total,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='COMPLETE')::integer issue_complete,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT'))::integer
        issue_active,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='BLOCKED')::integer issue_blocked,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='FAILED')::integer issue_failed,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='DEAD_LETTER')::integer issue_dead,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='CANCELLED')::integer issue_cancelled,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='SUPERSEDED')::integer issue_superseded,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE')::integer
        delivery_total,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='COMPLETE')::integer delivery_complete,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT'))::integer
        delivery_active,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='BLOCKED')::integer delivery_blocked,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='FAILED')::integer delivery_failed,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='DEAD_LETTER')::integer delivery_dead,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='CANCELLED')::integer delivery_cancelled,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='SUPERSEDED')::integer delivery_superseded
    from targets t
    left join descendant_chunks c on c.root_operation_id=t.id
    group by t.id
  ),
  result_aggregates as materialized (
    select t.id operation_id,
      coalesce(i.invoice_ids,'[]'::jsonb) invoice_ids,
      coalesce(d.document_operation_ids,'[]'::jsonb)
        document_operation_ids,
      coalesce(delivery_ops.delivery_operation_ids,'[]'::jsonb)
        delivery_operation_ids,
      coalesce(m.mail_outbox_ids,'[]'::jsonb) mail_outbox_ids,
      coalesce(ir.issue_outcomes,'[]'::jsonb) issue_outcomes,
      coalesce(b.blocked_entities,'[]'::jsonb) blocked_entities,
      jsonb_build_object(
        'total_count',cc.invoice_total,
        'returned_count',least(cc.invoice_total,500),
        'truncated',cc.invoice_total>500) invoice_ids_page,
      jsonb_build_object(
        'total_count',cc.document_total,
        'returned_count',least(cc.document_total,500),
        'truncated',cc.document_total>500) document_operations_page,
      jsonb_build_object(
        'total_count',cc.issue_total,
        'returned_count',least(cc.issue_total,500),
        'truncated',cc.issue_total>500) issue_outcomes_page,
      jsonb_build_object(
        'total_count',cc.delivery_operation_total,
        'returned_count',least(cc.delivery_operation_total,500),
        'truncated',cc.delivery_operation_total>500)
        delivery_operations_page,
      jsonb_build_object(
        'total_count',cc.mail_total,
        'returned_count',least(cc.mail_total,500),
        'truncated',cc.mail_total>500) mail_ids_page,
      jsonb_build_object(
        'total_count',cc.blocked_total,
        'returned_count',least(cc.blocked_total,500),
        'truncated',cc.blocked_total>500) blocked_entities_page,
      (select count(*)::integer from descendant_scope ds
        where ds.root_operation_id=t.id) total_descendant_operations,
      least(500,(select count(*)::integer from descendant_scope ds
        where ds.root_operation_id=t.id)) returned_descendant_operations,
      (select count(*)>500 from descendant_scope ds
        where ds.root_operation_id=t.id) results_truncated,
      case when (select count(*)>500 from descendant_scope ds
          where ds.root_operation_id=t.id)
        then encode(digest(concat_ws('|',t.id::text,'DESCENDANTS','500'),
          'sha256'),'hex')
      end continuation_token,
      case
        when tc.issue_total=0 then 'NOT_REQUESTED'
        when tc.issue_complete=tc.issue_total then 'ISSUED'
        when tc.issue_cancelled=tc.issue_total then 'CANCELLED'
        when tc.issue_superseded=tc.issue_total then 'SUPERSEDED'
        when tc.issue_dead=tc.issue_total then 'DEAD_LETTER'
        when tc.issue_failed=tc.issue_total then 'FAILED'
        when tc.issue_complete>0 and tc.issue_active>0
          and tc.issue_blocked+tc.issue_failed+tc.issue_dead
            +tc.issue_cancelled+tc.issue_superseded=0
          then 'PARTIAL_IN_PROGRESS'
        when tc.issue_blocked+tc.issue_failed+tc.issue_dead
            +tc.issue_cancelled+tc.issue_superseded>0
          then 'PARTIAL_OR_BLOCKED'
        else 'IN_PROGRESS' end legal_issue_status,
      case
        when tc.delivery_total=0 then 'NOT_REQUESTED'
        when tc.delivery_complete=tc.delivery_total then 'PREPARED'
        when tc.delivery_cancelled=tc.delivery_total then 'CANCELLED'
        when tc.delivery_superseded=tc.delivery_total then 'SUPERSEDED'
        when tc.delivery_dead=tc.delivery_total then 'DEAD_LETTER'
        when tc.delivery_failed=tc.delivery_total then 'FAILED'
        when tc.delivery_blocked+tc.delivery_failed+tc.delivery_dead
            +tc.delivery_cancelled+tc.delivery_superseded>0
          then 'PARTIAL_OR_BLOCKED'
        else 'IN_PROGRESS' end delivery_status
    from targets t
    left join invoice_results i on i.root_operation_id=t.id
    left join document_results d on d.root_operation_id=t.id
    left join delivery_operation_results delivery_ops
      on delivery_ops.root_operation_id=t.id
    left join mail_results m on m.root_operation_id=t.id
    left join issue_results ir on ir.root_operation_id=t.id
    left join descendant_blocked b on b.root_operation_id=t.id
    join category_counts cc on cc.root_operation_id=t.id
    join terminal_counts tc on tc.root_operation_id=t.id
  ),
  updated as materialized (
    update public.invoice_operations o
    set status=d.derived_status,
      phase=case when d.missing_replacement_units>0
        then 'BLOCKED' else coalesce(d.current_phase,o.phase) end,
      total_units=d.total_units,chunk_count=d.total_units,
      completed_units=d.complete_units,
      failed_units=d.failed_units,
      requires_user_action=d.requires_action,
      progress_json=(coalesce(o.progress_json,'{}'::jsonb)
        ||jsonb_build_object(
          'total_units',d.total_units,'completed_units',d.complete_units,
          'failed_units',d.failed_units,
          'blocked_required_count',
            d.blocked_units+d.missing_replacement_units,
          'requires_user_action',d.requires_action,
          'child_operations',jsonb_build_object(
            'rows',cr.children,
            'total_count',cr.child_total,
            'returned_count',cr.child_returned,
            'truncated',cr.children_truncated))),
      result_json=coalesce(o.result_json,'{}'::jsonb)
        ||jsonb_build_object(
          'invoice_ids',ra.invoice_ids,
          'document_operation_ids',ra.document_operation_ids,
          'delivery_operation_ids',ra.delivery_operation_ids,
          'mail_outbox_ids',ra.mail_outbox_ids,
          'issue_outcomes',ra.issue_outcomes,
          'blocked_entities',ra.blocked_entities,
          'invoice_ids_page',ra.invoice_ids_page,
          'document_operations_page',ra.document_operations_page,
          'issue_outcomes_page',ra.issue_outcomes_page,
          'delivery_operations_page',ra.delivery_operations_page,
          'mail_ids_page',ra.mail_ids_page,
          'blocked_entities_page',ra.blocked_entities_page,
          'total_descendant_operations',ra.total_descendant_operations,
          'returned_descendant_operations',ra.returned_descendant_operations,
          'results_truncated',ra.results_truncated,
          'continuation_token',ra.continuation_token,
          'legal_issue_status',ra.legal_issue_status,
          'delivery_status',ra.delivery_status),
      error_json=case
        when d.missing_replacement_units>0 then jsonb_build_object(
          'code','MISSING_REPLACEMENT_WORK',
          'count',d.missing_replacement_units,
          'blocked_entities',d.blocker_summary)
        when d.failed_units>0 then coalesce(o.error_json,'{}'::jsonb)
          ||jsonb_build_object('blocked_entities',d.blocker_summary)
        else o.error_json end,
      started_at_utc=case when d.derived_status='RUNNING'
        then coalesce(o.started_at_utc,v_now) else o.started_at_utc end,
      completed_at_utc=case when d.derived_status='COMPLETE'
        then coalesce(o.completed_at_utc,v_now)
        when d.derived_status not in('CANCELLED','SUPERSEDED') then null
        else o.completed_at_utc end,
      failed_at_utc=case when d.derived_status in('FAILED','DEAD_LETTER')
        then coalesce(o.failed_at_utc,v_now)
        when d.derived_status not in('CANCELLED','SUPERSEDED') then null
        else o.failed_at_utc end,
      updated_at_utc=v_now,
      change_seq=case when
        o.status is distinct from d.derived_status
        or o.phase is distinct from case when d.missing_replacement_units>0
          then 'BLOCKED' else coalesce(d.current_phase,o.phase) end
        or o.total_units is distinct from d.total_units
        or o.completed_units is distinct from d.complete_units
        or o.failed_units is distinct from d.failed_units
        or o.requires_user_action is distinct from d.requires_action
        or exists(select 1 from ancestor_bumps ab where ab.id=o.id)
        or cr.descendant_change_seq>o.change_seq
        then nextval('public.invoice_operation_change_seq')
        else o.change_seq end
    from derived d
    join child_results cr on cr.operation_id=d.operation_id
    join result_aggregates ra on ra.operation_id=d.operation_id
    where o.id=d.operation_id
    returning o.id,o.status,o.phase,o.total_units,o.completed_units,
      o.failed_units,
      case when coalesce(o.progress_json->>'blocked_required_count','')
          ~'^[0-9]{1,9}$'
        then(o.progress_json->>'blocked_required_count')::integer else 0 end
        blocked_required_count,
      o.requires_user_action,o.change_seq
  )
  select u.id,u.status,u.phase,u.total_units,u.completed_units,u.failed_units,
    u.blocked_required_count,u.requires_user_action,u.change_seq
  from updated u
  order by u.id;
end;
$function$;

-- private._invoice_operation_rollup_batch(uuid[],timestamp with time zone,boolean)
CREATE OR REPLACE FUNCTION private._invoice_operation_rollup_batch(p_operation_ids uuid[], p_now_utc timestamp with time zone DEFAULT now(), p_propagate_ancestors boolean DEFAULT true)
 RETURNS TABLE(operation_id uuid, status text, phase text, total_units integer, completed_units integer, failed_units integer, blocked_required_count integer, requires_user_action boolean, change_seq bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_core_operation_ids uuid[] := array[]::uuid[];
  v_root_operation_ids uuid[] := array[]::uuid[];
begin
  /*
   * Run the generic rollup once and retain its exact operation scope.  Result
   * carrier statement triggers may update their batch root, so carrier writes
   * must complete in their own SQL statements before the root update below.
   * Keeping these writes in one data-modifying CTE causes PostgreSQL 27000
   * when the result-page trigger and updated_roots touch the same root tuple.
   */
  select coalesce(array_agg(core.operation_id order by core.operation_id),
                  array[]::uuid[])
  into v_core_operation_ids
  from private._invoice_operation_rollup_core_v8(
    p_operation_ids,
    v_now,
    p_propagate_ancestors
  ) core;

  select coalesce(array_agg(distinct operation.id order by operation.id),
                  array[]::uuid[])
  into v_root_operation_ids
  from public.invoice_operations operation
  where operation.id=any(v_core_operation_ids)
    and operation.operation_type in ('GENERATE_INVOICES','ISSUE_INVOICES')
    and operation.entity_type='INVOICE_BATCH'
    and operation.input_json->>'contract_version'
      ='INVOICE_BATCH_SELECTION_ROOT_V2';

  update public.invoice_operation_chunks carrier
  set
    status=case
      when child.status='COMPLETE' then 'COMPLETE'
      when child.status in ('BLOCKED','FAILED','DEAD_LETTER')
        then child.status
      else carrier.status
    end,
    phase=case
      when child.status='COMPLETE' then 'COMPLETE'
      when child.status in ('BLOCKED','FAILED','DEAD_LETTER')
        then child.status
      else carrier.phase
    end,
    document_version_id=coalesce(
      ready_version.id,
      carrier.document_version_id
    ),
    result_json=coalesce(carrier.result_json,'{}'::jsonb)
      || jsonb_build_object(
        'result_category',case
          when child.status='COMPLETE' then 'REGENERATED'
          when child.status='BLOCKED' then 'BLOCKED'
          when child.status in ('FAILED','DEAD_LETTER') then 'FAILED'
          else 'IN_PROGRESS'
        end,
        'document_operation_id',child.id,
        'document_version_id',coalesce(
          ready_version.id,
          carrier.document_version_id
        )
      ),
    completed_at_utc=case
      when child.status in ('COMPLETE','BLOCKED','FAILED','DEAD_LETTER')
        then coalesce(carrier.completed_at_utc,v_now)
      else carrier.completed_at_utc
    end,
    updated_at_utc=v_now
  from public.invoice_operations child
  left join lateral (
    select version.id
    from public.invoice_document_versions version
    where version.operation_id=child.id
      and version.entity_type='INVOICE'
      and version.purpose='DRAFT_PREVIEW'
      and version.status='READY'
    order by version.ready_at_utc desc nulls last,
      version.created_at_utc desc,
      version.id desc
    limit 1
  ) ready_version on true
  where carrier.operation_id=any(v_root_operation_ids)
    and carrier.is_manifest_member
    and carrier.phase='WAITING_DOCUMENT'
    and carrier.status='WAITING'
    and pg_input_is_valid(
      coalesce(carrier.result_json->>'document_operation_id',''),
      'uuid'
    )
    and child.id=(carrier.result_json->>'document_operation_id')::uuid
    and child.status in ('COMPLETE','BLOCKED','FAILED','DEAD_LETTER');

  update public.invoice_operation_chunks carrier
  set
    result_json=coalesce(carrier.result_json,'{}'::jsonb)
      || jsonb_build_object(
        'result_category',case
          when carrier.status='COMPLETE'
           and carrier.result_category in (
             'EXCLUDED','ALREADY_ACTIVE','REGENERATED',
             'ISSUED','ISSUED_SEND_BLOCKED'
           ) then carrier.result_category
          when carrier.status='COMPLETE'
           and carrier.chunk_type='GENERATION_GROUP'
           and coalesce(
             carrier.payload_json->>'row_kind',
             'CREATE_INVOICE'
           )='CREATE_INVOICE' then 'GENERATED'
          when carrier.status='COMPLETE'
           and carrier.chunk_type='GENERATION_GROUP'
            then 'REGENERATED'
          when carrier.status='COMPLETE'
           and carrier.chunk_type='ISSUE_INVOICE'
           and coalesce(
             (carrier.payload_json->>'blocked_for_sending')::boolean,
             false
           ) then 'ISSUED_SEND_BLOCKED'
          when carrier.status='COMPLETE'
           and carrier.chunk_type='ISSUE_INVOICE' then 'ISSUED'
          when carrier.status='BLOCKED' then 'BLOCKED'
          when carrier.status='SUPERSEDED' then 'CHANGED'
          when carrier.status in ('FAILED','DEAD_LETTER') then 'FAILED'
          else 'IN_PROGRESS'
        end
      ),
    updated_at_utc=v_now
  where carrier.operation_id=any(v_root_operation_ids)
    and carrier.is_manifest_member
    and carrier.manifest_committed
    and carrier.result_visible
    and carrier.result_category is distinct from case
      when carrier.status='COMPLETE'
       and carrier.result_category in (
         'EXCLUDED','ALREADY_ACTIVE','REGENERATED',
         'ISSUED','ISSUED_SEND_BLOCKED'
       ) then carrier.result_category
      when carrier.status='COMPLETE'
       and carrier.chunk_type='GENERATION_GROUP'
       and coalesce(
         carrier.payload_json->>'row_kind',
         'CREATE_INVOICE'
       )='CREATE_INVOICE' then 'GENERATED'
      when carrier.status='COMPLETE'
       and carrier.chunk_type='GENERATION_GROUP' then 'REGENERATED'
      when carrier.status='COMPLETE'
       and carrier.chunk_type='ISSUE_INVOICE'
       and coalesce(
         (carrier.payload_json->>'blocked_for_sending')::boolean,
         false
       ) then 'ISSUED_SEND_BLOCKED'
      when carrier.status='COMPLETE'
       and carrier.chunk_type='ISSUE_INVOICE' then 'ISSUED'
      when carrier.status='BLOCKED' then 'BLOCKED'
      when carrier.status='SUPERSEDED' then 'CHANGED'
      when carrier.status in ('FAILED','DEAD_LETTER') then 'FAILED'
      else 'IN_PROGRESS'
    end;

  return query
  with recursive
  roots as materialized (
    select root_id operation_id
    from unnest(v_root_operation_ids) root_id
  ),
  descendants(descendant_root_operation_id,operation_id,depth,path) as (
    select r.operation_id,r.operation_id,0,array[r.operation_id]::uuid[]
    from roots r
    union all
    select
      d.descendant_root_operation_id,
      child.id,
      d.depth+1,
      d.path||child.id
    from descendants d
    join public.invoice_operations child
      on child.parent_operation_id=d.operation_id
    where d.depth<16
      and not child.id=any(d.path)
  ),
  carriers as materialized (
    select
      o.id batch_root_id,
      o.operation_type,
      o.manifest_committed root_manifest_committed,
      o.release_complete,
      o.progress_json root_progress_json,
      c.id,
      c.status,
      c.phase,
      c.payload_json,
      c.result_json,
      c.result_category,
      c.manifest_committed,
      c.result_visible
    from public.invoice_operations o
    join roots r on r.operation_id=o.id
    left join public.invoice_operation_chunks c
      on c.operation_id=o.id
     and c.is_manifest_member
     and c.manifest_generation=o.manifest_generation
     and c.replaced_by_chunk_id is null
  ),
  carrier_counts as materialized (
    select
      c.batch_root_id,
      min(c.operation_type) operation_type,
      bool_or(c.root_manifest_committed) manifest_committed,
      bool_or(c.release_complete) release_complete,
      coalesce(max(case
        when c.operation_type='GENERATE_INVOICES'
         and coalesce(
           c.root_progress_json->>'candidate_total',
           ''
         )~'^[0-9]+$'
          then (c.root_progress_json->>'candidate_total')::integer
        when c.operation_type='ISSUE_INVOICES'
         and coalesce(
           c.root_progress_json->>'invoice_total',
           ''
         )~'^[0-9]+$'
          then (c.root_progress_json->>'invoice_total')::integer
      end),0) candidate_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
      )::integer selected_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
      )::integer expanded_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
          and c.manifest_committed
          and c.status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT'
          )
      )::integer queued_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
          and not c.manifest_committed
      )::integer release_pending_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
          and c.manifest_committed
          and coalesce(c.result_category,'') not in(
            'ALREADY_ACTIVE','BLOCKED','CHANGED','MISSING','FAILED'
          )
      )::integer released_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
          and c.result_category='ALREADY_ACTIVE'
      )::integer release_conflict_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
          and c.result_category in(
            'BLOCKED','CHANGED','MISSING','FAILED'
          )
      )::integer release_blocked_total,
      count(c.id) filter (
        where c.result_category='GENERATED'
      )::integer generated_total,
      count(c.id) filter (
        where c.result_category='REGENERATED'
      )::integer regenerated_total,
      count(c.id) filter (
        where c.result_category in ('ISSUED','ISSUED_SEND_BLOCKED')
      )::integer issued_total,
      count(c.id) filter (
        where c.result_category='ISSUED_SEND_BLOCKED'
      )::integer issued_send_blocked_total,
      count(c.id) filter (
        where c.result_category='ALREADY_ACTIVE'
      )::integer already_active_total,
      count(c.id) filter (
        where c.result_category='BLOCKED'
      )::integer blocked_total,
      count(c.id) filter (
        where c.result_category='CHANGED'
      )::integer changed_total,
      count(c.id) filter (
        where c.result_category='FAILED'
      )::integer failed_total,
      count(c.id) filter (
        where c.result_category='MISSING'
           or c.payload_json->>'manifest_outcome'='MISSING'
      )::integer missing_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='EXCLUDED'
      )::integer excluded_total,
      count(c.id) filter (
        where c.payload_json->>'manifest_outcome'='SELECTED'
          and c.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      )::integer in_progress_total
    from carriers c
    group by c.batch_root_id
  ),
  delivery_counts as materialized (
    select
      d.descendant_root_operation_id as batch_root_id,
      count(c.id) filter (
        where c.chunk_type='DELIVERY_PREPARE'
          and c.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      )::integer delivery_pending_total,
      count(c.id) filter (
        where c.chunk_type='DELIVERY_PREPARE'
          and c.status='COMPLETE'
      )::integer delivery_complete_total,
      count(c.id) filter (
        where c.chunk_type='DELIVERY_PREPARE'
          and c.status in ('BLOCKED','FAILED','DEAD_LETTER')
      )::integer delivery_blocked_total
    from descendants d
    left join public.invoice_operation_chunks c
      on c.operation_id=d.operation_id
     and c.replaced_by_chunk_id is null
    group by d.descendant_root_operation_id
  ),
  progress as materialized (
    select
      jsonb_build_object(
        'contract_version','INVOICE_BATCH_PROGRESS_V2',
        'manifest_generation',root.manifest_generation,
        'manifest_status',coalesce(
          nullif(root.progress_json->>'manifest_status',''),
          case
            when root.release_complete then 'RELEASE_COMPLETE'
            when root.manifest_committed then 'RELEASE_MANIFEST'
            else 'BUILDING'
          end
        ),
        'manifest_committed',counts.manifest_committed,
        'expected_scan_total',case
          when coalesce(
            root.progress_json->>'expected_scan_total',
            ''
          ) ~ '^[0-9]+$'
            then (root.progress_json->>'expected_scan_total')::integer
          else counts.candidate_total
        end,
        'scanned_total',case
          when coalesce(
            root.progress_json->>'scanned_total',
            ''
          ) ~ '^[0-9]+$'
            then (root.progress_json->>'scanned_total')::integer
          else counts.expanded_total
        end,
        'selection_expansion_pending',not counts.manifest_committed,
        'release_pending_total',case
          when coalesce(
            root.progress_json->>'release_pending_total',
            ''
          ) ~ '^[0-9]+$'
            then (root.progress_json->>'release_pending_total')::integer
          else counts.release_pending_total
        end,
        'released_total',case
          when coalesce(
            root.progress_json->>'released_total',
            ''
          ) ~ '^[0-9]+$'
            then (root.progress_json->>'released_total')::integer
          else counts.released_total
        end,
        'release_conflict_total',case
          when coalesce(
            root.progress_json->>'release_conflict_total',
            ''
          ) ~ '^[0-9]+$'
            then (root.progress_json->>'release_conflict_total')::integer
          else counts.release_conflict_total
        end,
        'release_blocked_total',case
          when coalesce(
            root.progress_json->>'release_blocked_total',
            ''
          ) ~ '^[0-9]+$'
            then (root.progress_json->>'release_blocked_total')::integer
          else counts.release_blocked_total
        end,
        'release_complete',counts.release_complete,
        'committed_at_utc',root.progress_json->'committed_at_utc',
        'superseded_manifest_generation',
          root.progress_json->'superseded_manifest_generation',
        'candidate_total',case
          when counts.operation_type='GENERATE_INVOICES'
            then counts.candidate_total
          else 0
        end,
        'invoice_total',case
          when counts.operation_type='ISSUE_INVOICES'
            then counts.candidate_total
          else 0
        end,
        'selected_total',counts.selected_total,
        'expanded_total',counts.expanded_total,
        'queued_total',counts.queued_total,
        'generated_total',counts.generated_total,
        'regenerated_total',counts.regenerated_total,
        'issued_total',counts.issued_total,
        'issued_send_blocked_total',counts.issued_send_blocked_total,
        'already_active_total',counts.already_active_total,
        'blocked_total',counts.blocked_total,
        'changed_total',counts.changed_total,
        'failed_total',counts.failed_total,
        'excluded_total',counts.excluded_total,
        'missing_total',counts.missing_total,
        'in_progress_total',counts.in_progress_total,
        'delivery_pending_total',coalesce(delivery.delivery_pending_total,0),
        'delivery_complete_total',coalesce(delivery.delivery_complete_total,0),
        'delivery_blocked_total',coalesce(delivery.delivery_blocked_total,0),
        'final',counts.manifest_committed
          and counts.release_complete
          and coalesce(
            case
              when coalesce(
                root.progress_json->>'release_pending_total',
                ''
              ) ~ '^[0-9]+$'
                then (
                  root.progress_json->>'release_pending_total'
                )::integer
              else 0
            end,
            0
          )=0
          and counts.in_progress_total=0
          and coalesce(delivery.delivery_pending_total,0)=0
      ) progress_json,
      counts.*
    from carrier_counts counts
    join public.invoice_operations root
      on root.id=counts.batch_root_id
    left join delivery_counts delivery
      on delivery.batch_root_id=counts.batch_root_id
  ),
  updated_roots as materialized (
    update public.invoice_operations root
    set
      status=case
        when root.status='CANCELLED' then root.status
        when root.status in ('FAILED','DEAD_LETTER')
         and not p.manifest_committed then root.status
        when root.status='BLOCKED'
         and root.error_json->>'code'
          ='BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
          then root.status
        when not p.manifest_committed
          or not p.release_complete then 'QUEUED'
        when coalesce(
          (p.progress_json->>'release_pending_total')::integer,
          0
        )>0 then 'QUEUED'
        when p.in_progress_total>0
          or coalesce((p.progress_json->>'delivery_pending_total')::integer,0)>0
          then 'RUNNING'
        else 'COMPLETE'
      end,
      phase=case
        when root.status='CANCELLED' then root.phase
        when root.status in ('FAILED','DEAD_LETTER')
         and not p.manifest_committed then root.phase
        when root.status='BLOCKED'
         and root.error_json->>'code'
          ='BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
          then root.phase
        when not p.manifest_committed then 'BUILD_MANIFEST'
        when not p.release_complete then 'RELEASE_MANIFEST'
        when coalesce(
          (p.progress_json->>'release_pending_total')::integer,
          0
        )>0 then 'RELEASE_MANIFEST'
        when p.in_progress_total>0
          or coalesce((p.progress_json->>'delivery_pending_total')::integer,0)>0
          then 'BUSINESS_WORK'
        else 'TERMINAL'
      end,
      total_units=greatest(p.candidate_total,1),
      completed_units=greatest(
        p.candidate_total-p.in_progress_total,
        0
      ),
      failed_units=p.failed_total,
      progress_json=coalesce(root.progress_json,'{}'::jsonb)
        || p.progress_json,
      result_json=coalesce(root.result_json,'{}'::jsonb)
        || jsonb_build_object('batch_progress',p.progress_json),
      requires_user_action=(
        root.status in ('FAILED','DEAD_LETTER')
        or p.failed_total+p.blocked_total+p.changed_total>0
      ),
      completed_at_utc=case
        when root.status in ('FAILED','DEAD_LETTER')
         and not p.manifest_committed
          then coalesce(root.completed_at_utc,v_now)
        when p.manifest_committed
         and p.release_complete
         and coalesce(
           (p.progress_json->>'release_pending_total')::integer,
           0
         )=0
         and p.in_progress_total=0
         and coalesce(
           (p.progress_json->>'delivery_pending_total')::integer,
           0
         )=0 then coalesce(root.completed_at_utc,v_now)
        else null
      end,
      updated_at_utc=case
        when coalesce(root.progress_json,'{}'::jsonb)
          is distinct from (
            coalesce(root.progress_json,'{}'::jsonb)
            || p.progress_json
          ) then v_now
        else root.updated_at_utc
      end,
      change_seq=case
        when coalesce(root.progress_json,'{}'::jsonb)
          is distinct from (
            coalesce(root.progress_json,'{}'::jsonb)
            || p.progress_json
          )
          or root.status is distinct from case
            when root.status='CANCELLED' then root.status
            when root.status in ('FAILED','DEAD_LETTER')
             and not p.manifest_committed then root.status
            when root.status='BLOCKED'
             and root.error_json->>'code'
              ='BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
              then root.status
            when not p.manifest_committed
              or not p.release_complete then 'QUEUED'
            when coalesce(
              (p.progress_json->>'release_pending_total')::integer,
              0
            )>0 then 'QUEUED'
            when p.in_progress_total>0
              or coalesce(
                (p.progress_json->>'delivery_pending_total')::integer,
                0
              )>0 then 'RUNNING'
            else 'COMPLETE'
          end
          then nextval('public.invoice_operation_change_seq')
        else root.change_seq
      end
    from progress p
    where root.id=p.batch_root_id
    returning root.id
  )
  select
    operation.id,
    operation.status,
    operation.phase,
    operation.total_units,
    operation.completed_units,
    operation.failed_units,
    case
      when coalesce(
        operation.progress_json->>'blocked_required_count',
        ''
      ) ~ '^[0-9]{1,9}$'
        then (operation.progress_json->>'blocked_required_count')::integer
      else 0
    end,
    operation.requires_user_action,
    operation.change_seq
  from unnest(v_core_operation_ids) core(operation_id)
  join public.invoice_operations operation on operation.id=core.operation_id
  where (select count(*) from updated_roots)>=0
  order by operation.id;
end;
$function$;

-- private._invoice_operation_rollup_core_v8(uuid[],timestamp with time zone,boolean)
CREATE OR REPLACE FUNCTION private._invoice_operation_rollup_core_v8(p_operation_ids uuid[], p_now_utc timestamp with time zone DEFAULT now(), p_propagate_ancestors boolean DEFAULT true)
 RETURNS TABLE(operation_id uuid, status text, phase text, total_units integer, completed_units integer, failed_units integer, blocked_required_count integer, requires_user_action boolean, change_seq bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
begin
  return query
  with recursive requested as materialized (
    select distinct x.id
    from unnest(coalesce(p_operation_ids,array[]::uuid[])) x(id)
    where x.id is not null
  ),
  scope(id,depth) as (
    select r.id,0 from requested r
    union
    select o.parent_operation_id,s.depth+1
    from scope s join public.invoice_operations o on o.id=s.id
    where p_propagate_ancestors and o.parent_operation_id is not null
      and s.depth<16
  ),
  targets as materialized (
    select distinct id from scope where id is not null
  ),
  ancestor_bumps as materialized (
    select distinct id from scope where id is not null and depth>0
  ),
  target_ranked as materialized (
    select t.id,
      row_number() over(order by t.id) operation_no
    from targets t
  ),
  target_pages as materialized (
    select ((t.operation_no-1)/500)::integer page_no,
      array_agg(t.id order by t.id) operation_ids
    from target_ranked t
    group by ((t.operation_no-1)/500)::integer
  ),
  current_slots as materialized (
    select cc.*
    from target_pages a
    cross join lateral private._invoice_current_chunks_batch(
      a.operation_ids,null,null,10000) cc
  ),
  current_chunks as materialized (
    select s.logical_slot_key,
      coalesce(c.id,s.current_chunk_id) id,s.operation_id,s.chunk_type,
      s.level_no,s.sequence_no,s.work_key,s.plan_generation,
      s.entity_type,s.entity_id,s.document_version_id,s.document_asset_id,
      s.input_document_version_id,
      case when s.replacement_chain_status='INVALID'
        then 'BLOCKED' else c.status end status,
      case when s.replacement_chain_status='INVALID'
        then 'REPLACEMENT_VALIDATION' else c.phase end phase,
      c.payload_json,c.progress_json,c.result_json,
      case when s.replacement_chain_status='INVALID'
        then s.replacement_chain_error else c.error_json end error_json,
      coalesce(c.updated_at_utc,v_now) updated_at_utc,
      s.replacement_chain_status,s.replacement_chain_error
    from current_slots s
    left join public.invoice_operation_chunks c on c.id=s.current_chunk_id
  ),
  counts as materialized (
    select t.id operation_id,count(c.logical_slot_key)::integer total_units,
      count(*) filter(where c.status='QUEUED')::integer queued_units,
      count(*) filter(where c.status='RUNNING')::integer running_units,
      count(*) filter(where c.status='WAITING')::integer waiting_units,
      count(*) filter(where c.status='RETRY_WAIT')::integer retry_units,
      count(*) filter(where c.status='BLOCKED')::integer blocked_units,
      count(*) filter(where c.status='COMPLETE')::integer complete_units,
      count(*) filter(where c.status='FAILED')::integer failed_only_units,
      count(*) filter(where c.status='DEAD_LETTER')::integer dead_units,
      count(*) filter(where c.status='CANCELLED')::integer cancelled_units,
      count(*) filter(where c.status='SUPERSEDED')::integer superseded_units,
      count(*) filter(where c.replacement_chain_status='INVALID')::integer
        missing_replacement_units,
      (count(*) filter(where c.status in(
        'FAILED','DEAD_LETTER','BLOCKED'))
       +count(*) filter(where c.replacement_chain_status='INVALID'
          and c.status<>'BLOCKED'))::integer failed_units,
      (array_agg(c.phase order by
        case c.status when 'RUNNING' then 0 when 'QUEUED' then 1
          when 'RETRY_WAIT' then 2 when 'BLOCKED' then 3 when 'WAITING' then 4
          else 5 end,c.updated_at_utc desc,c.id)
        filter(where c.id is not null))[1] current_phase,
      coalesce(jsonb_agg(jsonb_build_object(
        'chunk_id',c.id,'chunk_type',c.chunk_type,'entity_type',c.entity_type,
        'entity_id',c.entity_id,'code',c.error_json->>'code',
        'replacement_chain_status',c.replacement_chain_status)
        order by c.updated_at_utc desc,c.id)
        filter(where c.status in('BLOCKED','FAILED','DEAD_LETTER')),
        '[]'::jsonb) blocker_summary
    from targets t
    left join current_chunks c on c.operation_id=t.id
    group by t.id
  ),
  derived as materialized (
    select c.*,
      case
        when o.status in('CANCELLED','SUPERSEDED') then o.status
        when c.missing_replacement_units>0 then 'BLOCKED'
        when c.running_units>0 then 'RUNNING'
        when c.queued_units>0 then 'QUEUED'
        when c.retry_units>0 then 'RETRY_WAIT'
        when c.blocked_units>0 then 'BLOCKED'
        when c.waiting_units>0 then 'WAITING'
        when c.dead_units>0 then 'DEAD_LETTER'
        when c.failed_only_units>0 then 'FAILED'
        when c.total_units>0 and c.complete_units=c.total_units then 'COMPLETE'
        when c.total_units>0 and c.cancelled_units=c.total_units then 'CANCELLED'
        when c.total_units>0 and c.superseded_units=c.total_units then 'SUPERSEDED'
        when c.cancelled_units>0 then 'BLOCKED'
        else o.status
      end derived_status,
      c.blocked_units>0 or c.dead_units>0 or c.failed_only_units>0
        or c.missing_replacement_units>0
        requires_action
    from counts c join public.invoice_operations o on o.id=c.operation_id
  ),
  child_rows as materialized (
    select parent.id operation_id,child.id child_id,
      child.operation_type,child.status,child.phase,child.change_seq,
      child.entity_id,child.error_json->>'code' error_code,
      row_number() over(partition by parent.id
        order by child.created_at_utc,child.id) child_no,
      count(*) over(partition by parent.id)::integer child_total
    from public.invoice_operations parent
    join targets t on t.id=parent.id
    join public.invoice_operations child
      on child.parent_operation_id=parent.id
  ),
  child_results as materialized (
    select t.id operation_id,
      coalesce(jsonb_agg(jsonb_build_object(
        'operation_id',child.child_id,
        'operation_type',child.operation_type,
        'status',child.status,'phase',child.phase,
        'change_seq',child.change_seq,
        'entity_id',child.entity_id,
        'error_code',child.error_code)
        order by child.child_no)
        filter(where child.child_no<=200),'[]'::jsonb) children,
      coalesce(max(child.child_total),0)::integer child_total,
      least(coalesce(max(child.child_total),0),200)::integer child_returned,
      coalesce(max(child.child_total),0)>200 children_truncated,
      coalesce(max(child.change_seq),0) descendant_change_seq
    from targets t
    left join child_rows child on child.operation_id=t.id
    group by t.id
  ),
  descendant_tree(root_operation_id,operation_id,depth,path) as (
    select t.id,t.id,0,array[t.id]::uuid[] from targets t
    union all
    select d.root_operation_id,o.id,d.depth+1,d.path||o.id
    from descendant_tree d
    join public.invoice_operations o
      on o.parent_operation_id=d.operation_id
    where not o.id=any(d.path)
  ),
  descendant_ranked as materialized (
    select d.*,
      row_number() over(
        partition by d.root_operation_id
        order by d.depth,d.operation_id) descendant_no
    from descendant_tree d
  ),
  descendant_scope as materialized (
    select d.root_operation_id,d.operation_id,d.depth,d.descendant_no
    from descendant_ranked d
  ),
  descendant_operation_ids as materialized (
    select d.operation_id,
      row_number() over(order by d.operation_id) operation_no
    from (
      select distinct scoped.operation_id
      from descendant_scope scoped
    ) d
  ),
  descendant_operation_pages as materialized (
    select ((d.operation_no-1)/500)::integer page_no,
      array_agg(d.operation_id order by d.operation_id) operation_ids
    from descendant_operation_ids d
    group by ((d.operation_no-1)/500)::integer
  ),
  descendant_current_slots as materialized (
    select cc.*
    from descendant_operation_pages a
    cross join lateral private._invoice_current_chunks_batch(
      a.operation_ids,null,null,10000) cc
  ),
  descendant_chunks as materialized (
    select d.root_operation_id,
      coalesce(c.id,s.current_chunk_id) id,s.operation_id,s.chunk_type,
      s.entity_type,s.entity_id,
      case when s.replacement_chain_status='INVALID'
        then 'BLOCKED' else c.status end status,
      case when s.replacement_chain_status='INVALID'
        then 'REPLACEMENT_VALIDATION' else c.phase end phase,
      c.result_json,
      case when s.replacement_chain_status='INVALID'
        then s.replacement_chain_error else c.error_json end error_json,
      coalesce(c.updated_at_utc,v_now) updated_at_utc
    from descendant_scope d
    join descendant_current_slots s on s.operation_id=d.operation_id
    left join public.invoice_operation_chunks c on c.id=s.current_chunk_id
  ),
  invoice_result_rows as materialized (
    select distinct c.root_operation_id,x.value::uuid invoice_id
    from descendant_chunks c
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(c.result_json->'invoice_ids')='array'
        then c.result_json->'invoice_ids' else '[]'::jsonb end) x(value)
    where x.value~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  invoice_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.invoice_id) order by r.invoice_id) invoice_ids
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.invoice_id) result_no
      from invoice_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  document_result_rows as materialized (
    select distinct d.root_operation_id,o.id document_operation_id
    from descendant_scope d
    join public.invoice_operations o on o.id=d.operation_id
    where o.operation_type='BUILD_DOCUMENT'
    union
    select distinct c.root_operation_id,
      (c.result_json->>'document_operation_id')::uuid
    from descendant_chunks c
    where coalesce(c.result_json->>'document_operation_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  document_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.document_operation_id)
        order by r.document_operation_id) document_operation_ids
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.document_operation_id) result_no
      from document_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  delivery_operation_result_rows as materialized (
    select distinct d.root_operation_id,o.id delivery_operation_id
    from descendant_scope d
    join public.invoice_operations o on o.id=d.operation_id
    where o.operation_type='DELIVER_INVOICES'
  ),
  delivery_operation_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.delivery_operation_id)
        order by r.delivery_operation_id) delivery_operation_ids
    from(
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.delivery_operation_id) result_no
      from delivery_operation_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),  mail_result_rows as materialized (
    select distinct c.root_operation_id,x.value::uuid mail_outbox_id
    from descendant_chunks c
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(c.result_json->'mail_outbox_ids')='array'
        then c.result_json->'mail_outbox_ids' else '[]'::jsonb end) x(value)
    where x.value~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    union
    select distinct c.root_operation_id,
      (c.result_json->>'mail_outbox_id')::uuid
    from descendant_chunks c
    where coalesce(c.result_json->>'mail_outbox_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  mail_results as materialized (
    select r.root_operation_id,
      jsonb_agg(to_jsonb(r.mail_outbox_id)
        order by r.mail_outbox_id) mail_outbox_ids
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.mail_outbox_id) result_no
      from mail_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  issue_result_rows as materialized (
    select c.root_operation_id,c.entity_id invoice_id,
      c.status,c.phase,c.result_json,c.error_json,c.updated_at_utc,c.id
    from descendant_chunks c
    where c.chunk_type='ISSUE_INVOICE'
      and c.entity_type='INVOICE' and c.entity_id is not null
  ),
  issue_results as materialized (
    select r.root_operation_id,
      jsonb_agg(jsonb_build_object(
        'chunk_id',r.id,'invoice_id',r.invoice_id,
        'status',r.status,'phase',r.phase,
        'document_version_id',coalesce(
          r.result_json->>'issued_document_version_id',
          r.result_json->>'document_version_id'),
        'document_operation_id',r.result_json->>'document_operation_id',
        'delivery_operation_id',r.result_json->>'delivery_operation_id',
        'error_code',r.error_json->>'code')
        order by r.updated_at_utc,r.id) issue_outcomes
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.updated_at_utc,x.id) result_no
      from issue_result_rows x
    ) r
    where r.result_no<=500
    group by r.root_operation_id
  ),
  descendant_blocked as materialized (
    select c.root_operation_id,
      jsonb_agg(jsonb_build_object(
        'chunk_id',c.id,'chunk_type',c.chunk_type,
        'entity_type',c.entity_type,'entity_id',c.entity_id,
        'status',c.status,'code',c.error_json->>'code')
        order by c.updated_at_utc desc,c.id)
        filter(where c.status in('BLOCKED','FAILED','DEAD_LETTER'))
        blocked_entities
    from (
      select x.*,row_number() over(partition by x.root_operation_id
        order by x.updated_at_utc desc,x.id) result_no
      from descendant_chunks x
      where x.status in('BLOCKED','FAILED','DEAD_LETTER')
    ) c
    where c.result_no<=500
    group by c.root_operation_id
  ),
  category_counts as materialized (
    select t.id root_operation_id,
      (select count(*)::integer from invoice_result_rows r
        where r.root_operation_id=t.id) invoice_total,
      (select count(*)::integer from document_result_rows r
        where r.root_operation_id=t.id) document_total,
      (select count(*)::integer from issue_result_rows r
        where r.root_operation_id=t.id) issue_total,
      (select count(*)::integer from delivery_operation_result_rows r
        where r.root_operation_id=t.id) delivery_operation_total,
      (select count(*)::integer from mail_result_rows r
        where r.root_operation_id=t.id) mail_total,
      (select count(*)::integer from descendant_chunks r
        where r.root_operation_id=t.id
          and r.status in('BLOCKED','FAILED','DEAD_LETTER')) blocked_total
    from targets t
  ),
  terminal_counts as materialized (
    select t.id root_operation_id,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE')::integer
        issue_total,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='COMPLETE')::integer issue_complete,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT'))::integer
        issue_active,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='BLOCKED')::integer issue_blocked,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='FAILED')::integer issue_failed,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='DEAD_LETTER')::integer issue_dead,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='CANCELLED')::integer issue_cancelled,
      count(*) filter(where c.chunk_type='ISSUE_INVOICE'
        and c.status='SUPERSEDED')::integer issue_superseded,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE')::integer
        delivery_total,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='COMPLETE')::integer delivery_complete,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT'))::integer
        delivery_active,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='BLOCKED')::integer delivery_blocked,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='FAILED')::integer delivery_failed,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='DEAD_LETTER')::integer delivery_dead,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='CANCELLED')::integer delivery_cancelled,
      count(*) filter(where c.chunk_type='DELIVERY_PREPARE'
        and c.status='SUPERSEDED')::integer delivery_superseded
    from targets t
    left join descendant_chunks c on c.root_operation_id=t.id
    group by t.id
  ),
  result_aggregates as materialized (
    select t.id operation_id,
      coalesce(i.invoice_ids,'[]'::jsonb) invoice_ids,
      coalesce(d.document_operation_ids,'[]'::jsonb)
        document_operation_ids,
      coalesce(delivery_ops.delivery_operation_ids,'[]'::jsonb)
        delivery_operation_ids,
      coalesce(m.mail_outbox_ids,'[]'::jsonb) mail_outbox_ids,
      coalesce(ir.issue_outcomes,'[]'::jsonb) issue_outcomes,
      coalesce(b.blocked_entities,'[]'::jsonb) blocked_entities,
      jsonb_build_object(
        'total_count',cc.invoice_total,
        'returned_count',least(cc.invoice_total,500),
        'truncated',cc.invoice_total>500) invoice_ids_page,
      jsonb_build_object(
        'total_count',cc.document_total,
        'returned_count',least(cc.document_total,500),
        'truncated',cc.document_total>500) document_operations_page,
      jsonb_build_object(
        'total_count',cc.issue_total,
        'returned_count',least(cc.issue_total,500),
        'truncated',cc.issue_total>500) issue_outcomes_page,
      jsonb_build_object(
        'total_count',cc.delivery_operation_total,
        'returned_count',least(cc.delivery_operation_total,500),
        'truncated',cc.delivery_operation_total>500)
        delivery_operations_page,
      jsonb_build_object(
        'total_count',cc.mail_total,
        'returned_count',least(cc.mail_total,500),
        'truncated',cc.mail_total>500) mail_ids_page,
      jsonb_build_object(
        'total_count',cc.blocked_total,
        'returned_count',least(cc.blocked_total,500),
        'truncated',cc.blocked_total>500) blocked_entities_page,
      (select count(*)::integer from descendant_scope ds
        where ds.root_operation_id=t.id) total_descendant_operations,
      least(500,(select count(*)::integer from descendant_scope ds
        where ds.root_operation_id=t.id)) returned_descendant_operations,
      (select count(*)>500 from descendant_scope ds
        where ds.root_operation_id=t.id) results_truncated,
      case when (select count(*)>500 from descendant_scope ds
          where ds.root_operation_id=t.id)
        then encode(digest(concat_ws('|',t.id::text,'DESCENDANTS','500'),
          'sha256'),'hex')
      end continuation_token,
      case
        when tc.issue_total=0 then 'NOT_REQUESTED'
        when tc.issue_complete=tc.issue_total then 'ISSUED'
        when tc.issue_cancelled=tc.issue_total then 'CANCELLED'
        when tc.issue_superseded=tc.issue_total then 'SUPERSEDED'
        when tc.issue_dead=tc.issue_total then 'DEAD_LETTER'
        when tc.issue_failed=tc.issue_total then 'FAILED'
        when tc.issue_complete>0 and tc.issue_active>0
          and tc.issue_blocked+tc.issue_failed+tc.issue_dead
            +tc.issue_cancelled+tc.issue_superseded=0
          then 'PARTIAL_IN_PROGRESS'
        when tc.issue_blocked+tc.issue_failed+tc.issue_dead
            +tc.issue_cancelled+tc.issue_superseded>0
          then 'PARTIAL_OR_BLOCKED'
        else 'IN_PROGRESS' end legal_issue_status,
      case
        when tc.delivery_total=0 then 'NOT_REQUESTED'
        when tc.delivery_complete=tc.delivery_total then 'PREPARED'
        when tc.delivery_cancelled=tc.delivery_total then 'CANCELLED'
        when tc.delivery_superseded=tc.delivery_total then 'SUPERSEDED'
        when tc.delivery_dead=tc.delivery_total then 'DEAD_LETTER'
        when tc.delivery_failed=tc.delivery_total then 'FAILED'
        when tc.delivery_blocked+tc.delivery_failed+tc.delivery_dead
            +tc.delivery_cancelled+tc.delivery_superseded>0
          then 'PARTIAL_OR_BLOCKED'
        else 'IN_PROGRESS' end delivery_status
    from targets t
    left join invoice_results i on i.root_operation_id=t.id
    left join document_results d on d.root_operation_id=t.id
    left join delivery_operation_results delivery_ops
      on delivery_ops.root_operation_id=t.id
    left join mail_results m on m.root_operation_id=t.id
    left join issue_results ir on ir.root_operation_id=t.id
    left join descendant_blocked b on b.root_operation_id=t.id
    join category_counts cc on cc.root_operation_id=t.id
    join terminal_counts tc on tc.root_operation_id=t.id
  ),
  updated as materialized (
    update public.invoice_operations o
    set status=d.derived_status,
      phase=case when d.missing_replacement_units>0
        then 'BLOCKED' else coalesce(d.current_phase,o.phase) end,
      total_units=d.total_units,chunk_count=d.total_units,
      completed_units=d.complete_units,
      failed_units=d.failed_units,
      requires_user_action=d.requires_action,
      progress_json=(coalesce(o.progress_json,'{}'::jsonb)
        ||jsonb_build_object(
          'total_units',d.total_units,'completed_units',d.complete_units,
          'failed_units',d.failed_units,
          'blocked_required_count',
            d.blocked_units+d.missing_replacement_units,
          'requires_user_action',d.requires_action,
          'child_operations',jsonb_build_object(
            'rows',cr.children,
            'total_count',cr.child_total,
            'returned_count',cr.child_returned,
            'truncated',cr.children_truncated))),
      result_json=coalesce(o.result_json,'{}'::jsonb)
        ||jsonb_build_object(
          'invoice_ids',ra.invoice_ids,
          'document_operation_ids',ra.document_operation_ids,
          'delivery_operation_ids',ra.delivery_operation_ids,
          'mail_outbox_ids',ra.mail_outbox_ids,
          'issue_outcomes',ra.issue_outcomes,
          'blocked_entities',ra.blocked_entities,
          'invoice_ids_page',ra.invoice_ids_page,
          'document_operations_page',ra.document_operations_page,
          'issue_outcomes_page',ra.issue_outcomes_page,
          'delivery_operations_page',ra.delivery_operations_page,
          'mail_ids_page',ra.mail_ids_page,
          'blocked_entities_page',ra.blocked_entities_page,
          'total_descendant_operations',ra.total_descendant_operations,
          'returned_descendant_operations',ra.returned_descendant_operations,
          'results_truncated',ra.results_truncated,
          'continuation_token',ra.continuation_token,
          'legal_issue_status',ra.legal_issue_status,
          'delivery_status',ra.delivery_status),
      error_json=case
        when d.missing_replacement_units>0 then jsonb_build_object(
          'code','MISSING_REPLACEMENT_WORK',
          'count',d.missing_replacement_units,
          'blocked_entities',d.blocker_summary)
        when d.failed_units>0 then coalesce(o.error_json,'{}'::jsonb)
          ||jsonb_build_object('blocked_entities',d.blocker_summary)
        else o.error_json end,
      started_at_utc=case when d.derived_status='RUNNING'
        then coalesce(o.started_at_utc,v_now) else o.started_at_utc end,
      completed_at_utc=case when d.derived_status='COMPLETE'
        then coalesce(o.completed_at_utc,v_now)
        when d.derived_status not in('CANCELLED','SUPERSEDED') then null
        else o.completed_at_utc end,
      failed_at_utc=case when d.derived_status in('FAILED','DEAD_LETTER')
        then coalesce(o.failed_at_utc,v_now)
        when d.derived_status not in('CANCELLED','SUPERSEDED') then null
        else o.failed_at_utc end,
      updated_at_utc=v_now,
      change_seq=case when
        o.status is distinct from d.derived_status
        or o.phase is distinct from case when d.missing_replacement_units>0
          then 'BLOCKED' else coalesce(d.current_phase,o.phase) end
        or o.total_units is distinct from d.total_units
        or o.completed_units is distinct from d.complete_units
        or o.failed_units is distinct from d.failed_units
        or o.requires_user_action is distinct from d.requires_action
        or exists(select 1 from ancestor_bumps ab where ab.id=o.id)
        or cr.descendant_change_seq>o.change_seq
        then nextval('public.invoice_operation_change_seq')
        else o.change_seq end
    from derived d
    join child_results cr on cr.operation_id=d.operation_id
    join result_aggregates ra on ra.operation_id=d.operation_id
    where o.id=d.operation_id
    returning o.id,o.status,o.phase,o.total_units,o.completed_units,
      o.failed_units,
      case when coalesce(o.progress_json->>'blocked_required_count','')
          ~'^[0-9]{1,9}$'
        then(o.progress_json->>'blocked_required_count')::integer else 0 end
        blocked_required_count,
      o.requires_user_action,o.change_seq
  )
  select u.id,u.status,u.phase,u.total_units,u.completed_units,u.failed_units,
    u.blocked_required_count,u.requires_user_action,u.change_seq
  from updated u
  order by u.id;
end;
$function$;

-- private._invoice_operation_start_batch_legacy_20260726(jsonb,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_operation_start_batch_legacy_20260726(p_commands jsonb, p_actor_user_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_jwt_role text:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    auth.jwt()->>'role','');
  v_auth_user uuid:=auth.uid();
  v_result jsonb;
begin
  if jsonb_typeof(p_commands)<>'array'
     or jsonb_array_length(p_commands)<1
     or jsonb_array_length(p_commands)>1000 then
    raise exception using errcode='22023',
      message='p_commands must be a JSON array containing 1..1000 commands';
  end if;

  if p_actor_user_id is null
     or not exists(select 1 from public.tms_users u
       where u.id=p_actor_user_id and u.is_active and lower(u.role)='admin')
     or(v_jwt_role<>'service_role' and v_auth_user is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='Active administrator actor and matching authenticated/service caller required';
  end if;

  with raw as materialized (
    select e.ordinality::integer command_no,e.value command_json,
      upper(btrim(coalesce(e.value->>'command_type',e.value->>'type',''))) command_type
    from jsonb_array_elements(p_commands) with ordinality e(value,ordinality)
  ),
  command_ids as materialized (
    select r.command_no,r.command_type,x.ordinality::integer item_no,x.value id_text,
      x.value ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        valid_uuid
    from raw r
    cross join lateral jsonb_array_elements_text(
      case
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
          then r.command_json->'nhsp_shift_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'source_ids')='array'
          then r.command_json->'source_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'timesheet_ids')='array'
          then r.command_json->'timesheet_ids'
        when r.command_type in('GENERATE_CREDIT_NOTE','ISSUE_INVOICES','DELIVER_INVOICES')
          and jsonb_typeof(r.command_json->'invoice_ids')='array'
          then r.command_json->'invoice_ids'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and coalesce(r.command_json->>'base_invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'base_invoice_id')
        when r.command_type in(
          'GENERATE_CREDIT_NOTE','VIEW_INVOICE_DOCUMENT','DELIVER_INVOICES')
          and coalesce(r.command_json->>'invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'invoice_id')
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and coalesce(r.command_json->>'timesheet_id','')<>'' then
          jsonb_build_array(r.command_json->>'timesheet_id')
        else '[]'::jsonb
      end
    ) with ordinality x(value,ordinality)
  ),
  canonical_ids as materialized (
    select command_no,array_agg(distinct id_text::uuid order by id_text::uuid) ids
    from command_ids where valid_uuid group by command_no
  ),
  generation_groups as materialized (
    select *
    from private._invoice_generation_resolve_command_groups(
      p_commands,p_actor_user_id,v_now)
  ),
  view_facts as materialized (
    select r.command_no,r.command_type,
      case when r.command_type='VIEW_INVOICE_DOCUMENT' then 'INVOICE' else 'TIMESHEET' end entity_type,
      (array_agg(ci.id_text::uuid order by ci.item_no))[1] entity_id,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then i.document_revision else t.document_revision end document_revision,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then 'DRAFT_PREVIEW' else 'TIMESHEET' end purpose,
      coalesce(nullif(r.command_json->>'template_version',''),
        case when r.command_type='VIEW_INVOICE_DOCUMENT'
          then 'invoice-professional-v1' else 'timesheet-professional-v1' end) template_version
    from raw r
    left join command_ids ci on ci.command_no=r.command_no and ci.valid_uuid
    left join public.invoices i
      on r.command_type='VIEW_INVOICE_DOCUMENT' and i.id=ci.id_text::uuid
    left join public.timesheets t
      on r.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=ci.id_text::uuid
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    group by r.command_no,r.command_type,i.document_revision,t.document_revision,r.command_json
  ),
  issue_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      encode(digest(string_agg(i.id||':'||i.document_revision,
        '|' order by i.id),'sha256'),'hex') invoice_revision_hash,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where r.command_type='ISSUE_INVOICES'
    group by r.command_no
  ),
  delivery_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      array_agg(i.issued_document_version_id order by i.id) document_version_ids,
      encode(digest(string_agg(concat_ws(':',i.id::text,
        i.issued_document_version_id::text,v.sha256,v.size_bytes::text,v.page_count::text),
        '|' order by i.id),'sha256'),'hex') delivery_revision,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join public.invoice_document_versions v
      on v.id=i.issued_document_version_id and v.status='READY'
      and v.purpose='FINAL_ISSUE' and v.entity_type='INVOICE' and v.entity_id=i.id
    where r.command_type='DELIVER_INVOICES' and i.status in('ISSUED','PAID')
    group by r.command_no
  ),
  recipient_sets as materialized (
    select r.command_no,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_recipients,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_cc,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_bcc,
      (select count(*)::integer
        from(
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end)
        ) e
        where nullif(btrim(e.value),'') is not null
          and btrim(e.value)!~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
        invalid_count
    from raw r
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_route_requests as materialized (
    select r.command_no,i.invoice_id,jsonb_build_object(
      'request_key',r.command_no::text||':'||i.invoice_id::text,
      'invoice_id',i.invoice_id,
      'recipient_set',rs.canonical_recipients,
      'cc',rs.canonical_cc,
      'bcc',rs.canonical_bcc,
      'delivery_policy',upper(coalesce(
        nullif(r.command_json->>'delivery_policy',''),'ATTACH')),
      'template_version',coalesce(
        nullif(r.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1')) request_json
    from raw r
    join delivery_facts f on f.command_no=r.command_no
    join recipient_sets rs on rs.command_no=r.command_no
    cross join unnest(f.invoice_ids) i(invoice_id)
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_routes as materialized (
    select q.command_no,d.*
    from private._invoice_delivery_routes_batch(coalesce((
      select jsonb_agg(q.request_json order by q.command_no,q.invoice_id)
      from delivery_route_requests q),'[]'::jsonb),
      (v_now at time zone 'Europe/London')::date) d
    join delivery_route_requests q
      on q.request_json->>'request_key'=d.request_key
      and q.invoice_id=d.invoice_id
  ),
  delivery_route_groups as materialized (
    select command_no,
      encode(digest(string_agg(invoice_id::text||':'||route_policy_hash,
        '|' order by invoice_id),'sha256'),'hex') route_set_hash,
      jsonb_agg(jsonb_build_object(
        'invoice_id',invoice_id,'to',canonical_to,'cc',canonical_cc,
        'bcc',canonical_bcc,'recipient_set_hash',recipient_set_hash,
        'route_policy_hash',route_policy_hash,
        'route_source',route_source,'do_not_send',do_not_send,
        'warning_codes',warning_codes,'blocker_codes',blocker_codes,
        'evaluated_date',(v_now at time zone 'Europe/London')::date)
        order by invoice_id) frozen_routes
    from delivery_routes
    group by command_no
  ),
  issue_delivery_intents as materialized (
    select r.command_no,
      (intent.intent_json-'recipient_set'-'cc'-'bcc')
        ||jsonb_build_object(
          'recipient_set',recipients.canonical,
          'cc',cc.canonical,'bcc',bcc.canonical) canonical_intent,
      recipients.requested_count+cc.requested_count+bcc.requested_count requested_count,
      recipients.valid_count+cc.valid_count+bcc.valid_count valid_count
    from raw r
    cross join lateral(
      select case when jsonb_typeof(r.command_json->'delivery_intent')='object'
        then r.command_json->'delivery_intent' else '{}'::jsonb end intent_json
    ) intent
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
                then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) recipients
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'cc')='array'
                then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) cc
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'bcc')='array'
                then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) bcc
    where r.command_type='ISSUE_INVOICES'
  ),
  asset_specs as materialized (
    select r.command_no,r.command_json,
      upper(btrim(coalesce(r.command_json->>'source_kind',''))) source_kind,
      case when coalesce(r.command_json->>'source_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(r.command_json->>'source_id')::uuid end source_id,
      nullif(btrim(r.command_json->>'source_revision'),'') source_revision,
      nullif(btrim(r.command_json->>'original_r2_key'),'') original_r2_key,
      nullif(btrim(r.command_json->>'original_filename'),'') original_filename,
      nullif(btrim(r.command_json->>'declared_media_type'),'') declared_media_type,
      case when coalesce(r.command_json->>'rotation_degrees','') ~ '^(0|90|180|270)$'
        then(r.command_json->>'rotation_degrees')::integer end rotation_degrees,
      r.command_json?'rotation_degrees' rotation_supplied
    from raw r where r.command_type='PREPARE_ASSET'
  ),
  issue_entity_locks as materialized (
    select pg_advisory_xact_lock(
      hashtextextended('ISSUE_INVOICE|'||ci.id_text,0))
    from command_ids ci join raw r on r.command_no=ci.command_no
    where r.command_type='ISSUE_INVOICES' and ci.valid_uuid
    order by ci.id_text
  ),
  command_validation as materialized (
    select r.command_no,r.command_type,
      case
        when jsonb_typeof(r.command_json)<>'object'
          then 'COMMAND_MUST_BE_OBJECT'
        when r.command_type not in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS','GENERATE_EXPENSES',
          'GENERATE_NHSP','GENERATE_CREDIT_NOTE','GENERATE_AUTO',
          'VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT','PREPARE_ASSET',
          'ISSUE_INVOICES','DELIVER_INVOICES','RECONCILE')
          then 'UNSUPPORTED_COMMAND_TYPE'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_AUTO')
          and not(
            jsonb_typeof(r.command_json->'source_ids')='array'
            or jsonb_typeof(r.command_json->'timesheet_ids')='array')
          then 'GENERATION_SOURCE_ARRAY_REQUIRED'
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')<>'array'
          then 'NHSP_SHIFT_ARRAY_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'consolidation_mode'
          and upper(coalesce(r.command_json->>'consolidation_mode','')) not in(
            'NONE','BY_WEEK','ANY_WEEK')
          then 'INVALID_CONSOLIDATION_MODE'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'allow_early'
          and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
          then 'ALLOW_EARLY_MUST_BE_BOOLEAN'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(
            r.command_json->>'target_invoice_week','')),'') is not null
          and not pg_input_is_valid(
            r.command_json->>'target_invoice_week','date')
          then 'INVALID_TARGET_INVOICE_WEEK'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'base_invoice_id','')),'') is null
          then 'BASE_INVOICE_ID_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and(select count(*) from command_ids x
            where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_BASE_INVOICE_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'credit_reason','')),'') is null
          then 'CREDIT_REASON_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'command_token','')),'') is null
          then 'CREDIT_COMMAND_TOKEN_REQUIRED'
        when exists(select 1 from command_ids x
          where x.command_no=r.command_no and not x.valid_uuid)
          then 'MALFORMED_UUID'
        when r.command_type like 'GENERATE_%' and not exists(
          select 1 from generation_groups g where g.command_no=r.command_no)
          then 'GENERATION_SOURCES_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and (select count(*) from generation_groups g
            where g.command_no=r.command_no)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and(select count(*) from command_ids x where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_DOCUMENT_ENTITY_REQUIRED'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and nullif(btrim(coalesce(r.command_json->>'priority_reason','')),'') is null
          then 'DOCUMENT_PRIORITY_REASON_REQUIRED'
        when r.command_type='VIEW_INVOICE_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'DRAFT_PREVIEW'))<>'DRAFT_PREVIEW'
          then 'INVALID_INVOICE_DOCUMENT_PURPOSE'
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'TIMESHEET'))<>'TIMESHEET'
          then 'INVALID_TIMESHEET_DOCUMENT_PURPOSE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and not exists(select 1 from view_facts v
            where v.command_no=r.command_no and v.document_revision is not null)
          then 'DOCUMENT_ENTITY_NOT_FOUND'
        when r.command_type='PREPARE_ASSET' and not exists(
          select 1 from asset_specs a
          where a.command_no=r.command_no
            and a.source_kind in(
              'MANUAL_TIMESHEET','TIMESHEET_EVIDENCE','OTHER_EVIDENCE',
              'HR_REPORT','NHSP_REPORT','HIGHER_RATE_SUPPORT')
            and a.source_id is not null and a.source_revision is not null
            and a.original_r2_key is not null and a.original_filename is not null
            and a.declared_media_type is not null
            and(not a.rotation_supplied or a.rotation_degrees is not null))
          then 'INVALID_ASSET_SOURCE_METADATA'
        when r.command_type='PREPARE_ASSET'
          and r.command_json?'rotation_degrees'
          and coalesce(r.command_json->>'rotation_degrees','')!~'^(0|90|180|270)$'
          then 'INVALID_ASSET_ROTATION'
        when r.command_type='ISSUE_INVOICES'
          and(jsonb_typeof(r.command_json->'invoice_ids')<>'array'
            or coalesce(cardinality((select ids from canonical_ids x
              where x.command_no=r.command_no)),0)=0
            or coalesce((select resolved_count from issue_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUE_INVOICES_NOT_RESOLVED'
        when r.command_type='ISSUE_INVOICES'
          and (r.command_json?'allow_early'
            and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
            or r.command_json?'deliver'
            and jsonb_typeof(r.command_json->'deliver')<>'boolean')
          then 'ISSUE_FLAGS_MUST_BE_BOOLEAN'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(nullif(r.command_json->>'command_token',''),'')=''
          then 'ISSUE_COMMAND_TOKEN_REQUIRED'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='ISSUE_INVOICES'
          and r.command_json?'delivery_intent'
          and jsonb_typeof(r.command_json->'delivery_intent')<>'object'
          then 'ISSUE_DELIVERY_INTENT_MUST_BE_OBJECT'
        when r.command_type='ISSUE_INVOICES'
          and jsonb_typeof(r.command_json->'delivery_intent')='object'
          and (
            r.command_json->'delivery_intent'?'recipient_set'
              and jsonb_typeof(r.command_json->'delivery_intent'->'recipient_set')<>'array'
            or r.command_json->'delivery_intent'?'cc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'cc')<>'array'
            or r.command_json->'delivery_intent'?'bcc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'bcc')<>'array')
          then 'ISSUE_DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='ISSUE_INVOICES'
          and exists(
            select 1 from issue_delivery_intents intent
            where intent.command_no=r.command_no
              and intent.requested_count<>intent.valid_count)
          then 'ISSUE_DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='ISSUE_INVOICES' and exists(
          select 1 from command_ids x
          join public.invoice_operation_chunks c
            on c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
            and c.entity_id=x.id_text::uuid
            and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
          where x.command_no=r.command_no and x.valid_uuid)
          and not exists(
            select 1
            from public.invoice_operations exact
            join issue_facts f on f.command_no=r.command_no
            join issue_delivery_intents intent on intent.command_no=r.command_no
            where exact.idempotency_key=encode(digest(concat_ws('|',
              'ISSUE_INVOICES',f.invoice_revision_hash,
              coalesce(r.command_json->>'allow_early','false'),
              coalesce(r.command_json->>'deliver','false'),
              coalesce(r.command_json->>'command_token',''),
              encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
              'sha256'),'hex')
              and exact.status in(
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
          then 'ACTIVE_ISSUE_CONFLICT'
        when r.command_type='DELIVER_INVOICES'
          and not(
            jsonb_typeof(r.command_json->'invoice_ids')='array'
            or nullif(btrim(coalesce(r.command_json->>'invoice_id','')),'') is not null)
          then 'DELIVERY_INVOICE_IDS_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and nullif(btrim(coalesce(
            r.command_json->>'delivery_request_token','')),'') is null
          then 'DELIVERY_REQUEST_TOKEN_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'recipient_set'
          and jsonb_typeof(r.command_json->'recipient_set')<>'array'
          then 'DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and ((r.command_json?'cc' and jsonb_typeof(r.command_json->'cc')<>'array')
            or(r.command_json?'bcc' and jsonb_typeof(r.command_json->'bcc')<>'array'))
          then 'DELIVERY_CC_BCC_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and exists(select 1 from recipient_sets rs
            where rs.command_no=r.command_no and rs.invalid_count>0)
          then 'DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_part_number'
          and coalesce(r.command_json->>'delivery_part_number','') !~ '^[1-9][0-9]*$'
          then 'INVALID_DELIVERY_PART_NUMBER'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_policy'
          and upper(coalesce(r.command_json->>'delivery_policy',''))
            not in('ATTACH','SPLIT','SECURE_LINK')
          then 'INVALID_DELIVERY_POLICY'
        when r.command_type='DELIVER_INVOICES'
          and(coalesce((select resolved_count from delivery_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUED_DOCUMENT_NOT_READY'
        when r.command_type='RECONCILE'
          and not(r.command_json?'operation_ids'
            or r.command_json?'older_than_seconds') then 'RECONCILE_SCOPE_REQUIRED'
        when r.command_type='RECONCILE'
          and r.command_json?'operation_ids'
          and jsonb_typeof(r.command_json->'operation_ids')<>'array'
          then 'RECONCILE_OPERATION_IDS_MUST_BE_ARRAY'
        when r.command_type='RECONCILE'
          and jsonb_typeof(r.command_json->'operation_ids')='array'
          and jsonb_array_length(r.command_json->'operation_ids')>500
          then 'RECONCILE_OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='RECONCILE'
          and r.command_json?'older_than_seconds'
          and coalesce(r.command_json->>'older_than_seconds','') !~ '^[0-9]{1,6}$'
          then 'RECONCILE_AGE_MUST_BE_INTEGER_SECONDS'
      end error_code,
      case when r.command_type like 'GENERATE_%' then (
        select jsonb_agg(jsonb_build_object(
          'group_key',g.group_key,'code',g.blocker_code,'detail',g.blocker_detail)
          order by g.group_key)
        from generation_groups g
        where g.command_no=r.command_no and g.blocker_code is not null)
      end error_detail
    from raw r cross join(select count(*) from issue_entity_locks) lock_barrier
  ),
  valid_commands as materialized (
    select r.* from raw r join command_validation v using(command_no,command_type)
    where v.error_code is null
  ),
  inserted_assets as materialized (
    insert into public.invoice_document_assets(
      source_kind,source_id,source_revision,original_r2_key,original_filename,
      declared_media_type,orientation_degrees,status,normalised_manifest_json,
      created_at_utc,updated_at_utc)
    select a.source_kind,a.source_id,a.source_revision,a.original_r2_key,
      a.original_filename,a.declared_media_type,a.rotation_degrees,
      'DISCOVERED','[]'::jsonb,v_now,v_now
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    on conflict(source_kind,source_id,source_revision,original_r2_key) do nothing
    returning *
  ),
  assets as materialized (
    select a.command_no,inserted.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join inserted_assets inserted
      on inserted.source_kind=a.source_kind
      and inserted.source_id=a.source_id
      and inserted.source_revision=a.source_revision
      and inserted.original_r2_key=a.original_r2_key
    union all
    select a.command_no,registered.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join public.invoice_document_assets registered
      on registered.source_kind=a.source_kind
      and registered.source_id=a.source_id
      and registered.source_revision=a.source_revision
      and registered.original_r2_key=a.original_r2_key
    where not exists(
      select 1 from inserted_assets inserted
      where inserted.source_kind=a.source_kind
        and inserted.source_id=a.source_id
        and inserted.source_revision=a.source_revision
        and inserted.original_r2_key=a.original_r2_key)
  ),
  asset_workflow_state as materialized (
    select a.*,
      exists(
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.document_asset_id=a.id
          and c.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
          and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      ) has_active_work
    from assets a
  ),
  operation_specs as materialized (
    select v.command_no,v.command_type,v.command_json,
      'GENERATE_INVOICES'::text operation_type,
      case when count(*)=1 then 'CLIENT' else 'INVOICE_BATCH' end entity_type,
      case when count(*)=1 then(array_agg(g.client_id order by g.client_id))[1]
        else null::uuid end entity_id,
      encode(digest(string_agg(g.source_revision_hash,'|' order by g.group_key),
        'sha256'),'hex') source_revision,
      null::text template_version,
      case when v.command_type='GENERATE_AUTO' then 200 else 600 end priority,
      count(*)::integer unit_count,
      jsonb_build_object('generation_groups',
        jsonb_agg(g.idempotency_components order by g.group_key)) canonical_input,
      encode(digest('GENERATE_INVOICES|'||
        string_agg(g.idempotency_components::text,'|' order by g.group_key),
        'sha256'),'hex') idempotency_key
    from valid_commands v join generation_groups g on g.command_no=v.command_no
    where v.command_type like 'GENERATE_%'
    group by v.command_no,v.command_type,v.command_json
    union all
    select v.command_no,v.command_type,v.command_json,'BUILD_DOCUMENT',
      f.entity_type,f.entity_id,f.document_revision::text,f.template_version,1000,1,
      jsonb_build_object('entity_type',f.entity_type,'entity_id',f.entity_id,
        'purpose',f.purpose,'document_revision',f.document_revision,
        'template_version',f.template_version),
      encode(digest(concat_ws('|','BUILD_DOCUMENT',f.entity_type,f.entity_id::text,
        f.purpose,f.document_revision::text,f.template_version),'sha256'),'hex')
    from valid_commands v join view_facts f on f.command_no=v.command_no
    where v.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and not exists(
        select 1 from public.invoice_document_versions ready
        where ready.entity_type=f.entity_type and ready.entity_id=f.entity_id
          and ready.purpose=f.purpose
          and ready.source_revision=f.document_revision::text
          and ready.template_version=f.template_version and ready.status='READY')
    union all
    select v.command_no,v.command_type,v.command_json,'PREPARE_ASSET',
      'DOCUMENT_ASSET',a.id,a.source_revision,null,550,1,
      jsonb_build_object('document_asset_id',a.id,'source_kind',a.source_kind,
        'source_id',a.source_id,'source_revision',a.source_revision,
        'original_r2_key',a.original_r2_key),
      encode(digest(concat_ws('|','PREPARE_ASSET',a.source_kind,a.source_id::text,
        a.source_revision,a.original_r2_key),'sha256'),'hex')
    from valid_commands v join asset_workflow_state a
      on a.command_no=v.command_no
    where v.command_type='PREPARE_ASSET'
      and a.status in('DISCOVERED','INSPECTING','NORMALISING')
      and not(a.status in('INSPECTING','NORMALISING')
        and not a.has_active_work)
    union all
    select v.command_no,v.command_type,v.command_json,'ISSUE_INVOICES',
      'INVOICE_BATCH',null,f.invoice_revision_hash,null,850,
      cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'invoice_revision_hash',f.invoice_revision_hash,
        'allow_early',coalesce(v.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(v.command_json->'deliver','false'::jsonb),
        'command_token',v.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(v.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      encode(digest(concat_ws('|','ISSUE_INVOICES',f.invoice_revision_hash,
        coalesce(v.command_json->>'allow_early','false'),
        coalesce(v.command_json->>'deliver','false'),
        coalesce(v.command_json->>'command_token',''),
        encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
        'sha256'),'hex')
    from valid_commands v join issue_facts f on f.command_no=v.command_no
    join issue_delivery_intents intent on intent.command_no=v.command_no
    where v.command_type='ISSUE_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'DELIVER_INVOICES',
      'INVOICE_BATCH',null,f.delivery_revision,
      coalesce(nullif(v.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1'),400,cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'issued_document_version_ids',to_jsonb(f.document_version_ids),
        'delivery_revision',f.delivery_revision,
        'recipient_set',rs.canonical_recipients,
        'recipient_set_hash',drg.route_set_hash,
        'frozen_delivery_routes',drg.frozen_routes,
        'template_version',coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_part_number',coalesce(v.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',v.command_json->>'delivery_request_token'),
      encode(digest(concat_ws('|','DELIVER_INVOICES',f.delivery_revision,
        drg.route_set_hash,
        coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(v.command_json->>'delivery_part_number','1'),
        v.command_json->>'delivery_request_token'),'sha256'),'hex')
    from valid_commands v join delivery_facts f on f.command_no=v.command_no
    join recipient_sets rs on rs.command_no=v.command_no
    join delivery_route_groups drg on drg.command_no=v.command_no
    where v.command_type='DELIVER_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'RECONCILE_INVOICE_WORK',
      'SYSTEM',null,
      encode(digest(coalesce(v.command_json->'operation_ids','[]')::text||'|'||
        coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex'),
      null,50,1,
      jsonb_build_object(
        'operation_ids',coalesce(v.command_json->'operation_ids','[]'::jsonb),
        'older_than_seconds',least(604800,greatest(30,case
          when coalesce(v.command_json->>'older_than_seconds','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'older_than_seconds')::integer else 300 end)),
        'max_rows',least(500,greatest(1,case
          when coalesce(v.command_json->>'max_rows','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'max_rows')::integer else 100 end))),
      encode(digest('RECONCILE|'||coalesce(v.command_json->'operation_ids','[]')::text||
        '|'||coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex')
    from valid_commands v where v.command_type='RECONCILE'
  ),
  locks as materialized (
    select pg_advisory_xact_lock(hashtextextended(x.lock_key,0))
    from(
      select idempotency_key lock_key from operation_specs
      union
      select 'ISSUE_INVOICE|'||unnest(f.invoice_ids)::text
      from issue_facts f join valid_commands v on v.command_no=f.command_no
      where v.command_type='ISSUE_INVOICES'
    ) x order by x.lock_key
  ),
  existing_before as materialized (
    select s.command_no,o.*
    from operation_specs s
    join lateral (
      select candidate.*
      from public.invoice_operations candidate
      where candidate.idempotency_key=s.idempotency_key
        and candidate.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(candidate.status='COMPLETE') desc,candidate.created_at_utc desc
      limit 1
    ) o on true
  ),
  inserted_operations as materialized (
    insert into public.invoice_operations(
      operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
      status,phase,priority,source_revision,template_version,input_json,
      config_json,progress_json,total_units,chunk_count,control_version,
      change_seq,created_at_utc,updated_at_utc)
    select s.operation_type,s.entity_type,s.entity_id,p_actor_user_id,
      s.idempotency_key,'QUEUED','SUBMITTED',s.priority,s.source_revision,
      s.template_version,s.canonical_input,
      jsonb_build_object(
        'command_type',s.command_type,
        'processor_policy',private._invoice_processor_limits()),
      jsonb_build_object('status_message','Accepted','total_units',s.unit_count,
        'completed_units',0,'failed_units',0),
      s.unit_count,s.unit_count,1,nextval('public.invoice_operation_change_seq'),
      v_now,v_now
    from operation_specs s cross join(select count(*) from locks) lock_barrier
    where not exists(select 1 from existing_before e where e.command_no=s.command_no)
    on conflict do nothing
    returning *
  ),
  chosen as materialized (
    select s.*,coalesce(i.id,e.id) operation_id,
      coalesce(i.status,e.status) operation_status,
      coalesce(i.phase,e.phase) operation_phase,
      coalesce(i.control_version,e.control_version) control_version,
      coalesce(i.change_seq,e.change_seq) change_seq,
      coalesce(i.priority,e.priority,s.priority) current_priority,
      i.id is not null created,e.id is not null reused
    from operation_specs s
    left join inserted_operations i on i.idempotency_key=s.idempotency_key
    left join existing_before e on e.command_no=s.command_no
  ),
  raised as materialized (
    update public.invoice_operations o
    set priority=greatest(o.priority,c.priority),updated_at_utc=v_now,
        change_seq=case when o.priority<c.priority
          then nextval('public.invoice_operation_change_seq') else o.change_seq end
    from chosen c
    where c.reused and o.id=c.operation_id
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning o.id
  ),
  existing_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
      and v.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
  ),
  document_versions as materialized (
    insert into public.invoice_document_versions(
      entity_type,entity_id,purpose,operation_id,source_revision,template_version,
      status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select f.entity_type,f.entity_id,f.purpose,c.operation_id,
      f.document_revision::text,f.template_version,'PLANNING','{}'::jsonb,
      encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
      encode(digest('[]','sha256'),'hex'),v_now
    from chosen c join view_facts f on f.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE'
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET') and status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning *
  ),
  all_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select e.* from existing_document_versions e
  ),
  chunk_specs as materialized (
    select c.operation_id,'GENERATION_GROUP'::text chunk_type,
      'VALIDATE_SOURCES'::text phase,
      encode(digest(concat_ws('|','GENERATION_GROUP',g.group_key,
        g.source_revision_hash,c.command_type,
        coalesce(g.idempotency_components->>'consolidation_mode',''),
        coalesce(g.idempotency_components->>'invoice_stream',''),'1'),
        'sha256'),'hex') work_key,
      row_number() over(partition by c.operation_id order by g.group_key)::integer-1 sequence_no,
      'CLIENT'::text entity_type,g.client_id entity_id,null::uuid document_version_id,
      null::uuid document_asset_id,
      g.idempotency_components||jsonb_build_object(
        'canonical_source_ids',to_jsonb(g.canonical_source_ids),
        'canonical_source_members',g.canonical_source_members,
        'source_types',to_jsonb(g.source_types),
        'source_revision',g.source_revision_hash,
        'resolver_blocker_code',g.blocker_code,
        'resolver_blocker_detail',g.blocker_detail) payload_json,
      c.priority,c.control_version
    from chosen c join generation_groups g on g.command_no=c.command_no
    where c.command_type like 'GENERATE_%' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',v.id::text,
        f.document_revision::text,f.template_version,'1'),'sha256'),'hex'),
      0,f.entity_type,f.entity_id,
      v.id,null,jsonb_build_object('purpose',f.purpose,
        'source_revision',f.document_revision::text,
        'template_version',f.template_version),c.priority,c.control_version
    from chosen c join view_facts f on f.command_no=c.command_no
    join all_document_versions v on v.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE' and v.status<>'READY'
    union all
    select c.operation_id,'ASSET_INSPECT','INSPECT',
      encode(digest(concat_ws('|','ASSET_INSPECT',a.id::text,a.source_revision,
        private._invoice_processor_limits()->>'policy_version'),'sha256'),'hex'),
      0,'DOCUMENT_ASSET',a.id,
      null,a.id,jsonb_build_object('source_revision',a.source_revision,
        'source_kind',a.source_kind,'source_id',a.source_id,
        'rotation_degrees',a.orientation_degrees),c.priority,c.control_version
    from chosen c join assets a on a.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and c.operation_status<>'COMPLETE'
      and a.status not in('READY','INSPECTING','NORMALISING')
    union all
    select c.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',i.id::text,
        i.document_revision::text,c.command_json->>'command_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,null,null,
      jsonb_build_object(
        'request_key',c.command_no::text||':'||i.id::text,
        'invoice_id',i.id,'source_revision',i.document_revision,
        'evaluation_date',(v_now at time zone 'Europe/London')::date,
        'frozen_issue_at_utc',v_now,
        'allow_early',coalesce(c.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.command_json->'deliver','false'::jsonb),
        'command_token',c.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(c.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      c.priority,c.control_version
    from chosen c join issue_facts f on f.command_no=c.command_no
    join issue_delivery_intents intent on intent.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where c.command_type='ISSUE_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DELIVERY_PREPARE','PREPARE',
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        i.issued_document_version_id::text,dr.route_policy_hash,
        coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(c.command_json->>'delivery_part_number','1'),
        c.command_json->>'delivery_request_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,i.issued_document_version_id,null,
      jsonb_build_object(
        'invoice_id',i.id,'issued_document_version_id',i.issued_document_version_id,
        'recipient_set',dr.canonical_to,'cc',dr.canonical_cc,
        'bcc',dr.canonical_bcc,
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'frozen_delivery_route',jsonb_build_object(
          'request_key',dr.request_key,
          'to',dr.canonical_to,'cc',dr.canonical_cc,'bcc',dr.canonical_bcc,
          'recipient_set_hash',dr.recipient_set_hash,
          'route_policy_hash',dr.route_policy_hash,
          'route_source',dr.route_source,'do_not_send',dr.do_not_send,
          'warning_codes',dr.warning_codes,'blocker_codes',dr.blocker_codes,
          'evaluated_date',(v_now at time zone 'Europe/London')::date),
        'template_version',coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(
          nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
        'delivery_part_number',coalesce(c.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',encode(digest(concat_ws('|',
          'DELIVERY_REQUEST',c.command_json->>'delivery_request_token',
          i.id::text,i.issued_document_version_id::text),'sha256'),'hex'),
        'user_command_token',c.command_json->>'delivery_request_token'),
      c.priority,c.control_version
    from chosen c join delivery_facts f on f.command_no=c.command_no
    join recipient_sets rs on rs.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join delivery_routes dr on dr.command_no=c.command_no
      and dr.request_key=c.command_no::text||':'||i.id::text
      and dr.invoice_id=i.id
    where c.command_type='DELIVER_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'RECONCILE','RECONCILE',
      encode(digest(concat_ws('|','RECONCILE',c.canonical_input::text,'1'),
        'sha256'),'hex'),
      0,'SYSTEM',null,null,null,
      c.canonical_input,c.priority,c.control_version
    from chosen c where c.command_type='RECONCILE' and c.operation_status<>'COMPLETE'
  ),
  inserted_chunks as materialized (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,document_asset_id,status,priority,run_after_utc,
      payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select c.operation_id,c.chunk_type,c.phase,c.work_key,c.sequence_no,c.entity_type,c.entity_id,
      c.document_version_id,c.document_asset_id,'QUEUED',c.priority,v_now,
      c.payload_json,c.control_version,v_now,v_now
    from chunk_specs c
    on conflict do nothing
    returning *
  ),
  asset_operation_links as (
    update public.invoice_document_assets a
    set operation_id=c.operation_id,
        status=case when a.status='DISCOVERED' then 'INSPECTING' else a.status end,
        updated_at_utc=v_now
    from chosen c join assets x on x.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and a.id=x.id and a.status<>'READY'
    returning a.id
  ),
  entity_pointers as (
    update public.invoices i
    set active_document_operation_id=case
          when c.command_type='VIEW_INVOICE_DOCUMENT' then c.operation_id
          else i.active_document_operation_id end,
        document_state=case when c.command_type='VIEW_INVOICE_DOCUMENT'
          then 'QUEUED' else i.document_state end,
        active_issue_operation_id=case when c.command_type='ISSUE_INVOICES'
          then c.operation_id else i.active_issue_operation_id end,
        issue_state=case when c.command_type='ISSUE_INVOICES'
          then 'VALIDATING' else i.issue_state end,
        updated_at=v_now
    from chosen c
    where(c.command_type='VIEW_INVOICE_DOCUMENT' and i.id=c.entity_id)
      or(c.command_type='ISSUE_INVOICES' and exists(
        select 1
        from issue_facts f
        where f.command_no=c.command_no
          and i.id=any(f.invoice_ids)))
    returning i.id
  ),
  timesheet_pointers as (
    update public.timesheets t
    set active_document_operation_id=c.operation_id,document_state='QUEUED',
        updated_at=v_now
    from chosen c
    where c.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=c.entity_id
    returning t.timesheet_id
  ),
  refreshed_counts as (
    update public.invoice_operations o
    set total_units=greatest(o.total_units,q.n),
        chunk_count=greatest(o.chunk_count,q.n),
        progress_json=coalesce(o.progress_json,'{}'::jsonb)||jsonb_build_object(
          'status_message','Queued',
          'total_units',greatest(o.total_units,q.n)),
        updated_at_utc=v_now,
        change_seq=nextval('public.invoice_operation_change_seq')
    from(
      select intended.operation_id,count(*)::integer n
      from chunk_specs intended
      cross join(
        select count(*) from inserted_chunks
      ) ensure_chunk_insert
      group by intended.operation_id
    ) q
    where o.id=q.operation_id and o.status<>'COMPLETE'
    returning o.id,o.chunk_count n
  ),
  ready_results as (
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_version_id',v.id,'r2_key',v.r2_key,
      'created',false,'reused_active',false,'reused_ready',true,
      'priority_raised',false,'blocked',false,'terminal_error',null) result
    from raw r join view_facts f on f.command_no=r.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version and v.status='READY'
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',true,'priority_raised',false,'blocked',false,
      'terminal_error',null) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET' and a.status='READY'
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status',a.status,
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'terminal_error',coalesce(a.error_json,
        jsonb_build_object('code','ASSET_'||a.status))) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status','BLOCKED',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'reconcile_available',true,
      'terminal_error',jsonb_build_object(
        'code','ASSET_WORKFLOW_INCONSISTENT',
        'asset_status',a.status,'document_asset_id',a.id)) result
    from raw r join asset_workflow_state a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('INSPECTING','NORMALISING')
      and not a.has_active_work
  ),
  operation_results as (
    select c.command_no,jsonb_build_object(
      'command_no',c.command_no,'command_type',c.command_type,'accepted',true,
      'operation_id',c.operation_id,'operation_type',c.operation_type,
      'status',coalesce(o.status,c.operation_status),
      'phase',coalesce(o.phase,c.operation_phase),
      'source_revision',c.source_revision,
      'change_seq',coalesce(o.change_seq,c.change_seq),
      'created',c.created,
      'reused_active',c.reused and coalesce(o.status,c.operation_status)<>'COMPLETE',
      'reused_ready',c.reused and coalesce(o.status,c.operation_status)='COMPLETE',
      'priority_raised',c.reused and c.priority>c.current_priority,
      'blocked',coalesce(o.status,c.operation_status)='BLOCKED',
      'terminal_error',null,
      'chunk_count',greatest(c.unit_count,(select count(*)
        from chunk_specs intended
        where intended.operation_id=c.operation_id)))
      result
    from chosen c
    left join public.invoice_operations o on o.id=c.operation_id
    left join refreshed_counts rc on rc.id=c.operation_id
  ),
  error_results as (
    select v.command_no,jsonb_build_object(
      'command_no',v.command_no,'command_type',v.command_type,
      'accepted',false,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,
      'blocked',false,
      'terminal_error',jsonb_build_object('code',v.error_code,
        'detail',v.error_detail),
      'error',jsonb_build_object('code',v.error_code,'detail',v.error_detail)) result
    from command_validation v where v.error_code is not null
  ),
  combined as (
    select * from ready_results
    union all
    select o.* from operation_results o
    where not exists(select 1 from ready_results r where r.command_no=o.command_no)
    union all
    select * from error_results
  )
  select coalesce(jsonb_agg(result order by command_no),'[]'::jsonb)
  into v_result from combined;

  return v_result;
end;
$function$;

-- private._invoice_operation_start_core_v8(jsonb,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_operation_start_core_v8(p_commands jsonb, p_actor_user_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_jwt_role text:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    auth.jwt()->>'role','');
  v_auth_user uuid:=auth.uid();
  v_result jsonb;
begin
  if jsonb_typeof(p_commands)<>'array'
     or jsonb_array_length(p_commands)<1
     or jsonb_array_length(p_commands)>1000 then
    raise exception using errcode='22023',
      message='p_commands must be a JSON array containing 1..1000 commands';
  end if;

  if p_actor_user_id is null
     or not exists(select 1 from public.tms_users u
       where u.id=p_actor_user_id and u.is_active and lower(u.role)='admin')
     or(v_jwt_role<>'service_role' and v_auth_user is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='Active administrator actor and matching authenticated/service caller required';
  end if;

  with raw as materialized (
    select e.ordinality::integer command_no,e.value command_json,
      upper(btrim(coalesce(e.value->>'command_type',e.value->>'type',''))) command_type
    from jsonb_array_elements(p_commands) with ordinality e(value,ordinality)
  ),
  command_ids as materialized (
    select r.command_no,r.command_type,x.ordinality::integer item_no,x.value id_text,
      x.value ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        valid_uuid
    from raw r
    cross join lateral jsonb_array_elements_text(
      case
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
          then r.command_json->'nhsp_shift_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'source_ids')='array'
          then r.command_json->'source_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'timesheet_ids')='array'
          then r.command_json->'timesheet_ids'
        when r.command_type in('GENERATE_CREDIT_NOTE','ISSUE_INVOICES','DELIVER_INVOICES')
          and jsonb_typeof(r.command_json->'invoice_ids')='array'
          then r.command_json->'invoice_ids'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and coalesce(r.command_json->>'base_invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'base_invoice_id')
        when r.command_type in(
          'GENERATE_CREDIT_NOTE','VIEW_INVOICE_DOCUMENT','DELIVER_INVOICES')
          and coalesce(r.command_json->>'invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'invoice_id')
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and coalesce(r.command_json->>'timesheet_id','')<>'' then
          jsonb_build_array(r.command_json->>'timesheet_id')
        else '[]'::jsonb
      end
    ) with ordinality x(value,ordinality)
  ),
  canonical_ids as materialized (
    select command_no,array_agg(distinct id_text::uuid order by id_text::uuid) ids
    from command_ids where valid_uuid group by command_no
  ),
  generation_groups as materialized (
    select *
    from private._invoice_generation_resolve_command_groups(
      p_commands,p_actor_user_id,v_now)
  ),
  view_facts as materialized (
    select r.command_no,r.command_type,
      case when r.command_type='VIEW_INVOICE_DOCUMENT' then 'INVOICE' else 'TIMESHEET' end entity_type,
      (array_agg(ci.id_text::uuid order by ci.item_no))[1] entity_id,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then i.document_revision else t.document_revision end document_revision,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then 'DRAFT_PREVIEW' else 'TIMESHEET' end purpose,
      coalesce(nullif(r.command_json->>'template_version',''),
        case when r.command_type='VIEW_INVOICE_DOCUMENT'
          then 'invoice-professional-v2' else 'timesheet-professional-v1' end) template_version
    from raw r
    left join command_ids ci on ci.command_no=r.command_no and ci.valid_uuid
    left join public.invoices i
      on r.command_type='VIEW_INVOICE_DOCUMENT' and i.id=ci.id_text::uuid
    left join public.timesheets t
      on r.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=ci.id_text::uuid
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    group by r.command_no,r.command_type,i.document_revision,t.document_revision,r.command_json
  ),
  issue_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      encode(digest(string_agg(i.id||':'||i.document_revision,
        '|' order by i.id),'sha256'),'hex') invoice_revision_hash,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where r.command_type='ISSUE_INVOICES'
    group by r.command_no
  ),
  delivery_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      array_agg(i.issued_document_version_id order by i.id) document_version_ids,
      encode(digest(string_agg(concat_ws(':',i.id::text,
        i.issued_document_version_id::text,v.sha256,v.size_bytes::text,v.page_count::text),
        '|' order by i.id),'sha256'),'hex') delivery_revision,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join public.invoice_document_versions v
      on v.id=i.issued_document_version_id and v.status='READY'
      and v.purpose='FINAL_ISSUE' and v.entity_type='INVOICE' and v.entity_id=i.id
    where r.command_type='DELIVER_INVOICES' and i.status in('ISSUED','PAID')
    group by r.command_no
  ),
  recipient_sets as materialized (
    select r.command_no,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_recipients,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_cc,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_bcc,
      (select count(*)::integer
        from(
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end)
        ) e
        where nullif(btrim(e.value),'') is not null
          and btrim(e.value)!~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
        invalid_count
    from raw r
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_route_requests as materialized (
    select r.command_no,i.invoice_id,jsonb_build_object(
      'request_key',r.command_no::text||':'||i.invoice_id::text,
      'invoice_id',i.invoice_id,
      'recipient_set',rs.canonical_recipients,
      'cc',rs.canonical_cc,
      'bcc',rs.canonical_bcc,
      'delivery_policy',upper(coalesce(
        nullif(r.command_json->>'delivery_policy',''),'ATTACH')),
      'template_version',coalesce(
        nullif(r.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1')) request_json
    from raw r
    join delivery_facts f on f.command_no=r.command_no
    join recipient_sets rs on rs.command_no=r.command_no
    cross join unnest(f.invoice_ids) i(invoice_id)
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_routes as materialized (
    select q.command_no,d.*
    from private._invoice_delivery_routes_batch(coalesce((
      select jsonb_agg(q.request_json order by q.command_no,q.invoice_id)
      from delivery_route_requests q),'[]'::jsonb),
      (v_now at time zone 'Europe/London')::date) d
    join delivery_route_requests q
      on q.request_json->>'request_key'=d.request_key
      and q.invoice_id=d.invoice_id
  ),
  delivery_route_groups as materialized (
    select command_no,
      encode(digest(string_agg(invoice_id::text||':'||route_policy_hash,
        '|' order by invoice_id),'sha256'),'hex') route_set_hash,
      jsonb_agg(jsonb_build_object(
        'invoice_id',invoice_id,'to',canonical_to,'cc',canonical_cc,
        'bcc',canonical_bcc,'recipient_set_hash',recipient_set_hash,
        'route_policy_hash',route_policy_hash,
        'route_source',route_source,'do_not_send',do_not_send,
        'warning_codes',warning_codes,'blocker_codes',blocker_codes,
        'evaluated_date',(v_now at time zone 'Europe/London')::date)
        order by invoice_id) frozen_routes
    from delivery_routes
    group by command_no
  ),
  issue_delivery_intents as materialized (
    select r.command_no,
      (intent.intent_json-'recipient_set'-'cc'-'bcc')
        ||jsonb_build_object(
          'recipient_set',recipients.canonical,
          'cc',cc.canonical,'bcc',bcc.canonical) canonical_intent,
      recipients.requested_count+cc.requested_count+bcc.requested_count requested_count,
      recipients.valid_count+cc.valid_count+bcc.valid_count valid_count
    from raw r
    cross join lateral(
      select case when jsonb_typeof(r.command_json->'delivery_intent')='object'
        then r.command_json->'delivery_intent' else '{}'::jsonb end intent_json
    ) intent
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
                then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) recipients
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'cc')='array'
                then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) cc
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'bcc')='array'
                then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) bcc
    where r.command_type='ISSUE_INVOICES'
  ),
  asset_specs as materialized (
    select r.command_no,r.command_json,
      upper(btrim(coalesce(r.command_json->>'source_kind',''))) source_kind,
      case when coalesce(r.command_json->>'source_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(r.command_json->>'source_id')::uuid end source_id,
      nullif(btrim(r.command_json->>'source_revision'),'') source_revision,
      nullif(btrim(r.command_json->>'original_r2_key'),'') original_r2_key,
      nullif(btrim(r.command_json->>'original_filename'),'') original_filename,
      nullif(btrim(r.command_json->>'declared_media_type'),'') declared_media_type,
      case when coalesce(r.command_json->>'rotation_degrees','') ~ '^(0|90|180|270)$'
        then(r.command_json->>'rotation_degrees')::integer end rotation_degrees,
      r.command_json?'rotation_degrees' rotation_supplied
    from raw r where r.command_type='PREPARE_ASSET'
  ),
  issue_entity_locks as materialized (
    select pg_advisory_xact_lock(
      hashtextextended('ISSUE_INVOICE|'||ci.id_text,0))
    from command_ids ci join raw r on r.command_no=ci.command_no
    where r.command_type='ISSUE_INVOICES' and ci.valid_uuid
    order by ci.id_text
  ),
  command_validation as materialized (
    select r.command_no,r.command_type,
      case
        when jsonb_typeof(r.command_json)<>'object'
          then 'COMMAND_MUST_BE_OBJECT'
        when r.command_type not in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS','GENERATE_EXPENSES',
          'GENERATE_NHSP','GENERATE_CREDIT_NOTE','GENERATE_AUTO',
          'VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT','PREPARE_ASSET',
          'ISSUE_INVOICES','DELIVER_INVOICES','RECONCILE')
          then 'UNSUPPORTED_COMMAND_TYPE'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_AUTO')
          and not(
            jsonb_typeof(r.command_json->'source_ids')='array'
            or jsonb_typeof(r.command_json->'timesheet_ids')='array')
          then 'GENERATION_SOURCE_ARRAY_REQUIRED'
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')<>'array'
          then 'NHSP_SHIFT_ARRAY_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'consolidation_mode'
          and upper(coalesce(r.command_json->>'consolidation_mode','')) not in(
            'NONE','BY_WEEK','ANY_WEEK')
          then 'INVALID_CONSOLIDATION_MODE'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'allow_early'
          and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
          then 'ALLOW_EARLY_MUST_BE_BOOLEAN'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(
            r.command_json->>'target_invoice_week','')),'') is not null
          and not pg_input_is_valid(
            r.command_json->>'target_invoice_week','date')
          then 'INVALID_TARGET_INVOICE_WEEK'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'base_invoice_id','')),'') is null
          then 'BASE_INVOICE_ID_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and(select count(*) from command_ids x
            where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_BASE_INVOICE_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'credit_reason','')),'') is null
          then 'CREDIT_REASON_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'command_token','')),'') is null
          then 'CREDIT_COMMAND_TOKEN_REQUIRED'
        when exists(select 1 from command_ids x
          where x.command_no=r.command_no and not x.valid_uuid)
          then 'MALFORMED_UUID'
        when r.command_type like 'GENERATE_%' and not exists(
          select 1 from generation_groups g where g.command_no=r.command_no)
          then 'GENERATION_SOURCES_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and (select count(*) from generation_groups g
            where g.command_no=r.command_no)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and(select count(*) from command_ids x where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_DOCUMENT_ENTITY_REQUIRED'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and nullif(btrim(coalesce(r.command_json->>'priority_reason','')),'') is null
          then 'DOCUMENT_PRIORITY_REASON_REQUIRED'
        when r.command_type='VIEW_INVOICE_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'DRAFT_PREVIEW'))<>'DRAFT_PREVIEW'
          then 'INVALID_INVOICE_DOCUMENT_PURPOSE'
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'TIMESHEET'))<>'TIMESHEET'
          then 'INVALID_TIMESHEET_DOCUMENT_PURPOSE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and not exists(select 1 from view_facts v
            where v.command_no=r.command_no and v.document_revision is not null)
          then 'DOCUMENT_ENTITY_NOT_FOUND'
        when r.command_type='PREPARE_ASSET' and not exists(
          select 1 from asset_specs a
          where a.command_no=r.command_no
            and a.source_kind in(
              'MANUAL_TIMESHEET','TIMESHEET_EVIDENCE','OTHER_EVIDENCE',
              'HR_REPORT','NHSP_REPORT','HIGHER_RATE_SUPPORT')
            and a.source_id is not null and a.source_revision is not null
            and a.original_r2_key is not null and a.original_filename is not null
            and a.declared_media_type is not null
            and(not a.rotation_supplied or a.rotation_degrees is not null))
          then 'INVALID_ASSET_SOURCE_METADATA'
        when r.command_type='PREPARE_ASSET'
          and r.command_json?'rotation_degrees'
          and coalesce(r.command_json->>'rotation_degrees','')!~'^(0|90|180|270)$'
          then 'INVALID_ASSET_ROTATION'
        when r.command_type='ISSUE_INVOICES'
          and(jsonb_typeof(r.command_json->'invoice_ids')<>'array'
            or coalesce(cardinality((select ids from canonical_ids x
              where x.command_no=r.command_no)),0)=0
            or coalesce((select resolved_count from issue_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUE_INVOICES_NOT_RESOLVED'
        when r.command_type='ISSUE_INVOICES'
          and (r.command_json?'allow_early'
            and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
            or r.command_json?'deliver'
            and jsonb_typeof(r.command_json->'deliver')<>'boolean')
          then 'ISSUE_FLAGS_MUST_BE_BOOLEAN'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(nullif(r.command_json->>'command_token',''),'')=''
          then 'ISSUE_COMMAND_TOKEN_REQUIRED'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='ISSUE_INVOICES'
          and r.command_json?'delivery_intent'
          and jsonb_typeof(r.command_json->'delivery_intent')<>'object'
          then 'ISSUE_DELIVERY_INTENT_MUST_BE_OBJECT'
        when r.command_type='ISSUE_INVOICES'
          and jsonb_typeof(r.command_json->'delivery_intent')='object'
          and (
            r.command_json->'delivery_intent'?'recipient_set'
              and jsonb_typeof(r.command_json->'delivery_intent'->'recipient_set')<>'array'
            or r.command_json->'delivery_intent'?'cc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'cc')<>'array'
            or r.command_json->'delivery_intent'?'bcc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'bcc')<>'array')
          then 'ISSUE_DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='ISSUE_INVOICES'
          and exists(
            select 1 from issue_delivery_intents intent
            where intent.command_no=r.command_no
              and intent.requested_count<>intent.valid_count)
          then 'ISSUE_DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='ISSUE_INVOICES' and exists(
          select 1 from command_ids x
          join public.invoice_operation_chunks c
            on c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
            and c.entity_id=x.id_text::uuid
            and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
          where x.command_no=r.command_no and x.valid_uuid)
          and not exists(
            select 1
            from public.invoice_operations exact
            join issue_facts f on f.command_no=r.command_no
            join issue_delivery_intents intent on intent.command_no=r.command_no
            where exact.idempotency_key=encode(digest(concat_ws('|',
              'ISSUE_INVOICES',f.invoice_revision_hash,
              coalesce(r.command_json->>'allow_early','false'),
              coalesce(r.command_json->>'deliver','false'),
              coalesce(r.command_json->>'command_token',''),
              encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
              'sha256'),'hex')
              and exact.status in(
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
          then 'ACTIVE_ISSUE_CONFLICT'
        when r.command_type='DELIVER_INVOICES'
          and not(
            jsonb_typeof(r.command_json->'invoice_ids')='array'
            or nullif(btrim(coalesce(r.command_json->>'invoice_id','')),'') is not null)
          then 'DELIVERY_INVOICE_IDS_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and nullif(btrim(coalesce(
            r.command_json->>'delivery_request_token','')),'') is null
          then 'DELIVERY_REQUEST_TOKEN_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'recipient_set'
          and jsonb_typeof(r.command_json->'recipient_set')<>'array'
          then 'DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and ((r.command_json?'cc' and jsonb_typeof(r.command_json->'cc')<>'array')
            or(r.command_json?'bcc' and jsonb_typeof(r.command_json->'bcc')<>'array'))
          then 'DELIVERY_CC_BCC_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and exists(select 1 from recipient_sets rs
            where rs.command_no=r.command_no and rs.invalid_count>0)
          then 'DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_part_number'
          and coalesce(r.command_json->>'delivery_part_number','') !~ '^[1-9][0-9]*$'
          then 'INVALID_DELIVERY_PART_NUMBER'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_policy'
          and upper(coalesce(r.command_json->>'delivery_policy',''))
            not in('ATTACH','SPLIT','SECURE_LINK')
          then 'INVALID_DELIVERY_POLICY'
        when r.command_type='DELIVER_INVOICES'
          and(coalesce((select resolved_count from delivery_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUED_DOCUMENT_NOT_READY'
        when r.command_type='RECONCILE'
          and not(r.command_json?'operation_ids'
            or r.command_json?'older_than_seconds') then 'RECONCILE_SCOPE_REQUIRED'
        when r.command_type='RECONCILE'
          and r.command_json?'operation_ids'
          and jsonb_typeof(r.command_json->'operation_ids')<>'array'
          then 'RECONCILE_OPERATION_IDS_MUST_BE_ARRAY'
        when r.command_type='RECONCILE'
          and jsonb_typeof(r.command_json->'operation_ids')='array'
          and jsonb_array_length(r.command_json->'operation_ids')>500
          then 'RECONCILE_OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='RECONCILE'
          and r.command_json?'older_than_seconds'
          and coalesce(r.command_json->>'older_than_seconds','') !~ '^[0-9]{1,6}$'
          then 'RECONCILE_AGE_MUST_BE_INTEGER_SECONDS'
      end error_code,
      case when r.command_type like 'GENERATE_%' then (
        select jsonb_agg(jsonb_build_object(
          'group_key',g.group_key,'code',g.blocker_code,'detail',g.blocker_detail)
          order by g.group_key)
        from generation_groups g
        where g.command_no=r.command_no and g.blocker_code is not null)
      end error_detail
    from raw r cross join(select count(*) from issue_entity_locks) lock_barrier
  ),
  valid_commands as materialized (
    select r.* from raw r join command_validation v using(command_no,command_type)
    where v.error_code is null
  ),
  inserted_assets as materialized (
    insert into public.invoice_document_assets(
      source_kind,source_id,source_revision,original_r2_key,original_filename,
      declared_media_type,orientation_degrees,status,normalised_manifest_json,
      created_at_utc,updated_at_utc)
    select a.source_kind,a.source_id,a.source_revision,a.original_r2_key,
      a.original_filename,a.declared_media_type,a.rotation_degrees,
      'DISCOVERED','[]'::jsonb,v_now,v_now
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    on conflict(source_kind,source_id,source_revision,original_r2_key) do nothing
    returning *
  ),
  assets as materialized (
    select a.command_no,inserted.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join inserted_assets inserted
      on inserted.source_kind=a.source_kind
      and inserted.source_id=a.source_id
      and inserted.source_revision=a.source_revision
      and inserted.original_r2_key=a.original_r2_key
    union all
    select a.command_no,registered.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join public.invoice_document_assets registered
      on registered.source_kind=a.source_kind
      and registered.source_id=a.source_id
      and registered.source_revision=a.source_revision
      and registered.original_r2_key=a.original_r2_key
    where not exists(
      select 1 from inserted_assets inserted
      where inserted.source_kind=a.source_kind
        and inserted.source_id=a.source_id
        and inserted.source_revision=a.source_revision
        and inserted.original_r2_key=a.original_r2_key)
  ),
  asset_workflow_state as materialized (
    select a.*,
      exists(
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.document_asset_id=a.id
          and c.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
          and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      ) has_active_work
    from assets a
  ),
  operation_specs as materialized (
    select v.command_no,v.command_type,v.command_json,
      'GENERATE_INVOICES'::text operation_type,
      case when count(*)=1 then 'CLIENT' else 'INVOICE_BATCH' end entity_type,
      case when count(*)=1 then(array_agg(g.client_id order by g.client_id))[1]
        else null::uuid end entity_id,
      encode(digest(string_agg(g.source_revision_hash,'|' order by g.group_key),
        'sha256'),'hex') source_revision,
      null::text template_version,
      case when v.command_type='GENERATE_AUTO' then 200 else 600 end priority,
      count(*)::integer unit_count,
      jsonb_build_object('generation_groups',
        jsonb_agg(g.idempotency_components order by g.group_key)) canonical_input,
      encode(digest('GENERATE_INVOICES|'||
        string_agg(g.idempotency_components::text,'|' order by g.group_key),
        'sha256'),'hex') idempotency_key
    from valid_commands v join generation_groups g on g.command_no=v.command_no
    where v.command_type like 'GENERATE_%'
    group by v.command_no,v.command_type,v.command_json
    union all
    select v.command_no,v.command_type,v.command_json,'BUILD_DOCUMENT',
      f.entity_type,f.entity_id,f.document_revision::text,f.template_version,1000,1,
      jsonb_build_object('entity_type',f.entity_type,'entity_id',f.entity_id,
        'purpose',f.purpose,'document_revision',f.document_revision,
        'template_version',f.template_version),
      encode(digest(concat_ws('|','BUILD_DOCUMENT',f.entity_type,f.entity_id::text,
        f.purpose,f.document_revision::text,f.template_version),'sha256'),'hex')
    from valid_commands v join view_facts f on f.command_no=v.command_no
    where v.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and not exists(
        select 1 from public.invoice_document_versions ready
        where ready.entity_type=f.entity_type and ready.entity_id=f.entity_id
          and ready.purpose=f.purpose
          and ready.source_revision=f.document_revision::text
          and ready.template_version=f.template_version and ready.status='READY')
    union all
    select v.command_no,v.command_type,v.command_json,'PREPARE_ASSET',
      'DOCUMENT_ASSET',a.id,a.source_revision,null,550,1,
      jsonb_build_object('document_asset_id',a.id,'source_kind',a.source_kind,
        'source_id',a.source_id,'source_revision',a.source_revision,
        'original_r2_key',a.original_r2_key),
      encode(digest(concat_ws('|','PREPARE_ASSET',a.source_kind,a.source_id::text,
        a.source_revision,a.original_r2_key),'sha256'),'hex')
    from valid_commands v join asset_workflow_state a
      on a.command_no=v.command_no
    where v.command_type='PREPARE_ASSET'
      and a.status in('DISCOVERED','INSPECTING','NORMALISING')
      and not(a.status in('INSPECTING','NORMALISING')
        and not a.has_active_work)
    union all
    select v.command_no,v.command_type,v.command_json,'ISSUE_INVOICES',
      'INVOICE_BATCH',null,f.invoice_revision_hash,null,850,
      cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'invoice_revision_hash',f.invoice_revision_hash,
        'allow_early',coalesce(v.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(v.command_json->'deliver','false'::jsonb),
        'command_token',v.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(v.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      encode(digest(concat_ws('|','ISSUE_INVOICES',f.invoice_revision_hash,
        coalesce(v.command_json->>'allow_early','false'),
        coalesce(v.command_json->>'deliver','false'),
        coalesce(v.command_json->>'command_token',''),
        encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
        'sha256'),'hex')
    from valid_commands v join issue_facts f on f.command_no=v.command_no
    join issue_delivery_intents intent on intent.command_no=v.command_no
    where v.command_type='ISSUE_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'DELIVER_INVOICES',
      'INVOICE_BATCH',null,f.delivery_revision,
      coalesce(nullif(v.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1'),400,cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'issued_document_version_ids',to_jsonb(f.document_version_ids),
        'delivery_revision',f.delivery_revision,
        'recipient_set',rs.canonical_recipients,
        'recipient_set_hash',drg.route_set_hash,
        'frozen_delivery_routes',drg.frozen_routes,
        'template_version',coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_part_number',coalesce(v.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',v.command_json->>'delivery_request_token'),
      encode(digest(concat_ws('|','DELIVER_INVOICES',f.delivery_revision,
        drg.route_set_hash,
        coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(v.command_json->>'delivery_part_number','1'),
        v.command_json->>'delivery_request_token'),'sha256'),'hex')
    from valid_commands v join delivery_facts f on f.command_no=v.command_no
    join recipient_sets rs on rs.command_no=v.command_no
    join delivery_route_groups drg on drg.command_no=v.command_no
    where v.command_type='DELIVER_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'RECONCILE_INVOICE_WORK',
      'SYSTEM',null,
      encode(digest(coalesce(v.command_json->'operation_ids','[]')::text||'|'||
        coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex'),
      null,50,1,
      jsonb_build_object(
        'operation_ids',coalesce(v.command_json->'operation_ids','[]'::jsonb),
        'older_than_seconds',least(604800,greatest(30,case
          when coalesce(v.command_json->>'older_than_seconds','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'older_than_seconds')::integer else 300 end)),
        'max_rows',least(500,greatest(1,case
          when coalesce(v.command_json->>'max_rows','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'max_rows')::integer else 100 end))),
      encode(digest('RECONCILE|'||coalesce(v.command_json->'operation_ids','[]')::text||
        '|'||coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex')
    from valid_commands v where v.command_type='RECONCILE'
  ),
  locks as materialized (
    select pg_advisory_xact_lock(hashtextextended(x.lock_key,0))
    from(
      select idempotency_key lock_key from operation_specs
      union
      select 'ISSUE_INVOICE|'||unnest(f.invoice_ids)::text
      from issue_facts f join valid_commands v on v.command_no=f.command_no
      where v.command_type='ISSUE_INVOICES'
    ) x order by x.lock_key
  ),
  existing_before as materialized (
    select s.command_no,o.*
    from operation_specs s
    join lateral (
      select candidate.*
      from public.invoice_operations candidate
      where candidate.idempotency_key=s.idempotency_key
        and candidate.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(candidate.status='COMPLETE') desc,candidate.created_at_utc desc
      limit 1
    ) o on true
  ),
  inserted_operations as materialized (
    insert into public.invoice_operations(
      operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
      status,phase,priority,source_revision,template_version,input_json,
      config_json,progress_json,total_units,chunk_count,control_version,
      change_seq,manifest_generation,manifest_committed,release_complete,
      created_at_utc,updated_at_utc)
    select s.operation_type,s.entity_type,s.entity_id,p_actor_user_id,
      s.idempotency_key,'QUEUED','SUBMITTED',s.priority,s.source_revision,
      s.template_version,s.canonical_input,
      jsonb_build_object(
        'command_type',s.command_type,
        'processor_policy',private._invoice_processor_limits()),
      jsonb_build_object('status_message','Accepted','total_units',s.unit_count,
        'completed_units',0,'failed_units',0),
      s.unit_count,s.unit_count,1,nextval('public.invoice_operation_change_seq'),
      case when s.command_type in ('ISSUE_INVOICES','DELIVER_INVOICES')
        then 1 else 0 end,
      true,true,
      v_now,v_now
    from operation_specs s cross join(select count(*) from locks) lock_barrier
    where not exists(select 1 from existing_before e where e.command_no=s.command_no)
    on conflict do nothing
    returning *
  ),
  chosen as materialized (
    select s.*,coalesce(i.id,e.id) operation_id,
      coalesce(i.status,e.status) operation_status,
      coalesce(i.phase,e.phase) operation_phase,
      coalesce(i.control_version,e.control_version) control_version,
      coalesce(i.change_seq,e.change_seq) change_seq,
      coalesce(i.priority,e.priority,s.priority) current_priority,
      i.id is not null created,e.id is not null reused
    from operation_specs s
    left join inserted_operations i on i.idempotency_key=s.idempotency_key
    left join existing_before e on e.command_no=s.command_no
  ),
  raised as materialized (
    update public.invoice_operations o
    set priority=greatest(o.priority,c.priority),updated_at_utc=v_now,
        change_seq=case when o.priority<c.priority
          then nextval('public.invoice_operation_change_seq') else o.change_seq end
    from chosen c
    where c.reused and o.id=c.operation_id
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning o.id
  ),
  existing_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
      and v.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
  ),
  document_versions as materialized (
    insert into public.invoice_document_versions(
      entity_type,entity_id,purpose,operation_id,source_revision,template_version,
      status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select f.entity_type,f.entity_id,f.purpose,c.operation_id,
      f.document_revision::text,f.template_version,'PLANNING','{}'::jsonb,
      encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
      encode(digest('[]','sha256'),'hex'),v_now
    from chosen c join view_facts f on f.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE'
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET') and status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning *
  ),
  all_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select e.* from existing_document_versions e
  ),
  chunk_specs as materialized (
    select c.operation_id,'GENERATION_GROUP'::text chunk_type,
      'VALIDATE_SOURCES'::text phase,
      encode(digest(concat_ws('|','GENERATION_GROUP',g.group_key,
        g.source_revision_hash,c.command_type,
        coalesce(g.idempotency_components->>'consolidation_mode',''),
        coalesce(g.idempotency_components->>'invoice_stream',''),'1'),
        'sha256'),'hex') work_key,
      row_number() over(partition by c.operation_id order by g.group_key)::integer-1 sequence_no,
      'CLIENT'::text entity_type,g.client_id entity_id,null::uuid document_version_id,
      null::uuid document_asset_id,
      g.idempotency_components||jsonb_build_object(
        'canonical_source_ids',to_jsonb(g.canonical_source_ids),
        'canonical_source_members',g.canonical_source_members,
        'source_types',to_jsonb(g.source_types),
        'source_revision',g.source_revision_hash,
        'resolver_blocker_code',g.blocker_code,
        'resolver_blocker_detail',g.blocker_detail) payload_json,
      c.priority,c.control_version
    from chosen c join generation_groups g on g.command_no=c.command_no
    where c.command_type like 'GENERATE_%' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',v.id::text,
        f.document_revision::text,f.template_version,'1'),'sha256'),'hex'),
      0,f.entity_type,f.entity_id,
      v.id,null,jsonb_build_object('purpose',f.purpose,
        'source_revision',f.document_revision::text,
        'template_version',f.template_version),c.priority,c.control_version
    from chosen c join view_facts f on f.command_no=c.command_no
    join all_document_versions v on v.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE' and v.status<>'READY'
    union all
    select c.operation_id,'ASSET_INSPECT','INSPECT',
      encode(digest(concat_ws('|','ASSET_INSPECT',a.id::text,a.source_revision,
        private._invoice_processor_limits()->>'policy_version'),'sha256'),'hex'),
      0,'DOCUMENT_ASSET',a.id,
      null,a.id,jsonb_build_object('source_revision',a.source_revision,
        'source_kind',a.source_kind,'source_id',a.source_id,
        'rotation_degrees',a.orientation_degrees),c.priority,c.control_version
    from chosen c join assets a on a.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and c.operation_status<>'COMPLETE'
      and a.status not in('READY','INSPECTING','NORMALISING')
    union all
    select c.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',i.id::text,
        i.document_revision::text,c.command_json->>'command_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,null,null,
      jsonb_build_object(
        'request_key',c.command_no::text||':'||i.id::text,
        'invoice_id',i.id,'source_revision',i.document_revision,
        'evaluation_date',(v_now at time zone 'Europe/London')::date,
        'frozen_issue_at_utc',v_now,
        'allow_early',coalesce(c.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.command_json->'deliver','false'::jsonb),
        'command_token',c.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(c.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      c.priority,c.control_version
    from chosen c join issue_facts f on f.command_no=c.command_no
    join issue_delivery_intents intent on intent.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where c.command_type='ISSUE_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DELIVERY_PREPARE','PREPARE',
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        i.issued_document_version_id::text,dr.route_policy_hash,
        coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(c.command_json->>'delivery_part_number','1'),
        c.command_json->>'delivery_request_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,i.issued_document_version_id,null,
      jsonb_build_object(
        'invoice_id',i.id,'issued_document_version_id',i.issued_document_version_id,
        'recipient_set',dr.canonical_to,'cc',dr.canonical_cc,
        'bcc',dr.canonical_bcc,
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'routing_request',jsonb_build_object(
          'request_key',dr.request_key,
          'invoice_id',i.id,
          'recipient_set',rs.canonical_recipients,
          'cc',dr.canonical_cc,
          'bcc',dr.canonical_bcc,
          'delivery_policy',upper(coalesce(
            nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
          'template_version',coalesce(
            nullif(c.command_json->>'delivery_template_version',''),
            'invoice-delivery-v1')),
        'frozen_delivery_route',jsonb_build_object(
          'request_key',dr.request_key,
          'to',dr.canonical_to,'cc',dr.canonical_cc,'bcc',dr.canonical_bcc,
          'recipient_set_hash',dr.recipient_set_hash,
          'route_policy_hash',dr.route_policy_hash,
          'route_source',dr.route_source,'do_not_send',dr.do_not_send,
          'delivery_suppressed',dr.delivery_suppressed,
          'suppression_reason',dr.suppression_reason,
          'self_bill',dr.self_bill,
          'template_version',coalesce(
            nullif(c.command_json->>'delivery_template_version',''),
            'invoice-delivery-v1'),
          'delivery_policy',upper(coalesce(
            nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
          'warning_codes',dr.warning_codes,'blocker_codes',dr.blocker_codes,
          'evaluated_date',(v_now at time zone 'Europe/London')::date),
        'template_version',coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(
          nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
        'delivery_part_number',coalesce(c.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',encode(digest(concat_ws('|',
          'DELIVERY_REQUEST',c.command_json->>'delivery_request_token',
          i.id::text,i.issued_document_version_id::text),'sha256'),'hex'),
        'user_command_token',c.command_json->>'delivery_request_token'),
      c.priority,c.control_version
    from chosen c join delivery_facts f on f.command_no=c.command_no
    join recipient_sets rs on rs.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join delivery_routes dr on dr.command_no=c.command_no
      and dr.request_key=c.command_no::text||':'||i.id::text
      and dr.invoice_id=i.id
    where c.command_type='DELIVER_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'RECONCILE','RECONCILE',
      encode(digest(concat_ws('|','RECONCILE',c.canonical_input::text,'1'),
        'sha256'),'hex'),
      0,'SYSTEM',null,null,null,
      c.canonical_input,c.priority,c.control_version
    from chosen c where c.command_type='RECONCILE' and c.operation_status<>'COMPLETE'
  ),
  inserted_chunks as materialized (
    insert into public.invoice_operation_chunks(
      id,operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,document_asset_id,status,priority,run_after_utc,
      payload_json,operation_control_version,manifest_generation,
      is_manifest_member,manifest_committed,result_visible,
      created_at_utc,updated_at_utc)
    select generated.id,c.operation_id,c.chunk_type,c.phase,c.work_key,c.sequence_no,
      c.entity_type,c.entity_id,
      c.document_version_id,c.document_asset_id,'QUEUED',c.priority,v_now,
      case when c.chunk_type='DELIVERY_PREPARE'
        then jsonb_set(
          jsonb_set(
            jsonb_set(
              coalesce(c.payload_json,'{}'::jsonb),
              '{request_key}',
              to_jsonb(generated.id::text),
              true),
            '{routing_request,request_key}',
            to_jsonb(generated.id::text),
            true),
          '{frozen_delivery_route,request_key}',
          to_jsonb(generated.id::text),
          true)
        else c.payload_json end,
      c.control_version,
      case when c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE')
        then 1 else 0 end,
      c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE'),
      c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE'),
      false,
      v_now,v_now
    from chunk_specs c
    cross join lateral (
      select gen_random_uuid() id
      where c.operation_id is not null
    ) generated
    on conflict do nothing
    returning *
  ),
  asset_operation_links as (
    update public.invoice_document_assets a
    set operation_id=c.operation_id,
        status=case when a.status='DISCOVERED' then 'INSPECTING' else a.status end,
        updated_at_utc=v_now
    from chosen c join assets x on x.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and a.id=x.id and a.status<>'READY'
    returning a.id
  ),
  entity_pointers as (
    update public.invoices i
    set active_document_operation_id=case
          when c.command_type='VIEW_INVOICE_DOCUMENT' then c.operation_id
          else i.active_document_operation_id end,
        document_state=case when c.command_type='VIEW_INVOICE_DOCUMENT'
          then 'QUEUED' else i.document_state end,
        active_issue_operation_id=case when c.command_type='ISSUE_INVOICES'
          then c.operation_id else i.active_issue_operation_id end,
        issue_state=case when c.command_type='ISSUE_INVOICES'
          then 'VALIDATING' else i.issue_state end,
        updated_at=v_now
    from chosen c
    where(c.command_type='VIEW_INVOICE_DOCUMENT' and i.id=c.entity_id)
      or(c.command_type='ISSUE_INVOICES' and exists(
        select 1
        from issue_facts f
        where f.command_no=c.command_no
          and i.id=any(f.invoice_ids)))
    returning i.id
  ),
  timesheet_pointers as (
    update public.timesheets t
    set active_document_operation_id=c.operation_id,document_state='QUEUED',
        updated_at=v_now
    from chosen c
    where c.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=c.entity_id
    returning t.timesheet_id
  ),
  refreshed_counts as (
    update public.invoice_operations o
    set total_units=greatest(o.total_units,q.n),
        chunk_count=greatest(o.chunk_count,q.n),
        progress_json=coalesce(o.progress_json,'{}'::jsonb)||jsonb_build_object(
          'status_message','Queued',
          'total_units',greatest(o.total_units,q.n)),
        updated_at_utc=v_now,
        change_seq=nextval('public.invoice_operation_change_seq')
    from(
      select intended.operation_id,count(*)::integer n
      from chunk_specs intended
      cross join(
        select count(*) from inserted_chunks
      ) ensure_chunk_insert
      group by intended.operation_id
    ) q
    where o.id=q.operation_id and o.status<>'COMPLETE'
    returning o.id,o.chunk_count n
  ),
  ready_results as (
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_version_id',v.id,'r2_key',v.r2_key,
      'created',false,'reused_active',false,'reused_ready',true,
      'priority_raised',false,'blocked',false,'terminal_error',null) result
    from raw r join view_facts f on f.command_no=r.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version and v.status='READY'
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',true,'priority_raised',false,'blocked',false,
      'terminal_error',null) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET' and a.status='READY'
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status',a.status,
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'terminal_error',coalesce(a.error_json,
        jsonb_build_object('code','ASSET_'||a.status))) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status','BLOCKED',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'reconcile_available',true,
      'terminal_error',jsonb_build_object(
        'code','ASSET_WORKFLOW_INCONSISTENT',
        'asset_status',a.status,'document_asset_id',a.id)) result
    from raw r join asset_workflow_state a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('INSPECTING','NORMALISING')
      and not a.has_active_work
  ),
  operation_results as (
    select c.command_no,jsonb_build_object(
      'command_no',c.command_no,'command_type',c.command_type,'accepted',true,
      'operation_id',c.operation_id,'operation_type',c.operation_type,
      'status',coalesce(o.status,c.operation_status),
      'phase',coalesce(o.phase,c.operation_phase),
      'source_revision',c.source_revision,
      'change_seq',coalesce(o.change_seq,c.change_seq),
      'created',c.created,
      'reused_active',c.reused and coalesce(o.status,c.operation_status)<>'COMPLETE',
      'reused_ready',c.reused and coalesce(o.status,c.operation_status)='COMPLETE',
      'priority_raised',c.reused and c.priority>c.current_priority,
      'blocked',coalesce(o.status,c.operation_status)='BLOCKED',
      'terminal_error',null,
      'chunk_count',greatest(c.unit_count,(select count(*)
        from chunk_specs intended
        where intended.operation_id=c.operation_id)))
      result
    from chosen c
    left join public.invoice_operations o on o.id=c.operation_id
    left join refreshed_counts rc on rc.id=c.operation_id
  ),
  error_results as (
    select v.command_no,jsonb_build_object(
      'command_no',v.command_no,'command_type',v.command_type,
      'accepted',false,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,
      'blocked',false,
      'terminal_error',jsonb_build_object('code',v.error_code,
        'detail',v.error_detail),
      'error',jsonb_build_object('code',v.error_code,'detail',v.error_detail)) result
    from command_validation v where v.error_code is not null
  ),
  combined as (
    select * from ready_results
    union all
    select o.* from operation_results o
    where not exists(select 1 from ready_results r where r.command_no=o.command_no)
    union all
    select * from error_results
  )
  select coalesce(jsonb_agg(result order by command_no),'[]'::jsonb)
  into v_result from combined;

  return v_result;
end;
$function$;

-- private._invoice_presentation_snapshot_batch(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_presentation_snapshot_batch(p_requests jsonb, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(request_key text, snapshot_schema_version text, presentation_model jsonb, timesheet_sources jsonb, supporting_sources jsonb, higher_rate_support jsonb, snapshot_json jsonb, snapshot_hash text, valid boolean, error_code text, error_detail jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
#variable_conflict use_column
declare
  v_now timestamptz := coalesce(p_now_utc, now());
begin
  if p_requests is null or jsonb_typeof(p_requests) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  if jsonb_array_length(p_requests) < 1
     or jsonb_array_length(p_requests) > 100 then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  return query
  with recursive raw_requests as materialized (
    select x.ordinality::integer request_no,
           x.value raw_request,
           nullif(btrim(coalesce(x.value->>'request_key','')),'') req_key,
           upper(nullif(btrim(coalesce(x.value->>'entity_type','')),'')) entity_type,
           case when coalesce(x.value->>'entity_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (x.value->>'entity_id')::uuid end entity_id,
           upper(nullif(btrim(coalesce(x.value->>'purpose','')),'')) purpose,
           coalesce(nullif(btrim(x.value->>'template_version'),''),'invoice-professional-v2') template_version,
           case when pg_input_is_valid(nullif(x.value->>'issue_at_utc',''),'timestamptz') then (x.value->>'issue_at_utc')::timestamptz end issue_at_utc,
           case when pg_input_is_valid(nullif(x.value->>'tax_point_utc',''),'timestamptz') then (x.value->>'tax_point_utc')::timestamptz end tax_point_utc,
           case when pg_input_is_valid(nullif(x.value->>'due_at_utc',''),'timestamptz') then (x.value->>'due_at_utc')::timestamptz end due_at_utc
    from jsonb_array_elements(p_requests) with ordinality x(value,ordinality)
  ),
  key_stats as materialized (
    select req_key,count(*)::integer key_count,min(request_no) first_request_no
    from raw_requests
    where req_key is not null
    group by req_key
  ),
  duplicate_key_results as materialized (
    select r.request_no,
           r.req_key request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           'DUPLICATE_REQUEST_KEY'::text error_code,
           jsonb_build_object('request_no',r.request_no,'request_key',r.req_key,'duplicate_count',ks.key_count,'first_request_no',ks.first_request_no) error_detail
    from raw_requests r
    join key_stats ks on ks.req_key=r.req_key
    where ks.key_count > 1
  ),
  processable as materialized (
    select r.*
    from raw_requests r
    left join key_stats ks on ks.req_key=r.req_key
    where coalesce(ks.key_count,0) <= 1
  ),
  invalid_request_results as materialized (
    select p.request_no,
           coalesce(p.req_key,'__request_'||p.request_no::text) request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           case
             when p.req_key is null then 'REQUEST_KEY_REQUIRED'
             when length(p.req_key) > 256 then 'REQUEST_KEY_TOO_LONG'
             when p.entity_type not in('INVOICE','TIMESHEET') then 'ENTITY_TYPE_UNSUPPORTED'
             when p.entity_id is null then 'ENTITY_ID_INVALID'
             when p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET') then 'PURPOSE_UNSUPPORTED'
             when p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null) then 'FINAL_ISSUE_DATES_REQUIRED'
             else 'PRESENTATION_REQUEST_INVALID' end error_code,
           jsonb_build_object('request_no',p.request_no,'entity_type',p.entity_type,'purpose',p.purpose) error_detail
    from processable p
    where p.req_key is null
       or length(p.req_key) > 256
       or p.entity_type not in('INVOICE','TIMESHEET')
       or p.entity_id is null
       or p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
       or (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  valid_requests as materialized (
    select p.*
    from processable p
    where p.req_key is not null and length(p.req_key) <= 256
      and p.entity_type in('INVOICE','TIMESHEET')
      and p.entity_id is not null
      and p.purpose in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
      and not (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  requested_invoices as materialized (
    select entity_id invoice_id from valid_requests where entity_type='INVOICE'
  ),
  reference_scope as materialized (
    select r.*
    from private._invoice_reference_rows_batch(
      coalesce((select array_agg(distinct invoice_id) from requested_invoices), array[]::uuid[])
    ) r
  ),
  invoice_line_base as materialized (
    select il.*,
           coalesce(nullif(btrim(vs.candidate_name),''),nullif(btrim(t.occupant_key_norm),'')) worker_name,
           coalesce(t.week_ending_date,
             case when pg_input_is_valid(nullif(il.meta_json->>'week_ending_date',''),'date')
               then (il.meta_json->>'week_ending_date')::date end)
             timesheet_week_ending_date,
           row_number() over(partition by il.invoice_id order by il.created_at,il.id)::integer base_display_order,
           case when pg_input_is_valid(nullif(il.meta_json->>'quantity',''),'numeric') then nullif(il.meta_json->>'quantity','')::numeric end meta_quantity,
           case when pg_input_is_valid(nullif(il.meta_json->>'units',''),'numeric') then nullif(il.meta_json->>'units','')::numeric end meta_units,
           case when il.timesheet_id is null
             then coalesce(nullif(btrim(il.meta_json->>'reference'),''),
               nullif(btrim(il.meta_json->>'po_number'),''))
             else refs.reference end canonical_reference,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_source,'NONE') end reference_source,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_scope,'TIMESHEET') end reference_scope,
           coalesce(refs.reference_source_row_keys,'[]'::jsonb)
             reference_source_row_keys,
           coalesce(refs.reference_required,false) reference_required
    from public.invoice_lines il
    left join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=il.timesheet_id
    left join lateral (
      select
        string_agg(x.current_reference,', ' order by x.first_row_key) reference,
        case when count(*)=1 then min(x.reference_source)
          else 'AGGREGATED_CANONICAL' end reference_source,
        case when count(*)=1 then min(x.reference_scope)
          else 'AGGREGATED_TIMESHEET' end reference_scope,
        jsonb_agg(x.row_key order by x.first_row_key) reference_source_row_keys,
        bool_or(x.is_required) reference_required
      from (
        select r.current_reference,min(r.row_key) first_row_key,
          min(r.row_key) row_key,
          min(case
            when r.ref_target='SEGMENT' then 'SEGMENT'
            when r.day_ymd is not null then 'DAY'
            else 'TIMESHEET' end) reference_source,
          min(case
            when r.ref_target='SEGMENT' then 'EXACT_SEGMENT'
            when r.day_ymd is not null then 'EXACT_DAY'
            else 'WHOLE_TIMESHEET' end) reference_scope,
          bool_or(r.is_required) is_required
        from reference_scope r
        where r.invoice_id=il.invoice_id and r.timesheet_id=il.timesheet_id
          and nullif(btrim(r.current_reference),'') is not null
        group by r.current_reference
      ) x
    ) refs on true
    where il.invoice_id in(select invoice_id from requested_invoices)
  ),
  invoice_line_component_raw as materialized (
    select b.invoice_id,b.id,b.created_at,
           (b.base_display_order*100+v.display_suffix)::integer base_display_order,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||v.bucket row_key,
           v.label description,
           b.canonical_reference reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           'hours'::text unit,
           round(coalesce(v.hours,0),4) quantity_raw,
           round(coalesce(v.hours,0)*coalesce(v.rate,0),4) net_raw,
           round(coalesce(b.total_charge_ex_vat,0),2) line_net,
           round(coalesce(b.vat_amount,0),2) line_vat,
           coalesce(b.vat_rate_pct,0) vat_rate,
           b.source_key,b.id source_invoice_line_id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    cross join lateral (values
      ('DAY','Day',1,coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
      ('NIGHT','Night',2,coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
      ('SATURDAY','Saturday',3,coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
      ('SUNDAY','Sunday',4,coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
      ('BANK_HOLIDAY','Bank holiday',5,coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
    ) v(bucket,label,display_suffix,hours,rate)
    where coalesce(v.hours,0)<>0
    union all
    select b.invoice_id,b.id,b.created_at,(b.base_display_order*100+90)::integer,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||lower(coalesce(nullif(b.meta_json->>'line_type',''),'residual')),
           case
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'Mileage'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%TRAVEL%' then 'Travel'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ACCOMMODATION%' then 'Accommodation'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%HIGHER%' then 'Higher rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADDITIONAL%' then 'Additional rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%REVERS%' then 'Reversal'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%CREDIT%' then 'Credit'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADJUST%' then 'Adjustment'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%EXPENSE%' then 'Other expenses'
             else coalesce(nullif(b.description,''),'Invoice line') end,
           b.canonical_reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           case when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'miles' else 'item' end,
           round(coalesce(b.meta_quantity,b.meta_units,1),4),
           round(coalesce(b.total_charge_ex_vat,0) - (
             coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
             + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
             + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
             + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
             + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
           ),4),
           round(coalesce(b.total_charge_ex_vat,0),2),round(coalesce(b.vat_amount,0),2),coalesce(b.vat_rate_pct,0),b.source_key,b.id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    where abs(coalesce(b.total_charge_ex_vat,0) - (
      coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
      + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
      + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
      + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
      + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
    )) > 0.004
       or not exists (
         select 1 from (values
           (coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
           (coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
           (coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
           (coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
           (coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
         ) nonzero(h,a) where coalesce(h,0)<>0 or coalesce(a,0)<>0)
  ),
  invoice_line_component_ranked as materialized (
    select r.*,
      row_number() over(partition by r.id order by r.base_display_order,r.row_key)::integer component_no,
      count(*) over(partition by r.id)::integer component_count,
      case when coalesce(r.line_net,0)<>0 then r.line_vat * r.net_raw / r.line_net
           else r.line_vat / nullif(count(*) over(partition by r.id),0) end raw_vat
    from invoice_line_component_raw r
  ),
  invoice_line_components as materialized (
    select q.invoice_id,q.id,q.created_at,q.base_display_order,q.row_key,q.description,
           q.reference,q.reference_required,q.reference_scope,q.reference_source,
           q.reference_source_row_keys,q.unit,
           q.quantity_raw quantity,
           case when q.quantity_raw<>0 then round(q.net_amount/q.quantity_raw,4) else q.net_amount end unit_price,
           q.net_amount,q.vat_rate,q.vat_amount,round(q.net_amount+q.vat_amount,2) gross_amount,
           q.source_key,q.source_invoice_line_id,q.worker_name,
           q.timesheet_week_ending_date
    from (
      select r.*,
        case when r.component_no=r.component_count
          then round(r.line_net - coalesce(sum(round(r.net_raw,2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(r.net_raw,2) end net_amount,
        case when r.component_no=r.component_count
          then round(r.line_vat - coalesce(sum(round(coalesce(r.raw_vat,0),2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(coalesce(r.raw_vat,0),2) end vat_amount
      from invoice_line_component_ranked r
    ) q
  ),
  invoice_line_rows as materialized (
    select c.invoice_id,
           jsonb_agg(jsonb_build_object(
             'row_key',c.row_key,
             'source_invoice_line_id',c.source_invoice_line_id,
             'source_key',coalesce(c.source_key,c.source_invoice_line_id::text),
             'description',c.description,
             'worker',c.worker_name,
             'week_ending_date',c.timesheet_week_ending_date,
             'reference',c.reference,
             'reference_required',c.reference_required,
             'reference_scope',c.reference_scope,
             'reference_source',c.reference_source,
             'reference_source_row_keys',c.reference_source_row_keys,
             'unit',c.unit,
             'quantity',c.quantity::text,
             'unit_price',c.unit_price::text,
             'net_amount',c.net_amount::text,
             'vat_rate',c.vat_rate::text,
             'vat_amount',c.vat_amount::text,
             'gross_amount',c.gross_amount::text,
             'display_order',c.base_display_order
           ) order by c.created_at,c.id,c.base_display_order) lines,
           round(sum(c.net_amount),2) line_net,
           round(sum(c.vat_amount),2) line_vat,
           round(sum(c.gross_amount),2) line_gross
    from invoice_line_components c
    group by c.invoice_id
  ),
  timesheet_targets as materialized (
    select distinct il.invoice_id,t.timesheet_id
    from requested_invoices ri
    join public.invoice_lines il on il.invoice_id=ri.invoice_id
      and il.timesheet_id is not null
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    union
    select null::uuid,vr.entity_id
    from valid_requests vr
    where vr.entity_type='TIMESHEET'
  ),
  timesheet_base as materialized (
    select target.invoice_id,t.timesheet_id,t.document_revision,
      upper(coalesce(t.sheet_scope::text,'')) sheet_scope,
      upper(coalesce(t.submission_mode::text,'')) submission_mode,
      t.contract_id,t.week_ending_date,
      t.worked_start_iso,t.worked_end_iso,t.break_start_iso,t.break_end_iso,
      coalesce(t.break_minutes,0) break_minutes,t.actual_schedule_json,
      t.day_references_json,t.reference_number,t.additional_units_week,
      t.additional_units_per_day,t.authorised_at_server,t.auth_name,
      t.auth_job_title,t.r2_nurse_key,t.r2_auth_key,t.img_sha256_nurse,
      t.img_sha256_auth,t.qr_status::text qr_status,t.qr_token,
      t.qr_payload_json,t.qr_signed_hash,t.qr_signed_at_utc,
      coalesce(vs.candidate_id,tf.candidate_id,ct.candidate_id) candidate_id,
      coalesce(vs.client_id,tf.client_id,ct.client_id) client_id,
      coalesce(nullif(btrim(cand.first_name),''),
        split_part(coalesce(vs.candidate_name,t.occupant_key_norm,''),' ',1))
        candidate_first_name,
      coalesce(nullif(btrim(cand.last_name),''),
        nullif(btrim(regexp_replace(
          coalesce(vs.candidate_name,t.occupant_key_norm,''),
          '^[^ ]+[ ]*','','g')),'')) candidate_surname,
      coalesce(nullif(btrim(tf.role),''),nullif(btrim(t.job_title_norm),''),
        nullif(btrim(ct.role),'')) job_profile_title,
      coalesce(nullif(btrim(cl.name),''),nullif(btrim(vs.client_name),''),
        nullif(btrim(t.hospital_norm),'')) client_name,
      nullif(lower(btrim(t.hospital_norm)),'') hospital_norm,
      nullif(lower(btrim(t.ward_norm)),'') ward_norm,
      coalesce(
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        nullif(btrim(cl.name),''),
        nullif(btrim(vs.client_name),'')) hospital,
      regexp_replace(
        regexp_replace(
          initcap(lower(nullif(btrim(t.ward_norm),''))),
          '\mNhs\M','NHS','g'),
        '\mIcu\M','ICU','g') ward_display,
      concat_ws(' - ',
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.ward_norm),''))),
            '\mNhs\M','NHS','g'),
          '\mIcu\M','ICU','g')) site_ward,
      coalesce(nullif(btrim(tf.band),''),nullif(btrim(t.band),'')) band,
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb) invoice_breakdown_json,
      coalesce(tf.additional_units_json,
        tf.invoice_breakdown_json#>'{additional,units}',
        '{}'::jsonb) additional_units_json,
      coalesce(ct.week_ending_weekday_snapshot,cs.week_ending_weekday,0)
        configured_week_ending_weekday,
      coalesce(pc.require_reference_to_invoice,false)
        or coalesce(pc.reference_number_required_to_issue_invoice,false)
        reference_required,
      sd.agency_name,
      case
        when nullif(coalesce(
          sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
          sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),'') is null
          then '{}'::jsonb
        else jsonb_build_object(
          'r2_key',coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),
          'sha256',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,sha256}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,sha256}')),
          'size_bytes',case when coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}',
            '')~'^[1-9][0-9]{0,18}$' then coalesce(
              sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
              sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}')::bigint end,
          'media_type',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,media_type}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,media_type}')))
      end logo_identity,
      coalesce(sd.timesheet_header_json,'{}'::jsonb) header_wording,
      coalesce(sd.timesheet_footer_json,'{}'::jsonb) footer_wording,
      coalesce(sd.temporary_worker_declaration_json,'{}'::jsonb)
        temporary_worker_declaration,
      coalesce(sd.client_declaration_json,'{}'::jsonb) client_declaration
    from timesheet_targets target
    join public.timesheets t on t.timesheet_id=target.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join public.contracts ct on ct.id=t.contract_id
    left join public.candidates cand on cand.id=coalesce(vs.candidate_id,ct.candidate_id)
    left join public.clients cl on cl.id=coalesce(vs.client_id,ct.client_id)
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
    left join lateral (
      select tf0.*
      from public.timesheets_financials tf0
      where tf0.timesheet_id=t.timesheet_id and tf0.is_current
      order by tf0.computed_at_utc desc nulls last,tf0.created_at desc nulls last,
        tf0.updated_at desc nulls last,tf0.id desc
      limit 1
    ) tf on true
    left join lateral (
      select cs0.week_ending_weekday
      from public.client_settings cs0
      where cs0.client_id=coalesce(vs.client_id,tf.client_id,ct.client_id)
        and cs0.effective_from<=coalesce(
          (t.worked_start_iso at time zone 'Europe/London')::date,
          t.week_ending_date,v_now::date)
      order by cs0.effective_from desc
      limit 1
    ) cs on true
    cross join public.settings_defaults sd
    where sd.id=1
  ),
  timesheet_number_fnv(
    invoice_id,timesheet_id,source_text,character_no,fnv_hash
  ) as (
    select b.invoice_id,b.timesheet_id,b.timesheet_id::text,1::integer,
      2166136261::bigint
    from timesheet_base b
    union all
    select h.invoice_id,h.timesheet_id,h.source_text,h.character_no+1,
      mod(
        ((h.fnv_hash # ascii(substr(
          h.source_text,h.character_no,1))::bigint)*16777619::bigint),
        4294967296::bigint)
    from timesheet_number_fnv h
    where h.character_no<=length(h.source_text)
  ),
  timesheet_week_context as materialized (
    select b.*,
      coalesce(b.week_ending_date,
        (b.worked_start_iso at time zone 'Europe/London')::date+
          ((b.configured_week_ending_weekday-
            extract(dow from (b.worked_start_iso at time zone
              'Europe/London')::date)::integer+7)%7)) resolved_week_ending_date
    from timesheet_base b
  ),
  timesheet_schedule_source as materialized (
    select b.invoice_id,b.timesheet_id,s.ordinality::integer source_order,s.value row_json
    from timesheet_week_context b
    cross join lateral jsonb_array_elements(
      case
        when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
          then b.invoice_breakdown_json->'segments'
        when jsonb_typeof(b.actual_schedule_json)='array'
          then b.actual_schedule_json
        else '[]'::jsonb
      end) with ordinality s(value,ordinality)
    union all
    select b.invoice_id,b.timesheet_id,1,jsonb_build_object(
      'date',(b.worked_start_iso at time zone 'Europe/London')::date,
      'start_utc',b.worked_start_iso,'end_utc',b.worked_end_iso,
      'break_start',case when b.break_start_iso is not null
        then to_char(b.break_start_iso at time zone 'Europe/London','HH24:MI') end,
      'break_end',case when b.break_end_iso is not null
        then to_char(b.break_end_iso at time zone 'Europe/London','HH24:MI') end,
      'break_minutes',b.break_minutes,'ref_num',b.reference_number)
    from timesheet_week_context b
    where b.sheet_scope='DAILY'
      and not exists(
        select 1 from jsonb_array_elements(
          case
            when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
              and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
              then b.invoice_breakdown_json->'segments'
            when jsonb_typeof(b.actual_schedule_json)='array'
              then b.actual_schedule_json
            else '[]'::jsonb
          end) existing)
  ),
  timesheet_schedule_normalised as materialized (
    select s.*,b.resolved_week_ending_date,b.reference_required,
      coalesce(nullif(btrim(s.row_json->>'segment_id'),''),
        case when nullif(btrim(s.row_json->>'start_utc'),'') is not null
          and nullif(btrim(s.row_json->>'end_utc'),'') is not null
          then 'SE:'||(s.row_json->>'start_utc')||'|'||
            (s.row_json->>'end_utc') end,
        'ts:'||s.timesheet_id::text||':'||(s.source_order-1)::text) segment_id,
      coalesce(nullif(btrim(s.row_json->>'date'),''),
        nullif(btrim(s.row_json->>'day'),''),
        case when pg_input_is_valid(nullif(coalesce(
            s.row_json->>'worked_start',s.row_json->>'start_utc'),''),
            'timestamptz')
          then (coalesce(s.row_json->>'worked_start',
            s.row_json->>'start_utc')::timestamptz at time zone
              'Europe/London')::date::text end,
        case when b.sheet_scope='DAILY'
          then (b.worked_start_iso at time zone 'Europe/London')::date::text end)
        work_date,
      coalesce(nullif(btrim(s.row_json->>'worked_start'),''),
        nullif(btrim(s.row_json->>'start_utc'),''),
        nullif(btrim(s.row_json->>'start'),'')) worked_start,
      coalesce(nullif(btrim(s.row_json->>'worked_end'),''),
        nullif(btrim(s.row_json->>'end_utc'),''),
        nullif(btrim(s.row_json->>'end'),'')) worked_end,
      case
        when nullif(btrim(s.row_json->>'break_start'),'') is not null
          and nullif(btrim(s.row_json->>'break_end'),'') is not null
          then 'EXPLICIT_INTERVAL'
        when coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
          and coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins')::integer>0
          then 'MINUTES_ONLY'
        else 'NONE' end break_display_mode,
      case when coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
        then coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins')::integer else 0 end break_minutes,
      coalesce(nullif(btrim(s.row_json->>'ref_num'),''),
        nullif(btrim(s.row_json->>'reference'),'')) source_reference
    from timesheet_schedule_source s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_schedule_rows as materialized (
    select s.invoice_id,s.timesheet_id,s.source_order,s.segment_id,s.work_date,
      jsonb_build_object(
        'row_key',s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
          coalesce(s.work_date,''),
        'display_order',row_number() over(
          partition by s.invoice_id,s.timesheet_id,s.work_date
          order by
            case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              then s.worked_start::timestamptz end nulls last,
            s.worked_start,s.segment_id,s.source_order),
        'segment_id',s.segment_id,
        'date',s.work_date,
        'worked_start_utc',case when pg_input_is_valid(
          nullif(s.worked_start,''),'timestamptz')
          then s.worked_start::timestamptz end,
        'worked_end_utc',case when pg_input_is_valid(
          nullif(s.worked_end,''),'timestamptz')
          then s.worked_end::timestamptz end,
        'display_start_local',case
          when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
            then to_char(s.worked_start::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_start~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_start,5)
          end,
        'display_end_local',case
          when pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then to_char(s.worked_end::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_end~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_end,5)
          end,
        'break_start_local',nullif(btrim(s.row_json->>'break_start'),''),
        'break_end_local',nullif(btrim(s.row_json->>'break_end'),''),
        'break_minutes',s.break_minutes,
        'break_display_mode',s.break_display_mode,
        'bucket_hours',jsonb_build_object(
          'DAY',coalesce(s.row_json->'hours_day','0'::jsonb),
          'NIGHT',coalesce(s.row_json->'hours_night','0'::jsonb),
          'SATURDAY',coalesce(s.row_json->'hours_sat','0'::jsonb),
          'SUNDAY',coalesce(s.row_json->'hours_sun','0'::jsonb),
          'BANK_HOLIDAY',coalesce(s.row_json->'hours_bh','0'::jsonb)),
        'paid_minutes',coalesce(
          case when (select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
            from(values(s.row_json->>'hours_day'),
              (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
              (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v))>0
            then round(60*(select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
              from(values(s.row_json->>'hours_day'),
                (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
                (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v)))::integer
          end,
          case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              and pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then greatest(0,round(extract(epoch from(
              s.worked_end::timestamptz-s.worked_start::timestamptz))/60)
                -s.break_minutes)::integer end,
          case when coalesce(s.row_json->>'hours',
              s.row_json->>'units','')~
                '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            then round(coalesce(s.row_json->>'hours',
              s.row_json->>'units')::numeric*60)::integer end),
        'band',b.band,
        'booking_reference',coalesce(
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          s.source_reference,
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          case when jsonb_typeof(b.day_references_json)='object'
            then coalesce(
              b.day_references_json#>>array[s.work_date,'reference'],
              b.day_references_json#>>array[s.work_date,'ref_num'],
              b.day_references_json->>s.work_date) end,
          nullif(b.reference_number,'')),
        'reference_required',b.reference_required,
        'reference_source',case
          when exists(select 1 from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null) then 'SEGMENT'
          when nullif(s.source_reference,'') is not null then 'SEGMENT_SOURCE'
          when exists(select 1 from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null) then 'DAY'
          when nullif(b.reference_number,'') is not null then 'TIMESHEET'
          else 'NONE' end,
        'reference_row_key',coalesce(
          (select rs.row_key from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id order by rs.row_key limit 1),
          s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
            coalesce(s.work_date,'')))
        shift_model
    from timesheet_schedule_normalised s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_current_additional_rows as materialized (
    select b.invoice_id,b.timesheet_id,d.code,d.unit_date,d.quantity
    from timesheet_week_context b
    cross join lateral (
      select upper(day_unit.key) code,day_value.key unit_date,
        (day_value.value#>>'{}')::numeric quantity
      from jsonb_each(case
        when jsonb_typeof(b.additional_units_per_day)='object'
          then b.additional_units_per_day else '{}'::jsonb end) day_unit(key,value)
      cross join lateral jsonb_each(case
        when jsonb_typeof(day_unit.value)='object'
          then day_unit.value else '{}'::jsonb end) day_value(key,value)
      where coalesce(day_value.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        and (day_value.value#>>'{}')::numeric<>0
      union all
      select upper(week_unit.key),null::text,
        (week_unit.value#>>'{}')::numeric
      from jsonb_each(case
        when jsonb_typeof(b.additional_units_week)='object'
          then b.additional_units_week else '{}'::jsonb end) week_unit(key,value)
      where coalesce(week_unit.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        and (week_unit.value#>>'{}')::numeric<>0
        and not exists(
          select 1
          from jsonb_each(case
            when jsonb_typeof(b.additional_units_per_day)='object'
              then b.additional_units_per_day else '{}'::jsonb end) per_day(code,value)
          cross join lateral jsonb_each(case
            when jsonb_typeof(per_day.value)='object'
              then per_day.value else '{}'::jsonb end) per_value(day,value)
          where upper(per_day.code)=upper(week_unit.key)
            and coalesce(per_value.value#>>'{}','')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            and (per_value.value#>>'{}')::numeric<>0)
    ) d
  ),
  timesheet_additional_rows as materialized (
    select b.invoice_id,b.timesheet_id,a.key code,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) rate_type,
      nullif(d.key,'') unit_date,
      case
        when d.key is not null and coalesce(d.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(d.value#>>'{}')::numeric
        when d.key is null and coalesce(a.value->>'unit_count','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(a.value->>'unit_count')::numeric
      end quantity,
      coalesce(nullif(a.value->>'unit_name',''),'unit') unit_name,
      case when d.key is null then 'WEEKLY' else 'PER_DAY' end frequency,
      case when coalesce(a.value->>'configured_display_order',
          a.value->>'display_order','')~'^[0-9]{1,9}$'
        then coalesce(a.value->>'configured_display_order',
          a.value->>'display_order')::integer else 2147483647 end configured_order
    from timesheet_week_context b
    cross join lateral jsonb_each(case
      when jsonb_typeof(b.additional_units_json)='object'
        then b.additional_units_json else '{}'::jsonb end) a(key,value)
    left join lateral jsonb_each(case
      when jsonb_typeof(a.value->'days')='object' and a.value->'days'<>'{}'::jsonb
        then a.value->'days' else '{}'::jsonb end) d(key,value) on true
    where jsonb_typeof(a.value)='object'
      and case
        when d.key is not null and coalesce(d.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(d.value#>>'{}')::numeric<>0
        when d.key is null and coalesce(a.value->>'unit_count','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(a.value->>'unit_count')::numeric<>0
        else false end
  ),
  timesheet_additional_staleness as materialized (
    select b.invoice_id,b.timesheet_id,
      exists(
        (select upper(c.code),c.unit_date,trim_scale(c.quantity)
         from timesheet_current_additional_rows c
         where c.invoice_id is not distinct from b.invoice_id
           and c.timesheet_id=b.timesheet_id
         except
         select upper(a.code),a.unit_date,trim_scale(a.quantity)
         from timesheet_additional_rows a
         where a.invoice_id is not distinct from b.invoice_id
           and a.timesheet_id=b.timesheet_id)
        union all
        (select upper(a.code),a.unit_date,trim_scale(a.quantity)
         from timesheet_additional_rows a
         where a.invoice_id is not distinct from b.invoice_id
           and a.timesheet_id=b.timesheet_id
         except
         select upper(c.code),c.unit_date,trim_scale(c.quantity)
         from timesheet_current_additional_rows c
         where c.invoice_id is not distinct from b.invoice_id
           and c.timesheet_id=b.timesheet_id)
      ) snapshot_stale
    from timesheet_week_context b
  ),
  timesheet_v2_models as materialized (
    select b.invoice_id,b.timesheet_id,
      jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V2',
        'template_version','timesheet-professional-v2',
        'layout_contract_version','TIMESHEET_ONE_PAGE_LANDSCAPE_V2',
        'timesheet_id',b.timesheet_id,
        'document_revision',b.document_revision,
        'timesheet_number',coalesce((
          select lpad((h.fnv_hash%100000000)::text,8,'0')
          from timesheet_number_fnv h
          where h.invoice_id is not distinct from b.invoice_id
            and h.timesheet_id=b.timesheet_id
            and h.character_no=length(h.source_text)+1
          limit 1),'00000000'),
        'sheet_scope',b.sheet_scope,
        'form_variant',case
          when b.submission_mode='MANUAL' and upper(coalesce(b.qr_status,''))='PENDING'
            then 'QR_UNSIGNED'
          when b.submission_mode='ELECTRONIC'
            and b.authorised_at_server is not null
            and nullif(b.r2_nurse_key,'') is not null
            and nullif(b.r2_auth_key,'') is not null
            then 'ELECTRONIC_SIGNED'
          else 'ELECTRONIC_UNSIGNED' end,
        'submission_mode',b.submission_mode,
        'locale','en-GB','time_zone','Europe/London',
        'week_period',jsonb_build_object(
          'start_date',b.resolved_week_ending_date-6,
          'end_date',b.resolved_week_ending_date,
          'end_weekday_index',extract(dow from b.resolved_week_ending_date)::integer,
          'end_weekday_name',trim(to_char(b.resolved_week_ending_date,'Day')),
          'start_weekday_name',trim(to_char(b.resolved_week_ending_date-6,'Day')),
          'source',case when b.week_ending_date is not null
            then 'TIMESHEET_WEEK_ENDING_DATE'
            when b.contract_id is not null then 'CONTRACT_WEEK_ENDING_WEEKDAY_SNAPSHOT'
            else 'CLIENT_SETTING' end,
          'configured_week_ending_weekday',b.configured_week_ending_weekday,
          'days',(select jsonb_agg(jsonb_build_object(
            'row_key','day:'||d.day_date::text,
            'display_order',d.display_order,
            'date',d.day_date,
            'weekday_index',extract(dow from d.day_date)::integer,
            'weekday_name',trim(to_char(d.day_date,'Day')),
            'weekday_abbreviation',trim(to_char(d.day_date,'Dy')),
            'shift_lines',coalesce((select jsonb_agg(r.shift_model order by
              (r.shift_model->>'display_order')::integer,r.source_order)
              from timesheet_schedule_rows r
              where r.invoice_id is not distinct from b.invoice_id
                and r.timesheet_id=b.timesheet_id
                and r.work_date=d.day_date::text),'[]'::jsonb))
            order by d.display_order)
            from(select (b.resolved_week_ending_date-7+g)::date day_date,
                g::integer display_order
              from generate_series(1,7) g) d)),
        'worker',jsonb_build_object(
          'first_name',b.candidate_first_name,
          'surname',b.candidate_surname,
          'job_profile_title',b.job_profile_title),
        'client',jsonb_build_object(
          'name',b.client_name,
          'hospital_norm',b.hospital_norm,
          'ward_norm',b.ward_norm,
          'hospital',b.hospital,
          'hospital_display',b.hospital,
          'ward_display',b.ward_display,
          'site_ward',b.site_ward,
          'hospital_ward_display',b.site_ward),
        'band',b.band,
        'branding',jsonb_build_object(
          'agency_name',coalesce(nullif(b.agency_name,''),'ARMS'),
          'logo',b.logo_identity),
        'wording',jsonb_build_object(
          'header',b.header_wording,'footer',b.footer_wording,
          'temporary_worker_declaration',b.temporary_worker_declaration,
          'client_declaration',b.client_declaration),
        'presentation_settings_hash',encode(digest(jsonb_build_object(
          'agency_name',b.agency_name,'logo',b.logo_identity,
          'header',b.header_wording,'footer',b.footer_wording,
          'temporary_worker_declaration',b.temporary_worker_declaration,
          'client_declaration',b.client_declaration)::text,'sha256'),'hex'),
        'additional_units_section',jsonb_build_object(
          'schema_version','TIMESHEET_ADDITIONAL_UNITS_V1',
          'visible',exists(select 1 from timesheet_additional_rows a
            where a.invoice_id is not distinct from b.invoice_id
              and a.timesheet_id=b.timesheet_id),
          'title','Additional rates / units',
          'column_labels',jsonb_build_object(
            'rate_type','Rate Type','date','Date',
            'quantity','Quantity','unit','Unit'),
          'minimum_blank_space_rows',1,
          'rows',coalesce((select jsonb_agg(jsonb_build_object(
            'row_key','additional:'||a.code||':'||coalesce(a.unit_date,'weekly'),
            'display_order',a.display_order,'code',a.code,
            'rate_type',a.rate_type,'date',a.unit_date,
            'quantity',trim_scale(a.quantity),'unit',a.unit_name,
            'frequency',a.frequency) order by a.display_order)
            from(select a0.*,row_number() over(order by a0.configured_order,
                a0.code,a0.unit_date nulls last)::integer display_order
              from timesheet_additional_rows a0
              where a0.invoice_id is not distinct from b.invoice_id
                and a0.timesheet_id=b.timesheet_id) a),'[]'::jsonb)),
        'additional_units_snapshot_stale',coalesce((
          select s.snapshot_stale
          from timesheet_additional_staleness s
          where s.invoice_id is not distinct from b.invoice_id
            and s.timesheet_id=b.timesheet_id),false),
        'totals',jsonb_build_object(
          'paid_minutes',coalesce((select sum(
            (r.shift_model->>'paid_minutes')::numeric)
            from timesheet_schedule_rows r
            where r.invoice_id is not distinct from b.invoice_id
              and r.timesheet_id=b.timesheet_id),0)),
        'authorisation',jsonb_build_object(
          'authorised',b.authorised_at_server is not null,
          'name',b.auth_name,'role',b.auth_job_title,
          'authorised_at_utc',b.authorised_at_server),
        'signatures',jsonb_build_object(
          'candidate',case when nullif(b.r2_nurse_key,'') is null then '{}'::jsonb
            else jsonb_build_object('r2_key',b.r2_nurse_key,
              'sha256',lower(b.img_sha256_nurse),'size_bytes',null,
              'media_type','image/png',
              'signed_date',b.authorised_at_server::date) end,
          'authoriser',case when nullif(b.r2_auth_key,'') is null then '{}'::jsonb
            else jsonb_build_object('r2_key',b.r2_auth_key,
              'sha256',lower(b.img_sha256_auth),'size_bytes',null,
              'media_type','image/png',
              'signed_date',b.authorised_at_server::date) end),
        'qr',jsonb_build_object(
          'required',b.submission_mode='MANUAL'
            and upper(coalesce(b.qr_status,''))='PENDING',
          'signed',b.qr_signed_hash is not null,
          'status',b.qr_status,'token',b.qr_token,
          'payload',case when jsonb_typeof(b.qr_payload_json)='object'
            then b.qr_payload_json else '{}'::jsonb end,
          'signed_hash',b.qr_signed_hash,'signed_at_utc',b.qr_signed_at_utc),
        'layout',jsonb_build_object(
          'one_page_required',true,
          'allowed_modes',jsonb_build_array('NORMAL','COMPACT','ULTRA'),
          'second_page_allowed',false,
          'minimum_font_size',5.5,
          'minimum_row_height_mm',3.45,
          'minimum_signature_height_mm',7,
          'minimum_additional_blank_rows',1),
        'week_period_hash',encode(digest(jsonb_build_object(
          'start_date',b.resolved_week_ending_date-6,
          'end_date',b.resolved_week_ending_date,
          'configured_week_ending_weekday',
            b.configured_week_ending_weekday)::text,'sha256'),'hex'),
        'reference_signature',encode(digest(coalesce((
          select string_agg((r.shift_model->>'reference_row_key')||'='||
            coalesce(r.shift_model->>'booking_reference',''),'||'
            order by r.work_date,(r.shift_model->>'display_order')::integer)
          from timesheet_schedule_rows r
          where r.invoice_id is not distinct from b.invoice_id
            and r.timesheet_id=b.timesheet_id),'') ,'sha256'),'hex'),
        'additional_units_hash',encode(digest(coalesce((
          select jsonb_agg(jsonb_build_object(
            'code',a.code,'date',a.unit_date,'quantity',a.quantity,
            'unit',a.unit_name) order by a.configured_order,a.code,
              a.unit_date nulls last)::text
          from timesheet_additional_rows a
          where a.invoice_id is not distinct from b.invoice_id
            and a.timesheet_id=b.timesheet_id),'[]'),'sha256'),'hex')
      ) render_model
    from timesheet_week_context b
  ),
  invoice_timesheet_rows as materialized (
    select il.invoice_id,t.timesheet_id,
      coalesce(v2.render_model,jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V1',
        'timesheet_id',t.timesheet_id,
        'document_revision',t.document_revision,
        'candidate',jsonb_build_object('id',coalesce(vs.candidate_id::text,null),'name',coalesce(vs.candidate_name,t.occupant_key_norm)),
        'client',jsonb_build_object('id',coalesce(vs.client_id::text,null),'name',vs.client_name),
        'contract',jsonb_build_object('id',coalesce(t.contract_id::text,null),'reference',t.booking_id),
        'work',jsonb_build_object(
          'hospital',t.hospital_norm,
          'site',t.hospital_norm,
          'ward',t.ward_norm,
          'assignment',coalesce(
            nullif(btrim(t.job_title_norm),''),
            case when nullif(btrim(t.shift_label_norm),'') is not null
                   and length(t.shift_label_norm) <= 80
                   and t.shift_label_norm !~* '^weekly-correction-'
                   and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
              then t.shift_label_norm end),
          'job_title',t.job_title_norm,
          'band',t.band,
          'shift_type',case when nullif(btrim(t.shift_label_norm),'') is not null
                              and length(t.shift_label_norm) <= 80
                              and t.shift_label_norm !~* '^weekly-correction-'
                              and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
                         then t.shift_label_norm end),
        'week_ending_date',t.week_ending_date,
        'submission_mode',t.submission_mode::text,
        'sheet_scope',t.sheet_scope::text,
        'daily_schedule_rows',coalesce((
           select jsonb_agg(jsonb_build_object(
             'date',coalesce(s.value->>'date',s.value->>'day',to_char(t.worked_start_iso::date,'YYYY-MM-DD')),
             'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc',t.scheduled_start_iso::text),
             'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc',t.scheduled_end_iso::text),
             'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc',t.worked_start_iso::text),
             'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc',t.worked_end_iso::text),
             'break_start',coalesce(s.value->>'break_start',t.break_start_iso::text),
             'break_end',coalesce(s.value->>'break_end',t.break_end_iso::text),
             'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then (coalesce(s.value->>'break_minutes',s.value->>'break_mins'))::integer else coalesce(t.break_minutes,0) end,
             'reference',coalesce(s.value->>'reference',s.value->>'ref_num',t.reference_number),
             'hours',coalesce(s.value->>'hours',s.value->>'units',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end),
             'units',coalesce(s.value->>'units',s.value->>'hours'),
             'display_order',s.ordinality)
             order by s.ordinality)
           from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality)
           where upper(coalesce(t.sheet_scope::text,''))='DAILY'
        ), case when upper(coalesce(t.sheet_scope::text,''))='DAILY' then jsonb_build_array(jsonb_build_object(
             'date',t.worked_start_iso::date,'scheduled_start',t.scheduled_start_iso,'scheduled_end',t.scheduled_end_iso,
             'worked_start',t.worked_start_iso,'worked_end',t.worked_end_iso,
             'break_start',t.break_start_iso,'break_end',t.break_end_iso,'break_minutes',coalesce(t.break_minutes,0),
             'reference',t.reference_number,'hours',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end,'units',null,'display_order',1)) else '[]'::jsonb end),
        'weekly_schedule_rows',coalesce((
           select jsonb_agg(jsonb_build_object(
             'date',coalesce(s.value->>'date',s.value->>'day'),
             'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc'),
             'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc'),
             'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),
             'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),
             'break_start',s.value->>'break_start','break_end',s.value->>'break_end',
             'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then (coalesce(s.value->>'break_minutes',s.value->>'break_mins'))::integer else 0 end,
             'reference',coalesce(s.value->>'reference',s.value->>'ref_num'),
             'hours',coalesce(
               s.value->>'hours',
               s.value->>'units',
               case when pg_input_is_valid(nullif(coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),''),'timestamptz')
                          and pg_input_is_valid(nullif(coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),''),'timestamptz')
                    then greatest(
                      0,
                      round((
                        extract(epoch from (
                          coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc')::timestamptz
                          - coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc')::timestamptz
                        )) / 60
                        - case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$'
                            then coalesce(s.value->>'break_minutes',s.value->>'break_mins')::numeric else 0 end
                      ) / 60,2)
                    )::text end),
             'units',coalesce(s.value->>'units',s.value->>'hours'),
             'display_order',s.ordinality)
             order by s.ordinality)
           from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality)
           where upper(coalesce(t.sheet_scope::text,''))='WEEKLY'
        ),'[]'::jsonb),
        'references',jsonb_build_object(
          'whole',coalesce((select rs.current_reference from reference_scope rs where rs.invoice_id=il.invoice_id and rs.timesheet_id=t.timesheet_id and rs.segment_id is null and rs.day_ymd is null and nullif(rs.current_reference,'') is not null order by rs.row_key limit 1),nullif(t.reference_number,'')),
          'day',coalesce(
             (
               select jsonb_agg(
                 jsonb_build_object(
                   'day_key',ordered_reference.day_ymd,
                   'reference',ordered_reference.current_reference,
                   'display_order',ordered_reference.display_order
                 )
                 order by ordered_reference.display_order
               )
               from (
                 select
                   rs.day_ymd,
                   rs.current_reference,
                   row_number() over(order by rs.day_ymd,rs.row_key)::integer as display_order
                 from reference_scope rs
                 where rs.invoice_id=il.invoice_id
                   and rs.timesheet_id=t.timesheet_id
                   and rs.day_ymd is not null
                   and rs.segment_id is null
               ) ordered_reference
             ),
             (select jsonb_agg(jsonb_build_object('day_key',d.key,'reference',case when jsonb_typeof(d.value)='object' then coalesce(d.value->>'reference',d.value->>'ref_num',d.value->>'value') else trim(both '"' from d.value::text) end,'display_order',d.ordinality) order by d.ordinality) from jsonb_each(case when jsonb_typeof(t.day_references_json)='object' then t.day_references_json else '{}'::jsonb end) with ordinality d(key,value,ordinality)),
             '[]'::jsonb),
          'segment',coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'segment_id',ordered_reference.segment_id,
                  'reference',ordered_reference.current_reference,
                  'display_order',ordered_reference.display_order
                )
                order by ordered_reference.display_order
              )
              from (
                select
                  rs.segment_id,
                  rs.current_reference,
                  row_number() over(order by rs.segment_id,rs.row_key)::integer as display_order
                from reference_scope rs
                where rs.invoice_id=il.invoice_id
                  and rs.timesheet_id=t.timesheet_id
                  and rs.segment_id is not null
              ) ordered_reference
            ),
            '[]'::jsonb
          )),
        'additional_units',coalesce((
          select jsonb_object_agg(
            au.key,
            case
              when jsonb_typeof(au.value)='number'
                then to_jsonb(trim_scale((au.value#>>'{}')::numeric)::text)
              else au.value
            end
            order by au.key
          )
          from jsonb_each(
            case when jsonb_typeof(t.additional_units_week)='object'
              then t.additional_units_week else '{}'::jsonb end
          ) au
        ),'{}'::jsonb),
        'authorisation',jsonb_build_object('authorised',t.authorised_at_server is not null,'name',t.auth_name,'role',t.auth_job_title,'authorised_at_utc',t.authorised_at_server),
        'signatures',jsonb_build_object(
          'candidate',case when nullif(t.r2_nurse_key,'') is null
            then jsonb_build_object('identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse')
            else jsonb_build_object('r2_key',t.r2_nurse_key,'sha256',t.img_sha256_nurse,'size_bytes',null,'media_type','image/png','identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse') end,
          'authoriser',case when nullif(t.r2_auth_key,'') is null
            then jsonb_build_object('identity',t.auth_name,'role',t.auth_job_title)
            else jsonb_build_object('r2_key',t.r2_auth_key,'sha256',t.img_sha256_auth,'size_bytes',null,'media_type','image/png','identity',t.auth_name,'role',t.auth_job_title) end),
        'qr',jsonb_build_object('required',t.qr_status is not null,'signed',t.qr_signed_hash is not null,'status',t.qr_status::text,'signed_hash',t.qr_signed_hash,'signed_at_utc',t.qr_signed_at_utc,'verification_summary',case when t.qr_signed_hash is not null then 'QR signature verified in frozen source' when t.qr_status is not null then t.qr_status::text else null end),
        'template_version','timesheet-professional-v1'
      )) render_model,
      t.submission_mode::text submission_mode,t.document_revision,t.manual_document_asset_id,
      coalesce(vs.client_is_nhsp,false) client_is_nhsp,
      coalesce(vs.client_no_timesheet_required,false) no_timesheet_required,
      coalesce(pc.effective_ts_attach_to_invoice,true) attach_timesheet
    from (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in(select invoice_id from requested_invoices)
        and il.timesheet_id is not null
    ) il
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join timesheet_v2_models v2
      on v2.invoice_id=il.invoice_id and v2.timesheet_id=t.timesheet_id
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
  ),
  invoice_timesheets_agg as materialized (
    select invoice_id,jsonb_agg(jsonb_build_object(
      'timesheet_id',timesheet_id,'submission_mode',submission_mode,'document_revision',document_revision,
      'manual_document_asset_id',manual_document_asset_id,'client_is_nhsp',client_is_nhsp,
      'no_timesheet_required',no_timesheet_required,'attach_timesheet',attach_timesheet,
      'render_model',render_model) order by timesheet_id) timesheet_sources
    from invoice_timesheet_rows group by invoice_id
  ),
  support_agg as materialized (
    select source_group.invoice_id,
      jsonb_agg(jsonb_build_object(
        'source_system',source_group.source_system,
        'import_id',(
          select s.import_id
          from public.invoice_hr_source_rows s
          where s.invoice_id=source_group.invoice_id
            and upper(s.source_system)=upper(source_group.source_system)
          order by s.import_id
          limit 1
        ),
        'render_model',jsonb_build_object(
          'schema_version',case when upper(source_group.source_system)='NHSP'
            then 'NHSP_PRESENTATION_V1' else 'HEALTHROSTER_PRESENTATION_V2' end,
          'rows',coalesce((select jsonb_agg(
            case when upper(source_group.source_system)='NHSP' then jsonb_build_object(
              'evidence_role',coalesce(
                nullif(btrim(r.value->>'evidence_role'),''),
                case
                  when upper(coalesce(
                    r.value->>'reversal_state',r.value->>'status',''))
                    in ('REVERSED','REVERSAL')
                  then 'NHSP Reversal'
                  else 'NHSP Shift'
                end),
              'worker',coalesce(
                r.value->>'worker',r.value->>'candidate',r.value->>'name',
                r.value->>'worker_name',r.value->>'staff_name'),
              'nhsp_shift_id',coalesce(
                r.value->>'nhsp_shift_id',r.value->>'shift_id',
                r.value->>'assignment_code',r.value->>'assignment'),
              'booking_reference',coalesce(
                r.value->>'booking_reference',r.value->>'reference',
                r.value->>'ref_num',r.value->>'assignment_code'),
              'site_ward',concat_ws(' / ',
                nullif(coalesce(
                  r.value->>'site',r.value->>'hospital',
                  r.value->>'trust',r.value->>'client'),''),
                nullif(r.value->>'ward','')),
              'shift_date',coalesce(
                r.value->>'shift_date',r.value->>'date',
                r.value->>'work_date',r.value->>'date_raw'),
              'shift_times',coalesce(
                r.value->>'shift_times',
                concat_ws(' - ',
                  nullif(coalesce(r.value->>'start',r.value->>'start_local'),''),
                  nullif(coalesce(r.value->>'end',r.value->>'end_local'),''))),
              'hours_units',coalesce(
                r.value->>'hours_units',r.value->>'hours',
                r.value->>'units',r.value->>'hours_worked',
                case
                  when coalesce(r.value->>'start_local','')
                         ~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
                   and coalesce(r.value->>'end_local','')
                         ~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
                   and coalesce(r.value->>'break_mins','0')
                         ~ '^[0-9]+([.][0-9]+)?$'
                  then trim(to_char(round((
                    extract(epoch from (
                      case
                        when (r.value->>'end_local')::time
                               >= (r.value->>'start_local')::time
                          then (r.value->>'end_local')::time
                               - (r.value->>'start_local')::time
                        else (r.value->>'end_local')::time
                               + interval '24 hours'
                               - (r.value->>'start_local')::time
                      end
                    )) / 3600
                    - (coalesce(r.value->>'break_mins','0')::numeric / 60)
                  )::numeric,2),'FM999999990.00'))
                end),
              'commission_amount',coalesce(
                r.value->>'commission_amount',r.value->>'commission',
                (select r.value->'raw_columns'->>((h.ordinality-1)::integer)
                 from jsonb_array_elements_text(
                   case when jsonb_typeof(s.header_columns)='array'
                     then s.header_columns else '[]'::jsonb end
                 ) with ordinality h(header_name,ordinality)
                 where lower(btrim(h.header_name))='commission'
                 order by h.ordinality
                 limit 1)),
              'total_amount',coalesce(
                r.value->>'total_amount',r.value->>'total_cost',
                (select r.value->'raw_columns'->>((h.ordinality-1)::integer)
                 from jsonb_array_elements_text(
                   case when jsonb_typeof(s.header_columns)='array'
                     then s.header_columns else '[]'::jsonb end
                 ) with ordinality h(header_name,ordinality)
                 where lower(btrim(h.header_name)) in ('total cost','total amount')
                 order by case when lower(btrim(h.header_name))='total cost'
                   then 0 else 1 end,h.ordinality
                 limit 1)),
              'source_identity',concat_ws(' · ',
                upper(coalesce(s.source_system,'NHSP')),
                'import row '||r.ordinality::text),
              'validation_state',coalesce(
                r.value->>'validation_state',r.value->>'status','Included'),
              'reversal_state',case
                when upper(coalesce(r.value->>'reversal_state',r.value->>'status','')) in ('REVERSED','REVERSAL')
                  or coalesce(
                    r.value->>'hours_units',r.value->>'hours',
                    r.value->>'units',r.value->>'hours_worked','') ~ '^-[0-9]'
                then 'REVERSED' else null end)
            else jsonb_build_object(
              'evidence_role',coalesce(
                nullif(btrim(r.value->>'evidence_role'),''),
                case
                  when upper(coalesce(
                    r.value->>'reversal_state',r.value->>'status',''))
                    in ('REVERSED','REVERSAL')
                  then 'HealthRoster Reversal'
                  else 'HealthRoster Shift'
                end),
              'worker',coalesce(
                r.value->>'worker',r.value->>'candidate',r.value->>'name',
                r.value->>'worker_name',r.value->>'staff_name'),
              'assignment',coalesce(
                r.value->>'assignment',r.value->>'role',
                r.value->>'job_title',r.value->>'assignment_code'),
              'shift_date',coalesce(
                r.value->>'shift_date',r.value->>'date',
                r.value->>'work_date',r.value->>'date_raw'),
              'shift_times',coalesce(
                r.value->>'shift_times',
                concat_ws(' - ',
                  nullif(coalesce(r.value->>'start',r.value->>'start_local'),''),
                  nullif(coalesce(r.value->>'end',r.value->>'end_local'),''))),
              'site',coalesce(
                r.value->>'site',r.value->>'hospital',
                r.value->>'trust',r.value->>'client'),
              'ward',r.value->>'ward',
              'booking_reference',case
                when coalesce(hr_match.reference_match_count,0)=1
                  then hr_match.ref_num
                else null end,
              'units_hours',coalesce(
                r.value->>'units_hours',r.value->>'hours',
                r.value->>'units',r.value->>'hours_worked'),
              'validation_state',coalesce(
                r.value->>'validation_state',r.value->>'status','Included'),
              'source_identity',concat_ws(' · ',
                upper(coalesce(s.source_system,'HEALTHROSTER')),
                'import row '||r.ordinality::text),
              'reference_match_state',case
                when coalesce(hr_match.reference_match_count,0)>1
                  then 'AMBIGUOUS'
                when coalesce(hr_match.reference_match_count,0)=0
                  then 'MISSING'
                when hr_match.match_priority=1
                  then 'EXACT_IMPORT_EXTERNAL_ROW'
                when hr_match.match_priority=2
                  then 'EXACT_IMPORT_REQUEST_ID'
                else 'CONTROLLED_UNIQUE_FALLBACK' end,
              'reference_match_count',coalesce(hr_match.reference_match_count,0),
              'reference_source','HEALTHROSTER_REF_NUM',
              'external_row_key',coalesce(
                hr_match.external_row_key,
                r.value->>'external_row_key',r.value->>'row_key',
                r.value->>'request_id',r.value->>'requestId'),
              'source_record_id',coalesce(
                hr_match.shift_id::text,r.value->>'unique_id'),
              'reversal_state',case
                when upper(coalesce(r.value->>'reversal_state',r.value->>'status','')) in ('REVERSED','REVERSAL')
                  or coalesce(
                    r.value->>'units_hours',r.value->>'hours',
                    r.value->>'units',r.value->>'hours_worked','') ~ '^-[0-9]'
                then 'REVERSED' else null end) end
            order by
              coalesce(
                r.value->>'shift_date',r.value->>'date',
                r.value->>'work_date',r.value->>'date_raw',''),
              coalesce(
                r.value->>'start',r.value->>'worked_start',
                r.value->>'start_local',''),
              s.import_id,
              r.ordinality)
            from public.invoice_hr_source_rows s
            cross join lateral jsonb_array_elements(
              case when jsonb_typeof(s.rows_json)='array' then s.rows_json else '[]'::jsonb end
            ) with ordinality r(value,ordinality)
            left join lateral (
              select
                min(ranked.match_priority) match_priority,
                count(*)::integer reference_match_count,
                case when count(*)=1 then min(ranked.ref_num) end ref_num,
                case when count(*)=1 then min(ranked.external_row_key) end external_row_key,
                case when count(*)=1 then min(ranked.shift_id::text)::uuid end shift_id
              from (
                select candidates.*,
                  min(candidates.match_priority) over () winning_priority
                from (
                  select ns.ref_num,ns.external_row_key,ns.id shift_id,1 match_priority
                  from public.nhsp_shifts ns
                  where upper(ns.source_system::text)=upper(s.source_system)
                    and ns.latest_import_id=s.import_id
                    and nullif(btrim(coalesce(
                      r.value->>'external_row_key',r.value->>'row_key','')),'') is not null
                    and ns.external_row_key=coalesce(
                      r.value->>'external_row_key',r.value->>'row_key')
                  union all
                  select ns.ref_num,ns.external_row_key,ns.id shift_id,2 match_priority
                  from public.nhsp_shifts ns
                  where upper(ns.source_system::text)=upper(s.source_system)
                    and ns.latest_import_id=s.import_id
                    and nullif(btrim(coalesce(
                      r.value->>'request_id',r.value->>'requestId','')),'') is not null
                    and ns.hr_request_id=coalesce(
                      r.value->>'request_id',r.value->>'requestId')
                  union all
                  select ns.ref_num,ns.external_row_key,ns.id shift_id,3 match_priority
                  from public.nhsp_shifts ns
                  where upper(ns.source_system::text)=upper(s.source_system)
                    and coalesce(r.value->>'work_date',r.value->>'date','')
                          ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                    and ns.work_date=coalesce(
                      r.value->>'work_date',r.value->>'date')::date
                    and nullif(r.value->>'start_utc','') is not null
                    and nullif(r.value->>'end_utc','') is not null
                    and ns.start_utc=(r.value->>'start_utc')::timestamptz
                    and ns.end_utc=(r.value->>'end_utc')::timestamptz
                    and (
                      nullif(r.value->>'client_id','') is null
                      or ns.client_id=(r.value->>'client_id')::uuid
                    )
                    and lower(btrim(coalesce(ns.staff_name,'')))=
                        lower(btrim(coalesce(
                          r.value->>'staff_name',r.value->>'worker_name',
                          r.value->>'worker','')))
                    and lower(btrim(coalesce(ns.ward,'')))=
                        lower(btrim(coalesce(r.value->>'ward','')))
                ) candidates
              ) ranked
              where ranked.match_priority=ranked.winning_priority
            ) hr_match on upper(s.source_system)<>'NHSP'
            where s.invoice_id=source_group.invoice_id
              and upper(s.source_system)=upper(source_group.source_system)), '[]'::jsonb),
          'source_identity',jsonb_build_object(
            'source_system',source_group.source_system,
            'import_ids',coalesce((
              select jsonb_agg(to_jsonb(import_id) order by import_id)
              from (
                select distinct s.import_id
                from public.invoice_hr_source_rows s
                where s.invoice_id=source_group.invoice_id
                  and upper(s.source_system)=upper(source_group.source_system)
              ) imports
            ),'[]'::jsonb)))
       ) order by source_group.source_system) supporting_sources
    from (
      select distinct s.invoice_id,upper(s.source_system) source_system
      from public.invoice_hr_source_rows s
      where s.invoice_id in(select invoice_id from requested_invoices)
    ) source_group
    group by source_group.invoice_id
  ),
  supporting_manifest_agg as materialized (
    select il.invoice_id,
      jsonb_agg(distinct jsonb_build_object(
        'timesheet_id',e.timesheet_id,
        'evidence_id',e.id,
        'kind',upper(coalesce(e.kind,'OTHER')),
        'display_name',coalesce(e.display_name,e.kind,'Evidence'),
        'storage_key',e.storage_key,
        'asset_id',e.document_asset_id,
        'source_kind',a.source_kind,
        'source_revision',coalesce(a.source_revision,e.source_revision,encode(digest(concat_ws('|',e.id::text,e.storage_key,e.created_at::text),'sha256'),'hex')),
        'original_r2_key',coalesce(a.original_r2_key,e.storage_key),
        'asset_sha256',a.normalised_sha256,
        'asset_manifest_hash',a.normalised_manifest_hash,
        'asset_size_bytes',a.normalised_size_bytes,
        'asset_page_count',a.normalised_page_count
      )) supporting_manifest
    from public.invoice_lines il
    join public.timesheet_evidence e on e.timesheet_id=il.timesheet_id
    left join public.invoice_document_assets a on a.id=e.document_asset_id
    where il.invoice_id in(select invoice_id from requested_invoices)
      and il.timesheet_id is not null
      and nullif(coalesce(e.storage_key,''),'') is not null
      and upper(coalesce(e.kind,''))<>'TIMESHEET'
    group by il.invoice_id
  ),
  higher_rate_agg as materialized (
    select il.invoice_id,
      jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows',
        coalesce(jsonb_agg(jsonb_build_object(
          'worker_source',coalesce(il.meta_json->>'worker',il.meta_json->>'candidate',il.booking_id),
          'shift_date',coalesce(il.meta_json->>'shift_date',il.meta_json->>'date'),
          'original_rate',il.meta_json->>'original_rate',
          'applied_rate',coalesce(il.meta_json->>'applied_rate',il.charge_day::text,il.charge_night::text,il.charge_sat::text,il.charge_sun::text,il.charge_bh::text),
          'units',coalesce(il.meta_json->>'units',il.meta_json->>'hours'),
          'display_amount',round(coalesce(il.total_charge_ex_vat,0),2)::text,
          'reason',coalesce(il.meta_json->>'reason',il.description),
          'approval_identity',il.meta_json->'approval_identity',
          'reference',coalesce(il.meta_json->>'reference',il.source_key)
        ) order by il.created_at,il.id) filter (where upper(coalesce(il.meta_json->>'line_type','') || ' ' || coalesce(il.description,'') || ' ' || coalesce(il.source_key,'')) like '%HIGHER%'), '[]'::jsonb)) higher_rate_support
    from public.invoice_lines il
    where il.invoice_id in(select invoice_id from requested_invoices)
    group by il.invoice_id
  ),
  invoice_models as materialized (
    select vr.request_no,vr.req_key request_key,
      case when vr.purpose='FINAL_ISSUE'
        then 'FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5'
        else 'INVOICE_PRESENTATION_SNAPSHOT_V5' end::text snapshot_schema_version,
      i.id invoice_id,
      jsonb_build_object(
        'schema_version','INVOICE_RENDER_MODEL_V1',
        'purpose',vr.purpose,
        'document_type',case when i.type::text='CREDIT_NOTE' then 'CREDIT_NOTE'
          when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}',i.header_snapshot_json->>'self_bill','false')) in('true','t','1','yes') then 'SELF_BILL_INVOICE'
          else 'INVOICE' end,
        'is_draft',vr.purpose<>'FINAL_ISSUE',
        'invoice_id',i.id,
        'invoice_number',i.invoice_no,
        'issue_date',case when vr.purpose='FINAL_ISSUE' then vr.issue_at_utc else i.issued_at_utc end,
        'preview_date',case when vr.purpose='DRAFT_PREVIEW' then v_now end,
        'tax_point',case
          when vr.purpose='FINAL_ISSUE' then vr.tax_point_utc::text
          else coalesce(i.header_snapshot_json->>'tax_point_utc',i.issued_at_utc::text)
        end,
        'due_date',case when vr.purpose='FINAL_ISSUE' then vr.due_at_utc else i.due_at_utc end,
        'currency',coalesce(i.header_snapshot_json->>'currency','GBP'),
        'supplier',jsonb_build_object(
          'legal_name',coalesce(nullif(i.header_snapshot_json->>'agency_name',''),sd.agency_name),
          'trading_name',i.header_snapshot_json->>'agency_trading_name',
          'registered_address',coalesce((select jsonb_agg(btrim(line) order by ord) from regexp_split_to_table(coalesce(nullif(i.header_snapshot_json->>'registered_address',''),sd.registered_address,''), E'\r?\n') with ordinality a(line,ord) where btrim(line)<>''),'[]'::jsonb),
          'company_registration_number',coalesce(nullif(i.header_snapshot_json->>'company_reg_number',''),sd.company_reg_number),
          'vat_registration_number',coalesce(nullif(i.header_snapshot_json->>'vat_registration_number',''),sd.vat_registration_number),
          'contact_email',coalesce(i.header_snapshot_json->>'supplier_email',sd.finance_email,sd.system_email),
          'contact_phone',i.header_snapshot_json->>'supplier_phone'),
        'customer',jsonb_build_object(
          'legal_name',coalesce(nullif(i.header_snapshot_json->>'client_name',''),cl.name),
          'billing_address',coalesce((select jsonb_agg(btrim(line) order by ord) from regexp_split_to_table(coalesce(nullif(i.header_snapshot_json->>'client_invoice_address',''),cl.invoice_address,cl.client_address,''), E'\r?\n') with ordinality a(line,ord) where btrim(line)<>''),'[]'::jsonb),
          'account_reference',coalesce(i.header_snapshot_json->>'client_reference',cl.cli_ref)),
        'references',jsonb_build_object('purchase_order',coalesce(i.header_snapshot_json->>'po_reference',i.header_snapshot_json->>'po_number'),'client_reference',coalesce(i.header_snapshot_json->>'client_reference',cl.cli_ref),'work_location',i.header_snapshot_json->>'work_location'),
        'candidate_summary',i.header_snapshot_json->>'candidate_summary',
        'suppress_candidate_header',
          upper(coalesce(
            i.header_snapshot_json#>>'{meta,consolidation_mode}',
            i.header_snapshot_json#>>'{meta,invoice_consolidation_mode}',
            i.header_snapshot_json->>'consolidation_mode',
            i.header_snapshot_json->>'invoice_consolidation_mode','NONE'))
            in('BY_WEEK','ANY_WEEK')
          or exists(select 1 from public.invoice_hr_source_rows nhsp
            where nhsp.invoice_id=i.id and upper(nhsp.source_system)='NHSP')
          or (select count(distinct il.timesheet_id)
              from public.invoice_lines il
              where il.invoice_id=i.id and il.timesheet_id is not null)>1
          or (select count(distinct nullif(btrim(lb.worker_name),''))
              from invoice_line_base lb where lb.invoice_id=i.id)>1,
        'branding',jsonb_build_object(
          'logo',case
            when jsonb_typeof(i.header_snapshot_json->'agency_logo')='object'
              then jsonb_build_object(
                'r2_key',i.header_snapshot_json#>>'{agency_logo,r2_key}',
                'sha256',lower(i.header_snapshot_json#>>'{agency_logo,sha256}'),
                'size_bytes',case
                  when coalesce(i.header_snapshot_json#>>'{agency_logo,size_bytes}','') ~ '^[1-9][0-9]{0,18}$'
                    then (i.header_snapshot_json#>>'{agency_logo,size_bytes}')::bigint
                  else null end,
                'media_type',lower(i.header_snapshot_json#>>'{agency_logo,media_type}'))
            when jsonb_typeof(coalesce(
              sd.invoice_document_presentation_json#>'{branding,logo}',
              sd.import_config_json#>'{invoice_document_presentation,branding,logo}'
            ))='object'
              then jsonb_build_object(
                'r2_key',coalesce(
                  sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
                  sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),
                'sha256',lower(coalesce(
                  sd.invoice_document_presentation_json#>>'{branding,logo,sha256}',
                  sd.import_config_json#>>'{invoice_document_presentation,branding,logo,sha256}')),
                'size_bytes',case
                  when coalesce(
                    sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
                    sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}',
                    ''
                  ) ~ '^[1-9][0-9]{0,18}$'
                    then coalesce(
                      sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
                      sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}'
                    )::bigint
                  else null end,
                'media_type',lower(coalesce(
                  sd.invoice_document_presentation_json#>>'{branding,logo,media_type}',
                  sd.import_config_json#>>'{invoice_document_presentation,branding,logo,media_type}')))
            else '{}'::jsonb end),
        'lines',coalesce(l.lines,'[]'::jsonb),
        'vat_breakdown',coalesce((select jsonb_agg(jsonb_build_object(
          'rate',vb.vat_rate_pct::text,
          'net_amount',vb.net::text,
          'vat_amount',vb.vat::text,
          'gross_amount',vb.gross::text
        ) order by vb.vat_rate_pct) from (
          select coalesce(vat_rate_pct,0) vat_rate_pct,
            round(sum(coalesce(total_charge_ex_vat,0)),2) net,
            round(sum(coalesce(vat_amount,0)),2) vat,
            round(sum(coalesce(total_inc_vat,coalesce(total_charge_ex_vat,0)+coalesce(vat_amount,0))),2) gross
          from public.invoice_lines
          where invoice_id=i.id
          group by coalesce(vat_rate_pct,0)
        ) vb),'[]'::jsonb),
        'totals',jsonb_build_object(
          'net',round(coalesce(i.subtotal_ex_vat,0),2)::text,
          'vat',round(coalesce(i.vat_amount,0),2)::text,
          'gross',round(coalesce(i.total_inc_vat,0),2)::text,
          'amount_paid',coalesce((
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'amount_paid',''),'numeric')
              then (i.header_snapshot_json->>'amount_paid')::numeric end
          ),0)::text,
          'amount_credited',coalesce((
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'amount_credited',''),'numeric')
              then (i.header_snapshot_json->>'amount_credited')::numeric end
          ),0)::text,
          'amount_outstanding',coalesce((
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'amount_outstanding',''),'numeric')
              then (i.header_snapshot_json->>'amount_outstanding')::numeric end
          ),coalesce(i.total_inc_vat,0))::text),
        'payment',jsonb_build_object(
          'terms_days',coalesce(
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
              then (i.header_snapshot_json->>'payment_terms_days')::integer end,
            cl.payment_terms_days,30),
          'terms_text',coalesce(
            nullif(i.header_snapshot_json->>'payment_terms_text',''),
            coalesce(
              case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
                then (i.header_snapshot_json->>'payment_terms_days')::integer end,
              cl.payment_terms_days,
              30
            )::text || ' days from invoice date'
          ),
          'due_date_basis','ISSUE_DATE',
          'instructions',coalesce(
            i.header_snapshot_json->>'payment_instructions',
            sd.invoice_document_presentation_json->>'payment_instructions',
            sd.import_config_json#>>'{invoice_document_presentation,payment_instructions}'),
          'account_name',case when lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes') then null
            else coalesce(i.header_snapshot_json#>>'{bank,name}',i.header_snapshot_json->>'bank_name',sd.bank_name) end,
          'sort_code',case when lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes') then null
            else coalesce(i.header_snapshot_json#>>'{bank,sort_code}',i.header_snapshot_json->>'bank_sort_code',sd.bank_sort_code) end,
          'account_number',case when lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes') then null
            else coalesce(i.header_snapshot_json#>>'{bank,account_number}',i.header_snapshot_json->>'bank_account_number',sd.bank_account_number) end,
          'remittance_reference',i.invoice_no,
          'remittance_email',coalesce(i.header_snapshot_json->>'remittance_email',sd.finance_email),
          'hide_bank_footer',lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes')),
        'credit_note',jsonb_build_object('is_credit_note',i.type::text='CREDIT_NOTE','original_invoice_id',i.original_invoice_id,'original_invoice_number',coalesce(i.header_snapshot_json->>'original_invoice_number',orig.invoice_no),'original_invoice_date',coalesce(i.header_snapshot_json->>'original_invoice_date',orig.issued_at_utc::text),'reason',coalesce(i.header_snapshot_json->>'credit_reason',i.notes)),
        'self_bill',jsonb_build_object('is_self_bill',lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}',i.header_snapshot_json->>'self_bill','false')) in('true','t','1','yes'),'legal_wording',coalesce(i.header_snapshot_json->>'self_bill_wording',coalesce(sd.invoice_document_presentation_json->>'self_bill_legal_wording', sd.import_config_json#>>'{invoice_document_presentation,self_bill_legal_wording}'))),
        'legal_wording',coalesce(i.header_snapshot_json->'legal_wording',coalesce(sd.invoice_document_presentation_json->'legal_wording', sd.import_config_json#>'{invoice_document_presentation,legal_wording}'),'[]'::jsonb),
        'attachment_policy',coalesce(i.header_snapshot_json->'attach_policy',i.header_snapshot_json->'attachment_policy','{}'::jsonb),
        'template_version',vr.template_version,
        'locale',coalesce(i.header_snapshot_json->>'locale',sd.invoice_document_presentation_json->>'locale',sd.import_config_json#>>'{invoice_document_presentation,locale}','en-GB'),
        'page_geometry',coalesce(i.header_snapshot_json->>'page_geometry',sd.invoice_document_presentation_json->>'page_geometry',sd.import_config_json#>>'{invoice_document_presentation,page_geometry}','A4_PORTRAIT_210X297MM')) presentation_model,
      coalesce(ts.timesheet_sources,'[]'::jsonb) timesheet_sources,
      coalesce(sa.supporting_sources,'[]'::jsonb) supporting_sources,
      coalesce(hra.higher_rate_support,jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb)) higher_rate_support,
      coalesce(l.line_net,0) line_net,coalesce(l.line_vat,0) line_vat,coalesce(l.line_gross,0) line_gross,
      round(coalesce(i.subtotal_ex_vat,0),2) invoice_net,round(coalesce(i.vat_amount,0),2) invoice_vat,round(coalesce(i.total_inc_vat,0),2) invoice_gross
    from valid_requests vr
    join public.invoices i on vr.entity_type='INVOICE' and i.id=vr.entity_id
    left join public.invoices orig on orig.id=i.original_invoice_id
    join public.clients cl on cl.id=i.client_id
    cross join public.settings_defaults sd
    left join invoice_line_rows l on l.invoice_id=i.id
    left join invoice_timesheets_agg ts on ts.invoice_id=i.id
    left join support_agg sa on sa.invoice_id=i.id
    left join supporting_manifest_agg sma on sma.invoice_id=i.id
    left join higher_rate_agg hra on hra.invoice_id=i.id
    where sd.id=1
  ),
  timesheet_models as materialized (
    select vr.request_no,vr.req_key request_key,'TIMESHEET_PRESENTATION_SNAPSHOT_V5'::text snapshot_schema_version,
      coalesce(v2.render_model,jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V1',
        'timesheet_id',t.timesheet_id,
        'document_revision',t.document_revision,
        'candidate',jsonb_build_object('id',coalesce(vs.candidate_id::text,null),'name',coalesce(vs.candidate_name,t.occupant_key_norm)),
        'client',jsonb_build_object('id',coalesce(vs.client_id::text,null),'name',vs.client_name),
        'contract',jsonb_build_object('id',coalesce(t.contract_id::text,null),'reference',t.booking_id),
        'work',jsonb_build_object(
          'hospital',t.hospital_norm,
          'site',t.hospital_norm,
          'ward',t.ward_norm,
          'assignment',coalesce(
            nullif(btrim(t.job_title_norm),''),
            case when nullif(btrim(t.shift_label_norm),'') is not null
                   and length(t.shift_label_norm) <= 80
                   and t.shift_label_norm !~* '^weekly-correction-'
                   and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
              then t.shift_label_norm end),
          'job_title',t.job_title_norm,
          'band',t.band,
          'shift_type',case when nullif(btrim(t.shift_label_norm),'') is not null
                              and length(t.shift_label_norm) <= 80
                              and t.shift_label_norm !~* '^weekly-correction-'
                              and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
                         then t.shift_label_norm end),
        'week_ending_date',t.week_ending_date,
        'submission_mode',t.submission_mode::text,
        'sheet_scope',t.sheet_scope::text,
        'daily_schedule_rows',coalesce((select jsonb_agg(jsonb_build_object('date',coalesce(s.value->>'date',s.value->>'day',to_char(t.worked_start_iso::date,'YYYY-MM-DD')),'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc',t.scheduled_start_iso::text),'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc',t.scheduled_end_iso::text),'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc',t.worked_start_iso::text),'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc',t.worked_end_iso::text),'break_start',coalesce(s.value->>'break_start',t.break_start_iso::text),'break_end',coalesce(s.value->>'break_end',t.break_end_iso::text),'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then (coalesce(s.value->>'break_minutes',s.value->>'break_mins'))::integer else coalesce(t.break_minutes,0) end,'reference',coalesce(s.value->>'reference',s.value->>'ref_num',t.reference_number),'hours',coalesce(s.value->>'hours',s.value->>'units',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end),'units',coalesce(s.value->>'units',s.value->>'hours'),'display_order',s.ordinality) order by s.ordinality) from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality) where upper(coalesce(t.sheet_scope::text,''))='DAILY'),case when upper(coalesce(t.sheet_scope::text,''))='DAILY' then jsonb_build_array(jsonb_build_object('date',t.worked_start_iso::date,'scheduled_start',t.scheduled_start_iso,'scheduled_end',t.scheduled_end_iso,'worked_start',t.worked_start_iso,'worked_end',t.worked_end_iso,'break_start',t.break_start_iso,'break_end',t.break_end_iso,'break_minutes',coalesce(t.break_minutes,0),'reference',t.reference_number,'hours',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end,'units',null,'display_order',1)) else '[]'::jsonb end),
        'weekly_schedule_rows',coalesce((select jsonb_agg(jsonb_build_object(
          'date',coalesce(s.value->>'date',s.value->>'day'),
          'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc'),
          'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc'),
          'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),
          'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),
          'break_start',s.value->>'break_start',
          'break_end',s.value->>'break_end',
          'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then coalesce(s.value->>'break_minutes',s.value->>'break_mins')::integer else 0 end,
          'reference',coalesce(s.value->>'reference',s.value->>'ref_num'),
          'hours',coalesce(
            s.value->>'hours',
            s.value->>'units',
            case when pg_input_is_valid(nullif(coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),''),'timestamptz')
                       and pg_input_is_valid(nullif(coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),''),'timestamptz')
                 then greatest(
                   0,
                   round((
                     extract(epoch from (
                       coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc')::timestamptz
                       - coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc')::timestamptz
                     )) / 60
                     - case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$'
                         then coalesce(s.value->>'break_minutes',s.value->>'break_mins')::numeric else 0 end
                   ) / 60,2)
                 )::text end),
          'units',coalesce(s.value->>'units',s.value->>'hours'),
          'display_order',s.ordinality
        ) order by s.ordinality) from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality) where upper(coalesce(t.sheet_scope::text,''))='WEEKLY'),'[]'::jsonb),
        'references',jsonb_build_object('whole',nullif(t.reference_number,''),'day',coalesce((select jsonb_agg(jsonb_build_object('day_key',d.key,'reference',case when jsonb_typeof(d.value)='object' then coalesce(d.value->>'reference',d.value->>'ref_num',d.value->>'value') else trim(both '"' from d.value::text) end,'display_order',d.ordinality) order by d.ordinality) from jsonb_each(case when jsonb_typeof(t.day_references_json)='object' then t.day_references_json else '{}'::jsonb end) with ordinality d(key,value,ordinality)), '[]'::jsonb),'segment','[]'::jsonb),
        'additional_units',coalesce((
          select jsonb_object_agg(
            au.key,
            case
              when jsonb_typeof(au.value)='number'
                then to_jsonb(trim_scale((au.value#>>'{}')::numeric)::text)
              else au.value
            end
            order by au.key
          )
          from jsonb_each(
            case when jsonb_typeof(t.additional_units_week)='object'
              then t.additional_units_week else '{}'::jsonb end
          ) au
        ),'{}'::jsonb),
        'authorisation',jsonb_build_object('authorised',t.authorised_at_server is not null,'name',t.auth_name,'role',t.auth_job_title,'authorised_at_utc',t.authorised_at_server),
        'signatures',jsonb_build_object(
          'candidate',case when nullif(t.r2_nurse_key,'') is null
            then jsonb_build_object('identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse')
            else jsonb_build_object('r2_key',t.r2_nurse_key,'sha256',t.img_sha256_nurse,'size_bytes',null,'media_type','image/png','identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse') end,
          'authoriser',case when nullif(t.r2_auth_key,'') is null
            then jsonb_build_object('identity',t.auth_name,'role',t.auth_job_title)
            else jsonb_build_object('r2_key',t.r2_auth_key,'sha256',t.img_sha256_auth,'size_bytes',null,'media_type','image/png','identity',t.auth_name,'role',t.auth_job_title) end),
        'qr',jsonb_build_object('required',t.qr_status is not null,'signed',t.qr_signed_hash is not null,'status',t.qr_status::text,'signed_hash',t.qr_signed_hash,'signed_at_utc',t.qr_signed_at_utc,'verification_summary',case when t.qr_signed_hash is not null then 'QR signature verified in frozen source' when t.qr_status is not null then t.qr_status::text else null end),
        'template_version','timesheet-professional-v1'
      )) presentation_model,
      '[]'::jsonb timesheet_sources,
      '[]'::jsonb supporting_sources,
      jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support
    from valid_requests vr
    join public.timesheets t on vr.entity_type='TIMESHEET' and t.timesheet_id=vr.entity_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join timesheet_v2_models v2
      on v2.invoice_id is null and v2.timesheet_id=t.timesheet_id
  ),
  missing_entity_results as materialized (
    select vr.request_no,vr.req_key request_key,
      case when vr.entity_type='INVOICE' then 'INVOICE_PRESENTATION_SNAPSHOT_V5' else 'TIMESHEET_PRESENTATION_SNAPSHOT_V5' end snapshot_schema_version,
      '{}'::jsonb presentation_model,'[]'::jsonb timesheet_sources,'[]'::jsonb supporting_sources,
      jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
      jsonb_build_object('snapshot_schema_version','PRESENTATION_ENTITY_NOT_FOUND','request_key',vr.req_key,'entity_type',vr.entity_type,'entity_id',vr.entity_id) snapshot_json,
      encode(digest(jsonb_build_object('snapshot_schema_version','PRESENTATION_ENTITY_NOT_FOUND','request_key',vr.req_key,'entity_type',vr.entity_type,'entity_id',vr.entity_id)::text,'sha256'),'hex') snapshot_hash,
      false valid,
      'PRESENTATION_ENTITY_NOT_FOUND'::text error_code,
      jsonb_build_object('entity_type',vr.entity_type,'entity_id',vr.entity_id) error_detail
    from valid_requests vr
    where not exists(select 1 from invoice_models im where im.request_no=vr.request_no)
      and not exists(select 1 from timesheet_models tm where tm.request_no=vr.request_no)
  ),
  all_models as materialized (
    select request_no,request_key,snapshot_schema_version,presentation_model,timesheet_sources,supporting_sources,higher_rate_support,
      case
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model->>'document_type','') is null then 'INVOICE_PRESENTATION_DOCUMENT_TYPE_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model->>'invoice_number','') is null then 'INVOICE_PRESENTATION_INVOICE_NUMBER_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model#>>'{supplier,legal_name}','') is null then 'INVOICE_PRESENTATION_SUPPLIER_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and jsonb_array_length(case when jsonb_typeof(presentation_model#>'{supplier,registered_address}')='array' then presentation_model#>'{supplier,registered_address}' else '[]'::jsonb end)=0 then 'INVOICE_PRESENTATION_SUPPLIER_ADDRESS_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model#>>'{customer,legal_name}','') is null then 'INVOICE_PRESENTATION_CUSTOMER_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and jsonb_array_length(case when jsonb_typeof(presentation_model#>'{customer,billing_address}')='array' then presentation_model#>'{customer,billing_address}' else '[]'::jsonb end)=0 then 'INVOICE_PRESENTATION_CUSTOMER_ADDRESS_REQUIRED'
        when snapshot_schema_version='FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5' and nullif(presentation_model->>'issue_date','') is null then 'INVOICE_PRESENTATION_ISSUE_DATE_REQUIRED'
        when snapshot_schema_version='FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5' and nullif(presentation_model->>'tax_point','') is null then 'INVOICE_PRESENTATION_TAX_POINT_REQUIRED'
        when snapshot_schema_version='FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5' and nullif(presentation_model->>'due_date','') is null then 'INVOICE_PRESENTATION_DUE_DATE_REQUIRED'
        when jsonb_array_length(coalesce(presentation_model->'lines','[]'::jsonb))=0
          and snapshot_schema_version like '%INVOICE%'
          and (coalesce(invoice_net,0)<>0 or coalesce(invoice_vat,0)<>0 or coalesce(invoice_gross,0)<>0)
          then 'INVOICE_PRESENTATION_REQUIRED_FIELD_MISSING'
        when snapshot_schema_version like '%INVOICE%' and (line_net,line_vat,line_gross) is distinct from (invoice_net,invoice_vat,invoice_gross) then 'INVOICE_PRESENTATION_LINE_TOTAL_MISMATCH'
        when snapshot_schema_version like '%INVOICE%' and invoice_vat<>0 and nullif(presentation_model#>>'{supplier,vat_registration_number}','') is null then 'INVOICE_PRESENTATION_VAT_NUMBER_REQUIRED'
        when (presentation_model->>'document_type')='CREDIT_NOTE' and nullif(coalesce(presentation_model#>>'{credit_note,original_invoice_number}',presentation_model#>>'{credit_note,original_invoice_id}'),'') is null then 'CREDIT_NOTE_ORIGINAL_REQUIRED'
        when (presentation_model->>'document_type')='CREDIT_NOTE' and nullif(presentation_model#>>'{credit_note,reason}','') is null then 'CREDIT_NOTE_REASON_REQUIRED'
        when (presentation_model->>'document_type')='SELF_BILL_INVOICE' and nullif(presentation_model#>>'{self_bill,legal_wording}','') is null then 'SELF_BILL_WORDING_REQUIRED'
        else null end error_code
    from invoice_models
    union all
    select request_no,request_key,snapshot_schema_version,presentation_model,timesheet_sources,supporting_sources,higher_rate_support,
      case
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and nullif(presentation_model#>>'{week_period,end_date}','') is null
          then 'TIMESHEET_WEEK_ENDING_DATE_MISSING'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and coalesce(presentation_model#>>'{week_period,configured_week_ending_weekday}','')~'^[0-6]$'
          and coalesce(presentation_model#>>'{week_period,end_weekday_index}','')~'^[0-6]$'
          and (presentation_model#>>'{week_period,configured_week_ending_weekday}')::integer
            <> (presentation_model#>>'{week_period,end_weekday_index}')::integer
          then 'TIMESHEET_WEEK_ENDING_WEEKDAY_MISMATCH'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and jsonb_array_length(case
            when jsonb_typeof(presentation_model#>'{week_period,days}')='array'
              then presentation_model#>'{week_period,days}' else '[]'::jsonb end)<>7
          then 'TIMESHEET_WEEK_PERIOD_INVALID'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and not exists(
            select 1
            from jsonb_array_elements(
              coalesce(presentation_model#>'{week_period,days}','[]'::jsonb)) d
            cross join lateral jsonb_array_elements(
              coalesce(d->'shift_lines','[]'::jsonb)) s)
          then 'TIMESHEET_PRESENTATION_SCHEDULE_MISSING'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and exists(
            select 1
            from jsonb_array_elements(
              coalesce(presentation_model#>'{week_period,days}','[]'::jsonb)) d
            cross join lateral jsonb_array_elements(
              coalesce(d->'shift_lines','[]'::jsonb)) s
            where s->>'date'<>d->>'date')
          then 'TIMESHEET_SCHEDULE_DATE_OUTSIDE_PERIOD'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and coalesce((presentation_model->>'additional_units_snapshot_stale')::boolean,false)
          then 'TIMESHEET_ADDITIONAL_UNITS_SNAPSHOT_STALE'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and exists(
            select 1
            from jsonb_array_elements(coalesce(
              presentation_model#>'{additional_units_section,rows}',
              '[]'::jsonb)) a
            where nullif(a->>'date','') is not null
              and ((a->>'date')::date<
                (presentation_model#>>'{week_period,start_date}')::date
                or (a->>'date')::date>
                (presentation_model#>>'{week_period,end_date}')::date))
          then 'TIMESHEET_ADDITIONAL_UNIT_DATE_OUTSIDE_PERIOD'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          then null
        when jsonb_array_length(coalesce(
            presentation_model->'daily_schedule_rows','[]'::jsonb))=0
          and jsonb_array_length(coalesce(
            presentation_model->'weekly_schedule_rows','[]'::jsonb))=0
          then 'TIMESHEET_PRESENTATION_SCHEDULE_MISSING'
        else null end error_code
    from timesheet_models
  ),
  assembled as materialized (
    select m.*,
      encode(digest(m.presentation_model::text,'sha256'),'hex') presentation_model_hash,
      jsonb_build_object(
        'snapshot_schema_version',m.snapshot_schema_version,
        'request_key',m.request_key,
        'presentation_model',m.presentation_model,
        'presentation_model_hash',encode(digest(m.presentation_model::text,'sha256'),'hex'),
        'timesheet_sources',m.timesheet_sources,
        'supporting_sources',m.supporting_sources,
        'supporting_manifest',coalesce((select sma.supporting_manifest from supporting_manifest_agg sma where sma.invoice_id=(m.presentation_model->>'invoice_id')::uuid),'[]'::jsonb),
        'higher_rate_support',m.higher_rate_support
      ) snapshot_json
    from all_models m
  )
  select d.request_key,d.snapshot_schema_version,d.presentation_model,d.timesheet_sources,d.supporting_sources,d.higher_rate_support,d.snapshot_json,d.snapshot_hash,d.valid,d.error_code,d.error_detail
  from duplicate_key_results d
  union all
  select i.request_key,i.snapshot_schema_version,i.presentation_model,i.timesheet_sources,i.supporting_sources,i.higher_rate_support,i.snapshot_json,i.snapshot_hash,i.valid,i.error_code,i.error_detail
  from invalid_request_results i
  union all
  select m.request_key,m.snapshot_schema_version,m.presentation_model,m.timesheet_sources,m.supporting_sources,m.higher_rate_support,
         m.snapshot_json,encode(digest(m.snapshot_json::text,'sha256'),'hex'),m.error_code is null,
         m.error_code,
         case when m.error_code is null then '{}'::jsonb else jsonb_build_object('request_key',m.request_key,'code',m.error_code) end
  from assembled m
  union all
  select e.request_key,e.snapshot_schema_version,e.presentation_model,e.timesheet_sources,e.supporting_sources,e.higher_rate_support,e.snapshot_json,e.snapshot_hash,e.valid,e.error_code,e.error_detail
  from missing_entity_results e
  ;
end;
$function$;

-- private._invoice_processor_limits()
CREATE OR REPLACE FUNCTION private._invoice_processor_limits()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'version','INVOICE_PROCESSOR_LIMITS_V4',
    'policy_version','INVOICE_PROCESSOR_LIMITS_V4',
    'context',jsonb_build_object(
      'ASSET_INSPECT',262144,
      'ASSET_NORMALISE',262144,
      'SOURCE_RENDER',524288,
      'INVOICE_CORE_RENDER',1048576,
      'PDF_MERGE',524288,
      'DOCUMENT_VERIFY',262144),
    'result',jsonb_build_object(
      'ASSET_INSPECT',524288,
      'ASSET_NORMALISE',524288,
      'SOURCE_RENDER',262144,
      'INVOICE_CORE_RENDER',262144,
      'PDF_MERGE',1048576,
      'DOCUMENT_VERIFY',524288),
    'asset',jsonb_build_object(
      'max_pixels',80000000,
      'max_decoded_bytes',536870912,
      'max_source_bytes',268435456,
      'allowed_media_types',jsonb_build_array(
        'application/pdf','image/jpeg','image/png'),
      'image_normalisation_profile','INVOICE_IMAGE_NORMALISATION_V1',
      'pdf_normalisation_profile','INVOICE_PDF_NORMALISATION_V1',
      'max_pdf_part_pages',100,
      'max_pdf_part_bytes',50331648,
      'max_part_input_bytes',67108864,
      'max_part_estimated_decoded_bytes',201326592),
    'merge',jsonb_build_object(
      'bin_packing_version','SEQUENTIAL_FIRST_FIT_V1',
      'max_inputs',24,
      'max_pages',2000,
      'max_input_bytes',536870912,
      'max_estimated_decoded_bytes',4294967296,
      'max_levels',16),
    'attachment_index',jsonb_build_object(
      'layout_version','BOUNDED_STABILISATION_V1',
      'renderer_version','INVOICE_ATTACHMENT_INDEX_RENDERER_V1',
      'template_version','invoice-attachment-index-v1',
      'css_font_identity','CLOUDTMS_INVOICE_CSS_FONT_V1',
      'page_geometry','A4_PORTRAIT_210X297MM',
      'locale_identity','en-GB_DDMMYYYY',
      'max_render_passes',3),
    'verify',jsonb_build_object(
      'object_receipt_contract','ACTUAL_BYTES_OBJECT_RECEIPT_V3',
      'logical_receipt_contract','LOGICAL_SOURCE_RECEIPT_V3',
      'merge_receipt_contract','ACTUAL_BYTES_MERGE_RECEIPT_V3',
      'document_root_receipt_contract','DOCUMENT_ROOT_RECEIPT_V3',
      'ordered_input_hash_contract','ACTUAL_ORDERED_INPUT_V1',
      'receipt_hash_algorithm','SHA256',
      'max_receipts',4096,
      'require_parse_success',true,
      'require_ordered_input_receipts',true,
      'require_logical_coverage_hash',true,
      'require_physical_receipt_hash',true),
    'delivery',jsonb_build_object(
      'max_attachments_per_message',30,
      'max_cumulative_attachment_bytes',20971520,
      'max_individual_attachment_bytes',10485760,
      'secure_link_threshold_bytes',20971520,
      'allowed_policies',jsonb_build_array('ATTACH','SPLIT','SECURE_LINK'))
  );
$function$;

-- private._invoice_reconcile_advance_batch(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_reconcile_advance_batch(p_claims jsonb, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_result jsonb;
begin
  /*
   * Every reconciliation command is bounded either by explicit operation IDs
   * or by its time fence and max_rows.  It performs only indexed database
   * repair; it never reads R2, regenerates financial data, or renders files.
   */
  with reconcile_claims as materialized (
    select c.id reconcile_chunk_id,c.operation_id reconcile_operation_id,c.payload_json,
      case when jsonb_typeof(c.payload_json->'operation_ids')='array'
        then jsonb_array_length(c.payload_json->'operation_ids') else 0 end
        explicit_operation_count,
      least(500,greatest(1,case
        when coalesce(c.payload_json->>'max_rows','') ~ '^[0-9]{1,6}$'
          then (c.payload_json->>'max_rows')::integer else 100 end)) max_rows,
      v_now-make_interval(secs=>least(604800,greatest(30,case
        when coalesce(c.payload_json->>'older_than_seconds','') ~ '^[0-9]{1,6}$'
          then (c.payload_json->>'older_than_seconds')::integer
        else 300 end))) not_updated_after_utc
    from jsonb_array_elements(p_claims) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    where c.chunk_type='RECONCILE' and c.status='RUNNING'
  ),
  explicit_scope as materialized (
    select rc.reconcile_chunk_id,(v.value)::uuid operation_id
    from reconcile_claims rc
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(rc.payload_json->'operation_ids')='array'
        then rc.payload_json->'operation_ids' else '[]'::jsonb end)
      with ordinality v(value,ordinality)
    where v.value ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and v.ordinality<=500
  ),
  implicit_scope as materialized (
    select rc.reconcile_chunk_id,o.id operation_id
    from reconcile_claims rc
    cross join lateral (
      select candidate.id
      from public.invoice_operations candidate
      where not exists(
        select 1 from explicit_scope e where e.reconcile_chunk_id=rc.reconcile_chunk_id)
        and candidate.id<>rc.reconcile_operation_id
        and candidate.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and candidate.updated_at_utc<=rc.not_updated_after_utc
      order by candidate.updated_at_utc,candidate.id
      limit rc.max_rows
    ) o
  ),
  scope as materialized (
    select distinct reconcile_chunk_id,operation_id from explicit_scope
    union
    select distinct reconcile_chunk_id,operation_id from implicit_scope
  ),
  scoped_operations as materialized (
    select distinct operation_id from scope
  ),
  scoped_operation_ids as materialized (
    select s.operation_id,
      row_number() over(order by s.operation_id) operation_no
    from scoped_operations s
  ),
  scoped_operation_pages as materialized (
    select ((s.operation_no-1)/500)::integer page_no,
      array_agg(s.operation_id order by s.operation_id) operation_ids
    from scoped_operation_ids s
    group by ((s.operation_no-1)/500)::integer
  ),
  initial_current_slots as materialized (
    select g.*
    from scoped_operation_pages p
    cross join lateral private._invoice_current_chunks_batch(
      p.operation_ids,null,null,10000) g
  ),
  initial_current_chunks as materialized (
    select g.*,c.payload_json,c.result_json,c.actual_page_count,
      c.actual_byte_count,c.updated_at_utc
    from initial_current_slots g
    left join public.invoice_operation_chunks c on c.id=g.current_chunk_id
  ),
  replacement_graph_validation as materialized (
    select g.operation_id,g.logical_slot_key,g.replacement_chain_error
    from initial_current_slots g
    where g.replacement_chain_status='INVALID'
  ),
  current_normalise_ranges as materialized (
    select c.operation_id,c.current_chunk_id,c.document_asset_id,
      c.current_status,c.sequence_no,c.payload_json,c.result_json,
      c.actual_page_count,c.actual_byte_count,
      case when coalesce(c.payload_json#>>'{page_range,start}','')
          ~'^[1-9][0-9]{0,8}$'
        then(c.payload_json#>>'{page_range,start}')::integer end range_start,
      case when coalesce(c.payload_json#>>'{page_range,end}','')
          ~'^[1-9][0-9]{0,8}$'
        then(c.payload_json#>>'{page_range,end}')::integer end range_end
    from initial_current_chunks c
    where c.replacement_chain_status='VALID'
      and c.chunk_type='ASSET_NORMALISE'
      and c.document_asset_id is not null
  ),
  ordered_normalise_ranges as materialized (
    select r.*,
      lag(r.range_end) over(partition by r.document_asset_id
        order by r.range_start,r.range_end,r.sequence_no,r.current_chunk_id)
        previous_end
    from current_normalise_ranges r
  ),
  asset_current_coverage as materialized (
    select a.id asset_id,a.status asset_status,a.source_page_count,
      count(r.current_chunk_id)::integer current_part_count,
      coalesce(bool_and(r.current_status='COMPLETE'),false) all_complete,
      coalesce(bool_and(
        r.range_start is not null and r.range_end is not null
        and r.range_start<=r.range_end
        and r.range_end<=a.source_page_count
        and r.range_start=coalesce(r.previous_end+1,1)
        and coalesce(r.actual_page_count,0)=r.range_end-r.range_start+1
        and coalesce(r.actual_byte_count,0)>0
        and coalesce(r.result_json->>'r2_key','')<>''
        and coalesce(r.result_json->>'sha256','')~'^[0-9a-f]{64}$'
      ),false)
      and min(r.range_start)=1
      and max(r.range_end)=a.source_page_count
      and sum(r.range_end-r.range_start+1)=a.source_page_count
        coverage_valid
    from public.invoice_document_assets a
    join ordered_normalise_ranges r on r.document_asset_id=a.id
    group by a.id,a.status,a.source_page_count
  ),
  invalid_current_assets as materialized (
    select c.*
    from asset_current_coverage c
    where c.current_part_count>0
      and(
        (c.asset_status='NORMALISING' and c.all_complete
          and not c.coverage_valid)
        or(c.asset_status='READY'
          and(not c.all_complete or not c.coverage_valid)))
  ),
  invalid_normalise_chunks as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code',case when a.asset_status='READY'
            then 'HISTORICAL_NORMALISATION_CONTAMINATION'
            else 'ASSET_RANGE_COVERAGE_MISMATCH' end,
          'asset_id',a.asset_id,
          'source_page_count',a.source_page_count,
          'current_part_count',a.current_part_count,
          'reconciled_at_utc',v_now)
    from invalid_current_assets a
    where c.id in(
      select r.current_chunk_id from current_normalise_ranges r
      where r.document_asset_id=a.asset_id)
    returning c.id,c.operation_id,c.document_asset_id
  ),
  failed_current_range_assets as (
    update public.invoice_document_assets a
    set status='FAILED',updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','ASSET_RANGE_COVERAGE_MISMATCH',
          'class','PERMANENT','retryable',false,
          'source_page_count',a.source_page_count,
          'reconciled_at_utc',v_now)
    from invalid_current_assets x
    where a.id=x.asset_id and x.asset_status='NORMALISING'
    returning a.id,a.operation_id,a.source_kind,a.source_id,a.error_json
  ),
  invalid_asset_evidence as (
    update public.timesheet_evidence e
    set processing_state='FAILED',
        processing_error_json=jsonb_build_object(
          'code',case when x.asset_status='READY'
            then 'HISTORICAL_NORMALISATION_CONTAMINATION'
            else 'ASSET_RANGE_COVERAGE_MISMATCH' end,
          'asset_id',a.id,'reconciled_at_utc',v_now)
    from invalid_current_assets x
    join public.invoice_document_assets a on a.id=x.asset_id
    where a.source_kind='TIMESHEET_EVIDENCE' and e.id=a.source_id
    returning e.id,e.timesheet_id,e.kind,e.processing_error_json
  ),
  invalid_manual_sources as (
    update public.timesheets t
    set document_state='FAILED',
        last_document_error_json=e.processing_error_json,
        updated_at=v_now
    from invalid_asset_evidence e
    where upper(coalesce(e.kind,''))='TIMESHEET'
      and t.timesheet_id=e.timesheet_id and t.is_current
    returning t.timesheet_id
  ),
  invalid_running as (
    update public.invoice_operation_chunks c
    set status=case when c.attempt_count>=c.max_attempts then 'DEAD_LETTER' else 'RETRY_WAIT' end,
        phase=case when c.attempt_count>=c.max_attempts then 'DEAD_LETTER' else c.phase end,
        run_after_utc=case when c.attempt_count>=c.max_attempts then c.run_after_utc
          else v_now+interval '30 seconds' end,
        error_json=jsonb_build_object(
          'code',case
            when c.lease_token is null then 'RUNNING_WITHOUT_LEASE_TOKEN'
            when c.lease_owner is null then 'RUNNING_WITHOUT_LEASE_OWNER'
            when c.lease_expires_at_utc is null then 'RUNNING_WITHOUT_LEASE_EXPIRY'
            else 'LEASE_EXPIRED' end,
          'reconciled_at_utc',v_now,
          'history',coalesce((
            select jsonb_agg(h.value order by h.ordinality)
            from jsonb_array_elements(coalesce(c.error_json->'history','[]'::jsonb))
                 with ordinality h(value,ordinality)
            where h.ordinality>greatest(
              jsonb_array_length(coalesce(c.error_json->'history','[]'::jsonb))-6,0)
          ),'[]'::jsonb)||jsonb_build_array(jsonb_build_object(
            'code',coalesce(c.error_json->>'code','UNKNOWN'),'at_utc',v_now))),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        failed_at_utc=case when c.attempt_count>=c.max_attempts then v_now else null end,
        updated_at_utc=v_now
    where c.operation_id in(select operation_id from scoped_operations)
      and c.status='RUNNING'
      and(c.lease_token is null or c.lease_owner is null
        or c.lease_expires_at_utc is null or c.lease_expires_at_utc<=v_now)
    returning c.id,c.operation_id
  ),
  cancelled_orphans as (
    update public.invoice_operation_chunks c
    set status=case when o.status='SUPERSEDED' then 'SUPERSEDED' else 'CANCELLED' end,
        phase=case when o.status='SUPERSEDED' then 'SUPERSEDED' else 'CANCELLED' end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        completed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object('code','PARENT_'||o.status,'reconciled_at_utc',v_now)
    from public.invoice_operations o
    where c.operation_id=o.id
      and o.id in(select operation_id from scoped_operations)
      and o.status in('CANCELLED','SUPERSEDED')
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning c.id,c.operation_id
  ),
  ready_asset_dependencies as (
    update public.invoice_operation_chunks d
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        result_json=jsonb_build_object(
          'asset_id',a.id,'source_revision',a.source_revision,
          'normalised_r2_key',a.normalised_r2_key,
          'normalised_manifest',a.normalised_manifest_json,
          'parts',a.normalised_manifest_json,
          'sha256',a.normalised_sha256,
          'normalised_manifest_hash',a.normalised_manifest_hash,
          'size_bytes',a.normalised_size_bytes,
          'page_count',a.normalised_page_count),
        expected_page_count=coalesce(a.normalised_page_count,d.expected_page_count),
        actual_page_count=a.normalised_page_count,
        expected_byte_count=coalesce(a.normalised_size_bytes,d.expected_byte_count),
        actual_byte_count=a.normalised_size_bytes,
        error_json=null
    from public.invoice_document_assets a
    where d.operation_id in(select operation_id from scoped_operations)
      and d.chunk_type='DOCUMENT_INPUT'
      and(
        d.status='WAITING'
        or(d.status='BLOCKED'
          and d.error_json->>'code'='DOCUMENT_DEPENDENCY_PERMANENT_FAILURE'))
      and d.document_asset_id=a.id and a.status='READY'
      and not exists(select 1 from invalid_current_assets x
        where x.asset_id=a.id)
      and a.normalised_size_bytes>0
      and a.normalised_page_count>0
      and((a.normalised_r2_key is not null
            and a.normalised_sha256 is not null
            and jsonb_array_length(a.normalised_manifest_json)=0
            and a.normalised_manifest_hash is null)
        or(a.normalised_r2_key is null
            and a.normalised_sha256 is null
            and jsonb_array_length(a.normalised_manifest_json)>0
            and a.normalised_manifest_hash is not null))
    returning d.id,d.operation_id,d.document_version_id
  ),
  ready_version_dependencies as (
    update public.invoice_operation_chunks d
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,
        updated_at_utc=v_now,lease_owner=null,lease_token=null,
        lease_expires_at_utc=null,
        result_json=jsonb_build_object(
          'document_version_id',v.id,'source_revision',v.source_revision,
          'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count),
        expected_page_count=coalesce(v.page_count,d.expected_page_count),
        actual_page_count=v.page_count,
        expected_byte_count=coalesce(v.size_bytes,d.expected_byte_count),
        actual_byte_count=v.size_bytes,error_json=null
    from public.invoice_document_versions v
    where d.operation_id in(select operation_id from scoped_operations)
      and d.chunk_type='DOCUMENT_INPUT'
      and(d.status='WAITING' or(d.status='BLOCKED'
        and d.error_json->>'code'='DOCUMENT_DEPENDENCY_PERMANENT_FAILURE'))
      and d.input_document_version_id=v.id and v.status='READY'
      and v.r2_key is not null and v.sha256 is not null
      and v.size_bytes>0 and v.page_count>0
    returning d.id,d.operation_id,d.document_version_id
  ),
  ready_dependencies as materialized (
    select * from ready_asset_dependencies
    union all
    select * from ready_version_dependencies
  ),
  reset_document_versions as (
    update public.invoice_document_versions v
    set status='WAITING_FOR_INPUTS',error_json=null
    where v.id in(select document_version_id from ready_dependencies)
      and v.status='FAILED'
      and v.error_json->>'code'='DOCUMENT_DEPENDENCY_PERMANENT_FAILURE'
    returning v.id
  ),
  failed_asset_dependencies as (
    update public.invoice_operation_chunks d
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','DOCUMENT_DEPENDENCY_PERMANENT_FAILURE',
          'asset_id',d.document_asset_id,
          'input_document_version_id',d.input_document_version_id,
          'source_entity_id',d.entity_id,'asset_error',
          coalesce(a.error_json,case when exists(
            select 1 from invalid_current_assets x where x.asset_id=a.id)
            then jsonb_build_object(
              'code','HISTORICAL_NORMALISATION_CONTAMINATION',
              'asset_id',a.id,'reconciled_at_utc',v_now) end))
    from public.invoice_document_assets a
    where d.operation_id in(select operation_id from scoped_operations)
      and d.chunk_type='DOCUMENT_INPUT'
      and d.status='WAITING'
      and d.document_asset_id=a.id
      and(
        a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
        or exists(select 1 from invalid_current_assets x
          where x.asset_id=a.id))
    returning d.id,d.operation_id,d.document_version_id
  ),
  failed_version_dependencies as (
    update public.invoice_operation_chunks d
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','DOCUMENT_DEPENDENCY_PERMANENT_FAILURE',
          'input_document_version_id',d.input_document_version_id,
          'source_entity_id',d.entity_id,'document_error',v.error_json)
    from public.invoice_document_versions v
    where d.operation_id in(select operation_id from scoped_operations)
      and d.chunk_type='DOCUMENT_INPUT' and d.status='WAITING'
      and d.input_document_version_id=v.id
      and v.status in('FAILED','SUPERSEDED','CANCELLED')
    returning d.id,d.operation_id,d.document_version_id
  ),
  failed_dependencies as materialized (
    select * from failed_asset_dependencies
    union all
    select * from failed_version_dependencies
  ),
  affected_document_versions as materialized (
    select document_version_id from ready_dependencies
    union select document_version_id from failed_dependencies
  ),
  plan_wake as (
    update public.invoice_operation_chunks p
    set status='QUEUED',
        phase=case when p.phase in('BUILD_MANIFEST','WAIT_FOR_INPUTS')
          then 'WAIT_FOR_INPUTS' else p.phase end,
        run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where p.chunk_type='DOCUMENT_PLAN'
      and p.document_version_id in(select document_version_id from affected_document_versions)
      and p.status in('WAITING','RETRY_WAIT','BLOCKED')
      and not exists(
        select 1 from public.invoice_operation_chunks d
        where d.document_version_id=p.document_version_id
          and d.chunk_type='DOCUMENT_INPUT' and d.status='BLOCKED')
    returning p.id,p.operation_id
  ),
  issue_wake as (
    update public.invoice_operation_chunks i
    set status=case when v.status='READY' then 'QUEUED' else 'BLOCKED' end,
        phase=case when v.status='READY' then 'FINALISE' else 'WAIT_DOCUMENT' end,
        run_after_utc=v_now,updated_at_utc=v_now,
        error_json=case when v.status='READY' then null else jsonb_build_object(
          'code','FINAL_DOCUMENT_PERMANENT_FAILURE',
          'document_version_id',v.id,'document_error',v.error_json) end,
        failed_at_utc=case when v.status='READY' then null else v_now end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    from public.invoice_document_versions v
    where i.operation_id in(select operation_id from scoped_operations)
      and i.chunk_type='ISSUE_INVOICE' and i.phase='WAIT_DOCUMENT'
      and i.status in('WAITING','RETRY_WAIT','BLOCKED')
      and coalesce(
        case when coalesce(i.payload_json->>'document_version_id','') ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'document_version_id')::uuid end,
        case when coalesce(i.payload_json->>'final_document_version_id','') ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'final_document_version_id')::uuid end)=v.id
      and v.status in('READY','FAILED','SUPERSEDED','CANCELLED')
    returning i.id,i.operation_id
  ),
  invoice_ready_pointers as (
    update public.invoices i
    set preview_document_version_id=case when v.purpose='DRAFT_PREVIEW' then v.id
          else i.preview_document_version_id end,
        document_state=case when v.purpose='DRAFT_PREVIEW' then 'READY' else i.document_state end,
        active_document_operation_id=case
          when i.active_document_operation_id=v.operation_id then null
          else i.active_document_operation_id end,
        invoice_pdf_r2_key=case when v.purpose='DRAFT_PREVIEW' then v.r2_key
          else i.invoice_pdf_r2_key end,
        invoice_pdf_generated_at_utc=case when v.purpose='DRAFT_PREVIEW' then v.verified_at_utc
          else i.invoice_pdf_generated_at_utc end,
        updated_at=v_now
    from public.invoice_document_versions v
    where v.entity_type='INVOICE' and v.purpose='DRAFT_PREVIEW' and v.status='READY'
      and v.operation_id in(select operation_id from scoped_operations)
      and i.id=v.entity_id and i.document_revision::text=v.source_revision
    returning i.id
  ),
  timesheet_ready_pointers as (
    update public.timesheets t
    set current_document_version_id=v.id,document_state='READY',
        active_document_operation_id=case when t.active_document_operation_id=v.operation_id then null
          else t.active_document_operation_id end,
        updated_at=v_now
    from public.invoice_document_versions v
    where v.entity_type='TIMESHEET' and v.purpose='TIMESHEET' and v.status='READY'
      and v.operation_id in(select operation_id from scoped_operations)
      and t.timesheet_id=v.entity_id and t.document_revision::text=v.source_revision
    returning t.timesheet_id
  ),
  stale_invoice_pointers as (
    update public.invoices i
    set active_document_operation_id=case when exists(
          select 1 from public.invoice_operations od
          where od.id=i.active_document_operation_id
            and od.id in(select operation_id from scoped_operations)
            and od.status in(
              'COMPLETE','FAILED','DEAD_LETTER','CANCELLED','SUPERSEDED'))
          then null else i.active_document_operation_id end,
        active_issue_operation_id=case when exists(
          select 1 from public.invoice_operations oi
          where oi.id=i.active_issue_operation_id
            and oi.id in(select operation_id from scoped_operations)
            and oi.status in(
              'COMPLETE','FAILED','DEAD_LETTER','CANCELLED','SUPERSEDED'))
          then null else i.active_issue_operation_id end,
        updated_at=v_now
    where exists(
      select 1 from public.invoice_operations o
      where o.id in(select operation_id from scoped_operations)
        and o.status in('COMPLETE','FAILED','DEAD_LETTER','CANCELLED','SUPERSEDED')
        and o.id in(i.active_document_operation_id,i.active_issue_operation_id))
    returning i.id
  ),
  stale_timesheet_pointers as (
    update public.timesheets t
    set active_document_operation_id=null,updated_at=v_now
    from public.invoice_operations o
    where o.id=t.active_document_operation_id
      and o.id in(select operation_id from scoped_operations)
      and o.status in(
        'COMPLETE','FAILED','DEAD_LETTER','CANCELLED','SUPERSEDED')
    returning t.timesheet_id
  ),
  empty_operation_repair as (
    update public.invoice_operations o
    set status='FAILED',phase='FAILED',total_units=1,completed_units=0,
        failed_units=1,chunk_count=0,requires_user_action=true,
        failed_at_utc=coalesce(o.failed_at_utc,v_now),
        error_json=jsonb_build_object(
          'code','ACTIVE_OPERATION_WITHOUT_CHUNKS',
          'reconciled_at_utc',v_now),
        progress_json=coalesce(o.progress_json,'{}'::jsonb)||
          jsonb_build_object('total_units',1,'completed_units',0,
            'failed_units',1,'reconciled_at_utc',v_now),
        updated_at_utc=v_now,
        change_seq=nextval('public.invoice_operation_change_seq')
    where o.id in(select operation_id from scoped_operations)
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and not exists(select 1 from public.invoice_operation_chunks c
        where c.operation_id=o.id)
    returning o.id
  ),
  invalid_verify_completion as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        completed_at_utc=null,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','VERIFY_COMPLETED_WITHOUT_READY_DOCUMENT',
          'document_version_id',c.document_version_id,
          'reconciled_at_utc',v_now)
    where c.operation_id in(select operation_id from scoped_operations)
      and c.chunk_type='DOCUMENT_VERIFY' and c.status='COMPLETE'
      and not exists(
        select 1 from public.invoice_document_versions v
        where v.id=c.document_version_id and v.status='READY'
          and nullif(v.r2_key,'') is not null
          and nullif(v.sha256,'') is not null
          and coalesce(v.size_bytes,0)>0 and coalesce(v.page_count,0)>0)
    returning c.id,c.operation_id,c.document_version_id
  ),
  missing_manual_document_work as (
    update public.timesheets t
    set document_state='FAILED',
        last_document_error_json=jsonb_build_object(
          'code','READY_MANUAL_ASSET_WITHOUT_DOCUMENT_WORKFLOW',
          'reconciled_at_utc',v_now),
        updated_at=v_now
    where t.is_current and t.manual_document_asset_id is not null
      and exists(
        select 1
        from public.invoice_document_assets a
        where a.id=t.manual_document_asset_id and a.status='READY')
      and not exists(
        select 1
        from public.invoice_document_versions v
        where v.entity_type='TIMESHEET' and v.entity_id=t.timesheet_id
          and v.purpose='TIMESHEET'
          and v.source_revision=t.document_revision::text
          and v.status in(
            'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
            'VERIFYING','READY'))
      and (
        t.active_document_operation_id in(
          select operation_id from scoped_operations)
        or exists(
          select 1
          from public.timesheet_evidence e
          join public.invoice_document_assets a
            on a.id=e.document_asset_id and a.status='READY'
          where e.timesheet_id=t.timesheet_id
            and upper(coalesce(e.kind,''))='TIMESHEET'
            and a.operation_id in(
              select operation_id from scoped_operations)))
    returning t.timesheet_id
  ),
  invalid_policy_chunks as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','PROCESSOR_POLICY_INVALID',
          'policy_version',o.config_json#>>'{processor_policy,version}',
          'reconciled_at_utc',v_now)
    from public.invoice_operations o
    where c.operation_id=o.id
      and c.id in(select current_chunk_id from initial_current_chunks
        where current_chunk_id is not null
          and replacement_chain_status='VALID')
      and c.status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      and(
        jsonb_typeof(o.config_json->'processor_policy')<>'object'
        or o.config_json#>>'{processor_policy,version}'
          is distinct from 'INVOICE_PROCESSOR_LIMITS_V4'
        or o.config_json#>>'{processor_policy,policy_version}'
          is distinct from 'INVOICE_PROCESSOR_LIMITS_V4'
        or jsonb_typeof(o.config_json#>'{processor_policy,context}')
          <>'object'
        or jsonb_typeof(o.config_json#>'{processor_policy,result}')
          <>'object'
        or jsonb_typeof(o.config_json#>
          '{processor_policy,delivery,allowed_policies}')<>'array'
        or o.config_json#>'{processor_policy,delivery,allowed_policies}'
          is distinct from '["ATTACH","SPLIT","SECURE_LINK"]'::jsonb
        or o.config_json#>'{processor_policy,asset,allowed_media_types}'
          is distinct from '["application/pdf","image/jpeg","image/png"]'::jsonb
        or o.config_json#>>'{processor_policy,verify,object_receipt_contract}'
          is distinct from 'ACTUAL_BYTES_OBJECT_RECEIPT_V3'
        or o.config_json#>>'{processor_policy,verify,logical_receipt_contract}'
          is distinct from 'LOGICAL_SOURCE_RECEIPT_V3'
        or o.config_json#>>'{processor_policy,verify,merge_receipt_contract}'
          is distinct from 'ACTUAL_BYTES_MERGE_RECEIPT_V3'
        or o.config_json#>>'{processor_policy,verify,document_root_receipt_contract}'
          is distinct from 'DOCUMENT_ROOT_RECEIPT_V3'
        or o.config_json#>>'{processor_policy,verify,ordered_input_hash_contract}'
          is distinct from 'ACTUAL_ORDERED_INPUT_V1'
        or(c.chunk_type='ASSET_NORMALISE' and exists(
          select 1 from public.invoice_document_assets a
          where a.id=c.document_asset_id
            and(a.original_sha256 is null or a.original_size_bytes is null)))
        or(c.chunk_type='DOCUMENT_VERIFY' and c.payload_json ? 'immutable_destination_prefix'))
    returning c.id,c.operation_id
  ),
  invalid_request_correlation as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','REQUEST_CORRELATION_INVALID',
          'chunk_id',c.id,
          'request_key',case
            when c.chunk_type='DELIVERY_PREPARE'
              then c.payload_json->>'request_key'
            else c.payload_json#>>'{frozen_delivery_route,request_key}' end,
          'reconciled_at_utc',v_now)
    where c.id in(select current_chunk_id from initial_current_chunks
        where current_chunk_id is not null
          and replacement_chain_status='VALID')
      and(
        (c.chunk_type='DELIVERY_PREPARE'
          and c.payload_json->>'request_key' is distinct from c.id::text)
        or(c.chunk_type='ISSUE_INVOICE'
          and jsonb_typeof(c.payload_json->'frozen_delivery_route')='object'
          and c.payload_json#>>'{frozen_delivery_route,request_key}'
            is distinct from c.id::text))
    returning c.id,c.operation_id
  ),
  delivery_route_request_batch as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key',c.id::text,
      'invoice_id',c.entity_id,
      'recipient_set',coalesce(
        c.payload_json#>'{routing_request,recipient_set}',
        '[]'::jsonb),
      'cc',coalesce(c.payload_json#>'{routing_request,cc}',
        '[]'::jsonb),
      'bcc',coalesce(c.payload_json#>'{routing_request,bcc}',
        '[]'::jsonb),
      'delivery_policy',coalesce(
        c.payload_json#>>'{routing_request,delivery_policy}',
        c.payload_json#>>'{frozen_delivery_route,delivery_policy}',
        'ATTACH'),
      'template_version',coalesce(
        c.payload_json#>>'{routing_request,template_version}',
        c.payload_json#>>'{frozen_delivery_route,template_version}',
        'invoice-delivery-v1'))
      order by c.id),'[]'::jsonb) requests
    from initial_current_chunks current
    join public.invoice_operation_chunks c
      on c.id=current.current_chunk_id
    where current.replacement_chain_status='VALID'
      and c.chunk_type='DELIVERY_PREPARE'
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and c.entity_type='INVOICE' and c.entity_id is not null
  ),
  current_delivery_routes as materialized (
    select route.*
    from delivery_route_request_batch b
    cross join lateral private._invoice_delivery_routes_batch(
      b.requests,(v_now at time zone 'Europe/London')::date) route
  ),
  delivery_route_drift as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','DELIVERY_ROUTE_CHANGED',
          'frozen_route_policy_hash',
            c.payload_json#>>'{frozen_delivery_route,route_policy_hash}',
          'current_route_policy_hash',route.route_policy_hash,
          'frozen_route',jsonb_build_object(
            'to',c.payload_json#>'{frozen_delivery_route,to}',
            'cc',c.payload_json#>'{frozen_delivery_route,cc}',
            'bcc',c.payload_json#>'{frozen_delivery_route,bcc}',
            'delivery_suppressed',c.payload_json#>
              '{frozen_delivery_route,delivery_suppressed}'),
          'current_route',jsonb_build_object(
            'to',route.canonical_to,'cc',route.canonical_cc,
            'bcc',route.canonical_bcc,
            'delivery_suppressed',route.delivery_suppressed,
            'suppression_reason',route.suppression_reason),
          'reconciled_at_utc',v_now)
    from current_delivery_routes route
    where c.id=route.request_key::uuid
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      and c.payload_json#>>'{frozen_delivery_route,route_policy_hash}'
        is distinct from route.route_policy_hash
    returning c.id,c.operation_id
  ),
  invalid_pagination_contracts as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','ATTACHMENT_INDEX_PAGINATION_CONTRACT_INVALID',
          'reconciled_at_utc',v_now)
    where c.id in(select current_chunk_id from initial_current_chunks
        where current_chunk_id is not null
          and replacement_chain_status='VALID')
      and c.chunk_type='SOURCE_RENDER' and c.status='COMPLETE'
      and c.payload_json->>'render_kind'='ATTACHMENT_INDEX'
      and c.payload_json->>'layout_phase'='FINAL'
      and(
        jsonb_typeof(c.payload_json->'pagination_stream')<>'array'
        or coalesce(c.payload_json->>'pagination_stream_hash','')<>
          encode(digest(coalesce(c.payload_json->'pagination_stream',
            '[]'::jsonb)::text,'sha256'),'hex')
        or c.result_json->>'displayed_start_pages_hash'
          is distinct from c.payload_json->>'expected_start_pages_hash'
        or jsonb_typeof(c.result_json->'displayed_page_map')<>'array'
        or c.result_json->'displayed_page_map'
          is distinct from c.payload_json->'attachments'
        or encode(digest(coalesce(c.result_json->'displayed_page_map',
            '[]'::jsonb)::text,'sha256'),'hex')
          is distinct from c.payload_json->>'expected_start_pages_hash'
        or c.result_json->>'final_index_page_count'
          is distinct from c.result_json->>'page_count'
        or c.result_json->>'pagination_stream_hash'
          is distinct from c.payload_json->>'pagination_stream_hash'
        or c.result_json->>'layout_identity_hash'
          is distinct from encode(digest(coalesce(
            c.payload_json->'determinism','{}'::jsonb)::text,
            'sha256'),'hex'))
    returning c.id,c.operation_id
  ),
  invalid_root_receipts as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','ROOT_MERGE_RECEIPT_CONTRACT_INVALID',
          'reconciled_at_utc',v_now)
    where c.id in(select current_chunk_id from initial_current_chunks
        where current_chunk_id is not null
          and replacement_chain_status='VALID')
      and c.chunk_type='PDF_MERGE' and c.status='COMPLETE'
      and(
        c.result_json#>>'{merge_receipt,receipt_contract}'
          is distinct from 'ACTUAL_BYTES_MERGE_RECEIPT_V3'
        or c.result_json#>>
            '{merge_receipt,combined_logical_receipt_root}'
          is distinct from
            c.payload_json->>'expected_logical_receipt_root'
        or c.result_json#>>
            '{merge_receipt,combined_physical_receipt_root}'
          is distinct from
            c.payload_json->>'expected_physical_receipt_root'
        or c.result_json#>>'{merge_receipt,actual_child_receipt_hash}'
          is distinct from c.payload_json->>'expected_child_receipt_hash'
        or jsonb_typeof(c.result_json#>'{merge_receipt,physical_receipts}')
          <>'array'
        or c.result_json#>'{merge_receipt,physical_receipts}'
          is distinct from coalesce(c.payload_json->'expected_physical_receipts',
            '[]'::jsonb)
        or c.result_json#>>'{merge_receipt,combined_physical_receipt_root}'
          is distinct from coalesce((
            select encode(digest(string_agg(
              receipt.value->>'physical_receipt','||'
              order by receipt.ordinality),'sha256'),'hex')
            from jsonb_array_elements(coalesce(c.result_json#>
              '{merge_receipt,physical_receipts}','[]'::jsonb))
              with ordinality receipt(value,ordinality)),''))
    returning c.id,c.operation_id
  ),
  invalid_self_bill_suppression as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',completed_at_utc=null,
        failed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','DELIVERY_SUPPRESSION_POLICY_INVALID',
          'detail','Raw self-bill state suppressed delivery without policy authority',
          'reconciled_at_utc',v_now)
    where c.id in(select current_chunk_id from initial_current_chunks
        where current_chunk_id is not null
          and replacement_chain_status='VALID')
      and c.chunk_type='DELIVERY_PREPARE' and c.status='COMPLETE'
      and lower(coalesce(c.result_json->>'delivery_skipped','false'))
        in('true','t','1','yes')
      and lower(coalesce(c.payload_json#>>
          '{frozen_delivery_route,self_bill}','false'))
        in('true','t','1','yes')
      and lower(coalesce(c.payload_json#>>
          '{frozen_delivery_route,delivery_suppressed}','false'))
        not in('true','t','1','yes')
    returning c.id,c.operation_id
  ),
  missing_delivery_children as (
    update public.invoice_operation_chunks c
    set status='QUEUED',phase='QUEUE_DELIVERY',completed_at_utc=null,
        failed_at_utc=null,run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','DELIVERY_DELEGATION_MISSING',
          'invoice_id',c.entity_id,'reconciled_at_utc',v_now)
    where c.id in(select current_chunk_id from initial_current_chunks
        where current_chunk_id is not null
          and replacement_chain_status='VALID'
          and chunk_type='ISSUE_INVOICE')
      and c.status='COMPLETE'
      and lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes')
      and c.payload_json#>>'{frozen_delivery_route,request_key}'=c.id::text
      and not exists(
        select 1
        from public.invoice_operations d
        join public.invoice_operation_chunks dc on dc.operation_id=d.id
        where d.parent_operation_id=c.operation_id
          and d.operation_type='DELIVER_INVOICES'
          and dc.chunk_type='DELIVERY_PREPARE'
          and dc.entity_type='INVOICE' and dc.entity_id=c.entity_id
          and dc.document_version_id=c.document_version_id
          and dc.status not in('CANCELLED','SUPERSEDED'))
    returning c.id,c.operation_id
  ),
  scoped_mail_ids as materialized (
    select distinct x.value::uuid mail_id
    from initial_current_chunks c
    cross join lateral jsonb_array_elements_text(
      case when jsonb_typeof(c.result_json->'mail_outbox_ids')='array'
        then c.result_json->'mail_outbox_ids' else '[]'::jsonb end) x(value)
    where x.value~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    union
    select distinct(c.result_json->>'mail_outbox_id')::uuid
    from initial_current_chunks c
    where coalesce(c.result_json->>'mail_outbox_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  stuck_secure_mail as (
    update public.mail_outbox m
    set status='FAILED',failed_at=v_now,
        last_error='SECURE_LINK_DESCRIPTOR_MISMATCH',
        attempt_lease_token=null,attempt_leased_at_utc=null,
        attempt_lease_expires_at_utc=null
    where m.id in(select mail_id from scoped_mail_ids)
      and upper(coalesce(m.type,''))='INVOICE'
      and m.status='QUEUED'
      and upper(coalesce(m.attachment_delivery_policy,''))='SECURE_LINK'
      and(
        jsonb_typeof(m.attachments)<>'array'
        or jsonb_array_length(case when jsonb_typeof(m.attachments)='array'
          then m.attachments else '[]'::jsonb end)=0
        or exists(
          select 1
          from jsonb_array_elements(
            case when jsonb_typeof(m.attachments)='array'
              then m.attachments else '[]'::jsonb end) a
          where upper(coalesce(a->>'delivery_mode',''))<>'SECURE_LINK'
            or lower(coalesce(a->>'secure_link_required','false'))
              not in('true','t','1','yes')
            or nullif(a->>'r2_key','') is not null
            or nullif(a->>'sha256','') is null
            or coalesce(a->>'size_bytes','')!~'^[1-9][0-9]{0,17}$'
            or coalesce(a->>'page_count','')!~'^[1-9][0-9]{0,8}$'))
    returning m.id
  ),
  scoped_invoice_ids as materialized (
    select distinct c.entity_id invoice_id
    from initial_current_chunks c
    where c.entity_type='INVOICE' and c.entity_id is not null
    union
    select distinct(c.result_json->>'invoice_id')::uuid
    from initial_current_chunks c
    where coalesce(c.result_json->>'invoice_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  correction_reconcile_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','reconcile-correction:'||i.invoice_id::text,
      'scope_key',i.invoice_id::text,
      'invoice_id',i.invoice_id,
      'validation_purpose','RECONCILE') order by i.invoice_id),
      '[]'::jsonb) scopes
    from scoped_invoice_ids i
  ),
  correction_unit_anomalies as materialized (
    select validation.invoice_id,validation.timesheet_id,
      validation.blocker_code,validation.blocker_codes,
      validation.detail_json
    from correction_reconcile_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) validation
    where not validation.valid
  ),
  historical_summary_contamination as materialized (
    select distinct o.id operation_id
    from public.invoice_operations o
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(o.result_json->'issue_outcomes')='array'
        then o.result_json->'issue_outcomes'
        else '[]'::jsonb end) outcome(value)
    where o.id in(select operation_id from scoped_operations)
      and coalesce(outcome.value->>'chunk_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and not exists(
        select 1 from initial_current_chunks current
        where current.operation_id=o.id
          and current.current_chunk_id=
            (outcome.value->>'chunk_id')::uuid
          and current.replacement_chain_status='VALID')
  ),
  oversized_parent_progress as materialized (
    select distinct o.id operation_id
    from public.invoice_operations o
    where o.id in(select operation_id from scoped_operations)
      and(
        pg_column_size(coalesce(o.progress_json,'{}'::jsonb))>524288
        or exists(
          select 1
          from jsonb_array_elements(case when jsonb_typeof(
              o.progress_json#>'{child_operations,rows}')='array'
            then o.progress_json#>'{child_operations,rows}'
            else '[]'::jsonb end) child(value)
          where child.value ?| array['result','error','progress']))
  ),  current_chunks as materialized (
    select g.*
    from scoped_operation_pages p
    cross join lateral private._invoice_current_chunks_batch(
      p.operation_ids,null,null,10000) g
  ),
  aggregates as materialized (
    select c.operation_id,count(*)::integer total,
      count(*) filter(where c.current_status='COMPLETE')::integer completed,
      count(*) filter(where c.current_status in(
        'FAILED','DEAD_LETTER','BLOCKED')
        or c.replacement_chain_status='INVALID')::integer failed,
      bool_or(c.current_status in('QUEUED','RUNNING','WAITING','RETRY_WAIT'))
        filter(where c.replacement_chain_status='VALID') active,
      bool_or(c.current_status='DEAD_LETTER') dead,
      bool_or(c.current_status='BLOCKED'
        or c.replacement_chain_status='INVALID') blocked
    from current_chunks c
    group by c.operation_id
  ),
  parent_repair as (
    update public.invoice_operations o
    set total_units=a.total,chunk_count=a.total,completed_units=a.completed,failed_units=a.failed,
        status=case
          when a.dead and not a.active then 'DEAD_LETTER'
          when a.blocked and not a.active then 'BLOCKED'
          when not a.active and a.failed>0 then 'FAILED'
          when not a.active then 'COMPLETE'
          when a.active and not a.dead and not a.blocked
            and o.status in('FAILED','DEAD_LETTER','BLOCKED') then 'QUEUED'
          else o.status end,
        phase=case
          when not a.active and a.failed=0 then 'COMPLETE'
          when a.active and not a.dead and not a.blocked
            and o.status in('FAILED','DEAD_LETTER','BLOCKED') then 'WAIT_FOR_INPUTS'
          else o.phase end,
        requires_user_action=(a.dead or a.blocked),
        completed_at_utc=case when not a.active and a.failed=0
          then coalesce(o.completed_at_utc,v_now) else o.completed_at_utc end,
        failed_at_utc=case when not a.active and a.failed>0
          then coalesce(o.failed_at_utc,v_now)
          when a.active and not a.dead and not a.blocked then null
          else o.failed_at_utc end,
        progress_json=coalesce(o.progress_json,'{}'::jsonb)||jsonb_build_object(
          'total_units',a.total,'completed_units',a.completed,'failed_units',a.failed,
          'reconciled_at_utc',v_now),
        updated_at_utc=v_now,change_seq=nextval('public.invoice_operation_change_seq')
    from aggregates a
    where o.id=a.operation_id
      and o.status not in('CANCELLED','SUPERSEDED')
    returning o.id
  ),
  rollup_repair as materialized (
    select r.*
    from scoped_operation_pages p
    cross join lateral private._invoice_operation_rollup_batch(
      p.operation_ids,v_now,true) r
  ),
  repair_counts as materialized (
    select
      (select count(*) from invalid_normalise_chunks)
        invalid_normalise_chunks,
      (select count(*) from failed_current_range_assets)
        failed_current_range_assets,
      (select count(*) from invalid_asset_evidence)
        invalid_asset_evidence,
      (select count(*) from invalid_running) invalid_running,
      (select count(*) from cancelled_orphans) cancelled_orphans,
      (select count(*) from ready_dependencies) ready_dependencies,
      (select count(*) from failed_dependencies) failed_dependencies,
      (select count(*) from plan_wake) document_plans_woken,
      (select count(*) from issue_wake) issue_chunks_woken,
      (select count(*) from invoice_ready_pointers) invoice_pointers_repaired,
      (select count(*) from timesheet_ready_pointers) timesheet_pointers_repaired,
      (select count(*) from stale_invoice_pointers) stale_pointers_cleared,
      (select count(*) from stale_timesheet_pointers)
        stale_timesheet_pointers_cleared,
      (select count(*) from empty_operation_repair) empty_operations_failed,
      (select count(*) from replacement_graph_validation)
        invalid_replacement_chains,
      (select coalesce(jsonb_agg(jsonb_build_object(
          'operation_id',operation_id,
          'logical_slot_key',logical_slot_key,
          'error',replacement_chain_error)
          order by operation_id,logical_slot_key),'[]'::jsonb)
       from replacement_graph_validation)
        invalid_replacement_chain_details,
      (select count(*) from invalid_verify_completion)
        invalid_verify_completions,
      (select count(*) from missing_manual_document_work)
        missing_manual_document_workflows,
      (select count(*) from invalid_policy_chunks)
        invalid_processor_policy_chunks,
      (select count(*) from invalid_request_correlation)
        invalid_request_correlations,
      (select count(*) from delivery_route_drift)
        delivery_route_drift_blocked,
      (select count(*) from invalid_pagination_contracts)
        invalid_pagination_contracts_blocked,
      (select count(*) from invalid_root_receipts)
        invalid_root_receipts_blocked,
      (select count(*) from invalid_self_bill_suppression)
        invalid_self_bill_suppressions_blocked,
      (select count(*) from missing_delivery_children)
        missing_delivery_children_requeued,
      (select count(*) from stuck_secure_mail)
        secure_link_mail_failed,
      (select count(*) from correction_unit_anomalies)
        correction_unit_anomalies_reported,
      (select count(*) from historical_summary_contamination)
        historical_summary_contamination_repaired,
      (select count(*) from oversized_parent_progress)
        oversized_parent_progress_repaired,
      (select count(*) from parent_repair) parent_operations_repaired,
      (select count(*) from rollup_repair) operations_rolled_up
  ),
  completed_reconcile as (
    update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        result_json=jsonb_build_object(
          'reconciled_at_utc',v_now,
          'scope_operation_count',(select count(*) from scoped_operations),
          'request_scope_operation_count',(select count(*) from scope s
            where s.reconcile_chunk_id=c.id),
          'requested_explicit_operation_count',rc.explicit_operation_count,
          'scope_truncated',rc.explicit_operation_count>500,
          'repairs',to_jsonb(r)),
        error_json=null
    from repair_counts r
    cross join reconcile_claims rc
    where rc.reconcile_chunk_id=c.id
    returning c.id,c.operation_id,c.result_json
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'operation_id',operation_id,'status','COMPLETE',
    'phase','COMPLETE','result',result_json
  )),'[]'::jsonb) into v_result from completed_reconcile;

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

-- private._invoice_reference_rows_batch(uuid[])
CREATE OR REPLACE FUNCTION private._invoice_reference_rows_batch(p_invoice_ids uuid[])
 RETURNS TABLE(invoice_id uuid, timesheet_id uuid, sheet_scope text, submission_mode text, ref_target text, segment_id text, day_ymd text, start_utc text, end_utc text, current_reference text, is_required boolean, row_key text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
with requested as materialized (
  select distinct x.invoice_id
  from unnest(coalesce(p_invoice_ids,array[]::uuid[])) x(invoice_id)
  where x.invoice_id is not null
),
invoice_timesheets as materialized (
  select l.invoice_id,l.timesheet_id,
    sum(case when upper(coalesce(l.meta_json->>'line_type','')) in(
      'HOURS_DAILY','HOURS_WEEKLY','ADDITIONAL_RATE','ADDITIONAL_RATE_DAILY')
      then coalesce(l.total_charge_ex_vat,0) else 0 end) worked_charge_ex,
    sum(case when upper(coalesce(l.meta_json->>'line_type','')) in(
      'HOURS_DAILY','HOURS_WEEKLY')
      then coalesce(l.hours_day,0)+coalesce(l.hours_night,0)+coalesce(l.hours_sat,0)
        +coalesce(l.hours_sun,0)+coalesce(l.hours_bh,0) else 0 end) worked_hours
  from requested r
  join public.invoice_lines l on l.invoice_id=r.invoice_id
  where l.timesheet_id is not null
  group by l.invoice_id,l.timesheet_id
  having sum(case when upper(coalesce(l.meta_json->>'line_type','')) in(
      'HOURS_DAILY','HOURS_WEEKLY','ADDITIONAL_RATE','ADDITIONAL_RATE_DAILY')
      then coalesce(l.total_charge_ex_vat,0) else 0 end)>0
    or sum(case when upper(coalesce(l.meta_json->>'line_type','')) in(
      'HOURS_DAILY','HOURS_WEEKLY')
      then coalesce(l.hours_day,0)+coalesce(l.hours_night,0)+coalesce(l.hours_sat,0)
        +coalesce(l.hours_sun,0)+coalesce(l.hours_bh,0) else 0 end)>0
),
base as materialized (
  select it.invoice_id,t.timesheet_id,t.sheet_scope::text sheet_scope,
    t.submission_mode::text submission_mode,t.reference_number,t.week_ending_date,
    t.worked_start_iso,t.worked_end_iso,t.scheduled_start_iso,t.scheduled_end_iso,
    t.actual_schedule_json,t.day_references_json,f.invoice_breakdown_json,
    coalesce(pc.require_reference_to_invoice,false)
      or coalesce(pc.reference_number_required_to_issue_invoice,false) is_required
  from invoice_timesheets it
  join public.timesheets t on t.timesheet_id=it.timesheet_id and t.is_current
  left join public.timesheets_financials f
    on f.timesheet_id=t.timesheet_id and f.is_current
  left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
),
segment_rows as materialized (
  select b.invoice_id,b.timesheet_id,b.sheet_scope,b.submission_mode,'SEGMENT'::text ref_target,
    coalesce(nullif(btrim(s.value->>'segment_id'),''),
      case when nullif(btrim(s.value->>'start_utc'),'') is not null
         and nullif(btrim(s.value->>'end_utc'),'') is not null
        then 'SE:'||(s.value->>'start_utc')||'|'||(s.value->>'end_utc') end) segment_id,
    coalesce(nullif(btrim(s.value->>'date'),''),
      case when coalesce(s.value->>'start_utc','')~
        '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
        then left(s.value->>'start_utc',10) end)
      day_ymd,
    nullif(btrim(s.value->>'start_utc'),'') start_utc,
    nullif(btrim(s.value->>'end_utc'),'') end_utc,
    nullif(btrim(s.value->>'ref_num'),'') current_reference,b.is_required
  from base b
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
      then b.invoice_breakdown_json->'segments' else '[]'::jsonb end) s(value)
  where upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
    and nullif(btrim(s.value->>'invoice_locked_invoice_id'),'')=b.invoice_id::text
    and(
      case when coalesce(s.value->>'charge_amount','')~
        '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        then (s.value->>'charge_amount')::numeric else 0 end>0
      or
      (select sum(case when coalesce(v,'')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then v::numeric else 0 end)
       from (values(s.value->>'hours_day'),(s.value->>'hours_night'),
         (s.value->>'hours_sat'),(s.value->>'hours_sun'),
         (s.value->>'hours_bh')) h(v))>0
    )
),
manual_rows as materialized (
  select b.invoice_id,b.timesheet_id,b.sheet_scope,b.submission_mode,'SEGMENT'::text ref_target,
    'ts:'||b.timesheet_id::text||':'||(s.ordinality-1)::text segment_id,
    nullif(btrim(s.value->>'date'),'') day_ymd,
    nullif(btrim(s.value->>'start_utc'),'') start_utc,
    nullif(btrim(s.value->>'end_utc'),'') end_utc,
    nullif(btrim(s.value->>'ref_num'),'') current_reference,b.is_required
  from base b
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(b.actual_schedule_json)='array'
      then b.actual_schedule_json else '[]'::jsonb end)
    with ordinality s(value,ordinality)
  where upper(coalesce(b.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
    and b.sheet_scope='WEEKLY' and b.submission_mode='MANUAL'
    and nullif(btrim(s.value->>'start'),'') is not null
    and nullif(btrim(s.value->>'end'),'') is not null
),
weekly_rows as materialized (
  select b.invoice_id,b.timesheet_id,b.sheet_scope,b.submission_mode,'FREEFORM'::text ref_target,
    null::text segment_id,nullif(btrim(j.key),'') day_ymd,null::text start_utc,
    null::text end_utc,nullif(btrim(j.value),'') current_reference,b.is_required
  from base b
  cross join lateral jsonb_each_text(
    case when jsonb_typeof(b.day_references_json)='object'
      then b.day_references_json else '{}'::jsonb end) j(key,value)
  where upper(coalesce(b.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
    and b.sheet_scope='WEEKLY' and b.submission_mode<>'MANUAL'
    and left(coalesce(j.key,''),2)<>'__'
),
freeform_rows as materialized (
  select b.invoice_id,b.timesheet_id,b.sheet_scope,b.submission_mode,
    'FREEFORM'::text ref_target,
    'freeform:'||(f.ordinality-1)::text segment_id,
    null::text day_ymd,null::text start_utc,null::text end_utc,
    nullif(btrim(case
      when jsonb_typeof(f.value)='string' then f.value#>>'{}'
      when jsonb_typeof(f.value)='object' then coalesce(
        f.value->>'reference',f.value->>'ref_num',f.value->>'value')
    end),'') current_reference,b.is_required
  from base b
  cross join lateral jsonb_array_elements(
    case
      when jsonb_typeof(b.day_references_json)='array'
        then b.day_references_json
      when jsonb_typeof(b.day_references_json)='object'
        and jsonb_typeof(b.day_references_json->'__freeform_refs')='array'
        then b.day_references_json->'__freeform_refs'
      when jsonb_typeof(b.day_references_json)='object'
        and jsonb_typeof(b.day_references_json->'__freeform')='array'
        then b.day_references_json->'__freeform'
      when jsonb_typeof(b.day_references_json)='object'
        and jsonb_typeof(b.day_references_json->'__freeform_lines')='array'
        then b.day_references_json->'__freeform_lines'
      else '[]'::jsonb
    end
  ) with ordinality f(value,ordinality)
  where upper(coalesce(b.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
    and b.sheet_scope='WEEKLY' and b.submission_mode<>'MANUAL'
    and nullif(btrim(case
      when jsonb_typeof(f.value)='string' then f.value#>>'{}'
      when jsonb_typeof(f.value)='object' then coalesce(
        f.value->>'reference',f.value->>'ref_num',f.value->>'value')
    end),'') is not null
),
fallback_rows as materialized (
  select b.invoice_id,b.timesheet_id,b.sheet_scope,b.submission_mode,'TIMESHEET'::text ref_target,
    null::text segment_id,
    coalesce(
      (b.worked_start_iso at time zone 'Europe/London')::date::text,
      (b.scheduled_start_iso at time zone 'Europe/London')::date::text,
      b.week_ending_date::text) day_ymd,
    coalesce(to_jsonb(b.worked_start_iso)#>>'{}',
      to_jsonb(b.scheduled_start_iso)#>>'{}') start_utc,
    coalesce(to_jsonb(b.worked_end_iso)#>>'{}',
      to_jsonb(b.scheduled_end_iso)#>>'{}') end_utc,
    nullif(btrim(b.reference_number),'') current_reference,b.is_required
  from base b
  where upper(coalesce(b.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
    and not(b.sheet_scope='WEEKLY' and b.submission_mode='MANUAL'
      and jsonb_typeof(b.actual_schedule_json)='array')
    and not(b.sheet_scope='WEEKLY' and b.submission_mode<>'MANUAL'
      and jsonb_typeof(b.day_references_json) in('object','array'))
),
all_rows as (
  select * from segment_rows
  union all select * from manual_rows
  union all select * from weekly_rows
  union all select * from freeform_rows
  union all select * from fallback_rows
)
select a.invoice_id,a.timesheet_id,a.sheet_scope,a.submission_mode,a.ref_target,
  a.segment_id,a.day_ymd,a.start_utc,a.end_utc,a.current_reference,a.is_required,
  a.timesheet_id::text||'|'||coalesce(a.ref_target,'')||'|'||
    coalesce(a.segment_id,'')||'|'||coalesce(a.day_ymd,'')||'|'||
    coalesce(a.start_utc,'')||'|'||coalesce(a.end_utc,'') row_key
from all_rows a
order by a.invoice_id,a.timesheet_id,a.day_ymd nulls last,
  a.start_utc nulls last,a.segment_id nulls last;
$function$;

-- private._invoice_result_page_revision_trigger_v2()
CREATE OR REPLACE FUNCTION private._invoice_result_page_revision_trigger_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_root_id uuid;
  v_stamp bigint;
begin
  if tg_op = 'INSERT' then
    for v_root_id in
      select distinct n.operation_id
      from new_rows n
      where n.chunk_type in ('GENERATION_GROUP','ISSUE_INVOICE')
        and n.result_visible
        and n.operation_id is not null
      order by n.operation_id
    loop
      perform 1
      from public.invoice_operations o
      where o.id = v_root_id
      for update;

      v_stamp := nextval(
        'public.invoice_operation_change_seq'::regclass
      );

      update public.invoice_operations o
      set result_page_revision = greatest(
            o.result_page_revision,
            v_stamp
          ),
          change_seq = greatest(o.change_seq, v_stamp),
          updated_at_utc = statement_timestamp()
      where o.id = v_root_id;
    end loop;
  elsif tg_op = 'DELETE' then
    for v_root_id in
      select distinct prior.operation_id
      from old_rows prior
      where prior.chunk_type in ('GENERATION_GROUP','ISSUE_INVOICE')
        and prior.result_visible
        and prior.operation_id is not null
      order by prior.operation_id
    loop
      perform 1
      from public.invoice_operations o
      where o.id = v_root_id
      for update;

      v_stamp := nextval(
        'public.invoice_operation_change_seq'::regclass
      );

      update public.invoice_operations o
      set result_page_revision = greatest(
            o.result_page_revision,
            v_stamp
          ),
          change_seq = greatest(o.change_seq, v_stamp),
          updated_at_utc = statement_timestamp()
      where o.id = v_root_id;
    end loop;
  else
    for v_root_id in
      select distinct coalesce(n.operation_id, o.operation_id) operation_id
      from old_rows o
      full join new_rows n on n.id = o.id
      where coalesce(n.chunk_type, o.chunk_type) in ('GENERATION_GROUP','ISSUE_INVOICE')
        and (
          n.result_visible is distinct from o.result_visible
          or n.selection_key is distinct from o.selection_key
          or n.result_category is distinct from o.result_category
          or n.document_version_id is distinct from o.document_version_id
          or n.replaced_by_chunk_id is distinct from o.replaced_by_chunk_id
          or n.manifest_generation is distinct from o.manifest_generation
        )
        and (coalesce(n.result_visible, false) or coalesce(o.result_visible, false))
        and coalesce(n.operation_id, o.operation_id) is not null
      order by coalesce(n.operation_id, o.operation_id)
    loop
      perform 1
      from public.invoice_operations root_operation
      where root_operation.id = v_root_id
      for update;

      v_stamp := nextval(
        'public.invoice_operation_change_seq'::regclass
      );

      update public.invoice_operations root_operation
      set result_page_revision = greatest(
            root_operation.result_page_revision,
            v_stamp
          ),
          change_seq = greatest(root_operation.change_seq, v_stamp),
          updated_at_utc = statement_timestamp()
      where root_operation.id = v_root_id;
    end loop;
  end if;

  return null;
end;
$function$;

-- private._invoice_segment_lock_batch(jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._invoice_segment_lock_batch(p_targets jsonb, p_now_utc timestamp with time zone)
 RETURNS TABLE(invoice_id uuid, timesheet_id uuid, success boolean, locked_segment_count integer, blocker_code text, detail_json jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
begin
  return query
  with raw as materialized (
    select x.ordinality,
      case when coalesce(x.value->>'invoice_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (x.value->>'invoice_id')::uuid end invoice_id,
      case when coalesce(x.value->>'timesheet_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (x.value->>'timesheet_id')::uuid end timesheet_id,
      nullif(x.value->>'expected_financial_revision','') expected_revision,
      array(select distinct btrim(s.value)
        from jsonb_array_elements_text(
          case when jsonb_typeof(x.value->'segment_ids')='array'
            then x.value->'segment_ids' else '[]'::jsonb end) s(value)
        where nullif(btrim(s.value),'') is not null) segment_ids
    from jsonb_array_elements(
      case when jsonb_typeof(p_targets)='array' then p_targets else '[]'::jsonb end)
      with ordinality x(value,ordinality)
  ),
  targets as materialized (
    select distinct on (r.invoice_id,r.timesheet_id) r.*,
      f.id financial_id,f.invoice_breakdown_json,
      encode(digest(jsonb_build_object(
        'financial_id',f.id,'timesheet_version',f.timesheet_version,
        'updated_at',f.updated_at,'basis',f.basis,
        'invoice_breakdown_json',f.invoice_breakdown_json)::text,'sha256'),'hex')
        current_revision
    from raw r
    left join public.timesheets_financials f
      on f.timesheet_id=r.timesheet_id and f.is_current
    where r.invoice_id is not null and r.timesheet_id is not null
    order by r.invoice_id,r.timesheet_id,r.ordinality
  ),
  segments as materialized (
    select t.*,s.ordinality segment_ordinality,
      s.value segment,
      coalesce(nullif(btrim(s.value->>'segment_id'),''),
        'SE:'||coalesce(s.value->>'start_utc','')||'|'||
          coalesce(s.value->>'end_utc','')) segment_key
    from targets t
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(t.invoice_breakdown_json->'segments')='array'
        then t.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      with ordinality s(value,ordinality)
  ),
  validation as materialized (
    select t.invoice_id,t.timesheet_id,t.financial_id,t.invoice_breakdown_json,
      t.current_revision,t.expected_revision,t.segment_ids,
      count(s.segment_key) filter(where s.segment_key=any(t.segment_ids)) selected_count,
      array_agg(s.segment_key order by s.segment_ordinality)
        filter(where s.segment_key=any(t.segment_ids)
          and nullif(btrim(s.segment->>'invoice_locked_invoice_id'),'') is not null
          and s.segment->>'invoice_locked_invoice_id'<>t.invoice_id::text)
        conflicting_keys
    from targets t
    left join segments s on s.invoice_id=t.invoice_id
      and s.timesheet_id=t.timesheet_id
    group by t.invoice_id,t.timesheet_id,t.financial_id,t.invoice_breakdown_json,
      t.current_revision,t.expected_revision,t.segment_ids
  ),
  classified as materialized (
    select v.*,
      case
        when v.financial_id is null then 'CURRENT_FINANCIAL_NOT_FOUND'
        when cardinality(v.segment_ids)=0 then 'SEGMENT_IDS_REQUIRED'
        when v.expected_revision is not null
          and v.expected_revision<>v.current_revision then 'SOURCE_REVISION_CHANGED'
        when v.selected_count<>cardinality(v.segment_ids) then 'SEGMENT_NOT_FOUND'
        when cardinality(coalesce(v.conflicting_keys,array[]::text[]))>0
          then 'SEGMENT_ALREADY_LOCKED'
      end blocker
    from validation v
  ),
  rebuilt as materialized (
    select c.invoice_id,c.timesheet_id,c.financial_id,
      jsonb_set(c.invoice_breakdown_json,'{segments}',
        jsonb_agg(
          case when s.segment_key=any(c.segment_ids)
            then s.segment||jsonb_build_object(
              'invoice_locked_invoice_id',c.invoice_id::text,
              'invoice_locked_at_utc',
                coalesce(p_now_utc,now())::text)
            else s.segment end order by s.segment_ordinality),true) new_breakdown,
      cardinality(c.segment_ids) locked_count
    from classified c
    join segments s on s.invoice_id=c.invoice_id
      and s.timesheet_id=c.timesheet_id
    where c.blocker is null
    group by c.invoice_id,c.timesheet_id,c.financial_id,
      c.invoice_breakdown_json,c.segment_ids
  ),
  changed as materialized (
    update public.timesheets_financials f
    set invoice_breakdown_json=r.new_breakdown,
      locked_by_invoice_id=case
        when not exists(
          select 1
          from jsonb_array_elements(r.new_breakdown->'segments') s(value)
          where nullif(btrim(s.value->>'invoice_locked_invoice_id'),'') is null)
        then r.invoice_id else f.locked_by_invoice_id end,
      locked_at_utc=case
        when f.locked_at_utc is null then coalesce(p_now_utc,now())
        else f.locked_at_utc end,
      updated_at=coalesce(p_now_utc,now())
    from rebuilt r
    where f.id=r.financial_id
    returning r.invoice_id,r.timesheet_id,r.locked_count
  )
  select c.invoice_id,c.timesheet_id,(c.blocker is null and ch.invoice_id is not null),
    coalesce(ch.locked_count,0)::integer,c.blocker,
    jsonb_build_object(
      'expected_segment_ids',to_jsonb(c.segment_ids),
      'selected_segment_count',c.selected_count,
      'conflicting_segment_ids',
        to_jsonb(coalesce(c.conflicting_keys,array[]::text[])),
      'expected_financial_revision',c.expected_revision,
      'current_financial_revision',c.current_revision)
  from classified c
  left join changed ch on ch.invoice_id=c.invoice_id
    and ch.timesheet_id=c.timesheet_id;
end;
$function$;

-- private._invoice_source_reference_validate_batch(jsonb)
CREATE OR REPLACE FUNCTION private._invoice_source_reference_validate_batch(p_source_members jsonb)
 RETURNS TABLE(source_member_key text, source_type text, source_id uuid, timesheet_id uuid, segment_id text, reference_ready boolean, blocker_code text, reference_source text, reference_hash text, current_revision text, detail_json jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
with supplied as materialized (
  select e.ordinality::integer member_no,e.value member,
    upper(btrim(coalesce(e.value->>'source_type','TIMESHEET'))) source_type,
    case when coalesce(e.value->>'source_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(e.value->>'source_id')::uuid end source_id,
    case when coalesce(e.value->>'related_timesheet_id',
        e.value->>'timesheet_id',e.value->>'source_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then coalesce(e.value->>'related_timesheet_id',
        e.value->>'timesheet_id',e.value->>'source_id')::uuid end timesheet_id,
    nullif(btrim(coalesce(e.value->>'segment_id','')),'') segment_id,
    coalesce(nullif(btrim(e.value->>'source_member_key'),''),
      encode(digest(concat_ws('|',
        upper(btrim(coalesce(e.value->>'source_type','TIMESHEET'))),
        coalesce(e.value->>'related_timesheet_id',
          e.value->>'timesheet_id',e.value->>'source_id',''),
        coalesce(nullif(btrim(e.value->>'segment_id'),''),'WHOLE'),
        coalesce(e.value->>'target_invoice_week','')),'sha256'),'hex'))
      source_member_key,
    nullif(btrim(coalesce(e.value->>'row_revision',
      e.value->>'source_revision','')),'') expected_revision,
    nullif(btrim(e.value->>'target_invoice_week'),'')
      target_invoice_week,
    upper(coalesce(nullif(btrim(e.value->>'invoice_stream'),''),
      'NORMAL')) invoice_stream,
    upper(coalesce(nullif(btrim(e.value->>'consolidation_mode'),''),
      'NONE')) consolidation_mode
  from jsonb_array_elements(case
    when jsonb_typeof(p_source_members)='array' then p_source_members
    else '[]'::jsonb end) with ordinality e(value,ordinality)
  where jsonb_typeof(e.value)='object'
),
authoritative as materialized (
  select s.*,t.sheet_scope::text sheet_scope,
    t.submission_mode::text submission_mode,t.reference_number,
    t.day_references_json,t.actual_schedule_json,t.version,
    t.updated_at,t.is_current,t.revoked_at,
    f.id financial_id,f.updated_at financial_updated_at,
    f.timesheet_version financial_timesheet_version,f.is_current financial_is_current,
    f.invoice_breakdown_json,
    seg.segment_json,
    encode(digest(concat_ws('|',
      t.timesheet_id::text,f.id::text,f.timesheet_version::text,
      f.updated_at::text,t.version::text,t.updated_at::text,
      coalesce(f.invoice_breakdown_json::text,''),
      coalesce(s.segment_id,'WHOLE'),
      coalesce(seg.segment_json::text,''),
      coalesce(seg.segment_json->>'segment_id',''),
      coalesce(seg.segment_json->>'invoice_target_week_start',''),
      coalesce(seg.segment_json->>'invoice_locked_invoice_id',''),
      coalesce(seg.segment_json->>'ref_num',''),
      coalesce(seg.segment_json->>'charge_amount',''),
      coalesce(seg.segment_json->>'pay_amount',''),
      coalesce(s.target_invoice_week,''),
      s.invoice_stream,s.consolidation_mode),'sha256'),'hex')
      current_revision
  from supplied s
  left join public.timesheets t on t.timesheet_id=s.timesheet_id
  left join public.timesheets_financials f
    on f.timesheet_id=s.timesheet_id and f.is_current
  left join lateral (
    select x.value segment_json
    from jsonb_array_elements(case
      when jsonb_typeof(f.invoice_breakdown_json->'segments')='array'
        then f.invoice_breakdown_json->'segments'
      else '[]'::jsonb end) x(value)
    where s.segment_id is not null
      and x.value->>'segment_id'=s.segment_id
    order by x.value->>'segment_id'
    limit 1
  ) seg on true
),
schedule_stats as materialized (
  select a.member_no,
    count(*) filter(where jsonb_typeof(x.value)='object'
      and nullif(btrim(x.value->>'start'),'') is not null
      and nullif(btrim(x.value->>'end'),'') is not null) scheduled_count,
    count(*) filter(where jsonb_typeof(x.value)='object'
      and nullif(btrim(x.value->>'start'),'') is not null
      and nullif(btrim(x.value->>'end'),'') is not null
      and nullif(btrim(x.value->>'ref_num'),'') is not null) referenced_count,
    coalesce(jsonb_agg(jsonb_build_object(
      'start',x.value->>'start','end',x.value->>'end',
      'reference',nullif(btrim(x.value->>'ref_num'),''))
      order by x.ordinality) filter(where jsonb_typeof(x.value)='object'
        and nullif(btrim(x.value->>'start'),'') is not null
        and nullif(btrim(x.value->>'end'),'') is not null),'[]'::jsonb)
      schedule_references
  from authoritative a
  left join lateral jsonb_array_elements(case
    when jsonb_typeof(a.actual_schedule_json)='array' then a.actual_schedule_json
    else '[]'::jsonb end) with ordinality x(value,ordinality) on true
  group by a.member_no
),
day_stats as materialized (
  select a.member_no,
    count(*) filter(where left(coalesce(d.key,''),2)<>'__'
      and nullif(btrim(d.value),'') is not null) referenced_count,
    coalesce(jsonb_object_agg(d.key,d.value order by d.key)
      filter(where left(coalesce(d.key,''),2)<>'__'
        and nullif(btrim(d.value),'') is not null),'{}'::jsonb)
      day_references
  from authoritative a
  left join lateral jsonb_each_text(case
    when jsonb_typeof(a.day_references_json)='object' then a.day_references_json
    else '{}'::jsonb end) d(key,value) on true
  group by a.member_no
),
freeform_stats as materialized (
  select a.member_no,
    count(*) filter(where nullif(btrim(case
      when jsonb_typeof(f.value)='string' then f.value#>>'{}'
      when jsonb_typeof(f.value)='object' then coalesce(
        f.value->>'reference',f.value->>'ref_num',f.value->>'value')
      end),'') is not null) referenced_count,
    coalesce(jsonb_agg(nullif(btrim(case
      when jsonb_typeof(f.value)='string' then f.value#>>'{}'
      when jsonb_typeof(f.value)='object' then coalesce(
        f.value->>'reference',f.value->>'ref_num',f.value->>'value')
      end),'') order by f.ordinality)
      filter(where nullif(btrim(case
        when jsonb_typeof(f.value)='string' then f.value#>>'{}'
        when jsonb_typeof(f.value)='object' then coalesce(
          f.value->>'reference',f.value->>'ref_num',f.value->>'value')
        end),'') is not null),'[]'::jsonb) freeform_references
  from authoritative a
  left join lateral jsonb_array_elements(
    case
      when jsonb_typeof(a.day_references_json)='array'
        then a.day_references_json
      when jsonb_typeof(a.day_references_json)='object'
        and jsonb_typeof(a.day_references_json->'__freeform_refs')='array'
        then a.day_references_json->'__freeform_refs'
      when jsonb_typeof(a.day_references_json)='object'
        and jsonb_typeof(a.day_references_json->'__freeform')='array'
        then a.day_references_json->'__freeform'
      when jsonb_typeof(a.day_references_json)='object'
        and jsonb_typeof(a.day_references_json->'__freeform_lines')='array'
        then a.day_references_json->'__freeform_lines'
      else '[]'::jsonb
    end
  ) with ordinality f(value,ordinality) on true
  group by a.member_no
),
segment_stats as materialized (
  select a.member_no,
    count(s.value)::integer segment_count,
    max(nullif(btrim(s.value->>'ref_num'),'')) segment_reference,
    coalesce(jsonb_agg(jsonb_build_object(
      'segment_id',coalesce(nullif(btrim(s.value->>'segment_id'),''),
        case when nullif(btrim(s.value->>'start_utc'),'') is not null
          and nullif(btrim(s.value->>'end_utc'),'') is not null
          then 'SE:'||(s.value->>'start_utc')||'|'||
            (s.value->>'end_utc') end),
      'reference',nullif(btrim(s.value->>'ref_num'),''),
      'target_invoice_week',s.value->>'invoice_target_week_start')
      order by s.ordinality)
      filter(where s.value is not null),'[]'::jsonb) segment_references
  from authoritative a
  left join lateral jsonb_array_elements(
    case when jsonb_typeof(a.invoice_breakdown_json->'segments')='array'
      then a.invoice_breakdown_json->'segments' else '[]'::jsonb end)
    with ordinality s(value,ordinality)
    on coalesce(nullif(btrim(s.value->>'segment_id'),''),
      case when nullif(btrim(s.value->>'start_utc'),'') is not null
        and nullif(btrim(s.value->>'end_utc'),'') is not null
        then 'SE:'||(s.value->>'start_utc')||'|'||
          (s.value->>'end_utc') end)=a.segment_id
  group by a.member_no
),
evaluated as materialized (
  select a.*,coalesce(ss.scheduled_count,0) scheduled_count,
    coalesce(ss.referenced_count,0) schedule_reference_count,
    coalesce(ss.schedule_references,'[]'::jsonb) schedule_references,
    coalesce(ds.referenced_count,0) day_reference_count,
    coalesce(ds.day_references,'{}'::jsonb) day_references,
    coalesce(fs.referenced_count,0) freeform_reference_count,
    coalesce(fs.freeform_references,'[]'::jsonb) freeform_references,
    coalesce(sg.segment_count,0) segment_count,
    sg.segment_reference,
    coalesce(sg.segment_references,'[]'::jsonb) segment_references,
    case
      when a.timesheet_id is null or a.sheet_scope is null then false
      when a.segment_id is not null
        then coalesce(sg.segment_count,0)=1
          and nullif(btrim(coalesce(sg.segment_reference,'')),'') is not null
      when upper(coalesce(a.sheet_scope,''))='WEEKLY'
        and upper(coalesce(a.submission_mode,''))='MANUAL'
        then coalesce(ss.scheduled_count,0)>0
          and ss.scheduled_count=ss.referenced_count
      when upper(coalesce(a.sheet_scope,''))='WEEKLY'
        then nullif(btrim(coalesce(a.reference_number,'')),'') is not null
          or coalesce(ds.referenced_count,0)>0
          or coalesce(fs.referenced_count,0)>0
      else nullif(btrim(coalesce(a.reference_number,'')),'') is not null
    end ready,
    case
      when a.segment_id is not null then 'FINANCIAL_SEGMENT_REFERENCE'
      when upper(coalesce(a.sheet_scope,''))='WEEKLY'
        and upper(coalesce(a.submission_mode,''))='MANUAL'
        then 'WEEKLY_MANUAL_SCHEDULE'
      when upper(coalesce(a.sheet_scope,''))='WEEKLY'
        and nullif(btrim(coalesce(a.reference_number,'')),'') is not null
        then 'WEEKLY_REFERENCE'
      when upper(coalesce(a.sheet_scope,''))='WEEKLY'
        and coalesce(ds.referenced_count,0)>0 then 'DAY_REFERENCES'
      when upper(coalesce(a.sheet_scope,''))='WEEKLY'
        and coalesce(fs.referenced_count,0)>0 then 'FREEFORM_REFERENCES'
      else 'TIMESHEET_REFERENCE'
    end resolved_reference_source
  from authoritative a
  left join schedule_stats ss using(member_no)
  left join day_stats ds using(member_no)
  left join freeform_stats fs using(member_no)
  left join segment_stats sg using(member_no)
)
select e.source_member_key,e.source_type,e.source_id,e.timesheet_id,e.segment_id,
  e.ready
    and e.is_current is true and e.revoked_at is null
    and e.financial_id is not null and e.financial_is_current is true
    and(e.expected_revision is null or e.expected_revision=e.current_revision),
  case
    when e.source_id is null or e.timesheet_id is null then 'SOURCE_ID_INVALID'
    when e.sheet_scope is null then 'SOURCE_NOT_FOUND'
    when e.is_current is not true or e.revoked_at is not null
      then 'TIMESHEET_NOT_CURRENT'
    when e.financial_id is null or e.financial_is_current is not true
      then 'CURRENT_FINANCIALS_MISSING'
    when e.expected_revision is not null
      and e.expected_revision<>e.current_revision then 'SOURCE_REVISION_CHANGED'
    when e.segment_id is not null and e.segment_count<>1
      then 'SOURCE_SEGMENT_NOT_FOUND'
    when not e.ready then 'INVOICE_REFERENCE_REQUIRED'
  end blocker_code,
  e.resolved_reference_source,
  encode(digest(jsonb_build_object(
    'timesheet_id',e.timesheet_id,'segment_id',e.segment_id,
    'sheet_scope',e.sheet_scope,'submission_mode',e.submission_mode,
    'reference_number',nullif(btrim(coalesce(e.reference_number,'')),''),
    'segment_reference',e.segment_reference,
    'day_references',e.day_references,
    'freeform_references',e.freeform_references,
    'schedule_references',e.schedule_references)::text,'sha256'),'hex'),
  e.current_revision,
  jsonb_build_object(
    'source_member_key',e.source_member_key,
    'sheet_scope',e.sheet_scope,'submission_mode',e.submission_mode,
    'whole_reference_present',
      nullif(btrim(coalesce(e.reference_number,'')),'') is not null,
    'segment_reference',e.segment_reference,
    'segment_match_count',e.segment_count,
    'day_reference_count',e.day_reference_count,
    'freeform_reference_count',e.freeform_reference_count,
    'scheduled_segment_count',e.scheduled_count,
    'scheduled_reference_count',e.schedule_reference_count,
    'current_revision',e.current_revision,
    'expected_revision',e.expected_revision)
from evaluated e
order by e.member_no;
$function$;

-- private._timesheet_exact_electronic_restore_proof_v1(uuid)
CREATE OR REPLACE FUNCTION private._timesheet_exact_electronic_restore_proof_v1(p_current_timesheet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_current public.timesheets%rowtype;
  v_electronic public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_approval_request public.candidate_approval_requests%rowtype;
  v_hours public.candidate_submission_components%rowtype;
  v_candidate_signature public.candidate_submission_components%rowtype;
  v_manager_signature public.candidate_submission_components%rowtype;
  v_required_component_ids uuid[];
  v_financial_sha256 bytea;
  v_reason text;
begin
  select * into v_current from public.timesheets where timesheet_id=p_current_timesheet_id;
  if not found then return jsonb_build_object('proven',false,'reason','TIMESHEET_NOT_FOUND'); end if;
  select * into v_electronic from public.timesheets
  where booking_id=v_current.booking_id
    and upper(coalesce(submission_mode::text,''))='ELECTRONIC'
  order by version desc,updated_at desc,created_at desc limit 1;
  if not found then return jsonb_build_object('proven',false,'reason','NO_ELECTRONIC_VERSION'); end if;

  if row(
    v_current.contract_id,v_current.sheet_scope,v_current.line_type,
    v_current.occupant_key_norm,v_current.hospital_norm,v_current.ward_norm,
    v_current.job_title_norm,v_current.band,v_current.scheduled_start_iso,
    v_current.scheduled_end_iso,v_current.worked_start_iso,v_current.worked_end_iso,
    v_current.break_start_iso,v_current.break_end_iso,v_current.break_minutes,
    v_current.worked_minutes,v_current.week_ending_date,v_current.actual_schedule_json,
    v_current.additional_units_week,v_current.additional_units_per_day,
    v_current.day_references_json,v_current.reference_number,v_current.is_adjustment,
    v_current.parent_timesheet_id,v_current.correction_id,v_current.correction_kind,
    v_current.adjustment_origin
  ) is distinct from row(
    v_electronic.contract_id,v_electronic.sheet_scope,v_electronic.line_type,
    v_electronic.occupant_key_norm,v_electronic.hospital_norm,v_electronic.ward_norm,
    v_electronic.job_title_norm,v_electronic.band,v_electronic.scheduled_start_iso,
    v_electronic.scheduled_end_iso,v_electronic.worked_start_iso,v_electronic.worked_end_iso,
    v_electronic.break_start_iso,v_electronic.break_end_iso,v_electronic.break_minutes,
    v_electronic.worked_minutes,v_electronic.week_ending_date,v_electronic.actual_schedule_json,
    v_electronic.additional_units_week,v_electronic.additional_units_per_day,
    v_electronic.day_references_json,v_electronic.reference_number,v_electronic.is_adjustment,
    v_electronic.parent_timesheet_id,v_electronic.correction_id,v_electronic.correction_kind,
    v_electronic.adjustment_origin
  ) then return jsonb_build_object('proven',false,'reason','CONTENT_MISMATCH'); end if;

  if v_electronic.candidate_workflow_id is null
     or v_electronic.candidate_workflow_generation is null
     or nullif(btrim(coalesce(v_electronic.r2_nurse_key,'')),'') is null
     or nullif(btrim(coalesce(v_electronic.r2_auth_key,'')),'') is null
     or nullif(btrim(coalesce(v_electronic.img_sha256_nurse,'')),'') is null
     or nullif(btrim(coalesce(v_electronic.img_sha256_auth,'')),'') is null then
    return jsonb_build_object('proven',false,'reason','SIGNATURE_PROOF_INCOMPLETE');
  end if;
  select * into v_workflow from public.candidate_submission_workflows
  where id=v_electronic.candidate_workflow_id;
  if not found or v_workflow.state<>'FINALISED'
     or v_workflow.canonical_financial_sha256 is null
     or v_workflow.candidate_signature_component_id is null
     or v_workflow.manager_signature_component_id is null then
    return jsonb_build_object('proven',false,'reason','WORKFLOW_PROOF_INCOMPLETE');
  end if;
  select * into v_approval_request
  from public.candidate_approval_requests request_row
  where request_row.workflow_id=v_workflow.id
    and request_row.workflow_generation=v_electronic.candidate_workflow_generation
    and request_row.state in ('APPROVED','SUPERSEDED')
    and request_row.approved_at_utc is not null
  order by request_row.approved_at_utc desc,
    request_row.request_generation desc,request_row.created_at_utc desc
  limit 1;
  if not found
     or v_approval_request.review_manifest_sha256 is null
     or v_approval_request.review_manifest_sha256
          is distinct from v_workflow.review_manifest_sha256
     or cardinality(v_approval_request.required_component_ids)=0
     or jsonb_array_length(v_approval_request.required_component_manifest_json)
          <> cardinality(v_approval_request.required_component_ids)
     or cardinality(v_approval_request.required_component_ids)
          <> (select count(distinct expected_id)
              from unnest(v_approval_request.required_component_ids) expected_id)
     or exists(
       select 1
       from unnest(v_approval_request.required_component_ids) expected_id
       where not exists(
         select 1
         from jsonb_array_elements(
           v_approval_request.required_component_manifest_json
         ) manifest_item
         where manifest_item->>'component_id'=expected_id::text
       )
     )
     or exists(
       select 1
       from jsonb_array_elements(
         v_approval_request.required_component_manifest_json
       ) manifest_item
       where not (manifest_item->>'component_id'=any(
         select expected_id::text
         from unnest(v_approval_request.required_component_ids) expected_id
       ))
     ) then
    return jsonb_build_object('proven',false,'reason','APPROVED_MANIFEST_PROOF_INCOMPLETE');
  end if;
  v_required_component_ids:=v_approval_request.required_component_ids;
  select * into v_hours from public.candidate_submission_components
  where id=v_approval_request.manager_review_timesheet_component_id
    and id=any(v_required_component_ids)
    and workflow_id=v_workflow.id
    and workflow_generation=v_electronic.candidate_workflow_generation
    and component_kind='HOURS_TIMESHEET' and required=true
    and state='IMMUTABLE' and final_signed_render_state='READY'
    and final_signed_storage_key is not null
    and final_signed_content_sha256 is not null
    and final_signed_render_input_sha256 is not null
    and review_render_input_sha256=final_signed_render_input_sha256
  order by review_ordinal,id limit 1;
  if not found then return jsonb_build_object('proven',false,'reason','DOCUMENT_PROOF_INCOMPLETE'); end if;
  -- W13 is a high-assurance historical restore.  Its authority is the exact
  -- immutable ID set frozen into the manager-approved request, not whichever
  -- required components happen to remain active today.
  if exists(
    select 1
    from unnest(v_required_component_ids) expected_id
    left join public.candidate_submission_components component
      on component.id=expected_id
     and component.workflow_id=v_workflow.id
     and component.workflow_generation=v_electronic.candidate_workflow_generation
    where component.id is null
      or component.required is distinct from true
      or component.review_ordinal is null
      or component.state<>'IMMUTABLE'
      or component.final_signed_render_state<>'READY'
      or component.final_signed_storage_key is null
      or component.final_signed_content_sha256 is null
      or component.final_signed_render_input_sha256 is null
      or component.review_render_input_sha256
           is distinct from component.final_signed_render_input_sha256
      or not exists(
        select 1
        from public.timesheet_evidence evidence
        where evidence.candidate_component_id=expected_id
          and evidence.processing_state<>'SUPERSEDED'
          and evidence.storage_key=component.final_signed_storage_key
          and evidence.document_role=case component.component_kind
            when 'HOURS_TIMESHEET' then 'SIGNED_TIMESHEET'
            when 'EXPENSE_SUMMARY' then 'EXPENSE_MILEAGE_APPROVAL_SUMMARY'
            when 'MILEAGE_FORM' then 'MILEAGE_CLAIM_FORM'
            when 'EXPENSE_EVIDENCE' then 'SOURCE_EVIDENCE'
            else component.document_role
          end
      )
  ) or exists(
    select 1
    from public.candidate_submission_components component
    where component.workflow_id=v_workflow.id
      and component.workflow_generation=v_electronic.candidate_workflow_generation
      and component.required=true
      and component.review_ordinal is not null
      and component.state='IMMUTABLE'
      and not (component.id=any(v_required_component_ids))
  ) then
    return jsonb_build_object(
      'proven',false,
      'reason','REQUIRED_FINAL_PAGE_PROOF_INCOMPLETE'
    );
  end if;
  select * into v_candidate_signature from public.candidate_submission_components
  where id=v_workflow.candidate_signature_component_id
    and workflow_id=v_workflow.id
    and workflow_generation=v_electronic.candidate_workflow_generation
    and component_kind='CANDIDATE_SIGNATURE'
    and state='IMMUTABLE'
    and immutable_at_utc is not null
    and source_content_sha256=v_workflow.candidate_signature_sha256
    and storage_key=v_electronic.r2_nurse_key;
  if not found or lower(btrim(v_electronic.img_sha256_nurse))
       is distinct from encode(v_candidate_signature.source_content_sha256,'hex') then
    return jsonb_build_object('proven',false,'reason','CANDIDATE_SIGNATURE_PROOF_INCOMPLETE');
  end if;
  select * into v_manager_signature from public.candidate_submission_components
  where id=v_workflow.manager_signature_component_id
    and workflow_id=v_workflow.id
    and workflow_generation=v_electronic.candidate_workflow_generation
    and component_kind='MANAGER_SIGNATURE'
    and state='IMMUTABLE'
    and immutable_at_utc is not null
    and approval_request_id=v_approval_request.id
    and source_content_sha256=v_workflow.manager_signature_sha256
    and storage_key=v_electronic.r2_auth_key;
  if not found or lower(btrim(v_electronic.img_sha256_auth))
       is distinct from encode(v_manager_signature.source_content_sha256,'hex') then
    return jsonb_build_object('proven',false,'reason','MANAGER_SIGNATURE_PROOF_INCOMPLETE');
  end if;
  if not exists(
    select 1 from public.timesheet_evidence evidence
    where evidence.timesheet_id=v_electronic.timesheet_id
      and upper(btrim(evidence.kind))='TIMESHEET'
      and evidence.processing_state<>'SUPERSEDED'
      and evidence.candidate_component_id=v_hours.id
      and evidence.storage_key=v_hours.final_signed_storage_key
  ) then return jsonb_build_object('proven',false,'reason','EVIDENCE_PROOF_INCOMPLETE'); end if;
  select * into v_fin from public.timesheets_financials
  where timesheet_id=v_current.timesheet_id and is_current=true
  order by computed_at_utc desc nulls last,updated_at desc,id desc limit 1;
  if not found then return jsonb_build_object('proven',false,'reason','FINANCIAL_PROOF_INCOMPLETE'); end if;
  v_financial_sha256:=private._candidate_financial_content_sha256_v1(v_fin.id);
  if v_financial_sha256 is distinct from v_workflow.canonical_financial_sha256 then
    return jsonb_build_object('proven',false,'reason','FINANCIAL_CONTENT_MISMATCH');
  end if;
  return jsonb_build_object('proven',true,'electronic_timesheet_id',v_electronic.timesheet_id,
    'electronic_version',v_electronic.version);
end;
$function$;

-- private._timesheet_qr_restore_legacy_v1(uuid,uuid,text,uuid)
CREATE OR REPLACE FUNCTION private._timesheet_qr_restore_legacy_v1(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_restore_kind text, p_actor_user_id uuid)
 RETURNS TABLE(timesheet_id uuid, restored_version integer, sheet_scope text, submission_mode text, qr_status text, qr_token text, restored_has_signed_pdf boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();

  v_any public.timesheets%rowtype;
  v_current public.timesheets%rowtype;
  v_restore public.timesheets%rowtype;

  v_booking_id text;          -- timesheets.booking_id is TEXT
  v_fin public.timesheets_financials%rowtype;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_id is required';
  end if;

  if p_expected_timesheet_id is null then
    raise exception '%',
      jsonb_build_object('error','EXPECTED_TIMESHEET_ID_REQUIRED')::text;
  end if;

  if upper(coalesce(p_restore_kind,'')) not in ('PENDING','SIGNED') then
    raise exception 'restore_kind must be PENDING or SIGNED';
  end if;

  -- 0) Resolve booking_id from ANY row
  select t.*
  into v_any
  from public.timesheets t
  where t.timesheet_id = p_timesheet_id
  limit 1;

  if not found then
    raise exception 'Timesheet not found';
  end if;

  v_booking_id := v_any.booking_id;
  if v_booking_id is null or btrim(v_booking_id) = '' then
    raise exception 'Timesheet booking_id is missing; cannot restore';
  end if;

  -- 1) Lock CURRENT row for booking_id
  select t.*
  into v_current
  from public.timesheets t
  where t.booking_id = v_booking_id
    and t.is_current = true
  for update;

  if not found then
    raise exception 'Current timesheet not found for booking_id';
  end if;

  if p_expected_timesheet_id <> v_current.timesheet_id then
    raise exception '%',
      jsonb_build_object(
        'error','TIMESHEET_MOVED',
        'current_timesheet_id', v_current.timesheet_id
      )::text;
  end if;

  -- 2) Lock current TSFIN and block if invoiced/paid
  select f.*
  into v_fin
  from public.timesheets_financials f
  where f.timesheet_id = v_current.timesheet_id
    and f.is_current = true
  for update;

  if found then
    if v_fin.locked_by_invoice_id is not null or v_fin.paid_at_utc is not null then
      raise exception 'Cannot restore: timesheet is invoiced/locked or paid';
    end if;
  end if;

  -- 3) Pick target revoked version
  if upper(p_restore_kind) = 'PENDING' then
    select t.*
    into v_restore
    from public.timesheets t
    where t.booking_id = v_booking_id
      and t.is_current = false
      and t.status = 'REVOKED'::public.timesheet_status_enum
      and t.qr_scanned_at is null
    order by t.version desc
    limit 1;
  else
    select t.*
    into v_restore
    from public.timesheets t
    where t.booking_id = v_booking_id
      and t.is_current = false
      and t.status = 'REVOKED'::public.timesheet_status_enum
      and t.qr_scanned_at is not null
    order by t.version desc
    limit 1;
  end if;

  if not found then
    raise exception 'No matching revoked version found to restore';
  end if;

  -- 4) Demote current -> not current
  update public.timesheets as t
  set is_current = false,
      updated_at = v_now
  where t.timesheet_id = v_current.timesheet_id
    and t.is_current = true;

  -- 5) Promote restored -> current
  update public.timesheets as t
  set is_current = true,
      updated_at = v_now
  where t.timesheet_id = v_restore.timesheet_id;

  -- 6) Move contract_week pointer if it points at old current row
  update public.contract_weeks as cw
  set timesheet_id = v_restore.timesheet_id,
      updated_at   = v_now
  where cw.timesheet_id = v_current.timesheet_id;

  -- 7) Move TSFIN row + enqueue recompute
  if v_fin.id is not null then
    update public.timesheets_financials as f
    set
      timesheet_id      = v_restore.timesheet_id,
      timesheet_version = v_restore.version,
      updated_at        = v_now
    where f.id = v_fin.id;

    -- ✅ FIX: use constraint name to avoid ambiguous (timesheet_id, reason)
    insert into public.ts_financials_outbox(timesheet_id, reason, attempt_count, next_attempt_at, last_error, created_at)
    values (v_restore.timesheet_id, 'VERSION_ROTATED'::public.ts_fin_reason_enum, 0, v_now, null, v_now)
    on conflict on constraint uq_tsfin_outbox do nothing;
  end if;

  -- 8) Audit
  insert into public.audit_events(
    object_type, object_id_text, action, before_json, after_json, reason, actor_user_id, ts_utc
  )
  values(
    'timesheet',
    v_restore.timesheet_id::text,
    'QR_RESTORED',
    jsonb_build_object(
      'booking_id', v_booking_id,
      'from_timesheet_id', v_current.timesheet_id::text,
      'from_version', v_current.version
    ),
    jsonb_build_object(
      'to_timesheet_id', v_restore.timesheet_id::text,
      'to_version', v_restore.version,
      'kind', upper(p_restore_kind)
    ),
    null,
    p_actor_user_id,
    v_now
  );

  -- Return
  timesheet_id := v_restore.timesheet_id;
  restored_version := v_restore.version;
  sheet_scope := v_restore.sheet_scope::text;
  submission_mode := v_restore.submission_mode::text;
  qr_status := coalesce(v_restore.qr_status::text, null);
  qr_token := v_restore.qr_token;
  restored_has_signed_pdf := (v_restore.manual_pdf_r2_key is not null and btrim(v_restore.manual_pdf_r2_key) <> '');
  return next;
end;
$function$;

-- private._timesheet_route_change_context_v1(uuid,text)
CREATE OR REPLACE FUNCTION private._timesheet_route_change_context_v1(p_current_timesheet_id uuid, p_target_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_action text:=upper(btrim(coalesce(p_target_action,'')));
  v_requested public.timesheets%rowtype;
  v_current public.timesheets%rowtype;
  v_week public.contract_weeks%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_contract public.contracts%rowtype;
  v_linked_workflow public.candidate_submission_workflows%rowtype;
  v_paper_workflow public.candidate_submission_workflows%rowtype;
  v_active_workflow public.candidate_submission_workflows%rowtype;
  v_request public.candidate_approval_requests%rowtype;
  v_signature jsonb:='{}'::jsonb;
  v_policy jsonb:='{}'::jsonb;
  v_import jsonb:='{}'::jsonb;
  v_restore_proof jsonb:='{}'::jsonb;
  v_history jsonb:='{}'::jsonb;
  v_paper_source_context jsonb:='{}'::jsonb;
  v_payload jsonb;
  v_context_hash text;
  v_route_family text;
  v_warning_code text;
  v_block_reason text;
  v_row_signature text;
  v_effective_mode text;
  v_booking_id text;
  v_contract_id uuid;
  v_client_id uuid;
  v_candidate_signed boolean:=false;
  v_manager_pending boolean:=false;
  v_manager_approved boolean:=false;
  v_final_signed_ready boolean:=false;
  v_qr_route_active boolean:=false;
  v_qr_code_generated boolean:=false;
  v_qr_pack_ready boolean:=false;
  v_qr_pack_issued_or_sent boolean:=false;
  v_qr_issued boolean:=false;
  v_qr_signed boolean:=false;
  v_prior_qr boolean:=false;
  v_import_authoritative boolean:=false;
  v_office_authorised boolean:=false;
  v_invoiced boolean:=false;
  v_paid boolean:=false;
  v_paper_allowed boolean:=false;
  v_permitted boolean:=false;
  v_reason_required boolean:=false;
  v_confirmation_required boolean:=false;
  v_active_workflow_count integer:=0;
  v_incomplete_expense_removal_required boolean:=false;
  v_resolvable_paper_context_conflict boolean:=false;
  v_contract_week_authorised boolean:=false;
  v_protected_history boolean:=false;
  v_scope text;
  v_basis text;
  v_actual_qr_backing boolean:=false;
begin
  if p_current_timesheet_id is null then
    raise exception 'ROUTE_CHANGE_TIMESHEET_REQUIRED' using errcode='22023';
  end if;
  if v_action not in (
    'CONVERT_QR_TO_MANUAL','ALLOW_ELECTRONIC_AGAIN','ALLOW_QR_AGAIN',
    'INVALIDATE_QR','REISSUE_QR','DISABLE_QR','SWITCH_TO_MANUAL',
    'SWITCH_DAILY_TO_MANUAL','REVERT_TO_ELECTRONIC'
  ) then
    raise exception 'ROUTE_CHANGE_ACTION_INVALID' using errcode='22023';
  end if;

  select * into v_requested from public.timesheets
  where timesheet_id=p_current_timesheet_id;
  if not found then raise exception 'TIMESHEET_NOT_FOUND' using errcode='P0002'; end if;
  v_booking_id:=nullif(btrim(coalesce(v_requested.booking_id,'')),'');
  if v_booking_id is null then
    raise exception 'TIMESHEET_BOOKING_ID_REQUIRED' using errcode='55000';
  end if;
  select * into v_current from public.timesheets
  where booking_id=v_booking_id and is_current=true
  order by version desc,updated_at desc,created_at desc limit 1;
  if not found then raise exception 'TIMESHEET_CURRENT_VERSION_NOT_FOUND' using errcode='P0002'; end if;

  select * into v_week from public.contract_weeks
  where timesheet_id=v_current.timesheet_id
  order by updated_at desc,created_at desc,id desc limit 1;
  select * into v_fin from public.timesheets_financials
  where timesheet_id=v_current.timesheet_id and is_current=true
  order by computed_at_utc desc nulls last,updated_at desc,id desc limit 1;
  v_contract_id:=coalesce(v_week.contract_id,v_current.contract_id);
  if v_contract_id is not null then
    select * into v_contract from public.contracts where id=v_contract_id;
    v_client_id:=v_contract.client_id;
  end if;
  v_client_id:=coalesce(v_client_id,v_fin.client_id);

  if v_client_id is not null then
    v_import:=private._candidate_import_authoritative_v1(
      v_client_id,v_contract_id,v_current.timesheet_id,
      case when v_fin.id is null then null else to_jsonb(v_fin) end,
      v_current.week_ending_date
    );
    v_import_authoritative:=coalesce((v_import->>'is_import_authoritative')::boolean,false);
  end if;
  if v_client_id is not null and v_contract_id is not null then
    v_policy:=private._candidate_policy_resolve_v1(
      v_client_id,v_contract_id,
      coalesce(v_current.week_ending_date,(current_timestamp at time zone 'Europe/London')::date)
    );
    v_effective_mode:=private._candidate_submission_mode_v1(
      v_client_id,v_contract_id,
      coalesce(v_current.week_ending_date,(current_timestamp at time zone 'Europe/London')::date)
    )::text;
    v_paper_allowed:=coalesce((v_policy->>'paper_submission_enabled')::boolean,false);
  else
    v_effective_mode:=coalesce(v_current.submission_mode::text,'MANUAL');
  end if;

  select exists(
    select 1 from public.timesheets history
    where history.booking_id=v_booking_id and (
      history.qr_status is not null
      or nullif(btrim(coalesce(history.qr_token,'')),'') is not null
      or history.qr_generated_at is not null
      or history.qr_scanned_at is not null
      or nullif(btrim(coalesce(history.qr_r2_key,'')),'') is not null
      or history.qr_signed_at_utc is not null
    )
  ) into v_prior_qr;
  v_qr_route_active:=coalesce(v_current.qr_status is not null
    or nullif(btrim(coalesce(v_current.qr_token,'')),'') is not null
    or v_current.qr_generated_at is not null
    or nullif(btrim(coalesce(v_current.qr_r2_key,'')),'') is not null
    or v_current.qr_scanned_at is not null
    or v_current.qr_signed_at_utc is not null
    or nullif(btrim(coalesce(v_current.qr_signed_hash,'')),'') is not null
    or v_current.candidate_submission_route_intent='PAPER',false);
  -- The QR code is created before the printable PDF.  Keep code generation,
  -- durable pack readiness, actual issue/send and signed return as separate
  -- facts so the approved W08/W09 wording is never asserted prematurely.
  v_qr_code_generated:=v_qr_route_active
    and nullif(btrim(coalesce(v_current.qr_token,'')),'') is not null
    and v_current.qr_generated_at is not null;
  v_qr_pack_issued_or_sent:=v_qr_route_active and (
    v_current.qr_last_sent_at_utc is not null
    or nullif(btrim(coalesce(v_current.qr_last_sent_hash,'')),'') is not null
  );
  v_qr_pack_ready:=v_qr_route_active and (
      -- The unchanged QR backend writes this key only after successful PDF
      -- rendering.  It is proof of an unsigned generated pack, never proof of
      -- a returned signature.
      nullif(btrim(coalesce(v_current.manual_pdf_r2_key,'')),'') is not null
      or (
      upper(coalesce(v_current.document_state::text,''))='READY'
      and v_current.current_document_version_id is not null
      and exists(
        select 1 from public.invoice_document_versions document_version
        where document_version.id=v_current.current_document_version_id
          and document_version.entity_type='TIMESHEET'
          and document_version.entity_id=v_current.timesheet_id
          and upper(coalesce(document_version.status,''))='READY'
      )
    )
    or v_qr_pack_issued_or_sent
  );
  v_qr_signed:=v_qr_route_active and (
    v_current.qr_signed_at_utc is not null
    or nullif(btrim(coalesce(v_current.qr_signed_hash,'')),'') is not null
    or v_current.qr_scanned_at is not null
    or exists(
      select 1 from public.timesheet_evidence evidence
      where evidence.timesheet_id=v_current.timesheet_id
        and upper(btrim(evidence.kind))='TIMESHEET'
        and evidence.document_role='SIGNED_TIMESHEET'
        and evidence.processing_state<>'SUPERSEDED'
        and nullif(btrim(coalesce(evidence.storage_key,'')),'') is not null
    )
  );
  v_scope:=upper(coalesce(v_current.sheet_scope::text,''));
  v_basis:=upper(coalesce(v_fin.basis::text,''));
  v_actual_qr_backing:=v_qr_route_active;
  v_route_family:=case
    when v_import_authoritative then 'IMPORT_AUTHORITATIVE'
    when v_actual_qr_backing then 'QR'
    when upper(coalesce(v_current.submission_mode::text,''))='ELECTRONIC'
      or upper(coalesce(v_week.submission_mode_snapshot::text,''))='ELECTRONIC'
      or v_current.candidate_submission_route_intent='ELECTRONIC'
      then 'ELECTRONIC'
    else 'MANUAL_NON_QR' end;

  -- Existing signed ELECTRONIC rows pre-date Candidate workflows.  Canonical
  -- CloudTMS signature/document evidence remains authoritative for warnings.
  v_candidate_signed:=nullif(btrim(coalesce(v_current.r2_nurse_key,'')),'') is not null
    or nullif(btrim(coalesce(v_current.img_sha256_nurse,'')),'') is not null;
  v_manager_approved:=nullif(btrim(coalesce(v_current.r2_auth_key,'')),'') is not null
    or nullif(btrim(coalesce(v_current.img_sha256_auth,'')),'') is not null
    or v_current.candidate_manager_approved_at_utc is not null;
  v_final_signed_ready:=v_manager_approved and exists(
    select 1 from public.timesheet_evidence evidence
    where evidence.timesheet_id=v_current.timesheet_id
      and upper(btrim(evidence.kind))='TIMESHEET'
      and evidence.processing_state<>'SUPERSEDED'
      and nullif(btrim(coalesce(evidence.storage_key,'')),'') is not null
  );

  select workflow.* into v_linked_workflow
  from public.candidate_submission_workflows workflow
  where workflow.id=v_current.candidate_workflow_id
     or workflow.target_timesheet_id=v_current.timesheet_id
     or workflow.anchor_timesheet_id=v_current.timesheet_id
  order by (workflow.id=v_current.candidate_workflow_id) desc,
    workflow.updated_at_utc desc,workflow.created_at_utc desc
  limit 1;
  -- A QR/PAPER route is owned by the immutable delivery receipt matching the
  -- current token. The historical candidate_workflow_id remains useful audit
  -- lineage, but it must never outrank a later live expense/PAPER generation.
  -- With no current token, a sole nonterminal workflow is selected; finalised
  -- history is used only when no nonterminal workflow exists. Ambiguity is a
  -- server-owned preview conflict and is recomputed again under confirmation
  -- locks before any source-wide retirement or route rotation.
  if v_route_family='QR' then
    v_paper_source_context:=private._candidate_paper_source_workflow_context_v1(
      v_current.timesheet_id
    );
    if not coalesce(
      (v_paper_source_context->>'identity_conflict')::boolean,false
    ) and nullif(v_paper_source_context->>'selected_workflow_id','') is not null then
      select workflow.* into v_paper_workflow
      from public.candidate_submission_workflows workflow
      where workflow.id=(v_paper_source_context->>'selected_workflow_id')::uuid
        and workflow.generation=
          (v_paper_source_context->>'selected_workflow_generation')::integer
        and workflow.state=v_paper_source_context->>'selected_workflow_state';
      if not found then
        raise exception 'CANDIDATE_PAPER_SOURCE_CONTEXT_CHANGED' using errcode='40001';
      end if;
    end if;
  end if;
  select workflow.* into v_active_workflow
  from public.candidate_submission_workflows workflow
  where (workflow.id=v_current.candidate_workflow_id
      or workflow.target_timesheet_id=v_current.timesheet_id
      or workflow.anchor_timesheet_id=v_current.timesheet_id)
    -- REFUSED remains recoverable because candidate workflow AMEND expressly
    -- accepts it.  A route version must not make that recovery anchor historic.
    and workflow.state not in ('FINALISED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED')
  order by (workflow.id=v_current.candidate_workflow_id) desc,
    workflow.updated_at_utc desc,workflow.created_at_utc desc
  limit 1;
  select count(*) into v_active_workflow_count
  from public.candidate_submission_workflows workflow
  where (workflow.id=v_current.candidate_workflow_id
      or workflow.target_timesheet_id=v_current.timesheet_id
      or workflow.anchor_timesheet_id=v_current.timesheet_id)
    and workflow.state not in ('FINALISED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED');

  -- A source-to-MANUAL intervention may explicitly remove one standalone
  -- incomplete expense claim.  This includes REFUSED because AMEND still owns
  -- a valid recovery path until the office confirms that the claim is removed.
  v_incomplete_expense_removal_required:=v_action in (
      'SWITCH_TO_MANUAL','SWITCH_DAILY_TO_MANUAL',
      'CONVERT_QR_TO_MANUAL','DISABLE_QR'
    )
    and v_active_workflow.id is not null
    and v_active_workflow.workflow_kind='CONTRACT_EXPENSE'
    and v_active_workflow.state not in (
      'FINALISED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED'
    );
  v_resolvable_paper_context_conflict:=v_incomplete_expense_removal_required
    and v_route_family='QR'
    and v_active_workflow_count=1
    and coalesce((v_paper_source_context->>'identity_conflict')::boolean,false)
    and v_paper_source_context->>'conflict_reason' in (
      'CANDIDATE_PAPER_SHARED_SOURCE_WORKFLOW_CONFLICT',
      'CURRENT_QR_TOKEN_OWNER_TERMINAL_WITH_LIVE_WORKFLOW'
    )
    and coalesce(
      (v_paper_source_context->>'affected_nonterminal_workflow_count')::integer,0
    )=1
    and exists(
      select 1
      from jsonb_array_elements(
        coalesce(v_paper_source_context->'affected_nonterminal_workflows','[]'::jsonb)
      ) affected
      where affected->>'workflow_id'=v_active_workflow.id::text
    );

  if v_linked_workflow.id is not null then
    v_candidate_signed:=v_candidate_signed
      or v_linked_workflow.candidate_signature_component_id is not null
      or v_linked_workflow.candidate_signed_at_utc is not null;
    v_manager_approved:=v_manager_approved
      or v_linked_workflow.state in ('MANAGER_APPROVED','RECEIVED','FINALISED')
      or v_linked_workflow.manager_signature_component_id is not null
      or v_linked_workflow.manager_approved_at_utc is not null;
    v_final_signed_ready:=v_final_signed_ready or exists(
      select 1 from public.candidate_submission_components component
      where component.workflow_id=v_linked_workflow.id
        and component.workflow_generation=v_linked_workflow.generation
        and component.required=true
        and component.state<>'SUPERSEDED'
        and component.final_signed_render_state='READY'
    );
    v_qr_signed:=v_qr_signed or (v_qr_route_active and exists(
      select 1 from public.candidate_submission_components component
      where component.workflow_id=v_linked_workflow.id
        and component.workflow_generation=v_linked_workflow.generation
        and component.component_kind='SIGNED_RETURN'
        and component.document_role='SIGNED_RETURN'
        and component.state='IMMUTABLE'
        and component.immutable_at_utc is not null
        and nullif(btrim(coalesce(component.storage_key,'')),'') is not null
    ));
  end if;
  -- A signed return necessarily followed issue even where a legacy send stamp
  -- is incomplete.  A merely generated or READY-but-unsent pack does not.
  v_qr_issued:=v_qr_pack_issued_or_sent or v_qr_signed;
  v_qr_pack_ready:=v_qr_pack_ready or v_qr_issued;
  if v_active_workflow.id is not null then
    select request_row.* into v_request
    from public.candidate_approval_requests request_row
    where request_row.workflow_id=v_active_workflow.id
      and request_row.workflow_generation=v_active_workflow.generation
      and (request_row.state='APPROVED' or (
        request_row.state='PENDING'
        and (request_row.expires_at_utc is null or request_row.expires_at_utc>now())
      ))
    order by (request_row.state='PENDING'
      and (request_row.expires_at_utc is null or request_row.expires_at_utc>now())) desc,
      request_row.request_generation desc,request_row.created_at_utc desc
    limit 1;
    v_manager_pending:=coalesce(v_request.state='PENDING',false);
    v_manager_approved:=v_manager_approved or coalesce(v_request.state='APPROVED',false);
  end if;

  v_contract_week_authorised:=upper(coalesce(v_week.status::text,''))='AUTHORISED';
  v_office_authorised:=v_current.authorised_at_server is not null
    or v_fin.authorised_at_utc is not null or v_contract_week_authorised;
  v_paid:=v_fin.paid_at_utc is not null;
  v_invoiced:=v_fin.locked_by_invoice_id is not null or exists(
    select 1 from jsonb_array_elements(
      case when jsonb_typeof(v_fin.invoice_breakdown_json->'segments')='array'
        then v_fin.invoice_breakdown_json->'segments' else '[]'::jsonb end
    ) segment
    where nullif(btrim(coalesce(segment->>'invoice_locked_invoice_id','')),'') is not null
  );
  select public.timesheet_removal_financial_history_v1(
    array_agg(history.timesheet_id order by history.timesheet_id),
    array[v_booking_id],
    case when v_week.id is null then array[]::uuid[] else array[v_week.id] end
  ) into v_history
  from public.timesheets history where history.booking_id=v_booking_id;
  v_protected_history:=coalesce((v_history->>'archive_required')::boolean,false)
    or exists(select 1 from jsonb_array_elements(coalesce(v_history->'blockers','[]'::jsonb)) blocker
      where blocker->>'code' not in ('TIMESHEET_STILL_AUTHORISED'));
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(
    v_current.timesheet_id,
    case when v_week.id is null then null else v_week.id end,
    false
  );
  v_row_signature:=nullif(btrim(coalesce(
    v_signature->>'backend_row_signature',v_signature->>'row_signature',v_signature->>'signature',''
  )), '');
  if v_row_signature is null then
    raise exception 'ROUTE_CHANGE_ROW_SIGNATURE_UNAVAILABLE' using errcode='55000';
  end if;
  if v_action='REVERT_TO_ELECTRONIC' then
    v_restore_proof:=private._timesheet_exact_electronic_restore_proof_v1(v_current.timesheet_id);
  end if;

  if v_import_authoritative then
    v_warning_code:='ROUTE_CHANGE_IMPORT_AUTHORITATIVE_BLOCK';
    v_block_reason:='IMPORT_AUTHORITATIVE';
  elsif v_paid or v_invoiced or v_protected_history then
    v_warning_code:='ROUTE_CHANGE_FINANCIAL_HISTORY_BLOCK';
    v_block_reason:='FINANCIAL_HISTORY';
  elsif v_office_authorised then
    v_warning_code:='ROUTE_CHANGE_REQUIRES_UNAUTHORISE';
    v_block_reason:='AUTHORISED';
  elsif coalesce((v_paper_source_context->>'identity_conflict')::boolean,false)
        and not v_resolvable_paper_context_conflict then
    v_warning_code:='ROUTE_CHANGE_WORKFLOW_CONFLICT';
    v_block_reason:=coalesce(
      v_paper_source_context->>'conflict_reason',
      'CANDIDATE_PAPER_SHARED_SOURCE_WORKFLOW_CONFLICT'
    );
  -- A distinct active workflow must ordinarily fail closed.  The one approved
  -- exception is an explicitly confirmed standalone incomplete expense claim,
  -- which confirmation supersedes before the route source is rotated.
  elsif v_action in ('SWITCH_TO_MANUAL','SWITCH_DAILY_TO_MANUAL')
        and v_active_workflow.id is not null
        and not v_incomplete_expense_removal_required
        and (
          v_active_workflow.id is distinct from v_linked_workflow.id
          or v_active_workflow.state='REFUSED'
        ) then
    v_warning_code:='ROUTE_CHANGE_WORKFLOW_CONFLICT';
    v_block_reason:='CANDIDATE_ROUTE_ACTIVE_WORKFLOW_CONFLICT';
  elsif v_active_workflow_count>1 then
    v_warning_code:='ROUTE_CHANGE_WORKFLOW_CONFLICT';
    v_block_reason:='MULTIPLE_ACTIVE_WORKFLOWS';
  elsif v_scope='DAILY'
        and v_action in ('ALLOW_QR_AGAIN','INVALIDATE_QR','REISSUE_QR') then
    v_warning_code:='DAILY_PAPER_ROUTE_NOT_ALLOWED';
    v_block_reason:='DAILY_PAPER_ROUTE_NOT_ALLOWED';
  elsif v_action='SWITCH_TO_MANUAL' and v_route_family='ELECTRONIC'
        and v_scope='WEEKLY' and v_week.id is not null and v_fin.id is not null
        and v_basis='CONTRACT_WEEKLY' and not coalesce(v_current.is_adjustment,false) then
    v_permitted:=true;
    v_reason_required:=true;
    v_warning_code:=case
      when v_incomplete_expense_removal_required
        then 'CANDIDATE_INCOMPLETE_EXPENSE_CLAIM_REMOVE_CONFIRM'
      when v_manager_approved or v_final_signed_ready then 'MANAGER_APPROVED_TO_MANUAL'
      when v_candidate_signed or v_manager_pending then 'CANDIDATE_SIGNED_MANAGER_PENDING_TO_MANUAL'
      else 'ELECTRONIC_UNSIGNED_TO_MANUAL' end;
  elsif v_action='SWITCH_DAILY_TO_MANUAL' and v_route_family='ELECTRONIC'
        and v_scope='DAILY' and v_fin.id is not null
        and v_basis not in ('NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL','HEALTHROSTER_ADJUSTMENT')
        and not coalesce(v_current.is_adjustment,false) then
    v_permitted:=true;
    v_reason_required:=true;
    v_warning_code:=case
      when v_incomplete_expense_removal_required
        then 'CANDIDATE_INCOMPLETE_EXPENSE_CLAIM_REMOVE_CONFIRM'
      when v_manager_approved or v_final_signed_ready then 'MANAGER_APPROVED_TO_MANUAL'
      when v_candidate_signed or v_manager_pending then 'CANDIDATE_SIGNED_MANAGER_PENDING_TO_MANUAL'
      else 'ELECTRONIC_UNSIGNED_TO_MANUAL' end;
  elsif v_action in ('CONVERT_QR_TO_MANUAL','DISABLE_QR') and v_route_family='QR'
        and v_actual_qr_backing and v_fin.id is not null
        and not coalesce(v_current.is_adjustment,false) then
    if v_incomplete_expense_removal_required then
      v_permitted:=true;
      v_reason_required:=true;
      v_warning_code:='CANDIDATE_INCOMPLETE_EXPENSE_CLAIM_REMOVE_CONFIRM';
    elsif v_qr_signed then
      v_permitted:=true;
      v_reason_required:=true;
      v_warning_code:='QR_SIGNED_TO_MANUAL';
    elsif v_qr_pack_issued_or_sent then
      v_permitted:=true;
      v_reason_required:=true;
      v_warning_code:='QR_ISSUED_TO_MANUAL';
    elsif v_qr_pack_ready then
      v_warning_code:='ROUTE_CHANGE_NOT_PERMITTED';
      v_block_reason:='QR_PACK_READY_NOT_ISSUED';
    else
      v_warning_code:='ROUTE_CHANGE_NOT_PERMITTED';
      v_block_reason:='QR_PACK_PREPARATION_IN_PROGRESS';
    end if;
  elsif v_action='ALLOW_ELECTRONIC_AGAIN' and v_route_family='MANUAL_NON_QR'
        and upper(coalesce(v_effective_mode,''))='ELECTRONIC'
        and v_fin.id is not null and not coalesce(v_current.is_adjustment,false) then
    v_permitted:=true;
    v_warning_code:='FRESH_ELECTRONIC_RESUBMISSION_REQUIRED';
  elsif v_action='ALLOW_QR_AGAIN' and v_route_family='MANUAL_NON_QR'
        and v_scope='WEEKLY'
        and (v_prior_qr or v_paper_allowed) and v_fin.id is not null
        and not coalesce(v_current.is_adjustment,false) then
    v_permitted:=true;
    v_warning_code:='FRESH_PAPER_RESUBMISSION_REQUIRED';
  elsif v_action in ('INVALIDATE_QR','REISSUE_QR') and v_route_family='QR'
        and v_scope='WEEKLY'
        and v_actual_qr_backing and v_qr_issued and v_fin.id is not null
        and not coalesce(v_current.is_adjustment,false) then
    v_permitted:=true;
    v_warning_code:='QR_REPLACEMENT_PACK_REQUIRED';
  elsif v_action='REVERT_TO_ELECTRONIC' and v_route_family='MANUAL_NON_QR'
        and coalesce((v_restore_proof->>'proven')::boolean,false) then
    v_permitted:=true;
    v_warning_code:='EXACT_ELECTRONIC_RESTORE_PROVEN';
  else
    v_warning_code:='ROUTE_CHANGE_NOT_PERMITTED';
    v_block_reason:='ROUTE_OR_POLICY_MISMATCH';
  end if;
  v_confirmation_required:=v_permitted;

  v_payload:=jsonb_build_object(
    'contract_version','TIMESHEET_ROUTE_CHANGE_CONTEXT_V1',
    'target_action',v_action,
    'booking_id',v_booking_id,
    'requested_timesheet_id',v_requested.timesheet_id,
    'current_timesheet_id',v_current.timesheet_id,
    'current_version',v_current.version,
    'current_updated_at_utc',v_current.updated_at,
    'current_status',v_current.status,
    'current_row_signature',v_row_signature,
    'row_signature',v_row_signature,
    'sheet_scope',v_scope,
    'tsfin_basis',v_basis,
    'pending_route_intent',v_current.candidate_submission_route_intent,
    'route_family',v_route_family,
    'effective_submission_mode',v_effective_mode,
    'effective_paper_submission_allowed',v_paper_allowed,
    'prior_qr_lineage',v_prior_qr,
    'import_authoritative',v_import_authoritative,
    'office_authorised',v_office_authorised,
    'contract_week_authorised',v_contract_week_authorised,
    'invoiced',v_invoiced,
    'paid',v_paid,
    'protected_financial_history',v_protected_history,
    'candidate_signed',v_candidate_signed,
    'manager_approval_pending',v_manager_pending,
    'manager_approved',v_manager_approved,
    'final_signed_document_ready',v_final_signed_ready,
    'qr_route_active',v_qr_route_active,
    'qr_code_generated',v_qr_code_generated,
    'qr_pack_ready',v_qr_pack_ready,
    'qr_pack_issued_or_sent',v_qr_pack_issued_or_sent,
    'qr_pack_issued',v_qr_issued,
    'qr_signed_returned',v_qr_signed
  )||jsonb_build_object(
    'linked_workflow_id',v_linked_workflow.id,
    'linked_workflow_generation',v_linked_workflow.generation,
    'linked_workflow_state',v_linked_workflow.state,
    'linked_workflow_updated_at_utc',v_linked_workflow.updated_at_utc,
    'paper_workflow_id',v_paper_workflow.id,
    'paper_workflow_generation',v_paper_workflow.generation,
    'paper_workflow_state',v_paper_workflow.state,
    'paper_source_workflow_context',v_paper_source_context,
    'paper_source_nonterminal_workflow_count',
      coalesce((v_paper_source_context->>'nonterminal_workflow_count')::integer,0),
    'paper_source_affected_nonterminal_workflow_count',
      coalesce((v_paper_source_context->>'affected_nonterminal_workflow_count')::integer,0),
    'paper_source_current_token_owner_workflow_id',
      nullif(v_paper_source_context->>'current_token_owner_workflow_id','')::uuid,
    'active_workflow_id',v_active_workflow.id,
    'active_workflow_count',v_active_workflow_count,
    'active_workflow_generation',v_active_workflow.generation,
    'incomplete_expense_claim_removal_required',
      v_incomplete_expense_removal_required,
    'incomplete_expense_workflow_id',case
      when v_incomplete_expense_removal_required then v_active_workflow.id else null end,
    'incomplete_expense_workflow_state',case
      when v_incomplete_expense_removal_required then v_active_workflow.state else null end,
    'incomplete_expense_confirmation_message',case
      when v_incomplete_expense_removal_required then
        'The candidate has started an expense claim but has not completed it. Do you want to remove the incomplete claim and continue?'
      else null end,
    'active_approval_request_id',v_request.id,
    'active_approval_request_state',v_request.state,
    'active_approval_request_updated_at_utc',v_request.updated_at_utc,
    'exact_electronic_restore_proof',v_restore_proof,
    'tsfin_id',v_fin.id,
    'tsfin_updated_at_utc',v_fin.updated_at,
    'permitted_action',v_permitted,
    'warning_code',v_warning_code,
    'confirmation_required',v_confirmation_required,
    'reason_required',v_reason_required,
    'block_reason',v_block_reason,
    'fresh_submission_required',v_action in ('ALLOW_ELECTRONIC_AGAIN','ALLOW_QR_AGAIN','INVALIDATE_QR','REISSUE_QR'),
    'notification_required',v_action in ('ALLOW_ELECTRONIC_AGAIN','ALLOW_QR_AGAIN','INVALIDATE_QR','REISSUE_QR')
  );
  v_context_hash:=encode(digest(convert_to(v_payload::text,'UTF8'),'sha256'),'hex');
  return v_payload||jsonb_build_object('context_sha256',v_context_hash);
end;
$function$;

-- private._timesheet_route_resubmission_notifications_v1(uuid,uuid,integer,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._timesheet_route_resubmission_notifications_v1(p_old_timesheet_id uuid, p_new_timesheet_id uuid, p_new_version integer, p_target_action text, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_old public.timesheets%rowtype;
  v_new public.timesheets%rowtype;
  v_candidate public.candidates%rowtype;
  v_account public.candidate_app_accounts%rowtype;
  v_environment text;
  v_action text:=upper(btrim(coalesce(p_target_action,'')));
  v_key text;
  v_template text;
  v_created integer:=0;
  v_recipients integer:=0;
  v_existing boolean;
  v_push_enabled boolean;
  v_keys jsonb:='[]'::jsonb;
begin
  select * into v_old from public.timesheets where timesheet_id=p_old_timesheet_id;
  select * into v_new from public.timesheets where timesheet_id=p_new_timesheet_id;
  -- CONTRACT ownership is authoritative and does not depend on a GCK.  DAILY
  -- may fall through to current TSFIN/workflow/occupant identity.
  select candidate_row.* into v_candidate
  from public.contracts contract_row
  join public.candidates candidate_row on candidate_row.id=contract_row.candidate_id
  where contract_row.id=coalesce(v_new.contract_id,v_old.contract_id)
  limit 1;
  if not found then
    select candidate_row.* into v_candidate
    from public.timesheets_financials financial_row
    join public.candidates candidate_row on candidate_row.id=financial_row.candidate_id
    where financial_row.timesheet_id in (p_new_timesheet_id,p_old_timesheet_id)
      and financial_row.is_current=true
    order by (financial_row.timesheet_id=p_new_timesheet_id) desc,
      financial_row.updated_at desc,financial_row.id desc limit 1;
  end if;
  if not found then
    select workflow_candidate.* into v_candidate
  from public.candidate_submission_workflows workflow
  join public.candidates workflow_candidate on workflow_candidate.id=workflow.candidate_id
  where workflow.id=v_old.candidate_workflow_id
     or workflow.target_timesheet_id=p_old_timesheet_id
     or workflow.anchor_timesheet_id=p_old_timesheet_id
  order by (workflow.id=v_old.candidate_workflow_id) desc,workflow.updated_at_utc desc
  limit 1;
  end if;
  if not found then
    select * into v_candidate from public.candidates candidate_row
    where candidate_row.active=true
      and nullif(btrim(coalesce(candidate_row.key_norm,'')),'') is not null
      and btrim(candidate_row.key_norm)=btrim(coalesce(v_old.occupant_key_norm,''))
    order by candidate_row.id limit 1;
  end if;
  select candidate_app_environment into v_environment
  from public.settings_defaults where id=1;
  if v_candidate.id is null or v_environment is null then
    return jsonb_build_object('notification_required',true,'notification_created',false,
      'notification_created_count',0,'notification_recipient_count',0,
      'notification_recipient_unavailable',true,'notification_dedupe_keys','[]'::jsonb);
  end if;
  v_template:=case when v_action='ALLOW_QR_AGAIN'
    then 'candidate-paper-resubmission-required-v1'
    else 'candidate-electronic-resubmission-required-v1' end;

  for v_account in
    select distinct account_row.*
    from public.candidate_app_accounts account_row
    where account_row.environment=v_environment and account_row.status='ACTIVE'
      and (
        account_row.email_normalized=lower(btrim(coalesce(v_candidate.email,'')))
        or exists(select 1 from public.candidate_app_sessions session_row
          where session_row.account_id=account_row.id
            and session_row.selected_candidate_id=v_candidate.id)
        or exists(select 1 from public.candidate_submission_workflows workflow_row
          where workflow_row.account_id=account_row.id
            and workflow_row.candidate_id=v_candidate.id)
      )
    order by account_row.id
  loop
    v_recipients:=v_recipients+1;
    v_key:='candidate-resubmission-required:'||v_account.id::text||':'
      ||p_new_timesheet_id::text||':'||coalesce(p_new_version,1)::text;
    select exists(select 1 from public.candidate_notifications where dedupe_key=v_key)
      into v_existing;
    v_push_enabled:=coalesce(
      (v_account.notification_preferences_json->>'resubmission_required')::boolean,true
    );
    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    ) values (
      v_account.id,v_candidate.id,null,p_new_timesheet_id,'RESUBMISSION_REQUIRED',
      'resubmission_required',v_template,
      jsonb_build_object('route',case when v_action='ALLOW_QR_AGAIN' then 'PAPER' else 'ELECTRONIC' end),
      jsonb_build_object('type','timesheet','timesheet_id',p_new_timesheet_id,
        'submission_route',case when v_action='ALLOW_QR_AGAIN' then 'PAPER' else 'ELECTRONIC' end),
      'UNREAD',case when v_push_enabled then 'PENDING' else 'SKIPPED' end,
      v_key,p_now_utc
    ) on conflict (dedupe_key) do update set dedupe_key=excluded.dedupe_key;
    if not v_existing then v_created:=v_created+1; end if;
    v_keys:=v_keys||jsonb_build_array(v_key);
  end loop;
  return jsonb_build_object(
    'notification_required',true,'notification_created',v_created>0,
    'notification_created_count',v_created,'notification_recipient_count',v_recipients,
    'notification_recipient_unavailable',v_recipients=0,
    'notification_dedupe_keys',v_keys
  );
end;
$function$;

-- private._timesheet_route_supersede_candidate_v1(uuid,text,text,text,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION private._timesheet_route_supersede_candidate_v1(p_workflow_id uuid, p_action text, p_reason_code text, p_reason_note text, p_actor_user_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_workflow public.candidate_submission_workflows%rowtype;
  v_request public.candidate_approval_requests%rowtype;
  v_paper_retirement_result jsonb:='{}'::jsonb;
  v_manager_retirement_result jsonb:='{}'::jsonb;
  v_withdrawal_required boolean:=false;
  v_cancelled integer:=0;
  v_superseded integer:=0;
  v_mail_ids jsonb:='[]'::jsonb;
  v_mail_id uuid;
  v_reason text:=btrim(coalesce(p_reason_code,''))
    ||case when nullif(btrim(coalesce(p_reason_note,'')),'') is not null
      then ': '||btrim(p_reason_note) else '' end;
begin
  if p_workflow_id is null then
    return jsonb_build_object('workflow_changed',false,'manager_request_cancelled',false,
      'manager_cancellation_email_queued',false,'manager_cancellation_mail_ids','[]'::jsonb);
  end if;
  select * into v_workflow from public.candidate_submission_workflows
  where id=p_workflow_id for update;
  if not found then
    return jsonb_build_object('workflow_changed',false,'workflow_id',p_workflow_id,
      'manager_request_cancelled',false,'manager_cancellation_email_queued',false,
      'manager_cancellation_mail_ids','[]'::jsonb);
  end if;

  if v_workflow.route='PAPER'
     and v_workflow.state in ('AWAITING_PAPER_RETURN','RECEIVED','FINALISED') then
    v_paper_retirement_result:=private._candidate_paper_delivery_retire_set_v1(
      array[v_workflow.id],array[v_workflow.generation],
      'ROUTE_INTERVENTION_'||upper(btrim(coalesce(p_action,'UNKNOWN'))),p_now_utc
    );
    if not coalesce((v_paper_retirement_result->>'retired')::boolean,false)
       or not coalesce(
         (v_paper_retirement_result->>'qr_invalidation_proven')::boolean,false
       ) then
      raise exception 'CANDIDATE_PAPER_QR_INVALIDATION_NOT_PROVEN'
        using errcode='40001',detail=v_paper_retirement_result::text;
    end if;
    if exists(
      select 1
      from jsonb_array_elements(
        coalesce(v_paper_retirement_result->'preserved_workflows','[]'::jsonb)
      ) preserved
      where preserved->>'workflow_state' in ('AWAITING_PAPER_RETURN','RECEIVED')
    ) then
      raise exception 'CANDIDATE_PAPER_SHARED_SOURCE_WORKFLOW_CONFLICT'
        using errcode='40001',detail=v_paper_retirement_result::text;
    end if;
    -- A finalised workflow is immutable historical approval. Retire only its
    -- preceding delivery generation; the route version may change without
    -- rewriting the finalised workflow or signed document/evidence history.
    if v_workflow.state='FINALISED' then
      return jsonb_build_object(
        'workflow_changed',false,'workflow_id',v_workflow.id,
        'paper_delivery_retired',true,
        'paper_delivery_retirement',v_paper_retirement_result,
        'manager_request_cancelled',false,
        'manager_cancellation_email_queued',false,
        'manager_cancellation_mail_ids','[]'::jsonb
      );
    end if;
  end if;

  -- REFUSED remains amendable in the Candidate workflow contract.  An office
  -- route intervention that has explicitly confirmed removal may therefore
  -- supersede it while retaining refusal reason/timestamps and audit history.
  if v_workflow.state in ('FINALISED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED') then
    return jsonb_build_object('workflow_changed',false,'workflow_id',p_workflow_id,
      'paper_delivery_retired',false,
      'manager_request_cancelled',false,'manager_cancellation_email_queued',false,
      'manager_cancellation_mail_ids','[]'::jsonb);
  end if;

  for v_request in
    select * from public.candidate_approval_requests
    where workflow_id=v_workflow.id and state in ('PENDING','APPROVED')
    order by created_at_utc,id for update
  loop
    v_withdrawal_required:=false;
    if v_request.method='EMAIL' then
      v_manager_retirement_result:=private._candidate_manager_mail_retire_v1(
        v_workflow.id,v_request.workflow_generation,array[v_request.id],
        'ROUTE_INTERVENTION_'||upper(btrim(coalesce(p_action,'UNKNOWN'))),p_now_utc
      );
      v_withdrawal_required:=coalesce(
        (v_manager_retirement_result->>'withdrawal_required')::boolean,false
      );
    end if;
    if v_request.state='PENDING' then
      if v_request.expires_at_utc is not null and v_request.expires_at_utc<=p_now_utc then
        update public.candidate_approval_requests set
          state='EXPIRED',updated_at_utc=p_now_utc
        where id=v_request.id;
        continue;
      end if;
      update public.candidate_approval_requests set
        state='CANCELLED',cancelled_at_utc=p_now_utc,updated_at_utc=p_now_utc
      where id=v_request.id;
      if v_request.method='EMAIL' and v_withdrawal_required
         and v_request.manager_email_normalized is not null then
        v_mail_id:=private._candidate_queue_mail_v1(
          jsonb_build_object(
            'subject','Timesheet approval request withdrawn',
            'body_text','The approval request for this timesheet has been withdrawn by CloudTMS. No further action is required.',
            'email_type','CANDIDATE_MANAGER_APPROVAL_WITHDRAWN',
            'payment_scope_json',jsonb_build_object(
              'candidate_mail_authority','MANAGER_APPROVAL_V1',
              'candidate_manager_mail_kind','WITHDRAWAL',
              'candidate_manager_workflow_id',v_workflow.id,
              'candidate_manager_workflow_generation',v_request.workflow_generation,
              'candidate_approval_request_id',v_request.id,
              'candidate_approval_request_generation',v_request.request_generation,
              'candidate_manager_mail_retired',false
            )
          ),
          v_request.manager_email_normalized,
          'CANDIDATE_MANAGER_APPROVAL_WITHDRAWN_V1:'||v_request.id::text,
          'candidate-manager-approval-withdrawn:'||v_request.id::text,
          v_workflow.id,p_now_utc
        );
        v_mail_ids:=v_mail_ids||jsonb_build_array(v_mail_id);
      end if;
      v_cancelled:=v_cancelled+1;
    else
      update public.candidate_approval_requests set
        state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
      where id=v_request.id;
      if v_request.method='EMAIL' and v_withdrawal_required
         and v_request.manager_email_normalized is not null then
        v_mail_id:=private._candidate_queue_mail_v1(
          jsonb_build_object(
            'subject','Timesheet approval request withdrawn',
            'body_text','The approval request for this timesheet has been withdrawn by CloudTMS. No further action is required.',
            'email_type','CANDIDATE_MANAGER_APPROVAL_WITHDRAWN',
            'payment_scope_json',jsonb_build_object(
              'candidate_mail_authority','MANAGER_APPROVAL_V1',
              'candidate_manager_mail_kind','WITHDRAWAL',
              'candidate_manager_workflow_id',v_workflow.id,
              'candidate_manager_workflow_generation',v_request.workflow_generation,
              'candidate_approval_request_id',v_request.id,
              'candidate_approval_request_generation',v_request.request_generation,
              'candidate_manager_mail_retired',false
            )
          ),
          v_request.manager_email_normalized,
          'CANDIDATE_MANAGER_APPROVAL_WITHDRAWN_V1:'||v_request.id::text,
          'candidate-manager-approval-withdrawn:'||v_request.id::text,
          v_workflow.id,p_now_utc
        );
        v_mail_ids:=v_mail_ids||jsonb_build_array(v_mail_id);
      end if;
      v_superseded:=v_superseded+1;
    end if;
  end loop;

  update public.candidate_submission_components set
    state='SUPERSEDED',superseded_at_utc=p_now_utc,
    review_render_state=case when review_render_state='NOT_REQUIRED'
      then review_render_state else 'SUPERSEDED' end,
    final_signed_render_state=case when final_signed_render_state='NOT_REQUIRED'
      then final_signed_render_state else 'SUPERSEDED' end
  where workflow_id=v_workflow.id and state not in ('SUPERSEDED','REJECTED');

  update public.candidate_submission_workflows set
    state='SUPERSEDED',cancelled_at_utc=coalesce(cancelled_at_utc,p_now_utc),
    last_mutation_idempotency_key='ROUTE_INTERVENTION:'||upper(btrim(p_action))||':'||v_workflow.generation::text,
    last_mutation_response_json=jsonb_build_object(
      'ok',true,'state','SUPERSEDED','reason_code',p_reason_code,
      'reason_note',nullif(btrim(coalesce(p_reason_note,'')),'')
    ),updated_at_utc=p_now_utc
  where id=v_workflow.id;

  perform private._candidate_audit_v1(
    'candidate_submission_workflow',v_workflow.id::text,'ROUTE_INTERVENTION_SUPERSEDE',
    jsonb_build_object('state',v_workflow.state,'generation',v_workflow.generation),
    jsonb_build_object('state','SUPERSEDED','action',upper(btrim(p_action))),
    v_reason,p_actor_user_id,'route-intervention:'||v_workflow.id::text,p_now_utc
  );
  return jsonb_build_object(
    'workflow_changed',true,'workflow_id',v_workflow.id,
    'paper_delivery_retired',coalesce((v_paper_retirement_result->>'retired')::boolean,false),
    'paper_delivery_retirement',v_paper_retirement_result,
    'manager_request_cancelled',v_cancelled>0,
    'cancelled_request_count',v_cancelled,'superseded_request_count',v_superseded,
    'manager_cancellation_email_queued',jsonb_array_length(v_mail_ids)>0,
    'manager_cancellation_mail_ids',v_mail_ids
  );
end;
$function$;

-- private._timesheet_route_version_core_v1(uuid,uuid,text,uuid,boolean)
CREATE OR REPLACE FUNCTION private._timesheet_route_version_core_v1(p_current_timesheet_id uuid, p_expected_timesheet_id uuid, p_target_action text, p_actor_user_id uuid, p_allow_manual_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text := upper(btrim(coalesce(p_target_action, '')));
  v_now timestamptz := now();

  v_requested_row public.timesheets%ROWTYPE;
  v_current_row public.timesheets%ROWTYPE;
  v_new_row public.timesheets%ROWTYPE;
  v_electronic_row public.timesheets%ROWTYPE;
  v_contract_week_row public.contract_weeks%ROWTYPE;
  v_tsfin_row public.timesheets_financials%ROWTYPE;
  v_revert_workflow public.candidate_submission_workflows%ROWTYPE;
  v_revert_approval_request public.candidate_approval_requests%ROWTYPE;
  v_revert_hours_component public.candidate_submission_components%ROWTYPE;
  v_revert_candidate_signature public.candidate_submission_components%ROWTYPE;
  v_revert_manager_signature public.candidate_submission_components%ROWTYPE;
  v_revert_evidence public.timesheet_evidence%ROWTYPE;
  v_revert_required_component_ids uuid[];
  v_current_financial_sha256 bytea;

  v_booking_id text;
  v_requested_timesheet_id uuid;
  v_current_timesheet_id uuid;
  v_new_timesheet_id uuid;
  v_contract_week_id uuid;
  v_contract_id uuid;
  v_client_id uuid;

  v_next_version integer;
  v_old_version integer;
  v_new_version integer;
  v_electronic_version integer;

  v_scope text;
  v_submission_mode text;
  v_qr_status text;
  v_basis text;

  v_has_qr_token boolean := false;
  v_has_qr_generated boolean := false;
  v_has_qr_scanned boolean := false;
  v_is_manual_only boolean := false;
  v_hard_locked boolean := false;
  v_has_segment_invoice_lock boolean := false;
  v_supports_electronic boolean := false;
  v_effective_mode public.submission_mode_enum;
  v_effective_policy jsonb := '{}'::jsonb;
  v_has_prior_qr_lineage boolean := false;
  v_was_stale boolean := false;

  v_is_import_authoritative boolean := false;
  v_import_authority jsonb := '{}'::jsonb;

  v_reverted boolean := false;
  v_switched boolean := false;
  v_converted boolean := false;

BEGIN
  IF p_current_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'timesheet_id is required';
  END IF;

  IF p_expected_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'expected_timesheet_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_action NOT IN (
    'CONVERT_QR_TO_MANUAL',
    'ALLOW_ELECTRONIC_AGAIN',
    'ALLOW_QR_AGAIN',
    'INVALIDATE_QR',
    'REISSUE_QR',
    'DISABLE_QR',
    'SWITCH_TO_MANUAL',
    'SWITCH_DAILY_TO_MANUAL',
    'REVERT_TO_ELECTRONIC'
  ) THEN
    RAISE EXCEPTION 'Unsupported target action: %', p_target_action;
  END IF;

  SELECT t_req.*
  INTO v_requested_row
  FROM public.timesheets AS t_req
  WHERE t_req.timesheet_id = p_current_timesheet_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Timesheet not found';
  END IF;

  v_requested_timesheet_id := v_requested_row.timesheet_id;
  v_booking_id := v_requested_row.booking_id;

  IF v_booking_id IS NULL OR btrim(v_booking_id) = '' THEN
    RAISE EXCEPTION 'Timesheet booking_id is missing; cannot version';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(v_booking_id));

  PERFORM 1
  FROM public.timesheets AS t_lock
  WHERE t_lock.booking_id = v_booking_id
  FOR UPDATE;

  SELECT t_cur.*
  INTO v_current_row
  FROM public.timesheets AS t_cur
  WHERE t_cur.booking_id = v_booking_id
    AND t_cur.is_current = true
  ORDER BY t_cur.version DESC, t_cur.updated_at DESC, t_cur.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    IF coalesce(v_requested_row.is_current, false) = true THEN
      v_current_row := v_requested_row;
    ELSE
      RAISE EXCEPTION 'Timesheet not found';
    END IF;
  END IF;

  v_current_timesheet_id := v_current_row.timesheet_id;
  v_was_stale := (v_requested_timesheet_id IS DISTINCT FROM v_current_timesheet_id);

  IF v_current_timesheet_id IS DISTINCT FROM p_expected_timesheet_id THEN
    RAISE EXCEPTION 'TIMESHEET_MOVED'
      USING DETAIL = jsonb_build_object(
        'current_timesheet_id', v_current_timesheet_id::text
      )::text;
  END IF;

  v_old_version := coalesce(v_current_row.version, 1);
  v_scope := upper(coalesce(v_current_row.sheet_scope::text, ''));
  v_submission_mode := upper(coalesce(v_current_row.submission_mode::text, ''));
  v_qr_status := upper(coalesce(v_current_row.qr_status::text, ''));

  -- The coordinated Candidate route authority never creates or replaces a
  -- DAILY paper route.  The dormant flag-off wrapper still delegates to the
  -- exact legacy owner, preserving existing office behaviour until cutover.
  IF v_scope = 'DAILY'
     AND v_action IN ('ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR') THEN
    RAISE EXCEPTION 'DAILY_PAPER_ROUTE_NOT_ALLOWED'
      USING ERRCODE='55000', DETAIL=jsonb_build_object(
        'code','DAILY_PAPER_ROUTE_NOT_ALLOWED',
        'sheet_scope',v_scope,
        'action',v_action
      )::text;
  END IF;

  IF v_current_row.archived_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'TIMESHEET_ARCHIVED_EDIT_BLOCKED: Archived timesheets cannot rotate submission route';
  END IF;

  SELECT cw_cur.*
  INTO v_contract_week_row
  FROM public.contract_weeks AS cw_cur
  WHERE cw_cur.timesheet_id = v_current_timesheet_id
  ORDER BY cw_cur.updated_at DESC, cw_cur.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    v_contract_week_id := v_contract_week_row.id;
    PERFORM 1
    FROM public.contract_weeks AS cw_lock
    WHERE cw_lock.id = v_contract_week_id
    FOR UPDATE;
  ELSE
    v_contract_week_id := NULL;
  END IF;

  SELECT tf_cur.*
  INTO v_tsfin_row
  FROM public.timesheets_financials AS tf_cur
  WHERE tf_cur.timesheet_id = v_current_timesheet_id
    AND tf_cur.is_current = true
  ORDER BY tf_cur.updated_at DESC, tf_cur.created_at DESC
  LIMIT 1;

  IF v_tsfin_row.id IS NOT NULL THEN
    PERFORM 1
    FROM public.timesheets_financials AS tf_lock
    WHERE tf_lock.id = v_tsfin_row.id
    FOR UPDATE;
  END IF;

  v_contract_id := coalesce(v_contract_week_row.contract_id, v_current_row.contract_id);
  v_client_id := v_tsfin_row.client_id;

  IF v_contract_id IS NOT NULL THEN
    SELECT coalesce(c.client_id, v_client_id)
    INTO v_client_id
    FROM public.contracts AS c
    WHERE c.id = v_contract_id
    LIMIT 1;
  END IF;

  IF v_client_id IS NOT NULL THEN
    v_import_authority := private._candidate_import_authoritative_v1(
      v_client_id,
      v_contract_id,
      v_current_timesheet_id,
      CASE WHEN v_tsfin_row.id IS NULL THEN NULL ELSE to_jsonb(v_tsfin_row) END,
      v_current_row.week_ending_date
    );
    v_is_import_authoritative := coalesce(
      (v_import_authority ->> 'is_import_authoritative')::boolean,
      false
    );
  END IF;

  IF v_is_import_authoritative THEN
    RAISE EXCEPTION 'Import-authoritative timesheets (NHSP / HealthRoster weekly no-timesheets) cannot change submission route';
  END IF;

  -- Route/version rotation invalidates the evidence and signature lineage that
  -- supported the current lifecycle.  It is never an alternative
  -- unauthorisation implementation: callers must compose the existing
  -- CloudTMS unauthorise authority first.
  IF v_current_row.authorised_at_server IS NOT NULL
     OR v_tsfin_row.authorised_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before changing its submission route.';
  END IF;

  IF v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR') THEN
    IF (
      v_current_row.authorised_at_server IS NOT NULL
      AND btrim(v_current_row.authorised_at_server::text) <> ''
      AND (v_current_row.revoked_at IS NULL OR btrim(v_current_row.revoked_at::text) = '')
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before converting QR to manual.';
    END IF;

    IF v_scope <> '' AND v_scope NOT IN ('WEEKLY', 'DAILY') THEN
      RAISE EXCEPTION 'Unsupported sheet_scope for QR conversion';
    END IF;

    IF v_submission_mode <> 'MANUAL' THEN
      RAISE EXCEPTION 'Timesheet is not in MANUAL mode; QR conversion not applicable';
    END IF;

    IF v_qr_status = '' THEN
      RAISE EXCEPTION 'Timesheet does not have QR metadata; nothing to convert';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'No financial snapshot for timesheet';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
      OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                      );

    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot convert QR: timesheet already invoiced or paid';
    END IF;
  ELSIF v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN
    IF v_current_row.is_adjustment = true OR coalesce(v_contract_week_row.is_adjustment, false) = true THEN
      RAISE EXCEPTION 'Adjustment timesheets cannot be converted to electronic submission';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
      OR coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
    );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot allow electronic again: timesheet is invoiced/locked or paid';
    END IF;

    v_has_qr_token := (btrim(coalesce(v_current_row.qr_token, '')) <> '');
    v_has_qr_generated := (v_current_row.qr_generated_at IS NOT NULL);
    v_has_qr_scanned := (v_current_row.qr_scanned_at IS NOT NULL);
    v_is_manual_only := (
      v_submission_mode = 'MANUAL'
      AND v_qr_status = ''
      AND v_has_qr_token = false
      AND v_has_qr_generated = false
      AND v_has_qr_scanned = false
    );

    IF v_is_manual_only = false THEN
      RAISE EXCEPTION 'Allow electronic again is only valid for manual-only timesheets';
    END IF;

    IF v_client_id IS NULL AND v_contract_id IS NOT NULL THEN
      BEGIN
        SELECT c_client.client_id
        INTO v_client_id
        FROM public.contracts AS c_client
        WHERE c_client.id = v_contract_id
        LIMIT 1;
      EXCEPTION WHEN OTHERS THEN
        v_client_id := NULL;
      END;
    END IF;

    IF v_client_id IS NULL THEN
      RAISE EXCEPTION 'Cannot resolve client_id for electronic eligibility check';
    END IF;

    v_effective_mode := private._candidate_submission_mode_v1(
      v_client_id,
      v_contract_id,
      coalesce(v_current_row.week_ending_date,
        (current_timestamp at time zone 'Europe/London')::date)
    );
    v_supports_electronic := v_effective_mode='ELECTRONIC'::public.submission_mode_enum;

    IF coalesce(v_supports_electronic, false) = false THEN
      RAISE EXCEPTION 'Client does not support electronic submission';
    END IF;
  ELSIF v_action IN ('ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR') THEN
    IF v_current_row.is_adjustment = true THEN
      RAISE EXCEPTION 'Adjustment timesheets cannot be converted to QR submission';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
      OR coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
    );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot allow QR again: timesheet is invoiced/locked or paid';
    END IF;

    v_has_qr_token := (btrim(coalesce(v_current_row.qr_token, '')) <> '');
    v_has_qr_generated := (v_current_row.qr_generated_at IS NOT NULL);
    v_has_qr_scanned := (v_current_row.qr_scanned_at IS NOT NULL);
    v_is_manual_only := (
      v_submission_mode = 'MANUAL'
      AND v_qr_status = ''
      AND v_has_qr_token = false
      AND v_has_qr_generated = false
      AND v_has_qr_scanned = false
    );

    IF v_action = 'ALLOW_QR_AGAIN' AND v_is_manual_only = false THEN
      RAISE EXCEPTION 'Allow QR again is only valid for manual-only timesheets';
    END IF;
    IF v_action = 'ALLOW_QR_AGAIN' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.timesheets qr_history
        WHERE qr_history.booking_id=v_booking_id
          AND (
            qr_history.qr_status IS NOT NULL
            OR nullif(btrim(coalesce(qr_history.qr_token,'')),'') IS NOT NULL
            OR qr_history.qr_generated_at IS NOT NULL
            OR qr_history.qr_scanned_at IS NOT NULL
            OR nullif(btrim(coalesce(qr_history.qr_r2_key,'')),'') IS NOT NULL
            OR qr_history.qr_signed_at_utc IS NOT NULL
          )
      ) INTO v_has_prior_qr_lineage;
      IF v_client_id IS NULL OR v_contract_id IS NULL THEN
        RAISE EXCEPTION 'Cannot resolve effective paper submission policy';
      END IF;
      v_effective_policy:=private._candidate_policy_resolve_v1(
        v_client_id,v_contract_id,
        coalesce(v_current_row.week_ending_date,
          (current_timestamp at time zone 'Europe/London')::date)
      );
      IF NOT v_has_prior_qr_lineage
         AND NOT coalesce((v_effective_policy->>'paper_submission_enabled')::boolean,false) THEN
        RAISE EXCEPTION 'ALLOW_QR_AGAIN_REQUIRES_PRIOR_LINEAGE_OR_PAPER_PERMISSION'
          USING ERRCODE='55000';
      END IF;
    END IF;
    IF v_action IN ('INVALIDATE_QR', 'REISSUE_QR')
       AND v_qr_status = '' AND v_has_qr_token = false
       AND v_has_qr_generated = false AND v_has_qr_scanned = false THEN
      RAISE EXCEPTION 'QR invalidation/reissue requires an actual QR-backed current timesheet';
    END IF;
  ELSIF v_action = 'SWITCH_TO_MANUAL' THEN
    IF (
      v_current_row.authorised_at_server IS NOT NULL
      AND btrim(v_current_row.authorised_at_server::text) <> ''
      AND (v_current_row.revoked_at IS NULL OR btrim(v_current_row.revoked_at::text) = '')
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before switching to manual.';
    END IF;

    IF v_scope <> 'WEEKLY' THEN
      RAISE EXCEPTION 'Only WEEKLY timesheets can be switched to manual';
    END IF;

    IF NOT (
      v_submission_mode = 'ELECTRONIC'
      OR (
        v_submission_mode = 'MANUAL'
        AND upper(coalesce(v_contract_week_row.submission_mode_snapshot::text,''))='ELECTRONIC'
      )
    ) THEN
      RAISE EXCEPTION 'Timesheet is not an electronic weekly timesheet';
    END IF;

    IF v_contract_week_row.id IS NULL THEN
      RAISE EXCEPTION 'Timesheet not linked to a contract week';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'No financial snapshot to switch';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
      OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                      );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot switch: timesheet already invoiced or paid';
    END IF;

    v_basis := upper(coalesce(v_tsfin_row.basis::text, ''));
    IF v_basis <> 'CONTRACT_WEEKLY' THEN
      RAISE EXCEPTION 'Only CONTRACT_WEEKLY timesheets can be switched to manual';
    END IF;
  ELSIF v_action = 'SWITCH_DAILY_TO_MANUAL' THEN
    IF (
      v_current_row.authorised_at_server IS NOT NULL
      AND btrim(v_current_row.authorised_at_server::text) <> ''
      AND (v_current_row.revoked_at IS NULL OR btrim(v_current_row.revoked_at::text) = '')
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before switching to manual.';
    END IF;

    IF v_booking_id IS NULL
      OR btrim(v_booking_id) = ''
      OR btrim(v_booking_id) = '{}'
      OR lower(btrim(v_booking_id)) = 'null'
      OR lower(btrim(v_booking_id)) = 'undefined'
    THEN
      RAISE EXCEPTION 'Timesheet booking_id is invalid; cannot rotate versions. Please repair booking_id.';
    END IF;

    IF v_scope <> 'DAILY' THEN
      RAISE EXCEPTION 'Only DAILY timesheets can be switched to manual via this endpoint';
    END IF;

    IF NOT (
      v_submission_mode = 'ELECTRONIC'
      OR (
        v_submission_mode = 'MANUAL'
        AND v_current_row.candidate_submission_route_intent='ELECTRONIC'
      )
    ) THEN
      RAISE EXCEPTION 'Timesheet is not an electronic daily timesheet';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'No financial snapshot to switch';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
      OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                      );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot switch: timesheet already invoiced or paid';
    END IF;

    v_basis := upper(coalesce(v_tsfin_row.basis::text, ''));
    IF v_basis IN ('NHSP', 'NHSP_ADJUSTMENT', 'HEALTHROSTER_SELF_BILL', 'HEALTHROSTER_ADJUSTMENT') THEN
      RAISE EXCEPTION 'Cannot switch NHSP/HR-based daily timesheets to manual';
    END IF;
  ELSIF v_action = 'REVERT_TO_ELECTRONIC' THEN
    IF v_current_row.is_adjustment = true THEN
      RAISE EXCEPTION 'Adjustment timesheets cannot be reverted/converted to electronic submission';
    END IF;

    SELECT t_elec.*
    INTO v_electronic_row
    FROM public.timesheets AS t_elec
    WHERE t_elec.booking_id = v_booking_id
      AND upper(coalesce(t_elec.submission_mode::text, '')) = 'ELECTRONIC'
    ORDER BY t_elec.version DESC, t_elec.updated_at DESC, t_elec.created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'No electronic version exists for this timesheet';
    END IF;

    IF v_tsfin_row.id IS NOT NULL THEN
      v_has_segment_invoice_lock := EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE
            WHEN v_tsfin_row.invoice_breakdown_json IS NOT NULL
             AND jsonb_typeof(v_tsfin_row.invoice_breakdown_json) = 'object'
             AND jsonb_typeof(v_tsfin_row.invoice_breakdown_json -> 'segments') = 'array'
            THEN v_tsfin_row.invoice_breakdown_json -> 'segments'
            ELSE '[]'::jsonb
          END
        ) AS s(seg)
        WHERE nullif(btrim(coalesce(s.seg ->> 'invoice_locked_invoice_id', '')), '') IS NOT NULL
      );

      v_hard_locked := (
        coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
        OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                                OR v_has_segment_invoice_lock
      );

      IF v_hard_locked THEN
        RAISE EXCEPTION 'Cannot revert: current timesheet is invoiced or paid';
      END IF;
    END IF;

    v_has_qr_token := (btrim(coalesce(v_current_row.qr_token, '')) <> '');
    v_has_qr_generated := (v_current_row.qr_generated_at IS NOT NULL);
    v_has_qr_scanned := (v_current_row.qr_scanned_at IS NOT NULL);
    v_is_manual_only := (
      v_submission_mode = 'MANUAL'
      AND v_qr_status = ''
      AND v_has_qr_token = false
      AND v_has_qr_generated = false
      AND v_has_qr_scanned = false
    );

    IF v_is_manual_only = true AND coalesce(p_allow_manual_only, false) = false THEN
      RAISE EXCEPTION 'Cannot revert: current is manual-only (set allow_manual_only=true to override)';
    END IF;

    IF v_current_timesheet_id = v_electronic_row.timesheet_id AND coalesce(v_current_row.is_current, false) = true THEN
      RETURN jsonb_build_object(
        'ok', true,
        'action', v_action,
        'reverted', false,
        'reason', 'Electronic version is already current',
        'booking_id', v_booking_id,
        'current_timesheet_id', v_current_timesheet_id::text,
        'current_version', coalesce(v_electronic_row.version, 1),
        'requested_timesheet_id', v_requested_timesheet_id::text,
        'was_stale', v_was_stale
      );
    END IF;
  END IF;

  SELECT coalesce(max(t_ver.version), 0) + 1
  INTO v_next_version
  FROM public.timesheets AS t_ver
  WHERE t_ver.booking_id = v_booking_id;

  IF v_action <> 'REVERT_TO_ELECTRONIC' THEN
    UPDATE public.timesheets AS t_demote
    SET
      is_current = false,
      status = 'REVOKED'::public.timesheet_status_enum,
      revoked_at = v_now,
      revoked_reason = CASE
        WHEN v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR') THEN 'QR_CONVERTED_TO_MANUAL'
        WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'ALLOW_ELECTRONIC_AGAIN'
        WHEN v_action = 'ALLOW_QR_AGAIN' THEN 'ALLOW_QR_AGAIN'
        WHEN v_action IN ('INVALIDATE_QR', 'REISSUE_QR') THEN 'QR_INVALIDATED_AFTER_CONTENT_CHANGE'
        WHEN v_action IN ('SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN 'SWITCHED_TO_MANUAL'
        ELSE t_demote.revoked_reason
      END,
      revoked_by = CASE
        WHEN v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR', 'ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR', 'SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL')
        THEN p_actor_user_id::text
        ELSE t_demote.revoked_by
      END,
      updated_at = v_now
    WHERE t_demote.booking_id = v_booking_id
      AND t_demote.is_current = true;

    -- Explicit route-version field matrix. Business facts are copied; every
    -- signature, QR token, generated/manual document and authorisation fact is
    -- deliberately cleared so a new route can never inherit stale evidence.
    INSERT INTO public.timesheets (
      timesheet_id, booking_id, occupant_key_norm, hospital_norm, ward_norm,
      job_title_norm, shift_label_norm, scheduled_start_iso, scheduled_end_iso,
      worked_start_iso, worked_end_iso, break_start_iso, break_end_iso,
      break_minutes, worked_minutes, week_ending_date, auth_name,
      auth_job_title, authorised_at_server, r2_nurse_key, r2_auth_key,
      img_sha256_nurse, img_sha256_auth, reference_number, reference_set_at,
      status, idempotency_key, client_hash, client_ua, created_at, updated_at,
      version, is_current, revoked_at, revoked_reason, revoked_by, contract_id,
      submission_mode, manual_pdf_r2_key, line_type, sheet_scope,
      actual_schedule_json, additional_units_week, additional_units_per_day,
      qr_token, qr_status, qr_payload_json, qr_generated_at, qr_scanned_at,
      qr_scan_info_json, qr_r2_key, day_references_json,
      manual_pdf_rotation_degrees, qr_last_sent_hash, qr_last_sent_at_utc,
      qr_signed_hash, qr_signed_at_utc, candidate_hint_text, band,
      generated_pdf_at_utc, is_adjustment, parent_timesheet_id,
      generated_pdf_refs_sig, generated_pdf_refs_snapshot_json,
      generated_pdf_refs_captured_at_utc, qr_sent_refs_sig,
      qr_sent_refs_snapshot_json, qr_sent_refs_captured_at_utc, correction_id,
      correction_kind, adjustment_origin, archived_at_utc,
      archived_by_user_id, archived_reason_code, document_revision,
      document_state, current_document_version_id,
      active_document_operation_id, manual_document_asset_id,
      last_document_error_json, candidate_workflow_id,
      candidate_workflow_generation, candidate_manager_approved_at_utc,
      candidate_submission_route_intent
    )
    SELECT
      gen_random_uuid(), v_booking_id, v_current_row.occupant_key_norm,
      v_current_row.hospital_norm, v_current_row.ward_norm,
      v_current_row.job_title_norm, v_current_row.shift_label_norm,
      v_current_row.scheduled_start_iso, v_current_row.scheduled_end_iso,
      v_current_row.worked_start_iso, v_current_row.worked_end_iso,
      v_current_row.break_start_iso, v_current_row.break_end_iso,
      v_current_row.break_minutes, v_current_row.worked_minutes,
      v_current_row.week_ending_date, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_current_row.reference_number, v_current_row.reference_set_at,
      'RECEIVED'::public.timesheet_status_enum, NULL, NULL, NULL, v_now, v_now,
      v_next_version, true, NULL, NULL, NULL, v_current_row.contract_id,
      -- A canonical ELECTRONIC row is forbidden until both signatures exist.
      -- Fresh electronic resubmission is represented by a clean unsigned row
      -- plus the authoritative ELECTRONIC contract-week route snapshot.  The
      -- existing WEEKLY finalisation authority sets ELECTRONIC atomically with
      -- the complete candidate/manager signature pair.
      'MANUAL'::public.submission_mode_enum,
      NULL, v_current_row.line_type, v_current_row.sheet_scope,
      v_current_row.actual_schedule_json,
      coalesce(v_current_row.additional_units_week, '{}'::jsonb),
      coalesce(v_current_row.additional_units_per_day, '{}'::jsonb),
      NULL,
      CASE WHEN v_action IN ('ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR')
        THEN 'PENDING'::public.timesheet_qr_status_enum ELSE NULL END,
      '{}'::jsonb, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL,
      v_current_row.candidate_hint_text, v_current_row.band, NULL,
      v_current_row.is_adjustment, v_current_row.parent_timesheet_id,
      NULL, NULL, NULL, NULL, NULL, NULL, v_current_row.correction_id,
      v_current_row.correction_kind, v_current_row.adjustment_origin,
      NULL, NULL, NULL, 1, 'NOT_REQUESTED', NULL, NULL, NULL, NULL,
      NULL, NULL, NULL,
      case
        when v_action='ALLOW_ELECTRONIC_AGAIN' and v_scope='DAILY' then 'ELECTRONIC'
        when v_action in ('ALLOW_QR_AGAIN','INVALIDATE_QR','REISSUE_QR')
          and v_scope='WEEKLY' then 'PAPER'
        else null
      end
    RETURNING * INTO v_new_row;

    v_new_timesheet_id := v_new_row.timesheet_id;
    v_new_version := v_new_row.version;

    IF v_new_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'Insert succeeded but no timesheet_id returned';
    END IF;

    IF v_action = 'SWITCH_TO_MANUAL' THEN
      IF v_contract_week_row.id IS NULL THEN
        RAISE EXCEPTION 'Timesheet not linked to a contract week';
      END IF;

      UPDATE public.contract_weeks AS cw_upd
      SET
        timesheet_id = v_new_timesheet_id,
        submission_mode_snapshot = 'MANUAL'::public.submission_mode_enum,
        updated_at = v_now
      WHERE cw_upd.id = v_contract_week_row.id;
    ELSIF v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR', 'ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR') THEN
      IF v_contract_week_row.id IS NOT NULL THEN
        UPDATE public.contract_weeks AS cw_move
        SET
          timesheet_id = v_new_timesheet_id,
          submission_mode_snapshot = CASE
            WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN'
              THEN 'ELECTRONIC'::public.submission_mode_enum
            ELSE 'MANUAL'::public.submission_mode_enum
          END,
          updated_at = v_now
        WHERE cw_move.id = v_contract_week_row.id;
      END IF;
    END IF;

    IF v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR', 'SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN
      IF v_tsfin_row.id IS NULL THEN
        RAISE EXCEPTION 'No financial snapshot to switch';
      END IF;

      UPDATE public.timesheets_financials AS tf_upd
      SET
        timesheet_id = v_new_timesheet_id,
        timesheet_version = coalesce(v_new_row.version, v_next_version),
        processing_status = CASE
          WHEN v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR') THEN
            CASE WHEN tf_upd.processing_status = 'UNPROCESSED'::public.ts_fin_processing_status_enum
              THEN 'UNPROCESSED'::public.ts_fin_processing_status_enum
              ELSE 'AWAITING_MANUAL_SIGNATURE'::public.ts_fin_processing_status_enum END
          ELSE tf_upd.processing_status
        END,
        authorised_by_user_id = NULL,
        authorised_at_utc = NULL,
        updated_at = v_now
      WHERE tf_upd.id = v_tsfin_row.id;
    ELSIF v_action IN ('ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR') THEN
      IF v_tsfin_row.id IS NOT NULL THEN
        UPDATE public.timesheets_financials AS tf_upd
        SET
          timesheet_id = v_new_timesheet_id,
          timesheet_version = coalesce(v_new_row.version, v_next_version),
          processing_status = CASE
            WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'UNASSIGNED'::public.ts_fin_processing_status_enum
            WHEN v_action IN ('ALLOW_QR_AGAIN', 'INVALIDATE_QR', 'REISSUE_QR') THEN
              CASE WHEN tf_upd.processing_status = 'UNPROCESSED'::public.ts_fin_processing_status_enum
                THEN 'UNPROCESSED'::public.ts_fin_processing_status_enum
                ELSE 'AWAITING_MANUAL_SIGNATURE'::public.ts_fin_processing_status_enum END
            ELSE tf_upd.processing_status
          END,
          -- Defensive only: the central precondition above proves these are
          -- already null.  Keeping the new generation explicit prevents stale
          -- lifecycle values reappearing if this branch changes later.
          authorised_by_user_id = NULL,
          authorised_at_utc = NULL,
          updated_at = v_now
        WHERE tf_upd.id = v_tsfin_row.id;
      END IF;
    END IF;

    IF v_action IN ('CONVERT_QR_TO_MANUAL', 'DISABLE_QR') THEN
      v_converted := true;
    ELSE
      v_switched := true;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'action', v_action,
      'converted', v_converted,
      'switched', v_switched,
      'reverted', false,
      'booking_id', v_booking_id,
      'contract_week_id', CASE WHEN v_contract_week_row.id IS NULL THEN NULL ELSE v_contract_week_row.id::text END,
      'old_timesheet_id', v_current_timesheet_id::text,
      'new_timesheet_id', v_new_timesheet_id::text,
      'current_timesheet_id', v_new_timesheet_id::text,
      'old_version', v_old_version,
      'new_version', v_new_version,
      'new_submission_mode', CASE
        WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'ELECTRONIC'
        ELSE 'MANUAL'
      END,
      'has_electronic_original', CASE WHEN v_action IN ('SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN true ELSE NULL END,
      'electronic_version', CASE WHEN v_action IN ('SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN v_old_version ELSE NULL END,
      'requested_timesheet_id', v_requested_timesheet_id::text,
      'was_stale', v_was_stale
    );
  ELSE
    IF ROW(
      v_current_row.contract_id, v_current_row.sheet_scope, v_current_row.line_type,
      v_current_row.occupant_key_norm, v_current_row.hospital_norm,
      v_current_row.ward_norm, v_current_row.job_title_norm, v_current_row.band,
      v_current_row.scheduled_start_iso, v_current_row.scheduled_end_iso,
      v_current_row.worked_start_iso, v_current_row.worked_end_iso,
      v_current_row.break_start_iso, v_current_row.break_end_iso,
      v_current_row.break_minutes, v_current_row.worked_minutes,
      v_current_row.week_ending_date, v_current_row.actual_schedule_json,
      v_current_row.additional_units_week, v_current_row.additional_units_per_day,
      v_current_row.day_references_json,
      v_current_row.reference_number, v_current_row.is_adjustment,
      v_current_row.parent_timesheet_id, v_current_row.correction_id,
      v_current_row.correction_kind, v_current_row.adjustment_origin
    ) IS DISTINCT FROM ROW(
      v_electronic_row.contract_id, v_electronic_row.sheet_scope,
      v_electronic_row.line_type, v_electronic_row.occupant_key_norm,
      v_electronic_row.hospital_norm, v_electronic_row.ward_norm,
      v_electronic_row.job_title_norm, v_electronic_row.band,
      v_electronic_row.scheduled_start_iso, v_electronic_row.scheduled_end_iso,
      v_electronic_row.worked_start_iso, v_electronic_row.worked_end_iso,
      v_electronic_row.break_start_iso, v_electronic_row.break_end_iso,
      v_electronic_row.break_minutes, v_electronic_row.worked_minutes,
      v_electronic_row.week_ending_date, v_electronic_row.actual_schedule_json,
      v_electronic_row.additional_units_week,
      v_electronic_row.additional_units_per_day,
      v_electronic_row.day_references_json,
      v_electronic_row.reference_number, v_electronic_row.is_adjustment,
      v_electronic_row.parent_timesheet_id, v_electronic_row.correction_id,
      v_electronic_row.correction_kind, v_electronic_row.adjustment_origin
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_CONTENT_MISMATCH: A changed route must create a new electronic approval generation';
    END IF;

    IF v_electronic_row.candidate_workflow_id IS NULL
       OR v_electronic_row.candidate_workflow_generation IS NULL
       OR nullif(btrim(coalesce(v_electronic_row.r2_nurse_key, '')), '') IS NULL
       OR nullif(btrim(coalesce(v_electronic_row.r2_auth_key, '')), '') IS NULL
       OR nullif(btrim(coalesce(v_electronic_row.img_sha256_nurse, '')), '') IS NULL
       OR nullif(btrim(coalesce(v_electronic_row.img_sha256_auth, '')), '') IS NULL THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_PROOF_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    SELECT workflow.* INTO v_revert_workflow
    FROM public.candidate_submission_workflows workflow
    WHERE workflow.id=v_electronic_row.candidate_workflow_id
    FOR UPDATE;
    IF NOT FOUND OR v_revert_workflow.state<>'FINALISED'
       OR v_revert_workflow.canonical_financial_sha256 IS NULL
       OR v_revert_workflow.candidate_signature_component_id IS NULL
       OR v_revert_workflow.manager_signature_component_id IS NULL THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_PROOF_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    SELECT request_row.* INTO v_revert_approval_request
    FROM public.candidate_approval_requests request_row
    WHERE request_row.workflow_id=v_revert_workflow.id
      AND request_row.workflow_generation=v_electronic_row.candidate_workflow_generation
      AND request_row.state IN ('APPROVED','SUPERSEDED')
      AND request_row.approved_at_utc IS NOT NULL
    ORDER BY request_row.approved_at_utc DESC,
      request_row.request_generation DESC,request_row.created_at_utc DESC
    LIMIT 1
    FOR UPDATE;
    IF NOT FOUND
       OR v_revert_approval_request.review_manifest_sha256 IS NULL
       OR v_revert_approval_request.review_manifest_sha256
            IS DISTINCT FROM v_revert_workflow.review_manifest_sha256
       OR cardinality(v_revert_approval_request.required_component_ids)=0
       OR jsonb_array_length(v_revert_approval_request.required_component_manifest_json)
            <> cardinality(v_revert_approval_request.required_component_ids)
       OR cardinality(v_revert_approval_request.required_component_ids)
            <> (SELECT count(DISTINCT expected_id)
                FROM unnest(v_revert_approval_request.required_component_ids) expected_id)
       OR EXISTS(
         SELECT 1
         FROM unnest(v_revert_approval_request.required_component_ids) expected_id
         WHERE NOT EXISTS(
           SELECT 1
           FROM jsonb_array_elements(
             v_revert_approval_request.required_component_manifest_json
           ) manifest_item
           WHERE manifest_item->>'component_id'=expected_id::text
         )
       )
       OR EXISTS(
         SELECT 1
         FROM jsonb_array_elements(
           v_revert_approval_request.required_component_manifest_json
         ) manifest_item
         WHERE NOT (manifest_item->>'component_id'=ANY(
           SELECT expected_id::text
           FROM unnest(v_revert_approval_request.required_component_ids) expected_id
         ))
       ) THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_APPROVED_MANIFEST_INCOMPLETE: A new electronic approval generation is required';
    END IF;
    v_revert_required_component_ids:=v_revert_approval_request.required_component_ids;

    SELECT component.* INTO v_revert_hours_component
    FROM public.candidate_submission_components component
    WHERE component.id=v_revert_approval_request.manager_review_timesheet_component_id
      AND component.id=ANY(v_revert_required_component_ids)
      AND component.workflow_id=v_revert_workflow.id
      AND component.workflow_generation=v_electronic_row.candidate_workflow_generation
      AND component.component_kind='HOURS_TIMESHEET'
      AND component.required=true
      AND component.state='IMMUTABLE'
      AND component.final_signed_render_state='READY'
      AND component.final_signed_storage_key IS NOT NULL
      AND component.final_signed_content_sha256 IS NOT NULL
      AND component.final_signed_render_input_sha256 IS NOT NULL
      AND component.review_render_input_sha256=component.final_signed_render_input_sha256
    ORDER BY component.review_ordinal,component.id
    LIMIT 1
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_DOCUMENT_LINEAGE_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    SELECT component.* INTO v_revert_candidate_signature
    FROM public.candidate_submission_components component
    WHERE component.id=v_revert_workflow.candidate_signature_component_id
      AND component.workflow_id=v_revert_workflow.id
      AND component.workflow_generation=v_electronic_row.candidate_workflow_generation
      AND component.component_kind='CANDIDATE_SIGNATURE'
      AND component.state='IMMUTABLE'
      AND component.immutable_at_utc IS NOT NULL
      AND component.source_content_sha256=v_revert_workflow.candidate_signature_sha256
      AND component.storage_key=v_electronic_row.r2_nurse_key
    FOR UPDATE;
    IF NOT FOUND OR lower(btrim(v_electronic_row.img_sha256_nurse))
         IS DISTINCT FROM encode(v_revert_candidate_signature.source_content_sha256,'hex') THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_SIGNATURE_LINEAGE_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    SELECT component.* INTO v_revert_manager_signature
    FROM public.candidate_submission_components component
    WHERE component.id=v_revert_workflow.manager_signature_component_id
      AND component.workflow_id=v_revert_workflow.id
      AND component.workflow_generation=v_electronic_row.candidate_workflow_generation
      AND component.component_kind='MANAGER_SIGNATURE'
      AND component.state='IMMUTABLE'
      AND component.immutable_at_utc IS NOT NULL
      AND component.approval_request_id=v_revert_approval_request.id
      AND component.source_content_sha256=v_revert_workflow.manager_signature_sha256
      AND component.storage_key=v_electronic_row.r2_auth_key
    FOR UPDATE;
    IF NOT FOUND OR lower(btrim(v_electronic_row.img_sha256_auth))
         IS DISTINCT FROM encode(v_revert_manager_signature.source_content_sha256,'hex') THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_SIGNATURE_LINEAGE_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    SELECT evidence.* INTO v_revert_evidence
    FROM public.timesheet_evidence evidence
    WHERE evidence.timesheet_id=v_electronic_row.timesheet_id
      AND upper(btrim(evidence.kind))='TIMESHEET'
      AND evidence.processing_state<>'SUPERSEDED'
      AND evidence.candidate_component_id=v_revert_hours_component.id
      AND evidence.storage_key=v_revert_hours_component.final_signed_storage_key
    LIMIT 1
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_DOCUMENT_LINEAGE_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    -- Re-prove the immutable page IDs frozen into the request that the manager
    -- actually approved.  A superseded/missing component cannot disappear
    -- from this proof, and a replacement component with the same role cannot
    -- stand in for the approved identity.
    IF EXISTS(
      SELECT 1
      FROM unnest(v_revert_required_component_ids) expected_id
      LEFT JOIN public.candidate_submission_components component
        ON component.id=expected_id
       AND component.workflow_id=v_revert_workflow.id
       AND component.workflow_generation=v_electronic_row.candidate_workflow_generation
      WHERE component.id IS NULL
        OR component.required IS DISTINCT FROM true
        OR component.review_ordinal IS NULL
        OR component.state<>'IMMUTABLE'
        OR component.final_signed_render_state<>'READY'
        OR component.final_signed_storage_key IS NULL
        OR component.final_signed_content_sha256 IS NULL
        OR component.final_signed_render_input_sha256 IS NULL
        OR component.review_render_input_sha256
             IS DISTINCT FROM component.final_signed_render_input_sha256
        OR NOT EXISTS(
          SELECT 1
          FROM public.timesheet_evidence evidence
          WHERE evidence.candidate_component_id=expected_id
            AND evidence.processing_state<>'SUPERSEDED'
            AND evidence.storage_key=component.final_signed_storage_key
            AND evidence.document_role=CASE component.component_kind
              WHEN 'HOURS_TIMESHEET' THEN 'SIGNED_TIMESHEET'
              WHEN 'EXPENSE_SUMMARY' THEN 'EXPENSE_MILEAGE_APPROVAL_SUMMARY'
              WHEN 'MILEAGE_FORM' THEN 'MILEAGE_CLAIM_FORM'
              WHEN 'EXPENSE_EVIDENCE' THEN 'SOURCE_EVIDENCE'
              ELSE component.document_role
            END
        )
    ) OR EXISTS(
      SELECT 1
      FROM public.candidate_submission_components component
      WHERE component.workflow_id=v_revert_workflow.id
        AND component.workflow_generation=v_electronic_row.candidate_workflow_generation
        AND component.required=true
        AND component.review_ordinal IS NOT NULL
        AND component.state='IMMUTABLE'
        AND NOT (component.id=ANY(v_revert_required_component_ids))
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_REQUIRED_FINAL_PAGE_PROOF_INCOMPLETE: A new electronic approval generation is required';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_FINANCIAL_PROOF_INCOMPLETE: A new electronic approval generation is required';
    END IF;
    v_current_financial_sha256:=private._candidate_financial_content_sha256_v1(v_tsfin_row.id);
    IF v_current_financial_sha256 IS DISTINCT FROM v_revert_workflow.canonical_financial_sha256 THEN
      RAISE EXCEPTION 'TIMESHEET_REVERT_FINANCIAL_CONTENT_MISMATCH: A new electronic approval generation is required';
    END IF;

    IF v_current_row.authorised_at_server IS NOT NULL
       OR v_tsfin_row.authorised_at_utc IS NOT NULL THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: Unauthorise before reverting route';
    END IF;

    UPDATE public.timesheets AS t_demote
    SET
      is_current = false,
      status = 'REVOKED'::public.timesheet_status_enum,
      revoked_at = v_now,
      revoked_reason = 'REVERTED_TO_EXACT_ELECTRONIC_VERSION',
      revoked_by = p_actor_user_id::text,
      updated_at = v_now
    WHERE t_demote.booking_id = v_booking_id
      AND t_demote.is_current = true;

    UPDATE public.timesheets AS t_promote
    SET
      is_current = true,
      status = 'RECEIVED'::public.timesheet_status_enum,
      revoked_at = NULL,
      revoked_reason = NULL,
      revoked_by = NULL,
      qr_status = NULL,
      qr_token = NULL,
      qr_generated_at = NULL,
      qr_scanned_at = NULL,
      qr_scan_info_json = NULL,
      qr_r2_key = NULL,
      qr_payload_json = '{}'::jsonb,
      qr_last_sent_hash = NULL,
      qr_last_sent_at_utc = NULL,
      qr_signed_hash = NULL,
      qr_signed_at_utc = NULL,
      updated_at = v_now
    WHERE t_promote.timesheet_id = v_electronic_row.timesheet_id;

    IF v_contract_week_row.id IS NOT NULL THEN
      UPDATE public.contract_weeks AS cw_move
      SET
        timesheet_id = v_electronic_row.timesheet_id,
        submission_mode_snapshot = 'ELECTRONIC'::public.submission_mode_enum,
        updated_at = v_now
      WHERE cw_move.id = v_contract_week_row.id;
    END IF;

    IF v_tsfin_row.id IS NOT NULL THEN
      UPDATE public.timesheets_financials AS tf_move
      SET
        timesheet_id = v_electronic_row.timesheet_id,
        timesheet_version = coalesce(v_electronic_row.version, 1),
        authorised_by_user_id = NULL,
        authorised_at_utc = NULL,
        updated_at = v_now
      WHERE tf_move.id = v_tsfin_row.id;
    END IF;

    v_reverted := true;
    v_electronic_version := coalesce(v_electronic_row.version, 1);

    RETURN jsonb_build_object(
      'ok', true,
      'action', v_action,
      'converted', false,
      'switched', false,
      'reverted', v_reverted,
      'booking_id', v_booking_id,
      'contract_week_id', CASE WHEN v_contract_week_row.id IS NULL THEN NULL ELSE v_contract_week_row.id::text END,
      'previous_current_timesheet_id', v_current_timesheet_id::text,
      'old_timesheet_id', v_current_timesheet_id::text,
      'new_timesheet_id', v_electronic_row.timesheet_id::text,
      'current_timesheet_id', v_electronic_row.timesheet_id::text,
      'electronic_version', v_electronic_version,
      'new_submission_mode', 'ELECTRONIC',
      'requested_timesheet_id', v_requested_timesheet_id::text,
      'was_stale', v_was_stale
    );
  END IF;
END;
$function$;

-- private._timesheet_route_version_legacy_v1(uuid,uuid,text,uuid,boolean)
CREATE OR REPLACE FUNCTION private._timesheet_route_version_legacy_v1(p_current_timesheet_id uuid, p_expected_timesheet_id uuid, p_target_action text, p_actor_user_id uuid, p_allow_manual_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text := upper(btrim(coalesce(p_target_action, '')));
  v_now timestamptz := now();

  v_requested_row public.timesheets%ROWTYPE;
  v_current_row public.timesheets%ROWTYPE;
  v_new_row public.timesheets%ROWTYPE;
  v_electronic_row public.timesheets%ROWTYPE;
  v_contract_week_row public.contract_weeks%ROWTYPE;
  v_tsfin_row public.timesheets_financials%ROWTYPE;

  v_booking_id text;
  v_requested_timesheet_id uuid;
  v_current_timesheet_id uuid;
  v_new_timesheet_id uuid;
  v_contract_week_id uuid;
  v_contract_id uuid;
  v_client_id uuid;

  v_next_version integer;
  v_old_version integer;
  v_new_version integer;
  v_electronic_version integer;

  v_scope text;
  v_submission_mode text;
  v_qr_status text;
  v_basis text;

  v_has_qr_token boolean := false;
  v_has_qr_generated boolean := false;
  v_has_qr_scanned boolean := false;
  v_is_manual_only boolean := false;
  v_hard_locked boolean := false;
  v_has_segment_invoice_lock boolean := false;
  v_supports_electronic boolean := false;
  v_was_stale boolean := false;

  v_summary_route_type text;
  v_summary_client_no_timesheet_required boolean := false;
  v_contract_is_nhsp boolean := false;
  v_contract_autoprocess_hr boolean := false;
  v_contract_no_timesheet_required boolean := false;
  v_manual_adjustment_editable boolean := false;
  v_is_import_authoritative boolean := false;

  v_reverted boolean := false;
  v_switched boolean := false;
  v_converted boolean := false;

  v_current_adjustment_origin text;
  v_current_parent_timesheet_id_text text;
  v_contract_week_is_adjustment boolean := false;
  v_contract_week_is_contract_week_only boolean := false;
BEGIN
  IF p_current_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'timesheet_id is required';
  END IF;

  IF p_expected_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'expected_timesheet_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_action NOT IN (
    'CONVERT_QR_TO_MANUAL',
    'ALLOW_ELECTRONIC_AGAIN',
    'ALLOW_QR_AGAIN',
    'SWITCH_TO_MANUAL',
    'SWITCH_DAILY_TO_MANUAL',
    'REVERT_TO_ELECTRONIC'
  ) THEN
    RAISE EXCEPTION 'Unsupported target action: %', p_target_action;
  END IF;

  SELECT t_req.*
  INTO v_requested_row
  FROM public.timesheets AS t_req
  WHERE t_req.timesheet_id = p_current_timesheet_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Timesheet not found';
  END IF;

  v_requested_timesheet_id := v_requested_row.timesheet_id;
  v_booking_id := v_requested_row.booking_id;

  IF v_booking_id IS NULL OR btrim(v_booking_id) = '' THEN
    RAISE EXCEPTION 'Timesheet booking_id is missing; cannot version';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(v_booking_id));

  PERFORM 1
  FROM public.timesheets AS t_lock
  WHERE t_lock.booking_id = v_booking_id
  FOR UPDATE;

  SELECT t_cur.*
  INTO v_current_row
  FROM public.timesheets AS t_cur
  WHERE t_cur.booking_id = v_booking_id
    AND t_cur.is_current = true
  ORDER BY t_cur.version DESC, t_cur.updated_at DESC, t_cur.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    IF coalesce(v_requested_row.is_current, false) = true THEN
      v_current_row := v_requested_row;
    ELSE
      RAISE EXCEPTION 'Timesheet not found';
    END IF;
  END IF;

  v_current_timesheet_id := v_current_row.timesheet_id;
  v_was_stale := (v_requested_timesheet_id IS DISTINCT FROM v_current_timesheet_id);

  IF v_current_timesheet_id IS DISTINCT FROM p_expected_timesheet_id THEN
    RAISE EXCEPTION 'TIMESHEET_MOVED'
      USING DETAIL = jsonb_build_object(
        'current_timesheet_id', v_current_timesheet_id::text
      )::text;
  END IF;

  v_old_version := coalesce(v_current_row.version, 1);
  v_scope := upper(coalesce(v_current_row.sheet_scope::text, ''));
  v_submission_mode := upper(coalesce(v_current_row.submission_mode::text, ''));
  v_qr_status := upper(coalesce(v_current_row.qr_status::text, ''));

  SELECT cw_cur.*
  INTO v_contract_week_row
  FROM public.contract_weeks AS cw_cur
  WHERE cw_cur.timesheet_id = v_current_timesheet_id
  ORDER BY cw_cur.updated_at DESC, cw_cur.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    v_contract_week_id := v_contract_week_row.id;
    PERFORM 1
    FROM public.contract_weeks AS cw_lock
    WHERE cw_lock.id = v_contract_week_id
    FOR UPDATE;
  ELSE
    v_contract_week_id := NULL;
  END IF;

  SELECT tf_cur.*
  INTO v_tsfin_row
  FROM public.timesheets_financials AS tf_cur
  WHERE tf_cur.timesheet_id = v_current_timesheet_id
    AND tf_cur.is_current = true
  ORDER BY tf_cur.updated_at DESC, tf_cur.created_at DESC
  LIMIT 1;

  IF v_tsfin_row.id IS NOT NULL THEN
    PERFORM 1
    FROM public.timesheets_financials AS tf_lock
    WHERE tf_lock.id = v_tsfin_row.id
    FOR UPDATE;
  END IF;

  v_contract_id := coalesce(v_contract_week_row.contract_id, v_current_row.contract_id);
  v_client_id := v_tsfin_row.client_id;

  IF v_action IN ('CONVERT_QR_TO_MANUAL', 'ALLOW_ELECTRONIC_AGAIN', 'SWITCH_TO_MANUAL') THEN
    BEGIN
      SELECT
        upper(coalesce(vts.route_type, '')),
        coalesce(vts.client_no_timesheet_required, false),
        coalesce(vts.contract_id, v_contract_id),
        coalesce(vts.contract_week_id, v_contract_week_id)
      INTO
        v_summary_route_type,
        v_summary_client_no_timesheet_required,
        v_contract_id,
        v_contract_week_id
      FROM public.v_timesheets_summary AS vts
      WHERE vts.timesheet_id = v_current_timesheet_id
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_summary_route_type := '';
      v_summary_client_no_timesheet_required := false;
    END;

    IF v_contract_week_id IS NOT NULL AND v_contract_week_row.id IS DISTINCT FROM v_contract_week_id THEN
      SELECT cw_reload.*
      INTO v_contract_week_row
      FROM public.contract_weeks AS cw_reload
      WHERE cw_reload.id = v_contract_week_id
      LIMIT 1;

      IF v_contract_week_row.id IS NOT NULL THEN
        PERFORM 1
        FROM public.contract_weeks AS cw_reload_lock
        WHERE cw_reload_lock.id = v_contract_week_row.id
        FOR UPDATE;
      END IF;
    END IF;

    v_current_adjustment_origin := upper(coalesce(v_current_row.adjustment_origin, ''));
    v_current_parent_timesheet_id_text := btrim(coalesce(v_current_row.parent_timesheet_id::text, ''));
    v_contract_week_is_adjustment := (
      coalesce(v_contract_week_row.is_adjustment, false)
      OR coalesce(v_contract_week_row.additional_seq, 0) > 0
    );
    v_contract_week_is_contract_week_only := (btrim(coalesce(v_contract_week_row.timesheet_id::text, '')) = '');

    IF v_summary_route_type = 'WEEKLY_NHSP_ADJUSTMENT' THEN
      IF (
        coalesce(v_current_row.is_adjustment, false) = true
        AND upper(coalesce(v_current_row.submission_mode::text, '')) = 'MANUAL'
        AND v_current_adjustment_origin NOT IN ('IMPORT_CORRECTION', 'IMPORT_CANCELLATION')
        AND (
          v_current_adjustment_origin = 'MANUAL_ADJUSTMENT'
          OR v_current_parent_timesheet_id_text <> ''
          OR v_contract_week_is_adjustment = true
        )
      ) THEN
        v_manual_adjustment_editable := true;
      ELSIF (
        v_contract_week_row.id IS NOT NULL
        AND v_contract_week_is_adjustment = true
        AND upper(coalesce(v_contract_week_row.submission_mode_snapshot::text, '')) = 'MANUAL'
        AND v_contract_week_is_contract_week_only = true
      ) THEN
        v_manual_adjustment_editable := true;
      ELSE
        v_manual_adjustment_editable := false;
      END IF;
    ELSE
      v_manual_adjustment_editable := false;
    END IF;

    IF v_manual_adjustment_editable = false THEN
      v_is_import_authoritative := (
        v_summary_route_type = 'WEEKLY_NHSP'
        OR v_summary_route_type = 'WEEKLY_NHSP_ADJUSTMENT'
        OR (v_summary_route_type = 'WEEKLY_HEALTHROSTER' AND v_summary_client_no_timesheet_required = true)
      );
    ELSE
      v_is_import_authoritative := false;
    END IF;

    IF v_is_import_authoritative = false AND v_contract_id IS NOT NULL THEN
      BEGIN
        SELECT
          coalesce(c.is_nhsp, false),
          coalesce(c.autoprocess_hr, false),
          coalesce(c.no_timesheet_required, false),
          coalesce(c.client_id, v_client_id)
        INTO
          v_contract_is_nhsp,
          v_contract_autoprocess_hr,
          v_contract_no_timesheet_required,
          v_client_id
        FROM public.contracts AS c
        WHERE c.id = v_contract_id
        LIMIT 1;
      EXCEPTION WHEN OTHERS THEN
        v_contract_is_nhsp := false;
        v_contract_autoprocess_hr := false;
        v_contract_no_timesheet_required := false;
      END;

      IF v_manual_adjustment_editable = false THEN
        v_is_import_authoritative := (
          v_contract_is_nhsp = true
          OR (v_contract_autoprocess_hr = true AND v_contract_no_timesheet_required = true)
        );
      END IF;
    END IF;
  END IF;

  IF v_action = 'CONVERT_QR_TO_MANUAL' THEN
    IF (
      v_current_row.authorised_at_server IS NOT NULL
      AND btrim(v_current_row.authorised_at_server::text) <> ''
      AND (v_current_row.revoked_at IS NULL OR btrim(v_current_row.revoked_at::text) = '')
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before converting QR to manual.';
    END IF;

    IF v_is_import_authoritative = true THEN
      RAISE EXCEPTION 'Import-authoritative timesheets (NHSP / HealthRoster weekly no-timesheets) cannot change submission route';
    END IF;

    IF v_scope <> '' AND v_scope NOT IN ('WEEKLY', 'DAILY') THEN
      RAISE EXCEPTION 'Unsupported sheet_scope for QR conversion';
    END IF;

    IF v_submission_mode <> 'MANUAL' THEN
      RAISE EXCEPTION 'Timesheet is not in MANUAL mode; QR conversion not applicable';
    END IF;

    IF v_qr_status = '' THEN
      RAISE EXCEPTION 'Timesheet does not have QR metadata; nothing to convert';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'No financial snapshot for timesheet';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
      OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                      );

    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot convert QR: timesheet already invoiced or paid';
    END IF;
  ELSIF v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN
    IF v_current_row.is_adjustment = true OR coalesce(v_contract_week_row.is_adjustment, false) = true THEN
      RAISE EXCEPTION 'Adjustment timesheets cannot be converted to electronic submission';
    END IF;

    IF v_is_import_authoritative = true THEN
      RAISE EXCEPTION 'Import-authoritative timesheets (NHSP / HealthRoster weekly no-timesheets) cannot use Allow electronic again';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
      OR coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
    );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot allow electronic again: timesheet is invoiced/locked or paid';
    END IF;

    v_has_qr_token := (btrim(coalesce(v_current_row.qr_token, '')) <> '');
    v_has_qr_generated := (v_current_row.qr_generated_at IS NOT NULL);
    v_has_qr_scanned := (v_current_row.qr_scanned_at IS NOT NULL);
    v_is_manual_only := (
      v_submission_mode = 'MANUAL'
      AND v_qr_status = ''
      AND v_has_qr_token = false
      AND v_has_qr_generated = false
      AND v_has_qr_scanned = false
    );

    IF v_is_manual_only = false THEN
      RAISE EXCEPTION 'Allow electronic again is only valid for manual-only timesheets';
    END IF;

    IF v_client_id IS NULL AND v_contract_id IS NOT NULL THEN
      BEGIN
        SELECT c_client.client_id
        INTO v_client_id
        FROM public.contracts AS c_client
        WHERE c_client.id = v_contract_id
        LIMIT 1;
      EXCEPTION WHEN OTHERS THEN
        v_client_id := NULL;
      END;
    END IF;

    IF v_client_id IS NULL THEN
      RAISE EXCEPTION 'Cannot resolve client_id for electronic eligibility check';
    END IF;

    BEGIN
      SELECT (upper(coalesce(cs.default_submission_mode::text, '')) = 'ELECTRONIC')
      INTO v_supports_electronic
      FROM public.client_settings AS cs
      WHERE cs.client_id = v_client_id
      ORDER BY cs.updated_at DESC NULLS LAST, cs.created_at DESC NULLS LAST
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_supports_electronic := false;
    END;

    IF coalesce(v_supports_electronic, false) = false THEN
      RAISE EXCEPTION 'Client does not support electronic submission';
    END IF;
  ELSIF v_action = 'ALLOW_QR_AGAIN' THEN
    IF v_current_row.is_adjustment = true THEN
      RAISE EXCEPTION 'Adjustment timesheets cannot be converted to QR submission';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
      OR coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
    );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot allow QR again: timesheet is invoiced/locked or paid';
    END IF;

    v_has_qr_token := (btrim(coalesce(v_current_row.qr_token, '')) <> '');
    v_has_qr_generated := (v_current_row.qr_generated_at IS NOT NULL);
    v_has_qr_scanned := (v_current_row.qr_scanned_at IS NOT NULL);
    v_is_manual_only := (
      v_submission_mode = 'MANUAL'
      AND v_qr_status = ''
      AND v_has_qr_token = false
      AND v_has_qr_generated = false
      AND v_has_qr_scanned = false
    );

    IF v_is_manual_only = false THEN
      RAISE EXCEPTION 'Allow QR again is only valid for manual-only timesheets';
    END IF;
  ELSIF v_action = 'SWITCH_TO_MANUAL' THEN
    IF (
      v_current_row.authorised_at_server IS NOT NULL
      AND btrim(v_current_row.authorised_at_server::text) <> ''
      AND (v_current_row.revoked_at IS NULL OR btrim(v_current_row.revoked_at::text) = '')
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before switching to manual.';
    END IF;

    IF v_scope <> 'WEEKLY' THEN
      RAISE EXCEPTION 'Only WEEKLY timesheets can be switched to manual';
    END IF;

    IF v_submission_mode <> 'ELECTRONIC' THEN
      RAISE EXCEPTION 'Timesheet is not an electronic weekly timesheet';
    END IF;

    IF v_contract_week_row.id IS NULL THEN
      RAISE EXCEPTION 'Timesheet not linked to a contract week';
    END IF;

    IF v_is_import_authoritative = true THEN
      RAISE EXCEPTION 'Import-authoritative timesheets (NHSP / HealthRoster weekly no-timesheets) cannot be converted to manual';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'No financial snapshot to switch';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
      OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                      );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot switch: timesheet already invoiced or paid';
    END IF;

    v_basis := upper(coalesce(v_tsfin_row.basis::text, ''));
    IF v_basis <> 'CONTRACT_WEEKLY' THEN
      RAISE EXCEPTION 'Only CONTRACT_WEEKLY timesheets can be switched to manual';
    END IF;
  ELSIF v_action = 'SWITCH_DAILY_TO_MANUAL' THEN
    IF (
      v_current_row.authorised_at_server IS NOT NULL
      AND btrim(v_current_row.authorised_at_server::text) <> ''
      AND (v_current_row.revoked_at IS NULL OR btrim(v_current_row.revoked_at::text) = '')
    ) THEN
      RAISE EXCEPTION 'TIMESHEET_AUTHORISED_EDIT_BLOCKED: This timesheet is authorised. Unauthorise it before switching to manual.';
    END IF;

    IF v_booking_id IS NULL
      OR btrim(v_booking_id) = ''
      OR btrim(v_booking_id) = '{}'
      OR lower(btrim(v_booking_id)) = 'null'
      OR lower(btrim(v_booking_id)) = 'undefined'
    THEN
      RAISE EXCEPTION 'Timesheet booking_id is invalid; cannot rotate versions. Please repair booking_id.';
    END IF;

    IF v_scope <> 'DAILY' THEN
      RAISE EXCEPTION 'Only DAILY timesheets can be switched to manual via this endpoint';
    END IF;

    IF v_submission_mode <> 'ELECTRONIC' THEN
      RAISE EXCEPTION 'Timesheet is not an electronic daily timesheet';
    END IF;

    IF v_tsfin_row.id IS NULL THEN
      RAISE EXCEPTION 'No financial snapshot to switch';
    END IF;

    v_hard_locked := (
      coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
      OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                      );
    IF v_hard_locked THEN
      RAISE EXCEPTION 'Cannot switch: timesheet already invoiced or paid';
    END IF;

    v_basis := upper(coalesce(v_tsfin_row.basis::text, ''));
    IF v_basis IN ('NHSP', 'NHSP_ADJUSTMENT', 'HEALTHROSTER_SELF_BILL', 'HEALTHROSTER_ADJUSTMENT') THEN
      RAISE EXCEPTION 'Cannot switch NHSP/HR-based daily timesheets to manual';
    END IF;
  ELSIF v_action = 'REVERT_TO_ELECTRONIC' THEN
    IF v_current_row.is_adjustment = true THEN
      RAISE EXCEPTION 'Adjustment timesheets cannot be reverted/converted to electronic submission';
    END IF;

    SELECT t_elec.*
    INTO v_electronic_row
    FROM public.timesheets AS t_elec
    WHERE t_elec.booking_id = v_booking_id
      AND upper(coalesce(t_elec.submission_mode::text, '')) = 'ELECTRONIC'
    ORDER BY t_elec.version DESC, t_elec.updated_at DESC, t_elec.created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'No electronic version exists for this timesheet';
    END IF;

    IF v_tsfin_row.id IS NOT NULL THEN
      v_has_segment_invoice_lock := EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE
            WHEN v_tsfin_row.invoice_breakdown_json IS NOT NULL
             AND jsonb_typeof(v_tsfin_row.invoice_breakdown_json) = 'object'
             AND jsonb_typeof(v_tsfin_row.invoice_breakdown_json -> 'segments') = 'array'
            THEN v_tsfin_row.invoice_breakdown_json -> 'segments'
            ELSE '[]'::jsonb
          END
        ) AS s(seg)
        WHERE nullif(btrim(coalesce(s.seg ->> 'invoice_locked_invoice_id', '')), '') IS NOT NULL
      );

      v_hard_locked := (
        coalesce(v_tsfin_row.paid_at_utc IS NOT NULL, false)
        OR coalesce(v_tsfin_row.locked_by_invoice_id IS NOT NULL, false)
                                OR v_has_segment_invoice_lock
      );

      IF v_hard_locked THEN
        RAISE EXCEPTION 'Cannot revert: current timesheet is invoiced or paid';
      END IF;
    END IF;

    v_has_qr_token := (btrim(coalesce(v_current_row.qr_token, '')) <> '');
    v_has_qr_generated := (v_current_row.qr_generated_at IS NOT NULL);
    v_has_qr_scanned := (v_current_row.qr_scanned_at IS NOT NULL);
    v_is_manual_only := (
      v_submission_mode = 'MANUAL'
      AND v_qr_status = ''
      AND v_has_qr_token = false
      AND v_has_qr_generated = false
      AND v_has_qr_scanned = false
    );

    IF v_is_manual_only = true AND coalesce(p_allow_manual_only, false) = false THEN
      RAISE EXCEPTION 'Cannot revert: current is manual-only (set allow_manual_only=true to override)';
    END IF;

    IF v_current_timesheet_id = v_electronic_row.timesheet_id AND coalesce(v_current_row.is_current, false) = true THEN
      RETURN jsonb_build_object(
        'ok', true,
        'action', v_action,
        'reverted', false,
        'reason', 'Electronic version is already current',
        'booking_id', v_booking_id,
        'current_timesheet_id', v_current_timesheet_id::text,
        'current_version', coalesce(v_electronic_row.version, 1),
        'requested_timesheet_id', v_requested_timesheet_id::text,
        'was_stale', v_was_stale
      );
    END IF;
  END IF;

  SELECT coalesce(max(t_ver.version), 0) + 1
  INTO v_next_version
  FROM public.timesheets AS t_ver
  WHERE t_ver.booking_id = v_booking_id;

  IF v_action <> 'REVERT_TO_ELECTRONIC' THEN
    UPDATE public.timesheets AS t_demote
    SET
      is_current = false,
      status = CASE
        WHEN v_action = 'REVERT_TO_ELECTRONIC' THEN t_demote.status
        ELSE 'REVOKED'::public.timesheet_status_enum
      END,
      revoked_reason = CASE
        WHEN v_action = 'CONVERT_QR_TO_MANUAL' THEN 'QR_CONVERTED_TO_MANUAL'
        WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'ALLOW_ELECTRONIC_AGAIN'
        WHEN v_action = 'ALLOW_QR_AGAIN' THEN 'ALLOW_QR_AGAIN'
        WHEN v_action IN ('SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN 'SWITCHED_TO_MANUAL'
        ELSE t_demote.revoked_reason
      END,
      revoked_by = CASE
        WHEN v_action IN ('CONVERT_QR_TO_MANUAL', 'ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN', 'SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL')
        THEN p_actor_user_id::text
        ELSE t_demote.revoked_by
      END,
      updated_at = v_now
    WHERE t_demote.booking_id = v_booking_id
      AND t_demote.is_current = true;

    v_new_row := v_current_row;
    v_new_row.timesheet_id := gen_random_uuid();
    v_new_row.booking_id := v_booking_id;
    v_new_row.version := v_next_version;
    v_new_row.is_current := true;
    v_new_row.created_at := v_now;
    v_new_row.updated_at := v_now;
    v_new_row.revoked_at := NULL;
    v_new_row.revoked_reason := NULL;
    v_new_row.revoked_by := NULL;
    v_new_row.authorised_at_server := NULL;
    IF v_action IN ('ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN', 'SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN
      v_new_row.r2_nurse_key := NULL;
      v_new_row.r2_auth_key := NULL;
    END IF;
    v_new_row.submission_mode := CASE
      WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'ELECTRONIC'::public.submission_mode_enum
      ELSE 'MANUAL'::public.submission_mode_enum
    END;
    v_new_row.manual_pdf_r2_key := NULL;
    v_new_row.qr_token := NULL;
    v_new_row.qr_status := CASE
      WHEN v_action = 'ALLOW_QR_AGAIN' THEN 'PENDING'::public.timesheet_qr_status_enum
      ELSE NULL
    END;
    v_new_row.qr_payload_json := '{}'::jsonb;
    v_new_row.qr_generated_at := NULL;
    v_new_row.qr_scanned_at := NULL;
    v_new_row.qr_scan_info_json := NULL;
    v_new_row.qr_r2_key := NULL;
    v_new_row.status := CASE
      WHEN v_action IN ('ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN') THEN 'RECEIVED'::public.timesheet_status_enum
      ELSE v_current_row.status
    END;

    IF v_action = 'ALLOW_QR_AGAIN' THEN
      v_new_row.qr_last_sent_hash := NULL;
      v_new_row.qr_last_sent_at_utc := NULL;
      v_new_row.qr_signed_hash := NULL;
      v_new_row.qr_signed_at_utc := NULL;
    END IF;

    INSERT INTO public.timesheets
    SELECT (v_new_row).*
    RETURNING * INTO v_new_row;

    v_new_timesheet_id := v_new_row.timesheet_id;
    v_new_version := v_new_row.version;

    IF v_new_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'Insert succeeded but no timesheet_id returned';
    END IF;

    IF v_action = 'SWITCH_TO_MANUAL' THEN
      IF v_contract_week_row.id IS NULL THEN
        RAISE EXCEPTION 'Timesheet not linked to a contract week';
      END IF;

      UPDATE public.contract_weeks AS cw_upd
      SET
        timesheet_id = v_new_timesheet_id,
        submission_mode_snapshot = 'MANUAL'::public.submission_mode_enum,
        updated_at = v_now
      WHERE cw_upd.id = v_contract_week_row.id;
    ELSIF v_action IN ('CONVERT_QR_TO_MANUAL', 'ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN') THEN
      IF v_contract_week_row.id IS NOT NULL THEN
        UPDATE public.contract_weeks AS cw_move
        SET
          timesheet_id = v_new_timesheet_id,
          updated_at = v_now
        WHERE cw_move.id = v_contract_week_row.id;
      END IF;
    END IF;

    IF v_action IN ('CONVERT_QR_TO_MANUAL', 'SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN
      IF v_tsfin_row.id IS NULL THEN
        RAISE EXCEPTION 'No financial snapshot to switch';
      END IF;

      UPDATE public.timesheets_financials AS tf_upd
      SET
        timesheet_id = v_new_timesheet_id,
        timesheet_version = coalesce(v_new_row.version, v_next_version),
        processing_status = CASE
          WHEN v_action = 'CONVERT_QR_TO_MANUAL' THEN 'AWAITING_MANUAL_SIGNATURE'::public.ts_fin_processing_status_enum
          ELSE tf_upd.processing_status
        END,
        authorised_by_user_id = NULL,
        authorised_at_utc = NULL,
        updated_at = v_now
      WHERE tf_upd.id = v_tsfin_row.id;
    ELSIF v_action IN ('ALLOW_ELECTRONIC_AGAIN', 'ALLOW_QR_AGAIN') THEN
      IF v_tsfin_row.id IS NOT NULL THEN
        UPDATE public.timesheets_financials AS tf_upd
        SET
          timesheet_id = v_new_timesheet_id,
          timesheet_version = coalesce(v_new_row.version, v_next_version),
          processing_status = CASE
            WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'UNASSIGNED'::public.ts_fin_processing_status_enum
            WHEN v_action = 'ALLOW_QR_AGAIN' THEN 'AWAITING_MANUAL_SIGNATURE'::public.ts_fin_processing_status_enum
            ELSE tf_upd.processing_status
          END,
          updated_at = v_now
        WHERE tf_upd.id = v_tsfin_row.id;
      END IF;
    END IF;

    IF v_action = 'CONVERT_QR_TO_MANUAL' THEN
      v_converted := true;
    ELSE
      v_switched := true;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'action', v_action,
      'converted', v_converted,
      'switched', v_switched,
      'reverted', false,
      'booking_id', v_booking_id,
      'contract_week_id', CASE WHEN v_contract_week_row.id IS NULL THEN NULL ELSE v_contract_week_row.id::text END,
      'old_timesheet_id', v_current_timesheet_id::text,
      'new_timesheet_id', v_new_timesheet_id::text,
      'current_timesheet_id', v_new_timesheet_id::text,
      'old_version', v_old_version,
      'new_version', v_new_version,
      'new_submission_mode', CASE
        WHEN v_action = 'ALLOW_ELECTRONIC_AGAIN' THEN 'ELECTRONIC'
        ELSE 'MANUAL'
      END,
      'has_electronic_original', CASE WHEN v_action IN ('SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN true ELSE NULL END,
      'electronic_version', CASE WHEN v_action IN ('SWITCH_TO_MANUAL', 'SWITCH_DAILY_TO_MANUAL') THEN v_old_version ELSE NULL END,
      'requested_timesheet_id', v_requested_timesheet_id::text,
      'was_stale', v_was_stale
    );
  ELSE
    UPDATE public.timesheets AS t_demote
    SET
      is_current = false,
      updated_at = v_now
    WHERE t_demote.booking_id = v_booking_id
      AND t_demote.is_current = true;

    UPDATE public.timesheets AS t_promote
    SET
      is_current = true,
      qr_status = NULL,
      qr_token = NULL,
      qr_generated_at = NULL,
      qr_scanned_at = NULL,
      qr_scan_info_json = NULL,
      qr_r2_key = NULL,
      qr_payload_json = '{}'::jsonb,
      qr_last_sent_hash = NULL,
      qr_last_sent_at_utc = NULL,
      qr_signed_hash = NULL,
      qr_signed_at_utc = NULL,
      updated_at = v_now
    WHERE t_promote.timesheet_id = v_electronic_row.timesheet_id;

    IF v_contract_week_row.id IS NOT NULL THEN
      UPDATE public.contract_weeks AS cw_move
      SET
        timesheet_id = v_electronic_row.timesheet_id,
        updated_at = v_now
      WHERE cw_move.id = v_contract_week_row.id;
    END IF;

    IF v_tsfin_row.id IS NOT NULL THEN
      UPDATE public.timesheets_financials AS tf_move
      SET
        timesheet_id = v_electronic_row.timesheet_id,
        timesheet_version = coalesce(v_electronic_row.version, 1),
        updated_at = v_now
      WHERE tf_move.id = v_tsfin_row.id;
    END IF;

    v_reverted := true;
    v_electronic_version := coalesce(v_electronic_row.version, 1);

    RETURN jsonb_build_object(
      'ok', true,
      'action', v_action,
      'converted', false,
      'switched', false,
      'reverted', v_reverted,
      'booking_id', v_booking_id,
      'contract_week_id', CASE WHEN v_contract_week_row.id IS NULL THEN NULL ELSE v_contract_week_row.id::text END,
      'previous_current_timesheet_id', v_current_timesheet_id::text,
      'old_timesheet_id', v_current_timesheet_id::text,
      'new_timesheet_id', v_electronic_row.timesheet_id::text,
      'current_timesheet_id', v_electronic_row.timesheet_id::text,
      'electronic_version', v_electronic_version,
      'new_submission_mode', 'ELECTRONIC',
      'requested_timesheet_id', v_requested_timesheet_id::text,
      'was_stale', v_was_stale
    );
  END IF;
END;
$function$;

-- private.pay_current_timesheet_entitlement_components_from_build_v1(uuid,text)
CREATE OR REPLACE FUNCTION private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id uuid, p_dependency_unit_key text DEFAULT NULL::text)
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, truth_ex_vat numeric, baseline_ex_vat numeric, truth_inc_vat numeric, baseline_inc_vat numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
SELECT fact.timesheet_id,
  fact.economic_key_type AS key_type,
  fact.economic_key_value AS key_value,
  round(sum(coalesce(fact.truth_ex_vat,0)),2) AS truth_ex_vat,
  round(sum(coalesce(fact.baseline_ex_vat,0)),2) AS baseline_ex_vat,
  round(sum(coalesce(fact.truth_inc_vat,0)),2) AS truth_inc_vat,
  round(sum(coalesce(fact.baseline_inc_vat,0)),2) AS baseline_inc_vat
FROM private.banking_pay_workbench_economic_build_facts AS fact
JOIN private.banking_pay_workbench_economic_builds AS build ON build.id=fact.build_id
WHERE fact.build_id=p_build_id
  AND fact.fact_family='ENTITLEMENT_COMPONENT'
  AND fact.timesheet_id IS NOT NULL
  AND fact.economic_key_type IS NOT NULL
  AND fact.economic_key_value IS NOT NULL
  AND (p_dependency_unit_key IS NULL OR fact.dependency_unit_key=p_dependency_unit_key)
  AND build.dependency_closure_sealed_at_utc IS NOT NULL
  AND build.dependency_edge_stream_complete
  AND build.edge_tag_stream_complete
GROUP BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value
ORDER BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value;

/* Retained installed formula reference; fact collection invokes the installed
   live helper before sealing. Authoritative reconciliation never executes it.
with
inp as (
  select coalesce(array_agg(scope_row.timesheet_id order by scope_row.stable_ordinal),array[]::uuid[]) as ts_ids
  from private.banking_pay_workbench_economic_build_scope as scope_row
  where scope_row.build_id=p_build_id
    and scope_row.closure_status='SEALED'
    and (p_dependency_unit_key is null or scope_row.dependency_unit_key=p_dependency_unit_key)
),
rotation_scope_rows as (
  select
    scope_rows.requested_timesheet_id,
    scope_rows.booking_id,
    scope_rows.canonical_timesheet_id,
    scope_rows.family_timesheet_id,
    scope_rows.family_is_current,
    scope_rows.family_version,
    scope_rows.requested_is_canonical
  from inp as input_scope
  join public._pay_timesheet_rotation_scope(input_scope.ts_ids) as scope_rows
    on true
),
rotation_scope_keyed as (
  select
    rotation_scope_rows.requested_timesheet_id,
    rotation_scope_rows.booking_id,
    rotation_scope_rows.canonical_timesheet_id,
    rotation_scope_rows.family_timesheet_id,
    rotation_scope_rows.family_is_current,
    rotation_scope_rows.family_version,
    rotation_scope_rows.requested_is_canonical,
    coalesce(rotation_scope_rows.booking_id, rotation_scope_rows.requested_timesheet_id::text) as scope_family_key
  from rotation_scope_rows
  where rotation_scope_rows.requested_timesheet_id is not null
),
projection_targets as (
  select
    rotation_scope_keyed.scope_family_key,
    coalesce(
      (
        array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
        filter (
          where coalesce(rotation_scope_keyed.requested_is_canonical, false) = true
            and rotation_scope_keyed.canonical_timesheet_id is not null
        )
      )[1],
      (
        array_agg(distinct rotation_scope_keyed.requested_timesheet_id order by rotation_scope_keyed.requested_timesheet_id)
        filter (where rotation_scope_keyed.requested_timesheet_id is not null)
      )[1],
      (
        array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
        filter (where rotation_scope_keyed.canonical_timesheet_id is not null)
      )[1]
    ) as projected_timesheet_id,
    (
      array_agg(distinct rotation_scope_keyed.canonical_timesheet_id order by rotation_scope_keyed.canonical_timesheet_id)
      filter (where rotation_scope_keyed.canonical_timesheet_id is not null)
    )[1] as canonical_timesheet_id
  from rotation_scope_keyed
  group by rotation_scope_keyed.scope_family_key
),
family_to_projection as (
  select distinct
    rotation_scope_keyed.family_timesheet_id,
    projection_targets.projected_timesheet_id,
    projection_targets.canonical_timesheet_id
  from rotation_scope_keyed
  join projection_targets
    on projection_targets.scope_family_key = rotation_scope_keyed.scope_family_key
  where rotation_scope_keyed.family_timesheet_id is not null
    and projection_targets.projected_timesheet_id is not null
),
canonical_projection as (
  select distinct
    family_to_projection.canonical_timesheet_id,
    family_to_projection.projected_timesheet_id
  from family_to_projection
  where family_to_projection.canonical_timesheet_id is not null
    and family_to_projection.projected_timesheet_id is not null
),
tf as (
  select
    canonical_projection.projected_timesheet_id as timesheet_id,
    canonical_projection.canonical_timesheet_id as canonical_timesheet_id,
    tfin.total_pay_ex_vat,
    tfin.invoice_breakdown_json,
    tfin.additional_units_json,
    tfin.expenses_pay_ex_vat,
    tfin.travel_pay_ex_vat,
    tfin.accommodation_pay_ex_vat,
    tfin.other_pay_ex_vat,
    tfin.mileage_pay_ex_vat,
    timesheet_rows.booking_id,
    upper(coalesce(timesheet_rows.sheet_scope::text,'')) as sheet_scope,
    timesheet_rows.reference_number,
    timesheet_rows.worked_start_iso as ts_worked_start_iso,
    timesheet_rows.worked_end_iso as ts_worked_end_iso,
    timesheet_rows.break_start_iso as ts_break_start_iso,
    timesheet_rows.break_end_iso as ts_break_end_iso,
    timesheet_rows.break_minutes as ts_break_minutes,
    timesheet_rows.actual_schedule_json as ts_actual_schedule_json,
    tfin.worked_start_iso as tf_worked_start_iso,
    tfin.worked_end_iso as tf_worked_end_iso,
    tfin.break_start_iso as tf_break_start_iso,
    tfin.break_end_iso as tf_break_end_iso,
    tfin.break_minutes as tf_break_minutes,
    tfin.actual_schedule_json as tf_actual_schedule_json
  from canonical_projection
  join public.timesheets_financials as tfin
    on tfin.is_current = true
   and tfin.timesheet_id = canonical_projection.canonical_timesheet_id
  join public.timesheets as timesheet_rows
    on timesheet_rows.timesheet_id = canonical_projection.canonical_timesheet_id
   and timesheet_rows.is_current = true
   and timesheet_rows.revoked_at is null
   and timesheet_rows.archived_at_utc is null
   and timesheet_rows.authorised_at_server is not null
),
truth_enriched as (
  select
    tf0.timesheet_id,
    tf0.canonical_timesheet_id,
    tf0.total_pay_ex_vat,
    tf0.invoice_breakdown_json,
    tf0.additional_units_json,
    tf0.expenses_pay_ex_vat,
    tf0.travel_pay_ex_vat,
    tf0.accommodation_pay_ex_vat,
    tf0.other_pay_ex_vat,
    tf0.mileage_pay_ex_vat,
    tf0.booking_id,
    tf0.sheet_scope,
    tf0.reference_number,
    coalesce(tf0.tf_worked_start_iso, tf0.ts_worked_start_iso) as effective_worked_start_iso,
    coalesce(tf0.tf_worked_end_iso, tf0.ts_worked_end_iso) as effective_worked_end_iso,
    coalesce(tf0.tf_break_start_iso, tf0.ts_break_start_iso) as effective_break_start_iso,
    coalesce(tf0.tf_break_end_iso, tf0.ts_break_end_iso) as effective_break_end_iso,
    coalesce(tf0.tf_break_minutes, tf0.ts_break_minutes) as effective_break_minutes,
    case
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'object' then tf0.tf_actual_schedule_json
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'array' then (
        select tf_sched_item.value
        from jsonb_array_elements(tf0.tf_actual_schedule_json) as tf_sched_item(value)
        where tf_sched_item.value is not null
          and jsonb_typeof(tf_sched_item.value) = 'object'
        limit 1
      )
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'object' then tf0.ts_actual_schedule_json
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'array' then (
        select ts_sched_item.value
        from jsonb_array_elements(tf0.ts_actual_schedule_json) as ts_sched_item(value)
        where ts_sched_item.value is not null
          and jsonb_typeof(ts_sched_item.value) = 'object'
        limit 1
      )
      else null::jsonb
    end as effective_daily_schedule_json
  from tf tf0
),
truth_segments as (
  select
    te.timesheet_id,
    te.canonical_timesheet_id,
    case
      when te.invoice_breakdown_json is not null
       and jsonb_typeof(te.invoice_breakdown_json) = 'object'
       and upper(coalesce(te.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
       and jsonb_typeof(te.invoice_breakdown_json->'segments') = 'array'
      then (
        select coalesce(
          jsonb_agg(seg.value),
          '[]'::jsonb
        )
        from jsonb_array_elements(te.invoice_breakdown_json->'segments') as seg(value)
        where seg.value is not null
          and jsonb_typeof(seg.value) = 'object'
      )
      when te.sheet_scope = 'DAILY'
      then jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false,
          'date', case
            when te.effective_worked_start_iso is not null then ((te.effective_worked_start_iso at time zone 'Europe/London')::date)::text
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'work_date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'ymd','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date_ymd','')), '')
            )
          end,
          'segment_key', ('ts:' || te.timesheet_id::text),
          'segment_stable_key', ('timesheet:' || coalesce(te.booking_id, te.timesheet_id::text)),
          'ref_num', nullif(btrim(coalesce(te.reference_number,'')), ''),
          'start_utc', case
            when te.effective_worked_start_iso is not null then te.effective_worked_start_iso::text
            else null
          end,
          'end_utc', case
            when te.effective_worked_end_iso is not null then te.effective_worked_end_iso::text
            else null
          end,
          'start', case
            when te.effective_worked_start_iso is not null then to_char((te.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'start','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_start','')), '')
            )
          end,
          'end', case
            when te.effective_worked_end_iso is not null then to_char((te.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'end','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_end','')), '')
            )
          end,
          'break_start', case
            when te.effective_break_start_iso is not null then to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '')
          end,
          'break_end', case
            when te.effective_break_end_iso is not null then to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '')
          end,
          'break_mins', coalesce(
            te.effective_break_minutes::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
            case
              when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                then greatest(
                  0::numeric,
                  round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                )
              else null::numeric
            end
          ),
          'breaks', case
            when jsonb_typeof(te.effective_daily_schedule_json->'breaks') = 'array' then te.effective_daily_schedule_json->'breaks'
            when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'end', to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    case
                      when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  )
                )
              )
            when nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '') is not null
             and nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '') is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), ''),
                  'end', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), ''),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                  )
                )
              )
            else '[]'::jsonb
          end
        )
      )
      else jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false
        )
      )
    end as segments_json
  from truth_enriched te
),
adjustment_truth_rows as (
  select distinct on (
    family_to_projection.projected_timesheet_id,
    adjustment_rows.id
  )
    family_to_projection.projected_timesheet_id as timesheet_id,
    adjustment_rows.id as adjustment_id,
    adjustment_rows.created_at as adjustment_created_at,
    round(coalesce(adjustment_rows.delta_pay_ex_vat, 0), 2) as delta_pay_ex_vat
  from family_to_projection
  join public.ts_pay_adjustments as adjustment_rows
    on adjustment_rows.timesheet_id = family_to_projection.family_timesheet_id
  where adjustment_rows.as_advance = false
    and adjustment_rows.timesheet_id is not null
    and adjustment_rows.id is not null
    and family_to_projection.projected_timesheet_id is not null
  order by
    family_to_projection.projected_timesheet_id,
    adjustment_rows.id,
    adjustment_rows.created_at nulls last,
    family_to_projection.family_timesheet_id
),
truth_snapshot_like as (
  select
    truth_segment_rows.timesheet_id,
    jsonb_build_object(
      'segments', truth_segment_rows.segments_json,
      'additional_units_json', coalesce(tf1.additional_units_json,'{}'::jsonb),
      'additional_pay_ex_vat', 0,
      'expenses', jsonb_build_object(
        'expenses_pay_ex_vat', round(coalesce(tf1.expenses_pay_ex_vat,0),2),
        'travel_pay_ex_vat', round(coalesce(tf1.travel_pay_ex_vat,0),2),
        'accommodation_pay_ex_vat', round(coalesce(tf1.accommodation_pay_ex_vat,0),2),
        'other_pay_ex_vat', round(coalesce(tf1.other_pay_ex_vat,0),2),
        'mileage_pay_ex_vat', round(coalesce(tf1.mileage_pay_ex_vat,0),2)
      ),
      'adjustments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', adjustment_truth_rows.adjustment_id::text,
            'delta_pay_ex_vat', adjustment_truth_rows.delta_pay_ex_vat
          )
          order by adjustment_truth_rows.adjustment_created_at nulls last, adjustment_truth_rows.adjustment_id
        )
        from adjustment_truth_rows
        where adjustment_truth_rows.timesheet_id = truth_segment_rows.timesheet_id
      ), '[]'::jsonb)
    ) as snap_json
  from truth_segments as truth_segment_rows
  join tf as tf1
    on tf1.timesheet_id = truth_segment_rows.timesheet_id
),
truth_components_raw as (
  select
    truth_snapshot_rows.timesheet_id,
    upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) as raw_key_type,
    nullif(btrim(coalesce(timesheet_component_rows.key_value, '')), '') as raw_key_value,
    timesheet_component_rows.amount_ex_vat,
    timesheet_component_rows.amount_inc_vat,
    case
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) in ('TS_DAY','TS_TOTAL')
        then 'SEGMENT_DELTA'
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) = 'ADJUSTMENT_CODE'
        then 'ADJUSTMENT_DELTA'
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) = 'EXPENSE_CODE'
       and upper(nullif(btrim(coalesce(timesheet_component_rows.key_value, '')), '')) = 'MILEAGE'
        then 'MILEAGE_DELTA'
      when upper(nullif(btrim(coalesce(timesheet_component_rows.key_type, '')), '')) in ('ADDITIONAL_CODE','EXPENSE_CODE')
        then 'EXPENSE_DELTA'
      else null::text
    end as resolver_item_type
  from truth_snapshot_like as truth_snapshot_rows
  join lateral public._pay_timesheet_components(truth_snapshot_rows.snap_json) as timesheet_component_rows
    on true
),
truth_components as (
  select
    truth_component_rows.timesheet_id,
    resolved_truth_keys.key_type,
    resolved_truth_keys.key_value,
    truth_component_rows.amount_ex_vat,
    truth_component_rows.amount_inc_vat
  from truth_components_raw as truth_component_rows
  join lateral public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => truth_component_rows.timesheet_id,
    p_live_source_json => jsonb_build_object(
      'timesheet_id', truth_component_rows.timesheet_id::text,
      'item_type', truth_component_rows.resolver_item_type,
      'component_key_type', truth_component_rows.raw_key_type,
      'component_key_value', truth_component_rows.raw_key_value,
      'work_date', case when truth_component_rows.raw_key_type = 'TS_DAY' then truth_component_rows.raw_key_value else null::text end
    ),
    p_item_type => truth_component_rows.resolver_item_type,
    p_key_type_hint => truth_component_rows.raw_key_type,
    p_key_value_hint => truth_component_rows.raw_key_value,
    p_work_date => case
      when truth_component_rows.raw_key_type = 'TS_DAY'
       and truth_component_rows.raw_key_value ~ '^\d{4}-\d{2}-\d{2}$'
        then truth_component_rows.raw_key_value::date
      else null::date
    end
  ) as resolved_truth_keys
    on true
  where resolved_truth_keys.key_resolution_failure_reason is null
),
active_settled_components as (
  select fact_row.timesheet_id,fact_row.economic_key_type as key_type,
         fact_row.economic_key_value as key_value,
         fact_row.amount_ex_vat,fact_row.amount_inc_vat
  from private.banking_pay_workbench_economic_build_facts as fact_row
  where fact_row.build_id=p_build_id
    and fact_row.fact_family='FROZEN_SETTLED_COMPONENT'
    and (p_dependency_unit_key is null or fact_row.dependency_unit_key=p_dependency_unit_key)
),
legacy_baseline_timesheets as (
  select null::uuid as source_timesheet_id,null::uuid as projected_timesheet_id where false
),
legacy_baseline_components_raw as (
  select fact_row.timesheet_id,
         fact_row.economic_key_type as raw_key_type,
         fact_row.economic_key_value as raw_key_value,
         fact_row.amount_ex_vat,fact_row.amount_inc_vat,
         case
           when fact_row.economic_key_type in ('TS_DAY','TS_TOTAL') then 'SEGMENT_DELTA'
           when fact_row.economic_key_type='ADJUSTMENT_CODE' then 'ADJUSTMENT_DELTA'
           when fact_row.economic_key_type='EXPENSE_CODE' and upper(fact_row.economic_key_value)='MILEAGE' then 'MILEAGE_DELTA'
           when fact_row.economic_key_type in ('ADDITIONAL_CODE','EXPENSE_CODE') then 'EXPENSE_DELTA'
           else null::text
         end as resolver_item_type
  from private.banking_pay_workbench_economic_build_facts as fact_row
  where fact_row.build_id=p_build_id
    and fact_row.fact_family='PAY_STATE_FALLBACK'
    and (p_dependency_unit_key is null or fact_row.dependency_unit_key=p_dependency_unit_key)
),
legacy_baseline_components as (
  select
    legacy_baseline_rows.timesheet_id,
    resolved_baseline_keys.key_type,
    resolved_baseline_keys.key_value,
    legacy_baseline_rows.amount_ex_vat,
    legacy_baseline_rows.amount_inc_vat
  from legacy_baseline_components_raw as legacy_baseline_rows
  join lateral public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => legacy_baseline_rows.timesheet_id,
    p_live_source_json => jsonb_build_object(
      'timesheet_id', legacy_baseline_rows.timesheet_id::text,
      'item_type', legacy_baseline_rows.resolver_item_type,
      'component_key_type', legacy_baseline_rows.raw_key_type,
      'component_key_value', legacy_baseline_rows.raw_key_value,
      'work_date', case when legacy_baseline_rows.raw_key_type = 'TS_DAY' then legacy_baseline_rows.raw_key_value else null::text end
    ),
    p_item_type => legacy_baseline_rows.resolver_item_type,
    p_key_type_hint => legacy_baseline_rows.raw_key_type,
    p_key_value_hint => legacy_baseline_rows.raw_key_value,
    p_work_date => case
      when legacy_baseline_rows.raw_key_type = 'TS_DAY'
       and legacy_baseline_rows.raw_key_value ~ '^\d{4}-\d{2}-\d{2}$'
        then legacy_baseline_rows.raw_key_value::date
      else null::date
    end
  ) as resolved_baseline_keys
    on true
  where resolved_baseline_keys.key_resolution_failure_reason is null
),
baseline_components as (
  select
    active_settled_components.timesheet_id,
    active_settled_components.key_type,
    active_settled_components.key_value,
    active_settled_components.amount_ex_vat,
    active_settled_components.amount_inc_vat
  from active_settled_components
  union all
  select
    legacy_baseline_components.timesheet_id,
    legacy_baseline_components.key_type,
    legacy_baseline_components.key_value,
    legacy_baseline_components.amount_ex_vat,
    legacy_baseline_components.amount_inc_vat
  from legacy_baseline_components
),
truth_grouped as (
  select
    truth_components.timesheet_id,
    upper(nullif(btrim(coalesce(truth_components.key_type, '')), '')) as key_type,
    nullif(btrim(coalesce(truth_components.key_value, '')), '') as key_value,
    round(sum(coalesce(truth_components.amount_ex_vat, 0)), 2) as truth_ex_vat,
    round(sum(coalesce(truth_components.amount_inc_vat, 0)), 2) as truth_inc_vat
  from truth_components
  where truth_components.timesheet_id is not null
    and truth_components.key_type is not null
    and btrim(truth_components.key_type) <> ''
    and truth_components.key_value is not null
    and btrim(truth_components.key_value) <> ''
    and truth_components.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    and not (truth_components.key_type = 'TS_DAY' and truth_components.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  group by
    truth_components.timesheet_id,
    upper(nullif(btrim(coalesce(truth_components.key_type, '')), '')),
    nullif(btrim(coalesce(truth_components.key_value, '')), '')
),
baseline_grouped as (
  select
    baseline_components.timesheet_id,
    upper(nullif(btrim(coalesce(baseline_components.key_type, '')), '')) as key_type,
    nullif(btrim(coalesce(baseline_components.key_value, '')), '') as key_value,
    round(sum(coalesce(baseline_components.amount_ex_vat, 0)), 2) as baseline_ex_vat,
    round(sum(coalesce(baseline_components.amount_inc_vat, 0)), 2) as baseline_inc_vat
  from baseline_components
  where baseline_components.timesheet_id is not null
    and baseline_components.key_type is not null
    and btrim(baseline_components.key_type) <> ''
    and baseline_components.key_value is not null
    and btrim(baseline_components.key_value) <> ''
    and baseline_components.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    and not (baseline_components.key_type = 'TS_DAY' and baseline_components.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  group by
    baseline_components.timesheet_id,
    upper(nullif(btrim(coalesce(baseline_components.key_type, '')), '')),
    nullif(btrim(coalesce(baseline_components.key_value, '')), '')
),
all_keys as (
  select
    truth_grouped.timesheet_id,
    truth_grouped.key_type,
    truth_grouped.key_value
  from truth_grouped

  union

  select
    baseline_grouped.timesheet_id,
    baseline_grouped.key_type,
    baseline_grouped.key_value
  from baseline_grouped
)
select
  all_keys.timesheet_id,
  all_keys.key_type,
  all_keys.key_value,
  round(coalesce(truth_grouped.truth_ex_vat, 0), 2) as truth_ex_vat,
  round(coalesce(baseline_grouped.baseline_ex_vat, 0), 2) as baseline_ex_vat,
  round(coalesce(truth_grouped.truth_inc_vat, 0), 2) as truth_inc_vat,
  round(coalesce(baseline_grouped.baseline_inc_vat, 0), 2) as baseline_inc_vat
from all_keys
left join truth_grouped
  on truth_grouped.timesheet_id = all_keys.timesheet_id
 and truth_grouped.key_type = all_keys.key_type
 and truth_grouped.key_value = all_keys.key_value
left join baseline_grouped
  on baseline_grouped.timesheet_id = all_keys.timesheet_id
 and baseline_grouped.key_type = all_keys.key_type
 and baseline_grouped.key_value = all_keys.key_value
where all_keys.timesheet_id is not null
  and all_keys.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
  and all_keys.key_value is not null
  and btrim(all_keys.key_value) <> ''
  and not (all_keys.key_type = 'TS_DAY' and all_keys.key_value !~ '^\d{4}-\d{2}-\d{2}$')
*/
$function$;

-- private.pay_payment_correction_sha256_v1(jsonb)
CREATE OR REPLACE FUNCTION private.pay_payment_correction_sha256_v1(p_value jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
 SET statement_timeout TO '1000ms'
AS $function$
    SELECT CASE
        WHEN p_value IS NULL THEN
            pg_catalog.current_setting('PAYMENT_CORRECTION_HASH_INPUT_REQUIRED')
        ELSE
            pg_catalog.encode(
                extensions.digest(
                    pg_catalog.convert_to(p_value::text, 'UTF8'),
                    'sha256'
                ),
                'hex'
            )
    END
$function$;

-- private.pay_payment_mutation_guard_v1(uuid,uuid,text)
CREATE OR REPLACE FUNCTION private.pay_payment_mutation_guard_v1(p_pay_batch_id uuid, p_correction_request_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT 'NEW_PAYMENT_ACTION'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
    v_mode text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_mode, '')));
    v_active_gate_request_id uuid;
    v_integrity_conflict_exists boolean := false;
    v_operation_continuity_exists boolean := false;
BEGIN
    IF p_pay_batch_id IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', NULL,
            'guard_acquired', false,
            'blocked', true,
            'code', 'PAYMENT_MUTATION_BATCH_REQUIRED',
            'message', 'A Banking Pay batch is required.'
        );
    END IF;

    IF v_mode NOT IN ('NEW_PAYMENT_ACTION', 'CORRECTION_APPLY', 'AUTHORITATIVE_EVENT') THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', NULL,
            'guard_acquired', false,
            'blocked', true,
            'code', 'PAYMENT_MUTATION_MODE_INVALID',
            'message', 'The Banking Pay mutation mode is invalid.'
        );
    END IF;

    IF v_mode = 'CORRECTION_APPLY' AND p_correction_request_id IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', NULL,
            'guard_acquired', false,
            'blocked', true,
            'code', 'PAYMENT_MUTATION_CORRECTION_REQUEST_REQUIRED',
            'message', 'The owning payment-correction request is required.'
        );
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'BANKING_PAY_BATCH_MUTATION:' || p_pay_batch_id::text,
            0
        )
    );

    IF NOT EXISTS (
        SELECT 1
        FROM public.pay_batches AS batch_row
        WHERE batch_row.id = p_pay_batch_id
    ) THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', NULL,
            'guard_acquired', true,
            'blocked', true,
            'code', 'PAYMENT_MUTATION_BATCH_REQUIRED',
            'message', 'The Banking Pay batch was not found.'
        );
    END IF;

    SELECT request_row.id
    INTO v_active_gate_request_id
    FROM public.pay_payment_correction_requests AS request_row
    WHERE request_row.pay_batch_id = p_pay_batch_id
      AND (
          request_row.status IN (
              'REQUESTED',
              'AWAITING_AUTHORISATION',
              'AUTHORISED',
              'EXPANDED',
              'PROCESSING'
          )
          OR EXISTS (
              SELECT 1
              FROM public.banking_pay_operations AS refresh_operation
              WHERE refresh_operation.operation_type = 'PAYMENT_CORRECTION'
                AND refresh_operation.pay_batch_id = request_row.pay_batch_id
                AND refresh_operation.input_json ->> 'correction_request_id' = request_row.id::text
                AND refresh_operation.phase = 'REFRESH_WORKBENCH'
                AND refresh_operation.status NOT IN ('COMPLETE', 'FAILED', 'CANCELLED')
          )
      )
    ORDER BY request_row.requested_at_utc DESC, request_row.id DESC
    LIMIT 1;

    SELECT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS transfer_event
        WHERE transfer_event.normalised_state = 'COMPLETED'
          AND transfer_event.movement_classification = 'AMBIGUOUS_REVIEW_REQUIRED'
          AND transfer_event.correction_disposition = 'BLOCKED'
          AND transfer_event.mapping_hints_json ->> 'business_code' = 'PAID_EVIDENCE_AFTER_RELEASE'
          AND (
              transfer_event.pay_batch_id = p_pay_batch_id
              OR EXISTS (
                  SELECT 1
                  FROM public.pay_batch_candidates AS guarded_candidate
                  WHERE guarded_candidate.pay_batch_id = p_pay_batch_id
                    AND guarded_candidate.candidate_id = transfer_event.candidate_id
              )
              OR EXISTS (
                  SELECT 1
                  FROM public.pay_batch_items AS released_item
                  JOIN public.pay_batch_candidates AS released_candidate
                    ON released_candidate.id = released_item.pay_batch_candidate_id
                  JOIN public.pay_batch_candidates AS guarded_candidate
                    ON guarded_candidate.candidate_id = released_candidate.candidate_id
                   AND guarded_candidate.pay_batch_id = p_pay_batch_id
                  WHERE released_item.pay_bank_transfer_id = transfer_event.pay_bank_transfer_id
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.pay_payment_correction_actions AS review_action
              WHERE review_action.metadata_json ->> 'business_code' = 'PAID_EVIDENCE_AFTER_RELEASE'
                AND review_action.metadata_json ->> 'review_status' = 'ACKNOWLEDGED'
                AND (
                    review_action.metadata_json ->> 'bank_event_id'
                ) = transfer_event.id::text
          )
    )
    INTO v_integrity_conflict_exists;

    IF v_mode = 'AUTHORITATIVE_EVENT' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', true,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', v_active_gate_request_id,
            'guard_acquired', true,
            'blocked', false,
            'code', 'PAYMENT_MUTATION_GUARD_AUTHORITATIVE_EVENT',
            'message', NULL
        );
    END IF;

    IF v_integrity_conflict_exists THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', v_active_gate_request_id,
            'guard_acquired', true,
            'blocked', true,
            'code', 'PAID_EVIDENCE_AFTER_RELEASE_REVIEW_REQUIRED',
            'message', 'Finance review is required before another payment action.'
        );
    END IF;

    IF v_mode = 'NEW_PAYMENT_ACTION' AND v_active_gate_request_id IS NOT NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', v_active_gate_request_id,
            'guard_acquired', true,
            'blocked', true,
            'code', 'PAYMENT_CHANGE_IN_PROGRESS',
            'message', 'A payment correction is already in progress.'
        );
    END IF;

    IF v_mode = 'CORRECTION_APPLY' THEN
        IF v_active_gate_request_id IS DISTINCT FROM p_correction_request_id THEN
            RETURN pg_catalog.jsonb_build_object(
                'ok', false,
                'mode', v_mode,
                'pay_batch_id', p_pay_batch_id,
                'correction_request_id', p_correction_request_id,
                'active_gate_request_id', v_active_gate_request_id,
                'guard_acquired', true,
                'blocked', true,
                'code', 'PAYMENT_CORRECTION_GATE_OWNER_MISMATCH',
                'message', 'The payment correction does not own the active batch gate.'
            );
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM public.banking_pay_operations AS operation_row
            WHERE operation_row.operation_type = 'PAYMENT_CORRECTION'
              AND operation_row.pay_batch_id = p_pay_batch_id
              AND operation_row.input_json ->> 'correction_request_id' = p_correction_request_id::text
              AND operation_row.status NOT IN ('FAILED', 'CANCELLED')
        )
        INTO v_operation_continuity_exists;

        IF NOT v_operation_continuity_exists THEN
            RETURN pg_catalog.jsonb_build_object(
                'ok', false,
                'mode', v_mode,
                'pay_batch_id', p_pay_batch_id,
                'correction_request_id', p_correction_request_id,
                'active_gate_request_id', v_active_gate_request_id,
                'guard_acquired', true,
                'blocked', true,
                'code', 'PAYMENT_CORRECTION_GATE_OWNER_MISMATCH',
                'message', 'Durable payment-correction operation continuity was not found.'
            );
        END IF;

        RETURN pg_catalog.jsonb_build_object(
            'ok', true,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', v_active_gate_request_id,
            'guard_acquired', true,
            'blocked', false,
            'code', 'PAYMENT_MUTATION_GUARD_CORRECTION_OWNED',
            'message', NULL
        );
    END IF;

    RETURN pg_catalog.jsonb_build_object(
        'ok', true,
        'mode', v_mode,
        'pay_batch_id', p_pay_batch_id,
        'correction_request_id', p_correction_request_id,
        'active_gate_request_id', v_active_gate_request_id,
        'guard_acquired', true,
        'blocked', false,
        'code', 'PAYMENT_MUTATION_GUARD_CLEAR',
        'message', NULL
    );
EXCEPTION
    WHEN lock_not_available OR query_canceled THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'mode', v_mode,
            'pay_batch_id', p_pay_batch_id,
            'correction_request_id', p_correction_request_id,
            'active_gate_request_id', v_active_gate_request_id,
            'guard_acquired', false,
            'blocked', true,
            'code', 'PAYMENT_MUTATION_LOCK_TIMEOUT',
            'message', 'The payment scope is busy. Try again.'
        );
END
$function$;

-- private.pay_pre_bank_cancel_apply_work_page_v1(uuid,uuid[],uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_pre_bank_cancel_apply_work_page_v1(p_correction_request_id uuid, p_work_item_ids uuid[], p_actor_user_id uuid DEFAULT NULL::uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_work record;
  v_result jsonb := '{}'::jsonb;
  v_results jsonb := '[]'::jsonb;
  v_error_message text;
  v_error_state text;
  v_count integer := 0;
  v_operation_id uuid := NULL::uuid;
  v_session_id uuid := NULL::uuid;
  v_preflight jsonb := pg_catalog.jsonb_build_object(
    'ok',true,'mode','PRE_FINANCIAL','candidate_results','[]'::jsonb
  );
  v_candidate_preflight jsonb := '{}'::jsonb;
  v_post_source_change_seq bigint := 0;
  v_post_dirty_generation bigint := 0;
  v_batch_id uuid := NULL::uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_fast_count integer := 0;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_set_page_enabled boolean := false;
  v_request_selection_json jsonb := '{}'::jsonb;
  v_correction_dirty_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_correction_request_id IS NULL
     OR p_work_item_ids IS NULL
     OR pg_catalog.cardinality(p_work_item_ids) < 1
     OR pg_catalog.cardinality(p_work_item_ids) > 100
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'PRE_BANK_CANCEL_APPLY_PAGE_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','PRE_BANK_CANCEL_APPLY_PAGE_ARGUMENT_INVALID'
      )::text;
  END IF;

  SELECT COALESCE(setting.banking_pay_pre_bank_cancel_set_page_v1_enabled,false)
  INTO v_set_page_enabled
  FROM public.settings_defaults AS setting
  ORDER BY setting.id
  LIMIT 1;

  SELECT operation_row.id,batch_row.source_workbench_session_id,
         request_row.pay_batch_id,COALESCE(request_row.selection_json,'{}'::jsonb)
  INTO v_operation_id,v_session_id,v_batch_id,v_request_selection_json
  FROM public.pay_payment_correction_requests AS request_row
  JOIN public.pay_batches AS batch_row ON batch_row.id=request_row.pay_batch_id
  JOIN public.banking_pay_operations AS operation_row
    ON operation_row.operation_type='PAYMENT_CORRECTION'
   AND operation_row.pay_batch_id=request_row.pay_batch_id
   AND operation_row.input_json->>'correction_request_id'=request_row.id::text
  WHERE request_row.id=p_correction_request_id
  ORDER BY operation_row.created_at_utc
  LIMIT 1;

  -- This page is the exact financial mutation owner.  Establish causality in
  -- the same transaction immediately before any cancellation DML so finance
  -- triggers can retain ordinary dirty evidence without electing a competing
  -- pre-boundary economic build.
  SELECT COALESCE(
    pg_catalog.array_agg(DISTINCT work_row.candidate_id ORDER BY work_row.candidate_id),
    ARRAY[]::uuid[]
  )
  INTO v_correction_dirty_candidate_ids
  FROM public.pay_payment_correction_work_items AS work_row
  WHERE work_row.correction_request_id=p_correction_request_id
    AND work_row.id=ANY(p_work_item_ids)
    AND work_row.candidate_id IS NOT NULL;

  IF v_operation_id IS NOT NULL
     AND v_batch_id IS NOT NULL
     AND pg_catalog.cardinality(v_correction_dirty_candidate_ids)>0 THEN
    PERFORM private.pay_workbench_correction_dirty_context_set_v1(
      p_correction_request_id:=p_correction_request_id,
      p_pay_batch_id:=v_batch_id,
      p_candidate_ids:=v_correction_dirty_candidate_ids,
      p_lifecycle_phase:='FINANCIAL_PAGE_START',
      p_policy_x_boundary:='POST_DRAFT_FROZEN_EVIDENCE',
      p_pre_request_authorities_json:=COALESCE(
        v_request_selection_json->'cancellation_reversion_pre_request_authorities_v2',
        v_request_selection_json->'draft_overlay_fast_pre_request_authorities',
        '{}'::jsonb
      ),
      p_operation_id:=v_operation_id,
      p_work_item_id:=NULL::uuid,
      p_options_json:=pg_catalog.jsonb_build_object(
        'owner','pay_pre_bank_cancel_apply_work_page_v1',
        'work_item_count',pg_catalog.cardinality(p_work_item_ids)
      )
    );
  END IF;

  IF v_set_page_enabled
     AND v_operation_id IS NOT NULL AND v_session_id IS NOT NULL THEN
    v_preflight := private.pay_workbench_cancel_reversion_admission_page_v1(
      p_correction_request_id,v_operation_id,v_session_id,p_work_item_ids,
      pg_catalog.jsonb_build_object('mode','PRE_FINANCIAL')
    );
  END IF;

  -- Elect the closed-world no-provider page.  Admission is based on the exact
  -- V3 post-Draft authority; this extra fence deliberately narrows the bulk
  -- path to candidate-complete local/no-bank scopes.  Any ambiguity remains on
  -- the established single-item owner below.
  DROP TABLE IF EXISTS pg_temp._bpay_pre_cancel_fast_work;
  CREATE TEMP TABLE pg_temp._bpay_pre_cancel_fast_work ON COMMIT DROP AS
  WITH requested AS (
    SELECT DISTINCT requested_id.work_id
    FROM pg_catalog.unnest(p_work_item_ids) AS requested_id(work_id)
    WHERE requested_id.work_id IS NOT NULL
      AND v_set_page_enabled
  ), preflight AS (
    SELECT
      (entry.value->>'work_item_id')::uuid AS work_item_id,
      (entry.value->>'candidate_id')::uuid AS candidate_id,
      entry.value AS proof
    FROM pg_catalog.jsonb_array_elements(
      COALESCE(v_preflight->'candidate_results','[]'::jsonb)
    ) AS entry(value)
    WHERE COALESCE((entry.value->>'admitted')::boolean,false)
      AND COALESCE(entry.value->>'work_item_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND COALESCE(entry.value->>'candidate_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ), exact_work AS (
    SELECT
      work_row.id AS work_item_id,
      work_row.candidate_id,
      work_row.pay_batch_candidate_id,
      work_row.pay_batch_id,
      work_row.selection_json,
      work_row.selection_hash,
      work_row.attempt_count,
      membership.pay_batch_item_ids,
      membership.active_item_count,
      membership.candidate_scope_hash,
      preflight.proof
    FROM requested
    JOIN public.pay_payment_correction_work_items AS work_row
      ON work_row.id=requested.work_id
     AND work_row.correction_request_id=p_correction_request_id
     AND work_row.pay_batch_id=v_batch_id
     AND work_row.work_kind='PRE_BANK_CANCEL'
     AND work_row.status='PROCESSING'
    JOIN public.pay_payment_correction_request_candidates AS membership
      ON membership.correction_request_id=p_correction_request_id
     AND membership.pay_batch_candidate_id=work_row.pay_batch_candidate_id
    JOIN preflight ON preflight.work_item_id=work_row.id
      AND preflight.candidate_id=work_row.candidate_id
    WHERE membership.active_item_count BETWEEN 1 AND 128
      AND pg_catalog.cardinality(membership.pay_batch_item_ids)=membership.active_item_count
      AND work_row.selection_hash IS NOT DISTINCT FROM membership.candidate_scope_hash
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(work_row.selection_json->>'scope_type','')))
            IN ('CANDIDATES','BATCH')
  ), item_proof AS (
    SELECT
      exact_work.work_item_id,
      pg_catalog.count(item_row.id)::integer AS resolved_item_count,
      pg_catalog.count(*) FILTER (WHERE COALESCE(item_row.is_voided,false))::integer AS voided_count,
      pg_catalog.count(*) FILTER (
        WHERE item_row.pay_batch_candidate_id IS DISTINCT FROM exact_work.pay_batch_candidate_id
      )::integer AS wrong_candidate_count,
      pg_catalog.count(*) FILTER (
        WHERE item_row.pay_bank_transfer_id IS NOT NULL
      )::integer AS provider_shape_count,
      pg_catalog.count(*) FILTER (
        WHERE pg_catalog.upper(COALESCE(item_row.item_type,'')) IN (
          'MANUAL_ADJUSTMENT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY'
        )
      )::integer AS manual_shape_count
    FROM exact_work
    CROSS JOIN LATERAL pg_catalog.unnest(exact_work.pay_batch_item_ids) AS member(item_id)
    LEFT JOIN public.pay_batch_items AS item_row ON item_row.id=member.item_id
    GROUP BY exact_work.work_item_id
  )
  SELECT exact_work.*
  FROM exact_work
  JOIN item_proof ON item_proof.work_item_id=exact_work.work_item_id
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id=exact_work.pay_batch_candidate_id
   AND batch_candidate.pay_batch_id=v_batch_id
   AND batch_candidate.candidate_id=exact_work.candidate_id
  WHERE item_proof.resolved_item_count=exact_work.active_item_count
    AND item_proof.voided_count=0
    AND item_proof.wrong_candidate_count=0
    AND item_proof.provider_shape_count=0
    AND item_proof.manual_shape_count=0
    AND batch_candidate.settled_at_utc IS NULL
    AND pg_catalog.upper(COALESCE(batch_candidate.settlement_status,''))<>'SETTLED'
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_batch_items AS outside_item
      WHERE outside_item.pay_batch_candidate_id=exact_work.pay_batch_candidate_id
        AND COALESCE(outside_item.is_voided,false)=false
        AND NOT (outside_item.id=ANY(exact_work.pay_batch_item_ids))
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_manual_adjustment_carry_forwards AS carry_forward
      WHERE carry_forward.source_pay_batch_item_id=ANY(exact_work.pay_batch_item_ids)
         OR carry_forward.target_pay_batch_item_id=ANY(exact_work.pay_batch_item_ids)
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS prior_correction
      WHERE prior_correction.pay_batch_item_id=ANY(exact_work.pay_batch_item_ids)
        AND prior_correction.status='APPLIED'
        AND prior_correction.correction_request_id IS DISTINCT FROM p_correction_request_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_advances AS payout_case
      JOIN public.pay_batch_items AS finance_item
        ON finance_item.finance_case_id=payout_case.id
      WHERE finance_item.id=ANY(exact_work.pay_batch_item_ids)
        AND (
          payout_case.payout_transfer_id IS NOT NULL
          OR pg_catalog.upper(COALESCE(payout_case.payout_status::text,''))='PAID'
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_bank_transfers AS transfer
      WHERE transfer.pay_batch_id=v_batch_id
        AND transfer.candidate_id=exact_work.candidate_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS transfer_event
      WHERE transfer_event.pay_batch_id=v_batch_id
        AND transfer_event.candidate_id=exact_work.candidate_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS transfer_scope
      WHERE transfer_scope.pay_batch_id=v_batch_id
        AND transfer_scope.candidate_id=exact_work.candidate_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.mail_outbox AS queued_mail
      WHERE pg_catalog.upper(COALESCE(queued_mail.status::text,''))='QUEUED'
        AND (
          queued_mail.context_id=v_batch_id
          OR queued_mail.recipient_id=exact_work.candidate_id
          OR queued_mail.reference ILIKE '%'||v_batch_id::text||'%'
        )
        AND pg_catalog.lower(pg_catalog.concat_ws('|',queued_mail.type,queued_mail.email_type,
          queued_mail.context_kind,queued_mail.reference,
          COALESCE(queued_mail.payment_scope_json::text,'{}')))
          LIKE ANY(ARRAY['%remittance%','%payout%','%pay_batch%','%finance_payout%'])
    );

  SELECT pg_catalog.count(*)::integer INTO v_fast_count
  FROM pg_temp._bpay_pre_cancel_fast_work;

  IF v_fast_count>0 THEN
    v_mutation_guard:=private.pay_payment_mutation_guard_v1(
      v_batch_id,p_correction_request_id,'CORRECTION_APPLY'
    );
    IF COALESCE((v_mutation_guard->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION '%',COALESCE(v_mutation_guard->>'code','PAYMENT_CORRECTION_GATE_OWNER_MISMATCH')
        USING ERRCODE='P0001',DETAIL=v_mutation_guard::text;
    END IF;

    -- Candidate serial authority is the only deliberate page loop.  Economic
    -- DML below is set-wise and candidates are locked in deterministic order.
    FOR v_work IN
      SELECT candidate_id
      FROM pg_temp._bpay_pre_cancel_fast_work
      ORDER BY candidate_id
    LOOP
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtext('PAY_WORKBENCH_CANDIDATE_SERIAL_V1'),
        pg_catalog.hashtext(v_work.candidate_id::text)
      );
    END LOOP;

    PERFORM 1 FROM public.pay_payment_correction_requests AS request_lock
      WHERE request_lock.id=p_correction_request_id FOR UPDATE;
    PERFORM 1 FROM public.pay_batches AS batch_lock
      WHERE batch_lock.id=v_batch_id
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(batch_lock.execution_commit_state,'NOT_SUBMITTED')))
              ='NOT_SUBMITTED'
        AND batch_lock.execution_commit_ref IS NULL
        AND batch_lock.execution_committed_at_utc IS NULL
      FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PRE_BANK_CANCEL_FAST_PAGE_EXECUTION_AUTHORITY_CHANGED'
        USING ERRCODE='P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp._bpay_pre_cancel_fast_items;
    CREATE TEMP TABLE pg_temp._bpay_pre_cancel_fast_items ON COMMIT DROP AS
    SELECT
      fast_work.work_item_id,fast_work.candidate_id,fast_work.proof,item_row.*
    FROM pg_temp._bpay_pre_cancel_fast_work AS fast_work
    CROSS JOIN LATERAL pg_catalog.unnest(fast_work.pay_batch_item_ids) AS member(item_id)
    JOIN public.pay_batch_items AS item_row ON item_row.id=member.item_id
    ORDER BY fast_work.candidate_id,item_row.id
    FOR UPDATE OF item_row;

    -- A local scheduled execution is only a durable wait.  The admission and
    -- batch locks above prove no provider boundary was crossed before retiring
    -- that wait for the whole page.
    UPDATE public.banking_pay_operations AS scheduled_local_operation
    SET status='CANCELLED',phase='COMPLETE',runner_state='CANCELLED',
        requires_user_action=false,
        result_json=COALESCE(scheduled_local_operation.result_json,'{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'code','SCHEDULED_LOCAL_EXECUTION_CANCELLED_BEFORE_APPLY',
            'correction_request_id',p_correction_request_id,
            'work_item_ids',(SELECT pg_catalog.jsonb_agg(work_item_id ORDER BY work_item_id)
              FROM pg_temp._bpay_pre_cancel_fast_work),
            'provider_submission_attempted',false,'submitted_to_bank',false),
        completed_at_utc=COALESCE(scheduled_local_operation.completed_at_utc,v_now),
        lease_owner=NULL,lease_expires_at_utc=NULL,locked_by=NULL,
        lock_expires_at_utc=NULL,run_after_utc=NULL,updated_at_utc=v_now,
        resume_reason='SCHEDULED_LOCAL_EXECUTION_CANCELLED_BEFORE_APPLY'
    WHERE scheduled_local_operation.pay_batch_id=v_batch_id
      AND scheduled_local_operation.operation_type='PAYMENT_EXECUTE'
      AND scheduled_local_operation.status IN ('QUEUED','RUNNING','PROCESSING','CLAIMED','IN_PROGRESS')
      AND scheduled_local_operation.phase='SCHEDULE_PAYMENT'
      AND scheduled_local_operation.resume_reason IN (
        'WAIT_FOR_SCHEDULED_NO_BANK_PAYMENT','WAIT_FOR_SCHEDULED_LOCAL_MANUAL_SETTLEMENT'
      );

    INSERT INTO public.pay_payment_correction_items(
      correction_request_id,pay_batch_id,pay_batch_candidate_id,candidate_id,
      pay_batch_item_id,pay_bank_transfer_id,timesheet_id,finance_case_id,
      finance_component_id,reservation_id,item_type,correction_item_kind,
      source_amount,amount_ex_vat,amount_vat,amount_inc_vat,
      economic_key_type,economic_key_value,before_snapshot_json,
      after_snapshot_json,status,created_at_utc,applied_at_utc
    )
    SELECT
      p_correction_request_id,v_batch_id,fast_item.pay_batch_candidate_id,
      fast_item.candidate_id,fast_item.id,fast_item.pay_bank_transfer_id,
      fast_item.timesheet_id,fast_item.finance_case_id,fast_item.finance_component_id,
      fast_item.reservation_id,fast_item.item_type,'PRE_BANK_CANCEL',
      economic_component.source_amount_ex_vat,fast_item.amount_ex_vat,
      fast_item.amount_vat,COALESCE(economic_component.source_amount_inc_vat,fast_item.amount_inc_vat),
      economic_component.key_type,economic_component.key_value,to_jsonb(fast_item),
      to_jsonb(fast_item)||pg_catalog.jsonb_build_object(
        'is_voided',true,'updated_at',v_now,'set_based_page',true,
        'work_item_id',fast_item.work_item_id),
      'APPLIED',v_now,v_now
    FROM pg_temp._bpay_pre_cancel_fast_items AS fast_item
    LEFT JOIN LATERAL (
      SELECT component.key_type,component.key_value,
             component.source_amount_ex_vat,component.source_amount_inc_vat
      FROM public._pay_batch_item_economic_components(
        NULL::uuid,ARRAY[fast_item.id]::uuid[]
      ) AS component
      LIMIT 1
    ) AS economic_component ON true
    ON CONFLICT (pay_batch_item_id,correction_item_kind)
      WHERE status='APPLIED' AND pay_batch_item_id IS NOT NULL DO NOTHING;

    UPDATE public.pay_batch_items AS item_to_void
    SET is_voided=true,updated_at=v_now
    FROM pg_temp._bpay_pre_cancel_fast_items AS fast_item
    WHERE item_to_void.id=fast_item.id AND COALESCE(item_to_void.is_voided,false)=false;

    DROP TABLE IF EXISTS pg_temp._bpay_pre_cancel_fast_reservations;
    CREATE TEMP TABLE pg_temp._bpay_pre_cancel_fast_reservations ON COMMIT DROP AS
    WITH candidate AS (
      SELECT DISTINCT reservation.id,reservation.finance_case_id,
        reservation.finance_component_id,reservation.pay_batch_item_id,
        reservation.reserved_amount,reservation.reserved_source_amount,
        fast_item.work_item_id,fast_item.candidate_id
      FROM public.pay_advance_reservations AS reservation
      JOIN pg_temp._bpay_pre_cancel_fast_items AS fast_item
        ON fast_item.reservation_id=reservation.id
        OR fast_item.id=reservation.pay_batch_item_id
      WHERE reservation.pay_batch_id=v_batch_id
        AND (
          pg_catalog.upper(pg_catalog.btrim(COALESCE(reservation.status,'')))='RESERVED'
          OR (pg_catalog.upper(pg_catalog.btrim(COALESCE(reservation.status,'')))='COMMITTED'
              AND reservation.settled_at_utc IS NULL)
        )
    ), released AS (
      UPDATE public.pay_advance_reservations AS reservation
      SET status='RELEASED',released_at_utc=COALESCE(reservation.released_at_utc,v_now),
          released_reason='PRE_BANK_CANCEL',updated_by_user_id=p_actor_user_id
      FROM candidate
      WHERE reservation.id=candidate.id
      RETURNING reservation.id
    )
    SELECT candidate.* FROM candidate JOIN released ON released.id=candidate.id;

    DROP TABLE IF EXISTS pg_temp._bpay_pre_cancel_fast_components;
    CREATE TEMP TABLE pg_temp._bpay_pre_cancel_fast_components ON COMMIT DROP AS
    SELECT component.id AS finance_component_id,component.finance_case_id,
      component.remaining_source_amount AS remaining_before,
      COALESCE(component.remaining_source_amount,0) AS remaining_after,
      pg_catalog.round(pg_catalog.sum(pg_catalog.abs(COALESCE(
        reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(item_row.id),
        item_row.frozen_source_amount,reservation.reserved_amount,
        item_row.amount_ex_vat,item_row.amount_inc_vat,0
      ))),2)::numeric AS restore_source_amount,
      (pg_catalog.array_agg(reservation.work_item_id ORDER BY reservation.work_item_id))[1] AS work_item_id
    FROM pg_temp._bpay_pre_cancel_fast_reservations AS reservation
    LEFT JOIN public.pay_batch_items AS item_row ON item_row.id=reservation.pay_batch_item_id
    JOIN public.pay_finance_case_components AS component
      ON component.id=COALESCE(reservation.finance_component_id,item_row.finance_component_id)
    GROUP BY component.id,component.finance_case_id,component.remaining_source_amount;

    UPDATE public.pay_finance_case_components AS component
    SET remaining_source_amount=fast_component.remaining_after,
        resolved_at_utc=CASE WHEN fast_component.remaining_after>0 THEN NULL ELSE component.resolved_at_utc END,
        closed_at_utc=NULL,updated_at_utc=v_now
    FROM pg_temp._bpay_pre_cancel_fast_components AS fast_component
    WHERE component.id=fast_component.finance_component_id;

    INSERT INTO public.pay_finance_case_events(
      finance_case_id,finance_component_id,event_type,event_at_utc,actor_user_id,
      pay_batch_id,reservation_id,before_json,after_json,reason,note
    )
    SELECT finance_case_id,finance_component_id,'COMPONENT_RESTORED',v_now,
      p_actor_user_id,v_batch_id,NULL::uuid,
      pg_catalog.jsonb_build_object('remaining_source_amount',remaining_before),
      pg_catalog.jsonb_build_object('remaining_source_amount',remaining_after,
        'restored_source_amount',restore_source_amount,'correction_kind','PRE_BANK_CANCEL',
        'work_item_id',work_item_id,'set_based_page',true),
      'PRE_BANK_CANCEL',
      'Set-based pre-bank cancellation released the reservation without changing live outstanding balance.'
    FROM pg_temp._bpay_pre_cancel_fast_components;

    INSERT INTO public.pay_finance_case_events(
      finance_case_id,finance_component_id,event_type,event_at_utc,actor_user_id,
      pay_batch_id,reservation_id,before_json,after_json,reason,note
    )
    SELECT finance_case_id,finance_component_id,'RESERVATION_RELEASED',v_now,
      p_actor_user_id,v_batch_id,id,
      pg_catalog.jsonb_build_object('reservation_status','RESERVED_OR_COMMITTED'),
      pg_catalog.jsonb_build_object('reservation_status','RELEASED',
        'released_reason','PRE_BANK_CANCEL','work_item_id',work_item_id,'set_based_page',true),
      'PRE_BANK_CANCEL','Set-based pre-bank cancellation released reservation.'
    FROM pg_temp._bpay_pre_cancel_fast_reservations
    WHERE finance_case_id IS NOT NULL;

    UPDATE public.pay_advances AS payout_case
    SET payout_status='PENDING',payout_pay_batch_id=NULL,payout_transfer_id=NULL,updated_at=v_now
    WHERE payout_case.id IN (
      SELECT DISTINCT fast_item.finance_case_id
      FROM pg_temp._bpay_pre_cancel_fast_items AS fast_item
      WHERE fast_item.finance_case_id IS NOT NULL
    )
      AND COALESCE(payout_case.payout_status::text,'')<>'PAID'
      AND payout_case.payout_pay_batch_id=v_batch_id;

    -- Recalculate every affected candidate once and the batch once.
    WITH affected AS (
      SELECT DISTINCT pay_batch_candidate_id
      FROM pg_temp._bpay_pre_cancel_fast_work
    ), sums AS (
      SELECT candidate.id,
        pg_catalog.count(item.id) FILTER (WHERE COALESCE(item.is_voided,false)=false)::integer AS active_count,
        pg_catalog.bool_or(COALESCE(item.is_voided,false)=false AND pg_catalog.upper(COALESCE(item.pay_channel,''))='PAYE') AS has_paye,
        pg_catalog.bool_or(COALESCE(item.is_voided,false)=false AND pg_catalog.upper(COALESCE(item.pay_channel,''))='UMBRELLA') AS has_umbrella,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false
          AND item.item_type NOT IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY','MANUAL_CREDIT_PAYOUT','LOAN_PAYOUT','DEBT_CREATED')
          THEN COALESCE(item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS earnings_ex,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false AND item.item_type<>'DEBT_CREATED'
          THEN COALESCE(item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS earnings_inc,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false
          AND COALESCE(item.paye_treatment,'NONE') IN ('GROSS_ADD','GROSS_DEDUCT') THEN COALESCE(item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS gross_adj,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false
          AND COALESCE(item.paye_treatment,'NONE') IN ('NET_ADD','NET_DEDUCT') THEN COALESCE(item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS net_adj,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false AND item.item_type='OVERPAYMENT_RECOVERY'
          THEN -COALESCE(item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS recovery,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false AND item.item_type='LOAN_REPAYMENT'
          THEN -COALESCE(item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS loan,
        pg_catalog.round(COALESCE(pg_catalog.sum(CASE WHEN COALESCE(item.is_voided,false)=false AND item.item_type='DEBT_CREATED'
          THEN COALESCE(item.amount_inc_vat,item.amount_ex_vat,0) ELSE 0 END),0),2)::numeric(12,2) AS debt
      FROM affected JOIN public.pay_batch_candidates AS candidate ON candidate.id=affected.pay_batch_candidate_id
      LEFT JOIN public.pay_batch_items AS item ON item.pay_batch_candidate_id=candidate.id
      GROUP BY candidate.id
    )
    UPDATE public.pay_batch_candidates AS candidate
    SET awaiting_net_amount=CASE WHEN sums.active_count=0 THEN false WHEN COALESCE(sums.has_paye,false)
          THEN NOT EXISTS (SELECT 1 FROM public.pay_batch_paye_net_inputs AS net_input WHERE net_input.pay_batch_candidate_id=candidate.id)
          ELSE false END,
        gross_preview=CASE WHEN sums.active_count=0 THEN 0 WHEN COALESCE(sums.has_paye,false)
          THEN pg_catalog.round(COALESCE(sums.earnings_ex,0)+COALESCE(sums.gross_adj,0),2)
          ELSE GREATEST(COALESCE(sums.earnings_inc,0),0) END,
        net_bank_amount=CASE WHEN sums.active_count=0 THEN 0 WHEN COALESCE(sums.has_paye,false)
          THEN CASE WHEN NOT EXISTS (SELECT 1 FROM public.pay_batch_paye_net_inputs AS net_input WHERE net_input.pay_batch_candidate_id=candidate.id)
            THEN NULL::numeric ELSE GREATEST(pg_catalog.round(COALESCE((SELECT net_amount FROM public.pay_batch_paye_net_inputs WHERE pay_batch_candidate_id=candidate.id),0)+COALESCE(sums.net_adj,0),2),0) END
          ELSE GREATEST(COALESCE(sums.earnings_inc,0),0) END,
        debt_created=COALESCE(sums.debt,0),overpayment_recovery_taken=COALESCE(sums.recovery,0),
        loan_repayment_taken=COALESCE(sums.loan,0),mismatch_settlement_choice=NULL,updated_at=v_now
    FROM sums WHERE candidate.id=sums.id AND candidate.pay_batch_id=v_batch_id;

    UPDATE public.pay_batches AS batch
    SET total_bank_out=COALESCE((SELECT pg_catalog.round(COALESCE(pg_catalog.sum(COALESCE(candidate.net_bank_amount,0)),0),2)
          FROM public.pay_batch_candidates AS candidate WHERE candidate.pay_batch_id=v_batch_id),0),
        total_debt_created=COALESCE((SELECT pg_catalog.round(COALESCE(pg_catalog.sum(COALESCE(candidate.debt_created,0)),0),2)
          FROM public.pay_batch_candidates AS candidate WHERE candidate.pay_batch_id=v_batch_id),0)
    WHERE batch.id=v_batch_id;

    INSERT INTO public.app_change_counters(entity_key,seq,updated_at)
    SELECT 'pay_candidate:'||fast_work.candidate_id::text,1,v_now
    FROM pg_temp._bpay_pre_cancel_fast_work AS fast_work
    ON CONFLICT (entity_key) DO UPDATE
      SET seq=public.app_change_counters.seq+1,updated_at=v_now;

    DROP TABLE IF EXISTS pg_temp._bpay_pre_cancel_fast_results;
    CREATE TEMP TABLE pg_temp._bpay_pre_cancel_fast_results ON COMMIT DROP AS
    WITH per_work AS (
      SELECT fast_work.work_item_id,fast_work.candidate_id,fast_work.proof,
        pg_catalog.count(DISTINCT fast_item.id)::integer AS selected_item_count,
        pg_catalog.count(DISTINCT reservation.id)::integer AS released_reservation_count,
        pg_catalog.count(DISTINCT component.finance_component_id)::integer AS restored_component_count,
        COALESCE(change_counter.seq,0) AS source_change_seq,
        COALESCE(change_counter.scope_change_generation,0) AS dirty_generation,
        pg_catalog.jsonb_build_object(
          'pay_batch_id',v_batch_id::text,'correction_request_id',p_correction_request_id::text,
          'work_item_id',fast_work.work_item_id::text,'change_kind','PRE_BANK_CANCEL',
          'changed_pay_batch_item_ids',pg_catalog.jsonb_agg(DISTINCT fast_item.id::text ORDER BY fast_item.id::text),
          'changed_pay_batch_candidate_ids',pg_catalog.jsonb_build_array(fast_work.pay_batch_candidate_id::text),
          'changed_candidate_ids',pg_catalog.jsonb_build_array(fast_work.candidate_id::text),
          'changed_finance_case_ids',COALESCE(pg_catalog.jsonb_agg(DISTINCT fast_item.finance_case_id::text ORDER BY fast_item.finance_case_id::text)
            FILTER (WHERE fast_item.finance_case_id IS NOT NULL),'[]'::jsonb),
          'changed_finance_component_ids',COALESCE(pg_catalog.jsonb_agg(DISTINCT fast_item.finance_component_id::text ORDER BY fast_item.finance_component_id::text)
            FILTER (WHERE fast_item.finance_component_id IS NOT NULL),'[]'::jsonb),
          'changed_reservation_ids',COALESCE(pg_catalog.jsonb_agg(DISTINCT fast_item.reservation_id::text ORDER BY fast_item.reservation_id::text)
            FILTER (WHERE fast_item.reservation_id IS NOT NULL),'[]'::jsonb),
          'set_based_page',true
        ) AS changed_scope_json
      FROM pg_temp._bpay_pre_cancel_fast_work AS fast_work
      JOIN pg_temp._bpay_pre_cancel_fast_items AS fast_item ON fast_item.work_item_id=fast_work.work_item_id
      LEFT JOIN pg_temp._bpay_pre_cancel_fast_reservations AS reservation ON reservation.work_item_id=fast_work.work_item_id
      LEFT JOIN pg_temp._bpay_pre_cancel_fast_components AS component ON component.work_item_id=fast_work.work_item_id
      LEFT JOIN public.app_change_counters AS change_counter
        ON change_counter.entity_key='pay_candidate:'||fast_work.candidate_id::text
      GROUP BY fast_work.work_item_id,fast_work.candidate_id,fast_work.pay_batch_candidate_id,
        fast_work.proof,change_counter.seq,change_counter.scope_change_generation
    ), result AS (
      SELECT per_work.*,
        pg_catalog.jsonb_build_object(
          'ok',true,'status','APPLIED','result_code','APPLIED','work_item_id',per_work.work_item_id,
          'candidate_id',per_work.candidate_id,'correction_request_id',p_correction_request_id,
          'pay_batch_id',v_batch_id,'correction_item_kind','PRE_BANK_CANCEL',
          'selected_item_count',per_work.selected_item_count,'expected_item_count',per_work.selected_item_count,
          'applied_item_count',per_work.selected_item_count,'voided_item_count',per_work.selected_item_count,
          'released_reservation_count',per_work.released_reservation_count,
          'released_reservations',per_work.released_reservation_count,
          'restored_component_count',per_work.restored_component_count,
          'restored_finance_components',per_work.restored_component_count,
          'changed_scope_json',per_work.changed_scope_json,'set_based_page',true,
          'refresh_result',pg_catalog.jsonb_build_object('status','PENDING_OPERATION_REFRESH','owner','pay_payment_correction_process_chunk'),
          'applied_at_utc',v_now
        ) AS base_result
      FROM per_work
    )
    SELECT result.*,
      result.base_result||pg_catalog.jsonb_build_object(
        'cancellation_reversion_preflight',result.proof,
        'cancellation_reversion_post_financial_authority',pg_catalog.jsonb_build_object(
          'contract_version','POST_FINANCIAL_CANCELLATION_AUTHORITY_V1',
          'source_change_seq',result.source_change_seq,'dirty_generation',result.dirty_generation,
          'authority_digest',pg_catalog.md5(
            COALESCE(result.proof->>'post_draft_authority_digest','')||'|'||result.work_item_id::text||'|'||
            result.source_change_seq::text||'|'||result.dirty_generation::text||'|'||
            pg_catalog.md5((result.base_result-'applied_at_utc'-'processed_at_utc')::text)||
            '|POST_FINANCIAL_CANCELLATION_AUTHORITY_V1'
          )
        )
      ) AS final_result
    FROM result;

    UPDATE public.pay_payment_correction_work_items AS work_row
    SET status='APPLIED',locked_at_utc=NULL,locked_by=NULL,
        processed_at_utc=COALESCE(work_row.processed_at_utc,v_now),last_error=NULL,
        result_json=COALESCE(work_row.result_json,'{}'::jsonb)||fast_result.final_result
    FROM pg_temp._bpay_pre_cancel_fast_results AS fast_result
    WHERE work_row.id=fast_result.work_item_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'work_item_id',fast_result.work_item_id::text,
      'candidate_id',fast_result.candidate_id::text,'result',fast_result.final_result
    ) ORDER BY fast_result.candidate_id,fast_result.work_item_id),'[]'::jsonb)
    INTO v_results
    FROM pg_temp._bpay_pre_cancel_fast_results AS fast_result;

    v_count:=v_fast_count;
  END IF;

  FOR v_work IN
    SELECT work_row.id,work_row.candidate_id,work_row.attempt_count
    FROM public.pay_payment_correction_work_items AS work_row
    JOIN (
      SELECT DISTINCT work_id
      FROM pg_catalog.unnest(p_work_item_ids) AS requested(work_id)
      WHERE work_id IS NOT NULL
    ) AS requested_work ON requested_work.work_id=work_row.id
    WHERE work_row.correction_request_id=p_correction_request_id
      AND work_row.work_kind='PRE_BANK_CANCEL'
      AND NOT EXISTS (
        SELECT 1 FROM pg_temp._bpay_pre_cancel_fast_work AS fast_work
        WHERE fast_work.work_item_id=work_row.id
      )
    ORDER BY work_row.candidate_id,work_row.id
  LOOP
    BEGIN
      SELECT result_row.value
      INTO v_candidate_preflight
      FROM pg_catalog.jsonb_array_elements(
        COALESCE(v_preflight->'candidate_results','[]'::jsonb)
      ) AS result_row(value)
      WHERE result_row.value->>'candidate_id'=v_work.candidate_id::text
      LIMIT 1;

      v_result := public.pay_pre_bank_cancel_apply_work_item(v_work.id,p_actor_user_id);

      SELECT COALESCE(change_counter.seq,0),COALESCE(change_counter.scope_change_generation,0)
      INTO v_post_source_change_seq,v_post_dirty_generation
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key='pay_candidate:'||v_work.candidate_id::text;

      v_result := COALESCE(v_result,'{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'cancellation_reversion_preflight',COALESCE(v_candidate_preflight,'{}'::jsonb),
          'cancellation_reversion_post_financial_authority',
          pg_catalog.jsonb_build_object(
            'contract_version','POST_FINANCIAL_CANCELLATION_AUTHORITY_V1',
            'source_change_seq',v_post_source_change_seq,
            'dirty_generation',v_post_dirty_generation,
            'authority_digest',pg_catalog.md5(
              COALESCE(v_candidate_preflight->>'post_draft_authority_digest','')||'|'||
              v_work.id::text||'|'||v_post_source_change_seq::text||'|'||
              v_post_dirty_generation::text||'|'||
              pg_catalog.md5((COALESCE(v_result,'{}'::jsonb)
                - 'applied_at_utc' - 'processed_at_utc')::text)||
              '|POST_FINANCIAL_CANCELLATION_AUTHORITY_V1'
            )
          )
        );

      -- The compatibility owner persists its financial result, but the page
      -- owner adds the certified-reversion proof and mutation-boundary
      -- authority afterwards.  Persist that augmented authority so the later
      -- REFRESH_WORKBENCH transaction reads the same proof returned here.
      UPDATE public.pay_payment_correction_work_items AS applied_work
      SET result_json=COALESCE(applied_work.result_json,'{}'::jsonb)||v_result
      WHERE applied_work.id=v_work.id
        AND applied_work.status='APPLIED';
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS
        v_error_message=MESSAGE_TEXT,
        v_error_state=RETURNED_SQLSTATE;

      UPDATE public.pay_payment_correction_work_items AS failed_work
      SET status=CASE WHEN failed_work.attempt_count>=5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
          locked_at_utc=NULL,locked_by=NULL,
          processed_at_utc=CASE WHEN failed_work.attempt_count>=5
            THEN pg_catalog.clock_timestamp() ELSE NULL END,
          last_error=v_error_message,
          result_json=COALESCE(failed_work.result_json,'{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'code',CASE WHEN failed_work.attempt_count>=5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
              'sqlstate',v_error_state,'message',v_error_message
            )
      WHERE failed_work.id=v_work.id;

      v_result := pg_catalog.jsonb_build_object(
        'ok',false,
        'status',CASE WHEN v_work.attempt_count>=5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
        'code',CASE WHEN v_work.attempt_count>=5 THEN 'FAILED_FINAL' ELSE 'FAILED_RETRYABLE' END,
        'sqlstate',v_error_state,
        'message',v_error_message
      );
    END;

    v_results := v_results || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'work_item_id',v_work.id::text,
        'candidate_id',CASE WHEN v_work.candidate_id IS NULL THEN NULL ELSE v_work.candidate_id::text END,
        'result',v_result
      )
    );
    v_count := v_count+1;
  END LOOP;

  -- Once financial DML has committed its candidate results, the same causal
  -- dirty job must wait for the operation's REFRESH_WORKBENCH route election.
  -- It remains durable and recoverable, but cannot independently elect a full
  -- build during FINALISE.
  UPDATE public.banking_pay_workbench_jobs AS held_job
  SET status='QUEUED',started_at_utc=NULL,
      run_at_utc=GREATEST(COALESCE(held_job.run_at_utc,v_now),v_now+interval '30 seconds'),
      updated_at_utc=v_now,
      payload_json=public._pay_workbench_dirty_payload_merge(
        COALESCE(held_job.payload_json,'{}'::jsonb),
        pg_catalog.jsonb_build_object(
          'waiting_for_correction_financial_boundary',false,
          'waiting_for_correction_route_election',true,
          'correction_request_id',p_correction_request_id,
          'correction_operation_id',v_operation_id,
          'route_election_parked_at_utc',v_now,
          'classifier_work_skipped_by_request_boundary',true,
          'source_build_enqueue_skipped_by_request_boundary',true,
          'rerun_required',true,'has_more',true
        )
      )
  FROM public.banking_pay_operations AS correction_operation,
       public.pay_payment_correction_work_items AS applied_work
  WHERE correction_operation.id=v_operation_id
    AND EXISTS (
      SELECT 1
      FROM public.settings_defaults AS setting_row
      WHERE setting_row.id=1
        AND COALESCE((pg_catalog.to_jsonb(setting_row)
          ->>'banking_pay_correction_held_dirty_route_absorption_v1_enabled')::boolean,false)
    )
    AND applied_work.correction_request_id=p_correction_request_id
    AND applied_work.id=ANY(p_work_item_ids)
    AND applied_work.status='APPLIED'
    AND applied_work.candidate_id=held_job.candidate_id
    AND held_job.id=CASE
      WHEN COALESCE(correction_operation.input_json->'cancellation_reversion_start_authorities_v2'
        ->applied_work.candidate_id::text->>'request_owned_dirty_job_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (correction_operation.input_json->'cancellation_reversion_start_authorities_v2'
          ->applied_work.candidate_id::text->>'request_owned_dirty_job_id')::uuid
      WHEN COALESCE(correction_operation.input_json->'draft_overlay_fast_start_authorities'
        ->applied_work.candidate_id::text->>'request_owned_dirty_job_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (correction_operation.input_json->'draft_overlay_fast_start_authorities'
          ->applied_work.candidate_id::text->>'request_owned_dirty_job_id')::uuid
      ELSE NULL::uuid END
    AND held_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
    AND held_job.status IN ('QUEUED','RUNNING');

  IF v_count IS DISTINCT FROM (
    SELECT pg_catalog.count(DISTINCT requested.work_id)::integer
    FROM pg_catalog.unnest(p_work_item_ids) AS requested(work_id)
    WHERE requested.work_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'PRE_BANK_CANCEL_APPLY_PAGE_MEMBERSHIP_MISMATCH'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','PRE_BANK_CANCEL_APPLY_PAGE_MEMBERSHIP_MISMATCH',
        'requested_count',pg_catalog.cardinality(p_work_item_ids),
        'resolved_count',v_count
      )::text;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'contract_version','PRE_BANK_CANCEL_APPLY_PAGE_V1',
    'correction_request_id',p_correction_request_id::text,
    'work_item_count',v_count,
    'set_based_work_item_count',v_fast_count,
    'compatibility_work_item_count',v_count-v_fast_count,
    'candidate_results',v_results
  );
END;
$function$;

-- private.pay_sync_overpayments_from_workbench_workspace_v1(uuid,uuid,uuid,uuid,date,date,uuid,text,uuid[],jsonb,uuid,uuid[],uuid[])
CREATE OR REPLACE FUNCTION private.pay_sync_overpayments_from_workbench_workspace_v1(p_build_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_nonce uuid, p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb DEFAULT '{}'::jsonb, p_client_filter_single uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
declare
  v_bounded_build private.banking_pay_workbench_economic_builds%rowtype;
  v_bounded_job public.banking_pay_workbench_jobs%rowtype;
  v_bounded_attempt private.banking_pay_workbench_stage_attempts%rowtype;
  v_bounded_registry private.banking_pay_workbench_candidate_scope_registry%rowtype;
  v_bounded_scope_ids uuid[] := array[]::uuid[];
  v_bounded_scope_count integer := 0;
  v_bounded_fact_count bigint := 0;
  v_bounded_pre_sync_digest text;
  v_bounded_post_sync_digest text;
  v_bounded_canonical_digest text;
  v_bounded_economic_component_digest text;
  v_bounded_presentation_allocation_digest text;
  v_bounded_canonical_count integer := 0;
  v_bounded_canonical_stage_timestamp timestamptz;
  v_bounded_canonical_result jsonb := '{}'::jsonb;
  v_public_result_json jsonb := '{}'::jsonb;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_timesheet_case_count int := 0;
  v_cases_inserted int := 0;
  v_cases_touched int := 0;
  v_cases_amended int := 0;
  v_cases_reopened int := 0;
  v_cases_cleared int := 0;
  v_case_update_count int := 0;
  v_overpayment_case_count int := 0;
  v_underpayment_case_count int := 0;
  v_case_candidates_json jsonb := '[]'::jsonb;
  v_overpayment_json jsonb := '[]'::jsonb;
  v_underpayment_json jsonb := '[]'::jsonb;
  v_preview_decisions_json jsonb := '{}'::jsonb;
  v_preview_context_json jsonb := '{}'::jsonb;
  v_preview_baseline_json jsonb := '{}'::jsonb;
  v_preview_collect_result_json jsonb := '{}'::jsonb;
  v_preview_canonical_result_json jsonb := '{}'::jsonb;
  v_preview_candidate_row_json jsonb := '{}'::jsonb;
  v_preview_scope_context_json jsonb := '{}'::jsonb;
  v_preview_scope_candidate_ids_json jsonb := '[]'::jsonb;
  v_preview_candidate_loop_id uuid := NULL::uuid;
  v_preview_candidate_count integer := 0;
  v_requested_candidate_count integer := 0;
  v_missing_candidate_count integer := 0;
  v_missing_candidate_ids_json jsonb := '[]'::jsonb;
  v_authoritative_timesheet_scope_requested boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_explicit_empty_timesheet_scope boolean := false;
  v_preview_scope_strategy text := 'CANDIDATE_FULL_LIVE';
  v_sync_authority_token text := NULL::text;
  v_current_sync_authority_token text := NULL::text;
  v_workbench_session_id_text text := NULL::text;
  v_source_build_run_id_text text := NULL::text;
  v_session_version_text text := NULL::text;
  v_workbench_session_id uuid := NULL::uuid;
  v_source_build_run_id uuid := NULL::uuid;
  v_workbench_session_version bigint := NULL::bigint;
  v_authoritative_candidate_id uuid := NULL::uuid;
  v_existing_active_reserved_amount numeric(12,2) := 0;
  v_effective_case_amount_ex numeric(12,2);
  v_active_reservation_protection_applied boolean := false;
  v_correction_rewrite_result jsonb := '{}'::jsonb;
  v_resolution_pending_member_ids uuid[] := array[]::uuid[];
  v_resolution_pending_root_ids uuid[] := array[]::uuid[];

  v_target_case_row record;
  v_existing_case_row record;
  v_case_before_json jsonb;
  v_case_after_json jsonb;
  v_components_sync_result jsonb;
  v_component_case_outstanding_amount numeric(12,2) := 0;
  v_component_open_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_existing_recovered_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_target_amount_is_authoritative_outstanding boolean := false;
  v_selected_finance_case_id uuid;
  v_selected_event_type text;
  v_selected_reason text;
  v_selected_note text;
  v_open_case_candidate record;
  v_target_case_amount_ex numeric(12,2);
  v_case_taxability public.pay_finance_taxability_enum := NULL;
  v_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_case_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_before_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_before_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_case_metadata_component_count integer := 0;
  v_synced_open_component_count integer := 0;
  v_taxability_event_before_json jsonb;
  v_taxability_event_after_json jsonb;
  v_authoritative_negative_component_count integer := 0;
  v_authoritative_negative_component_digest text := NULL::text;
  v_expected_negative_component_digest text := NULL::text;
  v_authoritative_settled_baseline_digest text := NULL::text;
  v_expected_settled_baseline_digest text := NULL::text;
  v_authoritative_session_valid boolean := false;
  v_observed_effect_count integer := 0;
  v_observed_effect_digest text := md5('');
  v_effect_mismatch_detail jsonb := '{}'::jsonb;
  v_presentation_mismatch_detail jsonb := '{}'::jsonb;
  v_rate_authority_failure_code text := NULL::text;
  v_rate_authority_failure_detail jsonb := '[]'::jsonb;
  v_exception_detail text := NULL::text;
  v_exception_context text := NULL::text;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
  v_captured_effects jsonb := '[]'::jsonb;
  v_execution_profile_version integer := CASE
    WHEN COALESCE(current_setting('cloudtms.pay_workbench_execution_profile_version', true), '') ~ '^[12]$'
      THEN current_setting('cloudtms.pay_workbench_execution_profile_version', true)::integer
    ELSE 1
  END;
  v_reconciliation_optimization_version integer := 0;
  v_reconcile_started_at timestamptz := clock_timestamp();
  v_freshness_set_ms integer := 0;
  v_workspace_cache_ms integer := 0;
  v_authoritative_components_ms integer := 0;
  v_preflight_setup_ms integer := 0;
  v_correction_residuals_ms integer := 0;
  v_authority_validation_ms integer := 0;
  v_component_assembly_ms integer := 0;
  v_preview_workspace_ms integer := 0;
  v_preview_collect_ms integer := 0;
  v_preview_canonical_ms integer := 0;
  v_preview_summary_ms integer := 0;
  v_case_workspace_ms integer := 0;
  v_finance_apply_ms integer := 0;
  v_post_freshness_ms integer := 0;
  v_canonical_render_ms integer := 0;
  v_canonical_stage_ms integer := 0;
  v_phase_started_at timestamptz := clock_timestamp();
begin
  SELECT * INTO v_bounded_registry
  FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE current_build_id=p_build_id FOR UPDATE;
  SELECT * INTO v_bounded_build
  FROM private.banking_pay_workbench_economic_builds
  WHERE id=p_build_id FOR UPDATE;
  SELECT * INTO v_bounded_job
  FROM public.banking_pay_workbench_jobs
  WHERE id=p_job_id FOR UPDATE;
  SELECT * INTO v_bounded_attempt
  FROM private.banking_pay_workbench_stage_attempts
  WHERE id=p_attempt_id FOR UPDATE;

  IF v_bounded_build.id IS NULL OR v_bounded_job.id IS NULL OR v_bounded_attempt.id IS NULL
     OR v_bounded_registry.candidate_id IS DISTINCT FROM v_bounded_build.candidate_id
     OR v_bounded_registry.dirty_generation IS DISTINCT FROM v_bounded_build.captured_candidate_generation
     OR v_bounded_registry.current_source_change_seq IS DISTINCT FROM v_bounded_build.source_change_seq
     OR v_bounded_job.economic_build_id IS DISTINCT FROM p_build_id
     OR v_bounded_job.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_job.status IS DISTINCT FROM 'RUNNING'
     OR v_bounded_attempt.job_id IS DISTINCT FROM p_job_id
     OR v_bounded_attempt.build_id IS DISTINCT FROM p_build_id
     OR v_bounded_attempt.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_attempt.attempt_nonce IS DISTINCT FROM p_attempt_nonce
     OR v_bounded_attempt.attempt_status IS DISTINCT FROM 'STARTED'
     OR clock_timestamp()>=v_bounded_attempt.lease_expires_at_utc
     OR v_bounded_build.status IS DISTINCT FROM 'RECONCILING'
     OR v_bounded_build.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_build.dependency_closure_sealed_at_utc IS NULL
     OR NOT v_bounded_build.dependency_edge_stream_complete
     OR NOT v_bounded_build.edge_tag_stream_complete
     OR v_bounded_build.tagged_edge_count<>v_bounded_build.dependency_edge_count
     OR v_bounded_build.row_seal_count<>v_bounded_build.scope_count THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  IF COALESCE(NULLIF(v_bounded_build.attestation_json->>'execution_profile_version','')::integer,1)
       IS DISTINCT FROM v_execution_profile_version
     OR COALESCE(v_bounded_attempt.execution_profile_version,1)
       IS DISTINCT FROM v_execution_profile_version THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXECUTION_PROFILE_MISMATCH' USING ERRCODE='23514';
  END IF;
  BEGIN
    v_reconciliation_optimization_version:=COALESCE(
      NULLIF(v_bounded_build.attestation_json->>'reconciliation_optimization_version','')::integer,0
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_INVALID' USING ERRCODE='23514';
  END;
  IF v_reconciliation_optimization_version NOT IN (0,1)
     OR (v_execution_profile_version=1 AND v_reconciliation_optimization_version<>0) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_MISMATCH' USING ERRCODE='23514';
  END IF;
  PERFORM pg_catalog.set_config(
    'cloudtms.pay_workbench_reconciliation_optimization_version',
    v_reconciliation_optimization_version::text,
    true
  );
  IF v_reconciliation_optimization_version=1 THEN
    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp._bpay_wb_correction_residual_cache_v2(
      candidate_id uuid NOT NULL,session_key text NOT NULL,exclude_key text NOT NULL,result_json jsonb NOT NULL,
      PRIMARY KEY(candidate_id,session_key,exclude_key)
    ) ON COMMIT DROP;
    TRUNCATE TABLE pg_temp._bpay_wb_correction_residual_cache_v2;
  END IF;

  IF EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
    WHERE build_id=p_build_id AND closure_status<>'SEALED' LIMIT 1
  ) OR EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=p_build_id
      AND NOT scope_row.required_fact_families <@ scope_row.completed_fact_families
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACTS_INCOMPLETE' USING ERRCODE='23514';
  END IF;

  SELECT array_agg(timesheet_id ORDER BY stable_ordinal),count(*)::integer
  INTO v_bounded_scope_ids,v_bounded_scope_count
  FROM private.banking_pay_workbench_economic_build_scope
  WHERE build_id=p_build_id AND closure_status='SEALED';
  v_bounded_scope_ids:=COALESCE(v_bounded_scope_ids,array[]::uuid[]);

  -- Session-replacement correction decisions are registered before the
  -- target candidate has authoritative build evidence.  The legacy source
  -- builder consumed those registrations immediately before materialising
  -- correction residuals; the bounded workspace must preserve that same
  -- ordering.  Capture and execute each recompute from raw authority.  The
  -- capture subtransaction rolls this state back with its finance DML, while
  -- execute persists the identical carried decision before effect and
  -- canonical-output attestation.
  PERFORM public._pay_workbench_case_resolution_carry_process_candidate_v1(
    v_bounded_build.session_id,
    v_bounded_build.candidate_id,
    v_bounded_build.source_build_run_id,
    clock_timestamp()
  );

  CREATE TEMP TABLE pg_temp.tmp_sync_entitlement_components_v2(
    timesheet_id uuid NOT NULL,
    key_type text NOT NULL,
    key_value text NOT NULL,
    truth_ex_vat numeric,
    baseline_ex_vat numeric,
    truth_inc_vat numeric,
    baseline_inc_vat numeric,
    PRIMARY KEY(timesheet_id,key_type,key_value)
  ) ON COMMIT DROP;
  CREATE TEMP TABLE pg_temp.tmp_sync_settled_basis_by_timesheet_v2(
    timesheet_id uuid PRIMARY KEY,
    active_settled_component_count integer NOT NULL,
    active_settled_signature text NOT NULL
  ) ON COMMIT DROP;

  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp.tmp_sync_entitlement_components_v2(
      timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,truth_inc_vat,baseline_inc_vat)
    SELECT component.timesheet_id,UPPER(BTRIM(component.key_type)),BTRIM(component.key_value),
      component.truth_ex_vat,component.baseline_ex_vat,component.truth_inc_vat,component.baseline_inc_vat
    FROM private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id,NULL::text) component
    WHERE NULLIF(BTRIM(COALESCE(component.key_type,'')),'') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(component.key_value,'')),'') IS NOT NULL;

    INSERT INTO pg_temp.tmp_sync_settled_basis_by_timesheet_v2(
      timesheet_id,active_settled_component_count,active_settled_signature)
    SELECT scope_row.timesheet_id,
      COUNT(fact.natural_key)::integer,
      md5(COALESCE((jsonb_agg(jsonb_build_object(
        'key_type',fact.economic_key_type,
        'key_value',fact.economic_key_value,
        'amount_ex_vat',ROUND(COALESCE(fact.amount_ex_vat,0),2),
        'amount_inc_vat',ROUND(COALESCE(fact.amount_inc_vat,0),2)
      ) ORDER BY fact.economic_key_type,fact.economic_key_value)
        FILTER (WHERE fact.natural_key IS NOT NULL))::text,'[]'))
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN private.banking_pay_workbench_economic_build_facts fact
      ON fact.build_id=scope_row.build_id
     AND fact.timesheet_id=scope_row.timesheet_id
     AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
    WHERE scope_row.build_id=p_build_id
    GROUP BY scope_row.timesheet_id;
  END IF;
  v_workspace_cache_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer;

  IF to_regclass('pg_temp._bpay_wb_pre_sync_freshness_v1') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FRESHNESS_CONTEXT_CONFLICT'
      USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_wb_pre_sync_freshness_v1(
    timesheet_id uuid PRIMARY KEY,
    input_fingerprint text NULL,
    revision_json jsonb NULL,
    settled_authority_digest text NOT NULL
  ) ON COMMIT DROP;
  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp._bpay_wb_pre_sync_freshness_v1(
      timesheet_id,input_fingerprint,revision_json,settled_authority_digest)
    SELECT scope_row.timesheet_id,current_fingerprint.input_fingerprint,
      current_fingerprint.revision_json,
      md5(jsonb_build_object(
        'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
        'last_settled_signature',pay_state.last_settled_signature,
        'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
        'last_settled_at_utc',pay_state.last_settled_at_utc
      )::text)
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,v_bounded_scope_ids
    ) current_fingerprint ON current_fingerprint.timesheet_id=scope_row.timesheet_id
    LEFT JOIN public.timesheet_pay_state pay_state ON pay_state.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id;
  ELSE
    INSERT INTO pg_temp._bpay_wb_pre_sync_freshness_v1(
      timesheet_id,input_fingerprint,revision_json,settled_authority_digest)
    SELECT scope_row.timesheet_id,current_fingerprint.input_fingerprint,
      current_fingerprint.revision_json,
      md5(jsonb_build_object(
        'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
        'last_settled_signature',pay_state.last_settled_signature,
        'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
        'last_settled_at_utc',pay_state.last_settled_at_utc
      )::text)
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,ARRAY[scope_row.timesheet_id]
    ) current_fingerprint ON true
    LEFT JOIN public.timesheet_pay_state pay_state ON pay_state.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id;
  END IF;
  v_freshness_set_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer-v_workspace_cache_ms;
  v_phase_started_at := clock_timestamp();

  IF EXISTS(
    SELECT 1
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN pg_temp._bpay_wb_pre_sync_freshness_v1 pre_sync
      ON pre_sync.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND pre_sync.input_fingerprint IS DISTINCT FROM scope_row.captured_input_fingerprint
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  SELECT count(*)::bigint,
         md5(COALESCE(string_agg(fact_family||':'||natural_key||':'||financial_digest,''
           ORDER BY fact_family,natural_key),''))
  INTO v_bounded_fact_count,v_bounded_pre_sync_digest
  FROM private.banking_pay_workbench_economic_build_facts
  WHERE build_id=p_build_id AND fact_family NOT IN ('DEPENDENCY_EDGE','EXPECTED_FINANCE_EFFECT');

  IF to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_wb_expected_effects(
    build_token uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid NULL,
    relation_name text NOT NULL,
    operation text NOT NULL,
    source_id uuid NOT NULL,
    actual_source_id uuid NULL,
    finance_case_id uuid NULL,
    finance_component_id uuid NULL,
    economic_key_type text NULL,
    economic_key_value text NULL,
    proposed boolean NOT NULL DEFAULT false,
    expected_before_digest text NULL,
    expected_after_digest text NULL,
    observed boolean NOT NULL DEFAULT false,
    UNIQUE NULLS NOT DISTINCT(
      build_token,relation_name,operation,source_id,candidate_id,timesheet_id,
      expected_before_digest,expected_after_digest
    )
  ) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_effect_identity_map_v1(
    relation_name text NOT NULL,
    logical_source_id uuid NOT NULL,
    actual_source_id uuid NOT NULL,
    PRIMARY KEY(relation_name,logical_source_id),
    UNIQUE(relation_name,actual_source_id)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_effect_identity_map_v1;

  IF NOT v_effect_capture_mode THEN
    INSERT INTO pg_temp._bpay_wb_expected_effects(build_token,candidate_id,timesheet_id,
      relation_name,operation,source_id,finance_case_id,finance_component_id,
      economic_key_type,economic_key_value,expected_before_digest,expected_after_digest,proposed,observed)
    SELECT v_bounded_build.build_token,fact.candidate_id,fact.timesheet_id,fact.source_relation,
      fact.source_payload_json->>'operation',fact.source_id,fact.finance_case_id,
      fact.finance_component_id,fact.economic_key_type,fact.economic_key_value,
      NULLIF(fact.source_payload_json->>'expected_before_digest',''),
      NULLIF(fact.source_payload_json->>'expected_after_digest',''),false,false
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=p_build_id AND fact.fact_family='EXPECTED_FINANCE_EFFECT';
    IF COALESCE((v_bounded_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE
       OR NULLIF(v_bounded_build.attestation_json->>'effect_plan_digest','') IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_REQUIRED' USING ERRCODE='23514';
    END IF;
  END IF;

  p_candidate_ids:=ARRAY[v_bounded_build.candidate_id];
  p_force_include_timesheet_ids:=v_bounded_scope_ids;
  p_exclude_timesheet_ids:=ARRAY(
    SELECT excluded_id FROM unnest(COALESCE(p_exclude_timesheet_ids,array[]::uuid[])) excluded_id
    WHERE excluded_id=ANY(v_bounded_scope_ids) ORDER BY excluded_id
  );
  PERFORM set_config('cloudtms.pay_workbench_overpayment_sync_token',v_bounded_build.build_token::text,true);
  p_mismatch_choices:=(CASE WHEN jsonb_typeof(COALESCE(p_mismatch_choices,'{}'::jsonb))='object'
    THEN COALESCE(p_mismatch_choices,'{}'::jsonb) ELSE '{}'::jsonb END)
    - 'overpayment_sync_negative_component_digest'
    - 'overpayment_sync_settled_baseline_digest'
    ||jsonb_build_object(
      'overpayment_sync_authoritative_timesheet_scope',true,
      'overpayment_sync_authority_token',v_bounded_build.build_token::text,
      'workbench_session_id',v_bounded_build.session_id::text,
      'source_build_run_id',v_bounded_build.source_build_run_id::text,
      'source_change_seq',v_bounded_build.source_change_seq,
      'session_version',v_bounded_build.session_version,
      'overpayment_sync_scope_digest',v_bounded_build.scope_digest,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    );

  v_preflight_setup_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  declare
    v_correction_candidate uuid;
    v_residuals jsonb;
    v_candidate_pending_member_ids uuid[] := array[]::uuid[];
    v_candidate_pending_root_ids uuid[] := array[]::uuid[];
  begin
    foreach v_correction_candidate in array coalesce(p_candidate_ids,array[]::uuid[]) loop
      v_residuals:=public._ctms_candidate_correction_residuals_v1(
        NULL::uuid,
        v_correction_candidate,
        NULL::uuid,
        'PAY_SYNC_OVERPAYMENTS'
      );

      v_candidate_pending_member_ids := ARRAY(
        select distinct member_id.value::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        cross join lateral jsonb_array_elements_text(
          coalesce(residual.value->'member_timesheet_ids', '[]'::jsonb)
        ) member_id(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and member_id.value
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by member_id.value::uuid
      );

      v_candidate_pending_root_ids := ARRAY(
        select distinct (residual.value->>'root_timesheet_id')::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and coalesce(residual.value->>'root_timesheet_id', '')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by (residual.value->>'root_timesheet_id')::uuid
      );

      v_resolution_pending_member_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_member_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_member_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      v_resolution_pending_root_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_root_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_root_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      if exists(
        select 1
        from jsonb_array_elements(v_residuals) r
        where coalesce((r->>'draftable')::boolean,false) is not true
          and not (
            coalesce(r->>'block_code','')
              = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
            and coalesce((r->>'unresolved_count')::integer,0) > 0
            and coalesce((r->>'reservation_overrun_count')::integer,0) = 0
            and coalesce((r->>'component_count')::integer,0) > 0
          )
          and not (
            coalesce(r->>'block_code','') = 'CORRECTION_CHAIN_RESERVATION_OVERRUN'
            and coalesce((r->>'reservation_overrun_count')::integer,0) > 0
            and exists (
              select 1
              from private.banking_pay_workbench_economic_build_facts active_batch_item
              where active_batch_item.build_id=p_build_id
                and active_batch_item.fact_family='PROTECTION_EVIDENCE'
                and active_batch_item.source_relation='pay_batch_items'
                and active_batch_item.candidate_id=v_correction_candidate
                and active_batch_item.source_payload_json->>'protection_kind'
                  ='ACTIVE_CORRECTION_CHAIN_BATCH_ITEM'
                and coalesce(
                  active_batch_item.source_payload_json #>> '{frozen_component_snapshot_json,correction_root_id}',
                  active_batch_item.source_payload_json #>> '{frozen_resolution_payload_json,correction_root_id}',
                  '')=coalesce(r->>'root_timesheet_id','')
            )
          )
          and (
            coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
            or exists (
              select 1
              from jsonb_array_elements_text(
                coalesce(r->'member_timesheet_ids','[]'::jsonb)
              ) member_id(value)
              where member_id.value::uuid
                    = any(coalesce(p_force_include_timesheet_ids,array[]::uuid[]))
            )
          )
      ) then
        raise exception 'CORRECTION_RESIDUAL_NOT_READY_FOR_OVERPAYMENT_SYNC' using errcode='P0001',detail=v_residuals::text;
      end if;
    end loop;
  end;
  v_correction_residuals_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_START',
    jsonb_build_object(
      'pay_date', p_pay_date,
      'week_ending_cutoff', p_week_ending_cutoff,
      'pay_channel_scope', p_pay_channel_scope,
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'force_include_timesheet_count', COALESCE(array_length(p_force_include_timesheet_ids, 1), 0),
      'exclude_timesheet_count', COALESCE(array_length(p_exclude_timesheet_ids, 1), 0)
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_date is null then
    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    raise exception 'week_ending_cutoff is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE', 'UMBRELLA') then
    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  v_requested_candidate_count := COALESCE(array_length(p_candidate_ids, 1), 0);

  v_authoritative_timesheet_scope_requested := LOWER(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authoritative_timesheet_scope',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_sync_authority_token := NULLIF(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  IF COALESCE(v_authoritative_timesheet_scope_requested, false)
     AND (
       p_force_include_timesheet_ids IS NULL
       OR v_sync_authority_token IS NULL
       OR v_current_sync_authority_token IS NULL
       OR v_sync_authority_token IS DISTINCT FROM v_current_sync_authority_token
     ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID',
              'message', 'Authoritative Timesheet scope is internal Workbench authority and requires the matching transaction-local source-build token.',
              'force_include_argument_supplied', p_force_include_timesheet_ids IS NOT NULL,
              'authority_token_supplied', v_sync_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_authoritative_timesheet_scope := COALESCE(v_authoritative_timesheet_scope_requested, false)
    AND p_force_include_timesheet_ids IS NOT NULL
    AND v_sync_authority_token IS NOT NULL
    AND v_sync_authority_token = v_current_sync_authority_token;

  v_explicit_empty_timesheet_scope := COALESCE(v_authoritative_timesheet_scope, false)
    AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) = 0;

  v_preview_scope_strategy := CASE
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
     AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
      THEN 'AUTHORITATIVE_EMPTY'
    ELSE 'CANDIDATE_FULL_LIVE'
  END;

  v_preview_decisions_json := (
      CASE
        WHEN jsonb_typeof(COALESCE(p_mismatch_choices, '{}'::jsonb)) = 'object'
          THEN COALESCE(p_mismatch_choices, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
      - 'refresh_scope_kind'
      - 'targeted_timesheet_ids'
      - 'targeted_timesheet_ids_requested'
      - 'linked_timesheet_ids'
      - 'linked_timesheet_ids_requested'
      - 'source_build_allow_full_fallback'
      - 'overpayment_sync_authority_token'
      - 'overpayment_sync_authoritative_timesheet_scope'
      - 'authoritative_timesheet_scope'
      - 'exact_timesheet_scope'
      - 'workbench_session_id'
      - 'source_build_run_id'
      - 'source_change_seq'
      - 'session_version'
      - 'overpayment_sync_scope_digest'
      - 'overpayment_sync_negative_component_digest'
      - 'overpayment_sync_settled_baseline_digest'
      - 'policy_x_authority_scope'
    )
    || jsonb_build_object(
      'overpayment_sync_mode', true,
      'emit_raw_overpayment_components', true,
      'preview_context_mode', CASE WHEN v_requested_candidate_count = 1 THEN 'FULL_COMPAT' ELSE 'PAGE' END,
      'scope_limit', LEAST(GREATEST(COALESCE(v_requested_candidate_count, 1), 1), 100),
      'pay_channel_scope', v_scope,
      'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
      'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
      'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb),
      'overpayment_sync_preview_scope_strategy', v_preview_scope_strategy
    )
    || CASE
      WHEN v_preview_scope_strategy = 'TARGETED_TIMESHEETS' THEN
        jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'source_build_allow_full_fallback', false,
          'overpayment_sync_explicit_empty_scope', false
        )
      ELSE
        jsonb_build_object(
          'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
          'targeted_timesheet_ids', '[]'::jsonb,
          'targeted_timesheet_ids_requested', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'overpayment_sync_explicit_empty_scope', COALESCE(v_explicit_empty_timesheet_scope, false)
        )
    END
    || CASE
      WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
        jsonb_build_object(
          'workbench_source_build_mode', true,
          'source_build_mode', true,
          'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'overpayment_sync_authority_token', v_sync_authority_token
        )
      ELSE '{}'::jsonb
    END;


  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID',
              'message', 'candidate_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS included_timesheet(timesheet_id)
    WHERE included_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID',
              'message', 'force_include_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])) AS excluded_timesheet(timesheet_id)
    WHERE excluded_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID',
              'message', 'exclude_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF v_requested_candidate_count > 100 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE',
              'candidate_count', v_requested_candidate_count,
              'limit', 100,
              'message', 'Supply at most 100 explicit candidate IDs per bounded reconciliation call.'
            )::text;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    IF v_requested_candidate_count IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED',
                'candidate_count', v_requested_candidate_count
              )::text;
    END IF;

    v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), '');
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), '');
    v_session_version_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), '');

    IF v_workbench_session_id_text IS NULL
       OR v_workbench_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_session_version_text IS NULL
       OR v_session_version_text !~ '^[0-9]{1,18}$'
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), '') IS NULL
       OR UPPER(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH' THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID',
                'workbench_session_id', v_workbench_session_id_text,
                'source_build_run_id', v_source_build_run_id_text,
                'session_version', v_session_version_text,
                'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
              )::text;
    END IF;

    v_workbench_session_id := v_workbench_session_id_text::uuid;
    v_source_build_run_id := v_source_build_run_id_text::uuid;
    v_workbench_session_version := v_session_version_text::bigint;

    v_authoritative_candidate_id := p_candidate_ids[1];

    -- Supabase preloads plpgsql_check with fatal nested-statement inspection.
    -- Keep this predicate in its bounded owner-only SQL helper so the deeply
    -- nested PL/pgSQL frame does not corrupt pldbgapi2's parent stack.
    v_authoritative_session_valid :=
      public._pay_workbench_authoritative_scope_valid_v1(
      v_workbench_session_id,
      v_authoritative_candidate_id,
      v_workbench_session_version,
      p_actor_user_id,
      p_pay_date,
      p_week_ending_cutoff,
      v_scope
    );

    IF COALESCE(v_authoritative_session_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID',
                'workbench_session_id', v_workbench_session_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'session_version', v_workbench_session_version,
                'candidate_id', v_authoritative_candidate_id::text,
                'pay_channel_scope', v_scope
              )::text;
    END IF;

    IF EXISTS (
      WITH candidate_authority_seed_timesheets AS (
        SELECT authoritative_tsfin.timesheet_id
        FROM public.timesheets_financials AS authoritative_tsfin
        WHERE authoritative_tsfin.candidate_id = v_authoritative_candidate_id
          AND authoritative_tsfin.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_case.linked_timesheet_id
        FROM public.pay_advances AS authoritative_case
        WHERE authoritative_case.candidate_id = v_authoritative_candidate_id
          AND authoritative_case.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_component.linked_timesheet_id
        FROM public.pay_finance_case_components AS authoritative_component
        WHERE authoritative_component.candidate_id = v_authoritative_candidate_id
          AND authoritative_component.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_override.timesheet_id
        FROM public.timesheet_payment_overrides AS authoritative_override
        WHERE authoritative_override.candidate_id = v_authoritative_candidate_id
          AND authoritative_override.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_adjustment.timesheet_id
        FROM public.ts_pay_adjustments AS authoritative_adjustment
        WHERE authoritative_adjustment.candidate_id = v_authoritative_candidate_id
          AND authoritative_adjustment.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_snooze.timesheet_id
        FROM public.pay_item_snoozes AS authoritative_snooze
        WHERE authoritative_snooze.candidate_id = v_authoritative_candidate_id
          AND authoritative_snooze.timesheet_id IS NOT NULL
          AND authoritative_snooze.cleared_at_utc IS NULL
          AND authoritative_snooze.cancelled_at_utc IS NULL

        UNION

        SELECT authoritative_batch_item.timesheet_id
        FROM public.pay_batch_candidates AS authoritative_batch_candidate
        JOIN public.pay_batch_items AS authoritative_batch_item
          ON authoritative_batch_item.pay_batch_candidate_id = authoritative_batch_candidate.id
        WHERE authoritative_batch_candidate.candidate_id = v_authoritative_candidate_id
          AND authoritative_batch_item.timesheet_id IS NOT NULL
          AND COALESCE(authoritative_batch_item.is_voided, false) IS NOT TRUE

        UNION

        SELECT authoritative_correction.timesheet_id
        FROM public.pay_payment_correction_items AS authoritative_correction
        WHERE authoritative_correction.candidate_id = v_authoritative_candidate_id
          AND authoritative_correction.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(authoritative_correction.status, ''))) = 'APPLIED'
      ), candidate_authority_seed_array AS (
        SELECT COALESCE(
          ARRAY_AGG(
            DISTINCT candidate_authority_seed_timesheets.timesheet_id
            ORDER BY candidate_authority_seed_timesheets.timesheet_id
          ),
          ARRAY[]::uuid[]
        ) AS timesheet_ids
        FROM candidate_authority_seed_timesheets
      ), candidate_authority_timesheets AS (
        SELECT candidate_authority_seed_timesheets.timesheet_id
        FROM candidate_authority_seed_timesheets

        UNION

        SELECT authority_rotation.canonical_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.canonical_timesheet_id IS NOT NULL

        UNION

        SELECT authority_rotation.family_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.family_timesheet_id IS NOT NULL
      )
      SELECT 1
      FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS authoritative_timesheet(timesheet_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM candidate_authority_timesheets AS candidate_authority
        WHERE candidate_authority.timesheet_id = authoritative_timesheet.timesheet_id
      )
    ) THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb)
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_explicit_empty_timesheet_scope, false) THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
      jsonb_build_object(
        'pay_channel_scope', v_scope,
        'authoritative_timesheet_scope', true,
        'explicit_empty_timesheet_scope', true,
        'preview_scope_strategy', v_preview_scope_strategy,
        'candidate_count', v_requested_candidate_count,
        'cases_inserted', 0,
        'cases_touched', 0,
        'cases_amended', 0,
        'cases_reopened', 0,
        'cases_cleared', 0
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'pay_channel_scope', v_scope,
      'authoritative_timesheet_scope', true,
      'explicit_empty_timesheet_scope', true,
      'preview_scope_strategy', v_preview_scope_strategy,
      'scope_timesheet_ids', '[]'::jsonb,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', 0,
      'preview_candidate_coverage_complete', true,
      'negative_preview_timesheets_count', 0,
      'negative_preview_timesheets', '[]'::jsonb,
      'underpayment_case_count', 0,
      'underpayment_cases', '[]'::jsonb,
      'timesheet_finance_case_candidates_count', 0,
      'timesheet_finance_case_candidates', '[]'::jsonb,
      'cases_inserted', 0,
      'cases_touched', 0,
      'cases_amended', 0,
      'cases_reopened', 0,
      'cases_cleared', 0
    );
  END IF;

  create temporary table if not exists pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    linked_shift_date date null,
    corrected_amount_ex numeric(12,2) not null,
    baseline_signature text null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    needs_lifecycle_tracking boolean not null default false,
    overpayment_amount_ex numeric(12,2) not null,
    underpayment_amount_ex numeric(12,2) not null,
    desired_case_type public.pay_finance_case_type_enum null,
    desired_advance_kind public.pay_advance_kind_enum null,
    desired_reason public.pay_advance_reason_enum null,
    source_original_paid_amount numeric(12,2) null,
    source_corrected_paid_amount numeric(12,2) null,
    components_sync_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_links (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    finance_case_id uuid not null,
    desired_case_type public.pay_finance_case_type_enum not null,
    source_original_paid_amount numeric(12,2) not null,
    source_corrected_paid_amount numeric(12,2) not null,
    case_amount_ex numeric(12,2) not null,
    linked_shift_date date null,
    baseline_signature text null,
    components_sync_json jsonb not null,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_clears (
    finance_case_id uuid not null primary key,
    candidate_id uuid not null,
    timesheet_id uuid not null,
    old_case_type public.pay_finance_case_type_enum not null,
    old_original_amount numeric(12,2) not null,
    old_outstanding_amount numeric(12,2) not null,
    old_source_original_paid_amount numeric(12,2) null,
    old_source_corrected_paid_amount numeric(12,2) null,
    old_linked_shift_date date null,
    old_baseline_signature text null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_preview_candidates (
    candidate_id uuid not null primary key,
    candidate_json jsonb not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_negative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_raw_negative_timesheet_rows (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    case_components_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  truncate table pg_temp.tmp_sync_timesheet_case_candidates;
  truncate table pg_temp.tmp_sync_case_links;
  truncate table pg_temp.tmp_sync_case_clears;
  truncate table pg_temp.tmp_sync_preview_candidates;
  truncate table pg_temp.tmp_sync_authoritative_negative_components;
  truncate table pg_temp.tmp_sync_authoritative_components;
  truncate table pg_temp.tmp_sync_raw_negative_timesheet_rows;

  v_authority_validation_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_finance_case_authority;
    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_finance_case_authority ON COMMIT DROP AS
    SELECT fact.build_id,fact.candidate_id,fact.finance_case_id,
      COUNT(*)::integer AS evidence_count,
      COUNT(DISTINCT UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),'')))::integer
        AS distinct_case_type_count,
      MIN(UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),''))) AS case_type
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=p_build_id
      AND fact.fact_family='FINANCE_CASE_IDENTITY'
      AND fact.finance_case_id IS NOT NULL
    GROUP BY fact.build_id,fact.candidate_id,fact.finance_case_id;

    CREATE UNIQUE INDEX tmp_sync_sealed_finance_case_authority_idx
      ON pg_temp.tmp_sync_sealed_finance_case_authority(
        build_id,candidate_id,finance_case_id);

    INSERT INTO pg_temp.tmp_sync_authoritative_components (
      timesheet_id,
      key_type,
      key_value,
      truth_ex_vat,
      baseline_ex_vat,
      reserved_ex_vat,
      outstanding_ex_vat,
      baseline_signature
    )
    WITH live_entitlement_components AS (
      SELECT
        entitlement_component.timesheet_id,
        UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
        BTRIM(entitlement_component.key_value) AS key_value,
        ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat
      FROM (
        SELECT legacy_component.*
        FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
          p_build_id,NULL::text
        ) AS legacy_component
        WHERE v_execution_profile_version = 1
        UNION ALL
        SELECT cached_component.*
        FROM pg_temp.tmp_sync_entitlement_components_v2 AS cached_component
        WHERE v_execution_profile_version = 2
      ) AS entitlement_component
      WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
    ), active_entitlement_reservations AS (
      SELECT
        reserved_component.timesheet_id,
        UPPER(BTRIM(reserved_component.key_type)) AS key_type,
        BTRIM(reserved_component.key_value) AS key_value,
        ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat
      FROM (
        SELECT fact.timesheet_id,fact.economic_key_type AS key_type,
          fact.economic_key_value AS key_value,
          SUM(CASE
            WHEN case_authority.evidence_count=1
              AND case_authority.distinct_case_type_count=1
              AND case_authority.case_type='OVERPAYMENT'
              THEN -ABS(COALESCE(fact.reserved_source_amount,0))
            ELSE COALESCE(fact.reserved_source_amount,0)
          END) AS amount_ex_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        LEFT JOIN pg_temp.tmp_sync_sealed_finance_case_authority case_authority
          ON case_authority.build_id=fact.build_id
         AND case_authority.candidate_id=fact.candidate_id
         AND case_authority.finance_case_id=fact.finance_case_id
        WHERE fact.build_id=p_build_id AND fact.fact_family='RESERVATION_COMPONENT'
        GROUP BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value
      ) AS reserved_component
      WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
    ), live_economic_keys AS (
      SELECT
        live_component.timesheet_id,
        live_component.key_type,
        live_component.key_value
      FROM live_entitlement_components AS live_component

      UNION

      SELECT
        reserved_component.timesheet_id,
        reserved_component.key_type,
        reserved_component.key_value
      FROM active_entitlement_reservations AS reserved_component
    ), raw_outstanding_components AS (
      SELECT
        live_key.timesheet_id,
        live_key.key_type,
        live_key.key_value,
        ROUND(COALESCE(live_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat,
        ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat,
        ROUND(
          COALESCE(live_component.truth_ex_vat, 0)
          - COALESCE(live_component.baseline_ex_vat, 0)
          - COALESCE(reserved_component.reserved_ex_vat, 0),
          2
        )::numeric(12,2) AS outstanding_ex_vat
      FROM live_economic_keys AS live_key
      LEFT JOIN live_entitlement_components AS live_component
        ON live_component.timesheet_id = live_key.timesheet_id
       AND live_component.key_type = live_key.key_type
       AND live_component.key_value = live_key.key_value
      LEFT JOIN active_entitlement_reservations AS reserved_component
        ON reserved_component.timesheet_id = live_key.timesheet_id
       AND reserved_component.key_type = live_key.key_type
       AND reserved_component.key_value = live_key.key_value
    )
    SELECT
      raw_component.timesheet_id,
      raw_component.key_type,
      raw_component.key_value,
      raw_component.truth_ex_vat,
      raw_component.baseline_ex_vat,
      raw_component.reserved_ex_vat,
      raw_component.outstanding_ex_vat,
      COALESCE(active_settled_basis.active_settled_signature,md5('[]')) AS baseline_signature
    FROM raw_outstanding_components AS raw_component
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS active_settled_component_count,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_component.key_type,
            'key_value', active_settled_component.key_value,
            'amount_ex_vat', ROUND(COALESCE(active_settled_component.amount_ex_vat, 0), 2),
            'amount_inc_vat', ROUND(COALESCE(active_settled_component.amount_inc_vat, 0), 2)
          ) ORDER BY active_settled_component.key_type, active_settled_component.key_value
        )::text, '[]')) AS active_settled_signature
      FROM (
        SELECT fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          fact.amount_ex_vat,fact.amount_inc_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=p_build_id AND fact.timesheet_id=raw_component.timesheet_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      ) AS active_settled_component
      HAVING v_execution_profile_version = 1

      UNION ALL

      SELECT cached_basis.active_settled_component_count,cached_basis.active_settled_signature
      FROM pg_temp.tmp_sync_settled_basis_by_timesheet_v2 cached_basis
      WHERE v_execution_profile_version = 2
        AND cached_basis.timesheet_id=raw_component.timesheet_id
    ) AS active_settled_basis ON true
    ;

    INSERT INTO pg_temp.tmp_sync_authoritative_negative_components(
      timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,
      reserved_ex_vat,outstanding_ex_vat,baseline_signature
    )
    SELECT timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,
      reserved_ex_vat,outstanding_ex_vat,baseline_signature
    FROM pg_temp.tmp_sync_authoritative_components
    WHERE outstanding_ex_vat < 0;

    PERFORM public._ctms_rewrite_sync_authoritative_correction_negative_components_v1(
      nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid,
      v_authoritative_candidate_id,
      coalesce(p_force_include_timesheet_ids, array[]::uuid[])
    );

    SELECT
      COUNT(*)::integer,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'timesheet_id', negative_component.timesheet_id::text,
          'key_type', negative_component.key_type,
          'key_value', negative_component.key_value,
          'truth_ex_vat', ROUND(negative_component.truth_ex_vat, 2)::numeric(12,2),
          'baseline_ex_vat', ROUND(negative_component.baseline_ex_vat, 2)::numeric(12,2),
          'reserved_ex_vat', ROUND(negative_component.reserved_ex_vat, 2)::numeric(12,2),
          'outstanding_ex_vat', ROUND(negative_component.outstanding_ex_vat, 2)::numeric(12,2)
        ) ORDER BY negative_component.timesheet_id, negative_component.key_type, negative_component.key_value
      )::text, '[]'))
    INTO
      v_authoritative_negative_component_count,
      v_authoritative_negative_component_digest
    FROM pg_temp.tmp_sync_authoritative_negative_components AS negative_component;

    SELECT md5(COALESCE(jsonb_agg(
      jsonb_build_object(
        'timesheet_id', settled_component.timesheet_id::text,
        'key_type', settled_component.key_type,
        'key_value', settled_component.key_value,
        'amount_ex_vat', ROUND(COALESCE(settled_component.amount_ex_vat, 0), 2),
        'amount_inc_vat', ROUND(COALESCE(settled_component.amount_inc_vat, 0), 2)
      ) ORDER BY settled_component.timesheet_id, settled_component.key_type, settled_component.key_value
    )::text, '[]'))
    INTO v_authoritative_settled_baseline_digest
    FROM (
      SELECT fact.timesheet_id,fact.economic_key_type AS key_type,
        fact.economic_key_value AS key_value,fact.amount_ex_vat,fact.amount_inc_vat
      FROM private.banking_pay_workbench_economic_build_facts fact
      WHERE fact.build_id=p_build_id
        AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
    ) AS settled_component;

    -- These two attestations are private build authority.  They are derived
    -- only after immutable fact materialisation; caller/job values were
    -- stripped above and can never assert them.
    v_expected_negative_component_digest := v_authoritative_negative_component_digest;
    v_expected_settled_baseline_digest := v_authoritative_settled_baseline_digest;
    p_mismatch_choices:=p_mismatch_choices||jsonb_build_object(
      'overpayment_sync_negative_component_digest',v_expected_negative_component_digest,
      'overpayment_sync_settled_baseline_digest',v_expected_settled_baseline_digest);

    IF v_authoritative_negative_component_digest IS DISTINCT FROM v_expected_negative_component_digest
       OR v_authoritative_settled_baseline_digest IS DISTINCT FROM v_expected_settled_baseline_digest THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                'expected_negative_component_digest', v_expected_negative_component_digest,
                'actual_negative_component_digest', v_authoritative_negative_component_digest,
                'expected_settled_baseline_digest', v_expected_settled_baseline_digest,
                'actual_settled_baseline_digest', v_authoritative_settled_baseline_digest,
                'message', 'The Workbench negative-component or settled-baseline authority changed before finance-case synchronisation.'
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope,false) THEN
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection_raw;
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection_failures;
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection_raw
    ON COMMIT DROP AS
    SELECT row_number() OVER(ORDER BY helper_row.timesheet_id NULLS FIRST,
        helper_row.economic_key_type NULLS FIRST,helper_row.economic_key_value NULLS FIRST,
        helper_row.physical_bucket_key NULLS FIRST,helper_row.failure_code NULLS FIRST,
        helper_row.evidence_json::text)::bigint AS materialization_ordinal,
      helper_row.*
    FROM private.pay_workbench_sealed_rate_component_projection_v1(
      p_build_id,v_bounded_build.candidate_id,
      CASE WHEN p_force_include_timesheet_ids IS NULL THEN NULL::uuid[]
        ELSE p_force_include_timesheet_ids END
    ) helper_row;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection_failures(
      failure_rank integer NOT NULL,failure_code text NOT NULL,timesheet_id uuid,
      economic_key_type text,economic_key_value text,physical_bucket_key text,
      detail_json jsonb NOT NULL
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 10,COALESCE(NULLIF(BTRIM(raw.failure_code),''),
        'RATE_AUTHORITY_FAILED_ROW_CODE_MISSING'),raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'projection_status',raw.projection_status,'failure_code',raw.failure_code)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))='FAILED';

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 20,'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'source_family_key',raw.source_family_key,'component_kind',raw.component_kind,
        'component_member_identity',raw.component_member_identity,'bucket_code',raw.bucket_code)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (raw.timesheet_id IS NULL OR NULLIF(BTRIM(raw.economic_key_type),'') IS NULL
        OR NULLIF(BTRIM(raw.economic_key_value),'') IS NULL
        OR NULLIF(BTRIM(raw.source_family_key),'') IS NULL
        OR NULLIF(BTRIM(raw.component_kind),'') IS NULL
        OR NULLIF(BTRIM(raw.component_member_identity),'') IS NULL
        OR NULLIF(BTRIM(raw.bucket_code),'') IS NULL
        OR NULLIF(BTRIM(raw.physical_bucket_key),'') IS NULL);

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 21,'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'source_pay_method',raw.source_pay_method)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (NULLIF(BTRIM(raw.source_pay_method),'') IS NULL
        OR UPPER(BTRIM(raw.source_pay_method)) NOT IN ('PAYE','UMBRELLA'));

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 22,'RATE_AUTHORITY_TARGET_PAY_METHOD_MISSING',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'target_pay_method',raw.target_pay_method)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (NULLIF(BTRIM(raw.target_pay_method),'') IS NULL
        OR UPPER(BTRIM(raw.target_pay_method)) NOT IN ('PAYE','UMBRELLA'));

    WITH key_methods AS MATERIALIZED (
      SELECT DISTINCT raw.timesheet_id,
        UPPER(BTRIM(raw.economic_key_type)) AS economic_key_type,
        BTRIM(raw.economic_key_value) AS economic_key_value,
        UPPER(BTRIM(raw.source_pay_method)) AS source_pay_method
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
        AND raw.failure_code IS NULL
    ), timesheet_methods AS MATERIALIZED (
      SELECT key_method.timesheet_id,
        COUNT(DISTINCT key_method.source_pay_method)::integer
          AS distinct_supported_method_count,
        COUNT(*)::integer AS economic_key_count,
        jsonb_agg(jsonb_build_object(
          'economic_key_type',key_method.economic_key_type,
          'economic_key_value',key_method.economic_key_value,
          'source_pay_method',key_method.source_pay_method)
          ORDER BY key_method.economic_key_type,key_method.economic_key_value,
            key_method.source_pay_method) AS complete_key_method_set
      FROM key_methods key_method
      GROUP BY key_method.timesheet_id
    )
    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 23,'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT',method.timesheet_id,
      NULL::text,NULL::text,NULL::text,
      jsonb_build_object(
        'distinct_supported_method_count',method.distinct_supported_method_count,
        'economic_key_count',method.economic_key_count,
        'complete_economic_key_method_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(method.complete_key_method_set::text,'UTF8'),
          'sha256'),'hex'),
        'sample_truncated',method.economic_key_count>25,
        'economic_key_method_sample',pg_catalog.jsonb_path_query_array(
          method.complete_key_method_set,'$[0 to 24]'))
    FROM timesheet_methods method
    WHERE method.distinct_supported_method_count<>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 30,'RATE_AUTHORITY_DUPLICATE_PHYSICAL_BUCKET',duplicate.timesheet_id,
      duplicate.economic_key_type,duplicate.economic_key_value,
      duplicate.physical_bucket_key,
      jsonb_build_object('duplicate_count',duplicate.duplicate_count)
    FROM (
      SELECT raw.timesheet_id,raw.economic_key_type,raw.economic_key_value,
        raw.physical_bucket_key,count(*)::integer AS duplicate_count
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
        AND raw.timesheet_id IS NOT NULL
        AND NULLIF(BTRIM(raw.economic_key_type),'') IS NOT NULL
        AND NULLIF(BTRIM(raw.economic_key_value),'') IS NOT NULL
        AND NULLIF(BTRIM(raw.physical_bucket_key),'') IS NOT NULL
      GROUP BY raw.timesheet_id,raw.economic_key_type,raw.economic_key_value,
        raw.physical_bucket_key HAVING count(*)>1
    ) duplicate;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 40,'RATE_AUTHORITY_TARGET_AUTHORITY_CONFLICT',NULL::uuid,NULL::text,
      NULL::text,NULL::text,jsonb_build_object(
        'target_method_count',count(DISTINCT raw.target_pay_method),
        'target_digest_count',count(DISTINCT raw.target_authority_digest),
        'conversion_digest_count',count(DISTINCT raw.conversion_context_digest))
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
    HAVING count(DISTINCT raw.target_pay_method)<>1
       OR count(DISTINCT raw.target_authority_digest)<>1
       OR count(DISTINCT raw.conversion_context_digest)<>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 45,'RATE_AUTHORITY_MULTIPLE_RATES_UNSUPPORTED',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,MIN(raw.physical_bucket_key),
      jsonb_build_object('component_kind',raw.component_kind,
        'component_member_identity',raw.component_member_identity,
        'bucket_code',raw.bucket_code,
        'source_rate_count',count(DISTINCT ROUND(raw.source_rate,6)),
        'source_charge_rate_count',count(DISTINCT ROUND(raw.source_charge_rate,6)))
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
      AND raw.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
    GROUP BY raw.timesheet_id,raw.component_kind,raw.component_member_identity,
      raw.economic_key_type,raw.economic_key_value,raw.bucket_code
    HAVING count(DISTINCT ROUND(raw.source_rate,6))>1
       OR count(DISTINCT ROUND(raw.source_charge_rate,6))>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 50,'PAY_SYNC_OVERPAYMENTS_RATE_ECONOMIC_FENCE_MISMATCH',
      COALESCE(expected.timesheet_id,actual.timesheet_id),
      COALESCE(expected.key_type,actual.economic_key_type),
      COALESCE(expected.key_value,actual.economic_key_value),NULL::text,
      jsonb_build_object('expected_truth_ex_vat',expected.truth_ex_vat,
        'actual_truth_ex_vat',actual.truth_ex_vat,
        'expected_baseline_ex_vat',expected.baseline_ex_vat,
        'actual_baseline_ex_vat',actual.baseline_ex_vat,
        'expected_reserved_ex_vat',expected.reserved_ex_vat,
        'actual_reserved_ex_vat',actual.reserved_ex_vat,
        'expected_outstanding_ex_vat',expected.outstanding_ex_vat,
        'actual_outstanding_ex_vat',actual.outstanding_ex_vat)
    FROM pg_temp.tmp_sync_authoritative_components expected
    FULL OUTER JOIN (
      SELECT raw.timesheet_id,UPPER(BTRIM(raw.economic_key_type)) AS economic_key_type,
        BTRIM(raw.economic_key_value) AS economic_key_value,
        ROUND(SUM(raw.truth_ex_vat),2) AS truth_ex_vat,
        ROUND(SUM(raw.baseline_ex_vat),2) AS baseline_ex_vat,
        ROUND(SUM(raw.reserved_ex_vat),2) AS reserved_ex_vat,
        ROUND(SUM(raw.outstanding_ex_vat),2) AS outstanding_ex_vat
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
        AND raw.failure_code IS NULL
      GROUP BY raw.timesheet_id,UPPER(BTRIM(raw.economic_key_type)),
        BTRIM(raw.economic_key_value)
    ) actual ON actual.timesheet_id=expected.timesheet_id
      AND actual.economic_key_type=expected.key_type
      AND actual.economic_key_value=expected.key_value
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
      OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
      OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
      OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
      OR actual.outstanding_ex_vat IS DISTINCT FROM expected.outstanding_ex_vat;

    v_rate_authority_failure_code:=NULL::text;
    v_rate_authority_failure_detail:='[]'::jsonb;

    SELECT failure.failure_code
    INTO v_rate_authority_failure_code
    FROM pg_temp.tmp_sync_sealed_rate_projection_failures failure
    ORDER BY failure.failure_rank,failure.timesheet_id NULLS FIRST,
      failure.economic_key_type NULLS FIRST,failure.economic_key_value NULLS FIRST,
      failure.physical_bucket_key NULLS FIRST,failure.failure_code
    LIMIT 1;

    SELECT COALESCE(jsonb_agg(jsonb_build_object('failure_rank',failure.failure_rank,
        'failure_code',failure.failure_code,'timesheet_id',failure.timesheet_id,
        'economic_key_type',failure.economic_key_type,
        'economic_key_value',failure.economic_key_value,
        'physical_bucket_key',failure.physical_bucket_key,
        'detail',failure.detail_json) ORDER BY failure.failure_rank,
        failure.timesheet_id NULLS FIRST,failure.economic_key_type NULLS FIRST,
        failure.economic_key_value NULLS FIRST,failure.physical_bucket_key NULLS FIRST,
        failure.failure_code),'[]'::jsonb)
    INTO v_rate_authority_failure_detail
    FROM pg_temp.tmp_sync_sealed_rate_projection_failures failure;

    IF v_rate_authority_failure_code IS NOT NULL THEN
      RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
        DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
          'failures',v_rate_authority_failure_detail)::text;
    END IF;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection ON COMMIT DROP AS
    SELECT raw.build_id,raw.candidate_id,raw.timesheet_id,raw.financial_row_id,
      raw.source_family_key,raw.economic_key_type,raw.economic_key_value,
      raw.component_kind,raw.component_member_identity,raw.segment_id,raw.segment_key,
      raw.segment_stable_key,raw.bucket_code,raw.bucket_sort_ordinal,
      raw.physical_bucket_key,raw.physical_bucket_digest,raw.source_units,
      raw.source_rate,raw.source_charge_rate,raw.truth_ex_vat,raw.baseline_ex_vat,
      raw.reserved_ex_vat,raw.outstanding_ex_vat,raw.source_charge_ex_vat,
      raw.source_pay_method,raw.target_pay_method,raw.umbrella_id,
      raw.umbrella_enabled,raw.umbrella_vat_chargeable,raw.erni_pct,raw.vat_rate_pct,
      raw.financial_revision_digest,raw.target_authority_digest,
      raw.conversion_context_digest,raw.sealed_evidence_digest,
      raw.projection_status,raw.failure_code,raw.evidence_json
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(raw.projection_status) IN ('READY','FIXED') AND raw.failure_code IS NULL;

    ALTER TABLE pg_temp.tmp_sync_sealed_rate_projection
      ALTER COLUMN timesheet_id SET NOT NULL,
      ALTER COLUMN economic_key_type SET NOT NULL,
      ALTER COLUMN economic_key_value SET NOT NULL,
      ALTER COLUMN source_family_key SET NOT NULL,
      ALTER COLUMN component_kind SET NOT NULL,
      ALTER COLUMN component_member_identity SET NOT NULL,
      ALTER COLUMN bucket_code SET NOT NULL,
      ALTER COLUMN physical_bucket_key SET NOT NULL,
      ALTER COLUMN physical_bucket_digest SET NOT NULL,
      ALTER COLUMN source_pay_method SET NOT NULL,
      ALTER COLUMN target_pay_method SET NOT NULL,
      ALTER COLUMN projection_status SET NOT NULL,
      ALTER COLUMN evidence_json SET NOT NULL,
      ADD CHECK (projection_status IN ('READY','FIXED')),
      ADD PRIMARY KEY(timesheet_id,economic_key_type,economic_key_value,physical_bucket_key);
    CREATE INDEX tmp_sync_sealed_rate_projection_lookup_idx
      ON pg_temp.tmp_sync_sealed_rate_projection(
        timesheet_id,source_family_key,economic_key_type,economic_key_value,bucket_code);

    /* The legacy pre-Draft renderer is allowed to omit an economic component
       whose live truth is zero.  Preserve every renderer-owned component as-is,
       but retain an exact physical-bucket map so a frozen baseline-only
       component can be supplied from the already validated sealed projection
       when (and only when) the renderer has no owner for that bucket. */
    DROP TABLE IF EXISTS pg_temp.tmp_sync_raw_preview_physical_components;
    CREATE TEMP TABLE pg_temp.tmp_sync_raw_preview_physical_components (
      candidate_id uuid NOT NULL,
      timesheet_id uuid NOT NULL,
      component_ordinality bigint NOT NULL,
      physical_bucket_key text NULL,
      component_json jsonb NOT NULL
    ) ON COMMIT DROP;

    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_missing_preview_components;
    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_missing_preview_components (
      candidate_id uuid NOT NULL,
      timesheet_id uuid NOT NULL,
      economic_key_type text NOT NULL,
      economic_key_value text NOT NULL,
      bucket_sort_ordinal integer NOT NULL,
      physical_bucket_key text NOT NULL,
      component_json jsonb NOT NULL,
      PRIMARY KEY(candidate_id,timesheet_id,physical_bucket_key)
    ) ON COMMIT DROP;
  END IF;

  v_component_assembly_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_authoritative_components_ms := COALESCE(v_preflight_setup_ms,0)
    + COALESCE(v_correction_residuals_ms,0)
    + COALESCE(v_authority_validation_ms,0)
    + COALESCE(v_component_assembly_ms,0);
  v_phase_started_at := clock_timestamp();
  IF v_requested_candidate_count > 0 THEN
    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT requested_candidate.candidate_id
      FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
      WHERE requested_candidate.candidate_id IS NOT NULL
      ORDER BY requested_candidate.candidate_id
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      )
      || CASE
        WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
          jsonb_build_object(
            'workbench_source_build_mode', true,
            'source_build_mode', true,
            'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            -- v_workbench_session_id has already passed the exact session,
            -- candidate, version, actor, pay-date and scope authority checks
            -- above.  The existing preview overlay deliberately requires this
            -- explicit session authority before consuming saved rate choices.
            'workbench_resolution_session_id',v_workbench_session_id::text
          )
        ELSE '{}'::jsonb
      END;

      IF COALESCE(v_authoritative_timesheet_scope, false) THEN
        v_phase_started_at := clock_timestamp();
        v_preview_collect_result_json := public.pay_preview_candidate_collect_scope(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
        v_preview_collect_ms := v_preview_collect_ms
          + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

        -- pay_preview_candidate_collect_scope intentionally discovers current
        -- pre-Draft reservation state.  A sealed build must not continue using
        -- those later live rows, so replace the complete reservation workspace
        -- with the RESERVATION_COMPONENT facts captured by this build before
        -- any baseline or component construction consumes it.
        DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_reservation_items;
        CREATE TEMP TABLE pg_temp.tmp_sync_sealed_reservation_items ON COMMIT DROP AS
        SELECT fact.fact_family||':'||fact.natural_key AS authority_fact_identity,
          CASE WHEN COALESCE(fact.source_payload_json#>>'{pay_batch_item,id}','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json#>>'{pay_batch_item,id}')::uuid
            WHEN COALESCE(fact.source_payload_json->>'pay_batch_item_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json->>'pay_batch_item_id')::uuid END AS pay_batch_item_id,
          CASE WHEN COALESCE(fact.source_payload_json#>>'{pay_batch_item,pay_batch_id}','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json#>>'{pay_batch_item,pay_batch_id}')::uuid
            WHEN COALESCE(fact.source_payload_json->>'pay_batch_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json->>'pay_batch_id')::uuid END AS pay_batch_id,
          fact.timesheet_id,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{pay_batch_item,segment_key}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_key}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_key}')),'')
            AS segment_key,
          NULLIF(BTRIM(COALESCE(
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_id}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_id}',
            CASE WHEN NULLIF(BTRIM(COALESCE(
                fact.source_payload_json#>>'{pay_batch_item,source_ref}',
                fact.source_payload_json->>'source_ref')),'') LIKE 'seg:%'
              THEN split_part(COALESCE(fact.source_payload_json#>>'{pay_batch_item,source_ref}',
                fact.source_payload_json->>'source_ref'),':',2) END,
            fact.source_payload_json#>>'{pay_batch_item,segment_key}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_key}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_key}')),'')
            AS segment_id_norm,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{pay_batch_item,source_ref}',
            fact.source_payload_json->>'source_ref')),'') AS source_ref,
          COALESCE(NULLIF(BTRIM(fact.source_payload_json#>>'{pay_batch_item,item_type}'),''),
            CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN 'OVERPAYMENT_RECOVERY' END,
            CASE UPPER(BTRIM(fact.economic_key_type))
              WHEN 'TS_DAY' THEN 'SEGMENT_DELTA' WHEN 'TS_TOTAL' THEN 'SEGMENT_DELTA'
              WHEN 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
              WHEN 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
              WHEN 'ADDITIONAL_CODE' THEN 'ADJUSTMENT_DELTA'
              ELSE 'ADJUSTMENT_DELTA' END) AS item_type,
          UPPER(BTRIM(fact.economic_key_type)) AS component_key_type,
          BTRIM(fact.economic_key_value) AS component_key_value,
          COALESCE(NULLIF(BTRIM(fact.source_payload_json#>>'{economic_key,key_resolution_source}'),''),
            CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN 'FINANCE_CASE_IDENTITY' END,
            'SEALED_RESERVATION_COMPONENT') AS key_resolution_source,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{economic_key,key_resolution_failure_reason}',
            fact.source_payload_json->>'resolution_failure')),'') AS key_resolution_failure_reason,
          ROUND(CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN -ABS(COALESCE(fact.reserved_source_amount,0))
            ELSE COALESCE(fact.reserved_source_amount,0) END,2) AS amount_ex_vat,
          CASE WHEN jsonb_typeof(fact.source_payload_json->'breakdowns')='array'
            THEN fact.source_payload_json->'breakdowns' ELSE '[]'::jsonb END AS breakdowns
        FROM private.banking_pay_workbench_economic_build_facts fact
        LEFT JOIN pg_temp.tmp_sync_sealed_finance_case_authority case_authority
          ON case_authority.build_id=fact.build_id
         AND case_authority.candidate_id=fact.candidate_id
         AND case_authority.finance_case_id=fact.finance_case_id
        WHERE fact.build_id=p_build_id AND fact.candidate_id=v_preview_candidate_loop_id
          AND fact.fact_family='RESERVATION_COMPONENT'
          AND fact.timesheet_id IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(fact.economic_key_type,'')),'') IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(fact.economic_key_value,'')),'') IS NOT NULL;

        CREATE UNIQUE INDEX tmp_sync_sealed_reservation_items_authority_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(authority_fact_identity);
        CREATE INDEX tmp_sync_sealed_reservation_items_key_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(
            timesheet_id,component_key_type,component_key_value);
        CREATE INDEX tmp_sync_sealed_reservation_items_source_ref_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(timesheet_id,source_ref);
        CREATE INDEX tmp_sync_sealed_reservation_items_type_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(timesheet_id,item_type);

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_batch_items_replacement
          (LIKE pg_temp.reserved_batch_items INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_batch_items_replacement(
          pay_batch_item_id,pay_batch_id,timesheet_id,segment_key,segment_id_norm,
          source_ref,item_type,component_key_type,component_key_value,
          key_resolution_source,key_resolution_failure_reason,amount_ex_vat)
        SELECT sealed.pay_batch_item_id,sealed.pay_batch_id,sealed.timesheet_id,
          sealed.segment_key,sealed.segment_id_norm,sealed.source_ref,sealed.item_type,
          sealed.component_key_type,sealed.component_key_value,
          sealed.key_resolution_source,sealed.key_resolution_failure_reason,
          sealed.amount_ex_vat
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_by_source_ref_replacement
          (LIKE pg_temp.reserved_by_source_ref INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_by_source_ref_replacement
        SELECT sealed.timesheet_id,sealed.source_ref,ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.source_ref IS NOT NULL
        GROUP BY sealed.timesheet_id,sealed.source_ref;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_total_by_timesheet_replacement
          (LIKE pg_temp.reserved_total_by_timesheet INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_total_by_timesheet_replacement
        SELECT sealed.timesheet_id,ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        GROUP BY sealed.timesheet_id;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_segment_key_map_replacement
          (LIKE pg_temp.reserved_segment_key_map INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_segment_key_map_replacement
        SELECT sealed.timesheet_id,sealed.segment_id_norm,
          sealed.component_key_type,sealed.component_key_value
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='SEGMENT_DELTA'
          AND sealed.component_key_type IN ('TS_DAY','TS_TOTAL')
          AND sealed.component_key_value IS NOT NULL
          AND (sealed.component_key_type<>'TS_DAY'
            OR sealed.component_key_value ~ '^\d{4}-\d{2}-\d{2}$');

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_segment_sums_replacement
          (LIKE pg_temp.reserved_segment_sums INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_segment_sums_replacement
        SELECT sealed.timesheet_id,sealed.component_key_type,sealed.component_key_value,
          ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='SEGMENT_DELTA'
          AND sealed.component_key_type IN ('TS_DAY','TS_TOTAL')
          AND sealed.component_key_value IS NOT NULL
          AND (sealed.component_key_type<>'TS_DAY'
            OR sealed.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
        GROUP BY sealed.timesheet_id,sealed.component_key_type,sealed.component_key_value;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_preview_segment_ords_replacement
          (LIKE pg_temp.reserved_preview_segment_ords INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_preview_segment_ords_replacement
        SELECT sealed.timesheet_id,
          CASE WHEN split_part(COALESCE(sealed.source_ref,''),':',3) ~ '^\d+$'
            THEN split_part(sealed.source_ref,':',3)::integer END,
          ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='ADJUSTMENT_DELTA'
          AND BTRIM(COALESCE(sealed.source_ref,'')) LIKE 'preview_seg:%'
        GROUP BY sealed.timesheet_id,
          CASE WHEN split_part(COALESCE(sealed.source_ref,''),':',3) ~ '^\d+$'
            THEN split_part(sealed.source_ref,':',3)::integer END;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_additional_by_code_replacement
          (LIKE pg_temp.reserved_additional_by_code INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_additional_by_code_replacement
        SELECT sealed.timesheet_id,UPPER(NULLIF(BTRIM(COALESCE(
            breakdown.value->>'bucket_code',
            CASE WHEN sealed.component_key_type='ADDITIONAL_CODE'
              THEN sealed.component_key_value END)),'')) AS code,
          ROUND(SUM(CASE
            WHEN COALESCE(breakdown.value#>>'{meta_json,source_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value#>>'{meta_json,source_amount_ex_vat}')::numeric)
            WHEN COALESCE(breakdown.value#>>'{meta_json,source_pay_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value#>>'{meta_json,source_pay_ex_vat}')::numeric)
            WHEN COALESCE(breakdown.value->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value->>'amount_ex_vat')::numeric)
            ELSE ABS(sealed.amount_ex_vat) END),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        LEFT JOIN LATERAL jsonb_array_elements(CASE
          WHEN jsonb_typeof(sealed.breakdowns)='array' AND jsonb_array_length(sealed.breakdowns)>0
            THEN sealed.breakdowns
          WHEN sealed.component_key_type='ADDITIONAL_CODE'
            THEN jsonb_build_array(jsonb_build_object(
              'bucket_code',sealed.component_key_value,
              'amount_ex_vat',sealed.amount_ex_vat,
              'line_kind','ADDITIONAL_UNIT'))
          ELSE '[]'::jsonb END) breakdown(value) ON true
        WHERE (breakdown.value->>'line_kind'='ADDITIONAL_UNIT'
            OR sealed.component_key_type='ADDITIONAL_CODE')
          AND NULLIF(BTRIM(COALESCE(breakdown.value->>'bucket_code',
            sealed.component_key_value)),'') IS NOT NULL
        GROUP BY sealed.timesheet_id,UPPER(NULLIF(BTRIM(COALESCE(
          breakdown.value->>'bucket_code',
          CASE WHEN sealed.component_key_type='ADDITIONAL_CODE'
            THEN sealed.component_key_value END)),''));

        DROP TABLE pg_temp.reserved_batch_items,pg_temp.reserved_by_source_ref,
          pg_temp.reserved_total_by_timesheet,pg_temp.reserved_segment_key_map,
          pg_temp.reserved_segment_sums,pg_temp.reserved_preview_segment_ords,
          pg_temp.reserved_additional_by_code;
        ALTER TABLE pg_temp.tmp_sync_reserved_batch_items_replacement RENAME TO reserved_batch_items;
        ALTER TABLE pg_temp.tmp_sync_reserved_by_source_ref_replacement RENAME TO reserved_by_source_ref;
        ALTER TABLE pg_temp.tmp_sync_reserved_total_by_timesheet_replacement RENAME TO reserved_total_by_timesheet;
        ALTER TABLE pg_temp.tmp_sync_reserved_segment_key_map_replacement RENAME TO reserved_segment_key_map;
        ALTER TABLE pg_temp.tmp_sync_reserved_segment_sums_replacement RENAME TO reserved_segment_sums;
        ALTER TABLE pg_temp.tmp_sync_reserved_preview_segment_ords_replacement RENAME TO reserved_preview_segment_ords;
        ALTER TABLE pg_temp.tmp_sync_reserved_additional_by_code_replacement RENAME TO reserved_additional_by_code;

        IF to_regclass('pg_temp.ts_baseline') IS NULL
           OR to_regclass('pg_temp.pay_preview_candidate_context') IS NULL THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_INPUT_MISSING'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_INPUT_MISSING',
              'candidate_id',v_preview_candidate_loop_id::text)::text;
        END IF;

        IF EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          LEFT JOIN pg_temp.ts_baseline baseline
            ON baseline.candidate_id=v_preview_candidate_loop_id
           AND baseline.timesheet_id=sealed.timesheet_id
          WHERE baseline.timesheet_id IS NULL
        ) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_METADATA_INCOMPLETE'
            USING ERRCODE='23514';
        END IF;

        UPDATE pg_temp.pay_preview_candidate_context context_row
        SET erni_pct=authority.erni_pct,vat_rate_pct=authority.vat_rate_pct
        FROM (
          SELECT MIN(sealed.erni_pct) AS erni_pct,MIN(sealed.vat_rate_pct) AS vat_rate_pct
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
        ) authority
        WHERE context_row.candidate_id=v_preview_candidate_loop_id;

        WITH segment_bucket_rows AS (
          SELECT sealed.*,
            CASE WHEN COALESCE(sealed.evidence_json#>>'{source_ordinal}','') ~ '^\d+$'
              THEN (sealed.evidence_json#>>'{source_ordinal}')::bigint ELSE 0 END
              AS source_ordinal,
            CASE WHEN jsonb_typeof(sealed.evidence_json#>'{source_payload,segment}')='object'
              THEN sealed.evidence_json#>'{source_payload,segment}' ELSE '{}'::jsonb END
              AS source_segment,
            COALESCE(sealed.segment_stable_key,sealed.segment_id,sealed.segment_key,
              CASE WHEN sealed.component_kind='WORKED_TIME_RESIDUAL'
                THEN 'worked-time-residual:'||sealed.economic_key_type||':'
                  ||sealed.economic_key_value END) AS builder_segment_identity
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          WHERE sealed.component_kind IN ('WORKED_TIME','WORKED_TIME_RESIDUAL')
        ), segment_grouped AS (
          SELECT segment.timesheet_id,segment.builder_segment_identity,
            segment.economic_key_type,segment.economic_key_value,
            COALESCE(MIN(segment.segment_id),segment.builder_segment_identity) AS segment_id,
            COALESCE(MIN(segment.segment_key),segment.builder_segment_identity) AS segment_key,
            MIN(segment.source_ordinal) AS source_ordinal,
            (array_agg(segment.source_segment ORDER BY segment.source_ordinal,
              segment.builder_segment_identity,segment.segment_id))[1]
              ||jsonb_build_object(
                'segment_id',COALESCE(MIN(segment.segment_id),segment.builder_segment_identity),
                'segment_key',COALESCE(MIN(segment.segment_key),segment.builder_segment_identity),
                'segment_stable_key',segment.builder_segment_identity,
                'date',MIN(COALESCE(segment.source_segment->>'date',
                  segment.source_segment->>'work_date',CASE
                    WHEN segment.economic_key_type='TS_DAY' THEN segment.economic_key_value END)),
                'hours_day',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='DAY'),0),6),
                'hours_night',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='NIGHT'),0),6),
                'hours_sat',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='SAT'),0),6),
                'hours_sun',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='SUN'),0),6),
                'hours_bh',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='BH'),0),6),
                'pay_amount',ROUND(SUM(segment.truth_ex_vat),2),
                'charge_amount',ROUND(SUM(COALESCE(segment.source_charge_ex_vat,0)),2))
              AS segment_json
          FROM segment_bucket_rows segment
          GROUP BY segment.timesheet_id,segment.builder_segment_identity,
            segment.economic_key_type,segment.economic_key_value
        ), segments_by_timesheet AS (
          SELECT grouped.timesheet_id,jsonb_agg(grouped.segment_json ORDER BY
            grouped.source_ordinal,grouped.builder_segment_identity,grouped.segment_id)
              AS segments_json
          FROM segment_grouped grouped GROUP BY grouped.timesheet_id
        ), additional_by_timesheet AS (
          SELECT additional.timesheet_id,
            COALESCE(jsonb_object_agg(
              additional.evidence_json#>>'{source_payload,raw_additional_code}',
              additional.evidence_json#>'{source_payload,source_value}' ORDER BY
              octet_length(additional.evidence_json#>>'{source_payload,raw_additional_code}'),
              encode(convert_to(additional.evidence_json#>>'{source_payload,raw_additional_code}',
                'UTF8'),'hex')),'{}'::jsonb) AS additional_json,
            ROUND(SUM(additional.truth_ex_vat),2) AS additional_pay_ex_vat,
            ROUND(SUM(COALESCE(additional.source_charge_ex_vat,0)),2)
              AS additional_charge_ex_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection additional
          WHERE additional.component_kind='ADDITIONAL_UNIT'
            AND COALESCE(additional.evidence_json->>'source_key','') NOT LIKE 'SEALED_SYNTHETIC:%'
            AND NULLIF(additional.evidence_json#>>'{source_payload,raw_additional_code}','')
              IS NOT NULL
          GROUP BY additional.timesheet_id
        ), adjustments_by_timesheet AS (
          SELECT adjustment.timesheet_id,jsonb_agg(jsonb_build_object(
              'id',adjustment.evidence_json#>>'{source_payload,adjustment_id}',
              'delta_pay_ex_vat',ROUND(adjustment.truth_ex_vat,2))
            ORDER BY adjustment.evidence_json#>>'{source_payload,adjustment_id}') AS adjustments_json
          FROM pg_temp.tmp_sync_sealed_rate_projection adjustment
          WHERE adjustment.component_kind='ADJUSTMENT'
            AND COALESCE(adjustment.evidence_json->>'source_key','') NOT LIKE 'SEALED_SYNTHETIC:%'
          GROUP BY adjustment.timesheet_id
        ), economic_projection_totals AS (
          SELECT sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value,
            ROUND(SUM(sealed.truth_ex_vat),2) AS truth_ex_vat,
            ROUND(SUM(sealed.baseline_ex_vat),2) AS baseline_ex_vat,
            ROUND(SUM(sealed.reserved_ex_vat),2) AS reserved_ex_vat,
            MIN(CASE WHEN COALESCE(sealed.evidence_json#>>'{economic_authority,baseline_inc_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>'{economic_authority,baseline_inc_vat}')::numeric END)
              AS baseline_inc_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          GROUP BY sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value
        ), baseline_only_keys AS (
          SELECT total.*
          FROM economic_projection_totals total
          WHERE ABS(total.truth_ex_vat)<=0.005 AND ABS(total.baseline_ex_vat)>0.005
        ), baseline_only_physical_evidence AS (
          SELECT sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value,
            ROUND(SUM(sealed.source_charge_ex_vat),2) AS source_charge_ex_vat,
            (array_agg(sealed.evidence_json#>'{source_payload,source_value}' ORDER BY
              sealed.physical_bucket_key))[1] AS source_value
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          JOIN baseline_only_keys baseline
            USING(timesheet_id,economic_key_type,economic_key_value)
          GROUP BY sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value
        ), baseline_only_active_artifacts AS (
          SELECT baseline.timesheet_id,
            jsonb_agg(jsonb_build_object(
              'key_type',baseline.economic_key_type,
              'key_value',baseline.economic_key_value,
              'amount_ex_vat',baseline.baseline_ex_vat,
              'amount_inc_vat',COALESCE(baseline.baseline_inc_vat,baseline.baseline_ex_vat),
              'baseline_source','SEALED_BUILD_FACTS') ORDER BY
              baseline.economic_key_type,baseline.economic_key_value) AS components_json,
            COUNT(*)::integer AS component_count,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS amount_ex_vat,
            ROUND(SUM(COALESCE(baseline.baseline_inc_vat,baseline.baseline_ex_vat)),2)
              AS amount_inc_vat
          FROM baseline_only_keys baseline GROUP BY baseline.timesheet_id
        ), baseline_only_expenses AS (
          SELECT baseline.timesheet_id,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS expenses_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat),0),2) AS expenses_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='TRAVEL'),2) AS travel_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='TRAVEL'),0),2) AS travel_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='ACCOMMODATION'),2) AS accommodation_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='ACCOMMODATION'),0),2)
              AS accommodation_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='OTHER'),2) AS other_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='OTHER'),0),2) AS other_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='MILEAGE'),2) AS mileage_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='MILEAGE'),0),2) AS mileage_charge_ex_vat
          FROM baseline_only_keys baseline
          LEFT JOIN baseline_only_physical_evidence sealed
            USING(timesheet_id,economic_key_type,economic_key_value)
          WHERE baseline.economic_key_type='EXPENSE_CODE'
          GROUP BY baseline.timesheet_id
        ), baseline_only_additional AS (
          SELECT baseline.timesheet_id,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS additional_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat),0),2) AS additional_charge_ex_vat,
            COALESCE(jsonb_object_agg(baseline.economic_key_value,
              COALESCE(sealed.source_value,
                jsonb_build_object('source_pay_ex_vat',baseline.baseline_ex_vat))
              ORDER BY octet_length(baseline.economic_key_value),
                encode(convert_to(baseline.economic_key_value,'UTF8'),'hex')),'{}'::jsonb)
              AS additional_units_json
          FROM baseline_only_keys baseline
          LEFT JOIN baseline_only_physical_evidence sealed
            USING(timesheet_id,economic_key_type,economic_key_value)
          WHERE baseline.economic_key_type='ADDITIONAL_CODE'
          GROUP BY baseline.timesheet_id
        ), baseline_only_adjustments AS (
          SELECT baseline.timesheet_id,jsonb_agg(jsonb_build_object(
              'id',baseline.economic_key_value,
              'pay_amount_ex_vat',baseline.baseline_ex_vat,
              'source_pay_ex_vat',baseline.baseline_ex_vat)
            ORDER BY baseline.economic_key_value) AS adjustments_json
          FROM baseline_only_keys baseline
          WHERE baseline.economic_key_type='ADJUSTMENT_CODE'
          GROUP BY baseline.timesheet_id
        ), timesheet_authority AS (
          SELECT sealed.timesheet_id,
            (jsonb_agg(DISTINCT sealed.source_pay_method ORDER BY sealed.source_pay_method)->>0)
              AS source_pay_method,
            MIN(sealed.target_pay_method) AS target_pay_method,
            MIN(sealed.umbrella_id::text)::uuid AS umbrella_id,
            bool_and(sealed.umbrella_enabled) AS umbrella_enabled,
            bool_and(sealed.umbrella_vat_chargeable) AS umbrella_vat_chargeable,
            ROUND(COALESCE(SUM(sealed.source_units)
              FILTER(WHERE sealed.component_kind='WORKED_TIME'),0),6) AS total_hours,
            ROUND(SUM(sealed.truth_ex_vat),2) AS total_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE ABS(sealed.truth_ex_vat)>0.005),0),2) AS total_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='DAY'),0),6)
              AS hours_day,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='NIGHT'),0),6)
              AS hours_night,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='SAT'),0),6)
              AS hours_sat,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='SUN'),0),6)
              AS hours_sun,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='BH'),0),6)
              AS hours_bh,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='DAY') AS pay_day,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='NIGHT') AS pay_night,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='SAT') AS pay_sat,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='SUN') AS pay_sun,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='BH') AS pay_bh,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='DAY') AS charge_day,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='NIGHT') AS charge_night,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='SAT') AS charge_sat,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='SUN') AS charge_sun,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='BH') AS charge_bh,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE'),0),2) AS expenses_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE'
                AND ABS(sealed.truth_ex_vat)>0.005),0),2) AS expenses_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='TRAVEL'),0),2)
              AS travel_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='TRAVEL'),0),2)
              AS travel_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='ACCOMMODATION'),0),2)
              AS accommodation_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='ACCOMMODATION'),0),2)
              AS accommodation_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='OTHER'),0),2)
              AS other_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='OTHER'),0),2)
              AS other_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='MILEAGE'),0),2)
              AS mileage_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='MILEAGE'),0),2)
              AS mileage_charge_ex_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed GROUP BY sealed.timesheet_id
        )
        UPDATE pg_temp.ts_baseline baseline
        SET ts_pay_method=authority.source_pay_method,
          cand_pay_method=authority.target_pay_method,
          cand_umbrella_id=authority.umbrella_id,
          umb_enabled=authority.umbrella_enabled,
          umb_vat_chargeable=authority.umbrella_vat_chargeable,
          base_json=jsonb_build_object(
            'baseline_source','SEALED_BUILD_FACTS',
            'active_settled_artifact_components',COALESCE(active.components_json,'[]'::jsonb),
            'active_settled_amount_ex_vat',COALESCE(active.amount_ex_vat,0),
            'active_settled_amount_inc_vat',COALESCE(active.amount_inc_vat,0),
            'segments','[]'::jsonb,
            'additional_pay_ex_vat',COALESCE(baseline_additional.additional_pay_ex_vat,0),
            'additional_charge_ex_vat',COALESCE(baseline_additional.additional_charge_ex_vat,0),
            'additional_units_json',COALESCE(baseline_additional.additional_units_json,'{}'::jsonb),
            'expenses',jsonb_build_object(
              'expenses_pay_ex_vat',COALESCE(baseline_expenses.expenses_pay_ex_vat,0),
              'expenses_charge_ex_vat',COALESCE(baseline_expenses.expenses_charge_ex_vat,0),
              'travel_pay_ex_vat',COALESCE(baseline_expenses.travel_pay_ex_vat,0),
              'travel_charge_ex_vat',COALESCE(baseline_expenses.travel_charge_ex_vat,0),
              'accommodation_pay_ex_vat',COALESCE(baseline_expenses.accommodation_pay_ex_vat,0),
              'accommodation_charge_ex_vat',COALESCE(baseline_expenses.accommodation_charge_ex_vat,0),
              'other_pay_ex_vat',COALESCE(baseline_expenses.other_pay_ex_vat,0),
              'other_charge_ex_vat',COALESCE(baseline_expenses.other_charge_ex_vat,0),
              'mileage_pay_ex_vat',COALESCE(baseline_expenses.mileage_pay_ex_vat,0),
              'mileage_charge_ex_vat',COALESCE(baseline_expenses.mileage_charge_ex_vat,0)),
            'adjustments',COALESCE(baseline_adjustments.adjustments_json,'[]'::jsonb)),
          active_settled_artifact_components_json=COALESCE(active.components_json,'[]'::jsonb),
          active_settled_artifact_component_count=COALESCE(active.component_count,0),
          active_settled_artifact_amount_ex_vat=COALESCE(active.amount_ex_vat,0),
          active_settled_artifact_amount_inc_vat=COALESCE(active.amount_inc_vat,0),
          has_active_settled_artifact_baseline=COALESCE(active.component_count,0)>0,
          bas_hours_day=0,bas_hours_night=0,bas_hours_sat=0,bas_hours_sun=0,bas_hours_bh=0,
          bas_pay_day=NULL,bas_pay_night=NULL,bas_pay_sat=NULL,bas_pay_sun=NULL,bas_pay_bh=NULL,
          bas_charge_day=NULL,bas_charge_night=NULL,bas_charge_sat=NULL,
          bas_charge_sun=NULL,bas_charge_bh=NULL,
          current_segments_json=COALESCE(segments.segments_json,'[]'::jsonb),
          current_adjustments_json=COALESCE(adjustments.adjustments_json,'[]'::jsonb),
          total_hours=authority.total_hours,total_pay_ex_vat=authority.total_pay_ex_vat,
          total_charge_ex_vat=authority.total_charge_ex_vat,
          hours_day=authority.hours_day,hours_night=authority.hours_night,
          hours_sat=authority.hours_sat,hours_sun=authority.hours_sun,hours_bh=authority.hours_bh,
          pay_day=authority.pay_day,pay_night=authority.pay_night,pay_sat=authority.pay_sat,
          pay_sun=authority.pay_sun,pay_bh=authority.pay_bh,
          charge_day=authority.charge_day,charge_night=authority.charge_night,
          charge_sat=authority.charge_sat,charge_sun=authority.charge_sun,
          charge_bh=authority.charge_bh,
          cur_hours_day=authority.hours_day,cur_hours_night=authority.hours_night,
          cur_hours_sat=authority.hours_sat,cur_hours_sun=authority.hours_sun,
          cur_hours_bh=authority.hours_bh,
          cur_pay_day=authority.pay_day,cur_pay_night=authority.pay_night,
          cur_pay_sat=authority.pay_sat,cur_pay_sun=authority.pay_sun,cur_pay_bh=authority.pay_bh,
          cur_charge_day=authority.charge_day,cur_charge_night=authority.charge_night,
          cur_charge_sat=authority.charge_sat,cur_charge_sun=authority.charge_sun,
          cur_charge_bh=authority.charge_bh,
          current_additional_units_json=COALESCE(additional.additional_json,'{}'::jsonb),
          current_additional_pay_ex_vat=COALESCE(additional.additional_pay_ex_vat,0),
          current_additional_charge_ex_vat=COALESCE(additional.additional_charge_ex_vat,0),
          current_expenses_pay_ex_vat=authority.expenses_pay_ex_vat,
          current_expenses_charge_ex_vat=authority.expenses_charge_ex_vat,
          current_travel_pay_ex_vat=authority.travel_pay_ex_vat,
          current_travel_charge_ex_vat=authority.travel_charge_ex_vat,
          current_accommodation_pay_ex_vat=authority.accommodation_pay_ex_vat,
          current_accommodation_charge_ex_vat=authority.accommodation_charge_ex_vat,
          current_other_pay_ex_vat=authority.other_pay_ex_vat,
          current_other_charge_ex_vat=authority.other_charge_ex_vat,
          current_mileage_pay_ex_vat=authority.mileage_pay_ex_vat,
          current_mileage_charge_ex_vat=authority.mileage_charge_ex_vat
        FROM timesheet_authority authority
        LEFT JOIN segments_by_timesheet segments USING(timesheet_id)
        LEFT JOIN additional_by_timesheet additional USING(timesheet_id)
        LEFT JOIN adjustments_by_timesheet adjustments USING(timesheet_id)
        LEFT JOIN baseline_only_active_artifacts active USING(timesheet_id)
        LEFT JOIN baseline_only_expenses baseline_expenses USING(timesheet_id)
        LEFT JOIN baseline_only_additional baseline_additional USING(timesheet_id)
        LEFT JOIN baseline_only_adjustments baseline_adjustments USING(timesheet_id)
        WHERE baseline.candidate_id=v_preview_candidate_loop_id
          AND baseline.timesheet_id=authority.timesheet_id;

        IF v_execution_profile_version=2 THEN
          v_phase_started_at := clock_timestamp();
          v_preview_canonical_result_json := public.pay_preview_candidate_build_canonical_lines(
            p_context_json => v_preview_context_json,
            p_candidate_id => v_preview_candidate_loop_id
          );
          v_preview_canonical_ms := v_preview_canonical_ms
            + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
        END IF;
      END IF;

      v_phase_started_at := clock_timestamp();
      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );
      v_preview_summary_ms := v_preview_summary_ms
        + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

      IF jsonb_typeof(COALESCE(v_preview_baseline_json, '{}'::jsonb)) <> 'object' THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND COALESCE(v_authoritative_negative_component_count, 0) > 0
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NULL THEN
        PERFORM public.pay_preview_candidate_build_case_component_rows(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope,false) THEN
        DELETE FROM pg_temp.tmp_sync_raw_preview_physical_components
        WHERE candidate_id=v_preview_candidate_loop_id;
        DELETE FROM pg_temp.tmp_sync_sealed_missing_preview_components
        WHERE candidate_id=v_preview_candidate_loop_id;

        IF to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
          INSERT INTO pg_temp.tmp_sync_raw_preview_physical_components(
            candidate_id,timesheet_id,component_ordinality,physical_bucket_key,
            component_json
          )
          SELECT raw_case.candidate_id,raw_case.timesheet_id,
            raw_component.ordinality::bigint,
            concat_ws('|','RATE_BUCKET_V1',raw_case.timesheet_id::text,
              NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
              UPPER(NULLIF(BTRIM(raw_component.value->>'component_key_type'),'')),
              NULLIF(BTRIM(raw_component.value->>'component_key_value'),''),
              CASE
                WHEN UPPER(BTRIM(COALESCE(
                    raw_component.value#>>'{source_basis_json,component_fallback}','')))
                      ='WORKED_TIME_AMOUNT'
                  THEN 'worked-time-residual:'
                    ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
                    ||BTRIM(raw_component.value->>'component_key_value')
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))
                    IN ('TS_DAY','TS_TOTAL')
                  THEN COALESCE(
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
                  THEN 'additional:'
                    ||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
                  THEN 'expense:'
                    ||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
                  THEN 'adjustment:'
                    ||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
              END,
              UPPER(BTRIM(COALESCE(
                CASE WHEN UPPER(BTRIM(COALESCE(
                    raw_component.value#>>'{source_basis_json,component_fallback}','')))
                      ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
                NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
                CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
                  WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
                  WHEN 'EXPENSE_CODE' THEN 'FIXED'
                  WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
                END)))) AS physical_bucket_key,
            raw_component.value
          FROM pg_temp.timesheet_case_rollup raw_case
          CROSS JOIN LATERAL jsonb_array_elements(CASE
            WHEN jsonb_typeof(raw_case.case_components_json)='array'
              THEN raw_case.case_components_json ELSE '[]'::jsonb END)
            WITH ORDINALITY raw_component(value,ordinality)
          WHERE raw_case.candidate_id=v_preview_candidate_loop_id;
        END IF;

        IF EXISTS(
          SELECT 1
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          WHERE sealed.candidate_id=v_preview_candidate_loop_id
            AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
            AND sealed.evidence_json#>>'{source_payload,source_kind}'
              IN ('SEGMENT','SEALED_BASELINE_COMPONENT','WORKED_TIME_RESIDUAL')
            AND jsonb_typeof(CASE
              WHEN sealed.evidence_json#>>'{source_payload,source_kind}'='SEGMENT'
                THEN sealed.evidence_json#>'{source_payload,segment}'
              ELSE sealed.evidence_json#>'{source_payload,source_value}' END)<>'object'
        ) THEN
          RAISE EXCEPTION 'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE',
              'candidate_id',v_preview_candidate_loop_id::text,
              'message','A sealed builder component has no complete frozen source basis.'
            )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_sealed_missing_preview_components(
          candidate_id,timesheet_id,economic_key_type,economic_key_value,
          bucket_sort_ordinal,physical_bucket_key,component_json
        )
        SELECT sealed.candidate_id,sealed.timesheet_id,sealed.economic_key_type,
          sealed.economic_key_value,sealed.bucket_sort_ordinal,sealed.physical_bucket_key,
          jsonb_strip_nulls(jsonb_build_object(
            'source_family_key',sealed.source_family_key,
            'component_key_type',sealed.economic_key_type,
            'component_key_value',sealed.economic_key_value,
            'component_kind',sealed.component_kind,
            'component_member_identity',sealed.component_member_identity,
            'classification',CASE WHEN sealed.economic_key_type='EXPENSE_CODE'
              THEN 'REIMBURSEMENT_GROSS_FIXED' ELSE 'TAXABLE_CHANNEL_SENSITIVE' END,
            'source_pay_method',sealed.source_pay_method,
            'current_target_pay_method',sealed.target_pay_method,
            'source_basis_json',
              bridge.source_basis_json
              ||jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id',sealed.timesheet_id::text,
                'source_family_key',sealed.source_family_key,
                'component_key_type',sealed.economic_key_type,
                'component_key_value',sealed.economic_key_value,
                'segment_id',sealed.segment_id,
                'segment_key',COALESCE(sealed.segment_key,sealed.segment_id),
                'segment_stable_key',sealed.segment_stable_key,
                'work_date',COALESCE(
                  bridge.source_basis_json->>'work_date',
                  bridge.source_basis_json->>'date'),
                'ref_num',bridge.source_basis_json->>'ref_num',
                'additional_code',CASE WHEN sealed.economic_key_type='ADDITIONAL_CODE'
                  THEN UPPER(sealed.economic_key_value) END,
                'expense_code',CASE WHEN sealed.economic_key_type='EXPENSE_CODE'
                  THEN UPPER(sealed.economic_key_value) END,
                'adjustment_id',CASE WHEN sealed.economic_key_type='ADJUSTMENT_CODE'
                  THEN sealed.economic_key_value END,
                'bucket_code',sealed.bucket_code,
                'source_pay_method',sealed.source_pay_method)),
            'source_units',sealed.source_units,
            'source_rate',sealed.source_rate,
            'source_charge_rate',sealed.source_charge_rate,
            'source_pay_ex_vat',sealed.outstanding_ex_vat,
            'source_charge_ex_vat',sealed.source_charge_ex_vat,
            'component_amount_ex_vat',sealed.outstanding_ex_vat,
            'authoritative_truth_ex_vat',sealed.truth_ex_vat,
            'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
            'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
            'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
            'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
            'physical_bucket_key',sealed.physical_bucket_key,
            'physical_bucket_digest',sealed.physical_bucket_digest,
            'sealed_evidence_digest',sealed.sealed_evidence_digest,
            'financial_revision_digest',sealed.financial_revision_digest,
            'target_authority_digest',sealed.target_authority_digest,
            'conversion_context_digest',sealed.conversion_context_digest
          )) AS component_json
        FROM pg_temp.tmp_sync_sealed_rate_projection sealed
        CROSS JOIN LATERAL (
          SELECT CASE
            WHEN sealed.evidence_json#>>'{source_payload,source_kind}'='SEGMENT'
              THEN sealed.evidence_json#>'{source_payload,segment}'
            ELSE sealed.evidence_json#>'{source_payload,source_value}'
          END AS source_basis_json
        ) bridge
        WHERE sealed.candidate_id=v_preview_candidate_loop_id
          AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
          AND sealed.evidence_json#>>'{source_payload,source_kind}'
            IN ('SEGMENT','SEALED_BASELINE_COMPONENT','WORKED_TIME_RESIDUAL')
          AND jsonb_typeof(bridge.source_basis_json)='object'
          AND NOT EXISTS(
            SELECT 1
            FROM pg_temp.tmp_sync_raw_preview_physical_components raw_component
            WHERE raw_component.candidate_id=sealed.candidate_id
              AND raw_component.timesheet_id=sealed.timesheet_id
              AND raw_component.physical_bucket_key=sealed.physical_bucket_key
          );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
        IF EXISTS (
          WITH correction_residuals AS (
            SELECT residual.value AS residual_json
            FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
              v_workbench_session_id_text::uuid,
              v_preview_candidate_loop_id,
              NULL::uuid,
              'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA'
            )) AS residual(value)
            WHERE COALESCE((residual.value->>'draftable')::boolean, false)
          ), correction_member_roots AS (
            SELECT DISTINCT
              member_id.value::uuid AS member_timesheet_id,
              (residual.residual_json->>'root_timesheet_id')::uuid AS root_timesheet_id
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements_text(
              COALESCE(residual.residual_json->'member_timesheet_ids', '[]'::jsonb)
            ) AS member_id(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND member_id.value
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          ), correction_component_totals AS (
            SELECT
              (residual.residual_json->>'root_timesheet_id')::uuid AS timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              1::integer AS preview_component_count,
              ROUND(
                (component.value->>'truth_ex_vat')::numeric,
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements(
              COALESCE(residual.residual_json->'components', '[]'::jsonb)
            ) AS component(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND COALESCE(component.value->>'truth_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND ROUND(
                    COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0),
                    2
                  ) < 0
          ), raw_preview_component_totals AS (
            SELECT
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(raw_component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS preview_component_count,
              ROUND(
                SUM((raw_component.value->>'component_amount_ex_vat')::numeric),
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM pg_temp.timesheet_case_rollup AS raw_case
            CROSS JOIN LATERAL jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                  THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS raw_component(value)
            WHERE raw_case.candidate_id = v_preview_candidate_loop_id
              AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
              AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
              AND NOT EXISTS (
                SELECT 1
                FROM correction_member_roots AS correction_member
                WHERE correction_member.member_timesheet_id = raw_case.timesheet_id
              )
              AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
          ), preview_component_totals AS (
            SELECT * FROM correction_component_totals
            UNION ALL
            SELECT * FROM raw_preview_component_totals
          ), sealed_baseline_only_keys AS (
            SELECT sealed.timesheet_id,sealed.economic_key_type AS key_type,
              sealed.economic_key_value AS key_value
            FROM pg_temp.tmp_sync_sealed_rate_projection sealed
            GROUP BY sealed.timesheet_id,sealed.economic_key_type,
              sealed.economic_key_value
            HAVING COUNT(*)=COUNT(*) FILTER(WHERE
                sealed.evidence_json#>>'{source_payload,source_kind}'=
                  'SEALED_BASELINE_COMPONENT')
              AND COUNT(*) FILTER(WHERE
                sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true')>0
              AND ROUND(SUM(sealed.truth_ex_vat),2)=0
              AND ROUND(SUM(sealed.outstanding_ex_vat),2)<0
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN preview_component_totals AS preview_total
            ON preview_total.timesheet_id = authoritative_component.timesheet_id
           AND preview_total.key_type = authoritative_component.key_type
           AND preview_total.key_value = authoritative_component.key_value
          LEFT JOIN sealed_baseline_only_keys sealed_baseline
            ON sealed_baseline.timesheet_id=authoritative_component.timesheet_id
           AND sealed_baseline.key_type=authoritative_component.key_type
           AND sealed_baseline.key_value=authoritative_component.key_value
          WHERE (
                  (
                    preview_total.preview_component_count IS NULL
                    AND ABS(ROUND(authoritative_component.truth_ex_vat, 2)) > 0.01
                  )
                  OR (
                    preview_total.preview_component_count IS NOT NULL
                    AND ABS(ROUND(
                      preview_total.preview_truth_ex_vat
                      - authoritative_component.truth_ex_vat,
                      2
                    )) > 0.01
                  )
                )
            AND sealed_baseline.timesheet_id IS NULL
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'authoritative_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_component.timesheet_id::text,
                        'key_type', bounded_component.key_type,
                        'key_value', bounded_component.key_value,
                        'truth_ex_vat', bounded_component.truth_ex_vat,
                        'outstanding_ex_vat', bounded_component.outstanding_ex_vat
                      ) ORDER BY bounded_component.timesheet_id, bounded_component.key_type, bounded_component.key_value), '[]'::jsonb)
                      FROM (
                        SELECT *
                        FROM pg_temp.tmp_sync_authoritative_negative_components
                        ORDER BY timesheet_id, key_type, key_value
                        LIMIT 10
                      ) AS bounded_component
                    ),
                    'correction_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_correction.root_timesheet_id,
                        'key_type', bounded_correction.key_type,
                        'key_value', bounded_correction.key_value,
                        'truth_ex_vat', bounded_correction.truth_ex_vat,
                        'outstanding_ex_vat', bounded_correction.outstanding_ex_vat
                      ) ORDER BY bounded_correction.root_timesheet_id, bounded_correction.key_type, bounded_correction.key_value), '[]'::jsonb)
                      FROM (
                        SELECT
                          residual.value->>'root_timesheet_id' AS root_timesheet_id,
                          UPPER(BTRIM(component.value->>'component_key_type')) AS key_type,
                          BTRIM(component.value->>'component_key_value') AS key_value,
                          component.value->>'truth_ex_vat' AS truth_ex_vat,
                          component.value->>'target_outstanding_ex_vat' AS outstanding_ex_vat
                        FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
                          v_workbench_session_id_text::uuid,
                          v_preview_candidate_loop_id,
                          NULL::uuid,
                          'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA_DIAGNOSTIC'
                        )) AS residual(value)
                        CROSS JOIN LATERAL jsonb_array_elements(
                          COALESCE(residual.value->'components', '[]'::jsonb)
                        ) AS component(value)
                        WHERE COALESCE((residual.value->>'draftable')::boolean, false)
                          AND ROUND(COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0), 2) < 0
                        ORDER BY residual.value->>'root_timesheet_id',
                                 UPPER(BTRIM(component.value->>'component_key_type')),
                                 BTRIM(component.value->>'component_key_value')
                        LIMIT 10
                      ) AS bounded_correction
                    ),
                    'message', 'Canonical negative component keys were not represented by preview metadata whose current component totals match authoritative live truth.'
                  )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows (
          candidate_id,
          timesheet_id,
          client_id,
          candidate_pay_method,
          case_is_blocked,
          case_components_json
        )
        SELECT
          raw_case.candidate_id,
          raw_case.timesheet_id,
          raw_case.client_id,
          (SELECT MIN(sealed.target_pay_method)
            FROM pg_temp.tmp_sync_sealed_rate_projection sealed
            WHERE sealed.timesheet_id=raw_case.timesheet_id),
          COALESCE(raw_case.is_blocked, false),
          COALESCE((
            SELECT jsonb_agg(
              raw_component.value
              || jsonb_build_object(
                'component_amount_ex_vat',sealed.outstanding_ex_vat,
                'authoritative_truth_ex_vat',sealed.truth_ex_vat,
                'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
                'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
                'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
                'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
                'physical_bucket_key',sealed.physical_bucket_key,
                'physical_bucket_digest',sealed.physical_bucket_digest,
                'sealed_evidence_digest',sealed.sealed_evidence_digest
              )
              ORDER BY sealed.economic_key_type,sealed.economic_key_value,
                sealed.bucket_sort_ordinal,sealed.physical_bucket_key
            )
            FROM jsonb_array_elements(CASE
              WHEN jsonb_typeof(raw_case.case_components_json)='array'
                THEN raw_case.case_components_json ELSE '[]'::jsonb END)
              WITH ORDINALITY raw_component(value,ordinality)
            JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
              ON sealed.timesheet_id=raw_case.timesheet_id
             AND sealed.economic_key_type=UPPER(BTRIM(raw_component.value->>'component_key_type'))
             AND sealed.economic_key_value=BTRIM(raw_component.value->>'component_key_value')
             AND sealed.physical_bucket_key=concat_ws('|','RATE_BUCKET_V1',
               raw_case.timesheet_id::text,
               NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
               UPPER(BTRIM(raw_component.value->>'component_key_type')),
               BTRIM(raw_component.value->>'component_key_value'),
               CASE
                 WHEN UPPER(BTRIM(COALESCE(
                     raw_component.value#>>'{source_basis_json,component_fallback}','')))
                       ='WORKED_TIME_AMOUNT'
                   THEN 'worked-time-residual:'
                     ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
                     ||BTRIM(raw_component.value->>'component_key_value')
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
                   THEN COALESCE(NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
                   THEN 'additional:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
                   THEN 'expense:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
                   THEN 'adjustment:'||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
               END,
               UPPER(BTRIM(COALESCE(
                 CASE WHEN UPPER(BTRIM(COALESCE(
                     raw_component.value#>>'{source_basis_json,component_fallback}','')))
                       ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
                 NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
                 CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
                   WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
                   WHEN 'EXPENSE_CODE' THEN 'FIXED'
                   WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
                 END))))
            JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
              ON negative_component.timesheet_id=sealed.timesheet_id
             AND negative_component.key_type=sealed.economic_key_type
             AND negative_component.key_value=sealed.economic_key_value
          ),'[]'::jsonb)
        FROM pg_temp.timesheet_case_rollup AS raw_case
        WHERE raw_case.candidate_id = v_preview_candidate_loop_id
          AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
          AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
          AND NOT (
            raw_case.timesheet_id
              = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
          )
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
            WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
          )
        ON CONFLICT (candidate_id, timesheet_id) DO UPDATE
        SET
          client_id = EXCLUDED.client_id,
          candidate_pay_method = EXCLUDED.candidate_pay_method,
          case_is_blocked = EXCLUDED.case_is_blocked,
          case_components_json = EXCLUDED.case_components_json;

        WITH missing_components AS (
          SELECT missing.candidate_id,missing.timesheet_id,
            jsonb_agg(missing.component_json ORDER BY missing.economic_key_type,
              missing.economic_key_value,missing.bucket_sort_ordinal,
              missing.physical_bucket_key) AS components_json
          FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
          JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
            ON negative_component.timesheet_id=missing.timesheet_id
           AND negative_component.key_type=missing.economic_key_type
           AND negative_component.key_value=missing.economic_key_value
          WHERE missing.candidate_id=v_preview_candidate_loop_id
          GROUP BY missing.candidate_id,missing.timesheet_id
        )
        UPDATE pg_temp.tmp_sync_raw_negative_timesheet_rows raw_row
        SET case_components_json=raw_row.case_components_json||missing.components_json
        FROM missing_components missing
        WHERE raw_row.candidate_id=missing.candidate_id
          AND raw_row.timesheet_id=missing.timesheet_id;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows(
          candidate_id,timesheet_id,client_id,candidate_pay_method,
          case_is_blocked,case_components_json
        )
        SELECT missing.candidate_id,missing.timesheet_id,baseline.client_id,
          (SELECT MIN(sealed.target_pay_method)
           FROM pg_temp.tmp_sync_sealed_rate_projection sealed
           WHERE sealed.timesheet_id=missing.timesheet_id),
          false,missing.components_json
        FROM (
          SELECT sealed_missing.candidate_id,sealed_missing.timesheet_id,
            jsonb_agg(sealed_missing.component_json ORDER BY
              sealed_missing.economic_key_type,sealed_missing.economic_key_value,
              sealed_missing.bucket_sort_ordinal,sealed_missing.physical_bucket_key)
              AS components_json
          FROM pg_temp.tmp_sync_sealed_missing_preview_components sealed_missing
          JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
            ON negative_component.timesheet_id=sealed_missing.timesheet_id
           AND negative_component.key_type=sealed_missing.economic_key_type
           AND negative_component.key_value=sealed_missing.economic_key_value
          WHERE sealed_missing.candidate_id=v_preview_candidate_loop_id
          GROUP BY sealed_missing.candidate_id,sealed_missing.timesheet_id
        ) missing
        JOIN pg_temp.ts_baseline baseline
          ON baseline.candidate_id=missing.candidate_id
         AND baseline.timesheet_id=missing.timesheet_id
        WHERE NOT EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_raw_negative_timesheet_rows existing_row
          WHERE existing_row.candidate_id=missing.candidate_id
            AND existing_row.timesheet_id=missing.timesheet_id
        );

        IF EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_authoritative_negative_components negative_component
          WHERE NOT (negative_component.timesheet_id
              =ANY(COALESCE(v_resolution_pending_root_ids,ARRAY[]::uuid[])))
            AND NOT (negative_component.timesheet_id
              =ANY(COALESCE(v_resolution_pending_member_ids,ARRAY[]::uuid[])))
            AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_raw_negative_timesheet_rows raw_row
              WHERE raw_row.candidate_id=v_preview_candidate_loop_id
                AND raw_row.timesheet_id=negative_component.timesheet_id)
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING',
              'candidate_id',v_preview_candidate_loop_id::text)::text;
        END IF;

        IF EXISTS (
          WITH allocated_component_totals AS (
            SELECT
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS allocated_component_count,
              ROUND(SUM((component.value->>'component_amount_ex_vat')::numeric), 2)::numeric(12,2) AS allocated_outstanding_ex_vat
            FROM pg_temp.tmp_sync_raw_negative_timesheet_rows AS raw_timesheet
            CROSS JOIN LATERAL jsonb_array_elements(raw_timesheet.case_components_json) AS component(value)
            WHERE raw_timesheet.candidate_id = v_preview_candidate_loop_id
              AND COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(component.value->>'component_key_value', ''))
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN allocated_component_totals AS allocated_total
            ON allocated_total.timesheet_id = authoritative_component.timesheet_id
           AND allocated_total.key_type = authoritative_component.key_type
           AND allocated_total.key_value = authoritative_component.key_value
          WHERE (
                  allocated_total.allocated_component_count IS NULL
                  OR (
                  ABS(ROUND(
                    COALESCE(allocated_total.allocated_outstanding_ex_vat, 0)
                    - authoritative_component.outstanding_ex_vat,
                    2
                  )) > 0.01
                )
                )
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'message', 'Canonical negative components were not represented exactly by the validated pre-draft component allocations.'
                  )::text;
        END IF;
      END IF;

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope,
                  'baseline_candidate_id', NULLIF(BTRIM(COALESCE(
                    v_preview_candidate_row_json->>'candidate_id',
                    v_preview_baseline_json->>'candidate_id',
                    ''
                  )), '')
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) IS DISTINCT FROM v_scope THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'requested_pay_channel_scope', v_scope,
                  'current_pay_method', NULLIF(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', '')), '')
                )::text;
      END IF;

      v_preview_candidate_row_json := v_preview_candidate_row_json
        || jsonb_build_object(
          'candidate_id', v_preview_candidate_loop_id::text,
          'itemisation', CASE
            WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
            WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        );

      INSERT INTO pg_temp.tmp_sync_preview_candidates (
        candidate_id,
        candidate_json
      )
      VALUES (
        v_preview_candidate_loop_id,
        v_preview_candidate_row_json
      )
      ON CONFLICT (candidate_id) DO UPDATE
      SET candidate_json = EXCLUDED.candidate_json;
    END LOOP;
  ELSE
    v_preview_scope_context_json := public.pay_preview_build_context(
      p_pay_date => p_pay_date,
      p_week_ending_cutoff => p_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => p_client_filter_single,
      p_preview_decisions_json => v_preview_decisions_json
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', 100
        )
    );

    v_preview_scope_candidate_ids_json := CASE
      WHEN jsonb_typeof(v_preview_scope_context_json->'candidate_ids') = 'array'
        THEN COALESCE(v_preview_scope_context_json->'candidate_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    IF LOWER(BTRIM(COALESCE(v_preview_scope_context_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS',
                'message', 'The bounded candidate page is incomplete. Supply explicit candidate_ids rather than accepting a partial all-candidate reconciliation.',
                'pay_channel_scope', v_scope,
                'page_count', COALESCE(v_preview_scope_context_json->>'page_count', '0'),
                'limit', COALESCE(v_preview_scope_context_json->>'limit', '100'),
                'next_cursor_json', COALESCE(v_preview_scope_context_json->'next_cursor_json', 'null'::jsonb)
              )::text;
    END IF;

    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT scoped_candidate.value::uuid
      FROM jsonb_array_elements_text(COALESCE(v_preview_scope_candidate_ids_json, '[]'::jsonb)) AS scoped_candidate(value)
      WHERE scoped_candidate.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY scoped_candidate.value::uuid
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      );

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) = v_scope THEN
        v_preview_candidate_row_json := v_preview_candidate_row_json
          || jsonb_build_object(
            'candidate_id', v_preview_candidate_loop_id::text,
            'itemisation', CASE
              WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
              WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          );

        INSERT INTO pg_temp.tmp_sync_preview_candidates (
          candidate_id,
          candidate_json
        )
        VALUES (
          v_preview_candidate_loop_id,
          v_preview_candidate_row_json
        )
        ON CONFLICT (candidate_id) DO UPDATE
        SET candidate_json = EXCLUDED.candidate_json;
      END IF;
    END LOOP;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_preview_candidate_count
  FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate;

  WITH requested_candidates AS (
    SELECT DISTINCT requested_candidate.candidate_id
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NOT NULL
  ), missing_candidates AS (
    SELECT requested_candidates.candidate_id
    FROM requested_candidates
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate
      WHERE preview_candidate.candidate_id = requested_candidates.candidate_id
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(missing_candidates.candidate_id::text ORDER BY missing_candidates.candidate_id), '[]'::jsonb)
  INTO v_missing_candidate_count,
       v_missing_candidate_ids_json
  FROM missing_candidates;

  IF COALESCE(v_missing_candidate_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
              'pay_channel_scope', v_scope,
              'requested_candidate_count', v_requested_candidate_count,
              'preview_candidate_count', v_preview_candidate_count,
              'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb)
            )::text;
  END IF;

  v_preview_workspace_ms := COALESCE(v_preview_collect_ms, 0)
    + COALESCE(v_preview_canonical_ms, 0)
    + COALESCE(v_preview_summary_ms, 0);
  v_phase_started_at := clock_timestamp();

  insert into pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id,
    timesheet_id,
    client_id,
    linked_shift_date,
    corrected_amount_ex,
    baseline_signature,
    candidate_pay_method,
    case_is_blocked,
    needs_lifecycle_tracking,
    overpayment_amount_ex,
    underpayment_amount_ex,
    desired_case_type,
    desired_advance_kind,
    desired_reason,
    source_original_paid_amount,
    source_corrected_paid_amount,
    components_sync_json
  )
  with candidate_rows as (
    select
      preview_candidate.candidate_id,
      upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) as candidate_pay_method,
      case
        when jsonb_typeof(preview_candidate.candidate_json->'itemisation') = 'array'
          then coalesce(preview_candidate.candidate_json->'itemisation', '[]'::jsonb)
        else '[]'::jsonb
      end as itemisation_json
    from pg_temp.tmp_sync_preview_candidates as preview_candidate
    where upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) = v_scope
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or preview_candidate.candidate_id = any(p_candidate_ids)
      )
  ),
  itemisation_timesheet_rows as (
    select cr.candidate_id,cr.candidate_pay_method,itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id','')),'')::uuid as client_id,
      round(coalesce(nullif(itm.value->>'amount_ex_vat','')::numeric,0),2)::numeric(12,2) as corrected_amount_ex,
      coalesce(itm.value->>'case_is_blocked','false')::boolean as case_is_blocked,
      coalesce(itm.value->'case_components','[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json,'[]'::jsonb)) itm(value)
    where coalesce(itm.value->>'line_type','')='TIMESHEET_PAYMENT'
      and nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'') is not null
      and (coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid=any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null)
      and not (coalesce(array_length(p_exclude_timesheet_ids,1),0)>0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid=any(p_exclude_timesheet_ids))
  ),
  authoritative_timesheet_rows AS (
    SELECT v_authoritative_candidate_id AS candidate_id,
      (SELECT MIN(sealed.target_pay_method)
       FROM pg_temp.tmp_sync_sealed_rate_projection sealed) AS candidate_pay_method,
      jsonb_build_object('line_type','TIMESHEET_PAYMENT','timesheet_id',scope_row.timesheet_id::text,
        'client_id',CASE WHEN metadata.client_id IS NULL THEN NULL ELSE metadata.client_id::text END,
        'amount_ex_vat',ROUND(COALESCE(economic_total.truth_ex_vat,0),2),
        'case_is_blocked',COALESCE(metadata.case_is_blocked,false),
        'case_components',COALESCE(physical_components.case_components_json,'[]'::jsonb)
          ||COALESCE(missing_physical_components.case_components_json,'[]'::jsonb),
        'source_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text) AS item_json,
      scope_row.timesheet_id,metadata.client_id,
      ROUND(COALESCE(economic_total.truth_ex_vat,0),2)::numeric(12,2) AS corrected_amount_ex,
      COALESCE(metadata.case_is_blocked,false) AS case_is_blocked,
      COALESCE(physical_components.case_components_json,'[]'::jsonb)
        ||COALESCE(missing_physical_components.case_components_json,'[]'::jsonb)
        AS case_components_json
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL (
      SELECT COALESCE(preview_row.client_id,current_financial.client_id) AS client_id,
        COALESCE(preview_row.case_is_blocked,false) AS case_is_blocked
      FROM (SELECT 1) seed
      LEFT JOIN LATERAL (
        SELECT item.client_id,item.case_is_blocked
        FROM itemisation_timesheet_rows item WHERE item.timesheet_id=scope_row.timesheet_id LIMIT 1
      ) preview_row ON true
      LEFT JOIN LATERAL (
        SELECT financial.client_id FROM public.timesheets_financials financial
        WHERE financial.timesheet_id=scope_row.timesheet_id AND financial.is_current
          AND financial.candidate_id=v_authoritative_candidate_id
        ORDER BY financial.computed_at_utc DESC NULLS LAST,financial.id DESC LIMIT 1
      ) current_financial ON true
    ) metadata ON true
    LEFT JOIN LATERAL (
      SELECT ROUND(COALESCE(SUM(component.truth_ex_vat),0),2) AS truth_ex_vat
      FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=scope_row.timesheet_id
    ) economic_total ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(jsonb_agg(
        raw_component.value||jsonb_build_object(
          'component_amount_ex_vat',sealed.outstanding_ex_vat,
          'authoritative_truth_ex_vat',sealed.truth_ex_vat,
          'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
          'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
          'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
          'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
          'physical_bucket_key',sealed.physical_bucket_key,
           'physical_bucket_digest',sealed.physical_bucket_digest,
           'sealed_evidence_digest',sealed.sealed_evidence_digest,
           'financial_revision_digest',sealed.financial_revision_digest,
           'target_authority_digest',sealed.target_authority_digest,
           'conversion_context_digest',sealed.conversion_context_digest,
           'source_pay_method',sealed.source_pay_method,
           'current_target_pay_method',sealed.target_pay_method,
           'source_basis_json',(CASE
             WHEN jsonb_typeof(raw_component.value->'source_basis_json')='object'
               THEN raw_component.value->'source_basis_json'
             ELSE '{}'::jsonb END)||jsonb_build_object(
               'source_pay_method',sealed.source_pay_method))
        ORDER BY raw_component.ordinality),'[]'::jsonb) AS case_components_json
      FROM pg_temp.timesheet_case_rollup raw_case
      CROSS JOIN LATERAL jsonb_array_elements(CASE
        WHEN jsonb_typeof(raw_case.case_components_json)='array'
          THEN raw_case.case_components_json ELSE '[]'::jsonb END)
        WITH ORDINALITY raw_component(value,ordinality)
      JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
        ON sealed.timesheet_id=raw_case.timesheet_id
       AND sealed.economic_key_type=UPPER(BTRIM(raw_component.value->>'component_key_type'))
       AND sealed.economic_key_value=BTRIM(raw_component.value->>'component_key_value')
       AND sealed.physical_bucket_key=concat_ws('|','RATE_BUCKET_V1',
         raw_case.timesheet_id::text,
         NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
         UPPER(BTRIM(raw_component.value->>'component_key_type')),
         BTRIM(raw_component.value->>'component_key_value'),
         CASE
           WHEN UPPER(BTRIM(COALESCE(
               raw_component.value#>>'{source_basis_json,component_fallback}','')))
                 ='WORKED_TIME_AMOUNT'
             THEN 'worked-time-residual:'
               ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
               ||BTRIM(raw_component.value->>'component_key_value')
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
             THEN COALESCE(NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
             THEN 'additional:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
             THEN 'expense:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
             THEN 'adjustment:'||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
         END,
         UPPER(BTRIM(COALESCE(
           CASE WHEN UPPER(BTRIM(COALESCE(
               raw_component.value#>>'{source_basis_json,component_fallback}','')))
                 ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
           NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
           CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
             WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
             WHEN 'EXPENSE_CODE' THEN 'FIXED'
              WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
            END))))
      WHERE raw_case.candidate_id=v_authoritative_candidate_id
        AND raw_case.timesheet_id=scope_row.timesheet_id
    ) physical_components ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(jsonb_agg(missing.component_json ORDER BY
        missing.economic_key_type,missing.economic_key_value,
        missing.bucket_sort_ordinal,missing.physical_bucket_key),'[]'::jsonb)
        AS case_components_json
      FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
      WHERE missing.candidate_id=v_authoritative_candidate_id
        AND missing.timesheet_id=scope_row.timesheet_id
    ) missing_physical_components ON true
    WHERE scope_row.build_id=p_build_id
      AND (coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
        OR scope_row.timesheet_id=ANY(p_force_include_timesheet_ids)
        OR p_force_include_timesheet_ids IS NULL)
      AND NOT (coalesce(array_length(p_exclude_timesheet_ids,1),0)>0
        AND scope_row.timesheet_id=ANY(p_exclude_timesheet_ids))
  ),
  timesheet_item_rows AS (
    SELECT item.candidate_id,item.candidate_pay_method,item.item_json,item.timesheet_id,item.client_id,
      item.corrected_amount_ex,item.case_is_blocked,item.case_components_json
    FROM authoritative_timesheet_rows item
    WHERE COALESCE(v_authoritative_timesheet_scope,false)
    UNION ALL
    SELECT item.candidate_id,item.candidate_pay_method,item.item_json,item.timesheet_id,item.client_id,
      item.corrected_amount_ex,item.case_is_blocked,item.case_components_json
    FROM itemisation_timesheet_rows item
    WHERE NOT COALESCE(v_authoritative_timesheet_scope,false)
  ),
  active_settled_basis AS (
    SELECT
      distinct_timesheet_rows.timesheet_id,
      active_components.active_settled_component_count,
      active_components.active_settled_amount_ex,
      active_components.active_settled_signature
    FROM (
      SELECT DISTINCT timesheet_item_rows.timesheet_id
      FROM timesheet_item_rows
      WHERE timesheet_item_rows.timesheet_id IS NOT NULL
    ) AS distinct_timesheet_rows
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS active_settled_component_count,
        round(COALESCE(sum(COALESCE(active_settled_rows.amount_ex_vat, 0)), 0), 2)::numeric(12,2) AS active_settled_amount_ex,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_rows.key_type,
            'key_value', active_settled_rows.key_value,
            'amount_ex_vat', round(COALESCE(active_settled_rows.amount_ex_vat, 0), 2),
            'amount_inc_vat', round(COALESCE(active_settled_rows.amount_inc_vat, 0), 2)
          )
          ORDER BY active_settled_rows.key_type, active_settled_rows.key_value
        )::text, '[]')) AS active_settled_signature
      FROM (
        SELECT fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          fact.amount_ex_vat,fact.amount_inc_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=p_build_id AND fact.timesheet_id=distinct_timesheet_rows.timesheet_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      ) AS active_settled_rows
    ) AS active_components
      ON true
  ),
  timesheet_item_with_baseline as (
    select
      tir.candidate_id,
      tir.timesheet_id,
      tir.client_id,
      coalesce(ts.worked_start_iso::date, ts.scheduled_start_iso::date, ts.week_ending_date) as linked_shift_date,
      tir.corrected_amount_ex,
      case
        when COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          then active_settled_basis.active_settled_signature
        else coalesce(
          tps.last_settled_signature,
          md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
        )
      end as baseline_signature,
      tir.candidate_pay_method,
      tir.case_is_blocked,
      tir.case_components_json
    from timesheet_item_rows tir
    join public.timesheets ts
      on ts.timesheet_id = tir.timesheet_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tir.timesheet_id
    left join active_settled_basis
      on active_settled_basis.timesheet_id = tir.timesheet_id
  ),
  timesheet_exploded_components as (
    select
      tiwb.candidate_id,
      tiwb.timesheet_id,
      tiwb.client_id,
      tiwb.linked_shift_date,
      tiwb.corrected_amount_ex,
      tiwb.baseline_signature,
      tiwb.candidate_pay_method,
      tiwb.case_is_blocked,
      comp.value as component_json,
      comp.ordinality::integer as component_order,
      UPPER(NULLIF(BTRIM(COALESCE(comp.value->>'component_key_type', '')), '')) AS component_key_type,
      NULLIF(BTRIM(COALESCE(comp.value->>'component_key_value', '')), '') AS component_key_value,
      round(coalesce(nullif(comp.value->>'component_amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as component_amount_ex
    from timesheet_item_with_baseline tiwb
    cross join lateral jsonb_array_elements(coalesce(tiwb.case_components_json, '[]'::jsonb)) with ordinality as comp(value, ordinality)
  ),
  finance_component_movements_raw as (
    /* Authoritative builds have already folded settled baseline and active
       reservations into each signed component.  Keep the movement relation
       fact-owned so no mutable finance table can change the result. */
    select v_authoritative_candidate_id as candidate_id,fact.timesheet_id,
      upper(btrim(coalesce(fact.economic_key_type,''))) as component_key_type,
      nullif(btrim(coalesce(fact.economic_key_value,'')),'') as component_key_value,
      case
        when fact.fact_family='FROZEN_SETTLED_COMPONENT' then upper(btrim(coalesce(
          fact.source_payload_json #>> '{pay_batch_item,item_type}',
          fact.source_payload_json->>'item_type','')))
        when fact.fact_family='RESERVATION_COMPONENT' then case upper(coalesce((
          select case_fact.source_payload_json->>'case_type'
          from private.banking_pay_workbench_economic_build_facts case_fact
          where case_fact.build_id=fact.build_id
            and case_fact.fact_family='FINANCE_CASE_IDENTITY'
            and case_fact.finance_case_id=fact.finance_case_id
          limit 1),'OVERPAYMENT'))
          when 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT' else 'OVERPAYMENT_RECOVERY' end
        else NULL end as item_type,
      round(abs(coalesce(fact.amount_ex_vat,fact.reserved_source_amount,0)),2)::numeric(12,2) as movement_amount_ex,
      (fact.fact_family='FROZEN_SETTLED_COMPONENT') as is_settled_movement,
      (fact.fact_family='RESERVATION_COMPONENT') as is_active_reservation
    from private.banking_pay_workbench_economic_build_facts fact
    where fact.build_id=p_build_id
      and fact.fact_family in ('FROZEN_SETTLED_COMPONENT','RESERVATION_COMPONENT')
      and fact.timesheet_id is not null
  ),
  finance_component_movements as (
    select
      fcmr.candidate_id,
      fcmr.timesheet_id,
      fcmr.component_key_type,
      fcmr.component_key_value,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_underpayment_payment_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_underpayment_payment_ex,
      true as has_finance_movement
    from finance_component_movements_raw fcmr
    where fcmr.component_key_type is not null
      and fcmr.component_key_value is not null
    group by fcmr.candidate_id, fcmr.timesheet_id, fcmr.component_key_type, fcmr.component_key_value
  ),
  timesheet_exploded_with_signed_balance as (
    select
      tec.*,
      coalesce(fcm.settled_overpayment_recovery_ex, 0) as settled_overpayment_recovery_ex,
      coalesce(fcm.reserved_overpayment_recovery_ex, 0) as reserved_overpayment_recovery_ex,
      coalesce(fcm.settled_underpayment_payment_ex, 0) as settled_underpayment_payment_ex,
      coalesce(fcm.reserved_underpayment_payment_ex, 0) as reserved_underpayment_payment_ex,
      coalesce(fcm.has_finance_movement, false) as has_finance_movement,
      case
        /* The authoritative pre-draft component amount is already the canonical
           live-truth minus settled-baseline minus active-reservation balance.
           Reapplying finance movements here would double count them. */
        when upper(btrim(coalesce(
               tec.component_json->>'overpayment_component_authority',
               ''
             ))) = 'PRE_DRAFT_LIVE_TRUTH'
          then round(coalesce(tec.component_amount_ex, 0), 2)::numeric(12,2)
        else round(
          coalesce(tec.component_amount_ex, 0)
          + coalesce(fcm.settled_overpayment_recovery_ex, 0)
          + coalesce(fcm.reserved_overpayment_recovery_ex, 0)
          - coalesce(fcm.settled_underpayment_payment_ex, 0)
          - coalesce(fcm.reserved_underpayment_payment_ex, 0),
          2
        )::numeric(12,2)
      end as signed_component_amount_ex
    from timesheet_exploded_components tec
    left join finance_component_movements fcm
      on fcm.candidate_id = tec.candidate_id
     and fcm.timesheet_id = tec.timesheet_id
     and fcm.component_key_type = tec.component_key_type
     and fcm.component_key_value = tec.component_key_value
  ),
  timesheet_case_rollup as (
    select
      tec.candidate_id,
      tec.timesheet_id,
      min(tec.client_id::text)::uuid as client_id,
      min(tec.linked_shift_date) as linked_shift_date,
      min(tec.corrected_amount_ex) as corrected_amount_ex,
      min(tec.baseline_signature) as baseline_signature,
      min(tec.candidate_pay_method) as candidate_pay_method,
      bool_or(tec.case_is_blocked) as case_is_blocked,
      bool_or(coalesce(tec.has_finance_movement, false)) as has_finance_movement,
      round(coalesce(sum(case when tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null then abs(tec.signed_component_amount_ex) else 0 end), 0), 2)::numeric(12,2) as overpayment_amount_ex,
      round(coalesce(sum(case when tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null then tec.signed_component_amount_ex else 0 end), 0), 2)::numeric(12,2) as underpayment_amount_ex,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''),
            'current_target_pay_method', nullif(btrim(coalesce(tec.component_json->>'current_target_pay_method', '')), ''),
            'source_basis_json', (CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END)||jsonb_build_object('source_pay_method',
              nullif(btrim(coalesce(tec.component_json->>'source_pay_method','')),'')),
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as overpayment_components_json,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''),
            'current_target_pay_method', nullif(btrim(coalesce(tec.component_json->>'current_target_pay_method', '')), ''),
            'source_basis_json', (CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END)||jsonb_build_object('source_pay_method',
              nullif(btrim(coalesce(tec.component_json->>'source_pay_method','')),'')),
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as underpayment_components_json
    from timesheet_exploded_with_signed_balance tec
    group by tec.candidate_id, tec.timesheet_id
  ),
  active_linked_underpayment_cases as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      true as has_existing_active_underpayment_case
    from public.pay_advances pa
    where pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
      and pa.linked_timesheet_id is not null
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
    group by pa.candidate_id, pa.linked_timesheet_id
  ),
  timesheet_case_candidates as (
    select
      tcr.candidate_id,
      tcr.timesheet_id,
      tcr.client_id,
      tcr.linked_shift_date,
      tcr.corrected_amount_ex,
      tcr.baseline_signature,
      tcr.candidate_pay_method,
      tcr.case_is_blocked,
      (
        tcr.overpayment_amount_ex > 0
        or (
          tcr.underpayment_amount_ex > 0
          and (
            tcr.case_is_blocked = true
            or coalesce(aluc.has_existing_active_underpayment_case, false) = true
            or coalesce(tcr.has_finance_movement, false) = true
          )
        )
      ) as needs_lifecycle_tracking,
      tcr.overpayment_amount_ex,
      tcr.underpayment_amount_ex,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_finance_case_type_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_finance_case_type_enum
        else null::public.pay_finance_case_type_enum
      end as desired_case_type,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_kind_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_kind_enum
        else null::public.pay_advance_kind_enum
      end as desired_advance_kind,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_reason_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_reason_enum
        else null::public.pay_advance_reason_enum
      end as desired_reason,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex + tcr.overpayment_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex - tcr.underpayment_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_original_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_corrected_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then tcr.overpayment_components_json
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then tcr.underpayment_components_json
        else '[]'::jsonb
      end as components_sync_json,
      1 as candidate_priority
    from timesheet_case_rollup tcr
    left join active_linked_underpayment_cases aluc
      on aluc.candidate_id = tcr.candidate_id
     and aluc.timesheet_id = tcr.timesheet_id
    where tcr.overpayment_amount_ex > 0
       or (
         tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         )
       )
  ),
  finance_case_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      nullif(btrim(coalesce(itm.value->>'linked_shift_date', '')), '')::date as linked_shift_date,
      upper(btrim(coalesce(itm.value->>'case_type', ''))) as case_type_text,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      round(abs(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0)), 2)::numeric(12,2) as line_amount_ex,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '') is not null
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  finance_case_candidates_raw as (
    select
      fcir.candidate_id,
      fcir.timesheet_id,
      coalesce(fcir.client_id, pa.client_id) as client_id,
      coalesce(fcir.linked_shift_date, pa.linked_shift_date) as linked_shift_date,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as corrected_amount_ex,
      pa.baseline_signature,
      fcir.candidate_pay_method,
      fcir.case_is_blocked,
      true as needs_lifecycle_tracking,
      case when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as overpayment_amount_ex,
      case when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as underpayment_amount_ex,
      pa.case_type as desired_case_type,
      pa.advance_kind as desired_advance_kind,
      pa.reason as desired_reason,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as source_corrected_paid_amount,
      coalesce(fcir.case_components_json, '[]'::jsonb) as components_sync_json,
      2 as candidate_priority
    from finance_case_item_rows fcir
    join public.pay_advances pa
      on pa.id = fcir.finance_case_id
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id = fcir.timesheet_id
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
  ),
  combined_case_candidates as (
    select
      tcc.candidate_id,
      tcc.timesheet_id,
      tcc.client_id,
      tcc.linked_shift_date,
      tcc.corrected_amount_ex,
      tcc.baseline_signature,
      tcc.candidate_pay_method,
      tcc.case_is_blocked,
      tcc.needs_lifecycle_tracking,
      tcc.overpayment_amount_ex,
      tcc.underpayment_amount_ex,
      tcc.desired_case_type,
      tcc.desired_advance_kind,
      tcc.desired_reason,
      tcc.source_original_paid_amount,
      tcc.source_corrected_paid_amount,
      tcc.components_sync_json,
      tcc.candidate_priority
    from timesheet_case_candidates tcc

    union all

    select
      fccr.candidate_id,
      fccr.timesheet_id,
      fccr.client_id,
      fccr.linked_shift_date,
      fccr.corrected_amount_ex,
      fccr.baseline_signature,
      fccr.candidate_pay_method,
      fccr.case_is_blocked,
      fccr.needs_lifecycle_tracking,
      fccr.overpayment_amount_ex,
      fccr.underpayment_amount_ex,
      fccr.desired_case_type,
      fccr.desired_advance_kind,
      fccr.desired_reason,
      fccr.source_original_paid_amount,
      fccr.source_corrected_paid_amount,
      fccr.components_sync_json,
      fccr.candidate_priority
    from finance_case_candidates_raw fccr
  ),
  deduped_case_candidates as (
    select
      ccc.candidate_id,
      ccc.timesheet_id,
      ccc.client_id,
      ccc.linked_shift_date,
      ccc.corrected_amount_ex,
      ccc.baseline_signature,
      ccc.candidate_pay_method,
      ccc.case_is_blocked,
      ccc.needs_lifecycle_tracking,
      ccc.overpayment_amount_ex,
      ccc.underpayment_amount_ex,
      ccc.desired_case_type,
      ccc.desired_advance_kind,
      ccc.desired_reason,
      ccc.source_original_paid_amount,
      ccc.source_corrected_paid_amount,
      ccc.components_sync_json
    from (
      select
        ccc_inner.*,
        row_number() over (
          partition by ccc_inner.candidate_id, ccc_inner.timesheet_id
          order by
            ccc_inner.candidate_priority asc,
            case when ccc_inner.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 0 else 1 end,
            case when ccc_inner.needs_lifecycle_tracking then 0 else 1 end
        ) as rn
      from combined_case_candidates ccc_inner
    ) ccc
    where ccc.rn = 1
  )
  select
    dcc.candidate_id,
    dcc.timesheet_id,
    dcc.client_id,
    dcc.linked_shift_date,
    dcc.corrected_amount_ex,
    dcc.baseline_signature,
    dcc.candidate_pay_method,
    dcc.case_is_blocked,
    dcc.needs_lifecycle_tracking,
    dcc.overpayment_amount_ex,
    dcc.underpayment_amount_ex,
    dcc.desired_case_type,
    dcc.desired_advance_kind,
    dcc.desired_reason,
    dcc.source_original_paid_amount,
    dcc.source_corrected_paid_amount,
    dcc.components_sync_json
  from deduped_case_candidates dcc
  where dcc.desired_case_type is not null;

  IF COALESCE(v_authoritative_timesheet_scope,false) THEN
    v_rate_authority_failure_code:=NULL::text;
    v_rate_authority_failure_detail:='{}'::jsonb;
    WITH component_methods AS MATERIALIZED (
      SELECT candidate.candidate_id,candidate.timesheet_id,
        UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),''))
          AS source_pay_method,
        UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),''))
          AS economic_key_type,
        NULLIF(BTRIM(component.value->>'component_key_value'),'')
          AS economic_key_value,
        component.ordinality::integer AS component_ordinality
      FROM pg_temp.tmp_sync_timesheet_case_candidates candidate
      CROSS JOIN LATERAL jsonb_array_elements(CASE
        WHEN jsonb_typeof(candidate.components_sync_json)='array'
          THEN candidate.components_sync_json ELSE '[]'::jsonb END)
        WITH ORDINALITY component(value,ordinality)
    ), method_summary AS MATERIALIZED (
      SELECT method.candidate_id,method.timesheet_id,COUNT(*)::integer AS component_count,
        COUNT(*) FILTER(WHERE method.source_pay_method IS NULL
          OR method.source_pay_method NOT IN ('PAYE','UMBRELLA'))::integer
          AS invalid_method_count,
        COUNT(DISTINCT method.source_pay_method) FILTER(
          WHERE method.source_pay_method IN ('PAYE','UMBRELLA'))::integer
          AS distinct_supported_method_count,
        jsonb_agg(jsonb_build_object(
          'component_ordinality',method.component_ordinality,
          'economic_key_type',method.economic_key_type,
          'economic_key_value',method.economic_key_value,
          'source_pay_method',method.source_pay_method)
          ORDER BY method.component_ordinality) AS complete_component_method_set
      FROM component_methods method
      GROUP BY method.candidate_id,method.timesheet_id
    )
    SELECT CASE WHEN summary.invalid_method_count>0
        THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
        ELSE 'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT' END,
      jsonb_build_object(
        'candidate_id',summary.candidate_id,
        'timesheet_id',summary.timesheet_id,
        'component_count',summary.component_count,
        'invalid_method_count',summary.invalid_method_count,
        'distinct_supported_method_count',summary.distinct_supported_method_count,
        'complete_component_method_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(summary.complete_component_method_set::text,'UTF8'),
          'sha256'),'hex'),
        'sample_truncated',summary.component_count>25,
        'component_method_sample',pg_catalog.jsonb_path_query_array(
          summary.complete_component_method_set,'$[0 to 24]'))
    INTO v_rate_authority_failure_code,v_rate_authority_failure_detail
    FROM method_summary summary
    WHERE summary.invalid_method_count>0
       OR summary.distinct_supported_method_count<>1
    ORDER BY summary.timesheet_id
    LIMIT 1;

    IF v_rate_authority_failure_code IS NOT NULL THEN
      RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
        DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
          'detail',v_rate_authority_failure_detail)::text;
    END IF;
  END IF;

  v_correction_rewrite_result :=
    public._ctms_rewrite_sync_correction_cases_v1(
    case
      when nullif(btrim(coalesce(p_mismatch_choices->>'workbench_session_id', '')), '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid
      else null::uuid
    end,
    coalesce(p_candidate_ids, array[]::uuid[]),
    coalesce(p_force_include_timesheet_ids, array[]::uuid[])
  );

  select coalesce(array_agg(distinct value::uuid order by value::uuid),array[]::uuid[])
  into v_resolution_pending_member_ids
  from jsonb_array_elements_text(
    coalesce(
      v_correction_rewrite_result
        ->'resolution_pending_member_timesheet_ids',
      '[]'::jsonb
    )
  ) pending_member(value);

  select count(*)::int into v_timesheet_case_count from pg_temp.tmp_sync_timesheet_case_candidates;
  select count(*)::int into v_overpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;
  select count(*)::int into v_underpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'client_id', case when t.client_id is null then null else t.client_id::text end,
        'linked_shift_date', case when t.linked_shift_date is null then null else t.linked_shift_date::text end,
        'baseline_signature', t.baseline_signature,
        'corrected_amount_ex', t.corrected_amount_ex,
        'case_is_blocked', t.case_is_blocked,
        'desired_case_type', case when t.desired_case_type is null then null else t.desired_case_type::text end,
        'needs_lifecycle_tracking', t.needs_lifecycle_tracking,
        'overpayment_amount_ex', t.overpayment_amount_ex,
        'underpayment_amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_case_candidates_json
  from pg_temp.tmp_sync_timesheet_case_candidates t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.overpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_overpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_underpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  v_case_workspace_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  for v_target_case_row in
    select
      t.*
    from pg_temp.tmp_sync_timesheet_case_candidates t
    order by t.candidate_id, t.timesheet_id
  loop
    v_selected_event_type := NULL;
    v_selected_reason := NULL;
    v_selected_note := NULL;
    v_case_update_count := 0;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.overpayment_amount_ex, 2)::numeric(12,2);
    elsif v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.underpayment_amount_ex, 2)::numeric(12,2);
    else
      v_target_case_amount_ex := null;
    end if;

    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array'
            THEN v_target_case_row.components_sync_json
          ELSE '[]'::jsonb
        END
      ) AS authoritative_component(value)
      WHERE UPPER(BTRIM(COALESCE(
        authoritative_component.value->>'overpayment_component_authority',
        ''
      ))) = 'PRE_DRAFT_LIVE_TRUTH'
    )
    INTO v_target_amount_is_authoritative_outstanding;

    v_case_taxability := NULL;
    v_case_routing_kind := NULL;
    v_case_metadata_component_count := 0;
    IF v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification = 'TAXABLE_CHANNEL_SENSITIVE', false)) THEN 'TAXABLE'::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification IN ('REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY'), false)) THEN 'NON_TAXABLE'::public.pay_finance_taxability_enum
          ELSE NULL::public.pay_finance_taxability_enum
        END,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          ELSE NULL::public.pay_finance_routing_kind_enum
        END
      INTO
        v_case_metadata_component_count,
        v_case_taxability,
        v_case_routing_kind
      FROM (
        SELECT
          upper(nullif(btrim(coalesce(component_element.value->>'classification', '')), '')) AS classification,
          upper(nullif(btrim(component_element.value->>'source_pay_method'),''))
            AS source_pay_method
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array' THEN v_target_case_row.components_sync_json
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS normalized_component;
    END IF;

    select
      pa.id as finance_case_id,
      pa.case_type as old_case_type,
      pa.status as old_status,
      round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature,
      pa.taxability as old_taxability,
      pa.routing_kind as old_routing_kind,
      pa.written_off_at_utc as old_written_off_at_utc,
      pa.cleared_at_utc as old_cleared_at_utc,
      exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts sync_safety_events
        where sync_safety_events.build_id=p_build_id
          and sync_safety_events.fact_family='PROTECTION_EVIDENCE'
          and sync_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_safety_events.source_payload_json->>'event_type', ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_safety_events.source_payload_json->>'event_type', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_safety_events.source_payload_json->>'reason', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      ) as old_has_manual_or_restructure_event,
      exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts automatic_clear_event
        where automatic_clear_event.build_id=p_build_id
          and automatic_clear_event.fact_family='PROTECTION_EVIDENCE'
          and automatic_clear_event.finance_case_id = pa.id
          and (
            (
              upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'event_type', ''))) = 'CASE_CLEARED'
              and lower(btrim(coalesce(automatic_clear_event.source_payload_json->>'reason', ''))) = 'rail_settlement'
            )
            or (
              upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'event_type', ''))) = 'CLEARED'
              and upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'reason', ''))) = 'PREVIEW_FINANCE_SYNC'
            )
          )
      ) as old_has_automatic_reconcilable_clear,
      round(coalesce((
        select sum(abs(coalesce(settled_fact.amount_ex_vat,0)))
        from private.banking_pay_workbench_economic_build_facts settled_fact
        where settled_fact.build_id=p_build_id
          and settled_fact.fact_family='FROZEN_SETTLED_COMPONENT'
          and settled_fact.finance_case_id=pa.id
          and (
            (
              v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_fact.source_payload_json #>> '{pay_batch_item,item_type}',
                settled_fact.source_payload_json->>'item_type',''))) = 'OVERPAYMENT_RECOVERY'
            )
            or (
              v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_fact.source_payload_json #>> '{pay_batch_item,item_type}',
                settled_fact.source_payload_json->>'item_type',''))) = 'UNDERPAYMENT_PAYMENT'
            )
          )
      ), 0), 2)::numeric(12,2) as old_active_recovered_amount
    into v_existing_case_row
    from public.pay_advances pa
    where pa.candidate_id = v_target_case_row.candidate_id
      and pa.linked_timesheet_id = v_target_case_row.timesheet_id
      and pa.case_type = v_target_case_row.desired_case_type
    order by
      case when upper(coalesce(pa.status::text,'')) = 'ACTIVE' then 0 else 1 end,
      pa.updated_at desc,
      pa.created_at desc,
      pa.id desc
    limit 1
    for update;

    v_existing_recovered_amount := greatest(
      coalesce(v_existing_case_row.old_active_recovered_amount, 0),
      0
    );

    v_existing_active_reserved_amount := 0::numeric(12,2);

    IF v_existing_case_row.finance_case_id IS NOT NULL THEN
      SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
        reservation_fact.reserved_source_amount,reservation_fact.amount_ex_vat,0))),0),2)::numeric(12,2)
      INTO v_existing_active_reserved_amount
      FROM private.banking_pay_workbench_economic_build_facts reservation_fact
      WHERE reservation_fact.build_id=p_build_id
        AND reservation_fact.fact_family='RESERVATION_COMPONENT'
        AND reservation_fact.finance_case_id=v_existing_case_row.finance_case_id;
    END IF;

    if v_existing_case_row.finance_case_id is not null
       and (
         v_existing_case_row.old_written_off_at_utc is not null
         or (
           v_existing_case_row.old_cleared_at_utc is not null
           and not (
             upper(coalesce(v_existing_case_row.old_status::text, '')) = 'PAID_OFF'
             and coalesce(v_existing_case_row.old_has_automatic_reconcilable_clear, false)
             and coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false) is not true
             and (
               (
                 coalesce(v_target_amount_is_authoritative_outstanding, false)
                 and round(coalesce(v_target_case_amount_ex, 0), 2) > 0
               )
               or (
                 coalesce(v_target_amount_is_authoritative_outstanding, false) is not true
                 and round(
                   coalesce(v_target_case_amount_ex, 0)
                   - coalesce(v_existing_recovered_amount, 0),
                   2
                 ) > 0
               )
             )
           )
         )
         or upper(coalesce(v_existing_case_row.old_status::text,'')) not in ('ACTIVE','PAID_OFF')
         or coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false)
       ) then
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_existing_case_row.finance_case_id,
        'SYNC_SKIPPED',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_existing_case_row.old_case_type::text,
          'status', v_existing_case_row.old_status::text,
          'original_amount', v_existing_case_row.old_original_amount,
          'outstanding_amount', v_existing_case_row.old_outstanding_amount,
          'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
          'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
          'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
          'baseline_signature', v_existing_case_row.old_baseline_signature,
          'written_off_at_utc', v_existing_case_row.old_written_off_at_utc,
          'cleared_at_utc', v_existing_case_row.old_cleared_at_utc,
          'has_manual_or_restructure_event', v_existing_case_row.old_has_manual_or_restructure_event,
          'has_automatic_reconcilable_clear', v_existing_case_row.old_has_automatic_reconcilable_clear,
          'existing_recovered_amount', v_existing_recovered_amount
        ),
        jsonb_build_object(
          'sync_skipped', true,
          'component_sync_skipped', true,
          'component_authority_preserved', true,
          'target_case_type', case when v_target_case_row.desired_case_type is null then null else v_target_case_row.desired_case_type::text end,
          'target_original_amount', v_target_case_amount_ex,
          'target_source_original_paid_amount', v_target_case_row.source_original_paid_amount,
          'target_source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
          'target_baseline_signature', v_target_case_row.baseline_signature,
          'target_pay_channel_scope', v_scope,
          'workbench_session_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), ''),
          'source_build_run_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), ''),
          'session_version', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), ''),
          'overpayment_sync_scope_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), ''),
          'overpayment_sync_negative_component_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), ''),
          'overpayment_sync_settled_baseline_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), ''),
          'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
        ),
        'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE',
        'Skipped case and component synchronisation because the existing case is written-off, cleared, closed, paused, manually resolved, or restructured.'
      );

      /* A protected case must not be inserted into tmp_sync_case_links with an
         empty component payload.  Every row in tmp_sync_case_links is processed
         later by pay_finance_components_sync_from_preview; an empty payload is
         authoritative removal input and can close open components.  The case
         clear pass already excludes protected cases by lifecycle state/event,
         so omitting the link preserves the complete protected case/component
         authority without allowing automatic sync to rewrite it. */
      continue;
    end if;

    IF v_existing_case_row.finance_case_id IS NOT NULL
       AND v_existing_case_row.old_case_type IS DISTINCT FROM v_target_case_row.desired_case_type
       AND COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'existing_case_type', v_existing_case_row.old_case_type::text,
                'target_case_type', v_target_case_row.desired_case_type::text,
                'active_reserved_amount', COALESCE(v_existing_active_reserved_amount, 0),
                'message', 'The finance-case direction cannot change while a frozen recovery or payment reservation remains active. Settle or cancel the active batch before reconciling the opposite direction.'
              )::text;
    END IF;

    IF COALESCE(v_target_amount_is_authoritative_outstanding, false) THEN
      /* PRE_DRAFT_LIVE_TRUTH supplies the canonical amount that remains after
         settled baseline movements and active reservations.  Keep historic
         consumption in the case lifetime total, but do not subtract it from
         the authoritative remaining amount a second time. */
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < COALESCE(v_existing_active_reserved_amount, 0);
      v_new_outstanding_amount := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        COALESCE(v_existing_active_reserved_amount, 0),
        0
      )::numeric(12,2);
      v_effective_case_amount_ex := ROUND(
        COALESCE(v_existing_recovered_amount, 0) + v_new_outstanding_amount,
        2
      )::numeric(12,2);
    ELSE
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2);
      v_effective_case_amount_ex := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2)
      )::numeric(12,2);
      v_new_outstanding_amount := greatest(v_effective_case_amount_ex - v_existing_recovered_amount, COALESCE(v_existing_active_reserved_amount, 0), 0)::numeric(12,2);
    END IF;

    if v_existing_case_row.finance_case_id is null then
      insert into public.pay_advances (
        candidate_id,
        client_id,
        case_type,
        advance_kind,
        reason,
        linked_timesheet_id,
        linked_shift_date,
        baseline_signature,
        source_original_paid_amount,
        source_corrected_paid_amount,
        original_amount,
        outstanding_amount,
        status,
        created_by,
        updated_at,
        created_at,
        cleared_at_utc,
        cleared_by_user_id,
        write_off_reason,
        written_off_at_utc,
        written_off_by_user_id,
        taxability,
        routing_kind
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.client_id,
        v_target_case_row.desired_case_type,
        v_target_case_row.desired_advance_kind,
        v_target_case_row.desired_reason,
        v_target_case_row.timesheet_id,
        v_target_case_row.linked_shift_date,
        v_target_case_row.baseline_signature,
        v_target_case_row.source_original_paid_amount,
        v_target_case_row.source_corrected_paid_amount,
        v_effective_case_amount_ex,
        v_new_outstanding_amount,
        'ACTIVE'::public.pay_advance_status_enum,
        p_actor_user_id,
        now(),
        now(),
        null,
        null,
        null,
        null,
        null,
        v_case_taxability,
        v_case_routing_kind
      )
      returning id into v_selected_finance_case_id;

      v_cases_inserted := v_cases_inserted + 1;
      v_selected_event_type := 'CREATED';
      v_selected_reason := 'PREVIEW_FINANCE_SYNC';
      v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Created overpayment finance case from component-aware preview sync' else 'Created lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      v_case_before_json := null;
      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'candidate_id', v_target_case_row.candidate_id::text,
        'linked_timesheet_id', v_target_case_row.timesheet_id::text,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
        'routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
        'status', 'ACTIVE'
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (v_case_taxability IS NOT NULL OR v_case_routing_kind IS NOT NULL) THEN jsonb_build_object(
          'before_taxability', null,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', null,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    else
      v_case_before_json := jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', v_existing_case_row.old_status::text,
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
        'routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      )
      || CASE
        WHEN v_existing_case_row.old_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        )
        ELSE '{}'::jsonb
      END;

      update public.pay_advances pa
      set
        client_id = v_target_case_row.client_id,
        case_type = v_target_case_row.desired_case_type,
        advance_kind = v_target_case_row.desired_advance_kind,
        reason = v_target_case_row.desired_reason,
        linked_shift_date = v_target_case_row.linked_shift_date,
        baseline_signature = v_target_case_row.baseline_signature,
        source_original_paid_amount = v_target_case_row.source_original_paid_amount,
        source_corrected_paid_amount = v_target_case_row.source_corrected_paid_amount,
        original_amount = v_effective_case_amount_ex,
        outstanding_amount = v_new_outstanding_amount,
        status = case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
        cleared_at_utc = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
        cleared_by_user_id = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
        taxability = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
          else pa.taxability
        end,
        routing_kind = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
          else pa.routing_kind
        end,
        updated_at = now()
      where pa.id = v_existing_case_row.finance_case_id
        and row(
          pa.client_id,
          pa.case_type,
          pa.advance_kind,
          pa.reason,
          pa.linked_shift_date,
          pa.baseline_signature,
          pa.source_original_paid_amount,
          pa.source_corrected_paid_amount,
          pa.original_amount,
          pa.outstanding_amount,
          pa.status,
          pa.cleared_at_utc,
          pa.cleared_by_user_id,
          pa.taxability,
          pa.routing_kind
        ) is distinct from row(
          v_target_case_row.client_id,
          v_target_case_row.desired_case_type,
          v_target_case_row.desired_advance_kind,
          v_target_case_row.desired_reason,
          v_target_case_row.linked_shift_date,
          v_target_case_row.baseline_signature,
          v_target_case_row.source_original_paid_amount,
          v_target_case_row.source_corrected_paid_amount,
          v_effective_case_amount_ex,
          v_new_outstanding_amount,
          case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
            else pa.taxability
          end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
            else pa.routing_kind
          end
        );

      get diagnostics v_case_update_count = row_count;

      v_selected_finance_case_id := v_existing_case_row.finance_case_id;
      v_cases_touched := v_cases_touched + 1;

      if v_case_update_count > 0
         and upper(coalesce(v_existing_case_row.old_status::text,'')) = 'PAID_OFF'
         and v_new_outstanding_amount > 0 then
        v_cases_reopened := v_cases_reopened + 1;
        v_selected_event_type := 'REOPENED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Reopened overpayment finance case from component-aware preview sync' else 'Reopened lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      elsif v_case_update_count > 0 then
        v_cases_amended := v_cases_amended + 1;
        v_selected_event_type := 'AMENDED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Amended overpayment finance case from component-aware preview sync' else 'Amended lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      end if;

      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'status', case when v_new_outstanding_amount > 0 then 'ACTIVE' else 'PAID_OFF' end,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END
          ELSE CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END
        END,
        'routing_kind', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END
          ELSE CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        END,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (
           v_existing_case_row.old_taxability IS DISTINCT FROM v_case_taxability
           OR v_existing_case_row.old_routing_kind IS DISTINCT FROM v_case_routing_kind
         ) THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    end if;

    insert into pg_temp.tmp_sync_case_links (
      candidate_id,
      timesheet_id,
      finance_case_id,
      desired_case_type,
      source_original_paid_amount,
      source_corrected_paid_amount,
      case_amount_ex,
      linked_shift_date,
      baseline_signature,
      components_sync_json
    )
    values (
      v_target_case_row.candidate_id,
      v_target_case_row.timesheet_id,
      v_selected_finance_case_id,
      v_target_case_row.desired_case_type,
      v_target_case_row.source_original_paid_amount,
      v_target_case_row.source_corrected_paid_amount,
      COALESCE(v_effective_case_amount_ex, v_target_case_amount_ex),
      v_target_case_row.linked_shift_date,
      v_target_case_row.baseline_signature,
      v_target_case_row.components_sync_json
    )
    on conflict (candidate_id, timesheet_id) do update
    set
      finance_case_id = excluded.finance_case_id,
      desired_case_type = excluded.desired_case_type,
      source_original_paid_amount = excluded.source_original_paid_amount,
      source_corrected_paid_amount = excluded.source_corrected_paid_amount,
      case_amount_ex = excluded.case_amount_ex,
      linked_shift_date = excluded.linked_shift_date,
      baseline_signature = excluded.baseline_signature,
      components_sync_json = excluded.components_sync_json;

    if v_selected_event_type is not null then
    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_selected_finance_case_id,
      v_selected_event_type,
      now(),
      p_actor_user_id,
      null,
      null,
      v_case_before_json,
      v_case_after_json,
      v_selected_reason,
      v_selected_note
    );
    end if;

    IF COALESCE(v_active_reservation_protection_applied, false)
       AND NOT EXISTS (
         SELECT 1
         FROM public.pay_finance_case_events AS protection_event
         WHERE protection_event.finance_case_id = v_selected_finance_case_id
           AND protection_event.event_type = 'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION'
           AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
           AND protection_event.before_json IS NOT DISTINCT FROM v_case_before_json
           AND protection_event.after_json = jsonb_build_object(
             'target_case_amount_ex', v_target_case_amount_ex,
             'effective_case_amount_ex', v_effective_case_amount_ex,
             'active_reserved_recovery_amount', v_existing_active_reserved_amount,
             'existing_recovered_amount', v_existing_recovered_amount,
             'outstanding_amount', v_new_outstanding_amount
           )
       ) THEN
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_selected_finance_case_id,
        'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
        now(),
        p_actor_user_id,
        null,
        null,
        v_case_before_json,
        jsonb_build_object(
          'target_case_amount_ex', v_target_case_amount_ex,
          'effective_case_amount_ex', v_effective_case_amount_ex,
          'active_reserved_recovery_amount', v_existing_active_reserved_amount,
          'existing_recovered_amount', v_existing_recovered_amount,
          'outstanding_amount', v_new_outstanding_amount
        ),
        'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
        'Deferred overpayment/underpayment case shrink because an active recovery reservation exists.'
      );
    END IF;
  end loop;

  for v_open_case_candidate in
    select
      pa.id as finance_case_id,
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      pa.case_type as old_case_type,
      round(coalesce(pa.original_amount,0),2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount,0),2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount,0),2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount,0),2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature
    from public.pay_advances pa
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or pa.candidate_id = any(p_candidate_ids)
      )
      and (
        p_client_filter_single is null
        or pa.client_id = p_client_filter_single
      )
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or pa.linked_timesheet_id = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and pa.linked_timesheet_id = any(p_exclude_timesheet_ids)
      )
      and not (
        coalesce(array_length(v_resolution_pending_member_ids, 1), 0) > 0
        and pa.linked_timesheet_id
              = any(v_resolution_pending_member_ids)
      )
      and not exists (
        select 1
        from pg_temp.tmp_sync_case_links l
        where l.finance_case_id = pa.id
      )
      and exists (
        select 1
        from public.candidates c
        where c.id = pa.candidate_id
          and upper(coalesce(c.pay_method,'')) = v_scope
      )
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and pa.written_off_at_utc is null
      and pa.cleared_at_utc is null
      and not exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts sync_clear_safety_events
        where sync_clear_safety_events.build_id=p_build_id
          and sync_clear_safety_events.fact_family='PROTECTION_EVIDENCE'
          and sync_clear_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'event_type', ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'event_type', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'reason', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      )
  loop
    SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
      reservation_fact.reserved_source_amount,reservation_fact.amount_ex_vat,0))),0),2)::numeric(12,2)
    INTO v_existing_active_reserved_amount
    FROM private.banking_pay_workbench_economic_build_facts reservation_fact
    WHERE reservation_fact.build_id=p_build_id
      AND reservation_fact.fact_family='RESERVATION_COMPONENT'
      AND reservation_fact.finance_case_id=v_open_case_candidate.finance_case_id;

    IF COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protection_event
        WHERE protection_event.finance_case_id = v_open_case_candidate.finance_case_id
          AND protection_event.event_type = 'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION'
          AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
          AND protection_event.before_json = jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          )
          AND protection_event.after_json = jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          )
      ) THEN
        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_open_case_candidate.finance_case_id,
          'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION',
          now(),
          p_actor_user_id,
          null,
          null,
          jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          ),
          jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          ),
          'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
          'Deferred finance case clear because an active recovery reservation exists.'
        );
      END IF;

      CONTINUE;
    END IF;

    insert into pg_temp.tmp_sync_case_clears (
      finance_case_id,
      candidate_id,
      timesheet_id,
      old_case_type,
      old_original_amount,
      old_outstanding_amount,
      old_source_original_paid_amount,
      old_source_corrected_paid_amount,
      old_linked_shift_date,
      old_baseline_signature
    )
    values (
      v_open_case_candidate.finance_case_id,
      v_open_case_candidate.candidate_id,
      v_open_case_candidate.timesheet_id,
      v_open_case_candidate.old_case_type,
      v_open_case_candidate.old_original_amount,
      v_open_case_candidate.old_outstanding_amount,
      v_open_case_candidate.old_source_original_paid_amount,
      v_open_case_candidate.old_source_corrected_paid_amount,
      v_open_case_candidate.old_linked_shift_date,
      v_open_case_candidate.old_baseline_signature
    )
    on conflict (finance_case_id) do nothing;
  end loop;

  for v_existing_case_row in
    select *
    from pg_temp.tmp_sync_case_clears
    order by candidate_id, timesheet_id, finance_case_id
  loop
    update public.pay_advances pa
    set
      status = 'PAID_OFF'::public.pay_advance_status_enum,
      outstanding_amount = 0,
      cleared_at_utc = coalesce(pa.cleared_at_utc, now()),
      cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id),
      updated_at = now()
    where pa.id = v_existing_case_row.finance_case_id;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_existing_case_row.finance_case_id,
      'CLEARED',
      now(),
      p_actor_user_id,
      null,
      null,
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'ACTIVE',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'PAID_OFF',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', 0,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      'PREVIEW_FINANCE_SYNC',
      'Cleared finance case because the current preview no longer requires a persistent lifecycle-tracked overpayment/underpayment header'
    );

    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_existing_case_row.finance_case_id,
      '[]'::jsonb,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_existing_case_row.candidate_id::text,
                'timesheet_id', v_existing_case_row.timesheet_id::text,
                'operation', 'CLEAR',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    v_cases_cleared := v_cases_cleared + 1;
  end loop;

  for v_target_case_row in
    select l.*
    from pg_temp.tmp_sync_case_links l
    order by l.candidate_id, l.timesheet_id
  loop
    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_target_case_row.finance_case_id,
      v_target_case_row.components_sync_json,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'operation', 'RECONCILE',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    SELECT
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
    INTO
      v_component_case_outstanding_amount,
      v_component_open_remaining_total
    FROM public.pay_advances AS pa
    LEFT JOIN public.pay_finance_case_components AS pfc
      ON pfc.finance_case_id = pa.id
    WHERE pa.id = v_target_case_row.finance_case_id
    GROUP BY pa.outstanding_amount;

    v_component_case_mismatch_amount := round(
      coalesce(v_component_case_outstanding_amount, 0) - coalesce(v_component_open_remaining_total, 0),
      2
    )::numeric(12,2);

    IF abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'case_outstanding_amount', coalesce(v_component_case_outstanding_amount, 0),
                'open_component_remaining_total', coalesce(v_component_open_remaining_total, 0),
                'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_synced_open_component_count := 0;
      v_synced_case_taxability := NULL;
      v_synced_case_routing_kind := NULL;

      select
        pa.taxability,
        pa.routing_kind
      into
        v_synced_before_taxability,
        v_synced_before_routing_kind
      from public.pay_advances pa
      where pa.id = v_target_case_row.finance_case_id
      limit 1;

      select
        count(*)::integer,
        case
          when count(*) = 0 then null::public.pay_finance_taxability_enum
          when bool_and(pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) then 'TAXABLE'::public.pay_finance_taxability_enum
          when bool_and(pfc.classification in (
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          )) then 'NON_TAXABLE'::public.pay_finance_taxability_enum
          else null::public.pay_finance_taxability_enum
        end,
        case
          when count(*) = 0 then null::public.pay_finance_routing_kind_enum
          when v_scope = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          when v_scope = 'UMBRELLA' then 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          else null::public.pay_finance_routing_kind_enum
        end
      into
        v_synced_open_component_count,
        v_synced_case_taxability,
        v_synced_case_routing_kind
      from public.pay_finance_case_components pfc
      where pfc.finance_case_id = v_target_case_row.finance_case_id
        and pfc.closed_at_utc is null
        and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

      if v_synced_open_component_count > 0
         and (v_synced_before_taxability is distinct from v_synced_case_taxability
              or v_synced_before_routing_kind is distinct from v_synced_case_routing_kind) then
        v_taxability_event_before_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end
        );

        v_taxability_event_after_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'before_taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'after_taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'before_routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end,
          'after_routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'inferred_from_open_components', true
        );

        update public.pay_advances pa
        set
          taxability = v_synced_case_taxability,
          routing_kind = v_synced_case_routing_kind,
          updated_at = now()
        where pa.id = v_target_case_row.finance_case_id;

        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_target_case_row.finance_case_id,
          case
            when v_synced_before_taxability is distinct from v_synced_case_taxability
             and v_synced_before_routing_kind is distinct from v_synced_case_routing_kind then 'HEADER_METADATA_INFERRED'
            when v_synced_before_taxability is distinct from v_synced_case_taxability then 'TAXABILITY_INFERRED'
            else 'ROUTING_KIND_INFERRED'
          end,
          now(),
          p_actor_user_id,
          null,
          null,
          v_taxability_event_before_json,
          v_taxability_event_after_json,
          'PREVIEW_FINANCE_SYNC',
          'Inferred overpayment taxability/routing metadata from open finance case components after component sync'
        );
      end if;
    end if;
  end loop;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'pay_channel_scope', v_scope,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', v_preview_candidate_count,
      'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
      'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
      'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
      'preview_scope_strategy', v_preview_scope_strategy,
      'overpayment_case_count', v_overpayment_case_count,
      'underpayment_case_count', v_underpayment_case_count,
      'cases_inserted', v_cases_inserted,
      'cases_touched', v_cases_touched,
      'cases_amended', v_cases_amended,
      'cases_reopened', v_cases_reopened,
      'cases_cleared', v_cases_cleared
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  v_public_result_json := jsonb_build_object(
    'ok', true,
    'pay_channel_scope', v_scope,
    'requested_candidate_count', v_requested_candidate_count,
    'preview_candidate_count', v_preview_candidate_count,
    'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
    'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb),
    'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
    'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
    'preview_scope_strategy', v_preview_scope_strategy,
    'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
    'negative_preview_timesheets_count', v_overpayment_case_count,
    'negative_preview_timesheets', v_overpayment_json,
    'underpayment_case_count', v_underpayment_case_count,
    'underpayment_cases', v_underpayment_json,
    'timesheet_finance_case_candidates_count', v_timesheet_case_count,
    'timesheet_finance_case_candidates', v_case_candidates_json,
    'correction_resolution_pending_chain_count',
      coalesce(
        nullif(
          v_correction_rewrite_result
            ->>'resolution_pending_chain_count',
          ''
        )::integer,
        0
      ),
    'correction_resolution_pending_member_timesheet_ids',
      to_jsonb(v_resolution_pending_member_ids),
    'cases_inserted', v_cases_inserted,
    'cases_touched', v_cases_touched,
    'cases_amended', v_cases_amended,
    'cases_reopened', v_cases_reopened,
    'cases_cleared', v_cases_cleared
  );

  v_finance_apply_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF v_effect_capture_mode THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id',candidate_id,'timesheet_id',timesheet_id,'relation_name',relation_name,
      'operation',operation,'source_id',source_id,'finance_case_id',finance_case_id,
      'finance_component_id',finance_component_id,'economic_key_type',economic_key_type,
      'economic_key_value',economic_key_value,'expected_before_digest',expected_before_digest,
      'expected_after_digest',expected_after_digest)
      ORDER BY relation_name,operation,source_id),'[]'::jsonb)
    INTO v_captured_effects FROM pg_temp._bpay_wb_expected_effects;
    IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects WHERE proposed IS NOT TRUE OR observed IS NOT TRUE) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CAPTURE_INCOMPLETE' USING ERRCODE='23514';
    END IF;
    RETURN jsonb_build_object('ok',true,'public_result_json',jsonb_build_object(
      'ok',true,'effect_plan_capture',true,'captured_effects',v_captured_effects,
      '_internal_reconcile_timing',jsonb_build_object(
        'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'workspace_cache_ms',v_workspace_cache_ms,
        'freshness_set_ms',v_freshness_set_ms,
        'authoritative_components_ms',v_authoritative_components_ms,
        'preflight_setup_ms',v_preflight_setup_ms,
        'correction_residuals_ms',v_correction_residuals_ms,
        'authority_validation_ms',v_authority_validation_ms,
        'component_assembly_ms',v_component_assembly_ms,
        'preview_workspace_ms',v_preview_workspace_ms,
        'preview_collect_ms',v_preview_collect_ms,
        'preview_canonical_ms',v_preview_canonical_ms,
        'preview_summary_ms',v_preview_summary_ms,
        'case_workspace_ms',v_case_workspace_ms,
        'finance_apply_ms',v_finance_apply_ms,
        'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
      'internal_result_json',jsonb_build_object(
        'captured_effect_count',jsonb_array_length(v_captured_effects),
        'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'freshness_set_ms',v_freshness_set_ms,
        'workspace_cache_ms',v_workspace_cache_ms,
        'authoritative_components_ms',v_authoritative_components_ms,
        'preflight_setup_ms',v_preflight_setup_ms,
        'correction_residuals_ms',v_correction_residuals_ms,
        'authority_validation_ms',v_authority_validation_ms,
        'component_assembly_ms',v_component_assembly_ms,
        'preview_workspace_ms',v_preview_workspace_ms,
        'preview_collect_ms',v_preview_collect_ms,
        'preview_canonical_ms',v_preview_canonical_ms,
        'preview_summary_ms',v_preview_summary_ms,
        'case_workspace_ms',v_case_workspace_ms,
        'finance_apply_ms',v_finance_apply_ms,
        'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer));
  END IF;

  IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects WHERE proposed IS NOT TRUE OR observed IS NOT TRUE)
     OR EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects
       WHERE build_token IS DISTINCT FROM v_bounded_build.build_token
          OR candidate_id IS DISTINCT FROM v_bounded_build.candidate_id
          OR relation_name NOT IN ('pay_advances','pay_finance_case_components','pay_finance_case_events')) THEN
    SELECT jsonb_build_object(
      'total_effects',count(*),
      'not_proposed',count(*) FILTER (WHERE proposed IS NOT TRUE),
      'not_observed',count(*) FILTER (WHERE observed IS NOT TRUE),
      'wrong_build_token',count(*) FILTER (
        WHERE build_token IS DISTINCT FROM v_bounded_build.build_token),
      'wrong_candidate',count(*) FILTER (
        WHERE candidate_id IS DISTINCT FROM v_bounded_build.candidate_id),
      'invalid_relation',count(*) FILTER (
        WHERE relation_name NOT IN (
          'pay_advances','pay_finance_case_components','pay_finance_case_events')),
      'pay_advances_not_observed',count(*) FILTER (
        WHERE relation_name='pay_advances' AND observed IS NOT TRUE),
      'components_not_observed',count(*) FILTER (
        WHERE relation_name='pay_finance_case_components' AND observed IS NOT TRUE),
      'events_not_observed',count(*) FILTER (
        WHERE relation_name='pay_finance_case_events' AND observed IS NOT TRUE)
    )
    INTO v_effect_mismatch_detail
    FROM pg_temp._bpay_wb_expected_effects;

    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
      v_effect_mismatch_detail::text
      USING ERRCODE='23514', DETAIL=v_effect_mismatch_detail::text;
  END IF;
  IF (v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared)>0
     AND (SELECT count(*) FROM pg_temp._bpay_wb_expected_effects
          WHERE relation_name='pay_advances' AND observed)
       < (v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared) THEN
    SELECT jsonb_build_object(
      'case_transitions',v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared,
      'observed_case_effects',count(*) FILTER (
        WHERE relation_name='pay_advances' AND observed)
    )
    INTO v_effect_mismatch_detail
    FROM pg_temp._bpay_wb_expected_effects;

    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
      v_effect_mismatch_detail::text
      USING ERRCODE='23514', DETAIL=v_effect_mismatch_detail::text;
  END IF;
  SELECT count(*)::integer,md5(COALESCE(string_agg(
    relation_name||':'||operation||':'||source_id::text||':'||
    COALESCE(expected_before_digest,'')||':'||COALESCE(expected_after_digest,''),''
    ORDER BY relation_name,operation,source_id),''))
  INTO v_observed_effect_count,v_observed_effect_digest
  FROM pg_temp._bpay_wb_expected_effects;

  -- Final freshness fence: preview helpers retained for presentation metadata
  -- cannot publish if any build-bound economic input changed during this RPC.
  -- Finance-case DML legitimately refreshes derived timesheet-pay summary cache
  -- fields.  The initial full-row fingerprint above remains exact; after DML,
  -- compare every non-pay-state revision plus the four settled-authority fields
  -- so cache-only refreshes cannot make the transaction stale while Policy X
  -- settlement authority and every other captured input remain fail-closed.
  CREATE TEMP TABLE pg_temp._bpay_wb_post_sync_freshness_v2(
    timesheet_id uuid PRIMARY KEY,
    input_fingerprint text NULL,
    revision_json jsonb NULL
  ) ON COMMIT DROP;
  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp._bpay_wb_post_sync_freshness_v2(timesheet_id,input_fingerprint,revision_json)
    SELECT fingerprint.timesheet_id,fingerprint.input_fingerprint,fingerprint.revision_json
    FROM private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,v_bounded_scope_ids
    ) fingerprint;
  ELSE
    INSERT INTO pg_temp._bpay_wb_post_sync_freshness_v2(timesheet_id,input_fingerprint,revision_json)
    SELECT scope_row.timesheet_id,fingerprint.input_fingerprint,fingerprint.revision_json
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,ARRAY[scope_row.timesheet_id]
    ) fingerprint ON true
    WHERE scope_row.build_id=p_build_id;
  END IF;
  IF EXISTS(
      SELECT 1
      FROM private.banking_pay_workbench_candidate_scope_registry registry
      WHERE registry.candidate_id=v_bounded_build.candidate_id
        AND (registry.current_build_id IS DISTINCT FROM p_build_id
          OR registry.dirty_generation IS DISTINCT FROM v_bounded_build.captured_candidate_generation
          OR registry.current_source_change_seq IS DISTINCT FROM v_bounded_build.source_change_seq)
    ) OR EXISTS(
      SELECT 1
      FROM private.banking_pay_workbench_economic_build_scope scope_row
      LEFT JOIN pg_temp._bpay_wb_pre_sync_freshness_v1 pre_sync
        ON pre_sync.timesheet_id=scope_row.timesheet_id
      LEFT JOIN pg_temp._bpay_wb_post_sync_freshness_v2 current_fingerprint
        ON current_fingerprint.timesheet_id=scope_row.timesheet_id
      LEFT JOIN public.timesheet_pay_state pay_state
        ON pay_state.timesheet_id=scope_row.timesheet_id
      WHERE scope_row.build_id=p_build_id
        AND (
          pre_sync.timesheet_id IS NULL
          OR current_fingerprint.input_fingerprint IS NULL
          OR (current_fingerprint.revision_json-'pay_state_digest')
               IS DISTINCT FROM (pre_sync.revision_json-'pay_state_digest')
          OR md5(jsonb_build_object(
               'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
               'last_settled_signature',pay_state.last_settled_signature,
               'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
               'last_settled_at_utc',pay_state.last_settled_at_utc
             )::text) IS DISTINCT FROM pre_sync.settled_authority_digest
        )
      LIMIT 1
    ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;
  v_post_freshness_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();
  /* The preview canonicaliser is retained only as a presentation renderer.
     Replace its complete timesheet economic input with the sealed build
     workspace before it runs, then attest the protected output fields. */
  IF to_regclass('pg_temp.timesheet_case_rollup_effective') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACT_WORKSPACE_MISSING' USING ERRCODE='23514';
  END IF;
  IF to_regclass('pg_temp.ts_baseline') IS NULL
     OR to_regclass('pg_temp.cand_payee') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACT_WORKSPACE_MISSING' USING ERRCODE='23514';
  END IF;
  -- The legacy renderer may omit a revoked or otherwise zero-current-truth
  -- economic target from its case rollup.  Preserve the complete private
  -- presentation graph by creating a neutral metadata-only row for every
  -- fact-derived economic target.  UNIT_PROJECTION also contains physical
  -- dependency evidence which deliberately owns no economic occurrence; that
  -- evidence remains sealed/attested but must not invent a presentation row.
  -- The sealed build facts below remain the sole source of every economic
  -- value.
  IF (SELECT count(*) FROM pg_temp.cand_payee payee
      WHERE payee.candidate_id=v_bounded_build.candidate_id)<>1
     OR EXISTS(
       WITH economic_target AS (
         SELECT DISTINCT component.timesheet_id
         FROM pg_temp.tmp_sync_authoritative_components component
       )
       SELECT 1
       FROM economic_target target
       LEFT JOIN pg_temp.ts_baseline baseline
         ON baseline.candidate_id=v_bounded_build.candidate_id
        AND baseline.timesheet_id=target.timesheet_id
       GROUP BY target.timesheet_id
       HAVING count(baseline.timesheet_id)<>1
     ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_METADATA_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  INSERT INTO pg_temp.timesheet_case_rollup_effective(
    candidate_id,timesheet_id,client_id,ts_week_ending_date,ts_client_name,ts_pay_method,
    cand_pay_method,cand_tms_ref,cand_display_name,cand_umbrella_id,umb_enabled,
    umb_vat_chargeable,candidate_has_bank_details,candidate_bank_hash,
    umbrella_has_bank_details,umbrella_bank_hash,resolution_family,case_needs_resolution,
    case_resolution_satisfied_now,resolution_action_label,linked_resolution_scope_json,
    case_total_amount_ex,safe_amount_ex,unresolved_taxable_amount_ex,open_taxable_count,
    open_reimbursement_count,unresolved_taxable_count,stale_count,is_mixed_case,is_blocked,
    segments_total_ex,delta_additional_pay_ex_vat,delta_expenses_pay_ex_vat,
    delta_travel_pay_ex_vat,delta_accommodation_pay_ex_vat,delta_other_pay_ex_vat,
    delta_mileage_pay_ex_vat,segment_deltas_json,adjustment_deltas_json,
    additional_unit_deltas_json,reservation_overrun_detected,payment_amount_ex_vat,
    payment_amount_inc_vat,payment_amount,case_resolution_summary_json,case_components_json
  )
  SELECT v_bounded_build.candidate_id,target.timesheet_id,baseline.client_id,
    baseline.ts_week_ending_date,baseline.ts_client_name,baseline.ts_pay_method,
    baseline.cand_pay_method,baseline.cand_tms_ref,baseline.cand_display_name,
    baseline.cand_umbrella_id,baseline.umb_enabled,baseline.umb_vat_chargeable,
    (baseline.cand_bank_hash IS NOT NULL AND BTRIM(baseline.cand_bank_hash)<>''),
    baseline.cand_bank_hash,
    (baseline.umb_bank_hash IS NOT NULL AND BTRIM(baseline.umb_bank_hash)<>''),
    baseline.umb_bank_hash,'BUCKETED',false,true,'Suggested Rate',
    jsonb_build_object(
      'resolve_all_linked_timesheets_default',true,
      'linked_scope_type','SELF_ONLY','linked_timesheet_count',1,
      'linked_timesheet_ids',jsonb_build_array(target.timesheet_id::text),
      'seed_timesheet_id',target.timesheet_id::text),
    0::numeric,0::numeric,0::numeric,0,0,0,0,false,false,
    0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,
    '[]'::jsonb,'[]'::jsonb,'[]'::jsonb,false,
    0::numeric,0::numeric,0::numeric,
    jsonb_build_object(
      'case_needs_resolution',false,'case_resolution_satisfied_now',true,
      'safe_amount_ex_vat',0,'blocked_case_amount_ex_vat',0,
      'unresolved_taxable_amount_ex_vat',0,
      'economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text),
    '[]'::jsonb
  FROM (
    SELECT DISTINCT component.timesheet_id
    FROM pg_temp.tmp_sync_authoritative_components component
  ) target
  JOIN pg_temp.ts_baseline baseline
    ON baseline.candidate_id=v_bounded_build.candidate_id
   AND baseline.timesheet_id=target.timesheet_id
  WHERE NOT EXISTS(
    SELECT 1 FROM pg_temp.timesheet_case_rollup_effective preview_row
    WHERE preview_row.candidate_id=v_bounded_build.candidate_id
      AND preview_row.timesheet_id=target.timesheet_id
  );
  IF EXISTS(
    SELECT 1
    FROM pg_temp.tmp_sync_authoritative_components component
    WHERE component.timesheet_id IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM pg_temp.timesheet_case_rollup_effective preview_row
        WHERE preview_row.candidate_id=v_bounded_build.candidate_id
          AND preview_row.timesheet_id=component.timesheet_id)
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_FACT_SCOPE_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  DELETE FROM pg_temp.timesheet_case_rollup_effective preview_row
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=preview_row.timesheet_id);

  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET case_components_json=COALESCE((
    SELECT jsonb_agg(component.component_json ORDER BY component.source_rank,
      component.component_ordinality,component.physical_bucket_key)
    FROM (
      SELECT 0::integer AS source_rank,raw_component.component_ordinality,
        raw_component.physical_bucket_key,
        raw_component.component_json||jsonb_strip_nulls(jsonb_build_object(
          'component_amount_ex_vat',COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),
          'source_pay_ex_vat',COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),
          'source_charge_ex_vat',sealed.source_charge_ex_vat
        )) AS component_json
      FROM pg_temp.tmp_sync_raw_preview_physical_components raw_component
      JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
        ON sealed.timesheet_id=raw_component.timesheet_id
       AND sealed.physical_bucket_key=raw_component.physical_bucket_key
       AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
      WHERE raw_component.candidate_id=preview_row.candidate_id
        AND raw_component.timesheet_id=preview_row.timesheet_id
      UNION ALL
      SELECT 1::integer,missing.bucket_sort_ordinal::bigint,
        missing.physical_bucket_key,missing.component_json
      FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
      WHERE missing.candidate_id=preview_row.candidate_id
        AND missing.timesheet_id=preview_row.timesheet_id
    ) component
  ),'[]'::jsonb)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id;

  DROP TABLE IF EXISTS pg_temp.tmp_sync_builder_physical_components;
  CREATE TEMP TABLE pg_temp.tmp_sync_builder_physical_components ON COMMIT DROP AS
  SELECT preview_row.candidate_id,preview_row.timesheet_id,
    component.ordinality::integer AS component_ordinality,component.value AS component_json,
    UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')) AS economic_key_type,
    NULLIF(BTRIM(component.value->>'component_key_value'),'') AS economic_key_value,
    concat_ws('|','RATE_BUCKET_V1',preview_row.timesheet_id::text,
      NULLIF(BTRIM(component.value->>'source_family_key'),''),
      UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')),
      NULLIF(BTRIM(component.value->>'component_key_value'),''),
      CASE
        WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'worked-time-residual:'||UPPER(BTRIM(component.value->>'component_key_type'))
            ||':'||BTRIM(component.value->>'component_key_value')
        WHEN UPPER(BTRIM(component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
          THEN COALESCE(
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_stable_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,work_date}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,date}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='ADDITIONAL_CODE'
          THEN 'additional:'||UPPER(BTRIM(component.value#>>'{source_basis_json,additional_code}'))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='EXPENSE_CODE'
          THEN 'expense:'||UPPER(BTRIM(component.value#>>'{source_basis_json,expense_code}'))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='ADJUSTMENT_CODE'
          THEN 'adjustment:'||BTRIM(component.value#>>'{source_basis_json,adjustment_id}')
      END,
      UPPER(BTRIM(COALESCE(
        CASE WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
        CASE UPPER(BTRIM(component.value->>'component_key_type'))
          WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED'
          WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
        END))))
      AS physical_bucket_key,
    md5(jsonb_build_object(
      'builder_comparison_version',1,'timesheet_id',preview_row.timesheet_id::text,
      'source_family_key',NULLIF(BTRIM(component.value->>'source_family_key'),''),
      'component_key_type',UPPER(BTRIM(component.value->>'component_key_type')),
      'component_key_value',BTRIM(component.value->>'component_key_value'),
      'segment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
      'segment_key',COALESCE(
        NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
        NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),'')),
      'segment_stable_key',NULLIF(BTRIM(
        component.value#>>'{source_basis_json,segment_stable_key}'),''),
      'work_date',NULLIF(BTRIM(COALESCE(component.value#>>'{source_basis_json,work_date}',
        component.value#>>'{source_basis_json,date}')),''),
      'ref_num',NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''),
      'additional_code',NULLIF(UPPER(BTRIM(
        component.value#>>'{source_basis_json,additional_code}')),''),
      'expense_code',NULLIF(UPPER(BTRIM(
        component.value#>>'{source_basis_json,expense_code}')),''),
      'adjustment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,adjustment_id}'),''),
      'bucket_code',UPPER(BTRIM(COALESCE(
        CASE WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
        CASE UPPER(BTRIM(component.value->>'component_key_type'))
          WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED'
          WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
        END))),
      'source_units',CASE WHEN COALESCE(component.value->>'source_units','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_units')::numeric,6) END,
      'source_rate',CASE WHEN COALESCE(component.value->>'source_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_rate')::numeric,6) END,
      'source_charge_rate',CASE WHEN COALESCE(component.value->>'source_charge_rate','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_charge_rate')::numeric,6) END,
      'source_pay_ex_vat',CASE WHEN COALESCE(component.value->>'source_pay_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_pay_ex_vat')::numeric,2) END,
      'source_charge_ex_vat',CASE WHEN COALESCE(component.value->>'source_charge_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_charge_ex_vat')::numeric,2) END,
      'source_pay_method',UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),'')),
      'target_pay_method',UPPER(NULLIF(BTRIM(
        component.value->>'current_target_pay_method'),'')))::text) AS builder_comparison_digest
  FROM pg_temp.timesheet_case_rollup_effective preview_row
  CROSS JOIN LATERAL jsonb_array_elements(CASE
    WHEN jsonb_typeof(preview_row.case_components_json)='array'
      THEN preview_row.case_components_json ELSE '[]'::jsonb END)
    WITH ORDINALITY component(value,ordinality)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id;

  SELECT failure.failure_code,failure.detail_json
  INTO v_rate_authority_failure_code,v_rate_authority_failure_detail
  FROM (
    SELECT 10 AS failure_rank,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING'::text
        AS failure_code,jsonb_build_object('timesheet_id',sealed.timesheet_id,
          'physical_bucket_key',sealed.physical_bucket_key) AS detail_json
    FROM pg_temp.tmp_sync_sealed_rate_projection sealed
    LEFT JOIN pg_temp.tmp_sync_builder_physical_components builder
      ON builder.timesheet_id=sealed.timesheet_id
     AND builder.physical_bucket_key=sealed.physical_bucket_key
    WHERE sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
      AND builder.timesheet_id IS NULL
    UNION ALL
    SELECT 20,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_EXTRA',jsonb_build_object(
      'timesheet_id',builder.timesheet_id,'physical_bucket_key',builder.physical_bucket_key)
    FROM pg_temp.tmp_sync_builder_physical_components builder
    LEFT JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
      ON sealed.timesheet_id=builder.timesheet_id
     AND sealed.physical_bucket_key=builder.physical_bucket_key
    WHERE sealed.timesheet_id IS NULL
    UNION ALL
    SELECT 30,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_DIGEST_MISMATCH',jsonb_build_object(
      'timesheet_id',sealed.timesheet_id,'physical_bucket_key',sealed.physical_bucket_key,
      'economic_key_type',sealed.economic_key_type,
      'economic_key_value',sealed.economic_key_value,
      'digest_mismatch',builder.builder_comparison_digest IS DISTINCT FROM
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}',
      'amount_mismatch',CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2)
        ELSE NULL::numeric END IS DISTINCT FROM ROUND(COALESCE(
          CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
          sealed.outstanding_ex_vat),2),
      'expected_digest',sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}',
      'actual_digest',builder.builder_comparison_digest,
      'expected_amount_ex_vat',ROUND(COALESCE(
        CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
            ~ '^-?\d+(\.\d+)?$'
          THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
        sealed.outstanding_ex_vat),2),
      'actual_amount_ex_vat',CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2) END)
    FROM pg_temp.tmp_sync_sealed_rate_projection sealed
    JOIN pg_temp.tmp_sync_builder_physical_components builder
      ON builder.timesheet_id=sealed.timesheet_id
     AND builder.physical_bucket_key=sealed.physical_bucket_key
    WHERE builder.builder_comparison_digest IS DISTINCT FROM
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}'
       OR CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2)
          ELSE NULL::numeric END IS DISTINCT FROM ROUND(COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),2)
  ) failure
  ORDER BY failure.failure_rank,
    failure.detail_json->>'timesheet_id',failure.detail_json->>'physical_bucket_key'
  LIMIT 1;

  IF v_rate_authority_failure_code IS NOT NULL THEN
    RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
      DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
        'detail',v_rate_authority_failure_detail)::text;
  END IF;

  WITH overlaid AS (
    SELECT builder.candidate_id,builder.timesheet_id,builder.component_ordinality,
      builder.component_json||jsonb_build_object(
        'component_amount_ex_vat',sealed.outstanding_ex_vat,
        'authoritative_truth_ex_vat',sealed.truth_ex_vat,
        'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
        'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
        'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
        'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
        'physical_bucket_key',sealed.physical_bucket_key,
        'physical_bucket_digest',sealed.physical_bucket_digest,
        'sealed_evidence_digest',sealed.sealed_evidence_digest,
        'financial_revision_digest',sealed.financial_revision_digest,
        'target_authority_digest',sealed.target_authority_digest,
        'conversion_context_digest',sealed.conversion_context_digest,
        'source_pay_method',sealed.source_pay_method,
        'current_target_pay_method',sealed.target_pay_method,
        'source_basis_json',(CASE
          WHEN jsonb_typeof(builder.component_json->'source_basis_json')='object'
            THEN builder.component_json->'source_basis_json'
          ELSE '{}'::jsonb END)||jsonb_build_object(
            'source_pay_method',sealed.source_pay_method))
        AS component_json
    FROM pg_temp.tmp_sync_builder_physical_components builder
    JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
      ON sealed.timesheet_id=builder.timesheet_id
     AND sealed.physical_bucket_key=builder.physical_bucket_key
  ), grouped AS (
    SELECT overlaid.candidate_id,overlaid.timesheet_id,
      jsonb_agg(overlaid.component_json ORDER BY overlaid.component_ordinality) AS components_json
    FROM overlaid GROUP BY overlaid.candidate_id,overlaid.timesheet_id
  )
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET case_components_json=grouped.components_json
  FROM grouped
  WHERE preview_row.candidate_id=grouped.candidate_id
    AND preview_row.timesheet_id=grouped.timesheet_id;

  WITH fact_totals AS (
    SELECT component.timesheet_id,
      ROUND(COALESCE(SUM(component.truth_ex_vat),0),2)::numeric(12,2) AS truth_ex_vat,
      ROUND(COALESCE(SUM(entitlement.truth_inc_vat),0),2)::numeric(12,2) AS truth_inc_vat
    FROM pg_temp.tmp_sync_authoritative_components component
    LEFT JOIN (
      SELECT legacy_component.*
      FROM private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id,NULL::text) legacy_component
      WHERE v_execution_profile_version = 1
      UNION ALL
      SELECT cached_component.*
      FROM pg_temp.tmp_sync_entitlement_components_v2 cached_component
      WHERE v_execution_profile_version = 2
    ) entitlement
      ON entitlement.timesheet_id=component.timesheet_id
     AND entitlement.key_type=component.key_type AND entitlement.key_value=component.key_value
    GROUP BY component.timesheet_id
  )
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET payment_amount_ex_vat=COALESCE(fact_totals.truth_ex_vat,0),
      payment_amount_inc_vat=COALESCE(fact_totals.truth_inc_vat,fact_totals.truth_ex_vat,0),
      payment_amount=COALESCE(fact_totals.truth_inc_vat,fact_totals.truth_ex_vat,0),
      case_total_amount_ex=COALESCE(fact_totals.truth_ex_vat,0),
      safe_amount_ex=CASE WHEN preview_row.is_blocked THEN 0 ELSE COALESCE(fact_totals.truth_ex_vat,0) END,
      case_resolution_summary_json=COALESCE(preview_row.case_resolution_summary_json,'{}'::jsonb)
        ||jsonb_build_object('economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text)
  FROM fact_totals
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND preview_row.timesheet_id=fact_totals.timesheet_id;
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET payment_amount_ex_vat=0,payment_amount_inc_vat=0,payment_amount=0,
      case_total_amount_ex=0,safe_amount_ex=0,case_components_json='[]'::jsonb,
      case_resolution_summary_json=COALESCE(preview_row.case_resolution_summary_json,'{}'::jsonb)
        ||jsonb_build_object('economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
      WHERE scope_row.build_id=p_build_id AND scope_row.timesheet_id=preview_row.timesheet_id)
    AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=preview_row.timesheet_id);

  -- Economic completeness is private build authority.  It is deliberately
  -- attested before presentation rendering so a zero-net, hidden, blocked or
  -- snoozed line is not required to invent a public row merely to prove that
  -- its physical components were preserved.
  SELECT md5(COALESCE(string_agg(
    sealed.timesheet_id::text||':'||sealed.economic_key_type||':'||
    sealed.economic_key_value||':'||sealed.physical_bucket_key||':'||
    sealed.sealed_evidence_digest,'' ORDER BY sealed.timesheet_id,
    sealed.economic_key_type,sealed.economic_key_value,sealed.bucket_sort_ordinal,
    sealed.physical_bucket_key),''))
  INTO v_bounded_economic_component_digest
  FROM pg_temp.tmp_sync_sealed_rate_projection sealed;

  v_bounded_canonical_result:=public.pay_preview_candidate_build_canonical_lines(
    v_preview_context_json,v_bounded_build.candidate_id);
  IF to_regclass('pg_temp.canonical_preview_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_LINES_MISSING' USING ERRCODE='23514';
  END IF;
  IF to_regclass('pg_temp.canonical_timesheet_presentation_state') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_STATE_MISSING' USING ERRCODE='23514';
  END IF;
  -- The renderer's protected state must cover the sealed scope exactly.  Its
  -- ready + blocked + indefinitely-hidden allocation must also reconstruct the
  -- complete private economic truth.  Case-resolution presentation is an
  -- overlay and is intentionally not added to that economic total.
  WITH economic_target AS (
    SELECT DISTINCT component.timesheet_id
    FROM pg_temp.tmp_sync_authoritative_components component
  ), fact_truth AS (
    SELECT target.timesheet_id,
      ROUND(COALESCE(SUM(component.truth_ex_vat),0),2) AS truth_ex_vat
    FROM economic_target target
    LEFT JOIN pg_temp.tmp_sync_authoritative_components component
      ON component.timesheet_id=target.timesheet_id
    GROUP BY target.timesheet_id
  ), state_row AS (
    SELECT state.timesheet_id,COUNT(*) AS state_count,
      MIN(state.amount_ex_vat) AS amount_ex_vat,
      MIN(state.ready_section_amount_ex_vat) AS ready_amount,
      MIN(state.blocked_section_amount_ex_vat) AS blocked_amount,
      MIN(state.hidden_indefinite_segment_amount_ex_vat) AS hidden_segment_amount,
      MIN(state.hidden_expense_amount_ex_vat) AS hidden_expense_amount,
      BOOL_OR(COALESCE(state.resolved_segment_rows_replace_source_total,false))
        AS resolved_segment_rows_replace_source_total,
      MIN(component_allocation.component_count) AS component_count,
      MIN(component_allocation.invalid_amount_count) AS invalid_component_amount_count,
      MIN(component_allocation.presentation_amount_ex_vat)
        AS component_presentation_amount_ex_vat
    FROM pg_temp.canonical_timesheet_presentation_state state
    LEFT JOIN LATERAL (
      SELECT COUNT(*)::integer AS component_count,
        COUNT(*) FILTER (WHERE
          COALESCE(component.value->>'ready_preview_amount_ex_vat','')
            !~ '^-?\d+(\.\d+)?$'
          AND COALESCE(component.value->>'preview_component_amount_ex_vat','')
            !~ '^-?\d+(\.\d+)?$')::integer AS invalid_amount_count,
        ROUND(COALESCE(SUM(CASE
          WHEN COALESCE(component.value->>'ready_preview_amount_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (component.value->>'ready_preview_amount_ex_vat')::numeric
          WHEN COALESCE(component.value->>'preview_component_amount_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (component.value->>'preview_component_amount_ex_vat')::numeric
          ELSE 0::numeric
        END),0),2) AS presentation_amount_ex_vat
      FROM jsonb_array_elements(CASE
        WHEN jsonb_typeof(state.case_components_json)='array'
          THEN state.case_components_json ELSE '[]'::jsonb END) component(value)
    ) component_allocation ON true
    WHERE state.candidate_id=v_bounded_build.candidate_id
    GROUP BY state.timesheet_id
  ), rollup_row AS (
    SELECT rollup.timesheet_id,COUNT(*) AS rollup_count
    FROM pg_temp.timesheet_case_rollup_effective rollup
    WHERE rollup.candidate_id=v_bounded_build.candidate_id
    GROUP BY rollup.timesheet_id
  ), canonical_line_row AS (
    SELECT line.timesheet_id,COUNT(*) AS line_count
    FROM pg_temp.canonical_timesheet_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
    GROUP BY line.timesheet_id
  ), presentation_seed_row AS (
    SELECT seed.timesheet_id,COUNT(*) AS seed_count
    FROM pg_temp.canonical_timesheet_presentation_seed seed
    WHERE seed.candidate_id=v_bounded_build.candidate_id
    GROUP BY seed.timesheet_id
  ), mismatch AS (
    SELECT
      fact.timesheet_id IS NULL AS missing_fact_target,
      state.timesheet_id IS NULL AS missing_state,
      COALESCE(state.state_count,0)<>1 AS state_multiplicity_mismatch,
      ABS(COALESCE(state.amount_ex_vat,0)-COALESCE(fact.truth_ex_vat,0))>0.01
        AS truth_amount_mismatch,
      (
        COALESCE(state.resolved_segment_rows_replace_source_total,false)
        AND (COALESCE(state.component_count,0)=0
          OR COALESCE(state.invalid_component_amount_count,0)>0)
      ) AS resolved_basis_bridge_invalid,
      ABS(COALESCE(CASE
        -- A resolved-rate presentation is intentionally target-valued while
        -- amount_ex_vat remains the sealed source economic truth.  The
        -- renderer's existing replacement marker selects the independently
        -- materialised component presentation total for this sum only.
        WHEN COALESCE(state.resolved_segment_rows_replace_source_total,false)
          THEN state.component_presentation_amount_ex_vat
        ELSE state.amount_ex_vat
      END,0)-(
        COALESCE(state.ready_amount,0)+COALESCE(state.blocked_amount,0)
        +COALESCE(state.hidden_segment_amount,0)+COALESCE(state.hidden_expense_amount,0)))>0.01
        AS allocation_sum_mismatch,
      COALESCE(rollup.rollup_count,0)>0 AS rollup_present,
      COALESCE(canonical_line.line_count,0)>0 AS canonical_line_present,
      COALESCE(presentation_seed.seed_count,0)>0 AS presentation_seed_present
    FROM fact_truth fact
    FULL OUTER JOIN state_row state USING(timesheet_id)
    LEFT JOIN rollup_row rollup USING(timesheet_id)
    LEFT JOIN canonical_line_row canonical_line USING(timesheet_id)
    LEFT JOIN presentation_seed_row presentation_seed USING(timesheet_id)
  )
  SELECT jsonb_build_object(
    'mismatch_count',count(*) FILTER (
      WHERE missing_fact_target OR missing_state OR state_multiplicity_mismatch
         OR truth_amount_mismatch OR resolved_basis_bridge_invalid
         OR allocation_sum_mismatch),
    'missing_fact_target_count',count(*) FILTER (WHERE missing_fact_target),
    'missing_state_count',count(*) FILTER (WHERE missing_state),
    'state_multiplicity_mismatch_count',count(*) FILTER (WHERE state_multiplicity_mismatch),
    'truth_amount_mismatch_count',count(*) FILTER (WHERE truth_amount_mismatch),
    'resolved_basis_bridge_invalid_count',count(*) FILTER (
      WHERE resolved_basis_bridge_invalid),
    'allocation_sum_mismatch_count',count(*) FILTER (WHERE allocation_sum_mismatch),
    'missing_state_with_rollup_count',count(*) FILTER (WHERE missing_state AND rollup_present),
    'missing_state_with_canonical_line_count',count(*) FILTER (
      WHERE missing_state AND canonical_line_present),
    'missing_state_with_presentation_seed_count',count(*) FILTER (
      WHERE missing_state AND presentation_seed_present)
  )
  INTO v_presentation_mismatch_detail
  FROM mismatch;

  IF COALESCE((v_presentation_mismatch_detail->>'mismatch_count')::integer,0)>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_ALLOCATION_AUTHORITY_MISMATCH %',
      v_presentation_mismatch_detail::text
      USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1 FROM pg_temp.canonical_preview_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
      AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
      AND (
        COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR NOT EXISTS(
          SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=p_build_id
            AND scope_row.timesheet_id=COALESCE(line.line_json->>'real_business_timesheet_id',
              line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid)
        OR UPPER(BTRIM(COALESCE(line.pay_channel::text,''))) IS DISTINCT FROM v_scope
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_FACT_AUTHORITY_MISMATCH' USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1
    FROM pg_temp.canonical_preview_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
    GROUP BY COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
      NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
      NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
      md5(line.line_json::text))
    HAVING count(*)>1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_LINE_IDENTITY_CONFLICT %', (
      WITH keyed_lines AS (
        SELECT
          COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
            NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
            NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
            md5(line.line_json::text)) AS line_identity,
          CASE
            WHEN NULLIF(BTRIM(line.line_json->>'presentation_line_id'),'') IS NOT NULL THEN 'PRESENTATION_LINE_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'preview_row_id'),'') IS NOT NULL THEN 'PREVIEW_ROW_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'line_id'),'') IS NOT NULL THEN 'LINE_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'case_key'),'') IS NOT NULL THEN 'CASE_KEY'
            ELSE 'ROW_DIGEST'
          END AS identity_source,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_role'),''),'~')) AS presentation_role,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_section'),''),'~')) AS presentation_section,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'line_type'),''),'~')) AS line_type,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'component_key_type'),''),'~')) AS component_key_type,
          UPPER(COALESCE(NULLIF(BTRIM(COALESCE(
            line.line_json->>'bucket_code',
            line.line_json#>>'{source_basis_json,bucket_code}'
          )),''),'~')) AS bucket_code
        FROM pg_temp.canonical_preview_lines line
        WHERE line.candidate_id=v_bounded_build.candidate_id
      ), duplicate_identities AS (
        SELECT keyed.line_identity,count(*)::integer AS row_count
        FROM keyed_lines keyed
        GROUP BY keyed.line_identity
        HAVING count(*)>1
      ), duplicate_rows AS (
        SELECT keyed.*
        FROM keyed_lines keyed
        JOIN duplicate_identities duplicate_identity
          ON duplicate_identity.line_identity=keyed.line_identity
      ), shape_counts AS (
        SELECT concat_ws('|',duplicate_row.identity_source,duplicate_row.presentation_role,
                 duplicate_row.presentation_section,duplicate_row.line_type,
                 duplicate_row.component_key_type,duplicate_row.bucket_code) AS shape,
               count(*)::integer AS row_count
        FROM duplicate_rows duplicate_row
        GROUP BY duplicate_row.identity_source,duplicate_row.presentation_role,
          duplicate_row.presentation_section,duplicate_row.line_type,
          duplicate_row.component_key_type,duplicate_row.bucket_code
      )
      SELECT jsonb_build_object(
        'duplicate_identity_count',(SELECT count(*)::integer FROM duplicate_identities),
        'duplicate_row_count',(SELECT count(*)::integer FROM duplicate_rows),
        'maximum_identity_multiplicity',COALESCE((SELECT max(row_count) FROM duplicate_identities),0),
        'line_shape_counts',COALESCE((SELECT jsonb_object_agg(shape,row_count ORDER BY shape)
          FROM shape_counts),'{}'::jsonb)
      )
    )::text USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    WITH expected AS (
      SELECT (allocation.value->>'timesheet_id')::uuid AS timesheet_id,
        allocation.value->>'line_identity' AS line_identity,
        allocation.value->>'parent_line_identity' AS parent_line_identity,
        allocation.value->>'presentation_section' AS presentation_section,
        allocation.value->>'pay_channel' AS pay_channel,
        ROUND((allocation.value->>'amount_ex_vat')::numeric,2) AS amount_ex_vat,
        (allocation.value->>'draftable')::boolean AS draftable,
        (allocation.value->>'excluded_from_allocation')::boolean AS excluded_from_allocation,
        ROUND((allocation.value->>'section_non_segment_amount_ex_vat')::numeric,2)
          AS section_non_segment_amount_ex_vat,
        allocation.value->'section_segment_rows' AS section_segment_rows,
        (allocation.value->>'resolved_segment_rows_replace_source_total')::boolean
          AS resolved_segment_rows_replace_source_total
      FROM pg_temp.canonical_timesheet_presentation_state state
      CROSS JOIN LATERAL jsonb_array_elements(
        private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
      WHERE state.candidate_id=v_bounded_build.candidate_id
    ), actual AS (
      SELECT COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid
          AS timesheet_id,
        COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
          NULLIF(BTRIM(line.line_json->>'line_id'),'')) AS line_identity,
        NULLIF(BTRIM(line.line_json->>'presentation_parent_line_id'),'') AS parent_line_identity,
        UPPER(NULLIF(BTRIM(line.line_json->>'presentation_section'),'')) AS presentation_section,
        UPPER(BTRIM(COALESCE(line.pay_channel::text,line.line_json->>'pay_channel',''))) AS pay_channel,
        ROUND(COALESCE(line.amount_ex_vat,0),2) AS amount_ex_vat,
        COALESCE((line.line_json->>'is_ready_for_draft')::boolean,false) AS draftable,
        COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)
          AS excluded_from_allocation,
        (
          UPPER(COALESCE(line.line_json->>'presentation_role',''))='PARENT'
          AND COALESCE((line.line_json->>'selection_allowed')::boolean,false)=false
          AND COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)=true
        ) AS semantic_non_selectable_parent,
        (
          UPPER(COALESCE(line.line_json->>'presentation_role',''))='PARENT'
          AND UPPER(COALESCE(line.line_json->>'presentation_reason',''))=
            'NEGATIVE_ORDINARY_PRESENTATION_ONLY'
          AND UPPER(COALESCE(line.line_json->>'presentation_section',''))='BLOCKED_FOR_PAY'
          AND COALESCE((line.line_json->>'selection_allowed')::boolean,false)=false
          AND COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)=true
          AND ROUND(COALESCE(line.amount_ex_vat,0),2)<0
        ) AS semantic_negative_parent,
        ROUND(COALESCE((line.line_json->>'section_non_segment_amount_ex_vat')::numeric,0),2)
          AS section_non_segment_amount_ex_vat,
        CASE WHEN jsonb_typeof(line.line_json->'section_segment_rows')='array'
          THEN line.line_json->'section_segment_rows' ELSE '[]'::jsonb END AS section_segment_rows,
        COALESCE((line.line_json->>'resolved_segment_rows_replace_source_total')::boolean,false)
          AS resolved_segment_rows_replace_source_total
      FROM pg_temp.canonical_preview_lines line
      WHERE line.candidate_id=v_bounded_build.candidate_id
        AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
        -- Semantic V3 publishes exact keyed allocation components beside the
        -- aggregate presentation parent.  The protected presentation fence
        -- continues to compare the parent only; economic component equality
        -- is independently enforced by the canonical fact-component fence
        -- immediately below.
        AND UPPER(COALESCE(line.line_json->>'presentation_role','PARENT'))
          <> 'ALLOCATION_COMPONENT'
        AND COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT 1
    FROM expected
    FULL OUTER JOIN actual USING(timesheet_id,line_identity)
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
       OR actual.parent_line_identity IS DISTINCT FROM expected.parent_line_identity
       OR (
         actual.presentation_section IS DISTINCT FROM expected.presentation_section
         AND NOT (
           actual.semantic_negative_parent
           AND actual.presentation_section='BLOCKED_FOR_PAY'
           AND expected.presentation_section='READY_TO_PAY'
         )
       )
       OR actual.pay_channel IS DISTINCT FROM expected.pay_channel
       OR ABS(actual.amount_ex_vat-expected.amount_ex_vat)>0.01
       OR (
         actual.semantic_non_selectable_parent
         AND actual.draftable IS DISTINCT FROM false
       )
       OR (
         NOT actual.semantic_non_selectable_parent
         AND actual.draftable IS DISTINCT FROM expected.draftable
       )
       OR (
         NOT actual.semantic_non_selectable_parent
         AND actual.excluded_from_allocation IS DISTINCT FROM expected.excluded_from_allocation
       )
       OR ABS(actual.section_non_segment_amount_ex_vat-
         expected.section_non_segment_amount_ex_vat)>0.01
       OR actual.section_segment_rows IS DISTINCT FROM expected.section_segment_rows
       OR actual.resolved_segment_rows_replace_source_total IS DISTINCT FROM
         expected.resolved_segment_rows_replace_source_total
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_ALLOCATION_MISMATCH'
      USING ERRCODE='23514';
  END IF;
  SELECT md5(COALESCE(string_agg(allocation.value::text,'' ORDER BY
    allocation.value->>'timesheet_id',allocation.value->>'line_identity'),''))
  INTO v_bounded_presentation_allocation_digest
  FROM pg_temp.canonical_timesheet_presentation_state state
  CROSS JOIN LATERAL jsonb_array_elements(
    private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
  WHERE state.candidate_id=v_bounded_build.candidate_id;
  IF EXISTS(
    WITH expected AS (
      SELECT sealed.timesheet_id,sealed.economic_key_type AS key_type,
        sealed.economic_key_value AS key_value,sealed.physical_bucket_key,
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}'
          AS builder_comparison_digest,
        sealed.outstanding_ex_vat AS component_amount_ex_vat,
        sealed.truth_ex_vat,sealed.baseline_ex_vat,sealed.reserved_ex_vat,
        sealed.outstanding_ex_vat,sealed.physical_bucket_digest,
        sealed.sealed_evidence_digest,sealed.financial_revision_digest,
        sealed.target_authority_digest,sealed.conversion_context_digest
      FROM pg_temp.tmp_sync_sealed_rate_projection sealed
      WHERE sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
    ), actual_lines AS (
      SELECT COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid AS timesheet_id,
        COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
          NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
          NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
          md5(line.line_json::text)) AS line_identity,
        CASE WHEN jsonb_typeof(line.line_json->'case_components')='array'
          THEN line.line_json->'case_components' ELSE '[]'::jsonb END AS components_json
      FROM pg_temp.canonical_preview_lines line
      WHERE line.candidate_id=v_bounded_build.candidate_id
        AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
        AND COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), expected_presentation_timesheets AS (
      SELECT DISTINCT (allocation.value->>'timesheet_id')::uuid AS timesheet_id
      FROM pg_temp.canonical_timesheet_presentation_state state
      CROSS JOIN LATERAL jsonb_array_elements(
        private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
      WHERE state.candidate_id=v_bounded_build.candidate_id
    ), actual_occurrence AS (
      SELECT actual_line.timesheet_id,actual_line.line_identity,
        UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')) AS key_type,
        NULLIF(BTRIM(component.value->>'component_key_value'),'') AS key_value,
        NULLIF(BTRIM(component.value->>'physical_bucket_key'),'') AS physical_bucket_key,
        md5(jsonb_build_object(
          'builder_comparison_version',1,
          'timesheet_id',actual_line.timesheet_id::text,
          'source_family_key',NULLIF(BTRIM(component.value->>'source_family_key'),''),
          'component_key_type',UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')),
          'component_key_value',NULLIF(BTRIM(component.value->>'component_key_value'),''),
          'segment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
          'segment_key',COALESCE(
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),'')),
          'segment_stable_key',NULLIF(BTRIM(
            component.value#>>'{source_basis_json,segment_stable_key}'),''),
          'work_date',NULLIF(BTRIM(COALESCE(component.value#>>'{source_basis_json,work_date}',
            component.value#>>'{source_basis_json,date}')),''),
          'ref_num',NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''),
          'additional_code',NULLIF(UPPER(BTRIM(
            component.value#>>'{source_basis_json,additional_code}')),''),
          'expense_code',NULLIF(UPPER(BTRIM(
            component.value#>>'{source_basis_json,expense_code}')),''),
          'adjustment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,adjustment_id}'),''),
          'bucket_code',UPPER(BTRIM(COALESCE(
            CASE WHEN UPPER(BTRIM(COALESCE(
                component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
              THEN 'FIXED' END,
            NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
            CASE UPPER(BTRIM(component.value->>'component_key_type'))
              WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
              WHEN 'EXPENSE_CODE' THEN 'FIXED'
              WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
            END))),
          'source_units',CASE WHEN COALESCE(component.value->>'source_units','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_units')::numeric,6) END,
          'source_rate',CASE WHEN COALESCE(component.value->>'source_rate','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_rate')::numeric,6) END,
          'source_charge_rate',CASE WHEN COALESCE(component.value->>'source_charge_rate','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_charge_rate')::numeric,6) END,
          'source_pay_ex_vat',CASE WHEN COALESCE(component.value->>'source_pay_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_pay_ex_vat')::numeric,2) END,
          'source_charge_ex_vat',CASE WHEN COALESCE(component.value->>'source_charge_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_charge_ex_vat')::numeric,2) END,
          'source_pay_method',UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),'')),
          'target_pay_method',UPPER(NULLIF(BTRIM(
            component.value->>'current_target_pay_method'),'')))::text)
          AS builder_comparison_digest,
        CASE WHEN COALESCE(component.value->>'component_amount_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'component_amount_ex_vat')::numeric,2) END
          AS component_amount_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_truth_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_truth_ex_vat')::numeric,2) END
          AS truth_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_baseline_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_baseline_ex_vat')::numeric,2) END
          AS baseline_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_reserved_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_reserved_ex_vat')::numeric,2) END
          AS reserved_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_outstanding_ex_vat')::numeric,2) END
          AS outstanding_ex_vat,
        NULLIF(BTRIM(component.value->>'physical_bucket_digest'),'') AS physical_bucket_digest,
        NULLIF(BTRIM(component.value->>'sealed_evidence_digest'),'') AS sealed_evidence_digest,
        NULLIF(BTRIM(component.value->>'financial_revision_digest'),'') AS financial_revision_digest,
        NULLIF(BTRIM(component.value->>'target_authority_digest'),'') AS target_authority_digest,
        NULLIF(BTRIM(component.value->>'conversion_context_digest'),'') AS conversion_context_digest
      FROM actual_lines actual_line
      CROSS JOIN LATERAL jsonb_array_elements(actual_line.components_json) component(value)
    ), conflicting_actual AS (
      SELECT timesheet_id,line_identity,physical_bucket_key
      FROM actual_occurrence
      GROUP BY timesheet_id,line_identity,physical_bucket_key
      HAVING physical_bucket_key IS NULL
        OR bool_or(key_type IS NULL OR key_value IS NULL OR
          builder_comparison_digest IS NULL OR physical_bucket_digest IS NULL OR
          sealed_evidence_digest IS NULL)
        OR count(*)>1
        OR count(DISTINCT jsonb_build_object('key_type',key_type,'key_value',key_value,
          'builder_comparison_digest',builder_comparison_digest,
          'component_amount_ex_vat',component_amount_ex_vat,'truth_ex_vat',truth_ex_vat,
          'baseline_ex_vat',baseline_ex_vat,'reserved_ex_vat',reserved_ex_vat,
          'outstanding_ex_vat',outstanding_ex_vat,
          'physical_bucket_digest',physical_bucket_digest,
          'sealed_evidence_digest',sealed_evidence_digest,
          'financial_revision_digest',financial_revision_digest,
          'target_authority_digest',target_authority_digest,
          'conversion_context_digest',conversion_context_digest))>1
    ), actual AS (
      -- Presentation splitting may repeat one identical physical component on
      -- several stable lines.  Collapse only after per-line duplicate and
      -- conflict checks have succeeded; never collapse DAY and NIGHT together.
      SELECT DISTINCT timesheet_id,key_type,key_value,physical_bucket_key,
        builder_comparison_digest,component_amount_ex_vat,truth_ex_vat,
        baseline_ex_vat,reserved_ex_vat,outstanding_ex_vat,
        physical_bucket_digest,sealed_evidence_digest,financial_revision_digest,
        target_authority_digest,conversion_context_digest
      FROM actual_occurrence
    ), expected_rendered AS (
      SELECT expected.* FROM expected
      JOIN expected_presentation_timesheets USING(timesheet_id)
    )
    SELECT 1 FROM conflicting_actual
    UNION ALL
    SELECT 1 FROM expected_rendered expected
      FULL OUTER JOIN actual USING(timesheet_id,key_type,key_value,physical_bucket_key)
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
       OR actual.builder_comparison_digest IS DISTINCT FROM expected.builder_comparison_digest
       OR actual.component_amount_ex_vat IS DISTINCT FROM expected.component_amount_ex_vat
       OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
       OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
       OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
       OR actual.outstanding_ex_vat IS DISTINCT FROM expected.outstanding_ex_vat
       OR actual.physical_bucket_digest IS DISTINCT FROM expected.physical_bucket_digest
       OR actual.sealed_evidence_digest IS DISTINCT FROM expected.sealed_evidence_digest
       OR actual.financial_revision_digest IS DISTINCT FROM expected.financial_revision_digest
       OR actual.target_authority_digest IS DISTINCT FROM expected.target_authority_digest
       OR actual.conversion_context_digest IS DISTINCT FROM expected.conversion_context_digest
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_PHYSICAL_FENCE_MISMATCH' USING ERRCODE='P0001';
  END IF;

  v_canonical_render_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  DELETE FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
  v_bounded_canonical_stage_timestamp:=clock_timestamp();
  INSERT INTO private.banking_pay_workbench_canonical_stage_lines(
    build_id,source_ordinal,session_id,candidate_id,session_version,source_change_seq,
    source_build_run_id,timesheet_id,line_key,parent_line_key,split_suffix,section,
    source_row_json,economic_key_json,contract_json,pay_channel_scope,
    refresh_scope_kind,row_digest,stage_status,verified_at_utc,created_at_utc
  )
  SELECT p_build_id,
    row_number() OVER(ORDER BY public.pay_workbench_preview_section_from_line_json(line.line_json),
      COALESCE(line.line_json->>'preview_row_id',line.line_json->>'line_id',
        line.line_json->>'case_key',md5(line.line_json::text)))::bigint,
    v_bounded_build.session_id,v_bounded_build.candidate_id,v_bounded_build.session_version,
    v_bounded_build.source_change_seq,v_bounded_build.source_build_run_id,
    CASE WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
      line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(line.line_json->>'real_business_timesheet_id',
        line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid ELSE NULL END,
    COALESCE(NULLIF(btrim(line.line_json->>'preview_row_id'),''),
      NULLIF(btrim(line.line_json->>'line_id'),''),NULLIF(btrim(line.line_json->>'case_key'),''),
      md5(line.line_json::text)),
    NULLIF(btrim(line.line_json->>'parent_line_key'),''),
    NULLIF(btrim(line.line_json->>'split_suffix'),''),
    public.pay_workbench_preview_section_from_line_json(line.line_json),line.line_json,
    CASE WHEN jsonb_typeof(line.line_json->'economic_key')='object'
      THEN line.line_json->'economic_key' ELSE '{}'::jsonb END,
    CASE WHEN jsonb_typeof(line.line_json->'contract_json')='object'
      THEN line.line_json->'contract_json'
      WHEN jsonb_typeof(line.line_json->'contract')='object' THEN line.line_json->'contract'
      ELSE '{}'::jsonb END,
    v_scope,'BOUNDED_ECONOMIC_BUILD',md5(line.line_json::text),'VERIFIED',
    v_bounded_canonical_stage_timestamp,v_bounded_canonical_stage_timestamp
  FROM pg_temp.canonical_preview_lines line
  WHERE line.candidate_id=v_bounded_build.candidate_id;

  SELECT count(*)::integer,
         md5(COALESCE(string_agg(row_digest,'' ORDER BY source_ordinal),''))
  INTO v_bounded_canonical_count,v_bounded_canonical_digest
  FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;

  SELECT md5(jsonb_build_object(
    'candidate_id',v_bounded_build.candidate_id,'case_count',count(*),
    'case_digest',md5(COALESCE(string_agg(md5(to_jsonb(case_row)::text),'' ORDER BY case_row.id),''))
  )::text)
  INTO v_bounded_post_sync_digest
  FROM public.pay_advances case_row WHERE case_row.candidate_id=v_bounded_build.candidate_id;

  v_canonical_stage_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

  UPDATE private.banking_pay_workbench_economic_builds
  SET status='RECONCILED',private_stage='SOURCE_PUBLISH',fact_count=v_bounded_fact_count,
      pre_sync_digest=v_bounded_pre_sync_digest,post_sync_digest=v_bounded_post_sync_digest,
      canonical_count=v_bounded_canonical_count,canonical_digest=v_bounded_canonical_digest,
      attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
        'version',1,'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
        'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_count',v_bounded_scope_count,
        'fact_count',v_bounded_fact_count,'canonical_count',v_bounded_canonical_count,
        'effect_plan_sealed',true,
        'effect_plan_count',COALESCE((v_bounded_build.attestation_json->>'effect_plan_count')::integer,0),
        'effect_plan_digest',v_bounded_build.attestation_json->>'effect_plan_digest',
        'effect_plan_created_at_utc',v_bounded_build.attestation_json->'effect_plan_created_at_utc',
        'observed_finance_effect_count',v_observed_effect_count,
        'observed_finance_effect_digest',v_observed_effect_digest,
        'economic_component_digest',v_bounded_economic_component_digest,
        'presentation_allocation_digest',v_bounded_presentation_allocation_digest,
        'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
        'canonical_digest',v_bounded_canonical_digest,
        'reconcile_execute_timing_json',jsonb_build_object(
          'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
          'workspace_cache_ms',v_workspace_cache_ms,
          'freshness_set_ms',v_freshness_set_ms,
          'authoritative_components_ms',v_authoritative_components_ms,
          'preflight_setup_ms',v_preflight_setup_ms,
          'correction_residuals_ms',v_correction_residuals_ms,
          'authority_validation_ms',v_authority_validation_ms,
          'component_assembly_ms',v_component_assembly_ms,
          'preview_workspace_ms',v_preview_workspace_ms,
          'preview_collect_ms',v_preview_collect_ms,
          'preview_canonical_ms',v_preview_canonical_ms,
          'preview_summary_ms',v_preview_summary_ms,
          'case_workspace_ms',v_case_workspace_ms,
          'finance_apply_ms',v_finance_apply_ms,
          'post_freshness_ms',v_post_freshness_ms,
          'canonical_render_ms',v_canonical_render_ms,
          'canonical_stage_ms',v_canonical_stage_ms,
          'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
      reconciled_at_utc=clock_timestamp(),publication_cursor_json=jsonb_build_object(
        'cursor_kind','SOURCE_PUBLISH','cursor_version',1,'build_id',p_build_id,
        'candidate_id',v_bounded_build.candidate_id,'canonical_count',v_bounded_canonical_count,
        'canonical_digest',v_bounded_canonical_digest),updated_at_utc=clock_timestamp()
  WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
  IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;

  RETURN jsonb_build_object(
    'ok',true,'public_result_json',v_public_result_json,
    'internal_result_json',jsonb_build_object(
      'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_timesheet_count',v_bounded_scope_count,
      'fact_count',v_bounded_fact_count,'canonical_stage_count',v_bounded_canonical_count,
      'economic_component_digest',v_bounded_economic_component_digest,
      'presentation_allocation_digest',v_bounded_presentation_allocation_digest,
      'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
      'canonical_digest',v_bounded_canonical_digest,
      'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
      'freshness_set_ms',v_freshness_set_ms,
      'workspace_cache_ms',v_workspace_cache_ms,
      'authoritative_components_ms',v_authoritative_components_ms,
      'preflight_setup_ms',v_preflight_setup_ms,
      'correction_residuals_ms',v_correction_residuals_ms,
      'authority_validation_ms',v_authority_validation_ms,
      'component_assembly_ms',v_component_assembly_ms,
      'preview_workspace_ms',v_preview_workspace_ms,
      'preview_collect_ms',v_preview_collect_ms,
      'preview_canonical_ms',v_preview_canonical_ms,
      'preview_summary_ms',v_preview_summary_ms,
      'case_workspace_ms',v_case_workspace_ms,
      'finance_apply_ms',v_finance_apply_ms,
      'post_freshness_ms',v_post_freshness_ms,
      'canonical_render_ms',v_canonical_render_ms,
      'canonical_stage_ms',v_canonical_stage_ms,
      'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer),
    'build_id',p_build_id,'attempt_id',p_attempt_id,
    'scope_timesheet_count',v_bounded_scope_count,
    'canonical_stage_count',v_bounded_canonical_count,
    'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
    'canonical_digest',v_bounded_canonical_digest
  );
exception
  when others then
    GET STACKED DIAGNOSTICS
      v_exception_detail = PG_EXCEPTION_DETAIL,
      v_exception_context = PG_EXCEPTION_CONTEXT;
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'pay_date', p_pay_date,
        'week_ending_cutoff', p_week_ending_cutoff,
        'pay_channel_scope', p_pay_channel_scope,
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM,
        'exception_detail', NULLIF(v_exception_detail, ''),
        'exception_context', NULLIF(v_exception_context, '')
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    IF SQLSTATE = '23514'
       AND SQLERRM = 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
        jsonb_build_object(
          'source',COALESCE(
            substring(v_exception_context FROM 'PL/pgSQL function [^\n]+'),
            'UNKNOWN_EFFECT_ATTESTATION_SOURCE'),
          'has_detail',NULLIF(v_exception_detail,'') IS NOT NULL
        )::text
        USING ERRCODE='23514';
    END IF;
    RAISE;
end;
$function$;

-- private.pay_workbench_cancel_reversion_admission_page_v1(uuid,uuid,uuid,uuid[],jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_cancel_reversion_admission_page_v1(p_correction_request_id uuid, p_operation_id uuid, p_session_id uuid, p_work_item_ids uuid[], p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT private.pay_workbench_cancel_reversion_proof_core_v1(
    p_correction_request_id,p_operation_id,p_session_id,p_work_item_ids,
    pg_catalog.upper(pg_catalog.btrim(COALESCE(p_options_json->>'mode','POST_FINANCIAL'))),
    COALESCE(p_options_json,'{}'::jsonb)-'mode'
  );
$function$;

-- private.pay_workbench_cancel_reversion_proof_core_v1(uuid,uuid,uuid,uuid[],text,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_cancel_reversion_proof_core_v1(p_correction_request_id uuid, p_operation_id uuid, p_session_id uuid, p_work_item_ids uuid[], p_mode text, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_count integer := 0;
  v_results jsonb := '[]'::jsonb;
  v_publication_identity_enforce_enabled boolean := false;
  v_mode text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode,'POST_FINANCIAL')));
  v_pre_request_status_page jsonb := '{}'::jsonb;
  v_unsent_overlay_proof jsonb := '{}'::jsonb;
BEGIN
  SELECT COALESCE(setting.banking_pay_source_publication_identity_enforce_v1_enabled,false)
  INTO v_publication_identity_enforce_enabled
  FROM public.settings_defaults AS setting
  WHERE setting.id=1;

  IF p_work_item_ids IS NULL OR pg_catalog.cardinality(p_work_item_ids) > 100
     OR v_mode NOT IN ('PRE_REQUEST','DRAFT_OVERLAY_PREFLIGHT','PRE_FINANCIAL','POST_FINANCIAL','OBSERVE_ONLY')
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'CANCELLATION_REVERSION_ADMISSION_ARGUMENT_INVALID'
      USING ERRCODE='P0001', DETAIL=pg_catalog.jsonb_build_object(
        'code','CANCELLATION_REVERSION_ADMISSION_ARGUMENT_INVALID'
      )::text;
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_object_keys(COALESCE(p_options_json,'{}'::jsonb)) AS option_key(key)
    WHERE option_key.key NOT IN ('candidate_ids','pay_batch_id','overlay_proof_mode')
  ) OR (
    v_mode='PRE_REQUEST'
    AND (
      p_operation_id IS NOT NULL
      OR COALESCE(p_options_json->>'overlay_proof_mode','PRE_REQUEST')
           NOT IN ('PRE_REQUEST','REQUEST_OWNED_CONTINUITY')
      OR (COALESCE(p_options_json->>'overlay_proof_mode','PRE_REQUEST')='PRE_REQUEST'
          AND p_correction_request_id IS NOT NULL)
      OR (COALESCE(p_options_json->>'overlay_proof_mode','PRE_REQUEST')='REQUEST_OWNED_CONTINUITY'
          AND p_correction_request_id IS NULL)
      OR COALESCE(p_options_json->>'pay_batch_id','')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR pg_catalog.jsonb_typeof(COALESCE(p_options_json->'candidate_ids','[]'::jsonb))<>'array'
      OR pg_catalog.jsonb_array_length(COALESCE(p_options_json->'candidate_ids','[]'::jsonb))<1
      OR pg_catalog.jsonb_array_length(COALESCE(p_options_json->'candidate_ids','[]'::jsonb))>100
    )
  ) OR (
    v_mode='DRAFT_OVERLAY_PREFLIGHT'
    AND (
      pg_catalog.jsonb_typeof(COALESCE(p_options_json->'candidate_ids','[]'::jsonb))<>'array'
      OR pg_catalog.jsonb_array_length(COALESCE(p_options_json->'candidate_ids','[]'::jsonb))<1
      OR pg_catalog.jsonb_array_length(COALESCE(p_options_json->'candidate_ids','[]'::jsonb))>100
    )
  ) OR (
    v_mode NOT IN ('PRE_REQUEST','DRAFT_OVERLAY_PREFLIGHT')
    AND (
      p_correction_request_id IS NULL OR p_operation_id IS NULL OR p_session_id IS NULL
      OR pg_catalog.cardinality(p_work_item_ids)<1
    )
  ) OR (
    v_mode='DRAFT_OVERLAY_PREFLIGHT'
    AND (p_correction_request_id IS NULL OR p_operation_id IS NULL OR p_session_id IS NULL)
  ) THEN
    RAISE EXCEPTION 'CANCELLATION_REVERSION_ADMISSION_ARGUMENT_INVALID'
      USING ERRCODE='P0001', DETAIL=pg_catalog.jsonb_build_object(
        'code','CANCELLATION_REVERSION_ADMISSION_ARGUMENT_INVALID','mode',v_mode
      )::text;
  END IF;

  -- PRE_REQUEST is the shared, read-only scheduled-reversion proof.  The
  -- immutable Draft source remains the Policy X payment authority.  A later
  -- scheduled source is accepted only when its current certified publication
  -- is exact and every non-overlay economic fact family is byte/economically
  -- identical to the original Draft economic build.  The intentionally
  -- excluded families are the closed set changed by an unsent payment overlay
  -- (allocation, expected effects, finance-item/component reservation state).
  IF v_mode='PRE_REQUEST' THEN
    -- Reuse the exact Current Payment Status cancelability classifier.  This
    -- closes provider/rail/outcome evidence without reproducing that large
    -- closed-world decision engine in this proof function.
    v_pre_request_status_page:=public.pay_batch_payment_status_page_v1(
      (p_options_json->>'pay_batch_id')::uuid,NULL::uuid,
      pg_catalog.jsonb_build_object(
        'included_candidate_tokens',COALESCE((
          SELECT pg_catalog.jsonb_agg(batch_candidate.id::text ORDER BY batch_candidate.id)
          FROM public.pay_batch_candidates AS batch_candidate
          WHERE batch_candidate.pay_batch_id=(p_options_json->>'pay_batch_id')::uuid
            AND batch_candidate.candidate_id IN (
              SELECT candidate_value.value::uuid
              FROM pg_catalog.jsonb_array_elements_text(p_options_json->'candidate_ids')
                AS candidate_value(value)
              WHERE candidate_value.value
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            )
        ),'[]'::jsonb)
      ),'STATUS','ASC',100,NULL::jsonb
    );

    v_unsent_overlay_proof:=private.pay_workbench_unsent_execution_overlay_proof_page_v1(
      (p_options_json->>'pay_batch_id')::uuid,
      ARRAY(
        SELECT candidate_value.value::uuid
        FROM pg_catalog.jsonb_array_elements_text(p_options_json->'candidate_ids')
          WITH ORDINALITY AS candidate_value(value,ordinality)
        WHERE candidate_value.value
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ORDER BY candidate_value.ordinality
      ),COALESCE(p_options_json->>'overlay_proof_mode','PRE_REQUEST'),
      p_correction_request_id,'{}'::jsonb
    );

    WITH requested_candidates AS (
      SELECT candidate_value.value::uuid AS candidate_id,candidate_value.ordinality
      FROM pg_catalog.jsonb_array_elements_text(p_options_json->'candidate_ids')
        WITH ORDINALITY AS candidate_value(value,ordinality)
      WHERE candidate_value.value
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), authority AS (
      SELECT
        requested_candidates.ordinality,
        requested_candidates.candidate_id,
        batch_candidate.id AS pay_batch_candidate_id,
        batch_row.id AS pay_batch_id,
        batch_row.source_workbench_session_id AS session_id,
        batch_row.source_session_version AS session_version,
        pg_catalog.upper(pg_catalog.btrim(COALESCE(batch_row.status,''))) AS batch_status,
        pg_catalog.upper(pg_catalog.btrim(COALESCE(batch_row.execution_commit_state,'NOT_SUBMITTED')))
          AS execution_commit_state,
        batch_candidate.settlement_status,
        batch_candidate.settled_at_utc,
        draft_operation.id AS draft_operation_id,
        draft_scope.allocation_basis_json,
        draft_scope.allocation_basis_json->'source_publication_attestation' AS frozen_attestation,
        draft_scope.allocation_basis_json->>'source_publication_id' AS frozen_source_publication_id,
        draft_scope.allocation_basis_json->'post_draft_authority' AS post_draft_authority,
        COALESCE(change_counter.seq,0) AS live_source_change_seq,
        COALESCE(change_counter.scope_change_generation,0) AS live_dirty_generation,
        registry.current_source_change_seq AS registry_source_change_seq,
        registry.dirty_generation AS registry_dirty_generation,
        candidate_state.source_change_seq AS candidate_state_source_change_seq,
        candidate_state.session_version AS candidate_state_session_version,
        current_scope.certified_preview_publication_source_change_seq AS publication_source_change_seq,
        current_scope.certified_preview_publication_source_build_run_id AS publication_source_build_run_id,
        current_scope.certified_preview_publication_source_publication_id AS publication_id,
        current_scope.certified_preview_publication_attestation_json AS current_attestation,
        current_scope.certified_preview_publication_parity_ok AS current_parity,
        original_build.id AS original_economic_build_id,
        COALESCE(current_build.id,refresh_owner_build.id) AS current_economic_build_id,
        CASE WHEN refresh_owner_build.id IS NOT NULL THEN original_build.id ELSE current_build.id END
          AS invariant_current_economic_build_id,
        COALESCE((cancelability_row.value->>'pre_provider_cancel_eligible')::boolean,false)
          AS pre_provider_cancel_eligible,
        COALESCE(cancelability_row.value->'available_actions','[]'::jsonb)
          AS current_available_actions,
        COALESCE((overlay_row.value->>'admitted')::boolean,false) AS exact_unsent_overlay,
        COALESCE(overlay_row.value->>'currentness_basis','')
          ='EXACT_UNSENT_EXECUTION_REFRESH_OWNER' AS exact_execution_refresh_owner,
        overlay_row.value AS unsent_overlay_authority
      FROM requested_candidates
      JOIN public.pay_batches AS batch_row
        ON batch_row.id=(p_options_json->>'pay_batch_id')::uuid
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id=batch_row.id
       AND batch_candidate.candidate_id=requested_candidates.candidate_id
      LEFT JOIN LATERAL (
        SELECT operation_row.id
        FROM public.banking_pay_operations AS operation_row
        WHERE operation_row.operation_type='DRAFT_CREATE'
          AND operation_row.status='COMPLETE'
          AND (
            operation_row.pay_batch_id=batch_row.id
            OR EXISTS (
              SELECT 1
              FROM public.banking_pay_operation_candidate_scope AS operation_scope_link
              WHERE operation_scope_link.operation_id=operation_row.id
                AND operation_scope_link.candidate_id=requested_candidates.candidate_id
                AND operation_scope_link.pay_batch_id=batch_row.id
                AND operation_scope_link.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
            )
          )
        ORDER BY operation_row.completed_at_utc DESC NULLS LAST,operation_row.created_at_utc DESC
        LIMIT 1
      ) AS draft_operation ON true
      LEFT JOIN public.banking_pay_operation_candidate_scope AS draft_scope
        ON draft_scope.operation_id=draft_operation.id
       AND draft_scope.candidate_id=requested_candidates.candidate_id
       AND draft_scope.pay_batch_id=batch_row.id
       AND draft_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
      LEFT JOIN public.app_change_counters AS change_counter
        ON change_counter.entity_key='pay_candidate:'||requested_candidates.candidate_id::text
      LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
        ON registry.candidate_id=requested_candidates.candidate_id
      LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
        ON candidate_state.session_id=batch_row.source_workbench_session_id
       AND candidate_state.candidate_id=requested_candidates.candidate_id
      LEFT JOIN public.banking_pay_workbench_session_scope AS current_scope
        ON current_scope.session_id=batch_row.source_workbench_session_id
       AND current_scope.candidate_id=requested_candidates.candidate_id
      LEFT JOIN private.banking_pay_workbench_economic_builds AS original_build
        ON original_build.id=CASE
          WHEN COALESCE(draft_scope.allocation_basis_json
            #>>'{source_publication_attestation,economic_build_id}','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (draft_scope.allocation_basis_json
            #>>'{source_publication_attestation,economic_build_id}')::uuid
          ELSE NULL::uuid END
       LEFT JOIN private.banking_pay_workbench_economic_builds AS current_build
        ON current_build.id=CASE
          WHEN COALESCE(current_scope.certified_preview_publication_attestation_json
            ->>'economic_build_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (current_scope.certified_preview_publication_attestation_json
            ->>'economic_build_id')::uuid
          ELSE NULL::uuid END
       AND current_build.session_id=batch_row.source_workbench_session_id
       AND current_build.candidate_id=requested_candidates.candidate_id
       AND current_build.status='COMPLETE'
      LEFT JOIN LATERAL (
        SELECT status_row.value
        FROM pg_catalog.jsonb_array_elements(
          COALESCE(v_pre_request_status_page->'rows','[]'::jsonb)
        ) AS status_row(value)
        WHERE status_row.value->>'candidate_id'=requested_candidates.candidate_id::text
        LIMIT 1
      ) AS cancelability_row ON true
      LEFT JOIN LATERAL (
        SELECT overlay_result.value
        FROM pg_catalog.jsonb_array_elements(
          COALESCE(v_unsent_overlay_proof->'candidate_results','[]'::jsonb)
        ) AS overlay_result(value)
        WHERE overlay_result.value->>'candidate_id'=requested_candidates.candidate_id::text
        LIMIT 1
      ) AS overlay_row ON true
      LEFT JOIN private.banking_pay_workbench_economic_builds AS refresh_owner_build
        ON refresh_owner_build.id=CASE
          WHEN COALESCE(overlay_row.value
            #>>'{execution_refresh_owner_authority,owner_economic_build_id}','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (overlay_row.value
            #>>'{execution_refresh_owner_authority,owner_economic_build_id}')::uuid
          ELSE NULL::uuid END
       AND refresh_owner_build.session_id=batch_row.source_workbench_session_id
       AND refresh_owner_build.candidate_id=requested_candidates.candidate_id
       AND pg_catalog.upper(pg_catalog.btrim(COALESCE(refresh_owner_build.status,''))) IN (
         'COLLECTING','READY_FOR_RECONCILIATION','RECONCILING','RECONCILED',
         'PUBLISHING','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE'
       )
    ), family_proof AS (
      SELECT
        authority.*,
        COALESCE(family_compare.invariant_family_count,0) AS invariant_family_count,
        COALESCE(family_compare.invariant_family_mismatch_count,0) AS invariant_family_mismatch_count,
        family_compare.invariant_economic_digest
      FROM authority
      LEFT JOIN LATERAL (
        WITH required_family(fact_family) AS (
          VALUES ('CANONICAL_INPUT'),('DEPENDENCY_EDGE'),('ENTITLEMENT_COMPONENT'),
            ('FINANCE_CASE_IDENTITY'),('FROZEN_SETTLED_COMPONENT'),('LIVE_ENTITLEMENT_INPUT'),
            ('PAYEE_BASELINE_INPUT'),('PROTECTION_EVIDENCE')
        ), per_build AS (
          SELECT
            fact.build_id,fact.fact_family,pg_catalog.count(*)::integer AS fact_count,
            pg_catalog.md5(COALESCE(pg_catalog.string_agg(
              fact.natural_key||E'\x1f'||COALESCE(fact.source_relation,'')||E'\x1f'||
              COALESCE(fact.source_id::text,'')||E'\x1f'||COALESCE(fact.source_subkey,'')||E'\x1f'||
              COALESCE(fact.economic_key_type,'')||E'\x1f'||COALESCE(fact.economic_key_value,'')||E'\x1f'||
              COALESCE(fact.truth_ex_vat::text,'')||E'\x1f'||COALESCE(fact.truth_inc_vat::text,'')||E'\x1f'||
              COALESCE(fact.amount_ex_vat::text,'')||E'\x1f'||COALESCE(fact.amount_inc_vat::text,'')||E'\x1f'||
              COALESCE(fact.baseline_ex_vat::text,'')||E'\x1f'||COALESCE(fact.baseline_inc_vat::text,'')||E'\x1f'||
              COALESCE(fact.finance_case_id::text,'')||E'\x1f'||COALESCE(fact.finance_component_id::text,'')||E'\x1f'||
              COALESCE(fact.reservation_id::text,''),E'\x1e' ORDER BY fact.natural_key
            ),'')) AS family_digest
          FROM private.banking_pay_workbench_economic_build_facts AS fact
          JOIN required_family ON required_family.fact_family=fact.fact_family
          WHERE fact.build_id IN (
            authority.original_economic_build_id,authority.invariant_current_economic_build_id
          )
          GROUP BY fact.build_id,fact.fact_family
        ), compared AS (
          SELECT required_family.fact_family,
            original.fact_count AS original_count,current_fact.fact_count AS current_count,
            original.family_digest AS original_digest,current_fact.family_digest AS current_digest
          FROM required_family
          LEFT JOIN per_build AS original
            ON original.build_id=authority.original_economic_build_id
           AND original.fact_family=required_family.fact_family
          LEFT JOIN per_build AS current_fact
            ON current_fact.build_id=authority.invariant_current_economic_build_id
           AND current_fact.fact_family=required_family.fact_family
        )
        SELECT pg_catalog.count(*)::integer AS invariant_family_count,
          pg_catalog.count(*) FILTER (WHERE original_count IS DISTINCT FROM current_count
            OR original_digest IS DISTINCT FROM current_digest)::integer AS invariant_family_mismatch_count,
          pg_catalog.md5(COALESCE(pg_catalog.string_agg(
            fact_family||':'||COALESCE(original_count::text,'')||':'||COALESCE(original_digest,''),
            '|' ORDER BY fact_family
          ),'')) AS invariant_economic_digest
        FROM compared
      ) AS family_compare ON true
    ), classified AS (
      SELECT family_proof.*,
        CASE
          WHEN session_id IS NULL THEN 'SOURCE_SESSION_MISSING'
          WHEN draft_operation_id IS NULL OR allocation_basis_json IS NULL THEN 'COMPLETED_DRAFT_SCOPE_MISSING'
          WHEN COALESCE(frozen_attestation->>'attestation_version','')<>'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
            OR COALESCE((frozen_attestation->>'semantic_ready')::boolean,false) IS NOT TRUE
            OR COALESCE((frozen_attestation->>'parity_complete')::boolean,false) IS NOT TRUE
            THEN 'LEGACY_OR_SEMANTICALLY_UNCERTIFIED_SOURCE'
          WHEN COALESCE(frozen_source_publication_id,'')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN 'LEGACY_PHYSICAL_PUBLICATION_MISSING'
          WHEN execution_commit_state<>'NOT_SUBMITTED' THEN 'PROVIDER_OR_EXECUTION_COMMIT_PRESENT'
          WHEN pg_catalog.upper(COALESCE(settlement_status,''))='SETTLED' OR settled_at_utc IS NOT NULL
            THEN 'SETTLEMENT_EVIDENCE_PRESENT'
          WHEN batch_status NOT IN ('SCHEDULED','AUTHORISED','ACTIVE') THEN 'UNSENT_SCHEDULE_STATE_NOT_EXACT'
          WHEN pre_provider_cancel_eligible IS NOT TRUE
            OR NOT (current_available_actions ? 'CANCEL_PAYMENT')
            THEN 'CURRENT_CANCELABILITY_AUTHORITY_REJECTED'
          WHEN original_economic_build_id IS NULL OR current_economic_build_id IS NULL
            THEN 'ECONOMIC_BUILD_LINEAGE_MISSING'
          WHEN exact_execution_refresh_owner IS NOT TRUE AND (
            current_parity IS NOT TRUE
            OR COALESCE(current_attestation->>'attestation_version','')<>'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
            OR COALESCE((current_attestation->>'semantic_ready')::boolean,false) IS NOT TRUE
            OR COALESCE((current_attestation->>'parity_complete')::boolean,false) IS NOT TRUE
          ) THEN 'CURRENT_SEMANTIC_PUBLICATION_NOT_EXACT'
          WHEN publication_source_change_seq IS DISTINCT FROM live_source_change_seq
            OR registry_source_change_seq IS DISTINCT FROM live_source_change_seq
            OR registry_dirty_generation IS DISTINCT FROM live_dirty_generation
            OR candidate_state_source_change_seq IS DISTINCT FROM live_source_change_seq
            OR candidate_state_session_version IS DISTINCT FROM session_version
            THEN CASE WHEN exact_unsent_overlay THEN NULL ELSE
              COALESCE(unsent_overlay_authority->>'rejection_reason','WORKBENCH_AUTHORITY_NOT_CURRENT') END
          WHEN invariant_family_count<>8 OR invariant_family_mismatch_count<>0
            THEN 'CURRENT_ECONOMIC_AUTHORITY_CHANGED'
          ELSE NULL
        END AS rejection_reason
      FROM family_proof
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'candidate_id',classified.candidate_id,'pay_batch_candidate_id',classified.pay_batch_candidate_id,
      'pay_batch_id',classified.pay_batch_id,'session_id',classified.session_id,
      'admitted',classified.rejection_reason IS NULL,
      'fast_reversion_eligible',classified.rejection_reason IS NULL,
      'rejection_reason',classified.rejection_reason,'draft_operation_id',classified.draft_operation_id,
      'original_economic_build_id',classified.original_economic_build_id,
      'current_economic_build_id',classified.current_economic_build_id,
      'original_source_publication_id',classified.frozen_source_publication_id,
      'current_source_publication_id',classified.publication_id,
      'source_change_seq',classified.live_source_change_seq,
      'dirty_generation',classified.live_dirty_generation,
      'invariant_economic_digest',classified.invariant_economic_digest,
      'invariant_family_count',classified.invariant_family_count,
      'invariant_family_mismatch_count',classified.invariant_family_mismatch_count,
      'contract_version','CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3',
      'pre_request_exact',classified.rejection_reason IS NULL,
      'currentness_basis',CASE WHEN classified.exact_unsent_overlay
        THEN COALESCE(NULLIF(classified.unsent_overlay_authority->>'currentness_basis',''),
          'EXACT_UNSENT_EXECUTION_OVERLAY') ELSE 'CERTIFIED_CURRENT_PUBLICATION' END,
      'execution_overlay_authority',classified.unsent_overlay_authority,
      'authority_digest',pg_catalog.md5(
        classified.pay_batch_id::text||'|'||classified.candidate_id::text||'|'||
        COALESCE(classified.draft_operation_id::text,'')||'|'||
        COALESCE(classified.original_economic_build_id::text,'')||'|'||
        COALESCE(classified.current_economic_build_id::text,'')||'|'||
        classified.live_source_change_seq::text||'|'||classified.live_dirty_generation::text||'|'||
        COALESCE(classified.invariant_economic_digest,'')||'|'||
        CASE WHEN classified.exact_unsent_overlay THEN COALESCE(
          NULLIF(classified.unsent_overlay_authority->>'currentness_basis',''),
          'EXACT_UNSENT_EXECUTION_OVERLAY') ELSE 'CERTIFIED_CURRENT_PUBLICATION' END||'|'||
        COALESCE(classified.unsent_overlay_authority->>'authority_digest','')||'|'||
        (classified.rejection_reason IS NULL)::text||'|CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3'
      )
    )) ORDER BY classified.ordinality),'[]'::jsonb),pg_catalog.count(*)::integer
    INTO v_results,v_count
    FROM classified;

    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'contract_version','CANCELLATION_REVERSION_PROOF_CORE_V1','mode',v_mode,
      'pay_batch_id',(p_options_json->>'pay_batch_id')::uuid,
      'candidate_count',v_count,
      'admitted_count',(SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(v_results) AS r(value)
        WHERE COALESCE((r.value->>'admitted')::boolean,false)),
      'candidate_results',v_results,
      'policy_x_authority_scope','POST_DRAFT_FROZEN_PAYMENT_PROOF_PLUS_EXACT_UNSENT_OVERLAY'
    );
  END IF;

  WITH requested_scope AS (
    SELECT
      candidate_value.value::uuid AS requested_candidate_id,
      NULL::uuid AS work_id,
      candidate_value.ordinality
    FROM pg_catalog.jsonb_array_elements_text(
      CASE WHEN v_mode='DRAFT_OVERLAY_PREFLIGHT'
        THEN COALESCE(p_options_json->'candidate_ids','[]'::jsonb)
        ELSE '[]'::jsonb END
    ) WITH ORDINALITY AS candidate_value(value,ordinality)
    WHERE candidate_value.value
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

    UNION ALL

    SELECT NULL::uuid,work_scope.work_id,work_scope.ordinality
    FROM pg_catalog.unnest(
      CASE WHEN v_mode<>'DRAFT_OVERLAY_PREFLIGHT' THEN p_work_item_ids ELSE ARRAY[]::uuid[] END
    ) WITH ORDINALITY AS work_scope(work_id,ordinality)
  ), authority AS (
    SELECT
      requested_scope.ordinality,
      work_row.id AS work_item_id,
      COALESCE(work_row.candidate_id,batch_candidate.candidate_id) AS candidate_id,
      COALESCE(work_row.pay_batch_candidate_id,batch_candidate.id) AS pay_batch_candidate_id,
      COALESCE(work_row.pay_batch_id,request_row.pay_batch_id) AS pay_batch_id,
      work_row.status AS work_status,
      work_row.result_json AS work_result,
      request_row.plan_json,
      request_row.selection_json,
      request_row.created_at_utc AS request_created_at_utc,
      request_row.selection_json->'draft_overlay_fast_pre_request_authorities'
        ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
        AS draft_overlay_pre_request_authority,
      COALESCE(
        work_row.selection_json->'cancellation_reversion_pre_request_authority',
        request_row.selection_json->'cancellation_reversion_pre_request_authorities_v3'
          ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text,
        request_row.selection_json->'cancellation_reversion_pre_request_authorities_v2'
          ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
      )
        AS cancellation_pre_request_authority_v2,
      correction_operation.input_json->'draft_overlay_fast_start_authorities'
        ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
        AS draft_overlay_start_authority,
      COALESCE(
        work_row.selection_json->'cancellation_reversion_start_authority_v2',
        correction_operation.input_json->'cancellation_reversion_start_authorities_v2'
          ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
      )
        AS cancellation_start_authority_v2,
      correction_operation.input_json->'cancellation_reversion_post_commit_authorities_v3'
        ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
        AS cancellation_terminal_authority_v3,
      batch_row.source_workbench_session_id,
      batch_row.source_session_version,
      batch_row.source_snapshot_run_id,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(batch_row.execution_commit_state,'NOT_SUBMITTED'))) AS execution_commit_state,
      batch_candidate.settlement_status,
      batch_candidate.settled_at_utc,
      draft_operation.id AS draft_operation_id,
      draft_scope.allocation_basis_json,
      draft_scope.allocation_basis_json->'source_publication_attestation' AS frozen_attestation,
      draft_scope.allocation_basis_json->>'source_build_run_id' AS frozen_source_build_run_id,
      draft_scope.allocation_basis_json->>'source_publication_id' AS frozen_source_publication_id,
      draft_scope.allocation_basis_json->'post_draft_authority' AS post_draft_authority,
      COALESCE(change_counter.seq,0) AS live_source_change_seq,
      COALESCE(change_counter.scope_change_generation,0) AS live_dirty_generation,
      registry.current_source_change_seq AS registry_source_change_seq,
      registry.dirty_generation AS registry_dirty_generation,
      candidate_state.source_change_seq AS candidate_state_source_change_seq,
      candidate_state.session_version AS candidate_state_session_version,
      request_owned_dirty.job_id AS current_request_owned_dirty_job_id
    FROM requested_scope
    LEFT JOIN public.pay_payment_correction_work_items AS work_row
      ON work_row.id=requested_scope.work_id
     AND work_row.correction_request_id=p_correction_request_id
    JOIN public.pay_payment_correction_requests AS request_row
      ON request_row.id=p_correction_request_id
    JOIN public.banking_pay_operations AS correction_operation
      ON correction_operation.id=p_operation_id
     AND correction_operation.operation_type='PAYMENT_CORRECTION'
     AND correction_operation.input_json->>'correction_request_id'=request_row.id::text
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.pay_batch_id=request_row.pay_batch_id
     AND batch_candidate.candidate_id=COALESCE(work_row.candidate_id,requested_scope.requested_candidate_id)
    JOIN public.pay_payment_correction_request_candidates AS request_candidate
      ON request_candidate.correction_request_id=request_row.id
     AND request_candidate.pay_batch_candidate_id=batch_candidate.id
    JOIN public.pay_batches AS batch_row ON batch_row.id=request_row.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT operation_row.id
      FROM public.banking_pay_operations AS operation_row
      WHERE operation_row.operation_type='DRAFT_CREATE'
        AND operation_row.status='COMPLETE'
        AND (
          operation_row.pay_batch_id=request_row.pay_batch_id
          OR EXISTS (
            SELECT 1
            FROM public.banking_pay_operation_candidate_scope AS operation_scope_link
            WHERE operation_scope_link.operation_id=operation_row.id
              AND operation_scope_link.candidate_id=batch_candidate.candidate_id
              AND operation_scope_link.pay_batch_id=request_row.pay_batch_id
              AND operation_scope_link.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
          )
        )
      ORDER BY operation_row.completed_at_utc DESC NULLS LAST, operation_row.created_at_utc DESC
      LIMIT 1
    ) AS draft_operation ON true
    LEFT JOIN public.banking_pay_operation_candidate_scope AS draft_scope
      ON draft_scope.operation_id=draft_operation.id
      AND draft_scope.candidate_id=batch_candidate.candidate_id
      AND draft_scope.pay_batch_id=request_row.pay_batch_id
     AND draft_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
    LEFT JOIN public.app_change_counters AS change_counter
      ON change_counter.entity_key='pay_candidate:'||batch_candidate.candidate_id::text
    LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
      ON registry.candidate_id=batch_candidate.candidate_id
    LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
      ON candidate_state.session_id=p_session_id
     AND candidate_state.candidate_id=batch_candidate.candidate_id
    LEFT JOIN LATERAL (
      SELECT dirty_job.id AS job_id
      FROM public.banking_pay_workbench_jobs AS dirty_job
        WHERE dirty_job.id=CASE
          WHEN COALESCE(
            correction_operation.input_json->'cancellation_reversion_start_authorities_v2'
              ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
              ->>'request_owned_dirty_job_id',
            correction_operation.input_json->'draft_overlay_fast_start_authorities'
              ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
              ->>'request_owned_dirty_job_id',''
          ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (
            COALESCE(
              correction_operation.input_json->'cancellation_reversion_start_authorities_v2'
                ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
                ->>'request_owned_dirty_job_id',
              correction_operation.input_json->'draft_overlay_fast_start_authorities'
                ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
                ->>'request_owned_dirty_job_id'
            )
          )::uuid
          ELSE NULL::uuid END
        AND dirty_job.candidate_id=COALESCE(work_row.candidate_id,batch_candidate.candidate_id)
        -- The transition-trigger job is normally candidate-global
        -- (session_id NULL).  If a session-scoped owner is supplied it must
        -- belong to this exact source Workbench session.
        AND (
          dirty_job.session_id IS NULL
          OR dirty_job.session_id=p_session_id
        )
        AND dirty_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND (
          dirty_job.status IN ('QUEUED','RUNNING')
          OR (
            dirty_job.status='SUCCEEDED'
            AND COALESCE(
              (dirty_job.payload_json->>'coalesced_to_current_refresh_authority')::boolean,
              false
            )
            AND COALESCE(dirty_job.payload_json->>'coalesced_owner_resolution','')
                  ='COMPLETE_CURRENT_AUTHORITY'
            AND COALESCE(dirty_job.payload_json->>'actual_refresh_scope_status','')
                  ='MATERIALISED'
          )
        )
        -- A request-owned transition can be merged into an older deduplicated
        -- dirty job.  Its updated_at is the durable receipt boundary; the exact
        -- job id, request authority and causal fields remain mandatory.
        AND GREATEST(
              dirty_job.created_at_utc,
              COALESCE(dirty_job.updated_at_utc,dirty_job.created_at_utc)
            )>=request_row.created_at_utc
        AND dirty_job.scope_change_generation=COALESCE(change_counter.scope_change_generation,0)
        AND COALESCE(dirty_job.payload_json->>'source_change_seq','')
              =COALESCE(change_counter.seq,0)::text
        AND COALESCE((dirty_job.payload_json->>'policy_x_dirtying_only')::boolean,false)
        AND COALESCE((dirty_job.payload_json->>'economic_truth_mutation_allowed')::boolean,true) IS FALSE
        AND (
          (
            pg_catalog.jsonb_typeof(COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb))='array'
            AND pg_catalog.jsonb_array_length(COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb))>0
            AND NOT EXISTS (
              SELECT 1
              FROM pg_catalog.jsonb_array_elements_text(
                COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb)
              ) AS dirty_reason(value)
              WHERE pg_catalog.upper(pg_catalog.btrim(dirty_reason.value)) NOT IN (
                'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
                'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE',
                'DIRTY_TRIGGER:PAY_BATCHES:UPDATE'
              )
            )
          )
          OR (
            COALESCE(dirty_job.payload_json->>'correction_dirty_causal_contract_version','')
              ='CORRECTION_OWNED_DIRTY_CAUSAL_V1'
            AND COALESCE(
              dirty_job.payload_json->'correction_dirty_contexts'
                ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
                ->>'correction_request_id',''
            )=p_correction_request_id::text
            AND COALESCE(
              dirty_job.payload_json->'correction_dirty_contexts'
                ->COALESCE(work_row.candidate_id,batch_candidate.candidate_id)::text
                ->>'pay_batch_id',''
            )=request_row.pay_batch_id::text
            AND COALESCE(dirty_job.payload_json->>'request_owned_scope_change_tx_token','')
              =COALESCE(dirty_job.payload_json->>'scope_change_tx_token','')
            AND COALESCE(dirty_job.payload_json->>'request_owned_scope_change_tx_token','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
        )
      LIMIT 1
    ) AS request_owned_dirty ON true
  ), source_proof AS (
    SELECT
      authority.*,
      source_rows.source_row_count,
      source_rows.source_identity_digest,
      pg_catalog.md5(
        authority.draft_operation_id::text||'|'||authority.pay_batch_id::text||'|'||
        p_session_id::text||'|'||authority.candidate_id::text||'|'||
        COALESCE(authority.post_draft_authority->>'source_change_seq','')||'|'||
        COALESCE(authority.post_draft_authority->>'dirty_generation','')||'|'||
        authority.source_session_version::text||'|'||authority.source_snapshot_run_id::text||'|'||
        COALESCE(authority.frozen_source_build_run_id,'')||'|'||
        COALESCE(authority.frozen_source_publication_id,'')||'|'||
        COALESCE(authority.allocation_basis_json->>'source_identity_digest','')||'|'||
        COALESCE(authority.allocation_basis_json->>'semantic_proof_digest','')||
        '|'||COALESCE((authority.post_draft_authority->>'fast_reversion_eligible')::boolean,false)::text||
        '|POST_DRAFT_LIVE_AUTHORITY_V2'
      ) AS recomputed_post_draft_authority_digest,
      CASE
        WHEN v_mode<>'DRAFT_OVERLAY_PREFLIGHT' AND authority.work_item_id IS NULL THEN 'WORK_ITEM_NOT_EXACT'
        WHEN v_mode='PRE_FINANCIAL' AND pg_catalog.upper(COALESCE(authority.work_status,''))<>'PROCESSING'
          THEN 'FINANCIAL_REVERSION_NOT_CLAIMED'
        WHEN v_mode IN ('POST_FINANCIAL','OBSERVE_ONLY')
          AND pg_catalog.upper(COALESCE(authority.work_status,''))<>'APPLIED'
          THEN 'FINANCIAL_REVERSION_NOT_APPLIED'
        WHEN v_mode IN ('POST_FINANCIAL','OBSERVE_ONLY')
          AND COALESCE(authority.work_result->>'result_code','')<>'APPLIED'
          THEN 'FINANCIAL_REVERSION_RESULT_NOT_EXACT'
        WHEN authority.source_workbench_session_id IS DISTINCT FROM p_session_id THEN 'SOURCE_SESSION_NOT_EXACT'
        WHEN authority.draft_operation_id IS NULL OR authority.allocation_basis_json IS NULL THEN 'COMPLETED_DRAFT_SCOPE_MISSING'
        WHEN COALESCE(authority.frozen_attestation->>'attestation_version','') <> 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
          OR COALESCE(authority.frozen_attestation->>'semantic_contract_version','') <> 'READY_TO_PAY_SEMANTIC_V2'
          OR COALESCE((authority.frozen_attestation->>'semantic_ready')::boolean,false) IS NOT TRUE
          OR COALESCE((authority.frozen_attestation->>'parity_complete')::boolean,false) IS NOT TRUE
          THEN 'LEGACY_OR_SEMANTICALLY_UNCERTIFIED_SOURCE'
        WHEN authority.frozen_source_build_run_id
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          OR COALESCE(authority.frozen_attestation->>'economic_build_id','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'ORIGINAL_BUILD_LINEAGE_MISSING'
        WHEN COALESCE(authority.frozen_source_publication_id,'')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'LEGACY_PHYSICAL_PUBLICATION_MISSING'
        WHEN COALESCE((authority.post_draft_authority->>'fast_reversion_eligible')::boolean,false) IS NOT TRUE
          THEN COALESCE(NULLIF(authority.post_draft_authority->>'fast_reversion_ineligible_reason',''),
                        'LEGACY_PHYSICAL_PUBLICATION_MISSING')
        WHEN COALESCE(authority.post_draft_authority->>'contract_version','')
               <>'POST_DRAFT_LIVE_AUTHORITY_V2'
          OR COALESCE(authority.post_draft_authority->>'draft_operation_id','')
               IS DISTINCT FROM authority.draft_operation_id::text
          OR COALESCE(authority.post_draft_authority->>'pay_batch_id','')
               IS DISTINCT FROM authority.pay_batch_id::text
          OR COALESCE(authority.post_draft_authority->>'workbench_session_id','')
               IS DISTINCT FROM p_session_id::text
          OR COALESCE(authority.post_draft_authority->>'candidate_id','')
               IS DISTINCT FROM authority.candidate_id::text
          OR COALESCE(authority.post_draft_authority->>'source_session_version','')
               IS DISTINCT FROM authority.source_session_version::text
          OR COALESCE(authority.post_draft_authority->>'source_snapshot_run_id','')
               IS DISTINCT FROM authority.source_snapshot_run_id::text
          OR COALESCE(authority.post_draft_authority->>'original_source_build_run_id','')
               IS DISTINCT FROM authority.frozen_source_build_run_id
          OR COALESCE(authority.post_draft_authority->>'original_source_publication_id','')
               IS DISTINCT FROM COALESCE(authority.frozen_source_publication_id,'')
          OR COALESCE(authority.post_draft_authority->>'original_source_identity_digest','')
               IS DISTINCT FROM authority.allocation_basis_json->>'source_identity_digest'
          OR COALESCE(authority.post_draft_authority->>'original_semantic_proof_digest','')
               IS DISTINCT FROM authority.allocation_basis_json->>'semantic_proof_digest'
          OR COALESCE(authority.post_draft_authority->>'authority_digest','')
               IS DISTINCT FROM pg_catalog.md5(
                 authority.draft_operation_id::text||'|'||authority.pay_batch_id::text||'|'||
                 p_session_id::text||'|'||authority.candidate_id::text||'|'||
                 COALESCE(authority.post_draft_authority->>'source_change_seq','')||'|'||
                 COALESCE(authority.post_draft_authority->>'dirty_generation','')||'|'||
                 authority.source_session_version::text||'|'||authority.source_snapshot_run_id::text||'|'||
                 COALESCE(authority.frozen_source_build_run_id,'')||'|'||
                 COALESCE(authority.frozen_source_publication_id,'')||'|'||
                 COALESCE(authority.allocation_basis_json->>'source_identity_digest','')||'|'||
                 COALESCE(authority.allocation_basis_json->>'semantic_proof_digest','')||
                 '|'||COALESCE((authority.post_draft_authority->>'fast_reversion_eligible')::boolean,false)::text||
                 '|POST_DRAFT_LIVE_AUTHORITY_V2'
               )
          THEN 'POST_DRAFT_AUTHORITY_MISSING_OR_MISMATCH'
        WHEN authority.execution_commit_state <> 'NOT_SUBMITTED' THEN 'PROVIDER_OR_EXECUTION_COMMIT_PRESENT'
        WHEN pg_catalog.upper(COALESCE(authority.settlement_status,''))='SETTLED'
          OR authority.settled_at_utc IS NOT NULL THEN 'SETTLEMENT_EVIDENCE_PRESENT'
        WHEN v_mode='DRAFT_OVERLAY_PREFLIGHT'
          AND (
            COALESCE(authority.draft_overlay_pre_request_authority->>'contract_version','')
              <>'DRAFT_OVERLAY_FAST_PRE_REQUEST_AUTHORITY_V1'
            OR COALESCE(authority.draft_overlay_pre_request_authority->>'candidate_id','')
              IS DISTINCT FROM authority.candidate_id::text
            OR COALESCE(
              (authority.draft_overlay_pre_request_authority->>'pre_request_exact')::boolean,
              false
            ) IS NOT TRUE
            OR COALESCE(authority.draft_overlay_pre_request_authority->>'source_change_seq','')
              !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.draft_overlay_pre_request_authority->>'dirty_generation','')
              !~ '^[0-9]{1,18}$'
            OR NULLIF(COALESCE(authority.draft_overlay_pre_request_authority->>'fence_digest',''),'')
              IS NULL
            OR COALESCE(authority.draft_overlay_pre_request_authority->>'post_draft_authority_digest','')
              IS DISTINCT FROM authority.post_draft_authority->>'authority_digest'
          ) THEN 'PRE_REQUEST_ECONOMIC_AUTHORITY_NOT_CURRENT'
        WHEN v_mode='DRAFT_OVERLAY_PREFLIGHT'
          AND (
            COALESCE(authority.draft_overlay_start_authority->>'contract_version','')
              <>'DRAFT_OVERLAY_FAST_START_AUTHORITY_V1'
            OR COALESCE(authority.draft_overlay_start_authority->>'correction_request_id','')
              IS DISTINCT FROM p_correction_request_id::text
            OR COALESCE(authority.draft_overlay_start_authority->>'operation_id','')
              IS DISTINCT FROM p_operation_id::text
            OR COALESCE(authority.draft_overlay_start_authority->>'candidate_id','')
              IS DISTINCT FROM authority.candidate_id::text
            OR COALESCE((authority.draft_overlay_start_authority->>'start_exact')::boolean,false)
              IS NOT TRUE
            OR COALESCE(authority.draft_overlay_start_authority->>'source_change_seq','')
              !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.draft_overlay_start_authority->>'dirty_generation','')
              !~ '^[0-9]{1,18}$'
            OR (
              COALESCE(
                (authority.draft_overlay_start_authority->>'request_owned_dirty_proven')::boolean,
                false
              )
              AND (
                COALESCE(authority.draft_overlay_start_authority->>'request_owned_dirty_job_id','')
                  !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR authority.current_request_owned_dirty_job_id IS DISTINCT FROM
                  (authority.draft_overlay_start_authority->>'request_owned_dirty_job_id')::uuid
              )
            )
            OR COALESCE(authority.draft_overlay_start_authority->>'pre_request_fence_digest','')
              IS DISTINCT FROM authority.draft_overlay_pre_request_authority->>'fence_digest'
            OR COALESCE(authority.draft_overlay_start_authority->>'fence_digest','')
              IS DISTINCT FROM pg_catalog.md5(
                p_correction_request_id::text||'|'||p_operation_id::text||'|'||
                authority.candidate_id::text||'|'||
                COALESCE(authority.draft_overlay_start_authority->>'source_change_seq','')||'|'||
                COALESCE(authority.draft_overlay_start_authority->>'dirty_generation','')||'|'||
                COALESCE(authority.draft_overlay_start_authority->>'pre_request_fence_digest','')||'|'||
                COALESCE(authority.draft_overlay_start_authority->>'request_owned_dirty_job_id','')||'|'||
                COALESCE(
                  (authority.draft_overlay_start_authority->>'request_owned_dirty_proven')::boolean,
                  false
                )::text||'|'||
                COALESCE((authority.draft_overlay_start_authority->>'start_exact')::boolean,false)::text||
                '|DRAFT_OVERLAY_FAST_START_AUTHORITY_V1'
              )
          ) THEN 'CANCELLATION_START_AUTHORITY_MISSING_OR_MISMATCH'
        WHEN v_mode='DRAFT_OVERLAY_PREFLIGHT'
          AND (
            authority.live_source_change_seq IS DISTINCT FROM
              (authority.draft_overlay_start_authority->>'source_change_seq')::bigint
            OR authority.live_dirty_generation IS DISTINCT FROM
              (authority.draft_overlay_start_authority->>'dirty_generation')::bigint
          )
          AND authority.current_request_owned_dirty_job_id IS NULL
          THEN 'CURRENT_ECONOMIC_AUTHORITY_CHANGED'
        WHEN v_mode='PRE_FINANCIAL'
          AND COALESCE(authority.cancellation_pre_request_authority_v2->>'contract_version','')
                IN ('CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V2',
                    'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3')
          AND (
            COALESCE((authority.cancellation_pre_request_authority_v2->>'pre_request_exact')::boolean,false)
              IS NOT TRUE
            OR COALESCE(authority.cancellation_pre_request_authority_v2->>'candidate_id','')
                 IS DISTINCT FROM authority.candidate_id::text
            OR COALESCE(authority.cancellation_pre_request_authority_v2->>'source_change_seq','')
                 !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.cancellation_pre_request_authority_v2->>'dirty_generation','')
                 !~ '^[0-9]{1,18}$'
            OR NULLIF(COALESCE(authority.cancellation_pre_request_authority_v2->>'authority_digest',''),'')
                 IS NULL
            OR COALESCE(authority.cancellation_start_authority_v2->>'contract_version','')
                 <>'CANCELLATION_REVERSION_START_AUTHORITY_V2'
            OR COALESCE(authority.cancellation_start_authority_v2->>'correction_request_id','')
                 IS DISTINCT FROM p_correction_request_id::text
            OR COALESCE(authority.cancellation_start_authority_v2->>'operation_id','')
                 IS DISTINCT FROM p_operation_id::text
            OR COALESCE(authority.cancellation_start_authority_v2->>'candidate_id','')
                 IS DISTINCT FROM authority.candidate_id::text
            OR COALESCE((authority.cancellation_start_authority_v2->>'start_exact')::boolean,false)
                 IS NOT TRUE
            OR COALESCE(authority.cancellation_start_authority_v2->>'pre_request_fence_digest','')
                 IS DISTINCT FROM authority.cancellation_pre_request_authority_v2->>'authority_digest'
            OR (
              COALESCE((authority.cancellation_start_authority_v2->>'request_owned_dirty_proven')::boolean,false)
              AND (
                COALESCE(authority.cancellation_start_authority_v2->>'request_owned_dirty_job_id','')
                  !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR authority.current_request_owned_dirty_job_id IS DISTINCT FROM
                  (authority.cancellation_start_authority_v2->>'request_owned_dirty_job_id')::uuid
              )
            )
            OR (
              authority.live_source_change_seq IS DISTINCT FROM
                (authority.cancellation_start_authority_v2->>'source_change_seq')::bigint
              OR authority.live_dirty_generation IS DISTINCT FROM
                (authority.cancellation_start_authority_v2->>'dirty_generation')::bigint
            ) AND authority.current_request_owned_dirty_job_id IS NULL
          ) THEN 'CANCELLATION_START_AUTHORITY_MISSING_OR_MISMATCH'
        WHEN v_mode='PRE_FINANCIAL'
          AND COALESCE(authority.cancellation_pre_request_authority_v2->>'contract_version','')
                NOT IN ('CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V2',
                        'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3')
          AND (
            COALESCE(authority.post_draft_authority->>'source_change_seq','') !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.post_draft_authority->>'dirty_generation','') !~ '^[0-9]{1,18}$'
            OR authority.live_source_change_seq
                 IS DISTINCT FROM (authority.post_draft_authority->>'source_change_seq')::bigint
            OR authority.live_dirty_generation
                 IS DISTINCT FROM (authority.post_draft_authority->>'dirty_generation')::bigint
          ) THEN 'CURRENT_ECONOMIC_AUTHORITY_CHANGED'
        WHEN v_mode IN ('POST_FINANCIAL','OBSERVE_ONLY')
          AND COALESCE(authority.cancellation_pre_request_authority_v2->>'contract_version','')
                IN ('CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V2',
                    'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3')
          AND (
            COALESCE(authority.work_result->'cancellation_reversion_preflight'->>'admitted','false')::boolean
              IS NOT TRUE
            OR COALESCE(authority.work_result->'cancellation_reversion_preflight'
                 ->>'scheduled_pre_request_authority_digest','')
              IS DISTINCT FROM authority.cancellation_pre_request_authority_v2->>'authority_digest'
            OR
            COALESCE(authority.cancellation_terminal_authority_v3->>'contract_version','')
              <>'POST_FINANCIAL_TERMINAL_AUTHORITY_V3'
            OR COALESCE((authority.cancellation_terminal_authority_v3->>'admitted')::boolean,false)
              IS NOT TRUE
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'correction_request_id','')
              IS DISTINCT FROM p_correction_request_id::text
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'operation_id','')
              IS DISTINCT FROM p_operation_id::text
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'session_id','')
              IS DISTINCT FROM p_session_id::text
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'candidate_id','')
              IS DISTINCT FROM authority.candidate_id::text
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'source_change_seq','') !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'dirty_generation','') !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'scope_change_tx_token','')
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR COALESCE(authority.cancellation_terminal_authority_v3->>'held_dirty_job_id','')
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR authority.live_source_change_seq IS DISTINCT FROM
              (authority.cancellation_terminal_authority_v3->>'source_change_seq')::bigint
            OR authority.live_dirty_generation IS DISTINCT FROM
              (authority.cancellation_terminal_authority_v3->>'dirty_generation')::bigint
            OR NOT EXISTS (
              SELECT 1 FROM public.banking_pay_scope_change_transactions AS scope_tx
              WHERE scope_tx.tx_token=(authority.cancellation_terminal_authority_v3
                ->>'scope_change_tx_token')::uuid
                AND scope_tx.state='FINALIZED'
                AND scope_tx.allocated_generation=(authority.cancellation_terminal_authority_v3
                  ->>'dirty_generation')::bigint
            )
            OR NOT EXISTS (
              SELECT 1 FROM public.banking_pay_workbench_jobs AS held_job
              WHERE held_job.id=CASE
                WHEN COALESCE(authority.cancellation_terminal_authority_v3
                  ->>'held_dirty_job_id','')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                THEN (authority.cancellation_terminal_authority_v3
                  ->>'held_dirty_job_id')::uuid END
                AND held_job.candidate_id=authority.candidate_id
                AND held_job.scope_change_generation=(authority.cancellation_terminal_authority_v3
                  ->>'dirty_generation')::bigint
            )
          ) THEN 'POST_FINANCIAL_TERMINAL_AUTHORITY_CHANGED'
        WHEN v_mode IN ('POST_FINANCIAL','OBSERVE_ONLY')
          AND COALESCE(authority.cancellation_pre_request_authority_v2->>'contract_version','')
                NOT IN ('CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V2',
                        'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3')
          AND (
            COALESCE(authority.work_result->'cancellation_reversion_preflight'->>'admitted','false')::boolean IS NOT TRUE
            OR COALESCE(authority.work_result->'cancellation_reversion_preflight'->>'post_draft_authority_digest','')
                 IS DISTINCT FROM authority.post_draft_authority->>'authority_digest'
            OR COALESCE(authority.work_result->'cancellation_reversion_post_financial_authority'->>'source_change_seq','')
                 !~ '^[0-9]{1,18}$'
            OR COALESCE(authority.work_result->'cancellation_reversion_post_financial_authority'->>'dirty_generation','')
                 !~ '^[0-9]{1,18}$'
            OR authority.live_source_change_seq IS DISTINCT FROM
                 (authority.work_result->'cancellation_reversion_post_financial_authority'->>'source_change_seq')::bigint
            OR authority.live_dirty_generation IS DISTINCT FROM
                 (authority.work_result->'cancellation_reversion_post_financial_authority'->>'dirty_generation')::bigint
          ) THEN 'POST_FINANCIAL_AUTHORITY_CHANGED'
        WHEN v_mode='DRAFT_OVERLAY_PREFLIGHT'
          AND (
            NOT (
              authority.registry_source_change_seq IS NOT DISTINCT FROM
                (authority.draft_overlay_pre_request_authority->>'source_change_seq')::bigint
              OR authority.registry_source_change_seq IS NOT DISTINCT FROM authority.live_source_change_seq
            )
            OR NOT (
              authority.registry_dirty_generation IS NOT DISTINCT FROM
                (authority.draft_overlay_pre_request_authority->>'dirty_generation')::bigint
              OR authority.registry_dirty_generation IS NOT DISTINCT FROM authority.live_dirty_generation
            )
            OR NOT (
              authority.candidate_state_source_change_seq IS NOT DISTINCT FROM
                (authority.draft_overlay_pre_request_authority->>'source_change_seq')::bigint
              OR authority.candidate_state_source_change_seq IS NOT DISTINCT FROM authority.live_source_change_seq
            )
            OR authority.candidate_state_session_version IS DISTINCT FROM authority.source_session_version
          )
          AND authority.current_request_owned_dirty_job_id IS NULL
          THEN 'WORKBENCH_AUTHORITY_NOT_FROZEN_DRAFT_BASELINE'
        WHEN v_mode<>'DRAFT_OVERLAY_PREFLIGHT'
          AND (authority.registry_source_change_seq IS DISTINCT FROM authority.live_source_change_seq
          OR authority.registry_dirty_generation IS DISTINCT FROM authority.live_dirty_generation
          OR authority.candidate_state_source_change_seq IS DISTINCT FROM authority.live_source_change_seq
          OR authority.candidate_state_session_version IS DISTINCT FROM authority.source_session_version)
          AND NOT (
            COALESCE(authority.cancellation_pre_request_authority_v2->>'contract_version','')
              IN ('CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V2',
                  'CANCELLATION_REVERSION_PRE_REQUEST_AUTHORITY_V3')
            AND authority.current_request_owned_dirty_job_id IS NOT NULL
          )
          THEN 'WORKBENCH_AUTHORITY_NOT_CURRENT'
        WHEN source_rows.source_row_count
             IS DISTINCT FROM COALESCE(NULLIF(authority.frozen_attestation->>'source_row_count','')::integer,-1)
          OR source_rows.source_identity_digest
             IS DISTINCT FROM authority.frozen_attestation->>'source_identity_digest'
          THEN 'ORIGINAL_SOURCE_DIGEST_MISMATCH'
        ELSE NULL
      END AS rejection_reason
    FROM authority
    LEFT JOIN LATERAL (
      SELECT
        pg_catalog.count(*)::integer AS source_row_count,
        pg_catalog.md5(COALESCE(pg_catalog.string_agg(
          public.pay_workbench_preview_section_from_line_json(source_row.source_row_json)
            || E'\x1f' || source_row.line_key || E'\x1f' || source_row.source_ordinal::text,
          E'\x1e' ORDER BY source_row.source_ordinal,
            public.pay_workbench_preview_section_from_line_json(source_row.source_row_json),
            source_row.line_key
        ),'')) AS source_identity_digest
      FROM public.banking_pay_workbench_candidate_source_lines AS source_row
      WHERE source_row.session_id=p_session_id
        AND source_row.candidate_id=authority.candidate_id
        AND source_row.session_version=authority.source_session_version
        AND source_row.source_build_run_id=CASE
          WHEN authority.frozen_source_build_run_id
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN authority.frozen_source_build_run_id::uuid ELSE NULL::uuid END
        AND authority.frozen_source_publication_id
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND source_row.source_publication_id=authority.frozen_source_publication_id::uuid
    ) AS source_rows ON true
  ), result_rows AS (
    SELECT
      source_proof.ordinality,
      pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'work_item_id',source_proof.work_item_id,
        'candidate_id',source_proof.candidate_id,
        'pay_batch_candidate_id',source_proof.pay_batch_candidate_id,
        'pay_batch_id',source_proof.pay_batch_id,
        'admitted',source_proof.rejection_reason IS NULL,
        'fast_reversion_eligible',source_proof.rejection_reason IS NULL,
        'rejection_reason',source_proof.rejection_reason,
        'draft_operation_id',source_proof.draft_operation_id,
        'original_economic_build_id',source_proof.frozen_attestation->>'economic_build_id',
        'original_source_build_run_id',COALESCE(
          source_proof.frozen_attestation->>'original_source_build_run_id',
          source_proof.frozen_source_build_run_id
        ),
        'replay_source_build_run_id',source_proof.frozen_source_build_run_id,
        'original_source_publication_id',source_proof.frozen_source_publication_id,
        'original_source_change_seq',source_proof.frozen_attestation->>'source_change_seq',
        'current_source_change_seq',source_proof.live_source_change_seq,
        'current_dirty_generation',source_proof.live_dirty_generation,
        'session_version',source_proof.source_session_version,
        'source_count',source_proof.source_row_count,
        'source_identity_digest',source_proof.source_identity_digest,
        'semantic_proof_digest',source_proof.frozen_attestation->>'semantic_proof_digest',
        'post_draft_authority_digest',source_proof.post_draft_authority->>'authority_digest',
        'recomputed_post_draft_authority_digest',source_proof.recomputed_post_draft_authority_digest,
        'pre_request_source_change_seq',source_proof.draft_overlay_pre_request_authority->>'source_change_seq',
        'pre_request_dirty_generation',source_proof.draft_overlay_pre_request_authority->>'dirty_generation',
        'pre_request_fence_digest',source_proof.draft_overlay_pre_request_authority->>'fence_digest',
        'scheduled_pre_request_authority_digest',
          source_proof.cancellation_pre_request_authority_v2->>'authority_digest',
        'cancellation_start_source_change_seq',source_proof.draft_overlay_start_authority->>'source_change_seq',
        'cancellation_start_dirty_generation',source_proof.draft_overlay_start_authority->>'dirty_generation',
        'cancellation_start_fence_digest',source_proof.draft_overlay_start_authority->>'fence_digest',
        'scheduled_cancellation_start_source_change_seq',
          source_proof.cancellation_start_authority_v2->>'source_change_seq',
        'scheduled_cancellation_start_dirty_generation',
          source_proof.cancellation_start_authority_v2->>'dirty_generation',
        'scheduled_cancellation_start_fence_digest',
          source_proof.cancellation_start_authority_v2->>'fence_digest',
        'post_financial_terminal_authority_digest',
          source_proof.cancellation_terminal_authority_v3->>'authority_digest',
        'request_owned_dirty_proven',source_proof.current_request_owned_dirty_job_id IS NOT NULL,
        'request_owned_dirty_job_id',source_proof.current_request_owned_dirty_job_id,
        'financial_reversion_digest',pg_catalog.md5(
          (COALESCE(source_proof.work_result,'{}'::jsonb)
            - 'applied_at_utc' - 'processed_at_utc')::text
        )
      )) AS result_json
    FROM source_proof
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(result_rows.result_json ORDER BY result_rows.ordinality),'[]'::jsonb),
         pg_catalog.count(*)::integer
  INTO v_results,v_count
  FROM result_rows;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'contract_version','CERTIFIED_CANCELLATION_REVERSION_ADMISSION_V1',
    'mode',v_mode,
    'correction_request_id',p_correction_request_id,
    'operation_id',p_operation_id,
    'session_id',p_session_id,
    'candidate_count',v_count,
    'admitted_count',(SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(v_results) AS r(value)
      WHERE COALESCE((r.value->>'admitted')::boolean,false)),
    'candidate_results',v_results,
    'policy_x_authority_scope','POST_DRAFT_FROZEN_PAYMENT_PROOF_PLUS_PRE_DRAFT_REVERSION'
  );
END;
$function$;

-- private.pay_workbench_candidate_bounded_scope_v1(uuid,uuid,jsonb,integer,uuid[],uuid[],uuid[],uuid)
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_bounded_scope_v1(p_build_id uuid, p_candidate_id uuid, p_cursor_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 500, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_force_include_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_client_filter_single uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_cursor jsonb := COALESCE(p_cursor_json,'{}'::jsonb);
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit,500),1),500);
  v_cursor_kind text := COALESCE(NULLIF(v_cursor->>'cursor_kind',''),'PREPARE_SCOPE');
  v_family_ordinal integer := COALESCE((v_cursor->>'seed_family_ordinal')::integer,1);
  v_family text := COALESCE(NULLIF(v_cursor->>'seed_family',''),'ACTIVE_STATE');
  v_last_key text := v_cursor->>'last_source_key';
  v_selected_count integer := 0;
  v_inserted_count integer := 0;
  v_merged_count integer := 0;
  v_accumulated_count bigint := COALESCE((v_cursor->>'accumulated_row_count')::bigint,0);
  v_processed_count bigint := COALESCE((v_cursor->>'processed_source_rows')::bigint,0);
  v_rolling_digest text := COALESCE(NULLIF(v_cursor->>'rolling_digest',''),md5('BPAY_SEED_SCOPE_V1'));
  v_row_digest text;
  v_has_more boolean := true;
  v_initial_sealed boolean := false;
  v_next_cursor jsonb;
  v_row record;
  v_scope_exists boolean;
  v_last_timesheet_id uuid;
  v_next_family text;
BEGIN
  IF jsonb_typeof(v_cursor)<>'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id=p_candidate_id FOR UPDATE;
  SELECT * INTO v_build
  FROM private.banking_pay_workbench_economic_builds AS build_row
  WHERE build_row.id=p_build_id FOR UPDATE;

  IF v_registry.candidate_id IS NULL OR v_build.id IS NULL
     OR v_build.candidate_id<>p_candidate_id
     OR v_registry.current_build_id IS DISTINCT FROM p_build_id
     OR v_registry.dirty_generation<>v_build.captured_candidate_generation
     OR v_registry.current_source_change_seq<>v_build.source_change_seq
     OR v_build.status<>'COLLECTING' OR v_build.private_stage<>'PREPARE_SCOPE' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT'
      USING ERRCODE='40001',DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_BUILD_NOT_CURRENT','build_id',p_build_id,'candidate_id',p_candidate_id
      )::text;
  END IF;

  IF COALESCE(v_cursor->>'build_id',p_build_id::text)<>p_build_id::text
     OR COALESCE(v_cursor->>'candidate_id',p_candidate_id::text)<>p_candidate_id::text
     OR COALESCE((v_cursor->>'captured_candidate_generation')::bigint,v_build.captured_candidate_generation)
        <>v_build.captured_candidate_generation
     OR COALESCE((v_cursor->>'captured_source_change_seq')::bigint,v_build.source_change_seq)
        <>v_build.source_change_seq THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  IF v_cursor_kind='SEED_SCOPE_SEAL' THEN
    v_last_timesheet_id := NULLIF(v_cursor->>'last_timesheet_id','')::uuid;
    FOR v_row IN
      SELECT scope_row.timesheet_id,scope_row.candidate_id,scope_row.seed_reasons,
             scope_row.captured_dirty_generation
      FROM private.banking_pay_workbench_economic_build_scope AS scope_row
      WHERE scope_row.build_id=p_build_id
        AND (v_last_timesheet_id IS NULL OR scope_row.timesheet_id>v_last_timesheet_id)
      ORDER BY scope_row.timesheet_id
      LIMIT v_limit
      FOR UPDATE
    LOOP
      v_selected_count:=v_selected_count+1;
      v_last_timesheet_id:=v_row.timesheet_id;
      v_row_digest:=md5(jsonb_build_object(
        'candidate_id',v_row.candidate_id,'timesheet_id',v_row.timesheet_id,
        'seed_reasons',(SELECT jsonb_agg(reason ORDER BY reason)
          FROM unnest(v_row.seed_reasons) AS reason),
        'captured_dirty_generation',v_row.captured_dirty_generation
      )::text);
      v_rolling_digest:=md5(v_rolling_digest||v_row_digest);
      v_accumulated_count:=v_accumulated_count+1;
    END LOOP;

    IF v_selected_count<v_limit THEN
      UPDATE private.banking_pay_workbench_economic_builds
      SET seed_scope_count=v_accumulated_count::integer,
          seed_scope_digest=v_rolling_digest,
          seed_scope_sealed_at_utc=clock_timestamp(),
          scope_count=v_accumulated_count::integer,
          dependency_node_count=v_accumulated_count::integer,
          private_stage='DEPENDENCY_CLOSURE',
          scope_cursor_json=jsonb_build_object(
            'cursor_kind','SEED_SCOPE_SEAL','cursor_version',1,'terminal',true,
            'build_id',p_build_id,'candidate_id',p_candidate_id,
            'processed_row_count',v_accumulated_count,'rolling_digest',v_rolling_digest
          ),
          closure_cursor_json=jsonb_build_object(
            'cursor_kind','DEPENDENCY_CLOSURE','cursor_version',1,
            'build_id',p_build_id,'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq,
            'frontier_timesheet_id',NULL,'dependency_family','CORRECTION_FORWARD',
            'dependency_family_ordinal',1,'last_edge_key',NULL,
            'processed_edge_count',0,'processed_emission_count',0,'page_number',1
          ),
          updated_at_utc=clock_timestamp()
      WHERE id=p_build_id AND private_stage='PREPARE_SCOPE';
      v_initial_sealed:=true;
      v_has_more:=true;
      v_next_cursor:=(SELECT closure_cursor_json
        FROM private.banking_pay_workbench_economic_builds WHERE id=p_build_id);
    ELSE
      v_next_cursor:=jsonb_build_object(
        'cursor_kind','SEED_SCOPE_SEAL','cursor_version',1,'build_id',p_build_id,
        'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,
        'page_number',COALESCE((v_cursor->>'page_number')::integer,1)+1,
        'last_timesheet_id',v_last_timesheet_id,'processed_row_count',v_accumulated_count,
        'accumulated_row_count',v_accumulated_count,'rolling_digest',v_rolling_digest,
        'previous_page_digest',md5(v_cursor::text||v_rolling_digest)
      );
      UPDATE private.banking_pay_workbench_economic_builds
      SET scope_cursor_json=v_next_cursor,updated_at_utc=clock_timestamp()
      WHERE id=p_build_id;
    END IF;

    RETURN jsonb_build_object(
      'ok',true,'build_id',p_build_id,'candidate_id',p_candidate_id,
      'cursor_kind',v_next_cursor->>'cursor_kind','cursor_version',1,
      'seed_family','COMPLETE','processed_source_count',v_selected_count,
      'new_scope_row_count',0,'merged_scope_row_count',0,
      'initial_scope_count',v_accumulated_count,'initial_scope_digest',v_rolling_digest,
      'initial_scope_sealed',v_initial_sealed,'has_more',v_has_more,
      'next_cursor_json',v_next_cursor
    );
  END IF;

  IF v_cursor_kind NOT IN ('PREPARE_SCOPE','SCOPE_SELECT') OR v_family_ordinal NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_seed_page_v1(
    source_key text PRIMARY KEY,timesheet_id uuid NOT NULL,reason text NOT NULL
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_seed_page_v1;

  INSERT INTO pg_temp._bpay_wb_seed_page_v1(source_key,timesheet_id,reason)
  WITH emissions AS (
    SELECT scope_state.timesheet_id::text AS source_key,scope_state.timesheet_id,'ACTIVE_STATE'::text AS reason
    FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
    WHERE v_family_ordinal=1 AND scope_state.candidate_id=p_candidate_id
      AND scope_state.economic_state IN ('DIRTY','LIVE')
    UNION ALL
    SELECT source_line.timesheet_id::text||':'||source_line.id::text,source_line.timesheet_id,'CURRENT_SOURCE_OWNER'
    FROM public.banking_pay_workbench_candidate_source_lines AS source_line
    WHERE v_family_ordinal=2 AND source_line.candidate_id=p_candidate_id
      AND source_line.status='CURRENT' AND source_line.timesheet_id IS NOT NULL
    UNION ALL
    SELECT advance_row.linked_timesheet_id::text||':'||advance_row.id::text,
           advance_row.linked_timesheet_id,'OPEN_ADVANCE'
    FROM public.pay_advances AS advance_row
    WHERE v_family_ordinal=3 AND advance_row.candidate_id=p_candidate_id
      AND advance_row.status='ACTIVE' AND advance_row.linked_timesheet_id IS NOT NULL
      AND advance_row.cleared_at_utc IS NULL AND advance_row.written_off_at_utc IS NULL
    UNION ALL
    SELECT component_row.linked_timesheet_id::text||':'||component_row.id::text,
           component_row.linked_timesheet_id,'OPEN_FINANCE_COMPONENT'
    FROM public.pay_finance_case_components AS component_row
    WHERE v_family_ordinal=4 AND component_row.candidate_id=p_candidate_id
      AND component_row.linked_timesheet_id IS NOT NULL AND component_row.closed_at_utc IS NULL
    UNION ALL
    SELECT reservation_row.id::text||':'||COALESCE(component_row.linked_timesheet_id,item_row.timesheet_id)::text,
           COALESCE(component_row.linked_timesheet_id,item_row.timesheet_id),'ACTIVE_RESERVATION'
    FROM public.pay_advance_reservations AS reservation_row
    LEFT JOIN public.pay_finance_case_components AS component_row
      ON component_row.id=reservation_row.finance_component_id
    LEFT JOIN public.pay_batch_items AS item_row ON item_row.id=reservation_row.pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=COALESCE(reservation_row.pay_batch_candidate_id,item_row.pay_batch_candidate_id)
    WHERE v_family_ordinal=5 AND reservation_row.released_at_utc IS NULL
      AND COALESCE(component_row.candidate_id,batch_candidate.candidate_id)=p_candidate_id
      AND COALESCE(component_row.linked_timesheet_id,item_row.timesheet_id) IS NOT NULL
    UNION ALL
    SELECT override_row.timesheet_id::text||':'||override_row.id::text,
           override_row.timesheet_id,'ACTIVE_OVERRIDE'
    FROM public.timesheet_payment_overrides AS override_row
    WHERE v_family_ordinal=6 AND override_row.candidate_id=p_candidate_id
      AND override_row.timesheet_id IS NOT NULL AND override_row.cleared_at_utc IS NULL
      AND override_row.consumed_at_utc IS NULL AND override_row.consumed_by_pay_batch_id IS NULL
    UNION ALL
    SELECT adjustment_row.timesheet_id::text||':'||adjustment_row.id::text,
           adjustment_row.timesheet_id,'UNPAID_ADJUSTMENT'
    FROM public.ts_pay_adjustments AS adjustment_row
    WHERE v_family_ordinal=7 AND adjustment_row.candidate_id=p_candidate_id
      AND adjustment_row.timesheet_id IS NOT NULL AND adjustment_row.paid_at_utc IS NULL
    UNION ALL
    SELECT snooze_row.timesheet_id::text||':'||snooze_row.id::text,
           snooze_row.timesheet_id,'ACTIVE_SNOOZE'
    FROM public.pay_item_snoozes AS snooze_row
    WHERE v_family_ordinal=8 AND snooze_row.candidate_id=p_candidate_id
      AND snooze_row.timesheet_id IS NOT NULL AND snooze_row.cleared_at_utc IS NULL
      AND snooze_row.cancelled_at_utc IS NULL
    UNION ALL
    SELECT target_id::text,target_id,'TARGETED_ID'
    FROM unnest(COALESCE(p_targeted_timesheet_ids,ARRAY[]::uuid[])) AS target_id
    WHERE v_family_ordinal=9 AND target_id IS NOT NULL
    UNION ALL
    SELECT force_id::text,force_id,'FORCED_ID'
    FROM unnest(COALESCE(p_force_include_timesheet_ids,ARRAY[]::uuid[])) AS force_id
    WHERE v_family_ordinal=10 AND force_id IS NOT NULL
  ), valid_emissions AS (
    SELECT DISTINCT ON (emission.source_key) emission.source_key,emission.timesheet_id,emission.reason
    FROM emissions AS emission
    JOIN public.timesheets AS timesheet_row ON timesheet_row.timesheet_id=emission.timesheet_id
    JOIN LATERAL (
      SELECT financial_row.candidate_id,financial_row.client_id
      FROM public.timesheets_financials AS financial_row
      WHERE financial_row.timesheet_id=emission.timesheet_id AND financial_row.is_current
      ORDER BY financial_row.id DESC LIMIT 1
    ) AS ownership_financial ON ownership_financial.candidate_id=p_candidate_id
    WHERE (p_client_filter_single IS NULL OR ownership_financial.client_id=p_client_filter_single)
      AND NOT emission.timesheet_id=ANY(COALESCE(p_exclude_timesheet_ids,ARRAY[]::uuid[]))
      AND (v_last_key IS NULL OR emission.source_key>v_last_key)
    ORDER BY emission.source_key,emission.timesheet_id
  )
  SELECT source_key,timesheet_id,reason FROM valid_emissions
  ORDER BY source_key LIMIT v_limit;

  FOR v_row IN SELECT * FROM pg_temp._bpay_wb_seed_page_v1 ORDER BY source_key
  LOOP
    v_selected_count:=v_selected_count+1;
    v_processed_count:=v_processed_count+1;
    v_last_key:=v_row.source_key;
    SELECT EXISTS(
      SELECT 1 FROM private.banking_pay_workbench_economic_build_scope AS scope_row
      WHERE scope_row.build_id=p_build_id AND scope_row.timesheet_id=v_row.timesheet_id
    ) INTO v_scope_exists;
    INSERT INTO private.banking_pay_workbench_economic_build_scope AS scope_row(
      build_id,timesheet_id,candidate_id,seed_reasons,dependency_reasons,
      captured_dirty_generation,required_fact_families
    ) VALUES (
      p_build_id,v_row.timesheet_id,p_candidate_id,ARRAY[v_row.reason],ARRAY[]::text[],
      v_build.captured_candidate_generation,
      ARRAY['FROZEN_SETTLED_COMPONENT','LIVE_ENTITLEMENT_INPUT','ENTITLEMENT_COMPONENT',
        'PAY_STATE_FALLBACK','PAYEE_BASELINE_INPUT','CANONICAL_INPUT']::text[]
    )
    ON CONFLICT(build_id,timesheet_id) DO UPDATE
    SET seed_reasons=(SELECT array_agg(DISTINCT reason ORDER BY reason)
      FROM unnest(scope_row.seed_reasons||EXCLUDED.seed_reasons) AS reason),
        updated_at_utc=clock_timestamp()
    WHERE scope_row.candidate_id=EXCLUDED.candidate_id
      AND scope_row.captured_dirty_generation=EXCLUDED.captured_dirty_generation;
    IF v_scope_exists THEN v_merged_count:=v_merged_count+1;
    ELSE v_inserted_count:=v_inserted_count+1; END IF;
  END LOOP;

  IF v_selected_count<v_limit THEN
    v_family_ordinal:=v_family_ordinal+1;
    v_last_key:=NULL;
  END IF;

  IF v_family_ordinal>10 THEN
    v_next_cursor:=jsonb_build_object(
      'cursor_kind','SEED_SCOPE_SEAL','cursor_version',1,'build_id',p_build_id,
      'candidate_id',p_candidate_id,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'page_number',1,'last_timesheet_id',NULL,'processed_row_count',0,
      'accumulated_row_count',0,'rolling_digest',md5('BPAY_SEED_SCOPE_V1'),
      'previous_page_digest',NULL
    );
  ELSE
    v_next_family:=(ARRAY['ACTIVE_STATE','CURRENT_SOURCE_OWNER','OPEN_ADVANCE',
      'OPEN_FINANCE_COMPONENT','ACTIVE_RESERVATION','ACTIVE_OVERRIDE','UNPAID_ADJUSTMENT',
      'ACTIVE_SNOOZE','TARGETED_ID','FORCED_ID'])[v_family_ordinal];
    v_next_cursor:=jsonb_build_object(
      'cursor_kind','SCOPE_SELECT','cursor_version',1,'build_id',p_build_id,
      'candidate_id',p_candidate_id,'seed_family',v_next_family,
      'seed_family_ordinal',v_family_ordinal,'last_source_key',v_last_key,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'processed_source_rows',v_processed_count
    );
  END IF;

  UPDATE private.banking_pay_workbench_economic_builds
  SET scope_cursor_json=v_next_cursor,scope_count=scope_count+v_inserted_count,
      updated_at_utc=clock_timestamp()
  WHERE id=p_build_id AND private_stage='PREPARE_SCOPE';

  RETURN jsonb_build_object(
    'ok',true,'build_id',p_build_id,'candidate_id',p_candidate_id,
    'cursor_kind',v_next_cursor->>'cursor_kind','cursor_version',1,
    'seed_family',COALESCE(v_next_cursor->>'seed_family','COMPLETE'),
    'processed_source_count',v_selected_count,'new_scope_row_count',v_inserted_count,
    'merged_scope_row_count',v_merged_count,'initial_scope_count',NULL,
    'initial_scope_digest',NULL,'initial_scope_sealed',false,'has_more',true,
    'next_cursor_json',v_next_cursor
  );
END;
$function$;

-- private.pay_workbench_candidate_physical_currentness_page_v1(uuid,uuid[],text,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_physical_currentness_page_v1(p_session_id uuid, p_candidate_ids uuid[], p_mode text DEFAULT 'TERMINAL_CURRENT'::text, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode,'TERMINAL_CURRENT')));
  v_allow_active_owner boolean := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    p_options_json->>'allow_active_owner','false'
  ))) IN ('true','t','1','yes','y','on');
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_id uuid;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_state public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_attestation jsonb := '{}'::jsonb;
  v_scope_ordinal bigint := 0;
  v_source_count integer := 0;
  v_ready_count integer := 0;
  v_active_noncurrent_preview_count integer := 0;
  v_active_noncurrent_source_count integer := 0;
  v_active_noncurrent_line_work_count integer := 0;
  v_source_minus_preview_count integer := 0;
  v_preview_minus_source_count integer := 0;
  v_duplicate_active_identity_count integer := 0;
  v_source_run_count integer := 0;
  v_source_publication_count integer := 0;
  v_source_build_run_id uuid := NULL::uuid;
  v_source_publication_id uuid := NULL::uuid;
  v_live_source_identity_digest text := NULL::text;
  v_live_preview_identity_digest text := NULL::text;
  v_live_source_digest text := NULL::text;
  v_selected_preview_count integer := 0;
  v_selected_session_count integer := 0;
  v_selection_consistent boolean := false;
  v_attestation_current boolean := false;
  v_active_owner_count integer := 0;
  v_active_owner_job_id uuid := NULL::uuid;
  v_active_owner_group_count integer := 0;
  v_current_owner_group_count integer := 0;
  v_older_owner_group_count integer := 0;
  v_unfenced_owner_group_count integer := 0;
  v_current_owner_group_key text := NULL::text;
  v_scope_pending_owner_group_key text := NULL::text;
  v_state_pending_owner_group_key text := NULL::text;
  v_active_owner_topology text := NULL::text;
  v_active_owner_job_ids jsonb := '[]'::jsonb;
  v_terminal_current boolean := false;
  v_current_or_active_owner boolean := false;
  v_reason text := NULL::text;
  v_proof_digest text := NULL::text;
  v_results jsonb := '[]'::jsonb;
  v_terminal_count integer := 0;
  v_current_or_owner_count integer := 0;
BEGIN
  IF p_session_id IS NULL
     OR p_candidate_ids IS NULL
     OR pg_catalog.cardinality(p_candidate_ids)=0
     OR pg_catalog.cardinality(p_candidate_ids)>100
     OR v_mode NOT IN ('TERMINAL_CURRENT','OBSERVE_ONLY')
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object'
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.jsonb_object_keys(COALESCE(p_options_json,'{}'::jsonb)) AS option_key(key)
       WHERE option_key.key NOT IN ('contract_version','allow_active_owner')
     )
     OR COALESCE(p_options_json->>'contract_version','1')<>'1'
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id)
       WHERE supplied.candidate_id IS NULL
     )
     OR (SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id))
          IS DISTINCT FROM
        (SELECT pg_catalog.count(DISTINCT supplied.candidate_id) FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id)) THEN
    RAISE EXCEPTION 'WORKBENCH_PHYSICAL_CURRENTNESS_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','WORKBENCH_PHYSICAL_CURRENTNESS_ARGUMENT_INVALID'
      )::text;
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id=p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WORKBENCH_PHYSICAL_CURRENTNESS_SESSION_MISSING'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','WORKBENCH_PHYSICAL_CURRENTNESS_SESSION_MISSING','session_id',p_session_id
      )::text;
  END IF;

  FOR v_candidate_id IN
    SELECT supplied.candidate_id
    FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id)
    ORDER BY supplied.candidate_id
  LOOP
    v_scope := NULL;
    v_state := NULL;
    v_registry := NULL;
    v_attestation := '{}'::jsonb;
    v_scope_ordinal := 0;
    v_source_count := 0;
    v_ready_count := 0;
    v_active_noncurrent_preview_count := 0;
    v_active_noncurrent_source_count := 0;
    v_active_noncurrent_line_work_count := 0;
    v_source_minus_preview_count := 0;
    v_preview_minus_source_count := 0;
    v_duplicate_active_identity_count := 0;
    v_source_run_count := 0;
    v_source_publication_count := 0;
    v_source_build_run_id := NULL::uuid;
    v_source_publication_id := NULL::uuid;
    v_live_source_identity_digest := NULL::text;
    v_live_preview_identity_digest := NULL::text;
    v_live_source_digest := NULL::text;
    v_selected_preview_count := 0;
    v_selected_session_count := 0;
    v_selection_consistent := false;
    v_attestation_current := false;
    v_active_owner_count := 0;
    v_active_owner_job_id := NULL::uuid;
    v_active_owner_group_count := 0;
    v_current_owner_group_count := 0;
    v_older_owner_group_count := 0;
    v_unfenced_owner_group_count := 0;
    v_current_owner_group_key := NULL::text;
    v_scope_pending_owner_group_key := NULL::text;
    v_state_pending_owner_group_key := NULL::text;
    v_active_owner_topology := NULL::text;
    v_active_owner_job_ids := '[]'::jsonb;
    v_terminal_current := false;
    v_current_or_active_owner := false;

    SELECT scope_row.* INTO v_scope
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id=p_session_id AND scope_row.candidate_id=v_candidate_id;

    SELECT state_row.* INTO v_state
    FROM public.banking_pay_workbench_session_candidate_state AS state_row
    WHERE state_row.session_id=p_session_id AND state_row.candidate_id=v_candidate_id;

    SELECT registry_row.* INTO v_registry
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry_row
    WHERE registry_row.candidate_id=v_candidate_id;

    v_attestation:=COALESCE(v_scope.certified_preview_publication_attestation_json,'{}'::jsonb);
    v_scope_ordinal:=COALESCE(v_scope.scope_ordinal,0);

    WITH current_source AS (
      SELECT
        public.pay_workbench_preview_section_from_line_json(source_row.source_row_json) AS section,
        source_row.line_key,
        source_row.source_ordinal,
        source_row.source_build_run_id,
        source_row.source_publication_id,
        source_row.source_row_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_row
      WHERE source_row.session_id=p_session_id
        AND source_row.candidate_id=v_candidate_id
        AND source_row.session_version=v_session.version
        AND source_row.source_change_seq=COALESCE(v_registry.current_source_change_seq,-1)
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(source_row.status,'')))='CURRENT'
    ), ready_preview AS (
      SELECT preview_row.section,preview_row.row_key,
        (preview_row.row_ordinal-(v_scope_ordinal*1000000))::bigint AS source_ordinal
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id=p_session_id
        AND preview_row.candidate_id=v_candidate_id
        AND preview_row.session_version=v_session.version
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status,'')))='READY'
    )
    SELECT
      (SELECT pg_catalog.count(*)::integer FROM current_source),
      (SELECT pg_catalog.count(*)::integer FROM ready_preview),
      (SELECT pg_catalog.count(DISTINCT source_build_run_id)::integer FROM current_source),
      (SELECT pg_catalog.count(DISTINCT source_publication_id)::integer FROM current_source),
      (SELECT pg_catalog.min(source_build_run_id::text)::uuid FROM current_source),
      (SELECT pg_catalog.min(source_publication_id::text)::uuid FROM current_source),
      (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        section||E'\x1f'||line_key||E'\x1f'||source_ordinal::text,E'\x1e'
        ORDER BY source_ordinal,section,line_key),'')) FROM current_source),
      (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        section||E'\x1f'||row_key||E'\x1f'||source_ordinal::text,E'\x1e'
        ORDER BY source_ordinal,section,row_key),'')) FROM ready_preview),
      (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        pg_catalog.md5(source_row_json::text),'' ORDER BY source_ordinal),'')) FROM current_source),
      (SELECT pg_catalog.count(*)::integer FROM (
        SELECT section,line_key,source_ordinal FROM current_source
        EXCEPT ALL
        SELECT section,row_key,source_ordinal FROM ready_preview
      ) AS source_diff),
      (SELECT pg_catalog.count(*)::integer FROM (
        SELECT section,row_key,source_ordinal FROM ready_preview
        EXCEPT ALL
        SELECT section,line_key,source_ordinal FROM current_source
      ) AS preview_diff),
      (SELECT COALESCE(pg_catalog.sum(duplicate_count-1),0)::integer FROM (
        SELECT pg_catalog.count(*)::integer AS duplicate_count
        FROM current_source GROUP BY section,line_key,source_ordinal HAVING pg_catalog.count(*)>1
        UNION ALL
        SELECT pg_catalog.count(*)::integer AS duplicate_count
        FROM ready_preview GROUP BY section,row_key,source_ordinal HAVING pg_catalog.count(*)>1
      ) AS duplicates)
    INTO v_source_count,v_ready_count,v_source_run_count,v_source_publication_count,
      v_source_build_run_id,v_source_publication_id,v_live_source_identity_digest,
      v_live_preview_identity_digest,v_live_source_digest,v_source_minus_preview_count,
      v_preview_minus_source_count,v_duplicate_active_identity_count;

    SELECT pg_catalog.count(*)::integer
    INTO v_active_noncurrent_preview_count
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id=p_session_id
      AND preview_row.candidate_id=v_candidate_id
      AND preview_row.session_version=v_session.version
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status,''))) IN (
        'DIRTY','PENDING','DELTA_PENDING','RUNNING','QUEUED','ERROR','FAILED'
      );

    SELECT pg_catalog.count(*)::integer
    INTO v_active_noncurrent_source_count
    FROM public.banking_pay_workbench_candidate_source_lines AS source_row
    WHERE source_row.session_id=p_session_id
      AND source_row.candidate_id=v_candidate_id
      AND source_row.session_version=v_session.version
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(source_row.status,''))) IN (
        'DIRTY','PENDING','DELTA_PENDING','RUNNING','QUEUED','ERROR','FAILED'
      );

    SELECT pg_catalog.count(*)::integer
    INTO v_active_noncurrent_line_work_count
    FROM public.banking_pay_workbench_candidate_line_work AS line_work
    WHERE line_work.session_id=p_session_id
      AND line_work.candidate_id=v_candidate_id
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(line_work.status,''))) IN (
        'DIRTY','PENDING','READY','RUNNING','QUEUED','ERROR','FAILED'
      );

    WITH active_jobs AS (
      SELECT owner_job.id,owner_job.economic_build_id,
        CASE WHEN owner_job.economic_build_id IS NOT NULL
          THEN 'BUILD:'||owner_job.economic_build_id::text ELSE 'JOB:'||owner_job.id::text END
          AS owner_group_key,
        COALESCE(owner_build.source_change_seq,CASE
          WHEN COALESCE(owner_job.payload_json->>'source_change_seq','')~'^[0-9]{1,18}$'
          THEN (owner_job.payload_json->>'source_change_seq')::bigint END) AS owner_source_change_seq,
        COALESCE(owner_build.captured_candidate_generation,owner_job.scope_change_generation,CASE
          WHEN COALESCE(owner_job.payload_json->>'scope_change_generation','')~'^[0-9]{1,18}$'
          THEN (owner_job.payload_json->>'scope_change_generation')::bigint END) AS owner_dirty_generation
      FROM public.banking_pay_workbench_jobs AS owner_job
      LEFT JOIN private.banking_pay_workbench_economic_builds AS owner_build
        ON owner_build.id=owner_job.economic_build_id
      WHERE owner_job.session_id=p_session_id
        AND owner_job.candidate_id=v_candidate_id
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(owner_job.status,''))) IN ('QUEUED','RUNNING')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(owner_job.job_type,''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD','WORKBENCH_CANDIDATE_DELTA_REFRESH'
        )
      ORDER BY owner_job.created_at_utc,owner_job.id
      LIMIT 101
    ), owner_groups AS (
      SELECT owner_group_key,
        pg_catalog.count(*)::integer AS active_job_count,
        pg_catalog.count(DISTINCT owner_source_change_seq)::integer AS source_sequence_count,
        pg_catalog.count(DISTINCT owner_dirty_generation)::integer AS dirty_generation_count,
        pg_catalog.min(owner_source_change_seq) AS owner_source_change_seq,
        pg_catalog.min(owner_dirty_generation) AS owner_dirty_generation,
        pg_catalog.min(id::text)::uuid AS representative_job_id
      FROM active_jobs
      GROUP BY owner_group_key
    ), classified_groups AS (
      SELECT owner_groups.*,
        owner_groups.source_sequence_count=1
          AND owner_groups.dirty_generation_count=1
          AND owner_groups.owner_source_change_seq IS NOT DISTINCT FROM v_registry.current_source_change_seq
          AND owner_groups.owner_dirty_generation IS NOT DISTINCT FROM v_registry.dirty_generation
          AS is_current_authority,
        owner_groups.source_sequence_count=1
          AND owner_groups.dirty_generation_count=1
          AND owner_groups.owner_source_change_seq<v_registry.current_source_change_seq
          AND owner_groups.owner_dirty_generation<v_registry.dirty_generation
          AS is_provably_older
      FROM owner_groups
    )
    SELECT
      (SELECT pg_catalog.count(*)::integer FROM active_jobs),
      (SELECT pg_catalog.count(*)::integer FROM owner_groups),
      (SELECT pg_catalog.count(*)::integer FROM classified_groups WHERE is_current_authority),
      (SELECT pg_catalog.count(*)::integer FROM classified_groups WHERE is_provably_older),
      (SELECT pg_catalog.count(*)::integer FROM classified_groups
        WHERE is_current_authority IS NOT TRUE AND is_provably_older IS NOT TRUE),
      (SELECT pg_catalog.min(owner_group_key) FROM classified_groups WHERE is_current_authority),
      (SELECT pg_catalog.min(representative_job_id::text)::uuid
        FROM classified_groups WHERE is_current_authority),
      COALESCE((SELECT pg_catalog.jsonb_agg(id::text ORDER BY id) FROM active_jobs),'[]'::jsonb)
    INTO v_active_owner_count,v_active_owner_group_count,v_current_owner_group_count,
         v_older_owner_group_count,v_unfenced_owner_group_count,v_current_owner_group_key,
         v_active_owner_job_id,v_active_owner_job_ids;

    SELECT CASE WHEN pending_job.economic_build_id IS NOT NULL
             THEN 'BUILD:'||pending_job.economic_build_id::text ELSE 'JOB:'||pending_job.id::text END
    INTO v_scope_pending_owner_group_key
    FROM public.banking_pay_workbench_jobs AS pending_job
    WHERE pending_job.id=v_scope.pending_job_id;

    SELECT CASE WHEN pending_job.economic_build_id IS NOT NULL
             THEN 'BUILD:'||pending_job.economic_build_id::text ELSE 'JOB:'||pending_job.id::text END
    INTO v_state_pending_owner_group_key
    FROM public.banking_pay_workbench_jobs AS pending_job
    WHERE pending_job.id=v_state.pending_job_id;

    SELECT pg_catalog.count(*)::integer
    INTO v_selected_preview_count
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id=p_session_id
      AND preview_row.candidate_id=v_candidate_id
      AND preview_row.session_version=v_session.version
      AND preview_row.status='READY'
      AND preview_row.selected IS TRUE
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state,'')))='SELECTED';

    SELECT pg_catalog.count(*)::integer
    INTO v_selected_session_count
    FROM pg_catalog.jsonb_array_elements_text(
      CASE WHEN pg_catalog.jsonb_typeof(COALESCE(v_session.server_selected_preview_row_ids,'[]'::jsonb))='array'
        THEN COALESCE(v_session.server_selected_preview_row_ids,'[]'::jsonb) ELSE '[]'::jsonb END
    ) AS selected_id(value)
    JOIN public.banking_pay_workbench_preview_rows AS preview_row
      ON selected_id.value=preview_row.id::text
     AND preview_row.session_id=p_session_id
     AND preview_row.candidate_id=v_candidate_id
     AND preview_row.session_version=v_session.version
     AND preview_row.status='READY';

    v_selection_consistent:=v_selected_preview_count=v_selected_session_count
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS preview_row
        WHERE preview_row.session_id=p_session_id
          AND preview_row.candidate_id=v_candidate_id
          AND preview_row.session_version=v_session.version
          AND preview_row.status='READY'
          AND (
            preview_row.selected IS DISTINCT FROM (pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state,'')))='SELECTED')
            OR COALESCE((preview_row.row_json->>'selected')::boolean,false) IS DISTINCT FROM COALESCE(preview_row.selected,false)
            OR pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.row_json->>'selection_state','')))
                 IS DISTINCT FROM pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state,'')))
          )
      );

    v_attestation_current:=
      v_attestation->>'attestation_version'='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
      AND v_attestation->>'contract_version'='3'
      AND v_attestation->>'semantic_contract_version'='READY_TO_PAY_SEMANTIC_V2'
      AND COALESCE((v_attestation->>'semantic_ready')::boolean,false)
      AND COALESCE((v_attestation->>'parity_complete')::boolean,false)
      AND COALESCE(v_attestation->>'session_id','')=p_session_id::text
      AND COALESCE(v_attestation->>'candidate_id','')=v_candidate_id::text
      AND COALESCE(v_attestation->>'session_version','')~'^[0-9]{1,18}$'
      AND (v_attestation->>'session_version')::bigint=v_session.version
      AND COALESCE(v_attestation->>'source_change_seq','')~'^[0-9]{1,18}$'
      AND (v_attestation->>'source_change_seq')::bigint=COALESCE(v_registry.current_source_change_seq,-1)
      AND COALESCE(v_attestation->>'source_row_count','')~'^[0-9]{1,9}$'
      AND (v_attestation->>'source_row_count')::integer=v_source_count
      AND COALESCE(v_attestation->>'preview_row_count','')~'^[0-9]{1,9}$'
      AND (v_attestation->>'preview_row_count')::integer=v_ready_count
      AND v_attestation->>'source_build_run_id'=COALESCE(v_source_build_run_id::text,'')
      AND v_attestation->>'source_publication_id'=COALESCE(v_source_publication_id::text,'')
      AND v_attestation->>'source_identity_digest'=v_live_source_identity_digest
      AND v_attestation->>'preview_identity_digest'=v_live_preview_identity_digest
      AND v_attestation->>'source_digest'=v_live_source_digest;

    v_terminal_current:=
      pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status,'')))='OPEN'
      AND v_session.discarded_at_utc IS NULL
      AND v_scope.session_id IS NOT NULL
      AND v_state.session_id IS NOT NULL
      AND v_registry.candidate_id IS NOT NULL
      AND COALESCE(v_registry.current_source_change_seq,-1)=COALESCE(v_state.source_change_seq,-2)
      AND COALESCE(v_registry.current_source_change_seq,-1)=COALESCE(v_scope.certified_preview_publication_source_change_seq,-2)
      AND v_state.session_version=v_session.version
      AND v_scope.certified_preview_publication_session_version=v_session.version
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_state.status,''))) IN ('READY','COMPLETE')
      AND v_state.pending_job_id IS NULL
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_scope.status,''))) IN ('MATERIALISED','READY','COMPLETE','SOURCE_EMPTY')
      AND v_scope.pending_job_id IS NULL
      AND v_scope.dirty IS FALSE
      AND v_scope.certified_preview_publication_required IS TRUE
      AND v_scope.certified_preview_publication_parity_ok IS TRUE
      AND v_source_count=v_ready_count
      AND v_source_run_count<=1
      AND v_source_publication_count<=1
      AND v_source_minus_preview_count=0
      AND v_preview_minus_source_count=0
      AND v_duplicate_active_identity_count=0
      AND v_active_noncurrent_preview_count=0
      AND v_active_noncurrent_source_count=0
      AND v_active_noncurrent_line_work_count=0
      AND v_active_owner_count=0
      AND v_selection_consistent
      AND v_attestation_current;

    v_current_or_active_owner:=v_terminal_current OR (
      v_allow_active_owner
      AND v_current_owner_group_count=1
      AND v_unfenced_owner_group_count=0
      AND v_scope_pending_owner_group_key=v_current_owner_group_key
      AND v_state_pending_owner_group_key=v_current_owner_group_key
      AND v_scope.dirty IS TRUE
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_scope.status,'')))='SOURCE_BUILD_PENDING'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_state.status,''))) IN ('PENDING','DIRTY')
    );

    v_active_owner_topology:=CASE
      WHEN v_current_owner_group_count=1 AND v_unfenced_owner_group_count=0
        AND v_older_owner_group_count>0 THEN 'CURRENT_WITH_PROVEN_OLDER_OWNER'
      WHEN v_current_owner_group_count=1 AND v_unfenced_owner_group_count=0
        THEN 'CURRENT_ONLY'
      WHEN v_current_owner_group_count>1 THEN 'COMPETING_CURRENT_OWNERS'
      WHEN v_unfenced_owner_group_count>0 THEN 'UNFENCED_OWNER_PRESENT'
      ELSE NULL
    END;

    v_reason:=CASE
      WHEN v_terminal_current THEN 'TERMINAL_CURRENT'
      -- Preserve the established route value consumed by session refresh.
      -- The exact current/older owner topology is exposed separately.
      WHEN v_current_or_active_owner THEN 'ACTIVE_OWNER'
      WHEN v_active_noncurrent_preview_count>0 THEN 'ACTIVE_NONCURRENT_PREVIEW_ROWS'
      WHEN v_active_noncurrent_source_count>0 THEN 'ACTIVE_NONCURRENT_SOURCE_ROWS'
      WHEN v_active_noncurrent_line_work_count>0 THEN 'ACTIVE_NONCURRENT_LINE_WORK'
      WHEN v_source_minus_preview_count>0 OR v_preview_minus_source_count>0 THEN 'SOURCE_PREVIEW_IDENTITY_MISMATCH'
      WHEN v_duplicate_active_identity_count>0 THEN 'DUPLICATE_ACTIVE_IDENTITY'
      WHEN v_attestation_current IS NOT TRUE THEN 'ATTESTATION_NOT_CURRENT'
      WHEN v_selection_consistent IS NOT TRUE THEN 'SELECTION_STATE_MISMATCH'
      WHEN v_unfenced_owner_group_count>0 THEN 'ACTIVE_OWNER_AUTHORITY_UNFENCED'
      WHEN v_current_owner_group_count>1 THEN 'COMPETING_CURRENT_AUTHORITY_OWNERS'
      WHEN v_active_owner_count>0 THEN 'ACTIVE_OWNER_NOT_EXACT'
      ELSE 'TERMINAL_STATE_NOT_CURRENT'
    END;

    v_proof_digest:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
      pg_catalog.concat_ws('|','WORKBENCH_PHYSICAL_CURRENTNESS_V1',p_session_id::text,
        v_session.version::text,v_candidate_id::text,COALESCE(v_registry.current_source_change_seq,-1)::text,
        COALESCE(v_registry.dirty_generation,-1)::text,COALESCE(v_source_build_run_id::text,''),
        COALESCE(v_source_publication_id::text,''),v_source_count::text,v_ready_count::text,
        v_active_noncurrent_preview_count::text,v_active_noncurrent_source_count::text,
        v_active_noncurrent_line_work_count::text,v_source_minus_preview_count::text,
        v_preview_minus_source_count::text,COALESCE(v_live_source_identity_digest,''),
        COALESCE(v_live_preview_identity_digest,''),v_attestation_current::text,
        v_active_owner_group_count::text,v_current_owner_group_count::text,
        v_older_owner_group_count::text,v_unfenced_owner_group_count::text,
        COALESCE(v_current_owner_group_key,''),COALESCE(v_active_owner_topology,''),
        v_terminal_current::text,
        v_current_or_active_owner::text,v_reason),
      'UTF8'),'sha256'),'hex');

    v_results:=v_results||pg_catalog.jsonb_build_array(pg_catalog.jsonb_strip_nulls(
      pg_catalog.jsonb_build_object(
        'candidate_id',v_candidate_id,'terminal_current',v_terminal_current,
        'current_or_active_owner',v_current_or_active_owner,'currentness_reason',v_reason,
        'session_version',v_session.version,'session_status',v_session.status,
        'source_change_seq',v_registry.current_source_change_seq,
        'dirty_generation',v_registry.dirty_generation,'source_build_run_id',v_source_build_run_id,
        'candidate_state_status',v_state.status,
        'candidate_state_source_change_seq',v_state.source_change_seq,
        'candidate_state_pending_job_id',v_state.pending_job_id,
        'scope_status',v_scope.status,'scope_dirty',v_scope.dirty,
        'scope_pending_job_id',v_scope.pending_job_id,
        'scope_publication_required',v_scope.certified_preview_publication_required,
        'scope_publication_parity_ok',v_scope.certified_preview_publication_parity_ok,
        'scope_publication_source_change_seq',v_scope.certified_preview_publication_source_change_seq,
        'source_publication_id',v_source_publication_id,'current_source_count',v_source_count,
        'ready_preview_count',v_ready_count,'active_noncurrent_preview_count',v_active_noncurrent_preview_count,
        'active_noncurrent_source_count',v_active_noncurrent_source_count,
        'active_noncurrent_line_work_count',v_active_noncurrent_line_work_count,
        'source_minus_preview_count',v_source_minus_preview_count,
        'preview_minus_source_count',v_preview_minus_source_count,
        'duplicate_active_identity_count',v_duplicate_active_identity_count,
        'live_source_identity_digest',v_live_source_identity_digest,
        'live_preview_identity_digest',v_live_preview_identity_digest,
        'attested_source_identity_digest',v_attestation->>'source_identity_digest',
        'attested_preview_identity_digest',v_attestation->>'preview_identity_digest',
        'attestation_current',v_attestation_current,'selection_consistent',v_selection_consistent,
        'active_owner_count',v_active_owner_count,'active_owner_job_ids',v_active_owner_job_ids,
        'active_owner_group_count',v_active_owner_group_count,
        'current_owner_group_count',v_current_owner_group_count,
        'older_owner_group_count',v_older_owner_group_count,
        'unfenced_owner_group_count',v_unfenced_owner_group_count,
        'active_owner_topology',v_active_owner_topology,
        'current_owner_group_key',v_current_owner_group_key,
        'scope_pending_owner_group_key',v_scope_pending_owner_group_key,
        'state_pending_owner_group_key',v_state_pending_owner_group_key,
        'active_owner_job_id',v_active_owner_job_id,
        'proof_digest',v_proof_digest
      )
    ));
    v_terminal_count:=v_terminal_count+CASE WHEN v_terminal_current THEN 1 ELSE 0 END;
    v_current_or_owner_count:=v_current_or_owner_count+CASE WHEN v_current_or_active_owner THEN 1 ELSE 0 END;
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','WORKBENCH_PHYSICAL_CURRENTNESS_V1','mode',v_mode,
    'session_id',p_session_id,'candidate_count',pg_catalog.cardinality(p_candidate_ids),
    'terminal_current_count',v_terminal_count,'current_or_active_owner_count',v_current_or_owner_count,
    'all_terminal_current',v_terminal_count=pg_catalog.cardinality(p_candidate_ids),
    'all_current_or_active_owner',v_current_or_owner_count=pg_catalog.cardinality(p_candidate_ids),
    'candidate_results',v_results
  );
END;
$function$;

-- private.pay_workbench_candidate_reuse_source_select_v1(uuid,uuid,bigint,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_reuse_source_select_v1(p_target_session_id uuid, p_candidate_id uuid, p_source_change_seq bigint, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_settings public.settings_defaults%ROWTYPE;
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_certification jsonb := '{}'::jsonb;
  v_examined integer := 0;
  v_nonempty_reuse_enabled boolean := false;
  v_empty_reuse_enabled boolean := false;
BEGIN
  IF p_target_session_id IS NULL OR p_candidate_id IS NULL OR p_source_change_seq IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'reuse_available',false,
      'reason','TARGET_CANDIDATE_AND_SEQUENCE_REQUIRED',
      'required_refresh_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'sources_examined',0
    );
  END IF;

  SELECT settings_row.* INTO v_settings
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  v_nonempty_reuse_enabled := pg_catalog.lower(coalesce(
    pg_catalog.to_jsonb(v_settings)->>'banking_pay_workbench_clone_bounded_reuse_v2_enabled','false'
  )) IN ('true','t','1','yes','y','on');
  v_empty_reuse_enabled := pg_catalog.lower(coalesce(
    pg_catalog.to_jsonb(v_settings)->>'banking_pay_workbench_clone_source_empty_reuse_enabled','false'
  )) IN ('true','t','1','yes','y','on');

  IF v_nonempty_reuse_enabled IS NOT TRUE
     AND v_empty_reuse_enabled IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'reuse_available',false,
      'reason','CERTIFIED_REUSE_V2_DISABLED',
      'required_refresh_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'sources_examined',0
    );
  END IF;

  FOR v_build IN
    SELECT candidate_build.*
    FROM private.banking_pay_workbench_economic_builds AS candidate_build
    WHERE candidate_build.candidate_id=p_candidate_id
      AND candidate_build.source_change_seq=p_source_change_seq
      AND candidate_build.status='COMPLETE'
      AND candidate_build.private_stage='COMPLETE'
      AND candidate_build.completed_at_utc IS NOT NULL
      AND candidate_build.failure_json='{}'::jsonb
      AND candidate_build.session_id<>p_target_session_id
      AND candidate_build.dependency_closure_sealed_at_utc IS NOT NULL
      AND candidate_build.dependency_edge_stream_complete IS TRUE
      AND candidate_build.edge_tag_stream_complete IS TRUE
      AND candidate_build.sealed_fingerprint_digest IS NOT NULL
      AND candidate_build.canonical_digest IS NOT NULL
      AND pg_catalog.lower(coalesce(candidate_build.publication_cursor_json->>'terminal','false'))
            IN ('true','t','1','yes','y','on')
    ORDER BY candidate_build.completed_at_utc DESC,candidate_build.id DESC
    LIMIT 16
  LOOP
    v_examined := v_examined+1;

    v_certification := private.pay_workbench_session_clone_bounded_certification_v1(
      v_build.session_id,
      p_target_session_id,
      p_candidate_id,
      pg_catalog.jsonb_strip_nulls(
        coalesce(p_options_json,'{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'source_session_id',v_build.session_id::text,
          'target_session_id',p_target_session_id::text,
          'source_selection_authorised',true,
          'allow_session_rebase',true,
          'rebase_simple_rows_only',true,
          'certification_version',2
        )
      )
    );

    IF coalesce((v_certification->>'clone_eligible')::boolean,false) IS TRUE
       AND NULLIF(v_certification->>'original_economic_build_id','')=v_build.id::text
       AND (
         (coalesce(v_certification->>'source_mode','NONEMPTY')='SOURCE_EMPTY' AND v_empty_reuse_enabled IS TRUE)
         OR (coalesce(v_certification->>'source_mode','NONEMPTY')<>'SOURCE_EMPTY' AND v_nonempty_reuse_enabled IS TRUE)
       ) THEN
      RETURN pg_catalog.jsonb_strip_nulls(
        v_certification
        || pg_catalog.jsonb_build_object(
          'reuse_available',true,
          'selected_source_session_id',v_build.session_id::text,
          'selected_economic_build_id',v_build.id::text,
          'selected_source_build_run_id',v_build.source_build_run_id::text,
          'sources_examined',v_examined,
          'search_limit',16
        )
      );
    END IF;
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'reuse_available',false,
    'reason','NO_CERTIFIED_REUSE_SOURCE_IN_BOUNDED_WINDOW',
    'required_refresh_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'sources_examined',v_examined,
    'search_limit',16
  );
END;
$function$;

-- private.pay_workbench_candidate_session_version_rebase_v1(uuid,uuid,bigint,bigint,uuid)
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_session_version_rebase_v1(p_session_id uuid, p_candidate_id uuid, p_from_session_version bigint, p_to_session_version bigint, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_state public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_from_version bigint;
  v_source_change_seq bigint;
  v_source_build_run_id uuid;
  v_source_publication_id uuid;
  v_source_count integer := 0;
  v_preview_count integer := 0;
  v_source_run_count integer := 0;
  v_source_publication_count integer := 0;
  v_source_minus_preview_count integer := 0;
  v_preview_minus_source_count integer := 0;
  v_active_job_count integer := 0;
  v_existing_target_source_count integer := 0;
  v_existing_target_preview_count integer := 0;
  v_source_identity_digest text;
  v_preview_identity_digest text;
  v_source_digest text;
  v_attestation jsonb := '{}'::jsonb;
  v_currentness jsonb := '{}'::jsonb;
  v_currentness_result jsonb := '{}'::jsonb;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_invalid_selectable_count integer := 0;
  v_selected_preview_count integer := 0;
  v_selected_session_count integer := 0;
  v_selection_consistent boolean := false;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL
     OR p_from_session_version IS NULL OR p_to_session_version IS NULL
     OR p_actor_user_id IS NULL
     OR p_from_session_version < 1
     OR p_to_session_version <> p_from_session_version + 1 THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_REBASE_ARGUMENT_INVALID'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_row
  WHERE actor_row.id = p_actor_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_REBASE_ACTOR_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL
     OR v_session.version IS DISTINCT FROM p_to_session_version THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'rebased', false, 'reason', 'SESSION_NOT_REBASEABLE'
    );
  END IF;
  v_from_version := p_from_session_version;

  SELECT registry_row.*
  INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry_row
  WHERE registry_row.candidate_id = p_candidate_id
  FOR UPDATE;

  SELECT scope_row.*
  INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  SELECT state_row.*
  INTO v_state
  FROM public.banking_pay_workbench_session_candidate_state AS state_row
  WHERE state_row.session_id = p_session_id
    AND state_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF v_registry.candidate_id IS NULL
     OR v_scope.session_id IS NULL
     OR v_state.session_id IS NULL
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_registry.initialisation_status, ''))) <> 'READY'
     OR v_registry.evaluated_generation IS DISTINCT FROM v_registry.dirty_generation
     OR v_scope.dirty IS NOT FALSE
     OR v_scope.pending_job_id IS NOT NULL
     OR v_state.pending_job_id IS NOT NULL
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_scope.status, '')))
          NOT IN ('MATERIALISED', 'READY', 'COMPLETE', 'SOURCE_EMPTY')
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_state.status, '')))
          NOT IN ('READY', 'COMPLETE')
     OR v_scope.certified_preview_publication_required IS NOT TRUE
     OR v_scope.certified_preview_publication_parity_ok IS NOT TRUE
     OR v_scope.certified_preview_publication_session_version IS DISTINCT FROM v_from_version
     OR v_state.session_version IS DISTINCT FROM v_from_version
     OR v_scope.certified_preview_publication_source_change_seq
          IS DISTINCT FROM v_registry.current_source_change_seq
     OR v_state.source_change_seq IS DISTINCT FROM v_registry.current_source_change_seq
     OR v_scope.certified_preview_publication_attestation_json->>'attestation_version'
          IS DISTINCT FROM 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
     OR v_scope.certified_preview_publication_attestation_json->>'contract_version'
          IS DISTINCT FROM '3'
     OR v_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
          IS DISTINCT FROM 'READY_TO_PAY_SEMANTIC_V2'
     OR COALESCE((v_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean, false) IS NOT TRUE
     OR COALESCE((v_scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean, false) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'rebased', false, 'reason', 'CANDIDATE_AUTHORITY_NOT_CLEAN_VERSION_ONLY'
    );
  END IF;

  v_source_change_seq := v_registry.current_source_change_seq;

  PERFORM 1
  FROM public.banking_pay_workbench_candidate_source_lines AS source_lock
  WHERE source_lock.session_id = p_session_id
    AND source_lock.candidate_id = p_candidate_id
    AND source_lock.session_version IN (v_from_version, v_session.version)
  ORDER BY source_lock.session_version, source_lock.source_ordinal, source_lock.id
  FOR UPDATE;

  PERFORM 1
  FROM public.banking_pay_workbench_preview_rows AS preview_lock
  WHERE preview_lock.session_id = p_session_id
    AND preview_lock.candidate_id = p_candidate_id
    AND preview_lock.session_version IN (v_from_version, v_session.version)
  ORDER BY preview_lock.session_version, preview_lock.row_ordinal, preview_lock.id
  FOR UPDATE;

  PERFORM 1
  FROM public.banking_pay_workbench_candidate_line_work AS line_lock
  WHERE line_lock.session_id = p_session_id
    AND line_lock.candidate_id = p_candidate_id
  ORDER BY line_lock.line_ordinal, line_lock.id
  FOR UPDATE;

  SELECT pg_catalog.count(*)::integer
  INTO v_active_job_count
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.session_id = p_session_id
    AND job_row.candidate_id = p_candidate_id
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(job_row.status, '')))
          IN ('QUEUED', 'PENDING', 'CLAIMED', 'RUNNING', 'PROCESSING');

  SELECT pg_catalog.count(*)::integer
  INTO v_existing_target_source_count
  FROM public.banking_pay_workbench_candidate_source_lines AS target_source
  WHERE target_source.session_id = p_session_id
    AND target_source.candidate_id = p_candidate_id
    AND target_source.session_version = v_session.version
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(target_source.status, ''))) = 'CURRENT';

  SELECT pg_catalog.count(*)::integer
  INTO v_existing_target_preview_count
  FROM public.banking_pay_workbench_preview_rows AS target_preview
  WHERE target_preview.session_id = p_session_id
    AND target_preview.candidate_id = p_candidate_id
    AND target_preview.session_version = v_session.version
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(target_preview.status, ''))) = 'READY';

  WITH source_rows AS (
    SELECT
      public.pay_workbench_preview_section_from_line_json(source_row.source_row_json) AS section,
      source_row.line_key,
      source_row.source_ordinal,
      source_row.source_build_run_id,
      source_row.source_publication_id,
      source_row.source_row_json
    FROM public.banking_pay_workbench_candidate_source_lines AS source_row
    WHERE source_row.session_id = p_session_id
      AND source_row.candidate_id = p_candidate_id
      AND source_row.session_version = v_from_version
      AND source_row.source_change_seq = v_source_change_seq
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(source_row.status, ''))) = 'CURRENT'
  ), preview_rows AS (
    SELECT
      preview_row.section,
      preview_row.row_key,
      (preview_row.row_ordinal - (v_scope.scope_ordinal * 1000000))::bigint AS source_ordinal
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.candidate_id = p_candidate_id
      AND preview_row.session_version = v_from_version
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status, ''))) = 'READY'
  )
  SELECT
    (SELECT pg_catalog.count(*)::integer FROM source_rows),
    (SELECT pg_catalog.count(*)::integer FROM preview_rows),
    (SELECT pg_catalog.count(DISTINCT source_build_run_id)::integer FROM source_rows),
    (SELECT pg_catalog.count(DISTINCT source_publication_id)::integer FROM source_rows),
    (SELECT pg_catalog.min(source_build_run_id::text)::uuid FROM source_rows),
    (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
      section || E'\x1f' || line_key || E'\x1f' || source_ordinal::text,
      E'\x1e' ORDER BY source_ordinal, section, line_key
    ), '')) FROM source_rows),
    (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
      section || E'\x1f' || row_key || E'\x1f' || source_ordinal::text,
      E'\x1e' ORDER BY source_ordinal, section, row_key
    ), '')) FROM preview_rows),
    (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
      pg_catalog.md5(source_row_json::text), '' ORDER BY source_ordinal
    ), '')) FROM source_rows),
    (SELECT pg_catalog.count(*)::integer FROM (
      SELECT section, line_key, source_ordinal FROM source_rows
      EXCEPT ALL
      SELECT section, row_key, source_ordinal FROM preview_rows
    ) AS source_diff),
    (SELECT pg_catalog.count(*)::integer FROM (
      SELECT section, row_key, source_ordinal FROM preview_rows
      EXCEPT ALL
      SELECT section, line_key, source_ordinal FROM source_rows
    ) AS preview_diff)
  INTO v_source_count, v_preview_count, v_source_run_count,
       v_source_publication_count, v_source_build_run_id,
       v_source_identity_digest, v_preview_identity_digest, v_source_digest,
       v_source_minus_preview_count, v_preview_minus_source_count;

  IF v_active_job_count <> 0
     OR v_existing_target_source_count <> 0
     OR v_existing_target_preview_count <> 0
     OR v_source_count = 0
     OR v_source_count IS DISTINCT FROM v_preview_count
     OR v_source_run_count <> 1
     OR v_source_publication_count <> 1
     OR v_source_minus_preview_count <> 0
     OR v_preview_minus_source_count <> 0
     OR v_scope.certified_preview_publication_source_build_run_id
          IS DISTINCT FROM v_source_build_run_id
     OR v_scope.certified_preview_publication_attestation_json->>'source_identity_digest'
          IS DISTINCT FROM v_source_identity_digest
     OR v_scope.certified_preview_publication_attestation_json->>'preview_identity_digest'
          IS DISTINCT FROM v_preview_identity_digest
     OR v_scope.certified_preview_publication_attestation_json->>'source_digest'
          IS DISTINCT FROM v_source_digest THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'rebased', false, 'reason', 'VERSION_REBASE_PARITY_NOT_EXACT'
    );
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_invalid_selectable_count
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND preview_row.session_version = v_from_version
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status, ''))) = 'READY'
    AND (
      preview_row.selected IS TRUE
      OR pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
    )
    AND NOT (
      pg_catalog.lower(pg_catalog.btrim(COALESCE(preview_row.row_json->>'draftable', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(preview_row.row_json->>'selection_allowed', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
    );

  SELECT pg_catalog.count(*)::integer
  INTO v_selected_preview_count
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND preview_row.session_version = v_from_version
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status, ''))) = 'READY'
    AND preview_row.selected IS TRUE
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state, ''))) = 'SELECTED';

  SELECT pg_catalog.count(*)::integer
  INTO v_selected_session_count
  FROM pg_catalog.jsonb_array_elements_text(
    CASE
      WHEN pg_catalog.jsonb_typeof(COALESCE(v_session.server_selected_preview_row_ids, '[]'::jsonb)) = 'array'
        THEN COALESCE(v_session.server_selected_preview_row_ids, '[]'::jsonb)
      ELSE '[]'::jsonb
    END
  ) AS selected_id(value)
  JOIN public.banking_pay_workbench_preview_rows AS preview_row
    ON selected_id.value = preview_row.id::text
   AND preview_row.session_id = p_session_id
   AND preview_row.candidate_id = p_candidate_id
   AND preview_row.session_version = v_from_version
   AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status, ''))) = 'READY';

  -- A false `server_selected_preview_row_ids_provided` flag means the session
  -- is using the preview rows' certified default selection, so an empty server
  -- id array is not an explicit "select none" decision.  Preserve those exact
  -- row-backed defaults during a same-session version rebase instead of
  -- unnecessarily rebuilding an unrelated candidate.
  v_selection_consistent := (
      v_session.server_selected_preview_row_ids_provided IS NOT TRUE
      OR v_selected_preview_count = v_selected_session_count
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.candidate_id = p_candidate_id
        AND preview_row.session_version = v_from_version
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status, ''))) = 'READY'
        AND (
          preview_row.selected IS DISTINCT FROM (
            pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
          )
          OR COALESCE((preview_row.row_json->>'selected')::boolean, false)
               IS DISTINCT FROM COALESCE(preview_row.selected, false)
          OR pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.row_json->>'selection_state', '')))
               IS DISTINCT FROM pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.selection_state, '')))
        )
    );

  IF v_invalid_selectable_count <> 0
     OR v_selection_consistent IS NOT TRUE
     OR COALESCE((v_scope.certified_preview_publication_attestation_json->>'invalid_selectable_row_count')::integer, 0) <> 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true, 'rebased', false, 'reason', 'VERSION_REBASE_SELECTION_NOT_EXACT'
    );
  END IF;

  v_source_publication_id := private.pay_workbench_source_publication_identity_v1(
    p_session_id, p_candidate_id, v_session.version,
    v_source_change_seq, v_source_build_run_id
  );

  BEGIN
    DROP TABLE IF EXISTS pg_temp._bpay_same_session_rebase_source;
    CREATE TEMPORARY TABLE pg_temp._bpay_same_session_rebase_source ON COMMIT DROP AS
    SELECT source_row.*
    FROM public.banking_pay_workbench_candidate_source_lines AS source_row
    WHERE source_row.session_id = p_session_id
      AND source_row.candidate_id = p_candidate_id
      AND source_row.session_version = v_from_version
      AND source_row.source_change_seq = v_source_change_seq
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(source_row.status, ''))) = 'CURRENT';

    UPDATE public.banking_pay_workbench_candidate_source_lines AS old_source
    SET status = 'SUPERSEDED', updated_at_utc = v_now
    WHERE old_source.session_id = p_session_id
      AND old_source.candidate_id = p_candidate_id
      AND old_source.session_version = v_from_version
      AND old_source.source_change_seq = v_source_change_seq
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(old_source.status, ''))) = 'CURRENT';

    INSERT INTO public.banking_pay_workbench_candidate_source_lines (
      session_id, candidate_id, session_version, source_change_seq,
      source_build_run_id, source_publication_id, source_ordinal, line_key,
      parent_line_key, split_suffix, timesheet_id, section, source_row_json,
      economic_key_json, contract_json, pay_channel_scope,
      refresh_scope_kind, status, created_at_utc, updated_at_utc
    )
    SELECT
      old_source.session_id, old_source.candidate_id, v_session.version,
      old_source.source_change_seq, old_source.source_build_run_id,
      v_source_publication_id, old_source.source_ordinal, old_source.line_key,
      old_source.parent_line_key, old_source.split_suffix, old_source.timesheet_id,
      old_source.section, old_source.source_row_json, old_source.economic_key_json,
      COALESCE(old_source.contract_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'authority_kind', 'CERTIFIED_CLONE',
          'invocation_kind', 'SESSION_VERSION_REBASE',
          'same_session_version_rebase_v1', pg_catalog.jsonb_build_object(
            'contract_version', 1,
            'authority_kind', 'CERTIFIED_CLONE',
            'invocation_kind', 'SESSION_VERSION_REBASE',
            'from_session_version', v_from_version,
            'to_session_version', v_session.version,
            'actor_user_id', p_actor_user_id::text,
            'rebased_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
      old_source.pay_channel_scope, 'CLONE_REBASE', 'CURRENT', v_now, v_now
    FROM pg_temp._bpay_same_session_rebase_source AS old_source;

    UPDATE public.banking_pay_workbench_preview_rows AS preview_update
    SET session_version = v_session.version,
        row_json = COALESCE(preview_update.row_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'session_id', p_session_id::text,
            'session_version', v_session.version,
            'same_session_version_rebase_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'authority_kind', 'CERTIFIED_CLONE',
              'invocation_kind', 'SESSION_VERSION_REBASE',
              'from_session_version', v_from_version,
              'to_session_version', v_session.version,
              'actor_user_id', p_actor_user_id::text,
              'rebased_at_utc', v_now::text,
              'physical_section_preserved', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
        updated_at_utc = v_now
    WHERE preview_update.session_id = p_session_id
      AND preview_update.candidate_id = p_candidate_id
      AND preview_update.session_version = v_from_version
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_update.status, ''))) = 'READY';

    UPDATE public.banking_pay_workbench_candidate_line_work AS line_update
    SET work_payload_json = COALESCE(line_update.work_payload_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'same_session_version_rebase_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'authority_kind', 'CERTIFIED_CLONE',
              'invocation_kind', 'SESSION_VERSION_REBASE',
              'from_session_version', v_from_version,
              'to_session_version', v_session.version,
              'actor_user_id', p_actor_user_id::text,
              'rebased_at_utc', v_now::text
            )
          ),
        result_row_json = COALESCE(line_update.result_row_json, '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'same_session_version_rebase_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'authority_kind', 'CERTIFIED_CLONE',
              'invocation_kind', 'SESSION_VERSION_REBASE',
              'from_session_version', v_from_version,
              'to_session_version', v_session.version,
              'actor_user_id', p_actor_user_id::text,
              'rebased_at_utc', v_now::text
            )
          ),
        updated_at_utc = v_now
    WHERE line_update.session_id = p_session_id
      AND line_update.candidate_id = p_candidate_id;

    v_candidate_state_result := public.pay_workbench_delta_update_candidate_state_v1(
      p_session_id,
      p_candidate_id,
      v_source_build_run_id,
      pg_catalog.jsonb_build_object(
        'context', 'CLONE_REBASE',
        'session_version', v_session.version,
        'source_change_seq', v_source_change_seq,
        'authority_kind', 'CERTIFIED_CLONE',
        'invocation_kind', 'SESSION_VERSION_REBASE',
        'actor_user_id', p_actor_user_id::text
      )
    );
    IF COALESCE((v_candidate_state_result->>'ok')::boolean, false) IS NOT TRUE
       OR COALESCE((v_candidate_state_result->>'fallback_required')::boolean, false) IS TRUE
       OR COALESCE((v_candidate_state_result->>'candidate_state_updated')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_REBASE_CANDIDATE_STATE_FAILED'
        USING ERRCODE = 'P0001';
    END IF;

    WITH current_source AS (
      SELECT
        public.pay_workbench_preview_section_from_line_json(source_row.source_row_json) AS section,
        source_row.line_key,
        source_row.source_ordinal,
        source_row.source_row_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_row
      WHERE source_row.session_id = p_session_id
        AND source_row.candidate_id = p_candidate_id
        AND source_row.session_version = v_session.version
        AND source_row.source_change_seq = v_source_change_seq
        AND source_row.source_publication_id = v_source_publication_id
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(source_row.status, ''))) = 'CURRENT'
    ), ready_preview AS (
      SELECT preview_row.section, preview_row.row_key,
        (preview_row.row_ordinal - (v_scope.scope_ordinal * 1000000))::bigint AS source_ordinal
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.candidate_id = p_candidate_id
        AND preview_row.session_version = v_session.version
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(preview_row.status, ''))) = 'READY'
    )
    SELECT
      pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        section || E'\x1f' || line_key || E'\x1f' || source_ordinal::text,
        E'\x1e' ORDER BY source_ordinal, section, line_key
      ), '')),
      (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        section || E'\x1f' || row_key || E'\x1f' || source_ordinal::text,
        E'\x1e' ORDER BY source_ordinal, section, row_key
      ), '')) FROM ready_preview),
      pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        pg_catalog.md5(source_row_json::text), '' ORDER BY source_ordinal
      ), ''))
    INTO v_source_identity_digest, v_preview_identity_digest, v_source_digest
    FROM current_source;

    v_attestation := COALESCE(v_scope.certified_preview_publication_attestation_json, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session.version,
        'source_change_seq', v_source_change_seq,
        'source_build_run_id', v_source_build_run_id::text,
        'source_publication_id', v_source_publication_id::text,
        'source_row_count', v_source_count,
        'preview_row_count', v_preview_count,
        'invalid_selectable_row_count', 0,
        'authority_kind', 'CERTIFIED_CLONE',
        'invocation_kind', 'SESSION_VERSION_REBASE',
        'source_identity_digest', v_source_identity_digest,
        'preview_identity_digest', v_preview_identity_digest,
        'source_digest', v_source_digest,
        'same_session_version_rebase_v1', pg_catalog.jsonb_build_object(
          'contract_version', 1,
          'authority_kind', 'CERTIFIED_CLONE',
          'invocation_kind', 'SESSION_VERSION_REBASE',
          'from_session_version', v_from_version,
          'to_session_version', v_session.version,
          'actor_user_id', p_actor_user_id::text,
          'rebased_at_utc', v_now::text,
          'source_rows_rederived', false,
          'preview_economics_changed', false,
          'physical_sections_changed', false,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      );

    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = 'READY',
        dirty = false,
        pending_job_id = NULL,
        error_json = NULL::jsonb,
        certified_preview_publication_required = true,
        certified_preview_publication_parity_ok = true,
        certified_preview_publication_session_version = v_session.version,
        certified_preview_publication_source_change_seq = v_source_change_seq,
        certified_preview_publication_source_build_run_id = v_source_build_run_id,
        certified_preview_publication_source_publication_id = v_source_publication_id,
        certified_preview_publication_attestation_json = v_attestation,
        updated_at_utc = v_now
    WHERE scope_update.session_id = p_session_id
      AND scope_update.candidate_id = p_candidate_id;

    v_currentness := private.pay_workbench_candidate_physical_currentness_page_v1(
      p_session_id, ARRAY[p_candidate_id]::uuid[], 'TERMINAL_CURRENT',
      pg_catalog.jsonb_build_object('contract_version', '1', 'allow_active_owner', false)
    );
    v_currentness_result := COALESCE(v_currentness->'candidate_results'->0, '{}'::jsonb);

    IF COALESCE((v_currentness_result->>'terminal_current')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_REBASE_POST_FENCE_FAILED'
        USING ERRCODE = 'P0001';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'rebased', false,
      'reason', 'VERSION_REBASE_TRANSACTION_ROLLED_BACK',
      'failure_code', SQLSTATE
    );
  END;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'rebased', true,
    'reason', 'CLEAN_SAME_SESSION_VERSION_REBASE',
    'session_id', p_session_id,
    'candidate_id', p_candidate_id,
    'from_session_version', v_from_version,
    'to_session_version', v_session.version,
    'source_change_seq', v_source_change_seq,
    'source_build_run_id', v_source_build_run_id,
    'source_publication_id', v_source_publication_id,
    'source_row_count', v_source_count,
    'preview_row_count', v_preview_count,
    'physical_sections_changed', false,
    'source_rows_rederived', false,
    'preview_economics_changed', false,
    'post_draft_artifacts_touched', false,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- private.pay_workbench_candidate_source_build_chunk_legacy_v1(uuid,uuid,jsonb,jsonb,integer)
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_source_build_chunk_legacy_v1(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_payload_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_cursor jsonb:=COALESCE(p_cursor_json,'{}'::jsonb);
  v_payload jsonb:=CASE WHEN jsonb_typeof(COALESCE(p_payload_json,'{}'::jsonb))='object'
    THEN COALESCE(p_payload_json,'{}'::jsonb) ELSE '{}'::jsonb END;
  v_build_id uuid:=NULLIF(v_payload->>'economic_build_id','')::uuid;
  v_attempt_id uuid:=NULLIF(v_payload->>'attempt_id','')::uuid;
  v_attempt_nonce uuid:=NULLIF(v_payload->>'attempt_nonce','')::uuid;
  v_stage text:=upper(COALESCE(NULLIF(v_payload->>'private_stage',''),NULLIF(v_cursor->>'cursor_kind','')));
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer:=LEAST(GREATEST(COALESCE(p_limit,25),1),500);
  -- Fact collection is intentionally capped independently of callers.  The
  -- complete candidate remains unbounded through durable continuation pages.
  v_fact_limit integer:=LEAST(GREATEST(COALESCE(p_limit,25),1),25);
  v_result jsonb;
  v_next jsonb;
  v_unit_key text:=NULLIF(v_cursor->>'dependency_unit_key','');
  v_fact_family text:=NULLIF(v_cursor->>'fact_family','');
  v_last_source_key text:=NULLIF(v_cursor->>'last_source_key','');
  v_page_number integer:=GREATEST(COALESCE((v_cursor->>'page_number')::integer,1),1);
  v_page_count integer:=0;
  v_page_digest text;
  v_cumulative_fact_count integer:=GREATEST(COALESCE((v_cursor->>'cumulative_fact_count')::integer,0),0);
  v_next_cumulative_fact_count integer:=0;
  v_cumulative_digest text:=COALESCE(NULLIF(v_cursor->>'cumulative_digest',''),md5('BPAY_FACT_STREAM_V2'));
  v_raw_physical_source_count bigint:=GREATEST(COALESCE((v_cursor->>'raw_physical_source_count')::bigint,0),0);
  v_resolved_physical_source_count bigint:=GREATEST(COALESCE((v_cursor->>'resolved_physical_source_count')::bigint,0),0);
  v_failed_physical_source_count bigint:=GREATEST(COALESCE((v_cursor->>'failed_physical_source_count')::bigint,0),0);
  v_page_physical_source_count bigint:=0;
  v_page_resolved_source_count bigint:=0;
  v_page_failed_source_count bigint:=0;
  v_next_raw_physical_source_count bigint:=0;
  v_next_resolved_physical_source_count bigint:=0;
  v_next_failed_physical_source_count bigint:=0;
  v_raw_physical_amount_ex_vat numeric:=COALESCE((v_cursor->>'raw_physical_amount_ex_vat')::numeric,0);
  v_resolved_physical_amount_ex_vat numeric:=COALESCE((v_cursor->>'resolved_physical_amount_ex_vat')::numeric,0);
  v_page_physical_amount_ex_vat numeric:=0;
  v_page_resolved_amount_ex_vat numeric:=0;
  v_next_raw_physical_amount_ex_vat numeric:=0;
  v_next_resolved_physical_amount_ex_vat numeric:=0;
  v_expected_source_count integer;
  v_raw_source_has_more boolean:=false;
  v_has_more boolean:=false;
  v_is_final boolean:=false;
  v_last_page_key text;
  v_last_raw_physical_source_key text:=NULLIF(v_cursor->>'last_raw_physical_source_key','');
  v_next_last_raw_physical_source_key text;
  v_cursor_start_hash text;
  v_cursor_end_hash text;
  v_existing_page private.banking_pay_workbench_economic_build_fact_pages%ROWTYPE;
  v_previous_page private.banking_pay_workbench_economic_build_fact_pages%ROWTYPE;
  v_fact_page_timestamp timestamptz;
  v_replay_cursor jsonb;
  v_unit_ids uuid[]:=ARRAY[]::uuid[];
  v_family_ordinal integer;
  v_unit_families text[]:=ARRAY[
    'LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK',
    'ENTITLEMENT_COMPONENT','PAYEE_BASELINE_INPUT','CANONICAL_INPUT'
  ];
  v_global_families text[]:=ARRAY[
    'FINANCE_ITEM_AUTHORITY','RESERVATION_COMPONENT','FINANCE_CASE_IDENTITY','FINANCE_COMPONENT_IDENTITY',
    'PROTECTION_EVIDENCE','ALLOCATION_INPUT'
  ];
  v_scope_inserted integer:=0;
  v_derived_fact_count integer:=0;
  v_derived_settled_count integer:=0;
  v_derived_fallback_count integer:=0;
  v_live_page_ids uuid[]:=ARRAY[]::uuid[];
  v_input_phase text:=upper(COALESCE(NULLIF(v_cursor->>'input_phase',''),'PROJECTION'));
  v_input_projection_id uuid:=NULLIF(v_cursor->>'input_projection_id','')::uuid;
  v_next_projection_id uuid;
  v_projection_has_more boolean:=false;
  v_projection_phase_transition boolean:=false;
  v_projection_family_transition boolean:=false;
  v_occurrence_bundle jsonb:='{}'::jsonb;
  v_resolution_failure text;
  v_vector jsonb;
  v_envelope_version integer;
  v_envelope jsonb;
  v_envelope_evidence jsonb;
  v_vector_item record;
  v_scale_blocked boolean:=false;
  v_scale_block_reason text;
  v_sync_result jsonb;
  v_capture_timing_json jsonb:='{}'::jsonb;
  v_effect_plan jsonb:='[]'::jsonb;
  v_effect_plan_digest text:=md5('');
  v_effect_plan_count integer:=0;
  v_publish_now boolean:=false;
  v_published_count integer:=0;
  v_published_digest text;
  v_source_publication_id uuid:=NULL::uuid;
  v_existing_publication_count integer:=0;
  v_existing_publication_digest text:=NULL::text;
  v_candidate_pay_method text;
  v_actor_user_id uuid;
  v_expected_count integer;
  v_cleanup_kind text;
  v_cleanup_count integer:=0;
  v_bootstrap_stream text;
  v_bootstrap_next_stream text;
  v_bootstrap_last_key text;
  v_bootstrap_page_count integer:=0;
  v_bootstrap_registered integer:=0;
  v_bootstrap_has_more boolean:=false;
  v_bootstrap_has_dirty boolean:=false;
  v_bootstrap_classification_phase text;
  v_bootstrap_unit_key text;
  v_bootstrap_last_unit_key text;
  v_bootstrap_last_ordinal bigint:=0;
  v_bootstrap_unit_relevant boolean:=false;
  v_bootstrap_page_relevant boolean:=false;
  v_bootstrap_raw_current_count bigint:=0;
  v_bootstrap_resolved_current_count bigint:=0;
  v_bootstrap_raw_baseline_count bigint:=0;
  v_bootstrap_resolved_baseline_count bigint:=0;
  v_bootstrap_page_raw_current_count bigint:=0;
  v_bootstrap_page_resolved_current_count bigint:=0;
  v_bootstrap_page_raw_baseline_count bigint:=0;
  v_bootstrap_page_resolved_baseline_count bigint:=0;
  v_bootstrap_evidence_complete boolean:=false;
  v_bootstrap_reset_count integer:=0;
  v_bootstrap_id uuid;
  v_reservation_order_contract constant text:='RESERVATION_COMPONENT_SOURCE_KEY_C_V1';
  v_is_fresh_reservation_cursor boolean:=false;
  v_correction_scope_issue_request_id uuid;
  v_correction_scope_issue_code text;
BEGIN
  IF v_build_id IS NULL OR v_attempt_id IS NULL OR v_attempt_nonce IS NULL
     OR jsonb_typeof(v_cursor)<>'object' OR p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(p_candidate_id),24062027));
  SELECT * INTO v_registry FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE candidate_id=p_candidate_id FOR UPDATE;
  SELECT * INTO v_build FROM private.banking_pay_workbench_economic_builds
  WHERE id=v_build_id FOR UPDATE;
  SELECT * INTO v_session FROM public.banking_pay_workbench_sessions
  WHERE id=p_session_id;
  -- Candidate source work never mutates the shared session row here. Holding
  -- it FOR UPDATE made every candidate in one Workbench session execute
  -- serially and caused concurrent RPC-1 claims to time out. The immutable
  -- build freezes session_version, and terminal completion/publication owns
  -- the exclusive session lock plus the final generation/version fences.
  IF v_registry.current_build_id IS DISTINCT FROM v_build_id
     OR v_build.candidate_id IS DISTINCT FROM p_candidate_id
     OR v_build.session_id IS DISTINCT FROM p_session_id
     OR v_build.session_version IS DISTINCT FROM v_session.version
     OR v_registry.dirty_generation IS DISTINCT FROM v_build.captured_candidate_generation
     OR v_registry.current_source_change_seq IS DISTINCT FROM v_build.source_change_seq
     OR v_build.private_stage IS DISTINCT FROM v_stage THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT' USING ERRCODE='40001';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_stage_attempts attempt
    WHERE attempt.id=v_attempt_id AND attempt.build_id=v_build_id
      AND attempt.attempt_nonce=v_attempt_nonce AND attempt.private_stage=v_stage
      AND attempt.attempt_status='STARTED' AND clock_timestamp()<attempt.lease_expires_at_utc
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  IF v_stage='PREPARE_SCOPE' THEN
    v_result:=private.pay_workbench_candidate_bounded_scope_v1(
      v_build_id,p_candidate_id,v_cursor,LEAST(v_limit,500),
      ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(v_payload->'targeted_timesheet_ids','[]'::jsonb)) value
        WHERE value ~* '^[0-9a-f-]{36}$' ORDER BY value::uuid),
      ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(v_payload->'force_include_timesheet_ids','[]'::jsonb)) value
        WHERE value ~* '^[0-9a-f-]{36}$' ORDER BY value::uuid),
      ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(v_payload->'exclude_timesheet_ids','[]'::jsonb)) value
        WHERE value ~* '^[0-9a-f-]{36}$' ORDER BY value::uuid),
      NULLIF(v_payload->>'client_filter_single','')::uuid
    );
    RETURN v_result||jsonb_build_object(
      'private_stage',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'stage_status','PREPARING','continuation_enqueued',false,
      'next_action',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id)
    );
  END IF;

  IF v_stage='DEPENDENCY_CLOSURE' THEN
    v_result:=private.pay_workbench_timesheet_dependency_closure_v2(v_build_id,v_cursor,LEAST(v_limit,25));
    RETURN v_result||jsonb_build_object(
      'private_stage',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'stage_status','PREPARING','continuation_enqueued',false,
      'next_action',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id)
    );
  END IF;

  IF v_stage='WORKSPACE_FACT' THEN
    -- Version 1.2.9: validate but never reconstruct a fact cursor.  The exact
    -- committed page-end JSON is the next invocation's page-start authority.
    v_cursor:=private.pay_workbench_fact_cursor_preserve_v2(v_cursor);
    IF NULLIF(v_cursor->>'build_id','')::uuid IS DISTINCT FROM v_build_id
       OR NULLIF(v_cursor->>'candidate_id','')::uuid IS DISTINCT FROM p_candidate_id
       OR COALESCE((v_cursor->>'captured_candidate_generation')::bigint,-1)
          IS DISTINCT FROM v_build.captured_candidate_generation
       OR COALESCE((v_cursor->>'captured_source_change_seq')::bigint,-1)
          IS DISTINCT FROM v_build.source_change_seq
       OR NULLIF(v_cursor->>'dependency_unit_key','') IS NULL
       OR NULLIF(v_cursor->>'fact_family','') IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    IF v_fact_family='RESERVATION_COMPONENT' THEN
      v_is_fresh_reservation_cursor:=
        v_page_number=1
        AND v_last_source_key IS NULL
        AND v_cursor->>'previous_page_digest' IS NULL
        AND v_cumulative_fact_count=0
        AND v_cumulative_digest=md5('BPAY_FACT_STREAM_V2')
        AND v_raw_physical_source_count=0
        AND v_resolved_physical_source_count=0
        AND v_failed_physical_source_count=0
        AND v_raw_physical_amount_ex_vat=0
        AND v_resolved_physical_amount_ex_vat=0
        AND v_last_raw_physical_source_key IS NULL
        AND COALESCE((v_cursor->>'terminal')::boolean,false)=false
        AND COALESCE((v_cursor->>'source_exhausted')::boolean,false)=false
        AND v_cursor->>'raw_terminal_source_key' IS NULL
        AND v_cursor->>'raw_page_evidence_digest' IS NULL
        AND NOT EXISTS(
          SELECT 1
          FROM private.banking_pay_workbench_economic_build_fact_pages page
          WHERE page.build_id=v_build_id
            AND page.dependency_unit_key=v_unit_key
            AND page.fact_family=v_fact_family
          LIMIT 1);
      IF NOT (v_cursor ? 'reservation_source_key_order_contract') THEN
        IF NOT v_is_fresh_reservation_cursor THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_RESERVATION_ORDER_CONTRACT_OBSOLETE'
            USING ERRCODE='40001';
        END IF;
        v_cursor:=v_cursor || jsonb_build_object(
          'reservation_source_key_order_contract',v_reservation_order_contract);
      ELSIF v_cursor->>'reservation_source_key_order_contract'
          <>v_reservation_order_contract THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_RESERVATION_ORDER_CONTRACT_OBSOLETE'
          USING ERRCODE='40001';
      END IF;
    END IF;
    IF v_build.dependency_closure_sealed_at_utc IS NULL OR EXISTS(
      SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=v_build_id AND closure_status<>'SEALED' LIMIT 1
    ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACTS_INCOMPLETE' USING ERRCODE='23514';
    END IF;

    -- A build that crossed an older bootstrap reset implementation can reach
    -- a fresh page-one cursor while its earlier bootstrap fact ledger is still
    -- attached.  Do not weaken the page-chain invariant or repair rows out of
    -- band.  Complete this exact material attempt by returning to the same
    -- bounded page -> fact -> scope reset owner used by current bootstrap
    -- classification.  The ordinary RPC-2 completion path then delivers the
    -- reset continuation atomically.
    IF v_page_number=1
       AND v_cumulative_fact_count=0
       AND v_cursor->>'previous_page_digest' IS NULL
       AND v_registry.initialisation_status='CLASSIFYING'
       AND v_registry.bootstrap_id IS NOT NULL
       AND EXISTS(
         SELECT 1
         FROM private.banking_pay_workbench_economic_build_fact_pages page
         WHERE page.build_id=v_build_id
           AND page.dependency_unit_key=v_unit_key
           AND page.fact_family=v_fact_family
         LIMIT 1
       ) THEN
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_registry.bootstrap_id,'bootstrap_stream','RESET_FACT_PAGES',
        'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,
        'recovery_reason','STALE_BOOTSTRAP_FACT_AUTHORITY');
      UPDATE private.banking_pay_workbench_economic_builds
      SET private_stage='BOOTSTRAP_DISCOVERY',updated_at_utc=clock_timestamp()
      WHERE id=v_build_id;
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET bootstrap_stream='RESET_FACT_PAGES',bootstrap_cursor_json=v_next,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','RESETTING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','classification_phase','RESET_FACT_PAGES',
        'recovery_reason','STALE_BOOTSTRAP_FACT_AUTHORITY');
    END IF;

    IF v_unit_key IS NULL THEN
      IF NOT EXISTS(SELECT 1
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id AND page.dependency_unit_key='GLOBAL'
          AND page.fact_family='FINANCE_ITEM_AUTHORITY'
          AND page.status='COMPLETED' AND page.is_family_final LIMIT 1) THEN
        v_unit_key:='GLOBAL';
        v_fact_family:='FINANCE_ITEM_AUTHORITY';
      ELSE
        SELECT dependency_unit_key INTO v_unit_key
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id
          AND NOT required_fact_families <@ completed_fact_families
        ORDER BY stable_ordinal LIMIT 1;
        IF v_unit_key IS NULL THEN v_unit_key:='GLOBAL'; END IF;
      END IF;
    END IF;
    IF v_fact_family IS NULL THEN
      v_fact_family:=CASE WHEN v_unit_key='GLOBAL' THEN v_global_families[1] ELSE v_unit_families[1] END;
    END IF;
    IF v_unit_key='GLOBAL' THEN
      v_family_ordinal:=array_position(v_global_families,v_fact_family);
    ELSE
      v_family_ordinal:=array_position(v_unit_families,v_fact_family);
      SELECT array_agg(timesheet_id ORDER BY stable_ordinal) INTO v_unit_ids
      FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key;
    END IF;
    IF v_family_ordinal IS NULL THEN RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023'; END IF;
    IF (v_unit_key='GLOBAL' AND v_input_phase IS DISTINCT FROM 'PHYSICAL_SOURCE')
       OR (v_unit_key<>'GLOBAL' AND v_fact_family='LIVE_ENTITLEMENT_INPUT'
         AND v_input_phase NOT IN ('PROJECTION','COMPONENTS'))
       OR (v_unit_key<>'GLOBAL' AND v_fact_family<>'LIVE_ENTITLEMENT_INPUT'
         AND v_input_phase IS DISTINCT FROM 'COMPONENTS') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    IF v_fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
       OR (v_fact_family='LIVE_ENTITLEMENT_INPUT' AND v_input_phase='COMPONENTS') THEN
      IF v_input_phase<>'COMPONENTS' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
      END IF;
      IF v_input_projection_id IS NULL THEN
        SELECT projection.timesheet_id INTO v_input_projection_id
        FROM private.banking_pay_workbench_economic_build_facts projection
        WHERE projection.build_id=v_build_id
          AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
          AND projection.dependency_unit_key=v_unit_key
          AND projection.source_relation='UNIT_PROJECTION'
        ORDER BY projection.timesheet_id,projection.natural_key LIMIT 1;
      END IF;
      IF v_input_projection_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_UNIT_PROJECTION_INCOMPLETE' USING ERRCODE='23514';
      END IF;
    END IF;
    CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_fact_page_v1(
      source_key text PRIMARY KEY,natural_key text NOT NULL,timesheet_id uuid NULL,
      subject_timesheet_ids uuid[] NOT NULL,source_relation text NOT NULL,source_id uuid NULL,
      economic_key_type text NULL,economic_key_value text NULL,
      amount_ex_vat numeric NULL,amount_inc_vat numeric NULL,
      truth_ex_vat numeric NULL,truth_inc_vat numeric NULL,
      baseline_ex_vat numeric NULL,baseline_inc_vat numeric NULL,
      reserved_source_amount numeric NULL,finance_case_id uuid NULL,
      finance_component_id uuid NULL,reservation_id uuid NULL,
      source_payload_json jsonb NOT NULL,financial_digest text NOT NULL
    ) ON COMMIT DROP;
    TRUNCATE pg_temp._bpay_wb_fact_page_v1;

    IF v_fact_family='FINANCE_ITEM_AUTHORITY' THEN
      v_occurrence_bundle:=private.pay_workbench_finance_item_authority_page_bundle_v1(
        v_build_id,
        CASE WHEN COALESCE(v_last_source_key,'') ~
          '^05:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN split_part(v_last_source_key,':',2)::uuid END,
        CASE WHEN COALESCE(v_last_source_key,'') ~
          '^05:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN split_part(v_last_source_key,':',3)::uuid END,
        v_fact_limit);
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT authority.source_key,md5('FINANCE_ITEM_AUTHORITY:'||authority.source_key),
        authority.resolved_timesheet_id,
        CASE WHEN authority.resolved_timesheet_id IS NULL THEN ARRAY[]::uuid[]
          ELSE ARRAY[authority.resolved_timesheet_id] END,
        'pay_batch_items',authority.pay_batch_item_id,
        authority.economic_key_type,authority.economic_key_value,
        authority.source_amount_ex_vat,authority.source_amount_inc_vat,
        NULL,NULL,NULL,NULL,NULL,
        authority.resolved_finance_case_id,authority.finance_component_id,NULL,
        authority.source_payload_json||jsonb_build_object(
          'authoritative_in_scope',authority.is_authoritative,
          'resolution_failure',authority.resolution_failure),
        authority.financial_digest
      FROM jsonb_to_recordset(COALESCE(v_occurrence_bundle->'rows','[]'::jsonb)) authority(
        source_key text,pay_batch_candidate_id uuid,pay_batch_item_id uuid,
        resolved_timesheet_id uuid,resolved_candidate_id uuid,resolved_finance_case_id uuid,
        finance_component_id uuid,economic_key_type text,economic_key_value text,
        source_amount_ex_vat numeric,source_amount_inc_vat numeric,is_authoritative boolean,
        source_payload_json jsonb,financial_digest text,resolution_failure text);
    ELSIF v_fact_family='LIVE_ENTITLEMENT_INPUT' AND v_input_phase='PROJECTION' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT projection.source_key,md5('UNIT_PROJECTION:'||projection.source_key),
        COALESCE(projection.projected_timesheet_id,projection.family_timesheet_id),
        ARRAY[projection.family_timesheet_id],
        'UNIT_PROJECTION',projection.family_timesheet_id,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
        NULL,NULL,NULL,NULL,
        jsonb_build_object('role','UNIT_PROJECTION','scope_family_key',projection.scope_family_key,
          'family_timesheet_id',projection.family_timesheet_id,
          'canonical_timesheet_id',projection.canonical_timesheet_id,
          'projected_timesheet_id',projection.projected_timesheet_id,
          'projection_resolution_status',projection.projection_resolution_status,
          'stable_ordinal',projection.stable_ordinal,
          'resolution_failure',CASE WHEN projection.projected_timesheet_id IS NULL
            THEN 'UNIT_PROJECTION_MISSING_CURRENT' END),
        md5(jsonb_build_object('family_timesheet_id',projection.family_timesheet_id,
          'scope_family_key',projection.scope_family_key,
          'canonical_timesheet_id',projection.canonical_timesheet_id,
          'projected_timesheet_id',projection.projected_timesheet_id,
          'stable_ordinal',projection.stable_ordinal)::text)
      FROM (
        WITH scope_page AS MATERIALIZED (
          SELECT scope_row.timesheet_id,scope_row.stable_ordinal
          FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=v_build_id
            AND scope_row.dependency_unit_key=v_unit_key
            AND (v_last_source_key IS NULL OR
              '00:'||LPAD(scope_row.stable_ordinal::text,20,'0')||':'||scope_row.timesheet_id::text>v_last_source_key)
          ORDER BY scope_row.stable_ordinal,scope_row.timesheet_id
          LIMIT v_fact_limit+1
        )
        SELECT scope_page.stable_ordinal,scope_page.timesheet_id AS family_timesheet_id,
          COALESCE(NULLIF(BTRIM(member.booking_id),''),scope_page.timesheet_id::text) AS scope_family_key,
          COALESCE(canonical.timesheet_id,fallback_member.timesheet_id) AS canonical_timesheet_id,
          COALESCE(canonical.timesheet_id,fallback_member.timesheet_id) AS projected_timesheet_id,
          CASE WHEN canonical.timesheet_id IS NOT NULL THEN 'CURRENT_FAMILY_MEMBER'
            WHEN fallback_member.timesheet_id IS NOT NULL THEN 'SEALED_FAMILY_FALLBACK_NO_CURRENT'
            ELSE 'UNRESOLVED' END AS projection_resolution_status,
          '00:'||LPAD(scope_page.stable_ordinal::text,20,'0')||':'||scope_page.timesheet_id::text AS source_key
        FROM scope_page
        JOIN public.timesheets member ON member.timesheet_id=scope_page.timesheet_id
        LEFT JOIN LATERAL (
          SELECT current_member.timesheet_id
          FROM public.timesheets current_member
          JOIN private.banking_pay_workbench_economic_build_scope current_scope
            ON current_scope.build_id=v_build_id
           AND current_scope.dependency_unit_key=v_unit_key
           AND current_scope.timesheet_id=current_member.timesheet_id
          -- Preserve the established rotation authority exactly: canonical
          -- identity is the highest-ranked is_current family member. Revocation
          -- and archival remain captured facts; they do not erase identity.
          WHERE current_member.is_current IS TRUE
            AND (CASE WHEN NULLIF(BTRIM(member.booking_id),'') IS NULL
                  THEN current_member.timesheet_id=member.timesheet_id
                  ELSE current_member.booking_id=member.booking_id END)
          ORDER BY current_member.version DESC NULLS LAST,
            current_member.updated_at DESC NULLS LAST,current_member.created_at DESC NULLS LAST,
            current_member.timesheet_id
          LIMIT 1
        ) canonical ON true
        LEFT JOIN LATERAL (
          -- Some bounded legacy families legitimately have no row still marked
          -- current. Keep one page-independent owner from the sealed unit rather
          -- than losing the physical family or projecting each page differently.
          SELECT fallback_row.timesheet_id
          FROM private.banking_pay_workbench_economic_build_scope fallback_scope
          JOIN public.timesheets fallback_row
            ON fallback_row.timesheet_id=fallback_scope.timesheet_id
          WHERE canonical.timesheet_id IS NULL
            AND fallback_scope.build_id=v_build_id
            AND fallback_scope.dependency_unit_key=v_unit_key
            AND (CASE WHEN NULLIF(BTRIM(member.booking_id),'') IS NULL
                  THEN fallback_row.timesheet_id=member.timesheet_id
                  ELSE fallback_row.booking_id=member.booking_id END)
          ORDER BY fallback_scope.stable_ordinal,fallback_row.timesheet_id
          LIMIT 1
        ) fallback_member ON true
        ORDER BY scope_page.stable_ordinal,scope_page.timesheet_id
      ) projection;
    ELSIF v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK') THEN
      v_occurrence_bundle:=private.pay_workbench_unit_economic_occurrence_bundle_v1(
        v_build_id,v_unit_key,v_fact_family,v_input_projection_id,
        v_last_source_key,v_fact_limit);
      IF jsonb_typeof(v_occurrence_bundle)<>'object'
         OR COALESCE((v_occurrence_bundle->>'bundle_version')::integer,0)<>1
         OR jsonb_typeof(v_occurrence_bundle->'rows')<>'array' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_EVIDENCE_INVALID'
          USING ERRCODE='23514';
      END IF;
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT occurrence.source_key,occurrence.natural_key,occurrence.timesheet_id,
        occurrence.subject_timesheet_ids,occurrence.source_relation,occurrence.source_id,
        occurrence.economic_key_type,occurrence.economic_key_value,
        occurrence.amount_ex_vat,occurrence.amount_inc_vat,
        occurrence.truth_ex_vat,occurrence.truth_inc_vat,
        occurrence.baseline_ex_vat,occurrence.baseline_inc_vat,
        NULL,
        CASE WHEN COALESCE(occurrence.source_payload_json->>'finance_case_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (occurrence.source_payload_json->>'finance_case_id')::uuid END,
        CASE WHEN COALESCE(occurrence.source_payload_json->>'finance_component_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (occurrence.source_payload_json->>'finance_component_id')::uuid END,
        CASE WHEN COALESCE(occurrence.source_payload_json->>'reservation_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (occurrence.source_payload_json->>'reservation_id')::uuid END,
        occurrence.source_payload_json,occurrence.financial_digest
      FROM jsonb_to_recordset(v_occurrence_bundle->'rows') occurrence(
        source_key text,natural_key text,timesheet_id uuid,subject_timesheet_ids uuid[],
        source_relation text,source_id uuid,economic_key_type text,economic_key_value text,
        amount_ex_vat numeric,amount_inc_vat numeric,truth_ex_vat numeric,truth_inc_vat numeric,
        baseline_ex_vat numeric,baseline_inc_vat numeric,source_payload_json jsonb,
        financial_digest text,resolution_failure text
      );
    ELSIF v_fact_family IN ('ENTITLEMENT_COMPONENT','PAYEE_BASELINE_INPUT','CANONICAL_INPUT') THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT source.source_key,md5(v_fact_family||':'||source.source_key),source.timesheet_id,
        ARRAY[source.timesheet_id],'economic_build_facts',source.source_id,
        source.key_type,source.key_value,
        CASE WHEN v_fact_family='CANONICAL_INPUT' THEN source.truth_ex_vat END,
        CASE WHEN v_fact_family='CANONICAL_INPUT' THEN source.truth_inc_vat END,
        source.truth_ex_vat,source.truth_inc_vat,source.baseline_ex_vat,source.baseline_inc_vat,
        NULL,NULL,NULL,NULL,
        jsonb_build_object('fact_role',v_fact_family,'source_fact_family',source.source_family,
          'source_natural_key',source.source_natural_key),
        md5(jsonb_build_object('timesheet_id',source.timesheet_id,'source_family',source.source_family,
          'source_natural_key',source.source_natural_key,'key_type',source.key_type,
          'key_value',source.key_value,'truth_ex_vat',source.truth_ex_vat,
          'truth_inc_vat',source.truth_inc_vat,'baseline_ex_vat',source.baseline_ex_vat,
          'baseline_inc_vat',source.baseline_inc_vat)::text)
      FROM (
        SELECT 'T:'||fact.natural_key AS source_key,fact.timesheet_id,fact.source_id,
          fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          COALESCE(fact.truth_ex_vat,0) AS truth_ex_vat,
          COALESCE(fact.truth_inc_vat,fact.truth_ex_vat,0) AS truth_inc_vat,
          0::numeric AS baseline_ex_vat,0::numeric AS baseline_inc_vat,
          fact.fact_family AS source_family,fact.natural_key AS source_natural_key
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id AND fact.fact_family='LIVE_ENTITLEMENT_INPUT'
          AND fact.dependency_unit_key=v_unit_key AND fact.source_relation<>'UNIT_PROJECTION'
          AND fact.economic_key_type IS NOT NULL
          AND COALESCE(fact.source_payload_json->>'evidence_only','false')<>'true'
        UNION ALL
        SELECT 'B:'||fact.fact_family||':'||fact.natural_key,fact.timesheet_id,fact.source_id,
          fact.economic_key_type,fact.economic_key_value,0::numeric,0::numeric,
          COALESCE(fact.amount_ex_vat,0),COALESCE(fact.amount_inc_vat,fact.amount_ex_vat,0),
          fact.fact_family,fact.natural_key
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
          AND fact.dependency_unit_key=v_unit_key AND fact.economic_key_type IS NOT NULL
          AND COALESCE(fact.source_payload_json->>'evidence_only','false')<>'true'
          AND (fact.fact_family<>'PAY_STATE_FALLBACK' OR NOT EXISTS(
            SELECT 1 FROM private.banking_pay_workbench_economic_build_facts active
            WHERE active.build_id=v_build_id AND active.fact_family='FROZEN_SETTLED_COMPONENT'
              AND active.dependency_unit_key=v_unit_key AND active.timesheet_id=fact.timesheet_id))
      ) source
      WHERE v_last_source_key IS NULL OR source.source_key>v_last_source_key
      ORDER BY source.source_key LIMIT v_fact_limit+1;
    ELSIF v_fact_family='RESERVATION_COMPONENT' THEN
      -- One server-owned projection resolves every financially open correction
      -- request for this candidate. Durable request-candidate membership is the
      -- primary frozen authority; work items, when present, must agree exactly.
      -- Only requests with no durable membership may use the already-valid
      -- legacy envelope/helper path. BLOCKED remains financially open.
      SELECT correction_request.id,
             'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED'
      INTO v_correction_scope_issue_request_id, v_correction_scope_issue_code
      FROM public.pay_payment_correction_requests AS correction_request
      WHERE correction_request.status IN (
          'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
        )
        AND correction_request.correction_kind IN (
          'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
        )
        AND NULLIF(BTRIM(COALESCE(
              correction_request.plan_json->>'candidate_scope_contract_version',''
            )), '') IS NOT NULL
        AND correction_request.plan_json->>'candidate_scope_contract_version' NOT IN ('1','2')
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS request_candidate
          WHERE request_candidate.pay_batch_id=correction_request.pay_batch_id
            AND request_candidate.candidate_id=p_candidate_id
        )
      ORDER BY correction_request.id::text
      LIMIT 1;

      IF v_correction_scope_issue_request_id IS NOT NULL THEN
        RAISE EXCEPTION '%', v_correction_scope_issue_code
          USING ERRCODE='P0001', DETAIL=jsonb_build_object(
            'code',v_correction_scope_issue_code,
            'correction_request_id',v_correction_scope_issue_request_id,
            'candidate_id',p_candidate_id
          )::text;
      END IF;

      v_correction_scope_issue_request_id:=NULL::uuid;
      v_correction_scope_issue_code:=NULL::text;

      SELECT correction_request.id,
             'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH'
      INTO v_correction_scope_issue_request_id, v_correction_scope_issue_code
      FROM public.pay_payment_correction_requests AS correction_request
      JOIN public.pay_payment_correction_request_candidates AS request_member
        ON request_member.correction_request_id=correction_request.id
      JOIN public.pay_batch_candidates AS request_candidate
        ON request_candidate.id=request_member.pay_batch_candidate_id
       AND request_candidate.pay_batch_id=correction_request.pay_batch_id
       AND request_candidate.candidate_id=p_candidate_id
      WHERE correction_request.status IN (
          'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
        )
        AND correction_request.correction_kind IN (
          'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
        )
        AND (
          request_member.pay_batch_item_ids IS NULL
          OR cardinality(request_member.pay_batch_item_ids)<>request_member.active_item_count
          OR EXISTS (
            SELECT 1
            FROM unnest(request_member.pay_batch_item_ids) AS frozen_item(pay_batch_item_id)
            LEFT JOIN public.pay_batch_items AS item_row
              ON item_row.id=frozen_item.pay_batch_item_id
             AND item_row.pay_batch_candidate_id=request_member.pay_batch_candidate_id
            WHERE item_row.id IS NULL
          )
          OR (
            EXISTS (
              SELECT 1
              FROM public.pay_payment_correction_work_items AS any_work
              WHERE any_work.correction_request_id=correction_request.id
            )
            AND NOT EXISTS (
              SELECT 1
              FROM public.pay_payment_correction_work_items AS matching_work
              WHERE matching_work.correction_request_id=correction_request.id
                AND matching_work.pay_batch_candidate_id=request_member.pay_batch_candidate_id
            )
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_work_items AS work_item
            WHERE work_item.correction_request_id=correction_request.id
              AND work_item.pay_batch_candidate_id=request_member.pay_batch_candidate_id
              AND (
                work_item.pay_batch_id IS DISTINCT FROM correction_request.pay_batch_id
                OR work_item.candidate_id IS DISTINCT FROM p_candidate_id
                OR work_item.selection_hash IS DISTINCT FROM request_member.candidate_scope_hash
                OR work_item.selection_json->>'expected_item_count'
                     IS DISTINCT FROM request_member.active_item_count::text
                OR work_item.selection_json->'expected_pay_batch_item_ids'
                     IS DISTINCT FROM to_jsonb(request_member.pay_batch_item_ids)
              )
          )
        )
      ORDER BY correction_request.id::text
      LIMIT 1;

      IF v_correction_scope_issue_request_id IS NOT NULL THEN
        RAISE EXCEPTION '%', v_correction_scope_issue_code
          USING ERRCODE='P0001', DETAIL=jsonb_build_object(
            'code',v_correction_scope_issue_code,
            'correction_request_id',v_correction_scope_issue_request_id,
            'candidate_id',p_candidate_id
          )::text;
      END IF;

      v_correction_scope_issue_request_id:=NULL::uuid;
      v_correction_scope_issue_code:=NULL::text;

      -- A no-membership request may use only a helper-compatible envelope or
      -- the helper's existing narrow whole-Draft compatibility contract.
      SELECT fallback_request.id,
             'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISSING'
      INTO v_correction_scope_issue_request_id, v_correction_scope_issue_code
      FROM (
        SELECT correction_request.*,
          CASE
            WHEN jsonb_typeof(correction_request.plan_json->'selected_pay_batch_item_ids')='array'
              THEN COALESCE(correction_request.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',correction_request.plan_json->'selected_pay_batch_item_ids',
                  'expected_pay_batch_item_ids',correction_request.plan_json->'selected_pay_batch_item_ids')
            WHEN jsonb_typeof(correction_request.plan_json#>'{selection,selected_pay_batch_item_ids}')='array'
              THEN COALESCE(correction_request.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',correction_request.plan_json#>'{selection,selected_pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',correction_request.plan_json#>'{selection,selected_pay_batch_item_ids}')
            WHEN jsonb_typeof(correction_request.plan_json#>'{selection,pay_batch_item_ids}')='array'
              THEN COALESCE(correction_request.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',correction_request.plan_json#>'{selection,pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',correction_request.plan_json#>'{selection,pay_batch_item_ids}')
            ELSE COALESCE(correction_request.selection_json,'{}'::jsonb)
          END AS resolved_selection_json
        FROM public.pay_payment_correction_requests AS correction_request
        WHERE correction_request.status IN (
            'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
          )
          AND correction_request.correction_kind IN (
            'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
          )
          AND NOT EXISTS (
            SELECT 1 FROM public.pay_payment_correction_request_candidates AS any_member
            WHERE any_member.correction_request_id=correction_request.id
          )
          AND EXISTS (
            SELECT 1 FROM public.pay_batch_candidates AS request_candidate
            WHERE request_candidate.pay_batch_id=correction_request.pay_batch_id
              AND request_candidate.candidate_id=p_candidate_id
          )
      ) AS fallback_request
      WHERE NOT (
        upper(NULLIF(BTRIM(COALESCE(fallback_request.resolved_selection_json->>'scope_type','')),''))
          IN ('BATCH','CANDIDATES','TRANSFER','UMBRELLA_PAYMENT_GROUP')
        OR (
          upper(BTRIM(COALESCE(fallback_request.resolved_selection_json->>'requested_action','')))='DRAFT_CANCEL'
          AND upper(BTRIM(COALESCE(fallback_request.resolved_selection_json->>'mode','')))='ALL_MATCHING'
          AND COALESCE(fallback_request.resolved_selection_json->>'source_context','')='pay_batch_cancel'
          AND COALESCE(fallback_request.resolved_selection_json->'filter_json','{}'::jsonb)='{}'::jsonb
          AND COALESCE(fallback_request.resolved_selection_json->'exclusions','[]'::jsonb)='[]'::jsonb
        )
      )
      ORDER BY fallback_request.id::text
      LIMIT 1;

      IF v_correction_scope_issue_request_id IS NOT NULL THEN
        RAISE EXCEPTION '%', v_correction_scope_issue_code
          USING ERRCODE='P0001', DETAIL=jsonb_build_object(
            'code',v_correction_scope_issue_code,
            'correction_request_id',v_correction_scope_issue_request_id,
            'candidate_id',p_candidate_id
          )::text;
      END IF;

      DROP TABLE IF EXISTS pg_temp._bpay_wb_open_correction_scope_v1;
      CREATE TEMP TABLE _bpay_wb_open_correction_scope_v1 ON COMMIT DROP AS
      WITH open_requests AS MATERIALIZED (
        SELECT correction_request.*
        FROM public.pay_payment_correction_requests AS correction_request
        WHERE correction_request.status IN (
            'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
          )
          AND correction_request.correction_kind IN (
            'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
          )
      ), membership_scope AS MATERIALIZED (
        SELECT request_row.id AS correction_request_id,
               frozen_item.pay_batch_item_id
        FROM open_requests AS request_row
        JOIN public.pay_payment_correction_request_candidates AS request_member
          ON request_member.correction_request_id=request_row.id
        JOIN public.pay_batch_candidates AS request_candidate
          ON request_candidate.id=request_member.pay_batch_candidate_id
         AND request_candidate.pay_batch_id=request_row.pay_batch_id
         AND request_candidate.candidate_id=p_candidate_id
        CROSS JOIN LATERAL unnest(request_member.pay_batch_item_ids)
          AS frozen_item(pay_batch_item_id)
      ), fallback_requests AS MATERIALIZED (
        SELECT request_row.*,
          CASE
            WHEN jsonb_typeof(request_row.plan_json->'selected_pay_batch_item_ids')='array'
              THEN COALESCE(request_row.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',request_row.plan_json->'selected_pay_batch_item_ids',
                  'expected_pay_batch_item_ids',request_row.plan_json->'selected_pay_batch_item_ids')
            WHEN jsonb_typeof(request_row.plan_json#>'{selection,selected_pay_batch_item_ids}')='array'
              THEN COALESCE(request_row.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',request_row.plan_json#>'{selection,selected_pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',request_row.plan_json#>'{selection,selected_pay_batch_item_ids}')
            WHEN jsonb_typeof(request_row.plan_json#>'{selection,pay_batch_item_ids}')='array'
              THEN COALESCE(request_row.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',request_row.plan_json#>'{selection,pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',request_row.plan_json#>'{selection,pay_batch_item_ids}')
            ELSE COALESCE(request_row.selection_json,'{}'::jsonb)
          END AS resolved_selection_json
        FROM open_requests AS request_row
        WHERE NOT EXISTS (
          SELECT 1 FROM public.pay_payment_correction_request_candidates AS any_member
          WHERE any_member.correction_request_id=request_row.id
        )
      ), fallback_scope AS MATERIALIZED (
        SELECT fallback_request.id AS correction_request_id,
               selected_item.pay_batch_item_id
        FROM fallback_requests AS fallback_request
        JOIN LATERAL public._pay_payment_correction_selected_items(
          fallback_request.pay_batch_id,
          fallback_request.resolved_selection_json,
          false
        ) AS selected_item ON selected_item.pay_batch_id=fallback_request.pay_batch_id
        WHERE selected_item.candidate_id=p_candidate_id
      )
      SELECT DISTINCT resolved_scope.correction_request_id,
             resolved_scope.pay_batch_item_id
      FROM (
        SELECT * FROM membership_scope
        UNION ALL
        SELECT * FROM fallback_scope
      ) AS resolved_scope;

      CREATE INDEX ON pg_temp._bpay_wb_open_correction_scope_v1(pay_batch_item_id);
      CREATE INDEX ON pg_temp._bpay_wb_open_correction_scope_v1(correction_request_id,pay_batch_item_id);

      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT reservation.id::text,md5('RESERVATION:'||reservation.id::text),
        authority.resolved_timesheet_id,authority.owner_ids,'pay_advance_reservations',reservation.id,
        authority.resolved_component_key_type,authority.resolved_component_key_value,
        NULL,NULL,NULL,NULL,NULL,NULL,COALESCE(reservation.reserved_source_amount,reservation.reserved_amount),
        authority.resolved_finance_case_id,authority.resolved_finance_component_id,
        reservation.id,to_jsonb(reservation)||jsonb_build_object('resolution_failure',CASE
          WHEN authority.resolution_failure IS NOT NULL THEN authority.resolution_failure
          WHEN cardinality(authority.component_key_pairs)<>1 THEN 'RESERVATION_ECONOMIC_KEY_CONFLICT'
          WHEN authority.resolved_component_key_type NOT IN
            ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
            OR NULLIF(BTRIM(authority.resolved_component_key_value),'') IS NULL
            THEN 'RESERVATION_ECONOMIC_KEY_INVALID'
          WHEN authority.resolved_component_key_type='TS_DAY' AND NOT (
            authority.resolved_component_key_value ~ '^\d{4}-\d{2}-\d{2}$'
            AND pg_input_is_valid(authority.resolved_component_key_value,'date')
            AND CASE WHEN pg_input_is_valid(authority.resolved_component_key_value,'date')
              THEN (authority.resolved_component_key_value::date)::text=
                authority.resolved_component_key_value ELSE false END)
            THEN 'RESERVATION_TS_DAY_INVALID'
          END,'authority_evidence',authority.evidence_json),
        md5(to_jsonb(reservation)::text)
      FROM public.pay_advance_reservations reservation
      LEFT JOIN public.pay_batch_items item ON item.id=reservation.pay_batch_item_id
      LEFT JOIN public.pay_finance_case_components component ON component.id=reservation.finance_component_id
      LEFT JOIN public.pay_advances finance_case
        ON finance_case.id=COALESCE(reservation.finance_case_id,component.finance_case_id)
      LEFT JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=reservation.pay_batch_candidate_id
      LEFT JOIN public.pay_batch_candidates item_batch_candidate ON item_batch_candidate.id=item.pay_batch_candidate_id
      CROSS JOIN LATERAL (
        SELECT resolved.owner_ids,resolved.candidate_ids,resolved.finance_case_ids,
          resolved.resolved_timesheet_id,resolved.resolved_finance_case_id,
          resolved.resolved_finance_component_id,resolved.resolved_component_key_type,
          resolved.resolved_component_key_value,resolved.resolution_failure,
          resolved.evidence_json,resolved.component_key_pairs
        FROM private.pay_workbench_financial_source_authority_v3(
          p_candidate_id,
          ARRAY(SELECT DISTINCT owner_id FROM (VALUES
            (item.timesheet_id),(component.linked_timesheet_id),(finance_case.linked_timesheet_id)
          ) owner(owner_id) WHERE owner_id IS NOT NULL ORDER BY owner_id),
          ARRAY(SELECT DISTINCT candidate_id FROM (VALUES
            (batch_candidate.candidate_id),(item_batch_candidate.candidate_id),
            (component.candidate_id),(finance_case.candidate_id)
          ) owner_candidate(candidate_id) WHERE candidate_id IS NOT NULL ORDER BY candidate_id),
          ARRAY(SELECT DISTINCT finance_case_id FROM (VALUES
            (reservation.finance_case_id),(item.finance_case_id),(component.finance_case_id)
          ) owner_case(finance_case_id) WHERE finance_case_id IS NOT NULL ORDER BY finance_case_id),
          ARRAY(SELECT DISTINCT finance_component_id FROM (VALUES
            (reservation.finance_component_id),(item.finance_component_id),(component.id)
          ) owner_component(finance_component_id)
            WHERE finance_component_id IS NOT NULL ORDER BY finance_component_id),
          jsonb_build_array(
            jsonb_build_object('source','RESERVATION_FROZEN_COLUMNS',
              'key_type',reservation.frozen_component_key_type,
              'key_value',reservation.frozen_component_key_value),
            jsonb_build_object('source','PAY_BATCH_ITEM_FROZEN_COLUMNS',
              'key_type',item.frozen_component_key_type,
              'key_value',item.frozen_component_key_value),
            jsonb_build_object('source','FINANCE_COMPONENT',
              'key_type',component.component_key_type,
              'key_value',component.component_key_value)),
          jsonb_build_array(
            jsonb_build_object('source','RESERVATION',
              'document',COALESCE(reservation.frozen_source_basis_json,'{}'::jsonb)),
            jsonb_build_object('source','PAY_BATCH_ITEM',
              'document',COALESCE(item.frozen_source_basis_json,'{}'::jsonb))),
          jsonb_build_array(
            jsonb_build_object('source','RESERVATION',
              'document',COALESCE(reservation.frozen_component_snapshot_json,'{}'::jsonb)),
            jsonb_build_object('source','PAY_BATCH_ITEM',
              'document',COALESCE(item.frozen_component_snapshot_json,'{}'::jsonb))),
          'RESERVATION'
        ) resolved
      ) authority
      WHERE (p_candidate_id=ANY(authority.candidate_ids)
          OR authority.owner_ids && ARRAY(
            SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope
            WHERE build_id=v_build_id))
        AND upper(btrim(COALESCE(reservation.status,''))) IN ('RESERVED','COMMITTED')
        AND reservation.released_at_utc IS NULL
        AND (item.id IS NULL OR COALESCE(item.is_voided,false) IS NOT TRUE)
        AND (authority.resolution_failure IS NOT NULL OR authority.owner_ids && ARRAY(
          SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope WHERE build_id=v_build_id))
        AND (v_last_source_key IS NULL OR reservation.id::text COLLATE "C"
          >v_last_source_key COLLATE "C")
      ORDER BY reservation.id::text COLLATE "C" LIMIT v_fact_limit+1;

      -- The normal pre-Draft preview treats active, non-settled pay-batch items as
      -- reservations even where no pay_advance_reservations row exists.  Seal
      -- that same authority here so reconciliation never has to rediscover it
      -- from later live state.  Existing directly-linked advance reservations
      -- remain the preferred owner and exclude the corresponding item below.
      WITH active_item_candidates AS MATERIALIZED (
        SELECT DISTINCT
          item.id AS pay_batch_item_id,
          batch_candidate.pay_batch_id,
          item.pay_batch_candidate_id,
          item.timesheet_id AS source_timesheet_id,
          item.item_type,
          item.segment_key,
          item.source_ref,
          UPPER(BTRIM(item.pay_channel)) AS pay_channel,
          item.reservation_id,
          item.finance_case_id,
          item.finance_component_id,
          item.frozen_component_key_type,
          item.frozen_component_key_value,
          COALESCE(item.frozen_source_basis_json,'{}'::jsonb) AS frozen_source_basis_json,
          COALESCE(item.frozen_component_snapshot_json,'{}'::jsonb)
            AS frozen_component_snapshot_json,
          COALESCE(item.frozen_resolution_payload_json,'{}'::jsonb)
            AS frozen_resolution_payload_json,
          COALESCE(item.frozen_resolution_result_json,'{}'::jsonb)
            AS frozen_resolution_result_json,
          ROUND(public._pay_batch_item_source_reservation_amount_ex_vat(item.id),2)
            AS reserved_source_amount,
          batch_row.status AS batch_status,
          batch_candidate.settlement_status AS candidate_settlement_status,
          batch_candidate.settled_at_utc AS candidate_settled_at_utc,
          transfer.status AS transfer_status,
          transfer.completed_at_utc AS transfer_completed_at_utc
        FROM public.pay_batch_items item
        JOIN public.pay_batch_candidates batch_candidate
          ON batch_candidate.id=item.pay_batch_candidate_id
        JOIN public.pay_batches batch_row ON batch_row.id=batch_candidate.pay_batch_id
        LEFT JOIN public.pay_bank_transfers transfer ON transfer.id=item.pay_bank_transfer_id
        WHERE batch_candidate.candidate_id=p_candidate_id
          AND item.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(item.pay_channel,''))) IN ('PAYE','UMBRELLA')
          AND item.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
          AND public._pay_batch_item_source_reservation_amount_ex_vat(item.id) IS NOT NULL
          AND COALESCE(item.is_voided,false) IS NOT TRUE
          AND EXISTS (
            SELECT 1
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=v_build_id
              AND scope_row.candidate_id=p_candidate_id
              AND (scope_row.timesheet_id=item.timesheet_id
                OR scope_row.root_timesheet_id=item.timesheet_id)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_items applied_correction
            WHERE applied_correction.pay_batch_item_id=item.id
              AND applied_correction.status='APPLIED'
              AND applied_correction.correction_item_kind IN (
                'PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          AND NOT (
            UPPER(BTRIM(COALESCE(batch_candidate.settlement_status,'')))='SETTLED'
            OR batch_candidate.settled_at_utc IS NOT NULL
            OR UPPER(BTRIM(COALESCE(transfer.status,'')))='COMPLETED'
            OR transfer.completed_at_utc IS NOT NULL
          )
          AND (
            public._pay_batch_status_is_active_reservation(batch_row.status)
            OR EXISTS (
              SELECT 1
              FROM pg_temp._bpay_wb_open_correction_scope_v1 AS correction_scope
              WHERE correction_scope.pay_batch_item_id=item.id
            )
            OR EXISTS (
              SELECT 1
              FROM public.pay_bank_transfer_events terminal_event
              WHERE terminal_event.pay_batch_id=batch_candidate.pay_batch_id
                AND terminal_event.pay_bank_transfer_id=item.pay_bank_transfer_id
                AND terminal_event.mapping_status='MATCHED'
                AND terminal_event.normalised_state IN ('FAILED','DECLINED','REJECTED','CANCELLED')
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.pay_payment_correction_items applied_failure_correction
                  WHERE applied_failure_correction.pay_batch_item_id=item.id
                    AND applied_failure_correction.status='APPLIED'
                    AND applied_failure_correction.correction_item_kind IN (
                      'NO_MONEY_UNWIND','PRE_BANK_CANCEL','SETTLED_REVERSAL')
                )
            )
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_advance_reservations advance
            WHERE (advance.pay_batch_item_id=item.id OR advance.id=item.reservation_id)
              AND UPPER(BTRIM(COALESCE(advance.status,''))) IN ('RESERVED','COMMITTED')
              AND advance.released_at_utc IS NULL
          )
      ), active_item_id_array AS MATERIALIZED (
        SELECT CASE WHEN COUNT(*)=0
          THEN ARRAY['00000000-0000-0000-0000-000000000000'::uuid]
          ELSE ARRAY_AGG(candidate.pay_batch_item_id ORDER BY candidate.pay_batch_item_id) END
          AS pay_batch_item_ids
        FROM active_item_candidates candidate
      ), active_item_components AS MATERIALIZED (
        SELECT component.pay_batch_item_id,
          UPPER(NULLIF(BTRIM(component.key_type),'')) AS key_type,
          NULLIF(BTRIM(component.key_value),'') AS key_value,
          NULLIF(BTRIM(component.key_resolution_source),'') AS key_resolution_source,
          NULLIF(BTRIM(component.key_resolution_failure_reason),'')
            AS key_resolution_failure_reason
        FROM active_item_id_array item_ids
        JOIN LATERAL public._pay_batch_item_economic_components(
          NULL::uuid,item_ids.pay_batch_item_ids) component ON true
      ), active_item_component_summary AS MATERIALIZED (
        SELECT candidate.pay_batch_item_id,
          COUNT(DISTINCT (component.key_type,component.key_value)) FILTER(
            WHERE component.key_type IS NOT NULL AND component.key_value IS NOT NULL)::integer
            AS economic_key_count,
          MIN(component.key_type) FILTER(
            WHERE component.key_type IS NOT NULL AND component.key_value IS NOT NULL) AS key_type,
          MIN(component.key_value) FILTER(
            WHERE component.key_type IS NOT NULL AND component.key_value IS NOT NULL) AS key_value,
          MIN(component.key_resolution_source) AS key_resolution_source,
          MIN(component.key_resolution_failure_reason) AS key_resolution_failure_reason
        FROM active_item_candidates candidate
        LEFT JOIN active_item_components component
          ON component.pay_batch_item_id=candidate.pay_batch_item_id
        GROUP BY candidate.pay_batch_item_id
      ), active_item_rotation AS MATERIALIZED (
        SELECT DISTINCT ON (rotation.requested_timesheet_id)
          rotation.requested_timesheet_id,
          COALESCE(rotation.canonical_timesheet_id,rotation.requested_timesheet_id)
            AS canonical_timesheet_id
        FROM public._pay_timesheet_rotation_scope(ARRAY(
          SELECT DISTINCT candidate.source_timesheet_id
          FROM active_item_candidates candidate
          ORDER BY candidate.source_timesheet_id)) rotation
        ORDER BY rotation.requested_timesheet_id,rotation.family_is_current DESC NULLS LAST,
          rotation.family_version DESC NULLS LAST,rotation.family_timesheet_id
      ), active_item_enriched AS MATERIALIZED (
        SELECT candidate.*,
          CASE WHEN candidate.reservation_id IS NULL THEN 1
            ELSE COUNT(*) OVER(PARTITION BY candidate.reservation_id) END::integer
            AS logical_owner_count,
          COALESCE(rotation.canonical_timesheet_id,candidate.source_timesheet_id)
            AS sealed_timesheet_id,
          component.economic_key_count,component.key_type,component.key_value,
          component.key_resolution_source,component.key_resolution_failure_reason,
          COALESCE((SELECT jsonb_agg(to_jsonb(breakdown) ORDER BY breakdown.id)
            FROM public.pay_batch_item_breakdowns breakdown
            WHERE breakdown.pay_batch_item_id=candidate.pay_batch_item_id),'[]'::jsonb)
            AS breakdowns,
          COALESCE((SELECT jsonb_agg(correction_scope.correction_request_id::text
                                    ORDER BY correction_scope.correction_request_id::text)
            FROM pg_temp._bpay_wb_open_correction_scope_v1 AS correction_scope
            WHERE correction_scope.pay_batch_item_id=candidate.pay_batch_item_id),
            '[]'::jsonb) AS open_correction_request_ids
        FROM active_item_candidates candidate
        LEFT JOIN active_item_component_summary component
          ON component.pay_batch_item_id=candidate.pay_batch_item_id
        LEFT JOIN active_item_rotation rotation
          ON rotation.requested_timesheet_id=candidate.source_timesheet_id
      ), active_item_payloads AS MATERIALIZED (
        SELECT enriched.*,
          CASE
            WHEN enriched.logical_owner_count<>1
              THEN 'RESERVATION_DUPLICATE_LOGICAL_OWNER'
            WHEN COALESCE(enriched.economic_key_count,0)=0
              THEN 'RESERVATION_ECONOMIC_KEY_MISSING'
            WHEN enriched.economic_key_count<>1
              THEN 'RESERVATION_ECONOMIC_KEY_CONFLICT'
            WHEN enriched.key_resolution_failure_reason IS NOT NULL
              THEN enriched.key_resolution_failure_reason
            WHEN enriched.key_type NOT IN (
              'TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE',
              'EXPENSE_CODE','MANUAL_CARRY_FORWARD')
              OR enriched.key_value IS NULL
              THEN 'RESERVATION_ECONOMIC_KEY_INVALID'
            WHEN enriched.key_type='TS_DAY' AND NOT (
              enriched.key_value ~ '^\d{4}-\d{2}-\d{2}$'
              AND pg_input_is_valid(enriched.key_value,'date')
              AND CASE WHEN pg_input_is_valid(enriched.key_value,'date')
                THEN enriched.key_value::date::text=enriched.key_value ELSE false END)
              THEN 'RESERVATION_TS_DAY_INVALID'
          END AS resolution_failure
        FROM active_item_enriched enriched
      ), active_item_documents AS MATERIALIZED (
        SELECT item.*,
          jsonb_build_object(
            'reservation_authority_version',2,
            'authority_source','ACTIVE_PAY_BATCH_ITEM',
            'pay_batch_item',jsonb_build_object(
              'id',item.pay_batch_item_id::text,
              'pay_batch_id',item.pay_batch_id::text,
              'pay_batch_candidate_id',item.pay_batch_candidate_id::text,
              'timesheet_id',item.source_timesheet_id::text,
              'projected_timesheet_id',item.sealed_timesheet_id::text,
              'item_type',item.item_type,
              'segment_key',item.segment_key,
              'source_ref',item.source_ref,
              'pay_channel',item.pay_channel,
              'reservation_id',item.reservation_id::text,
              'finance_case_id',item.finance_case_id::text,
              'finance_component_id',item.finance_component_id::text,
              'frozen_component_key_type',item.frozen_component_key_type,
              'frozen_component_key_value',item.frozen_component_key_value,
              'frozen_source_basis_json',item.frozen_source_basis_json,
              'frozen_component_snapshot_json',item.frozen_component_snapshot_json,
              'frozen_resolution_payload_json',item.frozen_resolution_payload_json,
              'frozen_resolution_result_json',item.frozen_resolution_result_json),
            'economic_key',jsonb_build_object(
              'key_type',item.key_type,'key_value',item.key_value,
              'key_resolution_source',item.key_resolution_source,
              'key_resolution_failure_reason',item.key_resolution_failure_reason),
            'active_state',jsonb_build_object(
              'batch_status',item.batch_status,
              'candidate_settlement_status',item.candidate_settlement_status,
              'candidate_settled_at_utc',item.candidate_settled_at_utc,
              'transfer_status',item.transfer_status,
              'transfer_completed_at_utc',item.transfer_completed_at_utc,
              'open_correction_request_ids',item.open_correction_request_ids),
            'breakdowns',item.breakdowns,
            'source_reservation_amount_ex_vat',item.reserved_source_amount,
            'resolution_failure',item.resolution_failure) AS source_payload_json
        FROM active_item_payloads item
      )
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT '~ITEM:'||item.pay_batch_item_id::text,
        md5('ACTIVE_ITEM_RESERVATION:'||item.pay_batch_item_id::text),
        item.sealed_timesheet_id,
        ARRAY(SELECT DISTINCT owner_id FROM unnest(ARRAY[
          item.source_timesheet_id,item.sealed_timesheet_id]) owner(owner_id)
          WHERE owner_id IS NOT NULL ORDER BY owner_id),
        'pay_batch_items_active_reservation',item.pay_batch_item_id,
        item.key_type,item.key_value,
        NULL,NULL,NULL,NULL,NULL,NULL,item.reserved_source_amount,
        item.finance_case_id,item.finance_component_id,
        COALESCE(item.reservation_id,item.pay_batch_item_id),
        item.source_payload_json,md5(item.source_payload_json::text)
      FROM active_item_documents item
      WHERE v_last_source_key IS NULL
        OR ('~ITEM:'||item.pay_batch_item_id::text) COLLATE "C"
          >v_last_source_key COLLATE "C"
      ORDER BY ('~ITEM:'||item.pay_batch_item_id::text) COLLATE "C"
      LIMIT v_fact_limit+1
      ON CONFLICT(source_key) DO NOTHING;
    ELSIF v_fact_family='FINANCE_CASE_IDENTITY' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT finance_case.id::text,md5('CASE:'||finance_case.id::text),finance_case.linked_timesheet_id,
        CASE WHEN finance_case.linked_timesheet_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[finance_case.linked_timesheet_id] END,
        'pay_advances',finance_case.id,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,finance_case.id,NULL,NULL,
        to_jsonb(finance_case),md5(to_jsonb(finance_case)::text)
      FROM public.pay_advances finance_case WHERE finance_case.candidate_id=p_candidate_id
        AND ((finance_case.cleared_at_utc IS NULL AND finance_case.written_off_at_utc IS NULL)
          OR finance_case.linked_timesheet_id IN (
            SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope
            WHERE build_id=v_build_id
          ))
        AND (v_last_source_key IS NULL OR finance_case.id::text>v_last_source_key)
      ORDER BY finance_case.id LIMIT v_fact_limit+1;
    ELSIF v_fact_family='FINANCE_COMPONENT_IDENTITY' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT component.id::text,md5('COMPONENT:'||component.id::text),component.linked_timesheet_id,
        CASE WHEN component.linked_timesheet_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[component.linked_timesheet_id] END,
        'pay_finance_case_components',component.id,
        CASE WHEN component.component_key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
          THEN component.component_key_type ELSE NULL END,
        CASE WHEN component.component_key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
          THEN component.component_key_value ELSE NULL END,
        component.source_amount,NULL,NULL,NULL,NULL,NULL,component.remaining_source_amount,
        component.finance_case_id,component.id,NULL,to_jsonb(component),md5(to_jsonb(component)::text)
      FROM public.pay_finance_case_components component WHERE component.candidate_id=p_candidate_id
        AND component.closed_at_utc IS NULL AND (v_last_source_key IS NULL OR component.id::text>v_last_source_key)
      ORDER BY component.id LIMIT v_fact_limit+1;
    ELSIF v_fact_family='PROTECTION_EVIDENCE' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT 'EVENT:'||event.id::text,md5('EVENT:'||event.id::text),component.linked_timesheet_id,
        CASE WHEN component.linked_timesheet_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[component.linked_timesheet_id] END,
        'pay_finance_case_events',event.id,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
        event.finance_case_id,event.finance_component_id,event.reservation_id,to_jsonb(event),md5(to_jsonb(event)::text)
      FROM public.pay_finance_case_events event
      JOIN private.banking_pay_workbench_economic_build_facts case_fact
        ON case_fact.build_id=v_build_id AND case_fact.fact_family='FINANCE_CASE_IDENTITY'
       AND case_fact.finance_case_id=event.finance_case_id
      LEFT JOIN public.pay_finance_case_components component ON component.id=event.finance_component_id
      WHERE case_fact.candidate_id=p_candidate_id
        AND (
          upper(btrim(COALESCE(event.event_type,''))) LIKE '%WRITE%OFF%'
          OR upper(btrim(COALESCE(event.event_type,''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
            'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
          OR upper(btrim(COALESCE(event.reason,''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
          OR (
            upper(btrim(COALESCE(event.event_type,'')))='CASE_CLEARED'
            AND lower(btrim(COALESCE(event.reason,'')))='rail_settlement'
          )
          OR (
            upper(btrim(COALESCE(event.event_type,'')))='CLEARED'
            AND upper(btrim(COALESCE(event.reason,'')))='PREVIEW_FINANCE_SYNC'
          )
        )
        AND event.id=(
          SELECT event_latest.id
          FROM public.pay_finance_case_events event_latest
          WHERE event_latest.finance_case_id=event.finance_case_id
            AND (
              upper(btrim(COALESCE(event_latest.event_type,''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(COALESCE(event_latest.event_type,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR upper(btrim(COALESCE(event_latest.reason,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR (upper(btrim(COALESCE(event_latest.event_type,'')))='CASE_CLEARED'
                AND lower(btrim(COALESCE(event_latest.reason,'')))='rail_settlement')
              OR (upper(btrim(COALESCE(event_latest.event_type,'')))='CLEARED'
                AND upper(btrim(COALESCE(event_latest.reason,'')))='PREVIEW_FINANCE_SYNC')
            )
            AND (CASE WHEN (
              upper(btrim(COALESCE(event_latest.event_type,''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(COALESCE(event_latest.event_type,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR upper(btrim(COALESCE(event_latest.reason,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE'))
              THEN 'MANUAL' ELSE 'AUTOMATIC_CLEAR' END)
              =(CASE WHEN (
                upper(btrim(COALESCE(event.event_type,''))) LIKE '%WRITE%OFF%'
                OR upper(btrim(COALESCE(event.event_type,''))) IN (
                  'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
                  'COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
                OR upper(btrim(COALESCE(event.reason,''))) IN (
                  'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE'))
                THEN 'MANUAL' ELSE 'AUTOMATIC_CLEAR' END)
          ORDER BY event_latest.event_at_utc DESC NULLS LAST,event_latest.id DESC
          LIMIT 1
        )
        AND (v_last_source_key IS NULL OR 'EVENT:'||event.id::text>v_last_source_key)
      ORDER BY event.id LIMIT v_fact_limit+1;
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT 'BATCH_ITEM:'||item.id::text,md5('BATCH_ITEM_PROTECTION:'||item.id::text),
        item.timesheet_id,CASE WHEN item.timesheet_id IS NULL THEN ARRAY[]::uuid[]
          ELSE ARRAY[item.timesheet_id] END,'pay_batch_items',item.id,
        NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,item.finance_case_id,
        item.finance_component_id,item.reservation_id,
        to_jsonb(item)||jsonb_build_object('protection_kind','ACTIVE_CORRECTION_CHAIN_BATCH_ITEM'),
        md5(to_jsonb(item)::text)
      FROM public.pay_batch_items item
      JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=item.pay_batch_candidate_id
      JOIN public.pay_batches batch_row ON batch_row.id=batch_candidate.pay_batch_id
      WHERE batch_candidate.candidate_id=p_candidate_id
        AND COALESCE(item.is_voided,false) IS NOT TRUE
        AND batch_row.cancelled_at_utc IS NULL
        AND upper(btrim(COALESCE(batch_row.status,''))) IN (
          'DRAFT','DRAFT_CREATED','READY','WAITING_BANK_CONFIRM','PARTIAL','FAILED',
          'BLOCKED_FUNDS','SCHEDULED','EXECUTING','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT')
        AND COALESCE(item.frozen_component_snapshot_json->>'correction_root_id',
          item.frozen_resolution_payload_json->>'correction_root_id','') IN (
            SELECT scope_row.root_timesheet_id::text
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=v_build_id AND scope_row.root_timesheet_id IS NOT NULL)
        AND (v_last_source_key IS NULL OR 'BATCH_ITEM:'||item.id::text>v_last_source_key)
      ORDER BY item.id LIMIT v_fact_limit+1
      ON CONFLICT(source_key) DO NOTHING;
    ELSIF v_fact_family='ALLOCATION_INPUT' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT fact.fact_family||':'||fact.natural_key,md5('ALLOCATION:'||fact.fact_family||':'||fact.natural_key),
        fact.timesheet_id,fact.subject_timesheet_ids,'economic_build_facts',fact.source_id,
        fact.economic_key_type,fact.economic_key_value,
        COALESCE(fact.amount_ex_vat,fact.truth_ex_vat),COALESCE(fact.amount_inc_vat,fact.truth_inc_vat),
        fact.truth_ex_vat,fact.truth_inc_vat,fact.baseline_ex_vat,fact.baseline_inc_vat,
        fact.reserved_source_amount,fact.finance_case_id,fact.finance_component_id,fact.reservation_id,
        jsonb_build_object('source_fact_family',fact.fact_family,'source_natural_key',fact.natural_key),fact.financial_digest
      FROM private.banking_pay_workbench_economic_build_facts fact
      WHERE fact.build_id=v_build_id AND fact.fact_family IN ('ENTITLEMENT_COMPONENT','RESERVATION_COMPONENT')
        AND fact.economic_key_type IS NOT NULL
        AND (v_last_source_key IS NULL OR fact.fact_family||':'||fact.natural_key>v_last_source_key)
      ORDER BY fact.fact_family,fact.natural_key LIMIT v_fact_limit+1;
    ELSE
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;

    SELECT NULLIF(BTRIM(page.source_payload_json->>'resolution_failure'),'')
    INTO v_resolution_failure
    FROM pg_temp._bpay_wb_fact_page_v1 page
    WHERE NULLIF(BTRIM(page.source_payload_json->>'resolution_failure'),'') IS NOT NULL
    ORDER BY
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN page.source_key END COLLATE "C",
      CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
        THEN page.source_key END
    LIMIT 1;
    IF v_resolution_failure IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ECONOMIC_KEY_RESOLUTION_INCOMPLETE'
        USING ERRCODE='23514',DETAIL=v_resolution_failure;
    END IF;
    IF v_fact_family='FINANCE_ITEM_AUTHORITY' THEN
      v_raw_source_has_more:=COALESCE(
        (v_occurrence_bundle->>'raw_source_has_more')::boolean,false);
      v_has_more:=v_raw_source_has_more;
    ELSIF v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
       AND v_input_phase<>'PROJECTION' THEN
      v_raw_source_has_more:=COALESCE(
        (v_occurrence_bundle->>'raw_source_has_more')::boolean,false);
      v_has_more:=v_raw_source_has_more;
    ELSE
      v_raw_source_has_more:=false;
      SELECT count(*)>v_fact_limit INTO v_has_more FROM pg_temp._bpay_wb_fact_page_v1;
    END IF;
    SELECT count(*)::integer,
      md5(CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN v_reservation_order_contract||':' ELSE '' END
        ||COALESCE(string_agg(source_key||':'||financial_digest,'' ORDER BY
          CASE WHEN v_fact_family='RESERVATION_COMPONENT'
            THEN source_key END COLLATE "C",
          CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
            THEN source_key END),'')),
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN max(source_key COLLATE "C") ELSE max(source_key) END
    INTO v_page_count,v_page_digest,v_last_page_key
    FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN source_key END COLLATE "C",
      CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
        THEN source_key END LIMIT v_fact_limit) page_rows;

    IF NOT v_has_more AND v_fact_family='LIVE_ENTITLEMENT_INPUT' AND v_input_phase='PROJECTION' THEN
      SELECT projection_ids.projected_timesheet_id INTO v_next_projection_id
      FROM (
        SELECT fact.timesheet_id AS projected_timesheet_id
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id AND fact.fact_family='LIVE_ENTITLEMENT_INPUT'
          AND fact.dependency_unit_key=v_unit_key AND fact.source_relation='UNIT_PROJECTION'
        UNION ALL
        SELECT page.timesheet_id
        FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
          CASE WHEN v_fact_family='RESERVATION_COMPONENT'
            THEN source_key END COLLATE "C",
          CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
            THEN source_key END LIMIT v_fact_limit) page
        WHERE page.source_relation='UNIT_PROJECTION'
      ) projection_ids
      ORDER BY projection_ids.projected_timesheet_id
      LIMIT 1;
      IF v_next_projection_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_UNIT_PROJECTION_INCOMPLETE' USING ERRCODE='23514';
      END IF;
      v_projection_phase_transition:=true;
      v_has_more:=true;
    ELSIF NOT v_has_more
      AND v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK') THEN
      SELECT projection.timesheet_id INTO v_next_projection_id
      FROM private.banking_pay_workbench_economic_build_facts projection
      WHERE projection.build_id=v_build_id
        AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
        AND projection.dependency_unit_key=v_unit_key
        AND projection.source_relation='UNIT_PROJECTION'
        AND projection.timesheet_id>v_input_projection_id
      ORDER BY projection.timesheet_id
      LIMIT 1;
      IF v_next_projection_id IS NOT NULL THEN
        v_projection_family_transition:=true;
        v_has_more:=true;
      END IF;
    END IF;

    IF v_fact_family='FINANCE_ITEM_AUTHORITY' OR (
         v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
         AND v_input_phase<>'PROJECTION') THEN
      v_has_more:=private.pay_workbench_physical_source_continuation_v1(
        v_raw_source_has_more,
        COALESCE((v_occurrence_bundle->>'raw_source_exhausted')::boolean,false),
        v_projection_family_transition);
    END IF;

    IF v_fact_family='FINANCE_ITEM_AUTHORITY' OR (
         v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
         AND v_input_phase<>'PROJECTION') THEN
      v_page_physical_source_count:=COALESCE((v_occurrence_bundle->>'raw_page_count')::bigint,0);
      v_page_resolved_source_count:=COALESCE((v_occurrence_bundle->>'resolved_page_count')::bigint,0);
      v_page_failed_source_count:=COALESCE((v_occurrence_bundle->>'failed_page_count')::bigint,0);
      v_page_physical_amount_ex_vat:=COALESCE((v_occurrence_bundle->>'raw_amount_ex_vat')::numeric,0);
      v_page_resolved_amount_ex_vat:=COALESCE((v_occurrence_bundle->>'resolved_amount_ex_vat')::numeric,0);
      IF (v_page_physical_source_count>0
           AND NULLIF(v_occurrence_bundle->>'last_raw_source_key','') IS NULL)
         OR NULLIF(v_occurrence_bundle->>'evidence_digest','') IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_EVIDENCE_INVALID'
          USING ERRCODE='23514';
      END IF;
    ELSE
      SELECT count(*)::bigint,
        count(*) FILTER(WHERE NULLIF(page.source_payload_json->>'resolution_failure','') IS NULL)::bigint,
        count(*) FILTER(WHERE NULLIF(page.source_payload_json->>'resolution_failure','') IS NOT NULL)::bigint,
        ROUND(COALESCE(sum(COALESCE(page.truth_ex_vat,page.amount_ex_vat,
          page.reserved_source_amount,0)),0),2),
        ROUND(COALESCE(sum(COALESCE(page.truth_ex_vat,page.amount_ex_vat,
          page.reserved_source_amount,0)) FILTER(
            WHERE NULLIF(page.source_payload_json->>'resolution_failure','') IS NULL),0),2)
      INTO v_page_physical_source_count,v_page_resolved_source_count,
        v_page_failed_source_count,v_page_physical_amount_ex_vat,
        v_page_resolved_amount_ex_vat
      FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
        CASE WHEN v_fact_family='RESERVATION_COMPONENT'
          THEN source_key END COLLATE "C",
        CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
          THEN source_key END LIMIT v_fact_limit) page
      WHERE v_fact_family='RESERVATION_COMPONENT'
        AND page.source_relation<>'UNIT_PROJECTION';
      IF v_fact_family='RESERVATION_COMPONENT' THEN
        SELECT jsonb_build_object(
          'evidence_digest',md5(v_reservation_order_contract||':'||COALESCE(string_agg(page.source_key||':'||COALESCE(
            NULLIF(page.source_payload_json->>'raw_physical_digest',''),page.financial_digest),''
            ORDER BY page.source_key COLLATE "C"),'')),
          'last_raw_source_key',max(page.source_key COLLATE "C"))
        INTO v_occurrence_bundle
        FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1
          ORDER BY source_key COLLATE "C" LIMIT v_fact_limit) page;
      END IF;
    END IF;
    v_next_raw_physical_source_count:=v_raw_physical_source_count+
      COALESCE(v_page_physical_source_count,0);
    v_next_resolved_physical_source_count:=v_resolved_physical_source_count+
      COALESCE(v_page_resolved_source_count,0);
    v_next_failed_physical_source_count:=v_failed_physical_source_count+
      COALESCE(v_page_failed_source_count,0);
    v_next_raw_physical_amount_ex_vat:=ROUND(v_raw_physical_amount_ex_vat+
      COALESCE(v_page_physical_amount_ex_vat,0),2);
    v_next_resolved_physical_amount_ex_vat:=ROUND(v_resolved_physical_amount_ex_vat+
      COALESCE(v_page_resolved_amount_ex_vat,0),2);
    v_next_last_raw_physical_source_key:=COALESCE(
      NULLIF(v_occurrence_bundle->>'last_raw_source_key',''),
      CASE WHEN v_page_physical_source_count>0 THEN v_last_page_key END,
      v_last_raw_physical_source_key);
    v_cursor_start_hash:=md5(v_cursor::text);
    v_next_cumulative_fact_count:=v_cumulative_fact_count+v_page_count;
    v_cumulative_digest:=md5(v_cumulative_digest||v_page_digest);
    v_is_final:=NOT v_has_more;
    v_next:=jsonb_build_object('cursor_kind','WORKSPACE_FACT','cursor_version',2,
      'build_id',v_build_id,'candidate_id',p_candidate_id,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'dependency_unit_key',v_unit_key,'fact_family',v_fact_family,
      'page_number',v_page_number+1,'last_source_key',CASE
        WHEN v_projection_phase_transition OR v_projection_family_transition THEN NULL
        WHEN v_has_more THEN v_last_page_key ELSE NULL END,
      'previous_page_digest',v_page_digest,'cumulative_fact_count',v_next_cumulative_fact_count,
      'cumulative_digest',v_cumulative_digest,
      'terminal',v_is_final,
      'raw_physical_source_count',v_next_raw_physical_source_count,
      'resolved_physical_source_count',v_next_resolved_physical_source_count,
      'failed_physical_source_count',v_next_failed_physical_source_count,
      'raw_physical_amount_ex_vat',v_next_raw_physical_amount_ex_vat,
      'resolved_physical_amount_ex_vat',v_next_resolved_physical_amount_ex_vat,
      'last_raw_physical_source_key',v_next_last_raw_physical_source_key,
      'source_exhausted',v_is_final,
      'raw_terminal_source_key',CASE WHEN v_is_final AND v_page_physical_source_count>0
        THEN v_next_last_raw_physical_source_key
        WHEN v_is_final AND v_next_raw_physical_source_count>0
        THEN v_next_last_raw_physical_source_key END,
      'raw_page_evidence_digest',v_occurrence_bundle->>'evidence_digest',
      'input_phase',CASE WHEN v_projection_phase_transition THEN 'COMPONENTS'
        ELSE v_input_phase END,
      'input_projection_id',CASE WHEN v_projection_phase_transition OR v_projection_family_transition
        THEN v_next_projection_id ELSE v_input_projection_id END);
    IF v_fact_family='RESERVATION_COMPONENT' THEN
      v_next:=v_next || jsonb_build_object(
        'reservation_source_key_order_contract',v_reservation_order_contract);
    END IF;
    v_cursor_end_hash:=md5(v_next::text);
    v_expected_source_count:=CASE
      WHEN v_is_final AND v_fact_family IN ('FINANCE_ITEM_AUTHORITY','LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT',
        'PAY_STATE_FALLBACK','RESERVATION_COMPONENT')
        THEN v_next_raw_physical_source_count::integer
      ELSE NULL END;

    IF v_page_number=1 THEN
      IF v_cumulative_fact_count<>0 OR v_cursor->>'previous_page_digest' IS NOT NULL
         OR v_cursor->>'cumulative_digest' IS DISTINCT FROM md5('BPAY_FACT_STREAM_V2')
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_fact_pages
           WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key
             AND fact_family=v_fact_family LIMIT 1) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_CHAIN_INCOMPLETE' USING ERRCODE='23514';
      END IF;
    ELSE
      SELECT * INTO v_previous_page
      FROM private.banking_pay_workbench_economic_build_fact_pages
      WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key
        AND fact_family=v_fact_family AND page_number=v_page_number-1;
      IF v_previous_page.id IS NULL OR v_previous_page.status<>'COMPLETED'
         OR v_previous_page.is_family_final
         OR v_previous_page.cursor_end_hash<>v_cursor_start_hash
         OR v_previous_page.cursor_end_json IS DISTINCT FROM v_cursor
         OR v_previous_page.cumulative_fact_count<>v_cumulative_fact_count
         OR v_previous_page.cumulative_digest<>COALESCE(v_cursor->>'cumulative_digest','')
         OR v_previous_page.page_digest<>COALESCE(v_cursor->>'previous_page_digest','') THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_CHAIN_INCOMPLETE' USING ERRCODE='23514';
      END IF;
    END IF;

    SELECT * INTO v_existing_page FROM private.banking_pay_workbench_economic_build_fact_pages
    WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key
      AND fact_family=v_fact_family AND page_number=v_page_number;
    IF FOUND THEN
      IF v_existing_page.attempt_id IS DISTINCT FROM v_attempt_id
         OR v_existing_page.status<>'COMPLETED'
         OR v_existing_page.cursor_start_json IS DISTINCT FROM v_cursor
         OR v_existing_page.cursor_start_hash<>v_cursor_start_hash
         OR v_existing_page.cursor_end_json IS DISTINCT FROM v_next
         OR v_existing_page.cursor_end_hash<>v_cursor_end_hash
         OR v_existing_page.expected_source_count IS DISTINCT FROM v_expected_source_count
         OR v_existing_page.actual_fact_count<>v_page_count
         OR v_existing_page.cumulative_fact_count<>v_next_cumulative_fact_count
         OR v_existing_page.page_digest<>v_page_digest
         OR v_existing_page.cumulative_digest<>v_cumulative_digest
         OR v_existing_page.is_family_final IS DISTINCT FROM v_is_final THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_REPLAY_CONFLICT' USING ERRCODE='23514';
      END IF;
      SELECT fact_cursor_json INTO v_replay_cursor
      FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage',v_build.private_stage,'stage_status','PAGE_REPLAYED',
        'has_more',true,'continuation_enqueued',false,
        'next_cursor_json',COALESCE(v_replay_cursor,v_next),'next_action',v_build.private_stage,
        'page_fact_count',v_page_count,'cumulative_fact_count',v_next_cumulative_fact_count,
        'page_digest',v_page_digest,'cumulative_digest',v_cumulative_digest);
    END IF;

    IF EXISTS(
      SELECT 1 FROM pg_temp._bpay_wb_fact_page_v1 page_row
      JOIN private.banking_pay_workbench_economic_build_facts existing
        ON existing.build_id=v_build_id AND existing.fact_family=v_fact_family
       AND existing.natural_key=page_row.natural_key
      WHERE existing.financial_digest<>page_row.financial_digest LIMIT 1
    ) THEN RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_REPLAY_CONFLICT' USING ERRCODE='23514'; END IF;

    IF v_fact_family IS NOT NULL THEN
      INSERT INTO private.banking_pay_workbench_economic_build_facts(
      build_id,fact_family,natural_key,candidate_id,timesheet_id,subject_timesheet_ids,
      dependency_unit_key,source_relation,source_id,economic_key_type,economic_key_value,
      amount_ex_vat,amount_inc_vat,truth_ex_vat,truth_inc_vat,baseline_ex_vat,baseline_inc_vat,
      reserved_source_amount,finance_case_id,finance_component_id,reservation_id,
      source_payload_json,financial_digest
    )
    SELECT v_build_id,v_fact_family,page.natural_key,p_candidate_id,page.timesheet_id,
      page.subject_timesheet_ids,v_unit_key,page.source_relation,page.source_id,
      page.economic_key_type,page.economic_key_value,page.amount_ex_vat,page.amount_inc_vat,
      page.truth_ex_vat,page.truth_inc_vat,page.baseline_ex_vat,page.baseline_inc_vat,
      page.reserved_source_amount,page.finance_case_id,page.finance_component_id,page.reservation_id,
      page.source_payload_json,page.financial_digest
    FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN source_key END COLLATE "C",
      CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
        THEN source_key END LIMIT v_fact_limit) page;
      GET DIAGNOSTICS v_scope_inserted=ROW_COUNT;
      IF v_scope_inserted<>v_page_count THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_COUNT_MISMATCH' USING ERRCODE='23514';
      END IF;
    ELSE
      v_scope_inserted:=0;
    END IF;

    -- Physical occurrences are already typed and immutable. Derived families
    -- page those stored occurrences; no page-local live helper is invoked.
    v_derived_fact_count:=0;
    v_derived_settled_count:=0;
    v_derived_fallback_count:=0;

    -- The table's physical column order evaluates completed_at_utc before
    -- created_at_utc.  Supplying one database-owned timestamp prevents two
    -- independent clock_timestamp() defaults from intermittently violating
    -- completed_at_utc >= created_at_utc under fast concurrent lanes.
    v_fact_page_timestamp:=clock_timestamp();
    INSERT INTO private.banking_pay_workbench_economic_build_fact_pages(
      build_id,attempt_id,dependency_unit_key,fact_family,page_number,
      cursor_start_json,cursor_start_hash,cursor_end_json,cursor_end_hash,
      expected_source_count,actual_fact_count,cumulative_fact_count,page_digest,cumulative_digest,is_family_final,
      completed_at_utc,created_at_utc
    ) VALUES(v_build_id,v_attempt_id,v_unit_key,v_fact_family,v_page_number,
      v_cursor,v_cursor_start_hash,v_next,v_cursor_end_hash,v_expected_source_count,v_page_count,
      v_next_cumulative_fact_count,v_page_digest,v_cumulative_digest,v_is_final,
      v_fact_page_timestamp,v_fact_page_timestamp);

    IF v_unit_key<>'GLOBAL' THEN
      UPDATE private.banking_pay_workbench_economic_build_scope scope_row
      SET fact_row_count=scope_row.fact_row_count+page_count.page_count,
          fact_digest=md5(COALESCE(scope_row.fact_digest,md5('BPAY_SCOPE_FACT_V1'))||v_page_digest),
          updated_at_utc=clock_timestamp()
      FROM (
        SELECT page.timesheet_id,count(*)::integer page_count
        FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
          CASE WHEN v_fact_family='RESERVATION_COMPONENT'
            THEN source_key END COLLATE "C",
          CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
            THEN source_key END LIMIT v_fact_limit) page
        WHERE page.timesheet_id IS NOT NULL GROUP BY page.timesheet_id
      ) page_count
      WHERE scope_row.build_id=v_build_id AND scope_row.timesheet_id=page_count.timesheet_id;
    END IF;

    UPDATE private.banking_pay_workbench_economic_builds build_row
    SET fact_count=build_row.fact_count+v_scope_inserted+v_derived_fact_count+v_derived_settled_count+v_derived_fallback_count,
        complexity_vector_json=COALESCE(build_row.complexity_vector_json,'{}'::jsonb)
          ||jsonb_build_object(
            'settled_source_row_count',COALESCE((build_row.complexity_vector_json->>'settled_source_row_count')::bigint,0)+page_stats.settled_count,
            'settled_component_count',COALESCE((build_row.complexity_vector_json->>'settled_component_count')::bigint,0)+page_stats.settled_count,
            'entitlement_component_count',COALESCE((build_row.complexity_vector_json->>'entitlement_component_count')::bigint,0)+page_stats.entitlement_count,
            'reservation_component_count',COALESCE((build_row.complexity_vector_json->>'reservation_component_count')::bigint,0)+page_stats.reservation_count,
            'finance_case_count',COALESCE((build_row.complexity_vector_json->>'finance_case_count')::bigint,0)+page_stats.case_count,
            'finance_component_count',COALESCE((build_row.complexity_vector_json->>'finance_component_count')::bigint,0)+page_stats.component_count,
            'protection_evidence_count',COALESCE((build_row.complexity_vector_json->>'protection_evidence_count')::bigint,0)+page_stats.protection_count,
            'expected_case_insert_count',COALESCE((build_row.complexity_vector_json->>'expected_case_insert_count')::bigint,0)+page_stats.negative_count,
            'expected_component_insert_count',COALESCE((build_row.complexity_vector_json->>'expected_component_insert_count')::bigint,0)+page_stats.negative_count,
            'canonical_source_row_count',COALESCE((build_row.complexity_vector_json->>'canonical_source_row_count')::bigint,0)+page_stats.canonical_count,
            'staging_bytes',COALESCE((build_row.complexity_vector_json->>'staging_bytes')::bigint,0)+page_stats.staging_bytes),
        updated_at_utc=clock_timestamp()
    FROM (SELECT
      count(*) FILTER(WHERE v_fact_family='FROZEN_SETTLED_COMPONENT')::bigint settled_count,
      count(*) FILTER(WHERE v_fact_family='ENTITLEMENT_COMPONENT')::bigint entitlement_count,
      count(*) FILTER(WHERE v_fact_family='RESERVATION_COMPONENT')::bigint reservation_count,
      count(*) FILTER(WHERE v_fact_family='FINANCE_CASE_IDENTITY')::bigint case_count,
      count(*) FILTER(WHERE v_fact_family='FINANCE_COMPONENT_IDENTITY')::bigint component_count,
      count(*) FILTER(WHERE v_fact_family='PROTECTION_EVIDENCE')::bigint protection_count,
      count(*) FILTER(WHERE v_fact_family='ENTITLEMENT_COMPONENT' AND truth_ex_vat<baseline_ex_vat)::bigint negative_count,
      count(*) FILTER(WHERE v_fact_family='CANONICAL_INPUT')::bigint canonical_count,
      COALESCE(sum(pg_column_size(source_payload_json)) FILTER(WHERE v_fact_family='CANONICAL_INPUT'),0)::bigint staging_bytes
      FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
        CASE WHEN v_fact_family='RESERVATION_COMPONENT'
          THEN source_key END COLLATE "C",
        CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
          THEN source_key END LIMIT v_fact_limit) accepted) page_stats
    WHERE build_row.id=v_build_id;

    IF v_is_final THEN
      IF v_unit_key<>'GLOBAL' THEN
        UPDATE private.banking_pay_workbench_economic_build_scope
        SET completed_fact_families=(SELECT array_agg(DISTINCT family ORDER BY family)
          FROM unnest(completed_fact_families||ARRAY[v_fact_family]) family),updated_at_utc=clock_timestamp()
        WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key;
      END IF;
      IF v_unit_key='GLOBAL' AND v_fact_family='FINANCE_ITEM_AUTHORITY' THEN
        SELECT dependency_unit_key INTO v_unit_key
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id AND NOT required_fact_families <@ completed_fact_families
        ORDER BY stable_ordinal LIMIT 1;
        IF v_unit_key IS NULL THEN
          v_unit_key:='GLOBAL';
          v_fact_family:=v_global_families[2];
        ELSE
          v_fact_family:=v_unit_families[1];
        END IF;
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,v_unit_key,v_fact_family,
          CASE WHEN v_unit_key<>'GLOBAL' THEN 'PROJECTION'
            ELSE 'PHYSICAL_SOURCE' END,NULL);
      ELSIF v_unit_key<>'GLOBAL' AND v_family_ordinal<cardinality(v_unit_families) THEN
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,v_unit_key,v_unit_families[v_family_ordinal+1],
          CASE WHEN v_unit_families[v_family_ordinal+1]='LIVE_ENTITLEMENT_INPUT'
            THEN 'PROJECTION' ELSE 'COMPONENTS' END,NULL);
      ELSIF v_unit_key<>'GLOBAL' THEN
        SELECT dependency_unit_key INTO v_unit_key
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id AND NOT required_fact_families <@ completed_fact_families
        ORDER BY stable_ordinal LIMIT 1;
        IF v_unit_key IS NULL THEN v_unit_key:='GLOBAL';v_fact_family:=v_global_families[2];
        ELSE v_fact_family:=v_unit_families[1]; END IF;
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,v_unit_key,v_fact_family,
          CASE WHEN v_unit_key<>'GLOBAL' THEN 'PROJECTION'
            ELSE 'PHYSICAL_SOURCE' END,NULL);
      ELSIF v_family_ordinal<cardinality(v_global_families) THEN
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,'GLOBAL',v_global_families[v_family_ordinal+1],
          'PHYSICAL_SOURCE',NULL);
      ELSE
        IF EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
          WHERE build_id=v_build_id AND NOT required_fact_families<@completed_fact_families LIMIT 1) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_CHAIN_INCOMPLETE' USING ERRCODE='23514';
        END IF;
        IF EXISTS(
          WITH required_stream AS (
            SELECT DISTINCT scope_row.dependency_unit_key,required.family AS fact_family
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            CROSS JOIN LATERAL unnest(ARRAY['LIVE_ENTITLEMENT_INPUT',
              'FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK']) required(family)
            WHERE scope_row.build_id=v_build_id
            UNION ALL SELECT 'GLOBAL'::text,'FINANCE_ITEM_AUTHORITY'::text
            UNION ALL SELECT 'GLOBAL'::text,'RESERVATION_COMPONENT'::text
          ), terminal_stream AS (
            SELECT page.dependency_unit_key,page.fact_family,count(*) AS terminal_count,
              min(page.expected_source_count) AS expected_source_count,
              min((page.cursor_end_json->>'raw_physical_source_count')::bigint) AS raw_count,
              min((page.cursor_end_json->>'resolved_physical_source_count')::bigint) AS resolved_count,
              min((page.cursor_end_json->>'failed_physical_source_count')::bigint) AS failed_count,
              min((page.cursor_end_json->>'raw_physical_amount_ex_vat')::numeric) AS raw_amount,
              min((page.cursor_end_json->>'resolved_physical_amount_ex_vat')::numeric) AS resolved_amount,
              min(NULLIF(page.cursor_end_json->>'raw_terminal_source_key','')) AS terminal_source_key,
              bool_and(COALESCE((page.cursor_end_json->>'source_exhausted')::boolean,false)) AS exhausted
            FROM private.banking_pay_workbench_economic_build_fact_pages page
            WHERE page.build_id=v_build_id AND page.status='COMPLETED' AND page.is_family_final
            GROUP BY page.dependency_unit_key,page.fact_family
          )
          SELECT 1 FROM required_stream required
          LEFT JOIN terminal_stream terminal USING(dependency_unit_key,fact_family)
          WHERE terminal.terminal_count IS DISTINCT FROM 1
             OR terminal.expected_source_count IS DISTINCT FROM terminal.raw_count::integer
             OR terminal.raw_count IS DISTINCT FROM terminal.resolved_count
             OR terminal.failed_count IS DISTINCT FROM 0
             OR ROUND(terminal.raw_amount,2) IS DISTINCT FROM ROUND(terminal.resolved_amount,2)
             OR (terminal.raw_count>0 AND terminal.terminal_source_key IS NULL)
             OR terminal.exhausted IS DISTINCT FROM true
          LIMIT 1
        ) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_SEAL_INCOMPLETE' USING ERRCODE='23514';
        END IF;
        IF v_registry.initialisation_status IN ('DISCOVERING','CLASSIFYING')
           AND v_registry.bootstrap_id IS NOT NULL
           AND COALESCE((v_build.attestation_json->>'bootstrap_active_reconciliation')::boolean,false)
             IS NOT TRUE THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_registry.bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','EVIDENCE','last_dependency_unit_key',NULL,
            'dependency_unit_key',NULL,'last_stable_ordinal',0,
            'unit_financially_relevant',false,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
          UPDATE private.banking_pay_workbench_economic_builds
          SET status='COLLECTING',private_stage='BOOTSTRAP_DISCOVERY',
            fact_cursor_json=jsonb_build_object('cursor_kind','WORKSPACE_FACT','cursor_version',2,
              'terminal',true,'build_id',v_build_id),
            updated_at_utc=clock_timestamp()
          WHERE id=v_build_id;
          UPDATE private.banking_pay_workbench_candidate_scope_registry
          SET initialisation_status='CLASSIFYING',bootstrap_stream='CLASSIFY_UNITS',
            bootstrap_cursor_json=v_next,updated_at_utc=clock_timestamp()
          WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
          RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
            'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
            'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
            'next_action','BOOTSTRAP_DISCOVERY');
        END IF;
        SELECT COALESCE(complexity_vector_json,'{}'::jsonb)||jsonb_build_object(
          'relevant_timesheet_count',scope_count,'dependency_node_count',dependency_node_count,
          'dependency_edge_count',dependency_edge_count,
          'expected_case_update_count',COALESCE((complexity_vector_json->>'finance_case_count')::bigint,0),
          'expected_case_clear_count',0,
          'expected_component_update_count',COALESCE((complexity_vector_json->>'finance_component_count')::bigint,0),
          'expected_component_close_count',0)
        INTO v_vector FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
        SELECT banking_pay_workbench_reconciliation_envelope_version,
               banking_pay_workbench_reconciliation_envelope_json,
               banking_pay_workbench_reconciliation_envelope_evidence_json
        INTO v_envelope_version,v_envelope,v_envelope_evidence
        FROM public.settings_defaults WHERE id=1;
        IF v_envelope_version IS NULL OR jsonb_typeof(v_envelope)<>'object' OR v_envelope='{}'::jsonb
           OR jsonb_typeof(v_envelope_evidence)<>'object' OR v_envelope_evidence='{}'::jsonb THEN
          v_scale_blocked:=true;
          v_scale_block_reason:='ENVELOPE_OR_EVIDENCE_MISSING_OR_MALFORMED';
          -- A malformed or absent configuration is itself immutable scale-block
          -- evidence.  Preserve a truthful non-empty snapshot so the durable
          -- BLOCKED row satisfies its lifecycle constraint without inventing a
          -- financial limit or allowing reconciliation to continue.
          v_envelope_version:=COALESCE(v_envelope_version,1);
          v_envelope:=jsonb_build_object(
            '_authority_state','ENVELOPE_OR_EVIDENCE_MISSING_OR_MALFORMED'
          );
          v_envelope_evidence:=jsonb_build_object(
            'evidence_status','UNVALIDATED_CONFIGURATION'
          );
        ELSE
          FOR v_vector_item IN SELECT key,value FROM jsonb_each_text(v_vector) LOOP
            IF COALESCE(v_envelope->>v_vector_item.key,'') !~ '^[0-9]+$'
               OR v_vector_item.value::numeric>(v_envelope->>v_vector_item.key)::numeric THEN
              v_scale_blocked:=true;
              v_scale_block_reason:='VECTOR_OUTSIDE_MEASURED_ENVELOPE';
              EXIT;
            END IF;
          END LOOP;
        END IF;
        IF v_scale_blocked THEN
          UPDATE private.banking_pay_workbench_economic_builds SET
            status='BLOCKED_UNVALIDATED_RECONCILIATION_SCALE',complexity_vector_json=v_vector,
            envelope_version=v_envelope_version,envelope_snapshot_json=COALESCE(v_envelope,'{}'::jsonb),
            envelope_evidence_json=COALESCE(v_envelope_evidence,'{}'::jsonb),
            attestation_json=attestation_json||jsonb_build_object(
              'reconciliation_scale_block',jsonb_build_object(
                'reason',COALESCE(v_scale_block_reason,'UNVALIDATED_RECONCILIATION_SCALE'),
                'envelope_version',v_envelope_version
              )
            ),
            fact_cursor_json=v_next||jsonb_build_object('terminal',true),updated_at_utc=clock_timestamp()
          WHERE id=v_build_id;
          RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','WORKSPACE_FACT',
            'stage_status','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE','has_more',false,
            'continuation_enqueued',false,'next_action','SCALE_EVIDENCE_REQUIRED','complexity_vector',v_vector);
        END IF;
        v_next:=jsonb_build_object('cursor_kind','RECONCILE_EXECUTE','cursor_version',1,
          'build_id',v_build_id,'candidate_id',p_candidate_id,
          'captured_candidate_generation',v_build.captured_candidate_generation,
          'captured_source_change_seq',v_build.source_change_seq);
        UPDATE private.banking_pay_workbench_economic_builds SET status='READY_FOR_RECONCILIATION',
          private_stage='RECONCILE_EXECUTE',fact_cursor_json=jsonb_build_object(
            'cursor_kind','WORKSPACE_FACT','cursor_version',2,'terminal',true,'build_id',v_build_id),
          complexity_vector_json=v_vector,envelope_version=v_envelope_version,
          envelope_snapshot_json=v_envelope,envelope_evidence_json=v_envelope_evidence,
          ready_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      END IF;
    END IF;
    IF (SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id)='WORKSPACE_FACT' THEN
      UPDATE private.banking_pay_workbench_economic_builds SET fact_cursor_json=v_next,
        updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    END IF;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage',
      (SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'stage_status','PREPARING','has_more',true,'continuation_enqueued',false,
      'next_cursor_json',v_next,'next_action',
      (SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'page_fact_count',v_page_count,'page_digest',v_page_digest);
  END IF;

  IF v_stage='RECONCILE_EXECUTE' THEN
    UPDATE private.banking_pay_workbench_economic_builds SET status='RECONCILING',updated_at_utc=clock_timestamp()
    WHERE id=v_build_id AND status='READY_FOR_RECONCILIATION' AND private_stage='RECONCILE_EXECUTE';
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
    SELECT upper(NULLIF(btrim(to_jsonb(candidate_row)->>'pay_method'),'')) INTO v_candidate_pay_method
    FROM public.candidates candidate_row WHERE candidate_row.id=p_candidate_id;
    v_actor_user_id:=COALESCE(NULLIF(v_payload->>'actor_user_id','')::uuid,v_session.actor_user_id);
    IF COALESCE((v_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE THEN
      BEGIN
        PERFORM set_config('cloudtms.pay_workbench_effect_capture_mode','capture',true);
        v_sync_result:=public.pay_sync_overpayments_from_preview(
          v_session.pay_date,v_session.week_ending_cutoff,v_actor_user_id,v_candidate_pay_method,
          ARRAY[p_candidate_id],COALESCE(v_payload->'mismatch_choices','{}'::jsonb),
          NULLIF(v_payload->>'client_filter_single','')::uuid,NULL,NULL
        );
        v_effect_plan:=COALESCE(v_sync_result->'captured_effects','[]'::jsonb);
        v_capture_timing_json:=CASE
          WHEN jsonb_typeof(v_sync_result->'_internal_reconcile_timing')='object'
            THEN v_sync_result->'_internal_reconcile_timing'
          ELSE '{}'::jsonb
        END;
        IF jsonb_typeof(v_effect_plan)<>'array' THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CAPTURE_INVALID' USING ERRCODE='23514';
        END IF;
        RAISE EXCEPTION 'PAY_WORKBENCH_EFFECT_PLAN_CAPTURE_ROLLBACK' USING ERRCODE='PZ001';
      EXCEPTION WHEN SQLSTATE 'PZ001' THEN
        NULL;
      END;
      -- Generated row identities and audit timestamps are not economic authority.
      -- INSERT effects are normalised, deterministically ordered, and assigned a
      -- build-owned plan identity before the durable plan is sealed.
      WITH ordered AS (
        SELECT raw_effect.value AS raw_effect,raw_effect.ordinality,
          row_number() OVER(ORDER BY raw_effect.value::text,raw_effect.ordinality) AS plan_ordinal
        FROM jsonb_array_elements(COALESCE(v_effect_plan,'[]'::jsonb))
          WITH ORDINALITY raw_effect(value,ordinality)
      ), identified AS (
        SELECT ordered.*,
          CASE WHEN ordered.raw_effect->>'operation'='INSERT'
            THEN (md5(v_build_id::text||':EXPECTED_FINANCE_EFFECT:'||ordered.plan_ordinal::text))::uuid
            ELSE NULLIF(ordered.raw_effect->>'source_id','')::uuid END AS logical_source_id
        FROM ordered
      ), normalised AS (
        SELECT identified.plan_ordinal,
          identified.raw_effect||jsonb_build_object(
            'source_id',identified.logical_source_id,
            'finance_case_id',CASE
              WHEN identified.raw_effect->>'operation'='INSERT'
               AND identified.raw_effect->>'relation_name'='pay_advances'
                THEN identified.logical_source_id
              WHEN NULLIF(identified.raw_effect->>'finance_case_id','') IS NULL THEN NULL
              ELSE COALESCE((SELECT parent.logical_source_id FROM identified parent
                WHERE parent.raw_effect->>'operation'='INSERT'
                  AND parent.raw_effect->>'relation_name'='pay_advances'
                  AND NULLIF(parent.raw_effect->>'source_id','')::uuid=
                    NULLIF(identified.raw_effect->>'finance_case_id','')::uuid),
                NULLIF(identified.raw_effect->>'finance_case_id','')::uuid) END,
            'finance_component_id',CASE
              WHEN identified.raw_effect->>'operation'='INSERT'
               AND identified.raw_effect->>'relation_name'='pay_finance_case_components'
                THEN identified.logical_source_id
              WHEN NULLIF(identified.raw_effect->>'finance_component_id','') IS NULL THEN NULL
              ELSE COALESCE((SELECT parent.logical_source_id FROM identified parent
                WHERE parent.raw_effect->>'operation'='INSERT'
                  AND parent.raw_effect->>'relation_name'='pay_finance_case_components'
                  AND NULLIF(parent.raw_effect->>'source_id','')::uuid=
                    NULLIF(identified.raw_effect->>'finance_component_id','')::uuid),
                NULLIF(identified.raw_effect->>'finance_component_id','')::uuid) END
          ) AS effect
        FROM identified
      )
      SELECT COALESCE(jsonb_agg(normalised.effect ORDER BY normalised.plan_ordinal),'[]'::jsonb)
      INTO v_effect_plan FROM normalised;
      v_effect_plan_count:=jsonb_array_length(COALESCE(v_effect_plan,'[]'::jsonb));
      v_effect_plan_digest:=md5(COALESCE(v_effect_plan::text,'[]'));
      DELETE FROM private.banking_pay_workbench_economic_build_facts
      WHERE build_id=v_build_id AND fact_family='EXPECTED_FINANCE_EFFECT';
      INSERT INTO private.banking_pay_workbench_economic_build_facts(build_id,fact_family,natural_key,
        candidate_id,timesheet_id,subject_timesheet_ids,dependency_unit_key,source_relation,source_id,
        finance_case_id,finance_component_id,economic_key_type,economic_key_value,
        source_payload_json,financial_digest,source_ordinal)
      SELECT v_build_id,'EXPECTED_FINANCE_EFFECT',md5('EXPECTED_FINANCE_EFFECT:'||effect.ordinality::text||':'||effect.value::text),
        (effect.value->>'candidate_id')::uuid,NULLIF(effect.value->>'timesheet_id','')::uuid,
        CASE WHEN NULLIF(effect.value->>'timesheet_id','') IS NULL THEN ARRAY[]::uuid[]
          ELSE ARRAY[(effect.value->>'timesheet_id')::uuid] END,'GLOBAL',effect.value->>'relation_name',
        (effect.value->>'source_id')::uuid,
        NULLIF(effect.value->>'finance_case_id','')::uuid,
        NULLIF(effect.value->>'finance_component_id','')::uuid,
        NULLIF(effect.value->>'economic_key_type',''),
        NULLIF(effect.value->>'economic_key_value',''),jsonb_build_object(
          'operation',effect.value->>'operation',
          'expected_before_digest',effect.value->>'expected_before_digest',
          'expected_after_digest',effect.value->>'expected_after_digest'),md5(effect.value::text),effect.ordinality
      FROM jsonb_array_elements(COALESCE(v_effect_plan,'[]'::jsonb)) WITH ORDINALITY effect(value,ordinality);
      UPDATE private.banking_pay_workbench_economic_builds SET status='READY_FOR_RECONCILIATION',
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'effect_plan_sealed',true,'effect_plan_count',v_effect_plan_count,
          'effect_plan_digest',v_effect_plan_digest,'effect_plan_created_at_utc',clock_timestamp(),
          'reconcile_capture_timing_json',v_capture_timing_json),
        updated_at_utc=clock_timestamp() WHERE id=v_build_id AND status='RECONCILING';
      v_next:=jsonb_build_object('cursor_kind','RECONCILE_EXECUTE','cursor_version',1,
        'build_id',v_build_id,'candidate_id',p_candidate_id,'reconcile_phase','EXECUTE',
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,'effect_plan_digest',v_effect_plan_digest);
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','RECONCILE_EXECUTE',
        'stage_status','EFFECT_PLAN_READY','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',v_next,'next_action','RECONCILE_EXECUTE',
        'effect_plan_count',v_effect_plan_count,'effect_plan_digest',v_effect_plan_digest);
    END IF;
    SELECT count(*)::integer,md5(COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id',fact.candidate_id,'timesheet_id',fact.timesheet_id,
      'relation_name',fact.source_relation,'operation',fact.source_payload_json->>'operation',
      'source_id',fact.source_id,'finance_case_id',fact.finance_case_id,
      'finance_component_id',fact.finance_component_id,
      'economic_key_type',fact.economic_key_type,'economic_key_value',fact.economic_key_value,
      'expected_before_digest',NULLIF(fact.source_payload_json->>'expected_before_digest',''),
      'expected_after_digest',NULLIF(fact.source_payload_json->>'expected_after_digest','')
      ) ORDER BY fact.source_ordinal),'[]'::jsonb)::text)
    INTO v_effect_plan_count,v_effect_plan_digest
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=v_build_id AND fact.fact_family='EXPECTED_FINANCE_EFFECT';
    IF v_effect_plan_count IS DISTINCT FROM
         COALESCE((v_build.attestation_json->>'effect_plan_count')::integer,0)
       OR v_effect_plan_digest IS DISTINCT FROM v_build.attestation_json->>'effect_plan_digest'
       OR NULLIF(v_cursor->>'effect_plan_digest','') IS DISTINCT FROM
          v_build.attestation_json->>'effect_plan_digest' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_MISMATCH'
        USING ERRCODE='23514';
    END IF;
    v_sync_result:=public.pay_sync_overpayments_from_preview(
      v_session.pay_date,v_session.week_ending_cutoff,v_actor_user_id,v_candidate_pay_method,
      ARRAY[p_candidate_id],COALESCE(v_payload->'mismatch_choices','{}'::jsonb),
      NULLIF(v_payload->>'client_filter_single','')::uuid,NULL,NULL
    );
    SELECT canonical_count<=25 INTO v_publish_now FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
    IF NOT v_publish_now THEN
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','SOURCE_PUBLISH',
        'stage_status','RECONCILED','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',(SELECT publication_cursor_json FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
        'next_action','SOURCE_PUBLISH','sync_result',v_sync_result);
    END IF;
    v_stage:='SOURCE_PUBLISH';
  END IF;

  IF v_stage='SOURCE_PUBLISH' THEN
    SELECT * INTO v_build FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id FOR UPDATE;
    IF v_build.status NOT IN ('RECONCILED','PUBLISHING') OR v_build.private_stage<>'SOURCE_PUBLISH'
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_canonical_stage_lines
         WHERE build_id=v_build_id AND stage_status<>'VERIFIED' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PUBLICATION_NOT_READY' USING ERRCODE='23514';
    END IF;
    UPDATE private.banking_pay_workbench_economic_builds SET status='PUBLISHING',updated_at_utc=clock_timestamp()
    WHERE id=v_build_id;
    v_source_publication_id:=CASE WHEN COALESCE((
      SELECT setting.banking_pay_source_publication_identity_write_v1_enabled
      FROM public.settings_defaults AS setting WHERE setting.id=1
    ),false) THEN private.pay_workbench_source_publication_identity_v1(
      p_session_id,p_candidate_id,v_build.session_version,
      v_build.source_change_seq,v_build.source_build_run_id
    ) ELSE NULL::uuid END;
    PERFORM 1 FROM public.banking_pay_workbench_candidate_source_lines
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT'
    ORDER BY source_ordinal FOR UPDATE;

    SELECT count(*)::integer,
           md5(COALESCE(string_agg(md5(source_row_json::text),'' ORDER BY source_ordinal),''))
    INTO v_existing_publication_count,v_existing_publication_digest
    FROM public.banking_pay_workbench_candidate_source_lines
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id
      AND session_version=v_build.session_version
      AND source_change_seq=v_build.source_change_seq
      AND source_build_run_id=v_build.source_build_run_id
      AND source_publication_id IS NOT DISTINCT FROM v_source_publication_id
      AND status IN ('DIRTY','CURRENT','SUPERSEDED');

    IF v_existing_publication_count>0 THEN
      IF v_existing_publication_count IS DISTINCT FROM v_build.canonical_count
         OR v_existing_publication_digest IS DISTINCT FROM v_build.canonical_digest THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PUBLICATION_REPLAY_CONFLICT'
          USING ERRCODE='23514',DETAIL=jsonb_build_object(
            'code','PAY_WORKBENCH_CANONICAL_PUBLICATION_REPLAY_CONFLICT',
            'build_id',v_build_id,'source_publication_id',v_source_publication_id,
            'expected_count',v_build.canonical_count,'actual_count',v_existing_publication_count,
            'expected_digest',v_build.canonical_digest,'actual_digest',v_existing_publication_digest
          )::text;
      END IF;
      UPDATE public.banking_pay_workbench_candidate_source_lines
      SET status='SUPERSEDED',updated_at_utc=clock_timestamp()
      WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT'
        AND source_publication_id IS DISTINCT FROM v_source_publication_id;
      UPDATE public.banking_pay_workbench_candidate_source_lines
      SET status='CURRENT',updated_at_utc=clock_timestamp()
      WHERE session_id=p_session_id AND candidate_id=p_candidate_id
        AND source_publication_id IS NOT DISTINCT FROM v_source_publication_id
        AND source_build_run_id=v_build.source_build_run_id
        AND status<>'CURRENT';
      v_published_count:=v_existing_publication_count;
    ELSE
      UPDATE public.banking_pay_workbench_candidate_source_lines
      SET status='SUPERSEDED',updated_at_utc=clock_timestamp()
      WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT';
      INSERT INTO public.banking_pay_workbench_candidate_source_lines(
      session_id,candidate_id,session_version,source_change_seq,source_build_run_id,source_publication_id,
      source_ordinal,line_key,parent_line_key,split_suffix,timesheet_id,section,
      source_row_json,economic_key_json,contract_json,pay_channel_scope,refresh_scope_kind,status
    ) SELECT session_id,candidate_id,session_version,source_change_seq,source_build_run_id,
      v_source_publication_id,
      source_ordinal,line_key,parent_line_key,split_suffix,timesheet_id,section,
      source_row_json,economic_key_json,contract_json,pay_channel_scope,refresh_scope_kind,'CURRENT'
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=v_build_id
    ORDER BY source_ordinal;
      GET DIAGNOSTICS v_published_count=ROW_COUNT;
    END IF;
    SELECT md5(COALESCE(string_agg(md5(source_row_json::text),'' ORDER BY source_ordinal),''))
    INTO v_published_digest FROM public.banking_pay_workbench_candidate_source_lines
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT'
      AND source_build_run_id=v_build.source_build_run_id
      AND source_publication_id IS NOT DISTINCT FROM v_source_publication_id;
    IF v_published_count<>v_build.canonical_count OR v_published_digest IS DISTINCT FROM v_build.canonical_digest THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PUBLICATION_DIGEST_MISMATCH' USING ERRCODE='23514';
    END IF;
    UPDATE public.banking_pay_workbench_session_candidate_state SET status='READY',
      source_change_seq=v_build.source_change_seq,session_version=v_build.session_version,
      pending_job_id=NULL,last_error_json='{}'::jsonb,last_recomputed_at_utc=clock_timestamp(),
      updated_at_utc=clock_timestamp()
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id;
    UPDATE private.banking_pay_workbench_timesheet_scope_state state_row
    SET economic_state=CASE WHEN EXISTS(
        SELECT 1
        FROM (
          SELECT fact.economic_key_type,fact.economic_key_value,
            ROUND(SUM(COALESCE(fact.truth_ex_vat,0)),2) AS truth_ex_vat,
            ROUND(SUM(COALESCE(fact.baseline_ex_vat,0)),2) AS baseline_ex_vat,
            ROUND(SUM(COALESCE(fact.reserved_source_amount,0)),2) AS reserved_source_amount,
            bool_or(fact.finance_case_id IS NOT NULL) AS has_finance_case
          FROM private.banking_pay_workbench_economic_build_facts fact
          WHERE fact.build_id=v_build_id
            AND state_row.timesheet_id=ANY(fact.subject_timesheet_ids)
            AND fact.fact_family IN ('ENTITLEMENT_COMPONENT','RESERVATION_COMPONENT','FINANCE_CASE_IDENTITY','FINANCE_COMPONENT_IDENTITY')
          GROUP BY fact.economic_key_type,fact.economic_key_value
        ) authority
        WHERE authority.truth_ex_vat IS DISTINCT FROM authority.baseline_ex_vat
          OR authority.reserved_source_amount<>0 OR authority.has_finance_case
      ) THEN 'LIVE' ELSE 'CLOSED' END,
      evaluated_generation=state_row.dirty_generation,
      current_input_fingerprint=scope_row.captured_input_fingerprint,
      evaluated_input_fingerprint=scope_row.captured_input_fingerprint,
      current_build_id=NULL,last_evaluated_at_utc=clock_timestamp(),
      closed_at_utc=CASE WHEN EXISTS(
        SELECT 1
        FROM (
          SELECT fact.economic_key_type,fact.economic_key_value,
            ROUND(SUM(COALESCE(fact.truth_ex_vat,0)),2) AS truth_ex_vat,
            ROUND(SUM(COALESCE(fact.baseline_ex_vat,0)),2) AS baseline_ex_vat,
            ROUND(SUM(COALESCE(fact.reserved_source_amount,0)),2) AS reserved_source_amount,
            bool_or(fact.finance_case_id IS NOT NULL) AS has_finance_case
          FROM private.banking_pay_workbench_economic_build_facts fact
          WHERE fact.build_id=v_build_id
            AND state_row.timesheet_id=ANY(fact.subject_timesheet_ids)
            AND fact.fact_family IN ('ENTITLEMENT_COMPONENT','RESERVATION_COMPONENT','FINANCE_CASE_IDENTITY','FINANCE_COMPONENT_IDENTITY')
          GROUP BY fact.economic_key_type,fact.economic_key_value
        ) authority
        WHERE authority.truth_ex_vat IS DISTINCT FROM authority.baseline_ex_vat
          OR authority.reserved_source_amount<>0 OR authority.has_finance_case
      ) THEN NULL ELSE clock_timestamp() END,updated_at_utc=clock_timestamp()
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=v_build_id AND state_row.timesheet_id=scope_row.timesheet_id;
    UPDATE private.banking_pay_workbench_candidate_scope_registry SET initialisation_status='READY',
      evaluated_generation=dirty_generation,current_build_id=NULL,last_evaluated_at_utc=clock_timestamp(),
      initialised_at_utc=COALESCE(initialised_at_utc,clock_timestamp()),failure_json='{}'::jsonb,
      updated_at_utc=clock_timestamp() WHERE candidate_id=p_candidate_id;
    UPDATE private.banking_pay_workbench_economic_builds SET status='COMPLETE',private_stage='COMPLETE',
      publication_cursor_json=jsonb_build_object('cursor_kind','SOURCE_PUBLISH','cursor_version',1,
        'terminal',true,'published_count',v_published_count,'published_digest',v_published_digest),
      completed_at_utc=clock_timestamp(),cleanup_not_before_utc=clock_timestamp()+interval '7 days',
      updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','COMPLETE',
      'stage_status','COMPLETE','has_more',false,'continuation_enqueued',false,
      'next_action','COMPLETE','published_count',v_published_count,'published_digest',v_published_digest);
  END IF;

  IF v_stage='BUILD_CLEANUP' THEN
    v_cleanup_kind:=COALESCE(NULLIF(v_cursor->>'cleanup_kind',''),'CANONICAL_STAGE');
    IF v_build.status<>'CLEANING' OR v_build.cleanup_not_before_utc IS NULL
       OR clock_timestamp()<v_build.cleanup_not_before_utc
       OR v_registry.current_build_id IS NOT DISTINCT FROM v_build_id
       OR EXISTS(SELECT 1 FROM public.banking_pay_workbench_jobs cleanup_job
         WHERE cleanup_job.economic_build_id=v_build_id
           AND cleanup_job.id<>(SELECT job_id FROM private.banking_pay_workbench_stage_attempts WHERE id=v_attempt_id)
           AND cleanup_job.status IN ('QUEUED','RUNNING') LIMIT 1)
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts cleanup_attempt
         WHERE cleanup_attempt.build_id=v_build_id AND cleanup_attempt.id<>v_attempt_id
           AND cleanup_attempt.attempt_status='STARTED' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CLEANUP_BUILD_PROTECTED' USING ERRCODE='55006';
    END IF;
    IF v_cleanup_kind='CANONICAL_STAGE' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_canonical_stage_lines
        WHERE build_id=v_build_id ORDER BY source_ordinal LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_canonical_stage_lines row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='FACT_PAGES'; END IF;
    ELSIF v_cleanup_kind='FACT_PAGES' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_economic_build_fact_pages
        WHERE build_id=v_build_id ORDER BY id LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_economic_build_fact_pages row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='FACTS'; END IF;
    ELSIF v_cleanup_kind='FACTS' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_economic_build_facts
        WHERE build_id=v_build_id ORDER BY fact_family,natural_key LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_economic_build_facts row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='SCOPE'; END IF;
    ELSIF v_cleanup_kind='SCOPE' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id ORDER BY timesheet_id LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_economic_build_scope row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='ATTEMPTS'; END IF;
    ELSIF v_cleanup_kind='ATTEMPTS' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_stage_attempts
        WHERE build_id=v_build_id AND id<>v_attempt_id ORDER BY id LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_stage_attempts row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='HEADER_FINALISE'; END IF;
    ELSIF v_cleanup_kind='HEADER_FINALISE' THEN
      IF EXISTS(SELECT 1 FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_fact_pages WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_facts WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts
           WHERE build_id=v_build_id AND id<>v_attempt_id LIMIT 1) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CLEANUP_CHILDREN_REMAIN' USING ERRCODE='23514';
      END IF;
      v_cleanup_kind:='COMPLETE';
      v_cleanup_count:=0;
    ELSIF v_cleanup_kind<>'COMPLETE' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    v_next:=jsonb_build_object('cursor_kind','BUILD_CLEANUP','cursor_version',1,
      'build_id',v_build_id,'candidate_id',p_candidate_id,'cleanup_kind',v_cleanup_kind,
      'deleted_count',v_cleanup_count,'terminal',v_cleanup_kind='COMPLETE');
    UPDATE private.banking_pay_workbench_economic_builds SET cleanup_cursor_json=v_next,
      status=CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE status END,
      private_stage=CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE private_stage END,
      updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','BUILD_CLEANUP',
      'stage_status',CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE 'CLEANING' END,
      'has_more',v_cleanup_kind<>'COMPLETE','continuation_enqueued',false,
      'next_cursor_json',v_next,'next_action',CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE 'BUILD_CLEANUP' END,
      'deleted_count',v_cleanup_count);
  END IF;

  IF v_stage='BOOTSTRAP_DISCOVERY' THEN
    v_bootstrap_id:=NULLIF(v_cursor->>'bootstrap_id','')::uuid;
    v_bootstrap_stream:=upper(COALESCE(NULLIF(v_cursor->>'bootstrap_stream',''),v_registry.bootstrap_stream));
    v_bootstrap_last_key:=NULLIF(v_cursor->>'last_source_key','');
    IF v_bootstrap_id IS NULL OR v_bootstrap_id IS DISTINCT FROM v_registry.bootstrap_id
       OR v_registry.initialisation_status NOT IN ('DISCOVERING','CLASSIFYING') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_bootstrap_page_v1(
      source_key text PRIMARY KEY,
      timesheet_id uuid NULL
    ) ON COMMIT DROP;
    TRUNCATE pg_temp._bpay_wb_bootstrap_page_v1;

    IF v_bootstrap_stream='TIMESHEETS_TSFIN' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'TIMESHEET:'||timesheet_row.timesheet_id::text row_key,timesheet_row.timesheet_id
        FROM public.timesheets timesheet_row
        JOIN public.contracts contract_row ON contract_row.id=timesheet_row.contract_id
        WHERE contract_row.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'TSFIN:'||financial.id::text row_key,financial.timesheet_id
        FROM public.timesheets_financials financial
        WHERE financial.candidate_id=p_candidate_id AND financial.is_current
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='BATCH_ARTIFACTS';
    ELSIF v_bootstrap_stream='BATCH_ARTIFACTS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'ITEM:'||item.id::text row_key,item.timesheet_id
        FROM public.pay_batch_items item
        JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=item.pay_batch_candidate_id
        WHERE batch_candidate.candidate_id=p_candidate_id AND item.timesheet_id IS NOT NULL
        UNION ALL
        SELECT 'SNAPSHOT:'||snapshot.id::text,snapshot.timesheet_id
        FROM public.pay_batch_timesheet_snapshots snapshot
        WHERE snapshot.candidate_id=p_candidate_id
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='CORRECTIONS';
    ELSIF v_bootstrap_stream='CORRECTIONS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'CORRECTION:'||correction.id::text,correction.timesheet_id
      FROM public.pay_payment_correction_items correction
      WHERE correction.candidate_id=p_candidate_id AND correction.timesheet_id IS NOT NULL
        AND (v_bootstrap_last_key IS NULL OR 'CORRECTION:'||correction.id::text>v_bootstrap_last_key)
      ORDER BY correction.id LIMIT 251;
      v_bootstrap_next_stream:='FINANCE';
    ELSIF v_bootstrap_stream='FINANCE' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'ADVANCE:'||finance_case.id::text row_key,finance_case.linked_timesheet_id timesheet_id
        FROM public.pay_advances finance_case WHERE finance_case.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'COMPONENT:'||component.id::text,component.linked_timesheet_id
        FROM public.pay_finance_case_components component WHERE component.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'EVENT:'||event.id::text,component.linked_timesheet_id
        FROM public.pay_finance_case_events event
        JOIN public.pay_advances finance_case ON finance_case.id=event.finance_case_id
        LEFT JOIN public.pay_finance_case_components component ON component.id=event.finance_component_id
        WHERE finance_case.candidate_id=p_candidate_id
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='RESERVATIONS';
    ELSIF v_bootstrap_stream='RESERVATIONS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'RESERVATION:'||reservation.id::text,COALESCE(item.timesheet_id,component.linked_timesheet_id)
      FROM public.pay_advance_reservations reservation
      LEFT JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=reservation.pay_batch_candidate_id
      LEFT JOIN public.pay_batch_items item ON item.id=reservation.pay_batch_item_id
      LEFT JOIN public.pay_finance_case_components component ON component.id=reservation.finance_component_id
      WHERE COALESCE(batch_candidate.candidate_id,component.candidate_id)=p_candidate_id
        AND (v_bootstrap_last_key IS NULL OR 'RESERVATION:'||reservation.id::text>v_bootstrap_last_key)
      ORDER BY reservation.id LIMIT 251;
      v_bootstrap_next_stream:='OVERRIDES_ADJUSTMENTS';
    ELSIF v_bootstrap_stream='OVERRIDES_ADJUSTMENTS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'OVERRIDE:'||override_row.id::text row_key,override_row.timesheet_id
        FROM public.timesheet_payment_overrides override_row WHERE override_row.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'ADJUSTMENT:'||adjustment.id::text,adjustment.timesheet_id
        FROM public.ts_pay_adjustments adjustment WHERE adjustment.candidate_id=p_candidate_id
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='SNOOZES';
    ELSIF v_bootstrap_stream='SNOOZES' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'SNOOZE:'||snooze.id::text,snooze.timesheet_id
      FROM public.pay_item_snoozes snooze
      WHERE snooze.candidate_id=p_candidate_id AND snooze.timesheet_id IS NOT NULL
        AND (v_bootstrap_last_key IS NULL OR 'SNOOZE:'||snooze.id::text>v_bootstrap_last_key)
      ORDER BY snooze.id LIMIT 251;
      v_bootstrap_next_stream:='CURRENT_SOURCE';
    ELSIF v_bootstrap_stream='CURRENT_SOURCE' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'SOURCE:'||source_row.id::text,source_row.timesheet_id
      FROM public.banking_pay_workbench_candidate_source_lines source_row
      WHERE source_row.candidate_id=p_candidate_id AND source_row.status IN ('CURRENT','DIRTY')
        AND source_row.timesheet_id IS NOT NULL
        AND (v_bootstrap_last_key IS NULL OR 'SOURCE:'||source_row.id::text>v_bootstrap_last_key)
      ORDER BY source_row.id LIMIT 251;
      v_bootstrap_next_stream:='SCOPE_CLOSURE';
    ELSIF v_bootstrap_stream='CLASSIFY_UNITS' THEN
      v_bootstrap_classification_phase:=upper(COALESCE(NULLIF(v_cursor->>'classification_phase',''),'EVIDENCE'));
      v_bootstrap_unit_key:=NULLIF(v_cursor->>'dependency_unit_key','');
      v_bootstrap_last_unit_key:=NULLIF(v_cursor->>'last_dependency_unit_key','');
      v_bootstrap_last_ordinal:=GREATEST(COALESCE((v_cursor->>'last_stable_ordinal')::bigint,0),0);
      v_bootstrap_unit_relevant:=COALESCE((v_cursor->>'unit_financially_relevant')::boolean,false);
      v_bootstrap_raw_current_count:=GREATEST(COALESCE((v_cursor->>'raw_current_occurrence_count')::bigint,0),0);
      v_bootstrap_resolved_current_count:=GREATEST(COALESCE((v_cursor->>'resolved_current_occurrence_count')::bigint,0),0);
      v_bootstrap_raw_baseline_count:=GREATEST(COALESCE((v_cursor->>'raw_baseline_occurrence_count')::bigint,0),0);
      v_bootstrap_resolved_baseline_count:=GREATEST(COALESCE((v_cursor->>'resolved_baseline_occurrence_count')::bigint,0),0);

      IF v_bootstrap_classification_phase='EVIDENCE' THEN
        IF v_bootstrap_unit_key IS NULL THEN
          SELECT scope_row.dependency_unit_key INTO v_bootstrap_unit_key
          FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=v_build_id AND scope_row.closure_status='SEALED'
            AND (v_bootstrap_last_unit_key IS NULL
              OR scope_row.dependency_unit_key>v_bootstrap_last_unit_key)
          ORDER BY scope_row.dependency_unit_key LIMIT 1;
        END IF;
        IF v_bootstrap_unit_key IS NULL THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','RESET_FACT_PAGES',
            'last_source_key',NULL,'build_id',v_build_id,'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
          UPDATE private.banking_pay_workbench_candidate_scope_registry
          SET bootstrap_stream='RESET_FACT_PAGES',bootstrap_cursor_json=v_next,
              updated_at_utc=clock_timestamp()
          WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
          -- The sealed seed cursor remains immutable. Bootstrap continuation is
          -- owned by the registry's dedicated bootstrap_cursor_json.
          UPDATE private.banking_pay_workbench_economic_builds
          SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
          RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
            'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
            'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
            'next_action','BOOTSTRAP_DISCOVERY','classification_phase','RESET_FACT_PAGES');
        END IF;

        INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1(source_key,timesheet_id)
        SELECT lpad(scope_row.stable_ordinal::text,20,'0'),scope_row.timesheet_id
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=v_build_id
          AND scope_row.dependency_unit_key=v_bootstrap_unit_key
          AND scope_row.stable_ordinal>v_bootstrap_last_ordinal
        ORDER BY scope_row.stable_ordinal LIMIT 26;
        SELECT count(*)>25 INTO v_bootstrap_has_more FROM pg_temp._bpay_wb_bootstrap_page_v1;
        SELECT count(*)::integer,COALESCE(max(source_key)::bigint,v_bootstrap_last_ordinal)
        INTO v_bootstrap_page_count,v_bootstrap_last_ordinal
        FROM (SELECT source_key FROM pg_temp._bpay_wb_bootstrap_page_v1
          ORDER BY source_key LIMIT 25) page;
        SELECT EXISTS(
          SELECT 1
          FROM (SELECT timesheet_id FROM pg_temp._bpay_wb_bootstrap_page_v1
            ORDER BY source_key LIMIT 25) page
          WHERE EXISTS(SELECT 1 FROM public.timesheets_financials financial
              WHERE financial.timesheet_id=page.timesheet_id
                AND financial.candidate_id=p_candidate_id AND financial.is_current
                AND financial.paid_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines source_row
              WHERE source_row.candidate_id=p_candidate_id
                AND source_row.timesheet_id=page.timesheet_id
                AND source_row.status IN ('CURRENT','DIRTY'))
            OR EXISTS(SELECT 1 FROM public.pay_advances finance_case
              WHERE finance_case.candidate_id=p_candidate_id
                AND finance_case.linked_timesheet_id=page.timesheet_id
                AND finance_case.cleared_at_utc IS NULL
                AND finance_case.written_off_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.pay_finance_case_components component
              WHERE component.candidate_id=p_candidate_id
                AND component.linked_timesheet_id=page.timesheet_id
                AND component.closed_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.timesheet_payment_overrides override_row
              WHERE override_row.candidate_id=p_candidate_id
                AND override_row.timesheet_id=page.timesheet_id
                AND override_row.cleared_at_utc IS NULL
                AND override_row.consumed_at_utc IS NULL
                AND override_row.consumed_by_pay_batch_id IS NULL)
            OR EXISTS(SELECT 1 FROM public.ts_pay_adjustments adjustment
              WHERE adjustment.candidate_id=p_candidate_id
                AND adjustment.timesheet_id=page.timesheet_id
                AND adjustment.paid_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.pay_item_snoozes snooze
              WHERE snooze.candidate_id=p_candidate_id
                AND snooze.timesheet_id=page.timesheet_id
                AND snooze.cleared_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.pay_advance_reservations reservation
              LEFT JOIN public.pay_batch_items item ON item.id=reservation.pay_batch_item_id
              LEFT JOIN public.pay_finance_case_components component
                ON component.id=reservation.finance_component_id
              WHERE COALESCE(item.timesheet_id,component.linked_timesheet_id)=page.timesheet_id
                AND reservation.status NOT IN ('RELEASED','SETTLED'))
            OR EXISTS(
              SELECT 1
              FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
                v_build_id,v_bootstrap_unit_key) component
              WHERE component.timesheet_id=page.timesheet_id
                AND (ROUND(COALESCE(component.truth_ex_vat,0),2)
                      IS DISTINCT FROM ROUND(COALESCE(component.baseline_ex_vat,0),2)
                  OR ROUND(COALESCE(component.truth_inc_vat,0),2)
                      IS DISTINCT FROM ROUND(COALESCE(component.baseline_inc_vat,0),2))
            )
            OR (
              NOT EXISTS(
                SELECT 1
                FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
                  v_build_id,v_bootstrap_unit_key) component
                WHERE component.timesheet_id=page.timesheet_id
              )
              AND (
                EXISTS(SELECT 1
                  FROM private.banking_pay_workbench_economic_build_facts fact
                  WHERE fact.build_id=v_build_id AND fact.timesheet_id=page.timesheet_id
                    AND fact.fact_family IN ('LIVE_ENTITLEMENT_INPUT',
                      'FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
                    AND fact.source_relation<>'UNIT_PROJECTION')
                OR EXISTS(SELECT 1 FROM public.timesheets_financials financial
                  WHERE financial.timesheet_id=page.timesheet_id
                    AND financial.candidate_id=p_candidate_id AND financial.is_current
                    AND ABS(COALESCE(financial.total_pay_ex_vat,0))>0.005)
                OR EXISTS(SELECT 1 FROM public.timesheet_pay_state state
                  WHERE state.timesheet_id=page.timesheet_id
                    AND COALESCE(state.last_settled_snapshot_json,'{}'::jsonb)<>'{}'::jsonb)
              )
            )
          LIMIT 1
        ) INTO v_bootstrap_page_relevant;
        SELECT
          COALESCE(SUM((page.cursor_end_json->>'raw_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family='LIVE_ENTITLEMENT_INPUT'),0),
          COALESCE(SUM((page.cursor_end_json->>'resolved_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family='LIVE_ENTITLEMENT_INPUT'),0),
          COALESCE(SUM((page.cursor_end_json->>'raw_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')),0),
          COALESCE(SUM((page.cursor_end_json->>'resolved_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')),0),
          COUNT(*)=3
            AND BOOL_AND(page.expected_source_count IS NOT NULL
              AND page.expected_source_count=(page.cursor_end_json->>'raw_physical_source_count')::integer
              AND (page.cursor_end_json->>'raw_physical_source_count')::bigint=
                (page.cursor_end_json->>'resolved_physical_source_count')::bigint
              AND (page.cursor_end_json->>'failed_physical_source_count')::bigint=0
              AND ROUND((page.cursor_end_json->>'raw_physical_amount_ex_vat')::numeric,2)=
                ROUND((page.cursor_end_json->>'resolved_physical_amount_ex_vat')::numeric,2)
              AND COALESCE((page.cursor_end_json->>'source_exhausted')::boolean,false))
        INTO v_bootstrap_raw_current_count,v_bootstrap_resolved_current_count,
          v_bootstrap_raw_baseline_count,v_bootstrap_resolved_baseline_count,
          v_bootstrap_evidence_complete
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id AND page.dependency_unit_key=v_bootstrap_unit_key
          AND page.fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
          AND page.status='COMPLETED' AND page.is_family_final;
        v_bootstrap_unit_relevant:=v_bootstrap_unit_relevant OR v_bootstrap_page_relevant;
        v_bootstrap_evidence_complete:=COALESCE(v_bootstrap_evidence_complete,false)
          AND v_bootstrap_raw_current_count=v_bootstrap_resolved_current_count
          AND v_bootstrap_raw_baseline_count=v_bootstrap_resolved_baseline_count;
        IF v_bootstrap_has_more THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','EVIDENCE','last_dependency_unit_key',v_bootstrap_last_unit_key,
            'dependency_unit_key',v_bootstrap_unit_key,'last_stable_ordinal',v_bootstrap_last_ordinal,
            'unit_financially_relevant',v_bootstrap_unit_relevant,
            'raw_current_occurrence_count',v_bootstrap_raw_current_count,
            'resolved_current_occurrence_count',v_bootstrap_resolved_current_count,
            'raw_baseline_occurrence_count',v_bootstrap_raw_baseline_count,
            'resolved_baseline_occurrence_count',v_bootstrap_resolved_baseline_count,
            'evidence_complete',v_bootstrap_evidence_complete,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        ELSE
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','APPLY','last_dependency_unit_key',v_bootstrap_last_unit_key,
            'dependency_unit_key',v_bootstrap_unit_key,'last_stable_ordinal',0,
            'unit_financially_relevant',v_bootstrap_unit_relevant,
            'raw_current_occurrence_count',v_bootstrap_raw_current_count,
            'resolved_current_occurrence_count',v_bootstrap_resolved_current_count,
            'raw_baseline_occurrence_count',v_bootstrap_raw_baseline_count,
            'resolved_baseline_occurrence_count',v_bootstrap_resolved_baseline_count,
            'evidence_complete',v_bootstrap_evidence_complete,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        END IF;
      ELSIF v_bootstrap_classification_phase='APPLY' THEN
        IF v_bootstrap_unit_key IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
        END IF;
        SELECT COUNT(*)=3 AND BOOL_AND(
            page.expected_source_count IS NOT NULL
            AND page.expected_source_count=(page.cursor_end_json->>'raw_physical_source_count')::integer
            AND (page.cursor_end_json->>'raw_physical_source_count')::bigint=
              (page.cursor_end_json->>'resolved_physical_source_count')::bigint
            AND (page.cursor_end_json->>'failed_physical_source_count')::bigint=0
            AND ROUND((page.cursor_end_json->>'raw_physical_amount_ex_vat')::numeric,2)=
              ROUND((page.cursor_end_json->>'resolved_physical_amount_ex_vat')::numeric,2)
            AND COALESCE((page.cursor_end_json->>'source_exhausted')::boolean,false))
        INTO v_bootstrap_evidence_complete
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id AND page.dependency_unit_key=v_bootstrap_unit_key
          AND page.fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
          AND page.status='COMPLETED' AND page.is_family_final;
        v_bootstrap_evidence_complete:=COALESCE(v_bootstrap_evidence_complete,false)
          AND COALESCE((v_cursor->>'evidence_complete')::boolean,false)
          AND v_bootstrap_raw_current_count=v_bootstrap_resolved_current_count
          AND v_bootstrap_raw_baseline_count=v_bootstrap_resolved_baseline_count
          AND NOT EXISTS(
            SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=v_build_id
              AND scope_row.dependency_unit_key=v_bootstrap_unit_key
              AND (scope_row.closure_status<>'SEALED'
                OR NOT scope_row.required_fact_families <@ scope_row.completed_fact_families))
          AND NOT EXISTS(
            SELECT 1 FROM private.banking_pay_workbench_economic_build_facts fact
            WHERE fact.build_id=v_build_id AND fact.dependency_unit_key=v_bootstrap_unit_key
              AND NULLIF(BTRIM(fact.source_payload_json->>'resolution_failure'),'') IS NOT NULL);
        IF NOT v_bootstrap_evidence_complete THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CLOSED_AUTHORITY_UNPROVED'
            USING ERRCODE='23514';
        END IF;
        INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1(source_key,timesheet_id)
        SELECT lpad(scope_row.stable_ordinal::text,20,'0'),scope_row.timesheet_id
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=v_build_id
          AND scope_row.dependency_unit_key=v_bootstrap_unit_key
          AND scope_row.stable_ordinal>v_bootstrap_last_ordinal
        ORDER BY scope_row.stable_ordinal LIMIT 26;
        SELECT count(*)>25 INTO v_bootstrap_has_more FROM pg_temp._bpay_wb_bootstrap_page_v1;
        SELECT count(*)::integer,COALESCE(max(source_key)::bigint,v_bootstrap_last_ordinal)
        INTO v_bootstrap_page_count,v_bootstrap_last_ordinal
        FROM (SELECT source_key FROM pg_temp._bpay_wb_bootstrap_page_v1
          ORDER BY source_key LIMIT 25) page;
        UPDATE private.banking_pay_workbench_timesheet_scope_state state_row SET
          economic_state=CASE WHEN v_bootstrap_unit_relevant THEN 'DIRTY' ELSE 'CLOSED' END,
          evaluated_generation=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.evaluated_generation ELSE state_row.dirty_generation END,
          current_input_fingerprint=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.current_input_fingerprint ELSE scope_row.captured_input_fingerprint END,
          evaluated_input_fingerprint=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.evaluated_input_fingerprint ELSE scope_row.captured_input_fingerprint END,
          last_dirty_reason=CASE WHEN v_bootstrap_unit_relevant
            THEN 'LEGACY_ACTIVE_UNIT_CLASSIFIED' ELSE 'LEGACY_CLOSED_UNIT_CLASSIFIED' END,
          last_evaluated_at_utc=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.last_evaluated_at_utc ELSE clock_timestamp() END,
          closed_at_utc=CASE WHEN v_bootstrap_unit_relevant THEN NULL ELSE clock_timestamp() END,
          current_build_id=CASE WHEN v_bootstrap_unit_relevant THEN v_build_id ELSE NULL END,
          updated_at_utc=clock_timestamp()
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        JOIN (SELECT timesheet_id FROM pg_temp._bpay_wb_bootstrap_page_v1
          ORDER BY source_key LIMIT 25) page ON page.timesheet_id=scope_row.timesheet_id
        WHERE scope_row.build_id=v_build_id
          AND state_row.timesheet_id=scope_row.timesheet_id
          AND state_row.dirty_generation<=v_build.captured_candidate_generation;
        IF v_bootstrap_has_more THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','APPLY','last_dependency_unit_key',v_bootstrap_last_unit_key,
            'dependency_unit_key',v_bootstrap_unit_key,'last_stable_ordinal',v_bootstrap_last_ordinal,
            'unit_financially_relevant',v_bootstrap_unit_relevant,
            'raw_current_occurrence_count',v_bootstrap_raw_current_count,
            'resolved_current_occurrence_count',v_bootstrap_resolved_current_count,
            'raw_baseline_occurrence_count',v_bootstrap_raw_baseline_count,
            'resolved_baseline_occurrence_count',v_bootstrap_resolved_baseline_count,
            'evidence_complete',v_bootstrap_evidence_complete,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        ELSE
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','EVIDENCE','last_dependency_unit_key',v_bootstrap_unit_key,
            'dependency_unit_key',NULL,'last_stable_ordinal',0,
            'unit_financially_relevant',false,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        END IF;
      ELSE
        RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
      END IF;
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET initialisation_status='CLASSIFYING',bootstrap_stream='CLASSIFY_UNITS',
          bootstrap_cursor_json=v_next,
          bootstrap_rows_seen=bootstrap_rows_seen+v_bootstrap_page_count,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      -- Do not replace the terminal seed-scope cursor during classification.
      UPDATE private.banking_pay_workbench_economic_builds
      SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','classification_phase',
        v_next->>'classification_phase','page_source_count',v_bootstrap_page_count);
    ELSIF v_bootstrap_stream='RESET_FACT_PAGES' THEN
      WITH doomed AS (
        SELECT page.ctid
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id
        ORDER BY page.dependency_unit_key,page.fact_family,page.page_number
        LIMIT 250
      ) DELETE FROM private.banking_pay_workbench_economic_build_fact_pages page
        USING doomed WHERE page.ctid=doomed.ctid;
      GET DIAGNOSTICS v_bootstrap_reset_count=ROW_COUNT;
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',
        CASE WHEN v_bootstrap_reset_count<250 THEN 'RESET_FACTS' ELSE 'RESET_FACT_PAGES' END,
        'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET bootstrap_stream=v_next->>'bootstrap_stream',bootstrap_cursor_json=v_next,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      UPDATE private.banking_pay_workbench_economic_builds
      SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','deleted_count',v_bootstrap_reset_count);
    ELSIF v_bootstrap_stream='RESET_FACTS' THEN
      WITH doomed AS (
        SELECT fact.ctid
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id
        ORDER BY fact.fact_family,fact.natural_key LIMIT 250
      ) DELETE FROM private.banking_pay_workbench_economic_build_facts fact
        USING doomed WHERE fact.ctid=doomed.ctid;
      GET DIAGNOSTICS v_bootstrap_reset_count=ROW_COUNT;
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',
        CASE WHEN v_bootstrap_reset_count<250 THEN 'RESET_SCOPE' ELSE 'RESET_FACTS' END,
        'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET bootstrap_stream=v_next->>'bootstrap_stream',bootstrap_cursor_json=v_next,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      -- Reset progress belongs to bootstrap_cursor_json until the atomic
      -- seed-seal reset below clears both the digest and sealed timestamp.
      UPDATE private.banking_pay_workbench_economic_builds
      SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','deleted_count',v_bootstrap_reset_count);
    ELSIF v_bootstrap_stream='RESET_SCOPE' THEN
      WITH doomed AS (
        SELECT scope_row.ctid
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=v_build_id ORDER BY scope_row.stable_ordinal LIMIT 250
      ) DELETE FROM private.banking_pay_workbench_economic_build_scope scope_row
        USING doomed WHERE scope_row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_bootstrap_reset_count=ROW_COUNT;
      IF v_bootstrap_reset_count>=250 THEN
        v_next:=v_cursor;
        UPDATE private.banking_pay_workbench_candidate_scope_registry
        SET bootstrap_cursor_json=v_next,updated_at_utc=clock_timestamp()
        WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
        RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
          'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
          'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
          'next_action','BOOTSTRAP_DISCOVERY','deleted_count',v_bootstrap_reset_count);
      END IF;
      SELECT EXISTS(
        SELECT 1 FROM private.banking_pay_workbench_timesheet_scope_state
        WHERE candidate_id=p_candidate_id AND economic_state='DIRTY' LIMIT 1
      ) INTO v_bootstrap_has_dirty;
      IF NOT v_bootstrap_has_dirty
         AND v_registry.dirty_generation=v_build.captured_candidate_generation
         AND v_registry.current_source_change_seq=v_build.source_change_seq THEN
        UPDATE private.banking_pay_workbench_candidate_scope_registry SET
          initialisation_status='READY',evaluated_generation=dirty_generation,current_build_id=NULL,
          last_evaluated_at_utc=clock_timestamp(),initialised_at_utc=clock_timestamp(),
          bootstrap_stream='COMPLETE',bootstrap_cursor_json=jsonb_build_object(
            'cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,'terminal',true,
            'bootstrap_id',v_bootstrap_id),failure_json='{}'::jsonb,updated_at_utc=clock_timestamp()
        WHERE candidate_id=p_candidate_id;
        UPDATE private.banking_pay_workbench_economic_builds SET
          status='COMPLETE',private_stage='COMPLETE',scope_count=0,dependency_node_count=0,
          dependency_edge_count=0,tagged_edge_count=0,unit_count=0,row_seal_count=0,
          last_stable_ordinal=0,scope_digest=md5(''),dependency_digest=md5(''),
          pre_sync_digest=md5(''),post_sync_digest=md5(''),canonical_digest=md5(''),
          attestation_json=jsonb_build_object('bootstrap_id',v_bootstrap_id,
            'no_active_scope',true,'classification_dependency_closed',true),
          reconciled_at_utc=clock_timestamp(),completed_at_utc=clock_timestamp(),
          cleanup_not_before_utc=clock_timestamp()+interval '7 days',
          updated_at_utc=clock_timestamp() WHERE id=v_build_id;
        RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','COMPLETE',
          'stage_status','COMPLETE','has_more',false,'continuation_enqueued',false,
          'next_action','COMPLETE','classification_dependency_closed',true);
      END IF;
      v_next:=jsonb_build_object('cursor_kind','SCOPE_SELECT','cursor_version',1,
        'seed_family','ACTIVE_STATE','last_source_key',NULL,'build_id',v_build_id,
        'candidate_id',p_candidate_id,'captured_candidate_generation',v_registry.dirty_generation,
        'captured_source_change_seq',v_registry.current_source_change_seq,'processed_source_rows',0);
      UPDATE private.banking_pay_workbench_economic_builds SET
        captured_candidate_generation=v_registry.dirty_generation,
        source_change_seq=v_registry.current_source_change_seq,status='COLLECTING',
        private_stage='PREPARE_SCOPE',scope_cursor_json=v_next,closure_cursor_json='{}'::jsonb,
        fact_cursor_json='{}'::jsonb,seed_scope_count=0,scope_count=0,
        dependency_node_count=0,dependency_edge_count=0,tagged_edge_count=0,
        unit_count=0,row_seal_count=0,last_stable_ordinal=0,fact_count=0,
        seed_scope_digest=NULL,dependency_edge_stream_digest=NULL,
        dependency_edge_stream_complete=false,dependency_edge_stream_terminal_key_json='{}'::jsonb,
        edge_tag_digest=NULL,edge_tag_stream_complete=false,
        edge_tag_stream_terminal_key_json='{}'::jsonb,unit_digest=NULL,
        sealed_fingerprint_digest=NULL,scope_digest=NULL,dependency_digest=NULL,
        seed_scope_sealed_at_utc=NULL,dependency_closure_sealed_at_utc=NULL,
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'bootstrap_active_reconciliation',true,
          'bootstrap_active_reconciliation_started_at_utc',statement_timestamp()),
        updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      UPDATE private.banking_pay_workbench_candidate_scope_registry SET
        initialisation_status='CLASSIFYING',bootstrap_stream='ACTIVE_RECONCILIATION',
        bootstrap_cursor_json=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY',
          'cursor_version',1,'terminal',true,'bootstrap_id',v_bootstrap_id),
        updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','PREPARE_SCOPE','stage_status','PREPARING','has_more',true,
        'continuation_enqueued',false,'next_cursor_json',v_next,'next_action','PREPARE_SCOPE');
    ELSE
      RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;

    SELECT count(*)>250 INTO v_bootstrap_has_more FROM pg_temp._bpay_wb_bootstrap_page_v1;
    SELECT count(*)::integer,max(source_key) INTO v_bootstrap_page_count,v_bootstrap_last_key
    FROM (SELECT source_key FROM pg_temp._bpay_wb_bootstrap_page_v1 ORDER BY source_key LIMIT 250) page;

    WITH discovered AS (
      SELECT DISTINCT page.timesheet_id
      FROM (SELECT * FROM pg_temp._bpay_wb_bootstrap_page_v1
        ORDER BY source_key LIMIT 250) page
      JOIN public.timesheets timesheet_row ON timesheet_row.timesheet_id=page.timesheet_id
      WHERE page.timesheet_id IS NOT NULL
    ), inserted AS (
      INSERT INTO private.banking_pay_workbench_timesheet_scope_state(
        timesheet_id,candidate_id,economic_state,dirty_generation,last_dirty_reason,
        current_build_id,registered_at_utc,last_dirtied_at_utc,updated_at_utc
      ) SELECT timesheet_id,p_candidate_id,'DIRTY',v_build.captured_candidate_generation,
        'LEGACY_BOOTSTRAP_DISCOVERY',v_build_id,clock_timestamp(),clock_timestamp(),clock_timestamp()
      FROM discovered
      ON CONFLICT(timesheet_id) DO UPDATE SET
        candidate_id=EXCLUDED.candidate_id,economic_state='DIRTY',
        dirty_generation=GREATEST(private.banking_pay_workbench_timesheet_scope_state.dirty_generation,
          EXCLUDED.dirty_generation),
        last_dirty_reason='LEGACY_BOOTSTRAP_DISCOVERY',current_build_id=v_build_id,
        last_dirtied_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp()
      RETURNING (xmax=0) newly_inserted
    ) SELECT count(*) FILTER(WHERE newly_inserted)::integer
      INTO v_bootstrap_registered FROM inserted;

    IF v_bootstrap_has_more THEN
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',v_bootstrap_stream,
        'last_source_key',v_bootstrap_last_key,'build_id',v_build_id,
        'candidate_id',p_candidate_id,'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
    ELSIF v_bootstrap_next_stream='SCOPE_CLOSURE' THEN
      v_next:=jsonb_build_object('cursor_kind','SCOPE_SELECT','cursor_version',1,
        'seed_family','ACTIVE_STATE','last_source_key',NULL,'build_id',v_build_id,
        'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,'processed_source_rows',0);
      UPDATE private.banking_pay_workbench_economic_builds SET
        private_stage='PREPARE_SCOPE',scope_cursor_json=v_next,updated_at_utc=clock_timestamp()
      WHERE id=v_build_id AND private_stage='BOOTSTRAP_DISCOVERY';
      UPDATE private.banking_pay_workbench_candidate_scope_registry SET
        initialisation_status='CLASSIFYING',bootstrap_stream='DEPENDENCY_CLOSURE',
        bootstrap_cursor_json=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY',
          'cursor_version',1,'terminal',true,'bootstrap_id',v_bootstrap_id,
          'next_stage','PREPARE_SCOPE'),
        bootstrap_rows_seen=bootstrap_rows_seen+v_bootstrap_page_count,
        bootstrap_timesheets_registered=bootstrap_timesheets_registered+v_bootstrap_registered,
        updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','PREPARE_SCOPE',
        'stage_status','CLASSIFYING','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',v_next,'next_action','PREPARE_SCOPE',
        'page_source_count',v_bootstrap_page_count,
        'timesheets_registered',v_bootstrap_registered);
    ELSE
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',v_bootstrap_next_stream,
        'last_source_key',NULL,'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
    END IF;

    UPDATE private.banking_pay_workbench_candidate_scope_registry SET
      initialisation_status='DISCOVERING',
      bootstrap_stream=COALESCE(v_next->>'bootstrap_stream',bootstrap_stream),
      bootstrap_cursor_json=v_next,
      bootstrap_rows_seen=bootstrap_rows_seen+v_bootstrap_page_count,
      bootstrap_timesheets_registered=bootstrap_timesheets_registered+v_bootstrap_registered,
      updated_at_utc=clock_timestamp()
    WHERE candidate_id=p_candidate_id;
    UPDATE private.banking_pay_workbench_economic_builds SET scope_cursor_json=v_next,
      updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','BOOTSTRAP_DISCOVERY',
      'stage_status','DISCOVERING',
      'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
      'next_action','BOOTSTRAP_DISCOVERY','page_source_count',v_bootstrap_page_count,
      'timesheets_registered',v_bootstrap_registered);
  END IF;
  RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
END;
$function$;

-- private.pay_workbench_canonical_component_core_v1(jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_canonical_component_core_v1(p_component_json jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT CASE
    WHEN jsonb_typeof(COALESCE(p_component_json,'null'::jsonb))<>'object' THEN NULL::jsonb
    ELSE jsonb_strip_nulls(jsonb_build_object(
      'component_key_type',UPPER(NULLIF(BTRIM(p_component_json->>'component_key_type'),'')),
      'component_key_value',NULLIF(BTRIM(p_component_json->>'component_key_value'),''),
      'component_amount_ex_vat',CASE
        WHEN COALESCE(p_component_json->>'component_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN to_jsonb(ROUND((p_component_json->>'component_amount_ex_vat')::numeric,2))
        ELSE NULL::jsonb END,
      'authoritative_truth_ex_vat',CASE
        WHEN COALESCE(p_component_json->>'authoritative_truth_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN to_jsonb(ROUND((p_component_json->>'authoritative_truth_ex_vat')::numeric,2))
        ELSE NULL::jsonb END,
      'authoritative_baseline_ex_vat',CASE
        WHEN COALESCE(p_component_json->>'authoritative_baseline_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN to_jsonb(ROUND((p_component_json->>'authoritative_baseline_ex_vat')::numeric,2))
        ELSE NULL::jsonb END,
      'authoritative_reserved_ex_vat',CASE
        WHEN COALESCE(p_component_json->>'authoritative_reserved_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN to_jsonb(ROUND((p_component_json->>'authoritative_reserved_ex_vat')::numeric,2))
        ELSE NULL::jsonb END,
      'authoritative_outstanding_ex_vat',CASE
        WHEN COALESCE(p_component_json->>'authoritative_outstanding_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN to_jsonb(ROUND((p_component_json->>'authoritative_outstanding_ex_vat')::numeric,2))
        ELSE NULL::jsonb END,
      'overpayment_component_authority',NULLIF(BTRIM(p_component_json->>'overpayment_component_authority'),''),
      'source_pay_method',UPPER(NULLIF(BTRIM(p_component_json->>'source_pay_method'),'')),
      'source_family_key',NULLIF(BTRIM(p_component_json->>'source_family_key'),''),
      'source_basis_identity',jsonb_strip_nulls(jsonb_build_object(
        'build_id',NULLIF(BTRIM(p_component_json#>>'{source_basis_json,build_id}'),''),
        'linked_timesheet_id',COALESCE(
          NULLIF(BTRIM(p_component_json#>>'{source_basis_json,linked_timesheet_id}'),''),
          NULLIF(BTRIM(p_component_json#>>'{source_basis_json,timesheet_id}'),'')),
        'component_key_type',UPPER(NULLIF(BTRIM(
          p_component_json#>>'{source_basis_json,component_key_type}'),'')),
        'component_key_value',NULLIF(BTRIM(
          p_component_json#>>'{source_basis_json,component_key_value}'),''),
        'authority',NULLIF(BTRIM(p_component_json#>>'{source_basis_json,authority}'),'')
      ))
    ))
  END;
$function$;

-- private.pay_workbench_correction_dirty_context_set_v1(uuid,uuid,uuid[],text,text,jsonb,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_correction_dirty_context_set_v1(p_correction_request_id uuid, p_pay_batch_id uuid, p_candidate_ids uuid[], p_lifecycle_phase text, p_policy_x_boundary text, p_pre_request_authorities_json jsonb DEFAULT '{}'::jsonb, p_operation_id uuid DEFAULT NULL::uuid, p_work_item_id uuid DEFAULT NULL::uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_phase text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_lifecycle_phase,'')));
  v_boundary text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_policy_x_boundary,'')));
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_context_count integer := 0;
BEGIN
  IF p_correction_request_id IS NULL
     OR p_pay_batch_id IS NULL
     OR v_phase NOT IN (
       'REQUEST_PREPARE','REQUEST_START','FINANCIAL_PAGE_START',
       'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
     )
     OR v_boundary NOT IN ('POST_DRAFT_FROZEN_EVIDENCE','PRE_DRAFT_LIVE_TRUTH')
     OR pg_catalog.jsonb_typeof(COALESCE(p_pre_request_authorities_json,'{}'::jsonb)) <> 'object'
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CORRECTION_DIRTY_CONTEXT_INVALID'
      USING ERRCODE='22023', DETAIL=pg_catalog.jsonb_build_object(
        'code','PAY_WORKBENCH_CORRECTION_DIRTY_CONTEXT_INVALID',
        'lifecycle_phase',v_phase,
        'policy_x_boundary',v_boundary
      )::text;
  END IF;

  SELECT COALESCE(pg_catalog.array_agg(DISTINCT candidate_id ORDER BY candidate_id),ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM pg_catalog.unnest(COALESCE(p_candidate_ids,ARRAY[]::uuid[])) AS candidate_scope(candidate_id)
  WHERE candidate_scope.candidate_id IS NOT NULL;

  IF pg_catalog.cardinality(v_candidate_ids)=0
     OR pg_catalog.cardinality(v_candidate_ids)>1000 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CORRECTION_DIRTY_CONTEXT_SCOPE_INVALID'
      USING ERRCODE='22023', DETAIL=pg_catalog.jsonb_build_object(
        'code','PAY_WORKBENCH_CORRECTION_DIRTY_CONTEXT_SCOPE_INVALID',
        'candidate_count',pg_catalog.cardinality(v_candidate_ids)
      )::text;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_correction_dirty_context_v1(
    contract_version text NOT NULL,
    correction_request_id uuid NOT NULL,
    correction_operation_id uuid NULL,
    correction_work_item_id uuid NULL,
    pay_batch_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    lifecycle_phase text NOT NULL,
    policy_x_boundary text NOT NULL,
    pre_request_source_change_seq bigint NOT NULL,
    pre_request_dirty_generation bigint NOT NULL,
    pre_request_fence_digest text NULL,
    context_digest text NOT NULL,
    created_at_utc timestamptz NOT NULL,
    PRIMARY KEY(candidate_id)
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_wb_correction_dirty_context_v1 AS context_row(
    contract_version,correction_request_id,correction_operation_id,
    correction_work_item_id,pay_batch_id,candidate_id,lifecycle_phase,
    policy_x_boundary,pre_request_source_change_seq,
    pre_request_dirty_generation,pre_request_fence_digest,context_digest,
    created_at_utc
  )
  SELECT
    'CORRECTION_OWNED_DIRTY_CAUSAL_V1',
    p_correction_request_id,
    p_operation_id,
    p_work_item_id,
    p_pay_batch_id,
    candidate_scope.candidate_id,
    v_phase,
    v_boundary,
    COALESCE(
      CASE WHEN COALESCE(
        p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'source_change_seq',''
      ) ~ '^[0-9]{1,18}$' THEN (
        p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'source_change_seq'
      )::bigint END,
      change_counter.seq,
      0
    ),
    COALESCE(
      CASE WHEN COALESCE(
        p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'dirty_generation',''
      ) ~ '^[0-9]{1,18}$' THEN (
        p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'dirty_generation'
      )::bigint END,
      change_counter.scope_change_generation,
      0
    ),
    NULLIF(
      p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'fence_digest',''
    ),
    pg_catalog.encode(extensions.digest(
      pg_catalog.convert_to(
        'CORRECTION_OWNED_DIRTY_CAUSAL_V1'||'|'||
        p_correction_request_id::text||'|'||COALESCE(p_operation_id::text,'')||'|'||
        COALESCE(p_work_item_id::text,'')||'|'||p_pay_batch_id::text||'|'||
        candidate_scope.candidate_id::text||'|'||v_phase||'|'||v_boundary||'|'||
        COALESCE(
          CASE WHEN COALESCE(
            p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'source_change_seq',''
          ) ~ '^[0-9]{1,18}$' THEN (
            p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'source_change_seq'
          )::bigint END,
          change_counter.seq,
          0
        )::text||'|'||
        COALESCE(
          CASE WHEN COALESCE(
            p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'dirty_generation',''
          ) ~ '^[0-9]{1,18}$' THEN (
            p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'dirty_generation'
          )::bigint END,
          change_counter.scope_change_generation,
          0
        )::text||'|'||
        COALESCE(
          p_pre_request_authorities_json->candidate_scope.candidate_id::text->>'fence_digest',''
        ),
        'UTF8'
      ),
      'sha256'
    ),'hex'),
    pg_catalog.clock_timestamp()
  FROM pg_catalog.unnest(v_candidate_ids) AS candidate_scope(candidate_id)
  LEFT JOIN public.app_change_counters AS change_counter
    ON change_counter.entity_key='pay_candidate:'||candidate_scope.candidate_id::text
  ON CONFLICT(candidate_id) DO UPDATE
  SET contract_version=EXCLUDED.contract_version,
      correction_request_id=EXCLUDED.correction_request_id,
      correction_operation_id=EXCLUDED.correction_operation_id,
      correction_work_item_id=EXCLUDED.correction_work_item_id,
      pay_batch_id=EXCLUDED.pay_batch_id,
      lifecycle_phase=EXCLUDED.lifecycle_phase,
      policy_x_boundary=EXCLUDED.policy_x_boundary,
      pre_request_source_change_seq=EXCLUDED.pre_request_source_change_seq,
      pre_request_dirty_generation=EXCLUDED.pre_request_dirty_generation,
      pre_request_fence_digest=EXCLUDED.pre_request_fence_digest,
      context_digest=EXCLUDED.context_digest,
      created_at_utc=EXCLUDED.created_at_utc;

  GET DIAGNOSTICS v_context_count=ROW_COUNT;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'contract_version','CORRECTION_OWNED_DIRTY_CAUSAL_V1',
    'correction_request_id',p_correction_request_id,
    'operation_id',p_operation_id,
    'pay_batch_id',p_pay_batch_id,
    'lifecycle_phase',v_phase,
    'policy_x_boundary',v_boundary,
    'candidate_count',v_context_count,
    'transaction_local',true
  );
END;
$function$;

-- private.pay_workbench_correction_held_dirty_job_resolve_v1(uuid,uuid,uuid,jsonb,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_correction_held_dirty_job_resolve_v1(p_correction_request_id uuid, p_operation_id uuid, p_session_id uuid, p_route_results_json jsonb, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_candidate record;
  v_job public.banking_pay_workbench_jobs%rowtype;
  v_completion jsonb := '{}'::jsonb;
  v_results jsonb := '[]'::jsonb;
  v_resolved_count integer := 0;
  v_current_count integer := 0;
  v_active_owner_count integer := 0;
  v_physical_currentness jsonb := '{}'::jsonb;
  v_candidate_currentness jsonb := '{}'::jsonb;
  v_post_commit_authority jsonb := '{}'::jsonb;
BEGIN
  IF p_correction_request_id IS NULL OR p_operation_id IS NULL OR p_session_id IS NULL
     OR pg_catalog.jsonb_typeof(COALESCE(p_route_results_json,'{}'::jsonb))<>'object'
     OR pg_catalog.jsonb_typeof(COALESCE(p_route_results_json->'candidate_ids','[]'::jsonb))<>'array'
     OR pg_catalog.jsonb_array_length(COALESCE(p_route_results_json->'candidate_ids','[]'::jsonb))>100
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object'
     OR EXISTS (
       SELECT 1 FROM pg_catalog.jsonb_object_keys(COALESCE(p_options_json,'{}'::jsonb)) AS k(key)
       WHERE k.key NOT IN ('owner')
     ) THEN
    RAISE EXCEPTION 'CORRECTION_HELD_DIRTY_RESOLVE_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','CORRECTION_HELD_DIRTY_RESOLVE_ARGUMENT_INVALID'
      )::text;
  END IF;

  FOR v_candidate IN
    SELECT candidate_value.value::uuid AS candidate_id,
      CASE
        WHEN COALESCE(operation_row.input_json->'cancellation_reversion_start_authorities_v2'
          ->candidate_value.value->>'request_owned_dirty_job_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (operation_row.input_json->'cancellation_reversion_start_authorities_v2'
            ->candidate_value.value->>'request_owned_dirty_job_id')::uuid
        WHEN COALESCE(operation_row.input_json->'draft_overlay_fast_start_authorities'
          ->candidate_value.value->>'request_owned_dirty_job_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (operation_row.input_json->'draft_overlay_fast_start_authorities'
            ->candidate_value.value->>'request_owned_dirty_job_id')::uuid
        ELSE NULL::uuid
      END AS held_job_id
    FROM pg_catalog.jsonb_array_elements_text(p_route_results_json->'candidate_ids')
      AS candidate_value(value)
    JOIN public.banking_pay_operations AS operation_row
      ON operation_row.id=p_operation_id
     AND operation_row.operation_type='PAYMENT_CORRECTION'
     AND operation_row.input_json->>'correction_request_id'=p_correction_request_id::text
    WHERE candidate_value.value
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ORDER BY candidate_value.value::uuid
  LOOP
    IF v_candidate.held_job_id IS NULL THEN
      v_results:=v_results||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'candidate_id',v_candidate.candidate_id,'status','NOT_REQUIRED_NO_HELD_JOB'
      ));
      CONTINUE;
    END IF;

    SELECT job_row.* INTO v_job
    FROM public.banking_pay_workbench_jobs AS job_row
    WHERE job_row.id=v_candidate.held_job_id
      AND job_row.candidate_id=v_candidate.candidate_id
      AND job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CORRECTION_HELD_DIRTY_JOB_MISSING'
        USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
          'code','CORRECTION_HELD_DIRTY_JOB_MISSING','candidate_id',v_candidate.candidate_id
        )::text;
    END IF;

    v_post_commit_authority:=COALESCE(
      p_route_results_json->'post_commit_authorities_v3'->v_candidate.candidate_id::text,
      '{}'::jsonb
    );
    IF COALESCE(v_post_commit_authority->>'contract_version','')
         <>'POST_FINANCIAL_TERMINAL_AUTHORITY_V3'
       OR COALESCE((v_post_commit_authority->>'admitted')::boolean,false) IS NOT TRUE
       OR COALESCE(v_post_commit_authority->>'correction_request_id','')
            IS DISTINCT FROM p_correction_request_id::text
       OR COALESCE(v_post_commit_authority->>'operation_id','')
            IS DISTINCT FROM p_operation_id::text
       OR COALESCE(v_post_commit_authority->>'session_id','')
            IS DISTINCT FROM p_session_id::text
       OR COALESCE(v_post_commit_authority->>'candidate_id','')
            IS DISTINCT FROM v_candidate.candidate_id::text
       OR COALESCE(v_post_commit_authority->>'held_dirty_job_id','')
            IS DISTINCT FROM v_job.id::text
       OR COALESCE(v_post_commit_authority->>'dirty_generation','')
            IS DISTINCT FROM COALESCE(v_job.scope_change_generation,0)::text THEN
      RAISE EXCEPTION 'CORRECTION_HELD_DIRTY_POST_COMMIT_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
          'code','CORRECTION_HELD_DIRTY_POST_COMMIT_AUTHORITY_MISMATCH',
          'candidate_id',v_candidate.candidate_id
        )::text;
    END IF;

    IF COALESCE(v_job.payload_json->>'correction_dirty_causal_contract_version','')
         <>'CORRECTION_OWNED_DIRTY_CAUSAL_V1'
       OR COALESCE(v_job.payload_json->'correction_dirty_contexts'
            ->v_candidate.candidate_id::text->>'correction_request_id','')
            IS DISTINCT FROM p_correction_request_id::text THEN
      RAISE EXCEPTION 'CORRECTION_HELD_DIRTY_CAUSAL_MISMATCH'
        USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
          'code','CORRECTION_HELD_DIRTY_CAUSAL_MISMATCH','candidate_id',v_candidate.candidate_id
        )::text;
    END IF;

    SELECT pg_catalog.count(*) FILTER (
             WHERE scope_row.pending_job_id IS NULL
               AND scope_row.dirty IS NOT TRUE
               AND pg_catalog.upper(COALESCE(scope_row.status,'')) IN ('MATERIALISED','READY','COMPLETE')
               AND candidate_state.pending_job_id IS NULL
               AND pg_catalog.upper(COALESCE(candidate_state.status,'')) IN ('READY','COMPLETE')
           )::integer,
           pg_catalog.count(*) FILTER (
             WHERE owner_job.id IS NOT NULL AND owner_job.status IN ('QUEUED','RUNNING')
           )::integer
    INTO v_current_count,v_active_owner_count
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
      ON candidate_state.session_id=scope_row.session_id
     AND candidate_state.candidate_id=scope_row.candidate_id
    LEFT JOIN public.banking_pay_workbench_jobs AS owner_job
      ON owner_job.id=scope_row.pending_job_id
     AND owner_job.candidate_id=scope_row.candidate_id
     AND owner_job.session_id=scope_row.session_id
     AND pg_catalog.upper(COALESCE(owner_job.job_type,'')) IN (
       'WORKBENCH_CANDIDATE_SOURCE_BUILD','WORKBENCH_CANDIDATE_DELTA_REFRESH'
     )
    WHERE scope_row.session_id=p_session_id
      AND scope_row.candidate_id=v_candidate.candidate_id;

    EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
      INTO v_physical_currentness
      USING p_session_id,ARRAY[v_candidate.candidate_id],'TERMINAL_CURRENT',
        pg_catalog.jsonb_build_object('contract_version',1,'allow_active_owner',true);
    v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
    v_current_count:=CASE
      WHEN COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN 1 ELSE 0 END;
    v_active_owner_count:=CASE
      WHEN COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) IS NOT TRUE
       AND COALESCE((v_candidate_currentness->>'current_or_active_owner')::boolean,false)
      THEN 1 ELSE 0 END;

    IF COALESCE(v_current_count,0)<>1 AND COALESCE(v_active_owner_count,0)<>1 THEN
      RAISE EXCEPTION 'CORRECTION_HELD_DIRTY_ROUTE_NOT_ELECTED'
        USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
          'code','CORRECTION_HELD_DIRTY_ROUTE_NOT_ELECTED','candidate_id',v_candidate.candidate_id,
          'current_count',v_current_count,'active_owner_count',v_active_owner_count
        )::text;
    END IF;

    -- The generic completion authority is intentionally idempotent.  A lost
    -- route-election response can therefore replay this call even when the
    -- held job is already SUCCEEDED; the owner reads its durable completion
    -- from payload_json and returns duplicate_completion=true.  Do not read a
    -- separate result column from the job row: no such column exists.
    v_completion:=public.pay_workbench_complete_job(
      v_job.id,
      pg_catalog.jsonb_build_object(
        'ok',true,'status','COALESCED_TO_CORRECTION_ROUTE_ELECTION',
        'correction_request_id',p_correction_request_id,'operation_id',p_operation_id,
        'candidate_id',v_candidate.candidate_id,
        'coalesced_to_current_refresh_authority',true,
        'coalesced_owner_resolution',CASE WHEN v_current_count=1
          THEN 'COMPLETE_CURRENT_AUTHORITY' ELSE 'ACTIVE_CURRENT_OWNER' END,
        'actual_refresh_scope_status',CASE WHEN v_current_count=1
          THEN 'MATERIALISED' ELSE 'STAGED' END
      )
    );

    v_resolved_count:=v_resolved_count+1;
    v_results:=v_results||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'candidate_id',v_candidate.candidate_id,'held_job_id',v_job.id,
      'status','COALESCED','current_authority',v_current_count=1,
      'active_owner',v_active_owner_count=1,'completion',v_completion
    ));
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','CORRECTION_HELD_DIRTY_ROUTE_RESOLUTION_V1',
    'correction_request_id',p_correction_request_id,'operation_id',p_operation_id,
    'resolved_count',v_resolved_count,'candidate_results',v_results
  );
END;
$function$;

-- private.pay_workbench_correction_post_commit_authority_page_v1(uuid,uuid,uuid,uuid[],jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_correction_post_commit_authority_page_v1(p_correction_request_id uuid, p_operation_id uuid, p_session_id uuid, p_work_item_ids uuid[], p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_candidate record;
  v_authorities jsonb := '{}'::jsonb;
  v_candidate_count integer := 0;
  v_finalized_count integer := 0;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  IF p_correction_request_id IS NULL OR p_operation_id IS NULL OR p_session_id IS NULL
     OR p_work_item_ids IS NULL OR pg_catalog.cardinality(p_work_item_ids)<1
     OR pg_catalog.cardinality(p_work_item_ids)>100
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object'
     OR EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(COALESCE(p_options_json,'{}'::jsonb)) AS k(key)
                WHERE k.key NOT IN ('owner')) THEN
    RAISE EXCEPTION 'CORRECTION_POST_COMMIT_AUTHORITY_ARGUMENT_INVALID' USING ERRCODE='P0001';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.banking_pay_operations AS operation_row
    JOIN public.pay_payment_correction_requests AS request_row
      ON request_row.id=p_correction_request_id AND request_row.pay_batch_id=operation_row.pay_batch_id
    WHERE operation_row.id=p_operation_id AND operation_row.operation_type='PAYMENT_CORRECTION'
      AND operation_row.input_json->>'correction_request_id'=p_correction_request_id::text
  ) THEN
    RAISE EXCEPTION 'CORRECTION_POST_COMMIT_OPERATION_MISMATCH' USING ERRCODE='P0001';
  END IF;

  FOR v_candidate IN
    SELECT DISTINCT work_row.candidate_id
    FROM pg_catalog.unnest(p_work_item_ids) AS requested(work_item_id)
    JOIN public.pay_payment_correction_work_items AS work_row ON work_row.id=requested.work_item_id
    WHERE work_row.correction_request_id=p_correction_request_id AND work_row.status='APPLIED'
      AND work_row.candidate_id IS NOT NULL ORDER BY work_row.candidate_id
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_candidate.candidate_id),24062027));
  END LOOP;

  -- Candidate serialization is acquired first; now lock the exact held jobs in
  -- deterministic UUID order so the post-commit fence and later coalescing
  -- cannot race the ordinary dirty-job runner.
  PERFORM 1
  FROM public.banking_pay_workbench_jobs AS held_job
  JOIN public.banking_pay_operations AS operation_row ON operation_row.id=p_operation_id
  JOIN public.pay_payment_correction_work_items AS work_row
    ON work_row.id=ANY(p_work_item_ids)
   AND work_row.correction_request_id=p_correction_request_id
   AND work_row.status='APPLIED'
   AND work_row.candidate_id=held_job.candidate_id
  WHERE held_job.id=CASE
    WHEN COALESCE(COALESCE(
      work_row.selection_json->'cancellation_reversion_start_authority_v2',
      operation_row.input_json->'cancellation_reversion_start_authorities_v2'
        ->work_row.candidate_id::text)->>'request_owned_dirty_job_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN (COALESCE(
      work_row.selection_json->'cancellation_reversion_start_authority_v2',
      operation_row.input_json->'cancellation_reversion_start_authorities_v2'
        ->work_row.candidate_id::text)->>'request_owned_dirty_job_id')::uuid END
  ORDER BY held_job.id
  FOR UPDATE OF held_job;

  WITH requested_work AS (
    SELECT DISTINCT ON (work_row.candidate_id)
      work_row.id AS work_item_id,work_row.candidate_id,work_row.result_json,
      COALESCE(
        work_row.selection_json->'cancellation_reversion_start_authority_v2',
        operation_row.input_json->'cancellation_reversion_start_authorities_v2'
          ->work_row.candidate_id::text
      ) AS start_authority,
      operation_row.input_json->'cancellation_reversion_post_financial_terminal_awaiting_commit_v3'
        ->work_row.candidate_id::text AS awaiting_authority
    FROM pg_catalog.unnest(p_work_item_ids) AS requested(work_item_id)
    JOIN public.pay_payment_correction_work_items AS work_row ON work_row.id=requested.work_item_id
    JOIN public.banking_pay_operations AS operation_row ON operation_row.id=p_operation_id
    WHERE work_row.correction_request_id=p_correction_request_id AND work_row.status='APPLIED'
      AND work_row.candidate_id IS NOT NULL ORDER BY work_row.candidate_id,work_row.id
  ), resolved AS (
    SELECT requested_work.*,held_job.id AS held_job_id,held_job.status AS held_job_status,
      held_job.scope_change_generation AS held_job_generation,held_job.payload_json AS held_payload,
      CASE WHEN COALESCE(held_job.payload_json->>'request_owned_scope_change_tx_token','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (held_job.payload_json->>'request_owned_scope_change_tx_token')::uuid END AS tx_token,
      scope_tx.state AS tx_state,scope_tx.allocated_generation,scope_tx.finalized_at_utc,
      COALESCE(change_counter.seq,0) AS source_change_seq,
      COALESCE(change_counter.scope_change_generation,0) AS counter_generation,
      registry.current_source_change_seq AS registry_source_change_seq,
      registry.dirty_generation AS registry_generation,
      pg_catalog.md5((COALESCE(requested_work.result_json,'{}'::jsonb)
        -'applied_at_utc'-'processed_at_utc')::text) AS financial_result_digest
    FROM requested_work
    LEFT JOIN public.banking_pay_workbench_jobs AS held_job
      ON held_job.id=CASE WHEN COALESCE(requested_work.start_authority->>'request_owned_dirty_job_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (requested_work.start_authority->>'request_owned_dirty_job_id')::uuid END
     AND held_job.candidate_id=requested_work.candidate_id
     AND held_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
    LEFT JOIN public.banking_pay_scope_change_transactions AS scope_tx
      ON scope_tx.tx_token=CASE WHEN COALESCE(held_job.payload_json->>'request_owned_scope_change_tx_token','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (held_job.payload_json->>'request_owned_scope_change_tx_token')::uuid END
    LEFT JOIN public.app_change_counters AS change_counter
      ON change_counter.entity_key='pay_candidate:'||requested_work.candidate_id::text
    LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
      ON registry.candidate_id=requested_work.candidate_id
  ), scope_proof AS (
    SELECT resolved.*,COALESCE(timesheet_proof.required_count,0) AS required_timesheet_count,
      COALESCE(timesheet_proof.exact_count,0) AS exact_timesheet_count
    FROM resolved LEFT JOIN LATERAL (
      WITH required_timesheets AS (
        SELECT DISTINCT value::uuid AS timesheet_id
        FROM pg_catalog.jsonb_array_elements_text(CASE
          WHEN pg_catalog.jsonb_typeof(resolved.held_payload->'targeted_timesheet_ids')='array'
            THEN resolved.held_payload->'targeted_timesheet_ids'
          WHEN pg_catalog.jsonb_typeof(resolved.held_payload->'affected_timesheet_ids')='array'
            THEN resolved.held_payload->'affected_timesheet_ids' ELSE '[]'::jsonb END) AS target(value)
        WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      SELECT pg_catalog.count(*)::integer AS required_count,
        pg_catalog.count(*) FILTER (WHERE state_row.candidate_id=resolved.candidate_id
          AND state_row.dirty_generation=resolved.allocated_generation)::integer AS exact_count
      FROM required_timesheets LEFT JOIN private.banking_pay_workbench_timesheet_scope_state AS state_row
        ON state_row.timesheet_id=required_timesheets.timesheet_id
       AND state_row.candidate_id=resolved.candidate_id
    ) AS timesheet_proof ON true
  ), classified AS (
    SELECT scope_proof.*,CASE
      WHEN COALESCE(start_authority->>'contract_version','')<>'CANCELLATION_REVERSION_START_AUTHORITY_V2'
        THEN 'START_AUTHORITY_MISSING'
      WHEN held_job_id IS NULL THEN 'HELD_DIRTY_JOB_MISSING'
      WHEN held_job_status IN ('FAILED','CANCELLED') THEN 'HELD_DIRTY_JOB_TERMINAL_FAILURE'
      WHEN COALESCE(held_payload->>'correction_dirty_causal_contract_version','')
        <>'CORRECTION_OWNED_DIRTY_CAUSAL_V1' THEN 'HELD_DIRTY_CAUSAL_MISMATCH'
      WHEN tx_token IS NULL OR tx_state<>'FINALIZED' OR allocated_generation IS NULL
        THEN 'SCOPE_GENERATION_NOT_FINALIZED'
      WHEN held_job_generation IS DISTINCT FROM allocated_generation
        OR COALESCE(held_payload->>'scope_change_generation','') IS DISTINCT FROM allocated_generation::text
        THEN 'HELD_JOB_GENERATION_MISMATCH'
      WHEN counter_generation IS DISTINCT FROM allocated_generation OR registry_generation IS DISTINCT FROM allocated_generation
        THEN 'POST_COMMIT_GENERATION_MISMATCH'
      WHEN registry_source_change_seq IS DISTINCT FROM source_change_seq
        OR COALESCE(held_payload->>'source_change_seq','') IS DISTINCT FROM source_change_seq::text
        THEN 'POST_COMMIT_SEQUENCE_MISMATCH'
      WHEN required_timesheet_count<>exact_timesheet_count THEN 'POST_COMMIT_TIMESHEET_SCOPE_MISMATCH'
      WHEN COALESCE(awaiting_authority->>'contract_version','')<>'POST_FINANCIAL_TERMINAL_AWAITING_COMMIT_V3'
        OR COALESCE(awaiting_authority->>'financial_result_digest','') IS DISTINCT FROM financial_result_digest
        THEN 'FINANCIAL_RESULT_AUTHORITY_MISMATCH'
      ELSE NULL END AS rejection_reason
    FROM scope_proof
  ), authority_rows AS (
    SELECT classified.*,pg_catalog.md5(
      p_correction_request_id::text||'|'||p_operation_id::text||'|'||p_session_id::text||'|'||work_item_id::text||'|'||
      candidate_id::text||'|'||tx_token::text||'|'||allocated_generation::text||'|'||
      source_change_seq::text||'|'||COALESCE(start_authority->>'fence_digest','')||'|'||
      financial_result_digest||'|POST_FINANCIAL_TERMINAL_AUTHORITY_V3') AS authority_digest
    FROM classified
  )
  SELECT COALESCE(pg_catalog.jsonb_object_agg(candidate_id::text,
    pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'contract_version','POST_FINANCIAL_TERMINAL_AUTHORITY_V3',
      'correction_request_id',p_correction_request_id,'operation_id',p_operation_id,
      'session_id',p_session_id,
      'work_item_id',work_item_id,'candidate_id',candidate_id,'held_dirty_job_id',held_job_id,
      'scope_change_tx_token',tx_token,'scope_change_tx_state',tx_state,
      'dirty_generation',allocated_generation,'source_change_seq',source_change_seq,
      'start_authority_digest',start_authority->>'fence_digest',
      'financial_result_digest',financial_result_digest,
      'required_timesheet_count',required_timesheet_count,'exact_timesheet_count',exact_timesheet_count,
      'authority_digest',authority_digest,'admitted',rejection_reason IS NULL,
      'rejection_reason',rejection_reason,'captured_at_utc',v_now
    )) ORDER BY candidate_id),'{}'::jsonb),pg_catalog.count(*)::integer,
    pg_catalog.count(*) FILTER (WHERE rejection_reason IS NULL)::integer
  INTO v_authorities,v_candidate_count,v_finalized_count FROM authority_rows;

  UPDATE public.banking_pay_operations AS operation_row
  SET input_json=COALESCE(operation_row.input_json,'{}'::jsonb)||pg_catalog.jsonb_build_object(
        'cancellation_reversion_post_commit_authorities_v3',v_authorities),
      progress_json=COALESCE(operation_row.progress_json,'{}'::jsonb)||pg_catalog.jsonb_build_object(
        'post_commit_authority_v3_candidate_count',v_candidate_count,
        'post_commit_authority_v3_finalized_count',v_finalized_count),updated_at_utc=v_now
  WHERE operation_row.id=p_operation_id;

  RETURN pg_catalog.jsonb_build_object('ok',true,
    'contract_version','CORRECTION_POST_COMMIT_AUTHORITY_PAGE_V1',
    'candidate_count',v_candidate_count,'finalized_count',v_finalized_count,
    'all_finalized',v_candidate_count>0 AND v_finalized_count=v_candidate_count,
    'candidate_authorities',v_authorities);
END;
$function$;

-- private.pay_workbench_current_entitlement_components_cached_v1(uuid[])
CREATE OR REPLACE FUNCTION private.pay_workbench_current_entitlement_components_cached_v1(p_timesheet_ids uuid[])
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, truth_ex_vat numeric, baseline_ex_vat numeric, truth_inc_vat numeric, baseline_inc_vat numeric)
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_sync_token_text text := NULL::text;
  v_sync_token uuid := NULL::uuid;
  v_cache_key text := NULL::text;
  v_cache_enabled boolean := false;
BEGIN
  SELECT COALESCE(
    ARRAY_AGG(DISTINCT input_id ORDER BY input_id),
    ARRAY[]::uuid[]
  )
  INTO v_timesheet_ids
  FROM UNNEST(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_rows(input_id)
  WHERE input_id IS NOT NULL;

  v_sync_token_text := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  IF COALESCE(
       current_setting('cloudtms.pay_workbench_execution_profile_version', true),
       ''
     ) = '2'
     AND v_sync_token_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_sync_token := v_sync_token_text::uuid;

    SELECT EXISTS (
      SELECT 1
      FROM private.banking_pay_workbench_economic_builds AS build_row
      WHERE build_row.build_token = v_sync_token
        AND build_row.status = 'RECONCILING'
    )
    INTO v_cache_enabled;
  END IF;

  IF NOT COALESCE(v_cache_enabled, false) THEN
    RETURN QUERY
    SELECT component_row.*
    FROM public._pay_current_timesheet_entitlement_components(
      v_timesheet_ids
    ) AS component_row;
    RETURN;
  END IF;

  v_cache_key := md5(array_to_string(v_timesheet_ids, ','));

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp._bpay_wb_live_entitlement_cache_v2 (
    sync_token uuid NOT NULL,
    cache_key text NOT NULL,
    input_timesheet_ids uuid[] NOT NULL,
    timesheet_id uuid NOT NULL,
    key_type text NOT NULL,
    key_value text NOT NULL,
    truth_ex_vat numeric NOT NULL,
    baseline_ex_vat numeric NOT NULL,
    truth_inc_vat numeric NOT NULL,
    baseline_inc_vat numeric NOT NULL,
    PRIMARY KEY(sync_token, cache_key, timesheet_id, key_type, key_value)
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp._bpay_wb_live_entitlement_cache_keys_v2 (
    sync_token uuid NOT NULL,
    cache_key text NOT NULL,
    input_timesheet_ids uuid[] NOT NULL,
    PRIMARY KEY(sync_token, cache_key)
  ) ON COMMIT DROP;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_temp._bpay_wb_live_entitlement_cache_keys_v2 AS cache_key_row
    WHERE cache_key_row.sync_token = v_sync_token
      AND cache_key_row.cache_key = v_cache_key
      AND cache_key_row.input_timesheet_ids = v_timesheet_ids
  ) THEN
    INSERT INTO pg_temp._bpay_wb_live_entitlement_cache_v2(
      sync_token,
      cache_key,
      input_timesheet_ids,
      timesheet_id,
      key_type,
      key_value,
      truth_ex_vat,
      baseline_ex_vat,
      truth_inc_vat,
      baseline_inc_vat
    )
    SELECT
      v_sync_token,
      v_cache_key,
      v_timesheet_ids,
      component_row.timesheet_id,
      component_row.key_type,
      component_row.key_value,
      component_row.truth_ex_vat,
      component_row.baseline_ex_vat,
      component_row.truth_inc_vat,
      component_row.baseline_inc_vat
    FROM public._pay_current_timesheet_entitlement_components(
      v_timesheet_ids
    ) AS component_row;

    INSERT INTO pg_temp._bpay_wb_live_entitlement_cache_keys_v2(
      sync_token,
      cache_key,
      input_timesheet_ids
    )
    VALUES (
      v_sync_token,
      v_cache_key,
      v_timesheet_ids
    );
  END IF;

  RETURN QUERY
  SELECT
    cached_component.timesheet_id,
    cached_component.key_type,
    cached_component.key_value,
    cached_component.truth_ex_vat,
    cached_component.baseline_ex_vat,
    cached_component.truth_inc_vat,
    cached_component.baseline_inc_vat
  FROM pg_temp._bpay_wb_live_entitlement_cache_v2 AS cached_component
  WHERE cached_component.sync_token = v_sync_token
    AND cached_component.cache_key = v_cache_key
    AND cached_component.input_timesheet_ids = v_timesheet_ids
  ORDER BY
    cached_component.timesheet_id,
    cached_component.key_type,
    cached_component.key_value;
END;
$function$;

-- private.pay_workbench_draft_create_adoption_finalize_v1(uuid,uuid,uuid,uuid[],jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_draft_create_adoption_finalize_v1(p_operation_id uuid, p_pay_batch_id uuid, p_session_id uuid, p_candidate_ids uuid[], p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_enabled boolean:=false;
  v_candidate_ids uuid[]:=ARRAY[]::uuid[];
  v_candidate_count integer:=0;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_invalid_scope_count integer:=0;
  v_active_owner_count integer:=0;
  v_invalid_attestation_count integer:=0;
  v_missing_phase_count integer:=0;
  v_unlinked_allocation_count integer:=0;
  v_semantic_proof jsonb:='{}'::jsonb;
BEGIN
  IF p_operation_id IS NULL OR p_pay_batch_id IS NULL OR p_session_id IS NULL
     OR p_options_json IS NULL OR pg_catalog.jsonb_typeof(p_options_json)<>'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_ARGUMENT_INVALID' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(settings_row.banking_pay_draft_create_adoption_v1_enabled,false)
  INTO v_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  SELECT COALESCE(pg_catalog.array_agg(candidate.candidate_id ORDER BY candidate.candidate_id),ARRAY[]::uuid[]),
         pg_catalog.count(*)::integer
  INTO v_candidate_ids,v_candidate_count
  FROM (
    SELECT DISTINCT candidate_id
    FROM pg_catalog.unnest(COALESCE(p_candidate_ids,ARRAY[]::uuid[])) AS candidate_id
    WHERE candidate_id IS NOT NULL
  ) AS candidate;

  IF v_candidate_count<1 OR v_candidate_count>100 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_CANDIDATE_LIMIT' USING ERRCODE='22023';
  END IF;

  IF COALESCE(v_enabled,false) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'enabled',false,'adopted',false,'candidate_count',v_candidate_count
    );
  END IF;

  SELECT operation_row.* INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id=p_operation_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.operation_type,'')))<>'DRAFT_CREATE'
     OR v_operation.workbench_session_id IS DISTINCT FROM p_session_id
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.phase,'')))<>'POST_CREATE_REFRESH'
     OR NOT (
       pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.status,''))) IN
         ('QUEUED','RUNNING','PROCESSING','CLAIMED','IN_PROGRESS')
       OR (
         pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.status,'')))='WAITING'
         AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.runner_state,'')))='RUNNABLE'
       )
     )
     OR p_pay_batch_id IS NULL
     OR NOT EXISTS(
       SELECT 1
       FROM public.banking_pay_operation_candidate_scope AS operation_batch_scope
       WHERE operation_batch_scope.operation_id=p_operation_id
         AND operation_batch_scope.pay_batch_id=p_pay_batch_id
         AND operation_batch_scope.workbench_session_id=p_session_id
         AND operation_batch_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
     ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_OPERATION_INVALID' USING ERRCODE='23514';
  END IF;

  -- Candidate serial authority is always acquired in UUID order.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(public._pay_workbench_candidate_serial_key(candidate_id),24062027)
  )
  FROM pg_catalog.unnest(v_candidate_ids) AS candidate(candidate_id)
  ORDER BY candidate.candidate_id;

  SELECT pg_catalog.count(*)::integer
  INTO v_invalid_scope_count
  FROM pg_catalog.unnest(v_candidate_ids) AS candidate(candidate_id)
  WHERE NOT EXISTS(
    SELECT 1
    FROM public.banking_pay_operation_candidate_scope AS operation_scope
    WHERE operation_scope.operation_id=p_operation_id
      AND operation_scope.pay_batch_id=p_pay_batch_id
      AND operation_scope.workbench_session_id=p_session_id
      AND operation_scope.candidate_id=candidate.candidate_id
      AND operation_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
  );

  IF v_invalid_scope_count>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_SCOPE_INVALID' USING ERRCODE='23514';
  END IF;

  -- Every canonical Draft writer must have closed its transaction-local
  -- expected-effects phase with no unmatched economic transition.  A missing
  -- phase is not treated as an empty phase: adoption fails closed.
  SELECT pg_catalog.count(*)::integer
  INTO v_missing_phase_count
  FROM pg_catalog.unnest(ARRAY[
    'insert_items','apply_finance_adjustments','finalise_reservations',
    'create_timesheet_snapshots','build_item_breakdowns'
  ]::text[]) AS required_phase(phase)
  WHERE COALESCE((v_operation.progress_json->'draft_expected_effects_v1'
      ->required_phase.phase->>'completed')::boolean,false) IS NOT TRUE
     OR COALESCE((v_operation.progress_json->'draft_expected_effects_v1'
      ->required_phase.phase->>'unmatched_count')::integer,-1) <> 0
     OR NULLIF(v_operation.progress_json->'draft_expected_effects_v1'
      ->required_phase.phase->>'observed_effect_digest','') IS NULL;

  IF v_missing_phase_count>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_EXPECTED_EFFECTS_INCOMPLETE'
      USING ERRCODE='23514',DETAIL=pg_catalog.jsonb_build_object(
        'operation_id',p_operation_id,'missing_or_invalid_phase_count',v_missing_phase_count
      )::text;
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_unlinked_allocation_count
  FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
  JOIN public.banking_pay_operation_candidate_scope AS operation_scope
    ON operation_scope.id=allocation_row.candidate_scope_id
   AND operation_scope.operation_id=p_operation_id
   AND operation_scope.candidate_id=ANY(v_candidate_ids)
  WHERE allocation_row.operation_id=p_operation_id
    AND (
      pg_catalog.upper(pg_catalog.btrim(COALESCE(allocation_row.status,'')))<>'ITEM_CREATED'
      OR allocation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
      OR allocation_row.pay_batch_item_id IS NULL
      OR NOT EXISTS(
        SELECT 1
        FROM public.pay_batch_items AS item
        JOIN public.pay_batch_candidates AS batch_candidate
          ON batch_candidate.id=item.pay_batch_candidate_id
        WHERE item.id=allocation_row.pay_batch_item_id
          AND batch_candidate.pay_batch_id=p_pay_batch_id
          AND batch_candidate.candidate_id=operation_scope.candidate_id
          AND COALESCE(item.is_voided,false) IS NOT TRUE
      )
    );

  IF v_unlinked_allocation_count>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_FROZEN_ALLOCATION_INCOMPLETE'
      USING ERRCODE='23514',DETAIL=pg_catalog.jsonb_build_object(
        'operation_id',p_operation_id,'unlinked_allocation_count',v_unlinked_allocation_count
      )::text;
  END IF;

  IF EXISTS(
    SELECT 1 FROM public.pay_batch_items AS item
    JOIN public.pay_batch_candidates AS candidate ON candidate.id=item.pay_batch_candidate_id
    WHERE candidate.pay_batch_id=p_pay_batch_id
      AND candidate.candidate_id=ANY(v_candidate_ids)
      AND item.pay_bank_transfer_id IS NOT NULL
  ) OR EXISTS(
    SELECT 1 FROM public.pay_bank_transfers AS transfer
    WHERE transfer.pay_batch_id=p_pay_batch_id AND transfer.candidate_id=ANY(v_candidate_ids)
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_POST_DRAFT_AUTHORITY_PRESENT' USING ERRCODE='23514';
  END IF;

  PERFORM scope.id
  FROM public.banking_pay_workbench_session_scope AS scope
  WHERE scope.session_id=p_session_id AND scope.candidate_id=ANY(v_candidate_ids)
  ORDER BY scope.candidate_id
  FOR UPDATE;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (
           WHERE scope.pending_job_id IS NOT NULL OR scope.dirty
             OR pg_catalog.upper(pg_catalog.btrim(COALESCE(scope.status,''))) NOT IN ('MATERIALISED','READY')
         )::integer,
         pg_catalog.count(*) FILTER (
           WHERE scope.certified_preview_publication_attestation_json->>'attestation_version'
                   IS DISTINCT FROM 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
              OR scope.certified_preview_publication_attestation_json->>'contract_version' IS DISTINCT FROM '3'
              OR scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
                   IS DISTINCT FROM 'READY_TO_PAY_SEMANTIC_V2'
              OR COALESCE((scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean,false) IS NOT TRUE
              OR COALESCE((scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,false) IS NOT TRUE
         )::integer
  INTO v_candidate_count,v_active_owner_count,v_invalid_attestation_count
  FROM public.banking_pay_workbench_session_scope AS scope
  WHERE scope.session_id=p_session_id AND scope.candidate_id=ANY(v_candidate_ids);

  IF v_candidate_count<>pg_catalog.cardinality(v_candidate_ids)
     OR v_active_owner_count>0 OR v_invalid_attestation_count>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_CURRENT_AUTHORITY_NOT_PROVEN'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'scope_count',v_candidate_count,'expected_count',pg_catalog.cardinality(v_candidate_ids),
        'active_owner_count',v_active_owner_count,
        'invalid_attestation_count',v_invalid_attestation_count
      )::text;
  END IF;

  v_semantic_proof:=private.pay_workbench_semantic_ready_proof_page_v1(
    p_session_id,v_candidate_ids,'{}'::jsonb,NULL::jsonb,'OBSERVE_ONLY','{}'::jsonb
  );
  IF COALESCE((v_semantic_proof->>'semantic_ready')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_ADOPTION_SEMANTIC_PROOF_FAILED' USING ERRCODE='23514';
  END IF;

  UPDATE public.banking_pay_operations AS operation_row
  SET progress_json=COALESCE(operation_row.progress_json,'{}'::jsonb)
    || pg_catalog.jsonb_build_object(
      'draft_create_adoption_v1',pg_catalog.jsonb_build_object(
        'adopted',true,'candidate_count',pg_catalog.cardinality(v_candidate_ids),
        'semantic_ready',true,'expected_effect_phase_count',5,
        'unlinked_allocation_count',0,'completed_at_utc',pg_catalog.clock_timestamp()
      )
    ),
    updated_at_utc=pg_catalog.clock_timestamp()
  WHERE operation_row.id=p_operation_id;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'enabled',true,'adopted',true,
    'candidate_count',pg_catalog.cardinality(v_candidate_ids),
    'semantic_proof',v_semantic_proof,
    'active_owner_count',0,'expected_effect_phase_count',5,
    'unlinked_allocation_count',0,'policy_x_drift',false
  );
END;
$function$;

